function setArchivedPageRestoreInterlock(opener, enabled) {
  if (enabled) {
    const owned = new Set();
    let current = opener;
    while (current?.parentElement) {
      const parent = current.parentElement;
      for (const sibling of parent.children) {
        if (sibling === current || sibling.id === 'state-recovery-overlay') continue;
        setElementInertOwner(sibling, 'archived-page-restore', true);
        owned.add(sibling);
      }
      if (parent === document.body) break;
      current = parent;
    }
    archivedPageRestoreInertElements = [...owned];
    return;
  }
  const owned = archivedPageRestoreInertElements;
  archivedPageRestoreInertElements = [];
  owned.forEach(element => setElementInertOwner(element, 'archived-page-restore', false));
}

function setArchivedPageRestoreBusy(context, candidateOpener, busy) {
  const itemId = String(context?.itemId || '');
  const escaped = itemId ? CSS.escape(itemId) : '';
  const fallback = escaped
    ? document.querySelector(
        `.archive-row[data-archive-item-id="${escaped}"] [data-archived-page-restore="true"]`,
      )
    : null;
  const opener = candidateOpener?.isConnected ? candidateOpener : fallback;
  if (!busy) setArchivedPageRestoreInterlock(null, false);
  if (!opener) return !busy;
  if (busy) {
    try { opener.focus({ preventScroll: true }); } catch { try { opener.focus(); } catch {} }
    setArchivedPageRestoreInterlock(opener, true);
  }
  opener.setAttribute('aria-busy', String(busy));
  opener.setAttribute('aria-disabled', String(busy));
  if (!busy) opener.removeAttribute('aria-disabled');
  const row = opener.closest('.archive-row');
  row?.classList.toggle('is-archived-page-restore-pending', busy);
  if (row) {
    if (busy) row.setAttribute('aria-busy', 'true');
    else row.removeAttribute('aria-busy');
  }
  return true;
}

