function setArchivedGroupBatchRestoreBusy(context, candidateOpener, busy) {
  const fallback = document.querySelector('[data-archived-group-batch-restore="true"]');
  const opener = candidateOpener?.isConnected ? candidateOpener : fallback;
  if (!busy) setArchivedPageRestoreInterlock(null, false);
  if (!opener) return !busy;
  if (busy) {
    try { opener.focus({ preventScroll: true }); } catch { try { opener.focus(); } catch {} }
    setArchivedPageRestoreInterlock(opener, true);
  }
  opener.setAttribute('aria-busy', String(busy));
  opener.setAttribute('aria-disabled', String(busy));
  if (!busy) opener.removeAttribute('aria-disabled');
  const selection = opener.closest('.archive-selection');
  selection?.classList.toggle('is-archived-group-batch-restore-pending', busy);
  if (selection) {
    if (busy) selection.setAttribute('aria-busy', 'true');
    else selection.removeAttribute('aria-busy');
  }
  return true;
}

