function focusArchivedPageRestoreOpener(opener) {
  if (!opener?.isConnected || typeof opener.focus !== 'function') return false;
  try { opener.focus({ preventScroll: true }); } catch { try { opener.focus(); } catch { return false; } }
  return true;
}

async function commitArchivedPageRestore(context, opener = null) {
  if (!context || isArchivedPageRestorePending() || State.isRecoveryRequired?.()) return false;
  const transaction = { context, opener };
  archivedPageRestorePending = transaction;
  if (!setArchivedPageRestoreBusy(context, opener, true)) {
    archivedPageRestorePending = null;
    return false;
  }

  const target = resolveArchivedPageRestoreTarget(context);
  if (!target) {
    requestAnimationFrame(() => {
      if (archivedPageRestorePending !== transaction) return;
      archivedPageRestorePending = null;
      setArchivedPageRestoreBusy(context, opener, false);
      toast(tr('detail.changed'), { danger: true, duration: 6000 });
      focusArchivedPageRestoreOpener(opener);
    });
    return false;
  }

  try {
    let destinationGroup = target.destination.groupRef;
    let createdGroup = null;
    if (target.destination.createInbox) {
      const groupId = String(createOrganizationIdAllocator()() || '');
      if (!groupId) throw new Error('Could not allocate an Inbox identity');
      createdGroup = {
        id: groupId,
        name: 'Inbox',
        symbol: '📥',
        color: '#6366f1',
        collapsed: false,
        items: [],
      };
      destinationGroup = createdGroup;
    }
    State.snapshot(archivedPageRestoreDestinationText(context));
    target.archive.splice(target.index, 1);
    if (createdGroup) target.destination.groupsRef.unshift(createdGroup);
    destinationGroup.items.push(target.item);
  } catch (error) {
    if (archivedPageRestorePending === transaction) archivedPageRestorePending = null;
    setArchivedPageRestoreBusy(context, opener, false);
    State.requireRecovery?.();
    if (typeof showStateRecoveryRequired === 'function') showStateRecoveryRequired(error);
    return false;
  }

  try {
    await State.persistNow();
  } catch (error) {
    if (archivedPageRestorePending === transaction) archivedPageRestorePending = null;
    setArchivedPageRestoreBusy(context, opener, false);
    if (State.isRecoveryRequired?.() && typeof showStateRecoveryRequired === 'function') {
      showStateRecoveryRequired(error);
    }
    return false;
  }

  if (archivedPageRestorePending !== transaction) {
    setArchivedPageRestoreBusy(context, opener, false);
    return false;
  }
  archivedPageRestorePending = null;
  setArchivedPageRestoreBusy(context, opener, false);
  renderBoard();
  renderArchiveList();
  updateNavChrome();
  toast(archivedPageRestoreDestinationText(
    context,
    context.collectionName === 'trash' ? 'trash.restoredTo' : 'archive.restoredTo',
  ), { undo: true });
  return true;
}

async function commitTrashedPageRestore(context, opener = null) {
  if (context?.collectionName !== 'trash') return false;
  return commitArchivedPageRestore(context, opener);
}

