async function commitArchivedPageBatchRestore(context, opener = null) {
  if (!context || isArchivedPageRestorePending() || State.isRecoveryRequired?.()) return false;
  const transaction = { context, opener };
  archivedPageRestorePending = transaction;
  if (!setArchivedPageBatchRestoreBusy(context, opener, true)) {
    archivedPageRestorePending = null;
    return false;
  }

  const resolved = resolveArchivedPageBatchRestoreTargets(context);
  if (!resolved) {
    requestAnimationFrame(() => {
      if (archivedPageRestorePending !== transaction) return;
      archivedPageRestorePending = null;
      setArchivedPageBatchRestoreBusy(context, opener, false);
      toast(tr('detail.changed'), { danger: true, duration: 6000 });
      focusArchivedPageRestoreOpener(opener);
    });
    return false;
  }

  try {
    const createdInboxes = new Map();
    const needsInbox = resolved.targets.some(target => target.destination.createInbox);
    const allocateGroupId = needsInbox ? createOrganizationIdAllocator() : null;
    for (const target of resolved.targets) {
      if (!target.destination.createInbox || createdInboxes.has(target.destination.spaceRef)) continue;
      const groupId = String(allocateGroupId?.() || '');
      if (!groupId) throw new Error('Could not allocate a unique Inbox identity');
      createdInboxes.set(target.destination.spaceRef, {
        id: groupId,
        name: 'Inbox',
        symbol: '📥',
        color: '#6366f1',
        collapsed: false,
        items: [],
      });
    }

    const snapshot = context.count === 1
      ? archivedPageRestoreDestinationText(context.reviews[0])
      : tr(context.collectionName === 'trash' ? 'trash.restoreSelected' : 'archive.restoreSelected');
    State.snapshot(snapshot);
    for (const target of resolved.targets) {
      const index = resolved.archive.indexOf(target.entry);
      if (index < 0) throw new Error('Reviewed Archive entry moved during Restore');
      resolved.archive.splice(index, 1);
    }
    for (const target of resolved.targets) {
      let destinationGroup = target.destination.groupRef;
      if (target.destination.createInbox) {
        destinationGroup = createdInboxes.get(target.destination.spaceRef) || null;
        if (!destinationGroup) throw new Error('Reviewed Inbox plan is unavailable');
        if (!target.destination.groupsRef.includes(destinationGroup)) {
          target.destination.groupsRef.unshift(destinationGroup);
        }
      }
      if (!destinationGroup || !Array.isArray(destinationGroup.items)) {
        throw new Error('Reviewed Restore destination is unavailable');
      }
      destinationGroup.items.push(target.item);
    }
  } catch (error) {
    if (archivedPageRestorePending === transaction) archivedPageRestorePending = null;
    setArchivedPageBatchRestoreBusy(context, opener, false);
    State.requireRecovery?.();
    if (typeof showStateRecoveryRequired === 'function') showStateRecoveryRequired(error);
    return false;
  }

  try {
    await State.persistNow();
  } catch (error) {
    if (archivedPageRestorePending === transaction) archivedPageRestorePending = null;
    setArchivedPageBatchRestoreBusy(context, opener, false);
    if (State.isRecoveryRequired?.() && typeof showStateRecoveryRequired === 'function') {
      showStateRecoveryRequired(error);
    }
    return false;
  }

  if (archivedPageRestorePending !== transaction) {
    setArchivedPageBatchRestoreBusy(context, opener, false);
    return false;
  }
  archivedPageRestorePending = null;
  setArchivedPageBatchRestoreBusy(context, opener, false);
  renderBoard();
  renderArchiveList();
  updateNavChrome();
  toast(archivedPageBatchRestoreSuccessText(context), { undo: true });
  return true;
}

