function captureTabFields(tab) {
  const settings = State.get().settings || {};
  let fallback = tab?.url || 'Untitled';
  try { fallback = new URL(tab.url).hostname || fallback; } catch {}
  return {
    title: settings.captureIncludeTitle !== false ? (tab?.title || fallback) : fallback,
    fav: settings.captureIncludeFavicon !== false ? (tab?.favIconUrl || tab?.fav || '') : ''
  };
}

function captureDestinationTabUrls(groupOrItems) {
  const rootItems = Array.isArray(groupOrItems) ? groupOrItems : groupOrItems?.items;
  const pending = Array.isArray(rootItems) ? [...rootItems] : [];
  const seen = new Set();
  const urls = new Set();
  while (pending.length) {
    const item = pending.pop();
    if (!item || typeof item !== 'object' || seen.has(item)) continue;
    seen.add(item);
    if (item.type === 'tab' && typeof item.url === 'string' && item.url) urls.add(item.url);
    if (Array.isArray(item.items)) {
      for (const child of item.items) pending.push(child);
    }
  }
  return urls;
}

function captureDuplicateExists(groupOrItems, url) {
  return State.get().settings.captureDeduplicate !== false &&
    captureDestinationTabUrls(groupOrItems).has(url);
}

function createCaptureBatchDuplicateFilter(groupOrItems) {
  if (State.get().settings.captureDeduplicate === false) return () => true;
  const seenUrls = captureDestinationTabUrls(groupOrItems);
  return candidate => {
    const url = typeof candidate?.url === 'string' ? candidate.url : '';
    if (!url) return true;
    if (seenUrls.has(url)) return false;
    seenUrls.add(url);
    return true;
  };
}

function createInboxCaptureContext(workspace = activeWs(), space = activeCat()) {
  try {
    const workspaceId = typeof workspace?.id === 'string' ? workspace.id : '';
    const spaceId = typeof space?.id === 'string' ? space.id : '';
    if (!workspaceId.trim() || !spaceId.trim() || activeWs() !== workspace || !Array.isArray(space.groups)) return null;
    const location = identitySpaceTarget(workspaceId, spaceId);
    if (!location || location.workspace !== workspace || location.space !== space) return null;
    const inboxes = space.groups.filter(group => group?.name === 'Inbox');
    if (inboxes.length > 1) return null;
    const inbox = inboxes[0] || null;
    const inboxId = inbox && typeof inbox.id === 'string' ? inbox.id : null;
    if (inbox) {
      if (!inboxId.trim() || !Array.isArray(inbox.items)) return null;
      const exactInbox = identityGroupTarget(inboxId);
      if (!exactInbox
          || exactInbox.workspace !== workspace
          || exactInbox.space !== space
          || exactInbox.group !== inbox) return null;
    }
    return {
      workspaceId,
      spaceId,
      workspaceRef: workspace,
      spaceRef: space,
      workspaceName: String(workspace.name || ''),
      spaceName: String(space.name || ''),
      inboxId,
      inboxRef: inbox,
    };
  } catch {
    return null;
  }
}

function resolveInboxCaptureTarget(context) {
  if (!context?.workspaceId || !context?.spaceId) return null;
  try {
    if (activeWs() !== context.workspaceRef) return null;
    const location = identitySpaceTarget(context.workspaceId, context.spaceId);
    if (!location
        || location.workspace !== context.workspaceRef
        || location.space !== context.spaceRef
        || String(location.workspace.name || '') !== context.workspaceName
        || String(location.space.name || '') !== context.spaceName
        || !Array.isArray(location.space.groups)) return null;
    const inboxes = location.space.groups.filter(group => group?.name === 'Inbox');
    if (context.inboxRef) {
      if (inboxes.length !== 1
          || inboxes[0] !== context.inboxRef
          || String(inboxes[0].id || '') !== context.inboxId
          || !Array.isArray(inboxes[0].items)) return null;
      const exactInbox = identityGroupTarget(context.inboxId);
      if (!exactInbox
          || exactInbox.workspace !== location.workspace
          || exactInbox.space !== location.space
          || exactInbox.group !== context.inboxRef) return null;
      return { workspace: location.workspace, space: location.space, inbox: context.inboxRef };
    }
    if (context.inboxId !== null || inboxes.length) return null;
    return { workspace: location.workspace, space: location.space, inbox: null };
  } catch {
    return null;
  }
}

function materializeInboxCaptureTarget(context) {
  const target = resolveInboxCaptureTarget(context);
  if (!target) return null;
  if (target.inbox) return target;
  let id = '';
  try {
    id = createOrganizationIdAllocator()();
  } catch {
    return null;
  }
  if (typeof id !== 'string' || !id.trim()) return null;
  const inbox = {
    id,
    name: 'Inbox',
    symbol: '📥',
    color: '#6366f1',
    collapsed: false,
    items: [],
  };
  target.space.groups.unshift(inbox);
  return { ...target, inbox };
}

function reportInboxCaptureUnavailable() {
  toast(tr('capture.destinationUnavailable'), { danger: true, duration: 5000 });
  return false;
}

function collectItemListCaptureTargets() {
  const targets = [];
  const state = State.get();
  const workspaces = Array.isArray(state?.workspaces) ? state.workspaces : [];
  for (const workspace of workspaces) {
    const spaces = Array.isArray(workspace?.categories) ? workspace.categories : [];
    for (const space of spaces) {
      const groups = Array.isArray(space?.groups) ? space.groups : [];
      for (const group of groups) {
        const walk = (items, stacks) => {
          if (!Array.isArray(items)) return;
          targets.push({
            workspace,
            space,
            group,
            stack: stacks[stacks.length - 1] || null,
            stacks: [...stacks],
            list: items,
          });
          for (const item of items) {
            if (item?.type === 'stack' && Array.isArray(item.items)) {
              walk(item.items, [...stacks, item]);
            }
          }
        };
        walk(group?.items, []);
      }
    }
  }
  return targets;
}

function createItemListCaptureContext(list, { allowInactiveSpace = false } = {}) {
  if (!Array.isArray(list)) return null;
  const matches = collectItemListCaptureTargets().filter(target => target.list === list);
  if (matches.length !== 1) return null;
  const target = matches[0];
  if (activeWs() !== target.workspace
      || (allowInactiveSpace !== true && activeCat() !== target.space)) return null;
  const ids = [target.workspace?.id, target.space?.id, target.group?.id, ...target.stacks.map(stack => stack?.id)];
  if (ids.some(id => typeof id !== 'string' || !id.trim())) return null;
  const context = Object.freeze({
    workspaceId: target.workspace.id,
    spaceId: target.space.id,
    groupId: target.group.id,
    stackIds: Object.freeze(target.stacks.map(stack => stack.id)),
    workspaceName: String(target.workspace.name || ''),
    spaceName: String(target.space.name || ''),
    groupName: String(target.group.name || ''),
    stackNames: Object.freeze(target.stacks.map(stack => String(stack.name || ''))),
    workspaceRef: target.workspace,
    spaceRef: target.space,
    groupRef: target.group,
    stackRefs: Object.freeze([...target.stacks]),
    listRef: list,
  });
  return resolveItemListCaptureTarget(context) ? context : null;
}

function resolveItemListCaptureTarget(context) {
  if (!context?.workspaceId || !context?.spaceId || !context?.groupId
      || !Array.isArray(context.stackIds) || !Array.isArray(context.stackNames)
      || !Array.isArray(context.stackRefs) || context.stackIds.length !== context.stackNames.length
      || context.stackIds.length !== context.stackRefs.length || !Array.isArray(context.listRef)) return null;
  const matches = collectItemListCaptureTargets().filter(target => (
    target.workspace?.id === context.workspaceId
      && target.space?.id === context.spaceId
      && target.group?.id === context.groupId
      && String(target.workspace.name || '') === context.workspaceName
      && String(target.space.name || '') === context.spaceName
      && String(target.group.name || '') === context.groupName
      && target.stacks.length === context.stackIds.length
      && target.stacks.every((stack, index) => stack?.id === context.stackIds[index]
        && String(stack.name || '') === context.stackNames[index])
  ));
  if (matches.length !== 1) return null;
  const target = matches[0];
  if (target.workspace !== context.workspaceRef
      || target.space !== context.spaceRef
      || target.group !== context.groupRef
      || target.list !== context.listRef
      || target.stacks.some((stack, index) => stack !== context.stackRefs[index])) return null;
  return target;
}

function createCaptureDestinationReceiptContext(destinationContext, items) {
  const target = resolveItemListCaptureTarget(destinationContext);
  const itemRefs = Array.from(items || []);
  const itemIds = itemRefs.map(item => item?.id);
  if (!target || !itemRefs.length
      || itemIds.some(id => typeof id !== 'string' || !id.trim())
      || new Set(itemIds).size !== itemIds.length
      || itemRefs.some(item => !target.list.includes(item))) return null;
  const context = Object.freeze({
    destinationContext,
    itemIds: Object.freeze(itemIds),
    itemRefs: Object.freeze(itemRefs),
    itemFingerprints: Object.freeze(itemRefs.map(item => itemDetailValueFingerprint(item))),
  });
  return resolveCaptureDestinationReceiptTarget(context) ? context : null;
}

function resolveCaptureDestinationReceiptTarget(context) {
  const target = resolveItemListCaptureTarget(context?.destinationContext);
  if (!target || !Array.isArray(context?.itemIds) || !context.itemIds.length
      || !Array.isArray(context.itemRefs) || !Array.isArray(context.itemFingerprints)
      || context.itemIds.length !== context.itemRefs.length
      || context.itemIds.length !== context.itemFingerprints.length) return null;
  const resolved = identityItemTargets(context.itemIds);
  if (!resolved || resolved.targets.length !== context.itemIds.length) return null;
  const byId = new Map(resolved.targets.map(itemTarget => [String(itemTarget.item?.id), itemTarget]));
  for (let index = 0; index < context.itemIds.length; index += 1) {
    const itemTarget = byId.get(context.itemIds[index]);
    if (!itemTarget
        || itemTarget.item !== context.itemRefs[index]
        || itemTarget.parentItems !== target.list
        || itemTarget.workspace !== target.workspace
        || itemTarget.space !== target.space
        || itemTarget.group !== target.group
        || itemDetailValueFingerprint(itemTarget.item) !== context.itemFingerprints[index]
        || itemTarget.ancestorStackIds.length !== target.stacks.length
        || itemTarget.ancestorStackIds.some((id, stackIndex) => String(id) !== String(target.stacks[stackIndex].id))) return null;
  }
  return { ...target, items: [...context.itemRefs] };
}

function captureDestinationReceiptMessage(target, {
  item = null,
  count = 1,
  closeSources = true,
} = {}) {
  const group = target?.group;
  const stackPath = Array.isArray(target?.stacks)
    ? target.stacks
    : (target?.stack ? [target.stack] : []);
  const parts = [
    ...homeTrailPathParts(target?.workspace, target?.space, homeTrailGroupName(group)),
    ...stackPath.map(stack => String(stack?.name || '').trim()).filter(Boolean),
  ];
  if (!group || parts.length < 3) return null;
  const destination = homeTrailPathText(parts);
  if (item) {
    const title = String(item.title || item.url || tr('itemAction.untitled')).trim()
      || tr('itemAction.untitled');
    return tr(closeSources ? 'capture.receiptSaved' : 'capture.receiptSavedCopy', {
      title,
      destination,
    });
  }
  const normalizedCount = Math.trunc(Number(count));
  if (!Number.isFinite(normalizedCount) || normalizedCount < 1) return null;
  const key = closeSources
    ? (normalizedCount === 1 ? 'capture.receiptSavedTab' : 'capture.receiptSavedTabs')
    : (normalizedCount === 1 ? 'capture.receiptSavedTabCopy' : 'capture.receiptSavedTabsCopy');
  return tr(key, { count: normalizedCount, destination });
}

function inboxCaptureReceiptMessage(target, options = {}) {
  if (target?.inbox?.name !== 'Inbox') return null;
  return captureDestinationReceiptMessage({
    workspace: target.workspace,
    space: target.space,
    group: target.inbox,
  }, options);
}

function revealCaptureDestinationStackPath(stacks) {
  if (!Array.isArray(stacks)) return false;
  let revealed = 0;
  for (const stack of stacks) {
    const id = typeof stack?.id === 'string' ? stack.id : '';
    if (!id) continue;
    const value = typeof CSS !== 'undefined' && CSS.escape
      ? CSS.escape(id)
      : id;
    const matches = document.querySelectorAll(
      `.item.stack[data-id="${value}"], .lv-stack[data-id="${value}"]`,
    );
    if (!matches.length) continue;
    matches.forEach(element => element.classList.add('search-expand'));
    revealed += 1;
  }
  return revealed === stacks.length;
}

function openCaptureDestinationReceipt(context) {
  const target = resolveCaptureDestinationReceiptTarget(context);
  if (!target?.workspace?.id || !target?.group?.id) {
    toast(tr('capture.destinationReceiptUnavailable'), { danger: true, duration: 5000 });
    return false;
  }
  let navigated = false;
  try {
    navigated = Router.navigate({
      type: 'group',
      wsId: target.workspace.id,
      groupId: target.group.id,
      itemId: null,
      query: {},
    }, { persist: false });
  } catch {}
  if (!navigated) {
    toast(tr('capture.destinationReceiptUnavailable'), { danger: true, duration: 5000 });
    return false;
  }
  requestAnimationFrame(() => {
    const current = resolveCaptureDestinationReceiptTarget(context);
    if (!current) {
      toast(tr('capture.destinationReceiptUnavailable'), { danger: true, duration: 5000 });
      return;
    }
    revealCaptureDestinationStackPath(current.stacks);
    const kind = current.stack ? 'stack' : 'group';
    const id = current.stack?.id || current.group.id;
    if (!focusIdentityTarget(kind, id)) {
      const fallback = document.getElementById('board') || document.getElementById('nav-home');
      try { fallback?.focus({ preventScroll: true }); } catch { try { fallback?.focus(); } catch {} }
    }
  });
  return true;
}

function toastCaptureDestinationReceipt(context, message, result) {
  const target = resolveCaptureDestinationReceiptTarget(context);
  if (!target || !message) {
    toast(captureResultMessage(tr('capture.destinationChangedAfterSave'), result), {
      undo: result?.actionId,
      tone: 'warning',
      duration: 8000,
    });
    return false;
  }
  toast(captureResultMessage(message, result), {
    undo: result?.actionId,
    duration: 8000,
    actionLabel: tr('capture.openDestination'),
    action: () => openCaptureDestinationReceipt(context),
  });
  return true;
}

function createGeneratedGroupCaptureContext(workspace = activeWs(), space = activeCat()) {
  try {
    const workspaceId = typeof workspace?.id === 'string' ? workspace.id : '';
    const spaceId = typeof space?.id === 'string' ? space.id : '';
    if (!workspaceId.trim()
        || !spaceId.trim()
        || activeWs() !== workspace
        || activeCat() !== space
        || !Array.isArray(space.groups)) return null;
    const location = identitySpaceTarget(workspaceId, spaceId);
    if (!location || location.workspace !== workspace || location.space !== space) return null;
    return Object.freeze({
      workspaceId,
      spaceId,
      workspaceRef: workspace,
      spaceRef: space,
      groupsRef: space.groups,
      workspaceName: String(workspace.name || ''),
      spaceName: String(space.name || ''),
    });
  } catch {
    return null;
  }
}

function resolveGeneratedGroupCaptureTarget(context) {
  if (!context?.workspaceId || !context?.spaceId) return null;
  try {
    if (activeWs() !== context.workspaceRef || activeCat() !== context.spaceRef) return null;
    const location = identitySpaceTarget(context.workspaceId, context.spaceId);
    if (!location
        || location.workspace !== context.workspaceRef
        || location.space !== context.spaceRef
        || location.space.groups !== context.groupsRef
        || String(location.workspace.name || '') !== context.workspaceName
        || String(location.space.name || '') !== context.spaceName
        || !Array.isArray(location.space.groups)) return null;
    return location;
  } catch {
    return null;
  }
}

function reportGeneratedGroupCaptureUnavailable() {
  toast(tr('capture.windowDestinationUnavailable'), { danger: true, duration: 5000 });
  return false;
}

function generatedCaptureGroupName(now = new Date()) {
  const locale = appLocale();
  return tr('capture.sessionName', {
    date: now.toLocaleDateString(locale, { month: 'short', day: 'numeric' }),
    time: now.toLocaleTimeString(locale, { hour: '2-digit', minute: '2-digit' }),
  });
}

function createGroupCaptureContext(group) {
  try {
    const target = identityGroupTarget(group?.id);
    if (!target
        || target.group !== group
        || !Array.isArray(target.group.items)
        || typeof target.workspace.id !== 'string' || !target.workspace.id
        || typeof target.space.id !== 'string' || !target.space.id
        || typeof target.group.id !== 'string' || !target.group.id) return null;
    return Object.freeze({
      workspaceRef: target.workspace,
      spaceRef: target.space,
      groupRef: target.group,
      itemsRef: target.group.items,
      workspaceId: target.workspace.id,
      spaceId: target.space.id,
      groupId: target.group.id,
      workspaceName: target.workspace.name,
      spaceName: target.space.name,
      groupName: target.group.name,
    });
  } catch {
    return null;
  }
}

function resolveGroupCaptureTarget(context) {
  try {
    if (!context
        || typeof context.workspaceId !== 'string' || !context.workspaceId
        || typeof context.spaceId !== 'string' || !context.spaceId
        || typeof context.groupId !== 'string' || !context.groupId) return null;
    const target = identityGroupTarget(context.groupId);
    if (!target
        || target.workspace !== context.workspaceRef
        || target.space !== context.spaceRef
        || target.group !== context.groupRef
        || target.group.items !== context.itemsRef
        || target.workspace.id !== context.workspaceId
        || target.space.id !== context.spaceId
        || target.group.id !== context.groupId
        || target.workspace.name !== context.workspaceName
        || target.space.name !== context.spaceName
        || target.group.name !== context.groupName
        || !Array.isArray(target.group.items)) return null;
    return target;
  } catch {
    return null;
  }
}

function reportGroupCaptureUnavailable() {
  toast(tr('capture.groupDestinationUnavailable'), { danger: true, duration: 5000 });
  return false;
}

function restoreArchiveEntries(entries) {
  return restoreStoredEntries(entries, 'archive');
}

function restoreTrashEntries(entries) {
  return restoreStoredEntries(entries, 'trash');
}

function restoreStoredEntries(entries, collectionName) {
  const s = State.get();
  const collection = Array.isArray(s[collectionName]) ? s[collectionName] : [];
  const valid = (entries || []).filter(entry => collection.includes(entry));
  if (!valid.length) return;
  const fromTrash = collectionName === 'trash';
  State.snapshot(valid.length === 1 ? 'Restore' : `Restore ${collectionName} items`);
  for (const entry of valid) {
    const destination = archiveRestoreDestination(entry);
    if (!destination) continue;
    const { cat } = destination;
    collection.splice(collection.indexOf(entry), 1);
    if (entry.kind === 'item') {
      let group = cat.groups.find(g => g.id === entry.groupId)
        || cat.groups.find(g => g.name === entry.groupName);
      if (!group) {
        group = cat.groups.find(g => g.name === 'Inbox');
        if (!group) {
          group = { id: uid(), name:'Inbox', symbol:'📥', color:'#6366f1', collapsed:false, items:[] };
          cat.groups.unshift(group);
        }
      }
      group.items.push(entry.data);
    } else {
      cat.groups.push(entry.data);
    }
  }
  State.persist();
  renderBoard();
  renderArchiveList();
  updateNavChrome();
  const message = fromTrash
    ? (valid.length === 1 ? tr('trash.restored') : tr('trash.restoredMany', { count: valid.length }))
    : (valid.length === 1 ? 'Restored' : `Restored ${valid.length} archived items`);
  toast(message, { undo: true });
}

function restoreArchive(idx) {
  const entry = State.get().archive[idx];
  if (entry) restoreArchiveEntries([entry]);
}
function moveArchiveEntriesToTrash(entries) {
  const s = State.get();
  const valid = (entries || []).filter(entry => s.archive.includes(entry));
  if (!valid.length) return;
  State.snapshot(valid.length === 1 ? 'Move to Trash' : 'Move archive items to Trash');
  const now = Date.now();
  valid.forEach(entry => {
    s.archive.splice(s.archive.indexOf(entry), 1);
    s.trash.unshift({ ...entry, trashedAt: now });
  });
  State.persist();
  renderBoard();
  renderArchiveList();
  updateNavChrome();
  toast(tr('archive.movedToTrash'), { undo: true });
}

let trashDeleteEntries = [];
let trashDeleteBusy = false;

function setTrashDeleteBusy(busy) {
  const overlay = document.getElementById('trash-delete-overlay');
  const cancel = document.getElementById('trash-delete-cancel');
  const confirmButton = document.getElementById('trash-delete-confirm');
  trashDeleteBusy = !!busy;
  if (overlay) overlay.setAttribute('aria-busy', String(trashDeleteBusy));
  if (cancel) cancel.disabled = trashDeleteBusy;
  if (confirmButton) {
    confirmButton.disabled = trashDeleteBusy;
    confirmButton.textContent = tr(trashDeleteBusy ? 'trash.deleting' : 'trash.deleteForever');
  }
}

function focusTrashDeleteFallback() {
  const target = document.querySelector('.trash-shell input[type="search"], .archive-shell input[type="search"]')
    || document.getElementById('nav-trash');
  if (target && typeof target.focus === 'function') {
    try { target.focus({ preventScroll: true }); } catch { try { target.focus(); } catch {} }
  }
}

function closeTrashDeleteDialog({ restoreFocus = true } = {}) {
  const overlay = document.getElementById('trash-delete-overlay');
  if (!overlay || overlay.classList.contains('hidden') || trashDeleteBusy) return false;
  overlay.classList.add('hidden');
  unlockBodyScroll();
  trashDeleteEntries = [];
  setTrashDeleteBusy(false);
  if (restoreFocus && !restoreOpener(overlay)) setTimeout(focusTrashDeleteFallback, 0);
  else if (!restoreFocus) restoreOpener(overlay);
  return true;
}

function permanentlyDeleteTrashEntries(entries) {
  const s = State.get();
  const valid = [...new Set((entries || []).filter(entry => s.trash.includes(entry)))];
  if (!valid.length) return false;
  const overlay = document.getElementById('trash-delete-overlay');
  if (!overlay || !overlay.classList.contains('hidden')) return false;
  trashDeleteEntries = valid;
  const message = valid.length === 1
    ? tr('trash.confirmOne', { title: archiveEntryTitle(valid[0]) })
    : tr('trash.confirmMany', { count: valid.length });
  document.getElementById('trash-delete-message').textContent = message;
  rememberOpener(overlay);
  setTrashDeleteBusy(false);
  overlay.classList.remove('hidden');
  lockBodyScroll();
  setTimeout(() => document.getElementById('trash-delete-cancel')?.focus({ preventScroll: true }), 0);
  return true;
}

async function confirmTrashDelete() {
  if (trashDeleteBusy) return false;
  const s = State.get();
  const valid = trashDeleteEntries.filter(entry => s.trash.includes(entry));
  if (!valid.length) {
    closeTrashDeleteDialog();
    return false;
  }
  setTrashDeleteBusy(true);
  valid.forEach(entry => s.trash.splice(s.trash.indexOf(entry), 1));
  try {
    await State.persistNow();
  } catch {
    // persistNow routes the failure through the fail-closed recovery overlay.
    // Do not show a durable-success toast for an unconfirmed deletion.
    setTrashDeleteBusy(false);
    return false;
  }
  // A confirmed permanent deletion must not remain recoverable through an
  // older in-memory Undo or Redo snapshot.
  State.clearUndoHistory();
  renderBoard();
  renderHeader();
  updateNavChrome();
  setTrashDeleteBusy(false);
  closeTrashDeleteDialog();
  toast(tr('trash.deleted'), { danger: true });
  return true;
}

function bindTrashDeleteDialog() {
  const overlay = document.getElementById('trash-delete-overlay');
  if (!overlay) return;
  document.getElementById('trash-delete-cancel').onclick = () => closeTrashDeleteDialog();
  document.getElementById('trash-delete-confirm').onclick = confirmTrashDelete;
  overlay.addEventListener('keydown', event => {
    if (event.key === 'Escape') {
      event.preventDefault();
      event.stopPropagation();
      closeTrashDeleteDialog();
      return;
    }
    trapTabKey(event, overlay);
  });
}

let organizationNameCtx = null;
let organizationNameBusy = false;

function organizationNameTarget(kind, id) {
  const state = State.get();
  if (kind === 'workspace') {
    const matches = state.workspaces.filter(workspace => workspace.id === id);
    if (matches.length !== 1) return null;
    return { kind, id, name: matches[0].name, entity: matches[0] };
  }
  if (kind === 'space') {
    const matches = [];
    state.workspaces.forEach(workspace => {
      workspace.categories.forEach(space => {
        if (space.id === id) matches.push({ workspace, space });
      });
    });
    if (matches.length !== 1) return null;
    return {
      kind,
      id,
      name: matches[0].space.name,
      workspaceId: matches[0].workspace.id,
      entity: matches[0].space,
    };
  }
  return null;
}

function organizationWorkspaceTarget(id) {
  const matches = State.get().workspaces.filter(workspace => workspace.id === id);
  return matches.length === 1 ? matches[0] : null;
}

function organizationGroupTarget(id) {
  const matches = [];
  State.get().workspaces.forEach(workspace => {
    workspace.categories.forEach(space => {
      space.groups.forEach(group => {
        if (group.id === id) matches.push({ workspace, space, group });
      });
    });
  });
  return matches.length === 1 ? matches[0] : null;
}

function createOrganizationIdAllocator() {
  const state = State.get();
  const used = LocusImportUtils.collectEntityIds(state);
  const reserve = value => {
    if (typeof value === 'string' && value) used.add(value);
  };
  // Archive and Trash envelopes retain the last active destination IDs outside
  // their payload. Reserving those hints prevents a newly created entity from
  // silently becoming the restore destination for unrelated stored content.
  for (const collection of [state.archive || [], state.trash || []]) {
    for (const entry of collection) {
      reserve(entry?.wsId);
      reserve(entry?.catId);
      reserve(entry?.groupId);
    }
  }
  for (const key of ['columnSizes', 'columnWidths']) {
    const record = state[key];
    if (record && typeof record === 'object' && !Array.isArray(record)) {
      Object.keys(record).forEach(reserve);
    }
  }
  for (const workspace of state.workspaces || []) {
    for (const space of workspace.categories || []) {
      const positions = space?.canvasPositions;
      if (positions && typeof positions === 'object' && !Array.isArray(positions)) {
        Object.keys(positions).forEach(reserve);
      }
    }
  }
  const remembered = state.settings?.captureLastTarget;
  reserve(remembered?.workspaceId);
  reserve(remembered?.categoryId);
  reserve(remembered?.groupId);
  reserve(state.settings?.captureDefaultCategoryId);
  return () => {
    for (let attempts = 0; attempts < 10000; attempts += 1) {
      const id = String(uid());
      if (id && !used.has(id)) {
        used.add(id);
        return id;
      }
    }
    throw new Error('Could not allocate a unique organization id');
  };
}

function organizationGroupMoveOptions(source) {
  if (!source) return null;
  const workspace = organizationWorkspaceTarget(source.workspace.id);
  const parent = identitySpaceTarget(source.workspace.id, source.space.id);
  if (workspace !== source.workspace || parent?.space !== source.space) return null;

  const options = [];
  const seen = new Set();
  for (let workspaceIndex = 0; workspaceIndex < source.workspace.categories.length; workspaceIndex += 1) {
    const space = source.workspace.categories[workspaceIndex];
    const id = String(space.id);
    const exact = identitySpaceTarget(source.workspace.id, id);
    if (seen.has(id) || exact?.workspace !== source.workspace || exact?.space !== space) return null;
    seen.add(id);
    if (space === source.space) continue;
    options.push({
      id,
      name: space.name,
      groupCount: space.groups.length,
      workspaceIndex: workspaceIndex + 1,
      workspaceCount: source.workspace.categories.length,
      duplicateName: source.workspace.categories
        .filter(candidate => candidate.name === space.name).length > 1,
    });
  }
  return options;
}

function organizationMoveSpaceLabel(option) {
  if (!option?.duplicateName) return option?.name || '';
  const position = tr('organization.space.position', {
    position: option.workspaceIndex,
    count: option.workspaceCount,
  });
  return tr('organization.space.duplicateLabel', { name: option.name, position });
}

function organizationGroupMoveFingerprint(source, options) {
  return JSON.stringify({
    workspaceName: source.workspace.name,
    sourceSpaceName: source.space.name,
    groupName: source.group.name,
    destinations: options.map(option => ({
      id: option.id,
      name: option.name,
      groupCount: option.groupCount,
      workspaceIndex: option.workspaceIndex,
      workspaceCount: option.workspaceCount,
      duplicateName: option.duplicateName,
    })),
  });
}

function organizationGroupItemIds(group) {
  const ids = new Set();
  const walk = items => (items || []).forEach(item => {
    ids.add(String(item.id));
    if (item.type === 'stack') walk(item.items);
  });
  walk(group?.items);
  return ids;
}

function organizationMoveOptionButton(spaceId) {
  return [...document.querySelectorAll('#organization-move-options .organization-move-option')]
    .find(button => button.dataset.spaceId === String(spaceId));
}

function selectOrganizationMoveDestination(spaceId, { focus = false } = {}) {
  if (!organizationNameCtx
    || organizationNameCtx.operation !== 'move-group'
    || organizationNameBusy
    || organizationNameCtx.unavailable) return false;
  const option = (organizationNameCtx.moveOptions || [])
    .find(candidate => candidate.id === String(spaceId));
  if (!option) return false;
  organizationNameCtx.destinationSpaceId = option.id;
  organizationNameCtx.errorKey = null;
  const host = document.getElementById('organization-move-options');
  host?.setAttribute('aria-invalid', 'false');
  document.querySelectorAll('#organization-move-options .organization-move-option')
    .forEach(button => {
      const selected = button.dataset.spaceId === option.id;
      button.setAttribute('aria-checked', String(selected));
      button.tabIndex = selected ? 0 : -1;
    });
  const error = document.getElementById('organization-name-error');
  if (error) {
    error.hidden = true;
    error.textContent = '';
  }
  const confirm = document.getElementById('organization-name-confirm');
  if (confirm) {
    const confirmLabel = tr('organization.group.moveHistory', {
      group: organizationNameCtx.groupName,
      space: organizationMoveSpaceLabel(option),
    });
    confirm.dataset.i18n = 'organization.group.move';
    confirm.textContent = tr('organization.group.move');
    confirm.disabled = false;
    confirm.setAttribute('aria-disabled', 'false');
    confirm.setAttribute('aria-label', confirmLabel);
    confirm.title = confirmLabel;
  }
  if (focus) {
    const button = organizationMoveOptionButton(option.id);
    try { button?.focus({ preventScroll: true }); } catch { try { button?.focus(); } catch {} }
    try { button?.scrollIntoView({ block: 'nearest' }); } catch {}
  }
  return true;
}

function paintOrganizationMoveOptions() {
  const host = document.getElementById('organization-move-options');
  if (!host) return;
  const focusedId = host.contains(document.activeElement)
    ? document.activeElement?.dataset?.spaceId
    : null;
  const previousScrollTop = host.scrollTop;
  host.textContent = '';
  if (!organizationNameCtx || organizationNameCtx.operation !== 'move-group') return;

  const options = organizationNameCtx.moveOptions || [];
  const selectedId = organizationNameCtx.destinationSpaceId;
  const invalidSelection = [
    'organization.group.moveRequired',
    'organization.group.moveDestinationUnavailable',
  ].includes(organizationNameCtx.errorKey);
  host.setAttribute('aria-invalid', String(invalidSelection));
  host.setAttribute('aria-describedby', 'organization-name-error');
  options.forEach((option, index) => {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'organization-move-option';
    button.dataset.spaceId = option.id;
    button.setAttribute('role', 'radio');
    button.setAttribute('aria-checked', String(option.id === selectedId));
    const groupCount = option.groupCount === 1
      ? tr('organization.group.moveOptionOne')
      : tr('organization.group.moveOptionMany', { count: option.groupCount });
    const duplicateName = option.duplicateName;
    const position = duplicateName
      ? tr('organization.space.position', {
        position: option.workspaceIndex,
        count: option.workspaceCount,
      })
      : '';
    button.setAttribute('aria-label', tr(
      duplicateName ? 'organization.group.moveOptionDuplicate' : 'organization.group.moveOption',
      { space: option.name, groups: groupCount, position },
    ));
    button.title = option.name;
    button.tabIndex = selectedId ? (option.id === selectedId ? 0 : -1) : (index === 0 ? 0 : -1);
    button.disabled = organizationNameBusy || !!organizationNameCtx.unavailable;

    const copy = document.createElement('span');
    copy.className = 'organization-move-option-copy';
    const name = document.createElement('span');
    name.className = 'organization-move-option-name';
    name.textContent = option.name;
    const meta = document.createElement('span');
    meta.className = 'organization-move-option-meta';
    meta.textContent = duplicateName ? `${groupCount} · ${position}` : groupCount;
    copy.append(name, meta);
    const check = document.createElement('span');
    check.className = 'organization-move-option-check';
    check.setAttribute('aria-hidden', 'true');
    check.textContent = '✓';
    button.append(copy, check);

    button.addEventListener('click', () => {
      selectOrganizationMoveDestination(option.id, { focus: true });
    });
    button.addEventListener('keydown', event => {
      const keys = ['ArrowDown', 'ArrowRight', 'ArrowUp', 'ArrowLeft', 'Home', 'End', ' ', 'Enter'];
      if (!keys.includes(event.key)) return;
      event.preventDefault();
      event.stopPropagation();
      let nextIndex = index;
      if (event.key === 'ArrowDown' || event.key === 'ArrowRight') nextIndex = (index + 1) % options.length;
      else if (event.key === 'ArrowUp' || event.key === 'ArrowLeft') nextIndex = (index - 1 + options.length) % options.length;
      else if (event.key === 'Home') nextIndex = 0;
      else if (event.key === 'End') nextIndex = options.length - 1;
      selectOrganizationMoveDestination(options[nextIndex].id, { focus: true });
    });
    host.appendChild(button);
  });
  host.scrollTop = previousScrollTop;
  if (focusedId && !organizationNameBusy && !organizationNameCtx.unavailable) {
    const target = organizationMoveOptionButton(focusedId);
    try { target?.focus({ preventScroll: true }); } catch { try { target?.focus(); } catch {} }
    try { target?.scrollIntoView({ block: 'nearest' }); } catch {}
  }
}

function paintOrganizationNameDialog() {
  if (!organizationNameCtx) return;
  const { kind, errorKey, unavailable } = organizationNameCtx;
  const operation = organizationNameCtx.operation || 'rename';
  const isRename = operation === 'rename';
  const isCreateAndMove = operation === 'create-space-and-move-group';
  const isExistingMove = operation === 'move-group';
  const titleKey = isRename
    ? `organization.${kind}.renameTitle`
    : isCreateAndMove
      ? 'organization.space.createForGroupTitle'
      : isExistingMove
        ? 'organization.group.moveTitle'
        : `organization.${kind}.createTitle`;
  const titleVars = (isCreateAndMove || isExistingMove) ? { group: organizationNameCtx.groupName } : {};
  const labelKey = isExistingMove
    ? 'organization.group.moveListLabel'
    : `organization.${kind}.nameLabel`;
  const title = document.getElementById('organization-name-title');
  const label = document.getElementById('organization-name-label');
  const input = document.getElementById('organization-name-input');
  const description = document.getElementById('organization-name-description');
  const moveField = document.getElementById('organization-move-field');
  const moveLabel = document.getElementById('organization-move-label');
  const error = document.getElementById('organization-name-error');
  const close = document.getElementById('organization-name-close');
  const cancel = document.getElementById('organization-name-cancel');
  const confirm = document.getElementById('organization-name-confirm');
  title.dataset.i18n = titleKey;
  title.textContent = tr(titleKey, titleVars);
  label.hidden = isExistingMove;
  input.hidden = isExistingMove;
  label.dataset.i18n = labelKey;
  label.textContent = tr(labelKey);
  const closeKey = isExistingMove ? 'organization.group.moveClose' : 'organization.close';
  close.dataset.i18nAriaLabel = closeKey;
  close.setAttribute('aria-label', tr(closeKey));
  cancel.dataset.i18n = 'organization.cancel';
  cancel.textContent = tr('organization.cancel');
  const confirmKey = organizationNameBusy
    ? (isRename
      ? 'organization.renaming'
      : isExistingMove
        ? 'organization.group.moving'
        : 'organization.creating')
    : (isRename
      ? 'organization.rename'
      : isExistingMove
        ? 'organization.group.move'
        : 'organization.create');
  confirm.dataset.i18n = confirmKey;
  confirm.textContent = tr(confirmKey);
  let confirmLabel = confirm.textContent;
  if (isExistingMove && !organizationNameBusy && organizationNameCtx.destinationSpaceId) {
    const destination = (organizationNameCtx.moveOptions || [])
      .find(option => option.id === organizationNameCtx.destinationSpaceId);
    if (destination) {
      confirmLabel = tr('organization.group.moveHistory', {
        group: organizationNameCtx.groupName,
        space: organizationMoveSpaceLabel(destination),
      });
    }
  }
  confirm.setAttribute('aria-label', confirmLabel);
  confirm.title = confirmLabel;
  if (description) {
    description.hidden = !(isCreateAndMove || isExistingMove);
    description.textContent = isCreateAndMove
      ? tr('organization.space.createForGroupBody')
      : isExistingMove
        ? tr('organization.group.moveBody', {
          source: organizationNameCtx.sourceSpaceName,
          workspace: organizationNameCtx.workspaceName,
        })
        : '';
    input.setAttribute('aria-describedby', isCreateAndMove
      ? 'organization-name-description organization-name-error'
      : 'organization-name-error');
  }
  if (moveField) moveField.hidden = !isExistingMove;
  if (moveLabel) {
    moveLabel.dataset.i18n = 'organization.group.moveListLabel';
    moveLabel.textContent = tr('organization.group.moveListLabel');
  }
  paintOrganizationMoveOptions();
  error.hidden = !errorKey;
  error.textContent = errorKey ? tr(errorKey) : '';
  input.setAttribute('aria-invalid', String(!isExistingMove && !!errorKey));
  input.disabled = organizationNameBusy || !!unavailable;
  close.disabled = organizationNameBusy;
  cancel.disabled = organizationNameBusy;
  confirm.disabled = !!unavailable || (isExistingMove && !organizationNameCtx.destinationSpaceId);
  confirm.setAttribute('aria-disabled', String(organizationNameBusy || confirm.disabled));
  document.getElementById('organization-name-overlay')
    .setAttribute('aria-busy', String(organizationNameBusy));
}

function setOrganizationNameBusy(busy) {
  organizationNameBusy = !!busy;
  paintOrganizationNameDialog();
  if (organizationNameBusy) {
    const confirm = document.getElementById('organization-name-confirm');
    try { confirm?.focus({ preventScroll: true }); } catch { try { confirm?.focus(); } catch {} }
  }
}

function setOrganizationNameError(errorKey, { unavailable = false } = {}) {
  if (!organizationNameCtx) return;
  organizationNameCtx.errorKey = errorKey || null;
  organizationNameCtx.unavailable = !!unavailable;
  paintOrganizationNameDialog();
}

function setOrganizationNameInterlock(enabled) {
  const overlay = document.getElementById('organization-name-overlay');
  const recovery = document.getElementById('state-recovery-overlay');
  for (const child of document.body.children) {
    if (child === overlay || child === recovery) continue;
    setElementInertOwner(child, 'organization-name', enabled);
  }
}

function focusOrganizationNameFallback(ctx) {
  const candidates = [];
  const targetId = ctx?.createdId || ctx?.id;
  if (ctx?.operation === 'move-group') {
    const spaces = [...document.querySelectorAll('.space-item')];
    candidates.push(spaces.find(element => element.dataset.catId === ctx.destinationSpaceId));
    candidates.push(spaces.find(element => element.dataset.catId === ctx.sourceSpaceId));
    candidates.push(document.getElementById('add-cat-btn'));
    candidates.push(document.getElementById('ws-menu-btn'));
  } else if (ctx?.kind === 'workspace') {
    const gridCards = [...document.querySelectorAll('.wsg-card')];
    const chips = [...document.querySelectorAll('.ws-chip')];
    if (ctx.workspaceGridOpen) {
      candidates.push(gridCards.find(element => element.dataset.wsId === targetId));
      candidates.push(document.getElementById('wsg-close'));
    }
    candidates.push(chips.find(element => element.dataset.wsid === targetId));
    candidates.push(document.getElementById('ws-menu-btn'));
    candidates.push(document.getElementById('add-ws-btn'));
  } else if (ctx?.kind === 'space') {
    const spaces = [...document.querySelectorAll('.space-item')];
    const homeActions = [...document.querySelectorAll('.home-card-more')];
    candidates.push(spaces.find(element => element.dataset.catId === targetId));
    candidates.push(homeActions.find(element => element.dataset.catId === targetId));
    candidates.push(document.getElementById('add-cat-btn'));
    candidates.push(document.getElementById('ws-menu-btn'));
  }
  for (const target of candidates) {
    if (!target || typeof target.focus !== 'function') continue;
    try { target.focus({ preventScroll: true }); } catch { try { target.focus(); } catch {} }
    if (document.activeElement === target) {
      if (ctx?.operation === 'move-group') {
        try { target.scrollIntoView({ block: 'nearest' }); } catch {}
      }
      return true;
    }
  }
  return false;
}

function closeOrganizationNameDialog({ preferTarget = false } = {}) {
  const overlay = document.getElementById('organization-name-overlay');
  if (!overlay || overlay.classList.contains('hidden') || organizationNameBusy) return false;
  const closingCtx = organizationNameCtx;
  overlay.classList.add('hidden');
  unlockBodyScroll();
  setOrganizationNameBusy(false);
  setOrganizationNameInterlock(false);
  organizationNameCtx = null;
  const restored = restoreOpener(overlay);
  if (preferTarget || !restored) {
    setTimeout(() => focusOrganizationNameFallback(closingCtx), 0);
  }
  return true;
}

function openOrganizationName(kind, id, opener) {
  const overlay = document.getElementById('organization-name-overlay');
  const recovery = document.getElementById('state-recovery-overlay');
  const deleteOverlay = document.getElementById('organization-delete-overlay');
  const trashOverlay = document.getElementById('trash-delete-overlay');
  const legacyModal = document.getElementById('modal-overlay');
  if (!overlay || !overlay.classList.contains('hidden')) return false;
  if ([recovery, deleteOverlay, trashOverlay, legacyModal].some(layer => layer && !layer.classList.contains('hidden'))) return false;
  const target = organizationNameTarget(kind, id);
  if (!target) return false;
  organizationNameCtx = {
    operation: 'rename',
    kind,
    id,
    workspaceId: target.workspaceId || null,
    originalName: target.name,
    errorKey: null,
    unavailable: false,
    workspaceGridOpen: !document.getElementById('ws-grid-overlay')?.classList.contains('hidden'),
  };
  focusDialogOpener(opener);
  rememberOpener(overlay);
  const input = document.getElementById('organization-name-input');
  input.value = target.name;
  setOrganizationNameBusy(false);
  setOrganizationNameInterlock(true);
  overlay.classList.remove('hidden');
  lockBodyScroll();
  setTimeout(() => {
    input.focus({ preventScroll: true });
    input.select();
  }, 0);
  return true;
}

function openOrganizationGroupMove(groupId, opener) {
  const overlay = document.getElementById('organization-name-overlay');
  const recovery = document.getElementById('state-recovery-overlay');
  const deleteOverlay = document.getElementById('organization-delete-overlay');
  const trashOverlay = document.getElementById('trash-delete-overlay');
  const legacyModal = document.getElementById('modal-overlay');
  if (!overlay || !overlay.classList.contains('hidden')) return false;
  if ([recovery, deleteOverlay, trashOverlay, legacyModal]
    .some(layer => layer && !layer.classList.contains('hidden'))) return false;

  const source = identityGroupTarget(String(groupId));
  const options = organizationGroupMoveOptions(source);
  if (!source
    || !options
    || State.get().activeWsId !== source.workspace.id
    || source.workspace.activeCatId !== source.space.id) return false;
  organizationNameCtx = {
    operation: 'move-group',
    kind: 'group',
    id: source.group.id,
    workspaceId: source.workspace.id,
    sourceSpaceId: source.space.id,
    groupId: source.group.id,
    workspaceName: source.workspace.name,
    sourceSpaceName: source.space.name,
    groupName: source.group.name,
    destinationSpaceId: null,
    moveOptions: options,
    reviewFingerprint: organizationGroupMoveFingerprint(source, options),
    errorKey: options.length ? null : 'organization.group.moveNoDestination',
    unavailable: !options.length,
    workspaceGridOpen: !document.getElementById('ws-grid-overlay')?.classList.contains('hidden'),
  };
  focusDialogOpener(opener);
  rememberOpener(overlay);
  document.getElementById('organization-name-input').value = '';
  setOrganizationNameBusy(false);
  setOrganizationNameInterlock(true);
  overlay.classList.remove('hidden');
  lockBodyScroll();
  setTimeout(() => {
    const initial = organizationMoveOptionButton(options[0]?.id)
      || document.getElementById('organization-name-cancel');
    try { initial?.focus({ preventScroll: true }); } catch { try { initial?.focus(); } catch {} }
    try { initial?.scrollIntoView({ block: 'nearest' }); } catch {}
  }, 0);
  return true;
}

function organizationGroupMoveMenuItems(groupId, opener) {
  const source = identityGroupTarget(String(groupId));
  const options = organizationGroupMoveOptions(source);
  if (!source || !options) return [];
  const items = [];
  if (options.length) {
    items.push({
      text: tr('organization.space.moveMenuLabel'),
      icon: cmIcons.move,
      action: () => openOrganizationGroupMove(source.group.id, opener),
    });
  }
  items.push({
    text: tr('organization.space.newAndMoveMenu'),
    icon: cmIcons.move,
    action: () => openOrganizationCreate('space', { groupId: source.group.id }, opener),
  });
  return items;
}

function openOrganizationCreate(kind, options = {}, opener) {
  const overlay = document.getElementById('organization-name-overlay');
  const recovery = document.getElementById('state-recovery-overlay');
  const deleteOverlay = document.getElementById('organization-delete-overlay');
  const trashOverlay = document.getElementById('trash-delete-overlay');
  const legacyModal = document.getElementById('modal-overlay');
  if (!overlay || !overlay.classList.contains('hidden')) return false;
  if ([recovery, deleteOverlay, trashOverlay, legacyModal].some(layer => layer && !layer.classList.contains('hidden'))) return false;

  let context = null;
  if (kind === 'workspace') {
    context = { operation: 'create-workspace', kind };
  } else if (kind === 'space' && options.groupId) {
    const source = organizationGroupTarget(options.groupId);
    const exactWorkspace = source ? organizationWorkspaceTarget(source.workspace.id) : null;
    const exactSpace = source ? organizationNameTarget('space', source.space.id) : null;
    if (!source || exactWorkspace !== source.workspace || exactSpace?.entity !== source.space) return false;
    context = {
      operation: 'create-space-and-move-group',
      kind,
      workspaceId: source.workspace.id,
      sourceSpaceId: source.space.id,
      groupId: source.group.id,
      groupName: source.group.name,
    };
  } else if (kind === 'space') {
    const workspaceId = options.workspaceId || State.get().activeWsId;
    if (!organizationWorkspaceTarget(workspaceId)) return false;
    context = { operation: 'create-space', kind, workspaceId };
  }
  if (!context) return false;

  organizationNameCtx = {
    ...context,
    errorKey: null,
    unavailable: false,
    workspaceGridOpen: !document.getElementById('ws-grid-overlay')?.classList.contains('hidden'),
  };
  focusDialogOpener(opener);
  rememberOpener(overlay);
  const input = document.getElementById('organization-name-input');
  input.value = '';
  setOrganizationNameBusy(false);
  setOrganizationNameInterlock(true);
  overlay.classList.remove('hidden');
  lockBodyScroll();
  setTimeout(() => input.focus({ preventScroll: true }), 0);
  return true;
}

async function confirmOrganizationCreate() {
  if (!organizationNameCtx || organizationNameBusy || organizationNameCtx.unavailable) return false;
  const input = document.getElementById('organization-name-input');
  const desiredName = input.value.trim();
  const dialogCtx = { ...organizationNameCtx };
  if (!desiredName) {
    setOrganizationNameError(`organization.${dialogCtx.kind}.nameRequired`);
    input.focus({ preventScroll: true });
    return false;
  }

  let workspace = null;
  let source = null;
  if (dialogCtx.operation === 'create-space') {
    workspace = organizationWorkspaceTarget(dialogCtx.workspaceId);
    if (!workspace) {
      setOrganizationNameError('organization.space.parentUnavailable', { unavailable: true });
      document.getElementById('organization-name-cancel').focus({ preventScroll: true });
      return false;
    }
  } else if (dialogCtx.operation === 'create-space-and-move-group') {
    source = organizationGroupTarget(dialogCtx.groupId);
    const exactWorkspace = organizationWorkspaceTarget(dialogCtx.workspaceId);
    const exactSpace = organizationNameTarget('space', dialogCtx.sourceSpaceId);
    if (!source
      || exactWorkspace !== source.workspace
      || exactSpace?.entity !== source.space
      || source.workspace.id !== dialogCtx.workspaceId
      || source.space.id !== dialogCtx.sourceSpaceId) {
      setOrganizationNameError('organization.group.unavailable', { unavailable: true });
      document.getElementById('organization-name-cancel').focus({ preventScroll: true });
      return false;
    }
    if (source.group.name !== dialogCtx.groupName) {
      organizationNameCtx.groupName = source.group.name;
      setOrganizationNameError('organization.group.nameChanged');
      input.focus({ preventScroll: true });
      return false;
    }
    workspace = source.workspace;
  }

  let created;
  try {
    const allocateId = createOrganizationIdAllocator();
    if (dialogCtx.operation === 'create-workspace') {
      const space = { id: allocateId(), name: tr('organization.space.defaultName'), groups: [] };
      created = {
        id: allocateId(),
        name: desiredName,
        symbol: '🏠',
        categories: [space],
        activeCatId: space.id,
      };
    } else {
      created = { id: allocateId(), name: desiredName, groups: source ? [source.group] : [] };
      if (source?.space?.canvasPositions
        && Object.prototype.hasOwnProperty.call(source.space.canvasPositions, source.group.id)) {
        created.canvasPositions = { [source.group.id]: source.space.canvasPositions[source.group.id] };
      }
    }
  } catch {
    setOrganizationNameError('organization.idUnavailable');
    input.focus({ preventScroll: true });
    return false;
  }

  let actionId;
  let successKey;
  let successVars;
  if (dialogCtx.operation === 'create-workspace') {
    actionId = State.snapshot(tr('organization.workspace.createHistory', { name: desiredName }));
    State.get().workspaces.push(created);
    State.get().activeWsId = created.id;
    successKey = 'organization.workspace.created';
    successVars = { name: desiredName };
  } else if (dialogCtx.operation === 'create-space') {
    actionId = State.snapshot(tr('organization.space.createHistory', { name: desiredName }));
    workspace.categories.push(created);
    workspace.activeCatId = created.id;
    State.get().activeWsId = workspace.id;
    successKey = 'organization.space.created';
    successVars = { name: desiredName };
  } else {
    const sourceIndex = source.space.groups.findIndex(group => group.id === source.group.id);
    if (sourceIndex < 0) {
      setOrganizationNameError('organization.group.unavailable', { unavailable: true });
      document.getElementById('organization-name-cancel').focus({ preventScroll: true });
      return false;
    }
    actionId = State.snapshot(tr('organization.space.createAndMoveHistory', {
      space: desiredName,
      group: source.group.name,
    }));
    source.space.groups.splice(sourceIndex, 1);
    if (source.space.canvasPositions) delete source.space.canvasPositions[source.group.id];
    workspace.categories.push(created);
    workspace.activeCatId = created.id;
    State.get().activeWsId = workspace.id;
    const remembered = State.get().settings?.captureLastTarget;
    if (remembered?.groupId === source.group.id) {
      remembered.workspaceId = workspace.id;
      remembered.categoryId = created.id;
    }
    successKey = 'organization.space.createdAndMoved';
    successVars = { space: desiredName, group: source.group.name };
  }

  organizationNameCtx.createdId = created.id;
  dialogCtx.createdId = created.id;
  setOrganizationNameBusy(true);
  try {
    await State.persistNow();
  } catch {
    // persistNow owns fail-closed recovery. Keep the one dirty transaction and
    // do not render, close, retry, roll back, or claim success.
    setOrganizationNameBusy(false);
    return false;
  }

  const headerReady = renderAll();
  if (dialogCtx.workspaceGridOpen) {
    try { await openWsGrid(); } catch {}
  } else if (dialogCtx.kind === 'workspace') {
    try { await headerReady; } catch {}
  }
  setOrganizationNameBusy(false);
  closeOrganizationNameDialog({ preferTarget: true });
  toast(tr(successKey, successVars), { undo: actionId });
  return true;
}

async function confirmOrganizationGroupMove() {
  if (!organizationNameCtx
    || organizationNameCtx.operation !== 'move-group'
    || organizationNameBusy
    || organizationNameCtx.unavailable) return false;

  const dialogCtx = organizationNameCtx;
  if (State.get().activeWsId !== dialogCtx.workspaceId) {
    setOrganizationNameError('organization.group.moveContextChanged', { unavailable: true });
    document.getElementById('organization-name-cancel').focus({ preventScroll: true });
    return false;
  }
  const source = identityGroupTarget(dialogCtx.groupId);
  if (source && source.workspace.activeCatId !== dialogCtx.sourceSpaceId) {
    setOrganizationNameError('organization.group.moveContextChanged', { unavailable: true });
    document.getElementById('organization-name-cancel').focus({ preventScroll: true });
    return false;
  }
  const exactWorkspace = organizationWorkspaceTarget(dialogCtx.workspaceId);
  const exactSourceSpace = identitySpaceTarget(dialogCtx.workspaceId, dialogCtx.sourceSpaceId);
  if (!source
    || exactWorkspace !== source.workspace
    || exactSourceSpace?.workspace !== source.workspace
    || exactSourceSpace?.space !== source.space
    || source.workspace.id !== dialogCtx.workspaceId
    || source.space.id !== dialogCtx.sourceSpaceId) {
    setOrganizationNameError('organization.group.unavailable', { unavailable: true });
    document.getElementById('organization-name-cancel').focus({ preventScroll: true });
    return false;
  }

  const options = organizationGroupMoveOptions(source);
  if (!options) {
    setOrganizationNameError('organization.group.unavailable', { unavailable: true });
    document.getElementById('organization-name-cancel').focus({ preventScroll: true });
    return false;
  }
  const reviewFingerprint = organizationGroupMoveFingerprint(source, options);
  if (reviewFingerprint !== dialogCtx.reviewFingerprint) {
    const destinationAvailable = options.some(option => option.id === dialogCtx.destinationSpaceId);
    dialogCtx.workspaceName = source.workspace.name;
    dialogCtx.sourceSpaceName = source.space.name;
    dialogCtx.groupName = source.group.name;
    dialogCtx.moveOptions = options;
    dialogCtx.reviewFingerprint = reviewFingerprint;
    dialogCtx.destinationSpaceId = destinationAvailable ? dialogCtx.destinationSpaceId : null;
    dialogCtx.unavailable = !options.length;
    dialogCtx.errorKey = !options.length
      ? 'organization.group.moveNoDestination'
      : destinationAvailable
        ? 'organization.group.moveChanged'
        : 'organization.group.moveDestinationUnavailable';
    paintOrganizationNameDialog();
    const focusTarget = dialogCtx.destinationSpaceId
      ? organizationMoveOptionButton(dialogCtx.destinationSpaceId)
      : organizationMoveOptionButton(options[0]?.id) || document.getElementById('organization-name-cancel');
    try { focusTarget?.focus({ preventScroll: true }); } catch { try { focusTarget?.focus(); } catch {} }
    try { focusTarget?.scrollIntoView({ block: 'nearest' }); } catch {}
    return false;
  }

  if (!dialogCtx.destinationSpaceId) {
    setOrganizationNameError('organization.group.moveRequired');
    const firstOption = organizationMoveOptionButton(options[0]?.id);
    try { firstOption?.focus({ preventScroll: true }); } catch { try { firstOption?.focus(); } catch {} }
    try { firstOption?.scrollIntoView({ block: 'nearest' }); } catch {}
    return false;
  }

  const destination = identitySpaceTarget(dialogCtx.workspaceId, dialogCtx.destinationSpaceId);
  const destinationOption = options.find(option => option.id === dialogCtx.destinationSpaceId);
  if (!destination
    || destination.workspace !== source.workspace
    || destination.space === source.space
    || !destinationOption
    || destinationOption.id !== destination.space.id) {
    dialogCtx.destinationSpaceId = null;
    dialogCtx.moveOptions = options;
    setOrganizationNameError('organization.group.moveDestinationUnavailable');
    const firstOption = organizationMoveOptionButton(options[0]?.id);
    try { firstOption?.focus({ preventScroll: true }); } catch { try { firstOption?.focus(); } catch {} }
    try { firstOption?.scrollIntoView({ block: 'nearest' }); } catch {}
    return false;
  }

  const sourceIndex = source.space.groups.findIndex(group => group === source.group);
  if (sourceIndex < 0) {
    setOrganizationNameError('organization.group.unavailable', { unavailable: true });
    document.getElementById('organization-name-cancel').focus({ preventScroll: true });
    return false;
  }

  const state = State.get();
  const movedItemIds = organizationGroupItemIds(source.group);
  const destinationLabel = organizationMoveSpaceLabel(destinationOption);
  const actionId = State.snapshot(tr('organization.group.moveHistory', {
    group: source.group.name,
    space: destinationLabel,
  }));
  source.space.groups.splice(sourceIndex, 1);
  destination.space.groups.push(source.group);

  if (source.space.canvasPositions
    && Object.prototype.hasOwnProperty.call(source.space.canvasPositions, source.group.id)) {
    if (!destination.space.canvasPositions
      || typeof destination.space.canvasPositions !== 'object'
      || Array.isArray(destination.space.canvasPositions)) {
      destination.space.canvasPositions = {};
    }
    destination.space.canvasPositions[source.group.id] = source.space.canvasPositions[source.group.id];
    delete source.space.canvasPositions[source.group.id];
  }

  const remembered = state.settings?.captureLastTarget;
  if (remembered
    && remembered.workspaceId === source.workspace.id
    && remembered.categoryId === source.space.id
    && remembered.groupId === source.group.id) {
    remembered.workspaceId = source.workspace.id;
    remembered.categoryId = destination.space.id;
  }

  for (const collection of [state.archive, state.trash]) {
    if (!Array.isArray(collection)) continue;
    collection.forEach(entry => {
      if (entry?.kind !== 'item'
        || entry.wsId !== source.workspace.id
        || entry.catId !== source.space.id
        || entry.groupId !== source.group.id) return;
      entry.wsId = source.workspace.id;
      entry.catId = destination.space.id;
      entry.catName = destination.space.name;
      entry.groupName = source.group.name;
    });
  }

  const successVars = { group: source.group.name, space: destinationLabel };
  setOrganizationNameBusy(true);
  try {
    await State.persistNow();
  } catch {
    // persistNow owns fail-closed recovery. The lower dialog remains as an
    // unavailable receipt record; do not retry, roll back, render, close, or
    // claim success for an outcome the storage boundary did not acknowledge.
    organizationNameBusy = false;
    dialogCtx.errorKey = 'organization.group.moveRecoveryRequired';
    dialogCtx.unavailable = true;
    paintOrganizationNameDialog();
    return false;
  }

  let selectionChanged = false;
  movedItemIds.forEach(itemId => {
    if (selectedItemIds.delete(itemId)) selectionChanged = true;
  });
  if (lastSelectedItemId && movedItemIds.has(String(lastSelectedItemId))) {
    lastSelectedItemId = null;
    selectionChanged = true;
  }
  if (selectionChanged) syncItemSelMode();
  renderAll();
  renderItemSelToolbar();
  setOrganizationNameBusy(false);
  closeOrganizationNameDialog({ preferTarget: true });
  toast(tr('organization.group.moved', successVars), { undo: actionId });
  return true;
}

async function confirmOrganizationName() {
  if (!organizationNameCtx || organizationNameBusy || organizationNameCtx.unavailable) return false;
  if (organizationNameCtx.operation === 'move-group') {
    return confirmOrganizationGroupMove();
  }
  if (organizationNameCtx.operation && organizationNameCtx.operation !== 'rename') {
    return confirmOrganizationCreate();
  }
  const input = document.getElementById('organization-name-input');
  const desiredName = input.value.trim();
  const dialogCtx = { ...organizationNameCtx };
  if (!desiredName) {
    setOrganizationNameError(`organization.${dialogCtx.kind}.nameRequired`);
    input.focus({ preventScroll: true });
    return false;
  }
  const target = organizationNameTarget(dialogCtx.kind, dialogCtx.id);
  if (!target || (dialogCtx.kind === 'space' && target.workspaceId !== dialogCtx.workspaceId)) {
    setOrganizationNameError(`organization.${dialogCtx.kind}.unavailable`, { unavailable: true });
    document.getElementById('organization-name-cancel').focus({ preventScroll: true });
    return false;
  }
  if (target.name !== dialogCtx.originalName) {
    organizationNameCtx.originalName = target.name;
    organizationNameCtx.workspaceId = target.workspaceId || null;
    input.value = target.name;
    setOrganizationNameError('organization.nameChanged');
    input.focus({ preventScroll: true });
    input.select();
    return false;
  }
  if (desiredName === target.name) {
    closeOrganizationNameDialog();
    return true;
  }

  const actionId = State.snapshot(tr(`organization.${dialogCtx.kind}.renameHistory`, {
    from: target.name,
    to: desiredName,
  }));
  target.entity.name = desiredName;
  setOrganizationNameBusy(true);
  try {
    await State.persistNow();
  } catch {
    // persistNow owns fail-closed recovery. Keep the dirty local graph and do
    // not render, close, retry, or claim success for an unknown outcome.
    setOrganizationNameBusy(false);
    return false;
  }

  const headerReady = renderAll();
  if (dialogCtx.workspaceGridOpen) {
    try { await openWsGrid(); } catch {}
  } else if (dialogCtx.kind === 'workspace') {
    // Workspace chips are rebuilt only after asynchronous Chrome window queries.
    // Wait for that actual render boundary before restoring focus; a fixed delay
    // can focus a chip that renderWsChips() subsequently removes.
    try { await headerReady; } catch {}
  }
  setOrganizationNameBusy(false);
  closeOrganizationNameDialog({ preferTarget: true });
  toast(tr(`organization.${dialogCtx.kind}.renamed`, { name: desiredName }), { undo: actionId });
  return true;
}

function bindOrganizationNameDialog() {
  const overlay = document.getElementById('organization-name-overlay');
  if (!overlay) return;
  const input = document.getElementById('organization-name-input');
  document.getElementById('organization-name-close').onclick = () => closeOrganizationNameDialog();
  document.getElementById('organization-name-cancel').onclick = () => closeOrganizationNameDialog();
  document.getElementById('organization-name-confirm').onclick = confirmOrganizationName;
  overlay.onclick = event => {
    if (event.target === overlay) closeOrganizationNameDialog();
  };
  input.addEventListener('input', () => {
    if (organizationNameCtx && !organizationNameCtx.unavailable && organizationNameCtx.errorKey) {
      setOrganizationNameError(null);
    }
  });
  overlay.addEventListener('keydown', event => {
    if (event.key === 'Escape') {
      event.preventDefault();
      event.stopPropagation();
      closeOrganizationNameDialog();
      return;
    }
    if (event.key === 'Enter' && event.target === input) {
      event.preventDefault();
      event.stopPropagation();
      confirmOrganizationName();
      return;
    }
    if (event.key === 'Tab') {
      trapTabKey(event, overlay);
      event.stopPropagation();
      return;
    }
    event.stopPropagation();
  });
}

function handleOrganizationNameGlobalKey(event) {
  const overlay = document.getElementById('organization-name-overlay');
  if (!overlay || overlay.classList.contains('hidden') || overlay.contains(event.target)) return false;
  const recovery = document.getElementById('state-recovery-overlay');
  const recoveryActive = !!(recovery && !recovery.classList.contains('hidden'));
  // The fail-closed recovery layer outranks naming. Do not cancel native
  // keyboard activation of its Reload action as the event reaches document.
  if (recoveryActive && recovery.contains(event.target)) return false;
  event.preventDefault();
  event.stopImmediatePropagation();
  if (event.key === 'Escape' && !recoveryActive) closeOrganizationNameDialog();
  return true;
}

let organizationDeleteCtx = null;
let organizationDeleteBusy = false;

function organizationDeleteOccupancy(entity) {
  const occupancy = { groups: 0, items: 0, reminders: 0 };
  const walk = items => (items || []).forEach(item => {
    occupancy.items += 1;
    if (item?.type === 'stack') walk(item.items);
  });
  const categories = Array.isArray(entity?.categories) ? entity.categories : [entity];
  categories.forEach(category => {
    occupancy.reminders += Array.isArray(category?.reminders) ? category.reminders.length : 0;
    (category?.groups || []).forEach(group => {
      occupancy.groups += 1;
      occupancy.reminders += Array.isArray(group?.reminders) ? group.reminders.length : 0;
      walk(group.items);
    });
  });
  return occupancy;
}

function organizationDeleteTarget(kind, id) {
  const state = State.get();
  if (kind === 'workspace') {
    if (state.workspaces.length <= 1) return null;
    const workspace = state.workspaces.find(candidate => candidate.id === id);
    if (!workspace) return null;
    const occupancy = organizationDeleteOccupancy(workspace);
    return {
      kind, id, name: workspace.name, occupancy,
      blocked: occupancy.groups > 0 || occupancy.items > 0 || occupancy.reminders > 0,
      fingerprint: JSON.stringify(workspace),
    };
  }
  if (kind === 'space') {
    const info = findCategory(id);
    if (!info || info.ws.categories.length <= 1) return null;
    const occupancy = organizationDeleteOccupancy(info.cat);
    return {
      kind, id, name: info.cat.name, occupancy,
      blocked: occupancy.groups > 0 || occupancy.items > 0 || occupancy.reminders > 0,
      fingerprint: JSON.stringify(info.cat), workspaceId: info.ws.id,
    };
  }
  return null;
}

function paintOrganizationDeleteDialog() {
  if (!organizationDeleteCtx) return;
  const { kind, name, blocked } = organizationDeleteCtx;
  const titleKey = `organization.${kind}.${blocked ? 'blockedTitle' : 'confirmTitle'}`;
  const title = document.getElementById('organization-delete-title');
  title.dataset.i18n = titleKey;
  title.textContent = tr(titleKey);
  document.getElementById('organization-delete-message').textContent = tr(
    `organization.${kind}.${blocked ? 'blockedBody' : 'confirmEmpty'}`,
    { name }
  );
  const cancelKey = blocked ? 'organization.close' : 'organization.cancel';
  const cancelButton = document.getElementById('organization-delete-cancel');
  cancelButton.dataset.i18n = cancelKey;
  cancelButton.textContent = tr(cancelKey);
  const confirmButton = document.getElementById('organization-delete-confirm');
  confirmButton.hidden = blocked;
  const confirmKey = organizationDeleteBusy ? 'organization.deleting' : `organization.${kind}.delete`;
  confirmButton.dataset.i18n = confirmKey;
  confirmButton.textContent = tr(confirmKey);
}

function setOrganizationDeleteBusy(busy) {
  const overlay = document.getElementById('organization-delete-overlay');
  const cancel = document.getElementById('organization-delete-cancel');
  const confirmButton = document.getElementById('organization-delete-confirm');
  organizationDeleteBusy = !!busy;
  if (overlay) overlay.setAttribute('aria-busy', String(organizationDeleteBusy));
  if (cancel) cancel.disabled = organizationDeleteBusy;
  if (confirmButton) confirmButton.disabled = organizationDeleteBusy || !!organizationDeleteCtx?.blocked;
  paintOrganizationDeleteDialog();
}

function setOrganizationDeleteInterlock(enabled) {
  const overlay = document.getElementById('organization-delete-overlay');
  const recovery = document.getElementById('state-recovery-overlay');
  for (const child of document.body.children) {
    if (child === overlay || child === recovery) continue;
    setElementInertOwner(child, 'organization', enabled);
  }
}

function focusOrganizationDeleteFallback(ctx) {
  const state = State.get();
  const workspace = state.workspaces.find(candidate => candidate.id === state.activeWsId);
  const activeCategoryId = workspace?.activeCatId;
  const visibleSpace = ctx?.kind === 'space' && activeCategoryId
    ? [...document.querySelectorAll('.space-item')].find(element => element.dataset.catId === activeCategoryId)
    : null;
  const candidates = ctx?.kind === 'workspace'
    ? [
        ctx.workspaceGridOpen ? document.getElementById('wsg-close') : null,
        document.getElementById('ws-menu-btn'),
        document.getElementById('add-ws-btn'),
      ]
    : [visibleSpace, document.getElementById('add-cat-btn'), document.getElementById('ws-menu-btn')];
  for (const target of candidates) {
    if (!target || typeof target.focus !== 'function') continue;
    try { target.focus({ preventScroll: true }); } catch { try { target.focus(); } catch {} }
    if (document.activeElement === target) return true;
  }
  return false;
}

function closeOrganizationDeleteDialog() {
  const overlay = document.getElementById('organization-delete-overlay');
  if (!overlay || overlay.classList.contains('hidden') || organizationDeleteBusy) return false;
  const closingCtx = organizationDeleteCtx;
  overlay.classList.add('hidden');
  unlockBodyScroll();
  setOrganizationDeleteBusy(false);
  setOrganizationDeleteInterlock(false);
  organizationDeleteCtx = null;
  if (!restoreOpener(overlay)) setTimeout(() => focusOrganizationDeleteFallback(closingCtx), 0);
  return true;
}

function focusDialogOpener(opener) {
  if (!opener || opener.isConnected === false || typeof opener.focus !== 'function') return;
  try { opener.focus({ preventScroll: true }); } catch { try { opener.focus(); } catch {} }
}

function openOrganizationDelete(kind, id, opener) {
  const overlay = document.getElementById('organization-delete-overlay');
  if (!overlay || !overlay.classList.contains('hidden')) return false;
  const namingOverlay = document.getElementById('organization-name-overlay');
  if (namingOverlay && !namingOverlay.classList.contains('hidden')) return false;
  const target = organizationDeleteTarget(kind, id);
  if (!target) return false;
  focusDialogOpener(opener);
  rememberOpener(overlay);
  organizationDeleteCtx = {
    ...target,
    workspaceGridOpen: !document.getElementById('ws-grid-overlay')?.classList.contains('hidden'),
  };
  setOrganizationDeleteBusy(false);
  setOrganizationDeleteInterlock(true);
  overlay.classList.remove('hidden');
  lockBodyScroll();
  setTimeout(() => document.getElementById('organization-delete-cancel')?.focus({ preventScroll: true }), 0);
  return true;
}

async function confirmOrganizationDelete() {
  if (organizationDeleteBusy || !organizationDeleteCtx) return false;
  const current = organizationDeleteTarget(organizationDeleteCtx.kind, organizationDeleteCtx.id);
  if (!current) {
    closeOrganizationDeleteDialog();
    return false;
  }
  if (current.fingerprint !== organizationDeleteCtx.fingerprint) {
    organizationDeleteCtx = { ...organizationDeleteCtx, ...current };
    setOrganizationDeleteBusy(false);
    document.getElementById('organization-delete-cancel')?.focus({ preventScroll: true });
    return false;
  }
  if (current.blocked) {
    organizationDeleteCtx = { ...organizationDeleteCtx, ...current };
    setOrganizationDeleteBusy(false);
    document.getElementById('organization-delete-cancel')?.focus({ preventScroll: true });
    return false;
  }

  const dialogCtx = organizationDeleteCtx;
  setOrganizationDeleteBusy(true);
  const actionId = State.snapshot(tr(`organization.${dialogCtx.kind}.deleteHistory`, { name: dialogCtx.name }));
  const state = State.get();
  if (dialogCtx.kind === 'workspace') {
    state.workspaces = state.workspaces.filter(workspace => workspace.id !== dialogCtx.id);
    if (state.activeWsId === dialogCtx.id) state.activeWsId = state.workspaces[0].id;
  } else {
    const info = findCategory(dialogCtx.id);
    info.ws.categories = info.ws.categories.filter(category => category.id !== dialogCtx.id);
    if (info.ws.activeCatId === dialogCtx.id) info.ws.activeCatId = info.ws.categories[0].id;
  }

  try {
    await State.persistNow();
  } catch {
    // persistNow owns the fail-closed recovery overlay. Do not render or claim
    // success until browser storage has acknowledged this recoverable change.
    setOrganizationDeleteBusy(false);
    return false;
  }

  renderAll();
  if (dialogCtx.workspaceGridOpen) {
    try { await openWsGrid(); } catch {}
  }
  setOrganizationDeleteBusy(false);
  closeOrganizationDeleteDialog();
  toast(tr(`organization.${dialogCtx.kind}.deleted`), { undo: actionId });
  return true;
}

function bindOrganizationDeleteDialog() {
  const overlay = document.getElementById('organization-delete-overlay');
  if (!overlay) return;
  document.getElementById('organization-delete-cancel').onclick = closeOrganizationDeleteDialog;
  document.getElementById('organization-delete-confirm').onclick = confirmOrganizationDelete;
  overlay.addEventListener('keydown', event => {
    if (event.key === 'Escape') {
      event.preventDefault();
      event.stopPropagation();
      closeOrganizationDeleteDialog();
      return;
    }
    if (event.key === 'Tab') {
      trapTabKey(event, overlay);
      return;
    }
    // Preserve native button activation while preventing document-level
    // shortcuts from opening a second surface above this decision.
    event.stopPropagation();
  });
}

function handleOrganizationDeleteGlobalKey(event) {
  const overlay = document.getElementById('organization-delete-overlay');
  if (!overlay || overlay.classList.contains('hidden') || overlay.contains(event.target)) return false;
  const recovery = document.getElementById('state-recovery-overlay');
  const recoveryActive = !!(recovery && !recovery.classList.contains('hidden'));
  if (recoveryActive && recovery.contains(event.target)) return false;
  event.preventDefault();
  event.stopImmediatePropagation();
  if (event.key === 'Escape' && !recoveryActive) closeOrganizationDeleteDialog();
  return true;
}

// ════════════════════════════════════════════════════════════════
// CRUD
// ════════════════════════════════════════════════════════════════
function identitySpaceTarget(workspaceId, spaceId) {
  const workspaces = State.get().workspaces.filter(workspace => workspace.id === workspaceId);
  const spaces = [];
  State.get().workspaces.forEach(workspace => {
    workspace.categories.forEach(space => {
      if (space.id === spaceId) spaces.push({ workspace, space });
    });
  });
  if (workspaces.length !== 1 || spaces.length !== 1 || spaces[0].workspace !== workspaces[0]) return null;
  return spaces[0];
}

function identityGroupTarget(groupId) {
  const target = organizationGroupTarget(groupId);
  if (!target) return null;
  const parent = identitySpaceTarget(target.workspace.id, target.space.id);
  if (!parent || parent.workspace !== target.workspace || parent.space !== target.space) return null;
  return { workspace: target.workspace, space: target.space, group: target.group };
}

// Resolve item IDs exhaustively instead of trusting findItem's first match.
// Imported duplicate IDs, selected ancestors/descendants, and moved parents
// therefore fail closed before the identity transaction takes a snapshot.
function identityItemTargets(itemIds) {
  const ids = [...new Set((itemIds || []).map(String))];
  const wanted = new Set(ids);
  const matches = new Map(ids.map(id => [id, []]));
  let order = 0;
  const walk = (items, ctx, parentStack, ancestorStackIds) => {
    for (let index = 0; index < items.length; index += 1) {
      const item = items[index];
      const id = String(item.id);
      const itemOrder = order++;
      if (wanted.has(id)) {
        matches.get(id).push({
          ...ctx,
          item,
          parentItems: items,
          parentStack,
          parentKey: parentStack ? `stack:${parentStack.id}` : `group:${ctx.group.id}`,
          ancestorStackIds: [...ancestorStackIds],
          index,
          order: itemOrder,
        });
      }
      if (item.type === 'stack' && Array.isArray(item.items)) {
        walk(item.items, ctx, item, [...ancestorStackIds, id]);
      }
    }
  };
  State.get().workspaces.forEach(workspace => {
    workspace.categories.forEach(space => {
      space.groups.forEach(group => {
        walk(group.items || [], { workspace, space, group }, null, []);
      });
    });
  });
  if (ids.some(id => matches.get(id).length !== 1)) return null;
  const targets = ids.map(id => matches.get(id)[0]).sort((a, b) => a.order - b.order);
  const nested = targets.some(target => target.ancestorStackIds.some(id => wanted.has(String(id))));
  return { targets, nested };
}

function identityStackTarget(stackId) {
  const resolved = identityItemTargets([stackId]);
  const target = resolved?.targets[0];
  if (target?.item?.type !== 'stack') return null;
  const group = identityGroupTarget(target.group.id);
  if (!group || group.group !== target.group) return null;
  for (const ancestorId of target.ancestorStackIds) {
    const ancestor = identityItemTargets([ancestorId])?.targets[0];
    if (!ancestor || ancestor.item.type !== 'stack') return null;
  }
  return target;
}

function identityFields(entity) {
  return {
    name: String(entity?.name || ''),
    symbol: String(entity?.symbol || ''),
    color: String(entity?.color || '#6366f1'),
  };
}

function identityFieldsFingerprint(entity) {
  return JSON.stringify(identityFields(entity));
}

function identitySelectionFingerprint(targets) {
  return JSON.stringify(targets.map(target => ({
    id: String(target.item.id),
    workspaceId: String(target.workspace.id),
    spaceId: String(target.space.id),
    groupId: String(target.group.id),
    parentKey: target.parentKey,
  })));
}

function identityGroupDuplicateFingerprint(target) {
  return JSON.stringify({
    workspaceId: target?.workspace?.id,
    spaceId: target?.space?.id,
    spaceName: target?.space?.name,
    group: target?.group,
  });
}

function cloneGroupForDuplicate(source, allocateId) {
  const copy = JSON.parse(JSON.stringify(source));
  const rekeyItems = items => (items || []).forEach(item => {
    item.id = allocateId();
    if (item.type === 'stack' && Array.isArray(item.items)) rekeyItems(item.items);
  });
  copy.id = allocateId();
  rekeyItems(copy.items);
  return copy;
}

function groupContainsReminderData(group) {
  if (Array.isArray(group?.reminders) && group.reminders.length) return true;
  const visit = items => (items || []).some(item => (
    !!item?.reminder || (item?.type === 'stack' && visit(item.items))
  ));
  return visit(group?.items);
}

function cloneGroupLayoutValue(value) {
  if (value == null) return value;
  return JSON.parse(JSON.stringify(value));
}

function prepareGroupDuplicateLayout(state, space, duplicate) {
  const layout = { keyed: [] };
  for (const key of ['columnSizes', 'columnWidths']) {
    const record = state[key];
    if (!record || typeof record !== 'object' || Array.isArray(record)
        || !Object.prototype.hasOwnProperty.call(record, duplicate.sourceId)) continue;
    layout.keyed.push({ key, value: cloneGroupLayoutValue(record[duplicate.sourceId]) });
  }
  const positions = space.canvasPositions;
  if (positions && typeof positions === 'object' && !Array.isArray(positions)) {
    const legacySizes = state.columnWidths && typeof state.columnWidths === 'object' && !Array.isArray(state.columnWidths)
      ? state.columnWidths
      : {};
    const currentSizes = state.columnSizes && typeof state.columnSizes === 'object' && !Array.isArray(state.columnSizes)
      ? state.columnSizes
      : {};
    const effectiveSizes = { ...legacySizes };
    for (const [groupId, savedSize] of Object.entries(currentSizes)) {
      // Rendering uses columnSizes[id] ?? columnWidths[id]; keep placement on
      // that same per-ID contract when imported current records are nullish.
      if (savedSize != null) effectiveSizes[groupId] = savedSize;
    }
    layout.canvasPosition = findOpenCanvasPosition(
      duplicate.group,
      [...space.groups, duplicate.group],
      positions,
      effectiveSizes[duplicate.sourceId],
      effectiveSizes,
    );
  }
  return layout;
}

function applyGroupDuplicateLayout(state, space, duplicate, layout) {
  for (const entry of layout.keyed) {
    if (!state[entry.key] || typeof state[entry.key] !== 'object' || Array.isArray(state[entry.key])) {
      state[entry.key] = {};
    }
    state[entry.key][duplicate.group.id] = entry.value;
  }
  if (layout.canvasPosition) space.canvasPositions[duplicate.group.id] = layout.canvasPosition;
}

function reconcileDuplicatedGroupReminders(group, name, actionId) {
  if (!groupContainsReminderData(group)) return;
  Promise.resolve()
    .then(() => chrome.runtime.sendMessage({ type: 'reconcile-reminders' }))
    .then(result => {
      if (result?.ok !== true) throw new Error('Reminder reconciliation failed');
    })
    .catch(() => {
      const current = identityGroupTarget(group.id);
      if (current?.group === group && State.latestActionId() === actionId) {
        toast(tr('groupEditor.duplicateReminderWarning', { name }), {
          tone: 'warning',
          duration: 8000,
          undo: actionId,
        });
      } else {
        toast(tr('history.reminderReconcileWarning'), { tone: 'warning', ...reminderReconcileRetry() });
      }
  });
}

function groupHasReopenableSavedTab(group) {
  const pending = Array.isArray(group?.items) ? [...group.items] : [];
  const seen = new Set();
  while (pending.length) {
    const item = pending.pop();
    if (!item || typeof item !== 'object' || seen.has(item)) continue;
    seen.add(item);
    if (item.type === 'tab' && isOpenableSavedTabUrl(item.url)) return true;
    if (item.type === 'stack' && Array.isArray(item.items)) {
      for (const child of item.items) pending.push(child);
    }
  }
  return false;
}

function openGroupAll(group, opener = null) {
  const target = identityGroupTarget(group?.id);
  if (!target || target.group !== group) {
    const message = tr('bulkReopen.groupUnavailable');
    if (!showBulkSavedTabReopenRecovery(opener, message)) {
      toast(message, { danger: true, duration: 5000 });
    }
    requestAnimationFrame(() => {
      if (!opener || opener.isConnected === false || typeof opener.focus !== 'function') return;
      try { opener.focus({ preventScroll: true }); } catch { try { opener.focus(); } catch {} }
    });
    return false;
  }
  const items = [];
  const collect = (list) => { list.forEach(it => { if (it.type === 'tab') items.push(it); else if (it.type === 'stack') collect(it.items || []); }); };
  collect(target.group.items);
  return openSavedTabItems(items, { opener });
}

// ════════════════════════════════════════════════════════════════
// GROUP / STACK IDENTITY EDITOR
// ════════════════════════════════════════════════════════════════
let modalCtx = null;
let modalBusy = false;
let intentEditorCtx = null;

function identityEditorPrefix() {
  return modalCtx?.entityKind === 'stack' ? 'stackEditor' : 'groupEditor';
}

function paintIdentityEditor() {
  if (!modalCtx) return;
  const prefix = identityEditorPrefix();
  const operation = modalCtx.operation;
  const isEdit = operation === 'edit';
  const isBatch = operation === 'batch-create';
  const isDuplicate = operation === 'duplicate';
  const titleKey = `${prefix}.${isBatch ? 'batchTitle' : isDuplicate ? 'duplicateTitle' : isEdit ? 'editTitle' : 'createTitle'}`;
  const confirmKey = `${prefix}.${modalBusy
    ? (isEdit ? 'saving' : isDuplicate ? 'duplicating' : 'creating')
    : (isEdit ? 'save' : isDuplicate ? 'duplicate' : 'create')}`;
  const title = document.getElementById('modal-title');
  const close = document.getElementById('modal-x');
  const symbolLabel = document.getElementById('lbl-symbol');
  const symbolHint = document.getElementById('emoji-trigger-hint');
  const symbolTrigger = document.getElementById('emoji-trigger');
  const nameLabel = document.getElementById('modal-name-label');
  const input = document.getElementById('modal-input');
  const colorLabel = document.getElementById('lbl-color');
  const description = document.getElementById('modal-description');
  const error = document.getElementById('modal-error');
  const cancel = document.getElementById('modal-cancel');
  const confirm = document.getElementById('modal-ok');
  const overlay = document.getElementById('modal-overlay');

  // An untouched generated copy name follows a live locale change. Once the
  // user types, their draft is canonical and must never be translated.
  if (isDuplicate && !modalBusy && !modalCtx.nameTouched) {
    modalCtx.draftName = tr('groupEditor.duplicateDefaultName', { name: modalCtx.sourceName });
    input.value = modalCtx.draftName;
  }

  title.dataset.i18n = titleKey;
  title.textContent = tr(titleKey);
  const closeKey = isDuplicate ? 'groupEditor.duplicateClose' : `${prefix}.close`;
  close.dataset.i18nAriaLabel = closeKey;
  close.setAttribute('aria-label', tr(closeKey));
  symbolLabel.dataset.i18n = `${prefix}.symbolLabel`;
  symbolLabel.textContent = tr(`${prefix}.symbolLabel`);
  symbolHint.dataset.i18n = `${prefix}.symbolHint`;
  symbolHint.textContent = tr(`${prefix}.symbolHint`);
  symbolTrigger.setAttribute('aria-label', tr('emojiPicker.current', { symbol: modalCtx.draftSymbol }));
  nameLabel.dataset.i18n = `${prefix}.nameLabel`;
  nameLabel.textContent = tr(`${prefix}.nameLabel`);
  input.dataset.i18nPlaceholder = `${prefix}.namePlaceholder`;
  input.placeholder = tr(`${prefix}.namePlaceholder`);
  colorLabel.dataset.i18n = `${prefix}.colorLabel`;
  colorLabel.textContent = tr(`${prefix}.colorLabel`);
  cancel.dataset.i18n = 'organization.cancel';
  cancel.textContent = tr('organization.cancel');
  confirm.dataset.i18n = confirmKey;
  confirm.textContent = tr(confirmKey);

  description.hidden = !isBatch && !isDuplicate;
  description.textContent = isBatch
    ? tr('stackEditor.batchDescription', { count: modalCtx.batchIds.length, group: modalCtx.groupName })
    : (isDuplicate
      ? tr('groupEditor.duplicateDescription', { group: modalCtx.sourceName, space: modalCtx.spaceName })
      : '');
  error.hidden = !modalCtx.errorKey;
  error.textContent = modalCtx.errorKey ? tr(modalCtx.errorKey) : '';
  const nameInvalid = modalCtx.errorKey === `${prefix}.nameRequired`;
  input.setAttribute('aria-invalid', String(nameInvalid));
  if (nameInvalid) input.setAttribute('aria-describedby', 'modal-error');
  else input.removeAttribute('aria-describedby');
  const disabled = modalBusy || !!modalCtx.unavailable;
  input.disabled = disabled;
  symbolTrigger.disabled = disabled;
  document.querySelectorAll('#color-row .csw').forEach(button => {
    button.disabled = disabled;
    const colorName = tr(`groupEditor.color.${button.dataset.colorKey}`);
    button.setAttribute('aria-label', tr('groupEditor.colorOption', { color: colorName }));
    button.title = colorName;
  });
  close.disabled = modalBusy;
  cancel.disabled = modalBusy;
  confirm.disabled = !!modalCtx.unavailable;
  confirm.setAttribute('aria-disabled', String(disabled));
  overlay.setAttribute('aria-busy', String(modalBusy));
}

function setIdentityEditorBusy(busy) {
  modalBusy = !!busy;
  paintIdentityEditor();
  if (modalBusy) document.getElementById('modal-ok')?.focus({ preventScroll: true });
}

function setIdentityEditorError(errorKey, { unavailable = false } = {}) {
  if (!modalCtx) return;
  modalCtx.errorKey = errorKey || '';
  modalCtx.unavailable = !!unavailable;
  paintIdentityEditor();
  const recovery = document.getElementById('state-recovery-overlay');
  const recoveryOwnsForeground = !!(recovery && !recovery.classList.contains('hidden'))
    || !!State.isRecoveryRequired?.();
  if (modalCtx.unavailable && !recoveryOwnsForeground) {
    const target = document.getElementById('modal-cancel') || document.getElementById('modal-x');
    try { target?.focus({ preventScroll: true }); } catch { try { target?.focus(); } catch {} }
  }
}

function clearIdentityEditorError() {
  if (!modalCtx || modalCtx.unavailable || !modalCtx.errorKey) return;
  if (modalCtx.errorKey === `${identityEditorPrefix()}.nameRequired` &&
      !document.getElementById('modal-input')?.value.trim()) return;
  modalCtx.errorKey = '';
  paintIdentityEditor();
}

function selectIdentityColor(color, { focus = false, chosen = false } = {}) {
  const requested = String(color || '#6366f1');
  const allButtons = [...document.querySelectorAll('#color-row .csw')];
  const custom = document.getElementById('identity-custom-color');
  let selected = allButtons.find(button => button !== custom && button.dataset.c === requested);
  let represented = !!selected;
  if (!selected && custom) {
    custom.hidden = false;
    custom.dataset.c = requested;
    custom.style.setProperty('--identity-custom-color', requested);
    selected = custom;
    represented = true;
  } else if (custom) {
    custom.hidden = true;
    custom.classList.remove('active');
    custom.setAttribute('aria-checked', 'false');
    custom.tabIndex = -1;
    custom.style.removeProperty('--identity-custom-color');
  }
  const buttons = allButtons.filter(button => !button.hidden);
  if (!selected) selected = buttons[0];
  buttons.forEach(button => {
    const active = button === selected;
    button.classList.toggle('active', active);
    button.setAttribute('aria-checked', String(active));
    button.tabIndex = active ? 0 : -1;
  });
  if (modalCtx) {
    modalCtx.draftColor = represented ? selected.dataset.c : requested;
    if (chosen) modalCtx.colorChosen = true;
  }
  if (focus && selected) selected.focus({ preventScroll: true });
  clearIdentityEditorError();
}

function handleIdentityColorKeydown(event) {
  if (!event.target.matches?.('#color-row .csw')) return false;
  const buttons = [...document.querySelectorAll('#color-row .csw')].filter(button => !button.hidden);
  const index = Math.max(0, buttons.indexOf(event.target));
  let next = index;
  if (event.key === 'Home') next = 0;
  else if (event.key === 'End') next = buttons.length - 1;
  else if (event.key === 'ArrowLeft' || event.key === 'ArrowUp') next = (index - 1 + buttons.length) % buttons.length;
  else if (event.key === 'ArrowRight' || event.key === 'ArrowDown') next = (index + 1) % buttons.length;
  else return false;
  event.preventDefault();
  event.stopPropagation();
  selectIdentityColor(buttons[next].dataset.c, { focus: true, chosen: true });
  return true;
}

function setIdentityEditorInterlock(enabled) {
  const overlay = document.getElementById('modal-overlay');
  const recovery = document.getElementById('state-recovery-overlay');
  const emoji = document.getElementById('emoji-picker');
  for (const child of document.body.children) {
    if (child === overlay || child === recovery || child === emoji) continue;
    setElementInertOwner(child, 'identity-editor', enabled);
  }
}

function focusIdentityTarget(kind, id) {
  const value = typeof CSS !== 'undefined' && CSS.escape ? CSS.escape(String(id)) : String(id).replace(/["\\]/g, '\\$&');
  const detail = document.getElementById('item-detail');
  const selectors = kind === 'group'
    ? [
        `.gcol[data-gid="${value}"] .gcol-toggle:not(.hidden)`,
        `.gcol[data-gid="${value}"] [data-act="more"]`,
        `.spc-col[data-gid="${value}"] .spc-chev`,
        `.lv-group[data-gid="${value}"] .lv-group-toggle`,
        `.ibx[data-gid="${value}"] .ibx-card[tabindex="0"]`,
        `.ibx[data-gid="${value}"] .ibx-title`,
      ]
    : [
        detail?.dataset.itemId === String(id) ? '#item-detail [data-idp-focus="stack-identity"]' : '',
        `.item.stack[data-id="${value}"] .stack-toggle`,
        `.lv-stack[data-id="${value}"] .lv-stack-toggle`,
      ];
  for (const selector of selectors) {
    if (!selector) continue;
    const target = document.querySelector(selector);
    if (!target || typeof target.focus !== 'function') continue;
    try { target.focus({ preventScroll: true }); } catch { try { target.focus(); } catch {} }
    if (document.activeElement === target) {
      try { target.scrollIntoView?.({ block: 'nearest', inline: 'nearest' }); } catch {}
      return true;
    }
  }
  return false;
}

function focusIdentityFallback(ctx) {
  if (ctx?.operation === 'edit' || ctx?.operation === 'duplicate') {
    if (focusIdentityTarget(ctx.entityKind, ctx.entityId)) return true;
  }
  const batchAction = ctx?.operation === 'batch-create'
    ? document.querySelector('#item-sel-toolbar [data-act="stack"]')
    : null;
  if (batchAction) {
    try { batchAction.focus({ preventScroll: true }); } catch { try { batchAction.focus(); } catch {} }
    if (document.activeElement === batchAction) return true;
  }
  if (ctx?.entityKind === 'stack' && ctx.groupId && focusIdentityTarget('group', ctx.groupId)) return true;
  const candidates = [
    document.querySelector('[data-spc-act="add-group"]:not([hidden])'),
    document.getElementById('space-title'),
    document.getElementById('board'),
  ];
  for (const target of candidates) {
    if (!target || typeof target.focus !== 'function') continue;
    try { target.focus({ preventScroll: true }); } catch { try { target.focus(); } catch {} }
    if (document.activeElement === target) return true;
  }
  return false;
}

function closeIdentityEditor({ restoreFocus = true } = {}) {
  const overlay = document.getElementById('modal-overlay');
  if (!overlay || overlay.classList.contains('hidden') || modalBusy) return false;
  const closingCtx = modalCtx;
  if (emojiPickerCtx?.target?.kind === 'identity-editor') closeEmojiPicker({ restoreFocus: false });
  overlay.classList.add('hidden');
  unlockBodyScroll();
  setIdentityEditorInterlock(false);
  modalCtx = null;
  modalBusy = false;
  const restored = restoreFocus ? restoreOpener(overlay) : (_overlayOpeners.delete(overlay), false);
  if (restoreFocus && !restored) setTimeout(() => focusIdentityFallback(closingCtx), 0);
  return true;
}

function closeModal() {
  return closeIdentityEditor();
}

function prepareIdentityBatch(itemIds) {
  const ids = [...new Set((itemIds || []).map(String))];
  if (ids.length < 2) return { errorKey: 'stackEditor.minimumSelection' };
  const resolved = identityItemTargets(ids);
  if (!resolved) return { errorKey: 'stackEditor.selectionUnavailable' };
  const uniqueParents = resolved.targets.every(target => {
    const group = identityGroupTarget(target.group.id);
    if (!group || group.group !== target.group) return false;
    return target.ancestorStackIds.every(ancestorId => {
      const ancestor = identityItemTargets([ancestorId])?.targets[0];
      return !!ancestor && ancestor.item.type === 'stack';
    });
  });
  if (!uniqueParents) return { errorKey: 'stackEditor.selectionUnavailable' };
  if (resolved.nested) return { errorKey: 'stackEditor.selectionNested' };
  const spaces = new Set(resolved.targets.map(target => `${target.workspace.id}:${target.space.id}`));
  if (spaces.size !== 1) return { errorKey: 'stackEditor.selectionScope' };
  const destination = resolved.targets.find(target => String(target.item.id) === ids[0]);
  return { resolved, destination };
}

function rejectIdentityEditorOpen(errorKey, fallbackCtx = null) {
  toast(tr(errorKey), { danger: true, duration: 6000 });
  if (fallbackCtx) setTimeout(() => focusIdentityFallback(fallbackCtx), 0);
  return false;
}

function openIdentityEditor(entityKind, operation, params = {}, opener) {
  const overlay = document.getElementById('modal-overlay');
  const recovery = document.getElementById('state-recovery-overlay');
  const organizationName = document.getElementById('organization-name-overlay');
  const organizationDelete = document.getElementById('organization-delete-overlay');
  if (!overlay || !overlay.classList.contains('hidden')) return false;
  if ((recovery && !recovery.classList.contains('hidden')) ||
      (organizationName && !organizationName.classList.contains('hidden')) ||
      (organizationDelete && !organizationDelete.classList.contains('hidden'))) return false;

  // Context-menu items disappear before their action runs. Move focus back to
  // the durable surface opener even when validation rejects the requested edit.
  focusDialogOpener(opener);
  const rejectionFallback = opener && (opener.isConnected === false || document.activeElement !== opener)
    ? {
        entityKind,
        operation,
        entityId: params.groupId || params.stackId || '',
        groupId: params.groupId || '',
      }
    : null;
  let next = null;
  if (entityKind === 'group' && operation === 'create') {
    const target = identitySpaceTarget(params.workspaceId, params.spaceId);
    if (!target) return rejectIdentityEditorOpen('groupEditor.parentUnavailable', rejectionFallback);
    next = {
      entityKind, operation,
      workspaceId: target.workspace.id,
      spaceId: target.space.id,
      draftName: '', draftSymbol: '📁', draftColor: '#6366f1', nameTouched: false, colorChosen: false,
    };
  } else if (entityKind === 'group' && operation === 'duplicate') {
    const target = identityGroupTarget(params.groupId);
    const state = State.get();
    if (!target || (params.workspaceId && target.workspace.id !== params.workspaceId) ||
        (params.spaceId && target.space.id !== params.spaceId) ||
        state.activeWsId !== target.workspace.id || target.workspace.activeCatId !== target.space.id) {
      return rejectIdentityEditorOpen('groupEditor.unavailable', rejectionFallback);
    }
    const fields = identityFields(target.group);
    next = {
      entityKind, operation, entityId: target.group.id,
      workspaceId: target.workspace.id, spaceId: target.space.id,
      sourceName: fields.name, spaceName: String(target.space.name || ''),
      openedFromGroupPage: typeof activeGroupPage !== 'undefined'
        && activeGroupPage?.groupId === target.group.id,
      baseline: identityGroupDuplicateFingerprint(target),
      draftName: tr('groupEditor.duplicateDefaultName', { name: fields.name }),
      draftSymbol: fields.symbol || '??', draftColor: fields.color,
      nameTouched: false, colorChosen: false,
    };
  } else if (entityKind === 'group' && operation === 'edit') {
    const target = identityGroupTarget(params.groupId);
    if (!target || (params.workspaceId && target.workspace.id !== params.workspaceId) ||
        (params.spaceId && target.space.id !== params.spaceId)) return rejectIdentityEditorOpen('groupEditor.unavailable', rejectionFallback);
    const fields = identityFields(target.group);
    next = {
      entityKind, operation, entityId: target.group.id,
      workspaceId: target.workspace.id, spaceId: target.space.id,
      baseline: identityFieldsFingerprint(target.group),
      draftName: fields.name, draftSymbol: fields.symbol || '📁', draftColor: fields.color, nameTouched: false, colorChosen: false,
    };
  } else if (entityKind === 'stack' && operation === 'create') {
    const target = identityGroupTarget(params.groupId);
    if (!target || (params.workspaceId && target.workspace.id !== params.workspaceId) ||
        (params.spaceId && target.space.id !== params.spaceId)) return rejectIdentityEditorOpen('stackEditor.parentUnavailable', rejectionFallback);
    next = {
      entityKind, operation,
      workspaceId: target.workspace.id, spaceId: target.space.id, groupId: target.group.id,
      draftName: '', draftSymbol: '📚', draftColor: '#6366f1', nameTouched: false, colorChosen: false,
    };
  } else if (entityKind === 'stack' && operation === 'edit') {
    const target = identityStackTarget(params.stackId);
    if (!target || (params.workspaceId && target.workspace.id !== params.workspaceId) ||
        (params.spaceId && target.space.id !== params.spaceId) ||
        (params.groupId && target.group.id !== params.groupId)) return rejectIdentityEditorOpen('stackEditor.unavailable', rejectionFallback);
    const fields = identityFields(target.item);
    next = {
      entityKind, operation, entityId: target.item.id,
      workspaceId: target.workspace.id, spaceId: target.space.id, groupId: target.group.id,
      parentKey: target.parentKey,
      baseline: identityFieldsFingerprint(target.item),
      draftName: fields.name, draftSymbol: fields.symbol || '📚', draftColor: fields.color, nameTouched: false, colorChosen: false,
    };
  } else if (entityKind === 'stack' && operation === 'batch-create') {
    const prepared = prepareIdentityBatch(params.itemIds);
    if (prepared.errorKey) {
      return rejectIdentityEditorOpen(prepared.errorKey, rejectionFallback);
    }
    const targets = prepared.resolved.targets;
    const first = prepared.destination;
    next = {
      entityKind, operation,
      workspaceId: first.workspace.id, spaceId: first.space.id, groupId: first.group.id,
      groupName: first.group.name,
      batchIds: targets.map(target => String(target.item.id)),
      batchBaseline: identitySelectionFingerprint(targets),
      draftName: '', draftSymbol: '📚', draftColor: '#6366f1', nameTouched: false, colorChosen: false,
    };
  }
  if (!next) return false;

  rememberOpener(overlay);
  modalCtx = next;
  modalBusy = false;
  document.getElementById('modal-input').value = next.draftName;
  document.getElementById('emoji-trigger-val').textContent = next.draftSymbol;
  selectIdentityColor(next.draftColor);
  paintIdentityEditor();
  setIdentityEditorInterlock(true);
  overlay.classList.remove('hidden');
  lockBodyScroll();
  setTimeout(() => {
    const target = params.focusField === 'symbol'
      ? document.getElementById('emoji-trigger')
      : document.getElementById('modal-input');
    target?.focus({ preventScroll: true });
    if (operation === 'duplicate' && target === document.getElementById('modal-input')
        && typeof target.select === 'function') target.select();
  }, 0);
  return true;
}

function handleIdentityEditorKeydown(event) {
  const overlay = document.getElementById('modal-overlay');
  if (!overlay || overlay.classList.contains('hidden')) return false;
  if (handleIdentityColorKeydown(event)) return true;
  if (event.key === 'Escape') {
    event.preventDefault();
    event.stopPropagation();
    if (!modalBusy) closeIdentityEditor();
    return true;
  }
  if (event.key === 'Tab') trapTabKey(event, overlay);
  if (event.key === 'Enter' && event.target === document.getElementById('modal-input')) {
    event.preventDefault();
    void confirmIdentityEditor();
  }
  event.stopPropagation();
  return true;
}

function handleIdentityEditorGlobalKey(event) {
  const overlay = document.getElementById('modal-overlay');
  if (!overlay || overlay.classList.contains('hidden') || overlay.contains(event.target)) return false;
  const emoji = document.getElementById('emoji-picker');
  const recovery = document.getElementById('state-recovery-overlay');
  if ((emoji && !emoji.classList.contains('hidden') && emoji.contains(event.target)) ||
      (recovery && !recovery.classList.contains('hidden') && recovery.contains(event.target))) return false;
  event.preventDefault();
  event.stopImmediatePropagation();
  if (event.key === 'Escape' && !modalBusy) closeIdentityEditor();
  return true;
}
function openIntentEditor(targetKind, targetId) {
  let entity = null;
  let title = 'Edit Intention';
  if (targetKind === 'group') {
    const info = findGroup(targetId);
    if (!info) return;
    entity = info.group;
    title = `Intention · ${info.group.name}`;
  } else if (targetKind === 'stack') {
    const info = findItem(targetId);
    if (!info || info.item.type !== 'stack') return;
    entity = info.item;
    title = `Intention · ${info.item.name || 'Stack'}`;
  }
  intentEditorCtx = { targetKind, targetId };
  const intent = entity.intent || {};
  document.getElementById('intent-title').textContent = title;
  document.getElementById('intent-purpose').value = intent.purpose || '';
  document.getElementById('intent-next-action').value = intent.nextAction || '';
  document.getElementById('intent-status').value = intent.status || 'active';
  document.getElementById('intent-type').value = intent.type || 'other';
  document.getElementById('intent-overlay').classList.remove('hidden');
}
function closeIntentEditor() {
  document.getElementById('intent-overlay').classList.add('hidden');
  intentEditorCtx = null;
}
function getIntentTarget(ctx = intentEditorCtx) {
  if (!ctx) return null;
  if (ctx.targetKind === 'group') return findGroup(ctx.targetId)?.group || null;
  if (ctx.targetKind === 'stack') {
    const info = findItem(ctx.targetId);
    if (info?.item?.type === 'stack') return info.item;
  }
  return null;
}
function saveIntentEditor() {
  const entity = getIntentTarget();
  if (!entity) return closeIntentEditor();
  const purpose = document.getElementById('intent-purpose').value.trim();
  const nextAction = document.getElementById('intent-next-action').value.trim();
  const status = document.getElementById('intent-status').value;
  const type = document.getElementById('intent-type').value;
  State.snapshot(tr('history.editIntention'));
  if (!purpose && !nextAction && status === 'active' && type === 'other') clearIntentMeta(entity);
  else {
    const i = ensureIntentMeta(entity);
    i.purpose = purpose;
    i.nextAction = nextAction;
    i.status = INTENT_STATUS.includes(status) ? status : 'active';
    i.type = INTENT_TYPE.includes(type) ? type : 'other';
    i.updatedAt = Date.now();
  }
  State.persist();
  renderBoard();
  closeIntentEditor();
  toast(tr('feedback.intentionSaved'));
}
function clearIntentEditor() {
  const entity = getIntentTarget();
  if (!entity) return closeIntentEditor();
  State.snapshot(tr('history.clearIntention'));
  clearIntentMeta(entity);
  State.persist();
  renderBoard();
  closeIntentEditor();
  toast(tr('feedback.intentionCleared'), { undo: true });
}
async function confirmIdentityEditor() {
  if (!modalCtx || modalBusy) return false;
  const ctx = modalCtx;
  const prefix = identityEditorPrefix();
  const input = document.getElementById('modal-input');
  let name = input.value.trim();
  const symbol = String(ctx.draftSymbol || (ctx.entityKind === 'stack' ? '📚' : '📁'));
  const color = String(ctx.draftColor || '#6366f1');
  ctx.draftName = input.value;
  if (!name && (ctx.operation !== 'edit' || ctx.nameTouched)) {
    setIdentityEditorError(`${prefix}.nameRequired`);
    input.focus({ preventScroll: true });
    return false;
  }

  let target = null;
  let batchTargets = null;
  let duplicatedGroup = null;
  let duplicateLayout = null;
  let sourceIndex = -1;
  if (ctx.entityKind === 'group' && ctx.operation === 'create') {
    target = identitySpaceTarget(ctx.workspaceId, ctx.spaceId);
    if (!target) {
      setIdentityEditorError('groupEditor.parentUnavailable', { unavailable: true });
      return false;
    }
  } else if (ctx.entityKind === 'group' && ctx.operation === 'duplicate') {
    target = identityGroupTarget(ctx.entityId);
    const state = State.get();
    if (!target || target.workspace.id !== ctx.workspaceId || target.space.id !== ctx.spaceId ||
        state.activeWsId !== ctx.workspaceId || target.workspace.activeCatId !== ctx.spaceId) {
      setIdentityEditorError('groupEditor.unavailable', { unavailable: true });
      return false;
    }
    sourceIndex = target.space.groups.indexOf(target.group);
    if (sourceIndex < 0) {
      setIdentityEditorError('groupEditor.unavailable', { unavailable: true });
      return false;
    }
    const currentBaseline = identityGroupDuplicateFingerprint(target);
    if (currentBaseline !== ctx.baseline) {
      const fields = identityFields(target.group);
      ctx.baseline = currentBaseline;
      ctx.sourceName = fields.name;
      ctx.spaceName = String(target.space.name || '');
      if (!ctx.nameTouched) {
        ctx.draftName = tr('groupEditor.duplicateDefaultName', { name: fields.name });
        input.value = ctx.draftName;
      } else {
        ctx.draftName = input.value;
      }
      if (!ctx.symbolChosen) ctx.draftSymbol = fields.symbol || '??';
      if (!ctx.colorChosen) ctx.draftColor = fields.color;
      document.getElementById('emoji-trigger-val').textContent = ctx.draftSymbol;
      selectIdentityColor(ctx.draftColor);
      setIdentityEditorError('groupEditor.duplicateChanged');
      input.focus({ preventScroll: true });
      return false;
    }
  } else if (ctx.entityKind === 'group' && ctx.operation === 'edit') {
    target = identityGroupTarget(ctx.entityId);
    if (!target || target.workspace.id !== ctx.workspaceId || target.space.id !== ctx.spaceId) {
      setIdentityEditorError('groupEditor.unavailable', { unavailable: true });
      return false;
    }
    const currentBaseline = identityFieldsFingerprint(target.group);
    if (currentBaseline !== ctx.baseline) {
      const fields = identityFields(target.group);
      ctx.baseline = currentBaseline;
      ctx.draftName = fields.name;
      ctx.draftSymbol = fields.symbol || '📁';
      ctx.draftColor = fields.color;
      ctx.nameTouched = false;
      ctx.symbolChosen = false;
      ctx.colorChosen = false;
      input.value = ctx.draftName;
      document.getElementById('emoji-trigger-val').textContent = ctx.draftSymbol;
      selectIdentityColor(ctx.draftColor);
      setIdentityEditorError('groupEditor.changed');
      input.focus({ preventScroll: true });
      return false;
    }
    if (!ctx.nameTouched) name = String(target.group.name || '');
    const nameUnchanged = !ctx.nameTouched || name === String(target.group.name || '');
    const symbolUnchanged = !ctx.symbolChosen || symbol === String(target.group.symbol || '');
    const colorUnchanged = !ctx.colorChosen || color === String(target.group.color || '');
    if (nameUnchanged && symbolUnchanged && colorUnchanged) {
      closeIdentityEditor();
      return true;
    }
  } else if (ctx.entityKind === 'stack' && ctx.operation === 'create') {
    target = identityGroupTarget(ctx.groupId);
    if (!target || target.workspace.id !== ctx.workspaceId || target.space.id !== ctx.spaceId) {
      setIdentityEditorError('stackEditor.parentUnavailable', { unavailable: true });
      return false;
    }
  } else if (ctx.entityKind === 'stack' && ctx.operation === 'edit') {
    target = identityStackTarget(ctx.entityId);
    if (!target || target.workspace.id !== ctx.workspaceId || target.space.id !== ctx.spaceId ||
        target.group.id !== ctx.groupId || target.parentKey !== ctx.parentKey) {
      setIdentityEditorError('stackEditor.unavailable', { unavailable: true });
      return false;
    }
    const currentBaseline = identityFieldsFingerprint(target.item);
    if (currentBaseline !== ctx.baseline) {
      const fields = identityFields(target.item);
      ctx.baseline = currentBaseline;
      ctx.draftName = fields.name;
      ctx.draftSymbol = fields.symbol || '📚';
      ctx.draftColor = fields.color;
      ctx.nameTouched = false;
      ctx.symbolChosen = false;
      ctx.colorChosen = false;
      input.value = ctx.draftName;
      document.getElementById('emoji-trigger-val').textContent = ctx.draftSymbol;
      selectIdentityColor(ctx.draftColor);
      setIdentityEditorError('stackEditor.changed');
      input.focus({ preventScroll: true });
      return false;
    }
    if (!ctx.nameTouched) name = String(target.item.name || '');
    const nameUnchanged = !ctx.nameTouched || name === String(target.item.name || '');
    const symbolUnchanged = !ctx.symbolChosen || symbol === String(target.item.symbol || '');
    const colorUnchanged = !ctx.colorChosen || color === String(target.item.color || '');
    if (nameUnchanged && symbolUnchanged && colorUnchanged) {
      closeIdentityEditor();
      return true;
    }
  } else if (ctx.entityKind === 'stack' && ctx.operation === 'batch-create') {
    const prepared = prepareIdentityBatch(ctx.batchIds);
    batchTargets = prepared.resolved?.targets || null;
    if (prepared.errorKey || !batchTargets || identitySelectionFingerprint(batchTargets) !== ctx.batchBaseline) {
      setIdentityEditorError('stackEditor.selectionUnavailable', { unavailable: true });
      return false;
    }
    target = identityGroupTarget(ctx.groupId);
    if (!target || target.workspace.id !== ctx.workspaceId || target.space.id !== ctx.spaceId) {
      setIdentityEditorError('stackEditor.parentUnavailable', { unavailable: true });
      return false;
    }
  } else {
    return false;
  }

  let entityId = ctx.entityId || null;
  if (ctx.operation !== 'edit') {
    try {
      const allocateId = createOrganizationIdAllocator();
      if (ctx.operation === 'duplicate') {
        duplicatedGroup = cloneGroupForDuplicate(target.group, allocateId);
        entityId = duplicatedGroup.id;
        duplicatedGroup.name = name;
        if (ctx.symbolChosen) duplicatedGroup.symbol = symbol;
        if (ctx.colorChosen) duplicatedGroup.color = color;
        duplicateLayout = prepareGroupDuplicateLayout(State.get(), target.space, {
          sourceId: target.group.id,
          group: duplicatedGroup,
        });
      } else {
        entityId = allocateId();
      }
    } catch {
      setIdentityEditorError(ctx.operation === 'duplicate'
        ? 'groupEditor.duplicateIdUnavailable'
        : `${prefix}.idUnavailable`);
      return false;
    }
  }

  const count = batchTargets?.length || 0;
  const historyKey = ctx.operation === 'batch-create'
    ? 'stackEditor.batchHistory'
    : (ctx.operation === 'duplicate'
      ? 'groupEditor.duplicateHistory'
      : `${prefix}.${ctx.operation === 'edit' ? 'editHistory' : 'createHistory'}`);
  setIdentityEditorBusy(true);
  const actionId = State.snapshot(tr(historyKey, { name, count, source: ctx.sourceName }));
  const state = State.get();
  state.activeWsId = ctx.workspaceId;
  const workspace = state.workspaces.find(candidate => candidate.id === ctx.workspaceId);
  if (workspace) workspace.activeCatId = ctx.spaceId;

  if (ctx.entityKind === 'group' && ctx.operation === 'create') {
    target.space.groups.push({
      id: entityId, name, symbol, color, collapsed: false, items: [],
    });
  } else if (ctx.entityKind === 'group' && ctx.operation === 'duplicate') {
    target.space.groups.splice(sourceIndex + 1, 0, duplicatedGroup);
    applyGroupDuplicateLayout(state, target.space, {
      sourceId: target.group.id,
      group: duplicatedGroup,
    }, duplicateLayout);
  } else if (ctx.entityKind === 'group' && ctx.operation === 'edit') {
    if (ctx.nameTouched) target.group.name = name;
    if (ctx.symbolChosen) target.group.symbol = symbol;
    if (ctx.colorChosen) target.group.color = color;
  } else if (ctx.entityKind === 'stack' && ctx.operation === 'create') {
    target.group.items.push(stampNew({
      id: entityId, type: 'stack', name, symbol, color, expanded: true, items: [],
    }));
  } else if (ctx.entityKind === 'stack' && ctx.operation === 'edit') {
    if (ctx.nameTouched) target.item.name = name;
    if (ctx.symbolChosen) target.item.symbol = symbol;
    if (ctx.colorChosen) target.item.color = color;
  } else if (ctx.operation === 'batch-create') {
    const moved = [];
    for (let index = ctx.batchIds.length - 1; index >= 0; index -= 1) {
      const current = identityItemTargets([ctx.batchIds[index]])?.targets[0];
      if (current) moved.unshift(...current.parentItems.splice(current.index, 1));
    }
    target.group.items.unshift(stampNew({
      id: entityId, type: 'stack', name, symbol, color, expanded: true, items: moved,
    }));
  }
  if (ctx.symbolChosen) rememberRecentEmoji(symbol);

  try {
    await State.persistNow();
  } catch (error) {
    // The persistence layer owns fail-closed recovery. Keep the dirty graph
    // behind it, and do not render, close, retry, or claim success here.
    if (State.isRecoveryRequired?.() && typeof showStateRecoveryRequired === 'function') {
      showStateRecoveryRequired(error);
    }
    setIdentityEditorBusy(false);
    setIdentityEditorError(ctx.operation === 'duplicate'
      ? 'groupEditor.duplicateRecoveryRequired'
      : `${prefix}.recoveryRequired`, { unavailable: true });
    return false;
  }

  if (ctx.operation === 'batch-create') {
    selectedItemIds.clear();
    explicitSelMode = false;
    lastSelectedItemId = null;
    syncItemSelMode();
    document.getElementById('item-sel-toolbar')?.remove();
  }
  if (ctx.operation === 'duplicate' && ctx.openedFromGroupPage && typeof Router !== 'undefined') {
    Router.navigate({
      type: 'group', wsId: ctx.workspaceId, groupId: entityId, itemId: null, query: {},
    }, { persist: false });
  } else {
    renderAll();
  }
  modalBusy = false;
  closeIdentityEditor({ restoreFocus: false });
  requestAnimationFrame(() => {
    if (!focusIdentityTarget(ctx.entityKind, entityId)) focusIdentityFallback(ctx);
  });
  const successKey = ctx.operation === 'batch-create'
    ? 'stackEditor.stacked'
    : (ctx.operation === 'duplicate'
      ? 'groupEditor.duplicated'
      : `${prefix}.${ctx.operation === 'edit' ? 'updated' : 'created'}`);
  toast(tr(successKey, { name, count, source: ctx.sourceName }), { undo: actionId });
  if (ctx.operation === 'duplicate') {
    reconcileDuplicatedGroupReminders(duplicatedGroup, name, actionId);
  }
  return true;
}

// ════════════════════════════════════════════════════════════════
// OPEN-TABS SIDEBAR + Multi-select + Window grouping
// ════════════════════════════════════════════════════════════════
let allOpenTabs = [];
let openTabsLoadState = 'loading';
let openTabsRefreshGeneration = 0;
let homeTrailSavePending = false;
let currentActiveTabId = null;
let selectedTabIds = new Set();
let lastClickedTabId = null;

function openTabSelectionOrder() {
  const visibleRows = Array.from(document.querySelectorAll('#open-tabs .otab:not(.hidden)'));
  const visibleIds = visibleRows.map(el => Number(el.dataset.tid)).filter(Number.isFinite);
  return visibleIds.length ? visibleIds : allOpenTabs.map(t => t.id);
}

function selectOpenTabRangeTo(tabId) {
  if (lastClickedTabId == null) lastClickedTabId = tabId;
  let order = openTabSelectionOrder();
  let aI = order.indexOf(lastClickedTabId);
  let bI = order.indexOf(tabId);
  if (aI < 0 || bI < 0) {
    order = allOpenTabs.map(t => t.id);
    aI = order.indexOf(lastClickedTabId);
    bI = order.indexOf(tabId);
  }
  if (aI < 0 || bI < 0) {
    selectedTabIds.add(tabId);
    lastClickedTabId = tabId;
    return;
  }
  const [lo, hi] = aI < bI ? [aI, bI] : [bI, aI];
  for (let k = lo; k <= hi; k++) selectedTabIds.add(order[k]);
}

function restoreOpenTabSelectionFocus(tabId) {
  requestAnimationFrame(() => {
    if (!isOpenTabsRailAvailable()) return;
    const rail = document.getElementById('tabrail');
    const todayDrawer = typeof isTodayTabsDrawerOpen === 'function' && isTodayTabsDrawerOpen();
    if (rail?.classList.contains('collapsed') && !todayDrawer) {
      document.getElementById('tabrail-toggle')?.focus();
      return;
    }
    const target = document.querySelector(`#open-tabs .otab[data-tid="${CSS.escape(String(tabId))}"] .otab-check`);
    if (target) target.focus();
    else restoreOpenTabCaptureFocus();
  });
}

function restoreOpenTabCaptureFocus() {
  requestAnimationFrame(() => {
    if (!isOpenTabsRailAvailable()) {
      const fallback = document.getElementById('topbar-save') || document.getElementById('nav-home');
      if (fallback?.focus) fallback.focus({ preventScroll: true });
      return;
    }
    const selected = document.querySelector('#open-tabs .otab.selected:not(.hidden) .otab-check');
    const filter = document.getElementById('tab-filter');
    const toggle = document.getElementById('tabrail-toggle');
    if (selected) {
      selected.focus();
      if (document.activeElement === selected) return;
    }
    if (filter) {
      filter.focus();
      if (document.activeElement === filter) return;
    }
    toggle?.focus();
  });
  return true;
}

function toggleOpenTabSelection(tabId, { range = false, restoreFocus = false } = {}) {
  if (range) {
    selectOpenTabRangeTo(tabId);
  } else {
    if (selectedTabIds.has(tabId)) selectedTabIds.delete(tabId);
    else selectedTabIds.add(tabId);
    lastClickedTabId = selectedTabIds.size ? tabId : null;
  }
  updateSelectedBadge();
  renderOpenTabs();
  if (restoreFocus) restoreOpenTabSelectionFocus(tabId);
}

function setOpenTabRailCount(value) {
  const count = document.getElementById('open-count');
  if (count) count.textContent = String(value);
  if (typeof syncTodayTabsEar === 'function') syncTodayTabsEar(value);
}

function renderOpenTabRailState(kind, options = {}) {
  const list = document.getElementById('open-tabs');
  if (!list) return false;
  const definitions = {
    loading: { titleKey: 'rail.loading', bodyKey: 'rail.loadingBody', role: 'status' },
    error: { titleKey: 'rail.error', bodyKey: 'rail.errorBody', actionKey: 'rail.retry', role: 'alert' },
    empty: { titleKey: 'rail.empty', bodyKey: 'rail.emptyBody', role: 'status' },
  };
  const definition = definitions[kind];
  if (!definition) return false;
  const action = definition.actionKey
    ? `<button type="button" class="otab-state-action">${esc(tr(definition.actionKey))}</button>`
    : '';
  list.setAttribute('aria-busy', String(kind === 'loading'));
  list.innerHTML = `
    <div class="otab-state is-${kind}" role="${definition.role}" aria-live="${kind === 'error' ? 'assertive' : 'polite'}">
      <span class="otab-state-mark" aria-hidden="true"></span>
      <strong>${esc(tr(definition.titleKey))}</strong>
      <p>${esc(tr(definition.bodyKey))}</p>
      ${action}
    </div>`;
  if (kind === 'error') {
    list.querySelector('.otab-state-action')?.addEventListener('click', () => retryOpenTabs());
  }
  if (options.focusAction) list.querySelector('.otab-state-action')?.focus();
  return true;
}

function retryOpenTabs() {
  if (openTabsLoadState === 'loading') return false;
  openTabsLoadState = 'loading';
  setOpenTabRailCount('—');
  renderOpenTabs();
  void refreshOpenTabs();
  return true;
}

function resolveOpenTabActionTarget(tab) {
  if (!Number.isInteger(tab?.id)) return null;
  const matches = allOpenTabs.filter(candidate => candidate.id === tab.id
    && candidate.windowId === tab.windowId
    && candidate.url === tab.url);
  return matches.length === 1 ? matches[0] : null;
}

function openTabActionMenuItems(tab, opener) {
  const t = resolveOpenTabActionTarget(tab);
  if (!t) return [];
  const tabTitle = String(t.title || t.url || '').trim() || tr('itemAction.untitled');
  const saveable = isOpenableSavedTabUrl(t.url);
  const batch = selectedTabIds.has(t.id) && selectedTabIds.size > 1;
  const saveCount = selectedCaptureTabs().length;
  const batchSave = batch && saveCount > 0;
  const restoreBefore = action => () => {
    focusDialogOpener(opener);
    return action();
  };
  return [
    { text: tr('rail.switchToTab', { title: tabTitle }), icon: cmIcons.open, action: restoreBefore(() => chrome.tabs.update(t.id, { active: true })) },
    { text: tr(selectedTabIds.has(t.id) ? 'rail.deselectTab' : 'rail.selectTab', { title: tabTitle }), icon: cmIcons.edit, action: () => toggleOpenTabSelection(t.id, { restoreFocus: true }) },
    batchSave ? { text: tr('rail.saveSelectedAsGroup', { count: saveCount }), icon: cmIcons.stack, action: () => saveSelectedAsGroup() } : null,
    { sep: true },
    batchSave
      ? { text: tr('rail.saveSelectedToInbox', { count: saveCount }), icon: cmIcons.archive, action: () => saveSelectedToInbox() }
      : !batch && saveable
        ? { text: tr('rail.saveToInbox', { title: tabTitle }), icon: cmIcons.archive, action: () => saveTabToInbox(t, { destinationReceipt: true }) }
        : null,
    {
      text: batch ? tr('rail.closeSelectedTabs', { count: selectedTabIds.size }) : tr('rail.closeTab', { title: tabTitle }),
      icon: cmIcons.delete,
      danger: true,
      action: () => {
        if (batch) {
          const ids = [...selectedTabIds];
          for (const id of ids) chrome.tabs.remove(id).catch(() => {});
          selectedTabIds.clear();
          lastClickedTabId = null;
          updateSelectedBadge();
          renderOpenTabs();
          restoreOpenTabCaptureFocus();
        } else {
          chrome.tabs.remove(t.id).catch(() => {});
        }
      },
    },
  ].filter(Boolean);
}

async function refreshOpenTabs() {
  const generation = ++openTabsRefreshGeneration;
  const previousTrailCandidate = homeTrailCandidateFingerprint();
  const focusKey = activeHome ? activeHomeTrailFocusKey() : null;
  try {
    const [activeArr, all] = await Promise.all([
      chrome.tabs.query({ active: true, currentWindow: true }),
      chrome.tabs.query({ currentWindow: true })  // Current window only for sidebar
    ]);
    if (generation !== openTabsRefreshGeneration) return false;
    allOpenTabs = all.filter(t => !isProto(t.url));
    openTabsLoadState = 'ready';
    currentActiveTabId = activeArr[0]?.id;
    setOpenTabRailCount(allOpenTabs.length);
    const focusedTabId = document.activeElement?.classList?.contains('otab-check')
      ? document.activeElement.closest('.otab[data-tid]')?.dataset?.tid
      : null;
    renderOpenTabs();
    if (focusedTabId != null) restoreOpenTabSelectionFocus(focusedTabId);
  } catch (e) {
    if (generation !== openTabsRefreshGeneration) return false;
    openTabsLoadState = 'error';
    setOpenTabRailCount('—');
    renderOpenTabs();
    console.warn('refreshOpenTabs', e);
  }
  // Home first renders before this deferred browser query. Repaint only the
  // active Home surface so its candidate leaves loading as soon as real tab
  // state arrives; other routes keep their existing rendering cadence.
  // Capture mutates the in-memory graph optimistically, then waits for storage.
  // A tab event that resolves in that window must not expose the unacknowledged
  // item on Home. The accepted or recovery path owns the eventual repaint.
  // The Today board shows nothing derived from the trail candidate (its tab
  // count is set by setOpenTabRailCount above), so a tab event never rebuilds
  // it and keyboard focus on a Today control stays where it is.
  const todayShown = !!document.querySelector?.('#board .today');
  if (activeHome && !captureCommitPending && !todayCapturePending && !todayShown
      && homeTrailCandidateFingerprint() !== previousTrailCandidate) {
    renderBoard();
    if (focusKey) restoreHomeTrailFocus(focusKey) || restoreHomeTrailFocus('capture');
  }
  return openTabsLoadState === 'ready';
}

function renderOpenTabs() {
  const $el = document.getElementById('open-tabs');
  if (!$el) return false;
  const scrollPos = $el.scrollTop;
  $el.innerHTML = '';

  // Clean stale selections
  const validIds = new Set(allOpenTabs.map(t => t.id));
  let selectionChanged = false;
  for (const id of [...selectedTabIds]) {
    if (!validIds.has(id)) {
      selectedTabIds.delete(id);
      selectionChanged = true;
    }
  }
  // Drop the shift-range anchor once nothing is selected so the next
  // shift-click starts a fresh range instead of spanning from a stale tab.
  if (!selectedTabIds.size) lastClickedTabId = null;
  if (selectionChanged) updateSelectedBadge();

  if (openTabsLoadState === 'loading') {
    setOpenTabRailCount('—');
    renderOpenTabRailState('loading');
    syncOpenTabRailCaptureControls();
    return true;
  }
  if (openTabsLoadState === 'error') {
    setOpenTabRailCount('—');
    renderOpenTabRailState('error');
    syncOpenTabRailCaptureControls();
    return true;
  }

  if (!allOpenTabs.length) {
    setOpenTabRailCount(0);
    renderOpenTabRailState('empty');
    syncOpenTabRailCaptureControls();
    return true;
  }

  $el.setAttribute('aria-busy', 'false');

  allOpenTabs.forEach(t => {
    const el = document.createElement('div');
    el.className = 'otab';
    el.setAttribute('role', 'listitem');
    el.tabIndex = -1;
    el.dataset.tid = t.id;
    if (t.id === currentActiveTabId) el.classList.add('active-tab');
    if (selectedTabIds.has(t.id)) el.classList.add('selected');
    const saveable = isOpenableSavedTabUrl(t.url);
    if (!saveable) el.classList.add('is-save-unavailable');
    el.draggable = saveable;
    const tabTitle = String(t.title || t.url || '').trim() || tr('itemAction.untitled');
    const selected = selectedTabIds.has(t.id);
    const fav = favUrl(t.url) || BLANK_FAV;
    // Chrome-discarded tabs keep their URL but are unloaded — flag them so the
    // sidebar reads like a workspace of live + resting tabs, not a flat list.
    const sleeping = t.discarded === true;
    const badge = sleeping
      ? `<span class="folio-badge is-hibernated" title="${esc(tr('rail.asleepHint'))}"><svg viewBox="0 0 14 14" fill="none"><path d="M11.5 8.2A4.6 4.6 0 015.8 2.5a4.6 4.6 0 105.7 5.7z" stroke="currentColor" stroke-width="1.4" stroke-linejoin="round"/></svg>${esc(tr('rail.asleep'))}</span>`
      : '';
    const domain = (() => { try { return new URL(t.url).hostname.replace(/^www\./, ''); } catch { return ''; } })();
    const tabMeta = saveable
      ? domain
      : [domain, tr('rail.notSaveable')].filter(Boolean).join(' · ');
    el.innerHTML = `
      <span class="otab-handle" aria-hidden="true"><svg width="8" height="12" viewBox="0 0 8 12" fill="currentColor"><circle cx="2" cy="2" r="1"/><circle cx="6" cy="2" r="1"/><circle cx="2" cy="6" r="1"/><circle cx="6" cy="6" r="1"/><circle cx="2" cy="10" r="1"/><circle cx="6" cy="10" r="1"/></svg></span>
      <button type="button" class="otab-check" role="checkbox" aria-checked="${selected}" aria-label="${esc(tr(selected ? 'rail.deselectTab' : 'rail.selectTab', { title: tabTitle }))}"></button>
      <button type="button" class="otab-primary" aria-label="${esc(tr('rail.switchToTab', { title: tabTitle }))}">
        <img class="otab-fav" src="${esc(fav)}" alt="" loading="lazy" decoding="async" draggable="false">
        <span class="otab-text">
          <span class="otab-title">${esc(t.title || t.url)}</span>
          <span class="otab-domain">${esc(tabMeta)}</span>
        </span>${badge}
      </button>
      <button type="button" class="otab-close" title="${esc(tr('rail.closeTab', { title: tabTitle }))}" aria-label="${esc(tr('rail.closeTab', { title: tabTitle }))}"><svg width="10" height="10" viewBox="0 0 10 10"><path d="M2 2l6 6M8 2l-6 6" stroke="currentColor" stroke-width="1.4" stroke-linecap="round"/></svg></button>`;

    // Checkbox area click — toggles selection without switching tab
    const tabCheck = el.querySelector('.otab-check');
    tabCheck.addEventListener('click', (e) => {
      e.stopPropagation();
      toggleOpenTabSelection(t.id, { range: e.shiftKey, restoreFocus: true });
    });

    // Close button — closes the browser tab without switching to it
    el.querySelector('.otab-close').addEventListener('click', (e) => {
      e.stopPropagation();
      chrome.tabs.remove(t.id).catch(() => {});
    });

    el.querySelector('.otab-primary').addEventListener('click', (e) => {
      if (e.shiftKey) {
        toggleOpenTabSelection(t.id, { range: true });
        return;
      }
      if (e.ctrlKey || e.metaKey) {
        toggleOpenTabSelection(t.id);
        return;
      }
      // In selection mode: click to add/toggle, not switch
      if (selectedTabIds.size > 0) {
        toggleOpenTabSelection(t.id);
        return;
      }
      // Plain click → switch tab
      lastClickedTabId = t.id;
      chrome.tabs.update(t.id, { active: true }).catch(()=>{});
    });

    bindBoardItemContextMenu(el, opener => openTabActionMenuItems(t, opener));

    // ── DRAG ── Promote to multi-drag if the dragged tab is selected
    el.addEventListener('dragstart', (e) => {
      if (!saveable) { e.preventDefault(); return; }
      const batchTabs = selectedCaptureTabs();
      const inBatch = selectedTabIds.has(t.id) && batchTabs.length > 1;
      // If user starts dragging an unselected tab while a batch exists, keep it single
      if (inBatch) {
        const tabs = batchTabs;
        const sourceDescriptors = tabs.map(capturedTabSourceDescriptor);
        if (sourceDescriptors.some(descriptor => !descriptor)) { e.preventDefault(); return; }
        drag = { kind: 'tabs-multi', data: sourceDescriptors };
        // Mark all selected tabs as dragging visually
        const draggedIds = new Set(tabs.map(tab => String(tab.id)));
        document.querySelectorAll('.otab.selected').forEach(x => {
          if (draggedIds.has(x.dataset.tid)) x.classList.add('dragging');
        });
        // Custom drag image showing count
        try {
          const ghost = document.createElement('div');
          ghost.className = 'multi-drag-ghost';
          ghost.textContent = tr('rail.tabsCount', { count: tabs.length });
          document.body.appendChild(ghost);
          ghost.style.position = 'absolute';
          ghost.style.left = '-9999px';
          e.dataTransfer.setDragImage(ghost, 40, 15);
          setTimeout(() => ghost.remove(), 0);
        } catch {}
      } else {
        const sourceDescriptor = capturedTabSourceDescriptor(t);
        if (!sourceDescriptor) { e.preventDefault(); return; }
        drag = { kind:'tab', data: sourceDescriptor };
        el.classList.add('dragging');
        // Custom compact drag image (favicon + title, no checkbox) so the
        // browser doesn't fall back to a full snapshot of the row — that
        // snapshot duplicated the checkbox and overlapped whatever it was
        // dragged over, reading as two overlapping selection boxes.
        try {
          const ghost = document.createElement('div');
          ghost.className = 'single-drag-ghost';
          const favImg = document.createElement('img');
          favImg.src = favUrl(t.url) || BLANK_FAV;
          ghost.appendChild(favImg);
          const label = document.createElement('span');
          label.textContent = t.title || t.url;
          ghost.appendChild(label);
          document.body.appendChild(ghost);
          ghost.style.position = 'absolute';
          ghost.style.left = '-9999px';
          e.dataTransfer.setDragImage(ghost, 14, 14);
          setTimeout(() => ghost.remove(), 0);
        } catch {}
      }
      e.dataTransfer.effectAllowed = 'copyMove';
      try { e.dataTransfer.setData('text/plain', t.url); } catch {}
    });
    el.addEventListener('dragend', () => {
      document.querySelectorAll('.otab.dragging').forEach(x => x.classList.remove('dragging'));
      document.querySelectorAll('.dragover, .drop-target').forEach(x => { x.classList.remove('dragover'); x.classList.remove('drop-target'); });
      document.querySelectorAll('.drag-ghost').forEach(x => x.remove());
      drag = null;
    });

    $el.appendChild(el);
  });
  applyFilter();
  syncOpenTabRailCaptureControls();
  $el.scrollTop = scrollPos;
  return true;
}
function syncOpenTabRailCaptureControls() {
  const busy = captureCommitPending || saveAllTabsPending;
  const saveAll = document.getElementById('rail-saveall');
  if (saveAll) {
    const canSave = openTabsLoadState === 'ready' && captureEligibleTabs(allOpenTabs).length > 0;
    saveAll.disabled = busy || !canSave;
    saveAll.setAttribute('aria-busy', String(busy));
    const label = saveAll.querySelector('span');
    if (label) {
      const key = busy ? 'rail.saving' : 'rail.saveAll';
      label.dataset.i18n = key;
      label.textContent = tr(key);
    }
  }
  const badge = document.getElementById('selected-badge');
  if (badge) {
    badge.setAttribute('aria-busy', String(busy));
    badge.querySelectorAll('[data-act="save"], [data-act="inbox"]').forEach(button => {
      button.disabled = busy;
    });
  }
  return busy;
}

function updateSelectedBadge() {
  const b = document.getElementById('selected-badge');
  if (!b) return false;
  if (selectedTabIds.size) {
    const count = selectedTabIds.size;
    const saveCount = selectedCaptureTabs().length;
    const saveActions = saveCount ? `
      <button type="button" class="sel-act" data-act="save">
        <svg width="11" height="11" viewBox="0 0 12 12" fill="none"><path d="M2 2h7l2 2v7H2V2z" stroke="currentColor" stroke-width="1.3" stroke-linejoin="round"/></svg>
        <span>${esc(tr('rail.saveSelectedAsGroup', { count: saveCount }))}</span>
      </button>
      <button type="button" class="sel-act" data-act="inbox">
        <svg width="11" height="11" viewBox="0 0 12 12" fill="none"><path d="M6 1v7m0 0l-2-2m2 2l2-2M2 8v2h8V8" stroke="currentColor" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round"/></svg>
        <span>${esc(tr('rail.saveSelectedToInbox', { count: saveCount }))}</span>
      </button>` : '';
    b.innerHTML = `
      <span class="sel-summary">
        <span><strong class="sel-count">${count}</strong> <span class="sel-lbl">${esc(tr('selection.selected'))}</span></span>
        <button type="button" class="sel-clear" data-act="clear" aria-label="${esc(tr('selection.clearTitle'))}">
          <svg width="12" height="12" viewBox="0 0 10 10" aria-hidden="true"><path d="M2 2l6 6M8 2l-6 6" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/></svg>
          <span>${esc(tr('selection.clearTitle'))}</span>
        </button>
      </span>
      <span class="sel-actions">${saveActions}</span>`;
    b.classList.remove('hidden');
    b.querySelectorAll('[data-act]').forEach(btn => {
      btn.onclick = (e) => {
        e.stopPropagation();
        const act = btn.dataset.act;
        if (act === 'save') saveSelectedAsGroup();
        else if (act === 'inbox') saveSelectedToInbox();
        else if (act === 'clear') { selectedTabIds.clear(); lastClickedTabId = null; updateSelectedBadge(); renderOpenTabs(); }
      };
    });
  } else {
    b.classList.add('hidden');
    b.replaceChildren();
  }
  syncOpenTabRailCaptureControls();
  return true;
}

function captureEligibleTabs(tabs) {
  return Array.from(tabs || []).filter(tab => isOpenableSavedTabUrl(tab?.url));
}

function selectedCaptureTabs() {
  return captureEligibleTabs(allOpenTabs.filter(tab => selectedTabIds.has(tab.id)));
}

function clearCapturedTabSelection(tabs) {
  for (const tab of tabs || []) selectedTabIds.delete(tab?.id ?? tab?.tabId);
  if (!selectedTabIds.size) lastClickedTabId = null;
}

async function saveSelectedToInbox() {
  const tabs = selectedCaptureTabs();
  if (!tabs.length) return;
  const ws = activeWs();
  const cat = activeCat();
  if (!ws || !cat) return false;
  const destination = createInboxCaptureContext(ws, cat);
  if (!destination) return reportInboxCaptureUnavailable();
  const actionId = State.snapshot(tr(
    tabs.length === 1 ? 'capture.snapshotInboxTab' : 'capture.snapshotInboxTabs',
    { count: tabs.length },
  ));
  const target = materializeInboxCaptureTarget(destination);
  if (!target) {
    State.rollbackSnapshot(actionId);
    return reportInboxCaptureUnavailable();
  }
  const inbox = target.inbox;
  let added = 0;
  const savedTabs = [];
  const savedItems = [];
  try {
    const allocateId = createOrganizationIdAllocator();
    for (const t of tabs) {
      if (captureDuplicateExists(inbox, t.url)) continue;
      const meta = captureTabFields(t);
      const item = stampNew({ id: allocateId(), type:'tab', title: meta.title, url: t.url, fav: meta.fav });
      inbox.items.push(item);
      savedItems.push(item);
      added++;
      savedTabs.push(t);
    }
  } catch {
    State.rollbackSnapshot(actionId);
    renderAll();
    return reportInboxCaptureUnavailable();
  }
  if (!added) {
    State.rollbackSnapshot(actionId);
    toast(tr('capture.alreadySaved'), { danger: true });
    return;
  }
  const closeSources = State.get().settings.closeTabOnSave;
  const listContext = createItemListCaptureContext(inbox.items);
  const receiptContext = createCaptureDestinationReceiptContext(listContext, savedItems);
  const receiptMessage = inboxCaptureReceiptMessage(target, { count: added, closeSources: !!closeSources });
  if (!receiptContext || !receiptMessage) {
    State.rollbackSnapshot(actionId);
    renderAll();
    return reportInboxCaptureUnavailable();
  }
  const result = await commitCapturedTabs(savedTabs, {
    actionId,
    closeSources,
    validateDestination: () => !!resolveCaptureDestinationReceiptTarget(receiptContext),
  });
  if (!result) return;
  clearCapturedTabSelection(tabs);
  renderBoard();
  renderOpenTabs();
  updateSelectedBadge();
  restoreOpenTabCaptureFocus();
  toastCaptureDestinationReceipt(receiptContext, receiptMessage, result);
}

let captureCommitPending = false;
let saveAllTabsPending = false;

function capturedTabSourceDescriptor(tab) {
  const tabId = tab?.tabId ?? tab?.id;
  const windowId = tab?.windowId;
  const expectedUrl = tab?.expectedUrl ?? tab?.url;
  const sourceWasActive = tab?.sourceWasActive ?? tab?.active;
  if (!Number.isInteger(tabId) || tabId < 0
    || !Number.isInteger(windowId) || windowId < 0
    || typeof expectedUrl !== 'string' || !expectedUrl
    || typeof sourceWasActive !== 'boolean') return null;
  const fav = tab?.fav ?? tab?.favIconUrl;
  return Object.freeze({
    tabId,
    windowId,
    expectedUrl,
    sourceWasActive,
    title: typeof tab?.title === 'string' ? tab.title : '',
    url: expectedUrl,
    fav: typeof fav === 'string' ? fav : '',
    pinned: tab?.pinned === true,
  });
}

async function refreshCapturedTabSourceDescriptors(descriptors) {
  const refreshed = [];
  for (const value of descriptors || []) {
    const expected = capturedTabSourceDescriptor(value);
    if (!expected) { refreshed.push(null); continue; }
    try {
      const current = await chrome.tabs.get(expected.tabId);
      const currentDescriptor = capturedTabSourceDescriptor(current);
      const pendingMatches = current?.pendingUrl == null
        || (typeof current.pendingUrl === 'string'
          && current.pendingUrl === expected.expectedUrl);
      refreshed.push(currentDescriptor
        && currentDescriptor.tabId === expected.tabId
        && currentDescriptor.windowId === expected.windowId
        && currentDescriptor.expectedUrl === expected.expectedUrl
        // The rail contains only this Locus window. A dragged source cannot be
        // active while the user is dropping from the active new-tab page; treat
        // activation before this read settles as protection, not new authority.
        && currentDescriptor.sourceWasActive === false
        && pendingMatches
        ? currentDescriptor
        : null);
    } catch {
      refreshed.push(null);
    }
  }
  return refreshed;
}

function capturedTabStillMatches(expected, current) {
  const descriptor = capturedTabSourceDescriptor(expected);
  if (!descriptor || !current
    || current.id !== descriptor.tabId
    || current.windowId !== descriptor.windowId
    || typeof current.active !== 'boolean'
    || (!descriptor.sourceWasActive && current.active)
    || current.url !== descriptor.expectedUrl) return false;
  if (current.pendingUrl == null) return true;
  return typeof current.pendingUrl === 'string'
    && current.pendingUrl === descriptor.expectedUrl;
}

async function commitCapturedTabs(tabsToClose = [], options = {}) {
  const actionId = options.actionId ?? State.latestActionId();
  const requestedTabs = Array.from(tabsToClose || []);
  const closeSources = options.closeSources ?? State.get().settings.closeTabOnSave;
  // Browser effects use an immutable copy of the identity the user reviewed.
  // Missing identity can still leave an accepted saved copy, but can never
  // authorize closing a live source tab.
  let closeCandidates = closeSources
    ? requestedTabs.map(tab => capturedTabSourceDescriptor(tab))
    : [];
  const destinationStillMatches = () => {
    if (typeof options.validateDestination !== 'function') return true;
    try { return options.validateDestination() === true; } catch { return false; }
  };
  if (captureCommitPending) {
    State.rollbackSnapshot(actionId);
    renderAll();
    toast(tr('capture.pending'), { danger: true, duration: 5000 });
    return false;
  }
  captureCommitPending = true;
  syncOpenTabRailCaptureControls();
  if (!State.beginCaptureAction(actionId)) {
    captureCommitPending = false;
    syncOpenTabRailCaptureControls();
    toast(tr('capture.startFailed'), { danger: true, duration: 5000 });
    return false;
  }
  try {
    const capturePreparationDataToken = State.dataMutationToken();
    if (closeSources && options.refreshSources === true) {
      // Drag rows come from an asynchronously refreshed rail cache. Re-read each
      // exact source before persistence so original active state cannot be stale,
      // then retain the separate post-receipt read before any removal.
      closeCandidates = await refreshCapturedTabSourceDescriptors(closeCandidates);
    }
    const laterEditDuringPreparation = State.dataMutationToken() !== capturePreparationDataToken;
    let destinationChanged = !destinationStillMatches();
    if (laterEditDuringPreparation || destinationChanged) {
      // The combined write may legitimately keep the later graph, but that graph
      // is no longer proof that every optimistic saved copy still exists at its
      // reviewed destination. Persist it, then protect every source from cleanup.
      closeCandidates = closeCandidates.map(() => null);
    }
    let captureWriteDataToken = State.dataMutationToken();
    try {
      // A captured tab is not considered saved until chrome.storage confirms the
      // write. Closing first can destroy the only recoverable copy on quota or
      // extension-shutdown failures.
      const persistence = State.persistNow();
      captureWriteDataToken = State.dataMutationToken();
      await persistence;
    } catch (error) {
      let recovered = false;
      let acceptedWithoutReceipt = false;
      let laterEditsRemain = laterEditDuringPreparation
        || State.dataMutationToken() !== captureWriteDataToken;
      if (laterEditsRemain) {
        showStateRecoveryRequired(new Error('Save was not confirmed. Your tabs stayed open and later edits remain visible. Reload the latest saved data before continuing.'));
      } else {
        try {
          await restoreAuthoritativeState({ expectedDataMutationToken: captureWriteDataToken });
          recovered = true;
          acceptedWithoutReceipt = State.matchesUnconfirmedWrite(error);
        } catch (recoveryError) {
          if (recoveryError?.code === 'LOCUS_STATE_RECOVERY_INTERRUPTED') {
            laterEditsRemain = true;
            showStateRecoveryRequired(recoveryError);
          } else {
            // Display-only fallback. Further persistence remains blocked, so even
            // an interleaved newer action cannot overwrite authoritative storage.
            State.rollbackSnapshot(actionId);
            renderAll();
            showStateRecoveryRequired(recoveryError);
          }
        }
      }
      toast(laterEditsRemain
        ? tr('capture.unconfirmedLater')
        : acceptedWithoutReceipt
        ? tr('capture.receiptLost')
        : recovered
        ? tr('capture.restored')
        : tr('capture.failed'),
      { danger: true, duration: 8000 });
      return false;
    }
    if (!destinationStillMatches()) {
      destinationChanged = true;
      closeCandidates = closeCandidates.map(() => null);
    }
    const closedTabs = [];
    const failedTabs = [];
    if (closeSources) {
      for (let index = 0; index < requestedTabs.length; index++) {
        if (!destinationStillMatches()) {
          destinationChanged = true;
          failedTabs.push(...requestedTabs.slice(index));
          break;
        }
        const tab = closeCandidates[index];
        if (State.isRecoveryRequired()) {
          failedTabs.push(...requestedTabs.slice(index));
          break;
        }
        const tabId = tab?.tabId;
        if (tabId == null) { failedTabs.push(tab); continue; }
        try {
          // The saved URL and the browser tab ID are reviewed together. A tab
          // can navigate while storage is confirming the save; closing that new
          // page would be a different, unapproved effect. Re-read immediately
          // before removal and fail open when identity changed.
          const currentTab = await chrome.tabs.get(tabId);
          if (!destinationStillMatches()) {
            destinationChanged = true;
            failedTabs.push(...requestedTabs.slice(index));
            break;
          }
          if (!capturedTabStillMatches(tab, currentTab)) {
            failedTabs.push(tab);
            continue;
          }
          await chrome.tabs.remove(tabId);
          closedTabs.push(tab);
        } catch { failedTabs.push(tab); }
      }
    }
    // Register browser-side effects before the pending flag is cleared. There
    // must be no event-loop turn in which Undo can pop this capture without the
    // information needed to restore its source tabs.
    State.registerClosedTabs(actionId, closedTabs);
    return {
      actionId,
      closeSources,
      requestedCloseCount: closeSources ? requestedTabs.length : 0,
      closedCount: closedTabs.length,
      failedCloseCount: failedTabs.length,
      destinationChanged,
    };
  } finally {
    State.finishCaptureAction(actionId);
    captureCommitPending = false;
    syncOpenTabRailCaptureControls();
  }
}

function captureResultMessage(base, result) {
  const requested = Number(result?.requestedCloseCount) || 0;
  if (!result?.closeSources || !requested) return base;
  const closed = Number(result.closedCount) || 0;
  if (closed === requested) {
    return tr(requested === 1 ? 'capture.closedOne' : 'capture.closedMany', { base, count: closed });
  }
  if (!closed) return tr(requested === 1 ? 'capture.stayedOpenOne' : 'capture.stayedOpenMany', { base });
  return tr('capture.closedPartial', { base, closed, requested });
}

function toastCaptureResult(base, result) {
  const partialClose = Number(result?.failedCloseCount) > 0;
  toast(captureResultMessage(base, result), {
    undo: result?.actionId,
    duration: partialClose ? 6000 : 3000,
  });
}

function captureReceiptPresentation(context, closeSources) {
  const title = String(context?.itemRef?.title || context?.itemRef?.url || tr('itemAction.untitled')).trim()
    || tr('itemAction.untitled');
  const destinationParts = homeTrailPathParts(
    context?.workspaceRef,
    context?.spaceRef,
    homeTrailGroupName(context?.groupRef),
  );
  if (destinationParts.length !== 3) return null;
  return {
    message: tr(closeSources ? 'capture.receiptSaved' : 'capture.receiptSavedCopy', {
      title,
      destination: homeTrailPathText(destinationParts),
    }),
    actionLabel: tr('capture.showSavedItem'),
  };
}

function openCapturedItemReceipt(context) {
  let target = null;
  try { target = resolveSavedItemRecoveryTarget(context); } catch {}
  if (!target || target.item?.type !== 'tab' || !target.ws?.id || !target.group?.id || !target.item?.id) {
    toast(tr('capture.receiptUnavailable'), { danger: true, duration: 5000 });
    return false;
  }
  const opener = document.getElementById('nav-inbox') || document.getElementById('topbar-save');
  focusDialogOpener(opener);
  prepareItemDetailOpen(target.item.id);
  let navigated = false;
  try {
    navigated = Router.navigate({
      type: 'group',
      wsId: target.ws.id,
      groupId: target.group.id,
      itemId: target.item.id,
      query: {},
    }, { persist: false });
  } catch {}
  if (!navigated) {
    cancelSearchItemDetailPreparation(target.item.id);
    toast(tr('capture.receiptUnavailable'), { danger: true, duration: 5000 });
    return false;
  }
  return true;
}

function toastCapturedItemReceipt(context, result) {
  let target = null;
  try { target = resolveSavedItemRecoveryTarget(context); } catch {}
  if (!target) {
    toast(captureResultMessage(tr('capture.destinationChangedAfterSave'), result), {
      undo: result?.actionId,
      tone: 'warning',
      duration: 8000,
    });
    return false;
  }
  let presentation = null;
  try { presentation = captureReceiptPresentation(context, !!result?.closeSources); } catch {}
  if (!presentation) {
    toastCaptureResult(tr(result?.closeSources ? 'capture.savedInbox' : 'capture.savedCopyInbox'), result);
    return false;
  }
  toast(captureResultMessage(presentation.message, result), {
    undo: result?.actionId,
    duration: 8000,
    actionLabel: presentation.actionLabel,
    action: () => openCapturedItemReceipt(context),
  });
  return true;
}
function applyFilter() {
  const filter = document.getElementById('tab-filter');
  const list = document.getElementById('open-tabs');
  if (!filter || !list) return 0;
  const q = filter.value.toLowerCase().trim();
  list.querySelector('.otab-filter-state')?.remove();
  if (openTabsLoadState !== 'ready') return 0;
  // Build id→tab map once instead of O(n²) find() per row.
  const byId = new Map();
  for (const t of allOpenTabs) byId.set(String(t.id), t);
  let matchCount = 0;
  document.querySelectorAll('#open-tabs .otab').forEach(el => {
    const t = byId.get(el.dataset.tid);
    if (!t) return;
    const match = !q || (t.title||'').toLowerCase().includes(q) || (t.url||'').toLowerCase().includes(q);
    el.classList.toggle('hidden', !match);
    if (match) matchCount += 1;
  });
  if (q && matchCount === 0 && allOpenTabs.length) {
    const state = document.createElement('div');
    state.className = 'otab-state otab-filter-state is-no-match';
    state.setAttribute('role', 'status');
    state.setAttribute('aria-live', 'polite');
    state.innerHTML = `
      <span class="otab-state-mark" aria-hidden="true"></span>
      <strong>${esc(tr('rail.noMatch'))}</strong>
      <p>${esc(tr('rail.noMatchBody'))}</p>
      <button type="button" class="otab-state-action">${esc(tr('rail.clearFilter'))}</button>`;
    state.querySelector('.otab-state-action').addEventListener('click', () => {
      filter.value = '';
      applyFilter();
      filter.focus({ preventScroll: true });
    });
    list.appendChild(state);
  }
  return matchCount;
}

function isOpenTabsRailAvailable() {
  const rail = document.getElementById('tabrail');
  if (!rail || window.innerWidth <= 820) return false;
  return getComputedStyle(rail).display !== 'none';
}

function isOpenTabsRailDrawerOpen() {
  const rail = document.getElementById('tabrail');
  return isOpenTabsRailAvailable()
    && window.innerWidth <= 1280
    && !rail.classList.contains('collapsed');
}

function setOpenTabsRailCollapsed(collapsed, options = {}) {
  const rail = document.getElementById('tabrail');
  const toggle = document.getElementById('tabrail-toggle');
  if (!rail || !toggle) return false;
  const next = !!collapsed;
  const settings = State.get().settings;
  const changed = !!settings.railCollapsed !== next || rail.classList.contains('collapsed') !== next;
  settings.railCollapsed = next;
  if (changed) applySettings();
  else updateRailToggleLabel();
  if (changed && options.persist !== false) State.persist();
  if (options.restoreFocus) {
    requestAnimationFrame(() => focusDialogOpener(toggle));
  }
  return true;
}

function focusOpenTabFilter() {
  if (!isOpenTabsRailAvailable()) return false;
  // Item details is the one floating layer; S stays off while it is open.
  if (document.getElementById('item-detail')?.classList.contains('open')) return false;
  const rail = document.getElementById('tabrail');
  // Today keeps the rail behind its edge tab: S opens that drawer instead of
  // changing the saved collapsed preference.
  if (typeof todayTabsDrawerAvailable === 'function' && todayTabsDrawerAvailable()) {
    setTodayTabsDrawer(true, { opener: document.activeElement });
    focusTodayTabsDrawerTarget('tab-filter');
    return true;
  }
  if (rail.classList.contains('collapsed')) {
    setOpenTabsRailCollapsed(false, { persist: true });
  }
  requestAnimationFrame(() => {
    const filter = document.getElementById('tab-filter');
    if (filter && isOpenTabsRailAvailable()) filter.focus({ preventScroll: true });
  });
  return true;
}

function handleOpenTabsEscape(event) {
  if (event?.key !== 'Escape' || !isOpenTabsRailAvailable()) return false;
  const rail = document.getElementById('tabrail');
  const filter = document.getElementById('tab-filter');
  const todayDrawer = typeof isTodayTabsDrawerOpen === 'function' && isTodayTabsDrawerOpen();
  if (!rail.contains(document.activeElement) && !todayDrawer) return false;
  if (document.activeElement === filter && filter.value) {
    event.preventDefault();
    filter.value = '';
    applyFilter();
    return true;
  }
  if (selectedTabIds.size) {
    event.preventDefault();
    const focusId = lastClickedTabId ?? selectedTabIds.values().next().value;
    selectedTabIds.clear();
    lastClickedTabId = null;
    updateSelectedBadge();
    renderOpenTabs();
    if (focusId != null) restoreOpenTabSelectionFocus(focusId);
    return true;
  }
  if (todayDrawer) {
    event.preventDefault();
    setTodayTabsDrawer(false, { restoreFocus: true });
    return true;
  }
  if (isOpenTabsRailDrawerOpen()) {
    event.preventDefault();
    setOpenTabsRailCollapsed(true, { persist: true, restoreFocus: true });
    return true;
  }
  return false;
}

async function saveTabToInbox(t, options = {}) {
  if (!isOpenableSavedTabUrl(t?.url)) return false;
  const ws = activeWs();
  const cat = activeCat();
  if (!ws || !cat) return false;
  const destination = createInboxCaptureContext(ws, cat);
  if (!destination) return reportInboxCaptureUnavailable();
  const actionId = State.snapshot(tr('capture.snapshotInbox'));
  const target = materializeInboxCaptureTarget(destination);
  if (!target) {
    State.rollbackSnapshot(actionId);
    return reportInboxCaptureUnavailable();
  }
  const inbox = target.inbox;
  if (captureDuplicateExists(inbox, t.url)) { State.rollbackSnapshot(actionId); toast(tr('capture.alreadySaved'), { danger: true }); return false; }
  let savedItem;
  try {
    const allocateId = createOrganizationIdAllocator();
    const meta = captureTabFields(t);
    savedItem = stampNew({ id: allocateId(), type:'tab', title: meta.title, url: t.url, fav: meta.fav });
  } catch {
    State.rollbackSnapshot(actionId);
    renderAll();
    return reportInboxCaptureUnavailable();
  }
  inbox.items.push(savedItem);
  const closeSources = options.closeSource ?? State.get().settings.closeTabOnSave;
  const listContext = createItemListCaptureContext(inbox.items);
  const destinationReceiptContext = createCaptureDestinationReceiptContext(listContext, [savedItem]);
  const receiptMessage = inboxCaptureReceiptMessage(target, { item: savedItem, closeSources: !!closeSources });
  let itemReceiptContext = null;
  if (options.receipt === true) {
    try {
      itemReceiptContext = createSavedItemRecoveryContext({ ws, cat, group: inbox, parents: [], item: savedItem });
    } catch {}
  }
  if (!destinationReceiptContext || !receiptMessage || (options.receipt === true && !itemReceiptContext)) {
    State.rollbackSnapshot(actionId);
    renderAll();
    return reportInboxCaptureUnavailable();
  }
  const result = await commitCapturedTabs([t], {
    closeSources,
    actionId,
    validateDestination: () => !!resolveCaptureDestinationReceiptTarget(destinationReceiptContext),
  });
  if (!result) return false;
  renderBoard();
  let destinationConfirmed = false;
  try {
    destinationConfirmed = result.destinationChanged !== true
      && !!resolveCaptureDestinationReceiptTarget(destinationReceiptContext);
  } catch {}
  if (!destinationConfirmed) {
    toast(captureResultMessage(tr('capture.destinationChangedAfterSave'), result), {
      undo: result.actionId,
      tone: 'warning',
      duration: 8000,
    });
  }
  else if (itemReceiptContext) toastCapturedItemReceipt(itemReceiptContext, result);
  else if (options.destinationReceipt === true) {
    toastCaptureDestinationReceipt(destinationReceiptContext, receiptMessage, result);
  }
  else toastCaptureResult(
    receiptMessage || tr(closeSources ? 'capture.savedInbox' : 'capture.savedCopyInbox'),
    result,
  );
  return options.returnOutcome === true
    ? Object.freeze({ accepted: true, item: savedItem, destinationConfirmed })
    : savedItem;
}
async function saveSelectedAsGroup() {
  const tabs = selectedCaptureTabs();
  if (!tabs.length || State.isRecoveryRequired()) return false;
  if (captureCommitPending || saveAllTabsPending) {
    toast(tr('capture.pending'), { danger: true, duration: 5000 });
    return false;
  }
  const sourceTabs = tabs.map(capturedTabSourceDescriptor);
  if (sourceTabs.some(tab => !tab)) return false;
  const destination = createGeneratedGroupCaptureContext();
  const target = resolveGeneratedGroupCaptureTarget(destination);
  if (!target) return reportGeneratedGroupCaptureUnavailable();
  let group;
  try {
    const allocateId = createOrganizationIdAllocator();
    const date = new Date().toLocaleDateString(appLocale(), { month: 'short', day: 'numeric' });
    group = {
      id: allocateId(),
      symbol: '📂',
      color: '#6366f1',
      collapsed: false,
      name: tr('capture.selectedGroupName', { count: sourceTabs.length, date }),
      items: sourceTabs.map(tab => {
        const meta = captureTabFields(tab);
        return stampNew({ id: allocateId(), type: 'tab', title: meta.title, url: tab.url, fav: meta.fav });
      }),
    };
  } catch {
    return reportGeneratedGroupCaptureUnavailable();
  }
  const closeSources = State.get().settings.closeTabOnSave;
  const actionId = State.snapshot(tr('capture.snapshotSelectionGroup', { count: sourceTabs.length }));
  target.space.groups.push(group);
  const listContext = createItemListCaptureContext(group.items);
  const receiptContext = createCaptureDestinationReceiptContext(listContext, group.items);
  const receiptTarget = resolveItemListCaptureTarget(listContext);
  const receiptMessage = captureDestinationReceiptMessage(receiptTarget, {
    count: sourceTabs.length,
    closeSources: !!closeSources,
  });
  if (!receiptContext || !receiptMessage) {
    State.rollbackSnapshot(actionId);
    renderAll();
    return reportGeneratedGroupCaptureUnavailable();
  }
  const result = await commitCapturedTabs(sourceTabs, {
    actionId,
    closeSources,
    refreshSources: true,
    validateDestination: () => !!resolveCaptureDestinationReceiptTarget(receiptContext),
  });
  if (!result) return false;
  clearCapturedTabSelection(tabs);
  renderBoard();
  renderOpenTabs();
  updateSelectedBadge();
  restoreOpenTabCaptureFocus();
  toastCaptureDestinationReceipt(receiptContext, receiptMessage, result);
  return group;
}

async function addSidebarOrActiveTabToGroup(g) {
  if (State.isRecoveryRequired()) return false;
  if (captureCommitPending || saveAllTabsPending) {
    toast(tr('capture.pending'), { danger: true, duration: 5000 });
    return false;
  }
  const selectionRequested = selectedTabIds.size > 0;
  const selectedTabs = selectedCaptureTabs();
  if (selectionRequested && !selectedTabs.length) return;
  const destination = createGroupCaptureContext(g);
  if (!destination) return reportGroupCaptureUnavailable();
  if (selectedTabs.length) {
    const target = resolveGroupCaptureTarget(destination);
    if (!target) return reportGroupCaptureUnavailable();
    const addedTabs = selectedTabs.filter(createCaptureBatchDuplicateFilter(target.group));
    if (!addedTabs.length) return toast(tr('capture.alreadySaved'), { danger: true });
    let savedItems;
    try {
      const allocateId = createOrganizationIdAllocator();
      savedItems = addedTabs.map(t => {
        const meta = captureTabFields(t);
        return stampNew({ id: allocateId(), type:'tab', title:meta.title, url:t.url, fav:meta.fav });
      });
    } catch {
      return reportGroupCaptureUnavailable();
    }
    const actionId = State.snapshot(tr(
      addedTabs.length === 1 ? 'capture.snapshotGroupTab' : 'capture.snapshotGroupTabs',
      { count: addedTabs.length },
    ));
    target.group.items.push(...savedItems);
    const closeSources = State.get().settings.closeTabOnSave;
    const listContext = createItemListCaptureContext(target.group.items);
    const receiptContext = createCaptureDestinationReceiptContext(listContext, savedItems);
    const receiptTarget = resolveItemListCaptureTarget(listContext);
    const receiptMessage = captureDestinationReceiptMessage(receiptTarget, {
      count: addedTabs.length,
      closeSources: !!closeSources,
    });
    if (!receiptContext || !receiptMessage) {
      State.rollbackSnapshot(actionId);
      renderAll();
      return reportGroupCaptureUnavailable();
    }
    const result = await commitCapturedTabs(addedTabs, {
      actionId,
      closeSources,
      validateDestination: () => !!resolveCaptureDestinationReceiptTarget(receiptContext),
    });
    if (!result) return;
    clearCapturedTabSelection(selectedTabs);
    renderBoard();
    renderOpenTabs();
    updateSelectedBadge();
    restoreOpenTabCaptureFocus();
    toastCaptureDestinationReceipt(receiptContext, receiptMessage, result);
    return;
  }

  let currentWindowTabs;
  try {
    currentWindowTabs = await chrome.tabs.query({ currentWindow: true });
  } catch {
    toast(tr('capture.tabReadFailed'), { danger: true, duration: 5000 });
    return false;
  }
  const newestEligible = recentSaveCandidate(currentWindowTabs);
  if (!newestEligible) {
    toast(tr('capture.selectTabToAdd'));
    return;
  }
  const target = resolveGroupCaptureTarget(destination);
  if (!target) return reportGroupCaptureUnavailable();
  const t = recentSaveCandidate(Array.from(currentWindowTabs || [])
    .filter(tab => !captureDuplicateExists(target.group, tab?.url)));
  if (!t) return toast(tr('capture.alreadySaved'));
  let savedItem;
  try {
    const allocateId = createOrganizationIdAllocator();
    const meta = captureTabFields(t);
    savedItem = stampNew({ id: allocateId(), type:'tab', title:meta.title, url:t.url, fav:meta.fav });
  } catch {
    return reportGroupCaptureUnavailable();
  }
  const actionId = State.snapshot(tr('capture.snapshotGroupTab'));
  target.group.items.push(savedItem);
  const closeSources = State.get().settings.closeTabOnSave;
  const listContext = createItemListCaptureContext(target.group.items);
  const receiptContext = createCaptureDestinationReceiptContext(listContext, [savedItem]);
  const receiptTarget = resolveItemListCaptureTarget(listContext);
  const receiptMessage = captureDestinationReceiptMessage(receiptTarget, {
    count: 1,
    closeSources: !!closeSources,
  });
  if (!receiptContext || !receiptMessage) {
    State.rollbackSnapshot(actionId);
    renderAll();
    return reportGroupCaptureUnavailable();
  }
  const result = await commitCapturedTabs([t], {
    actionId,
    closeSources,
    validateDestination: () => !!resolveCaptureDestinationReceiptTarget(receiptContext),
  });
  if (!result) return;
  renderBoard();
  toastCaptureDestinationReceipt(receiptContext, receiptMessage, result);
}

async function saveAllTabs() {
  if (State.isRecoveryRequired()) return false;
  if (saveAllTabsPending || captureCommitPending) {
    toast(tr('capture.pending'), { danger: true, duration: 5000 });
    return false;
  }
  const destination = createGeneratedGroupCaptureContext();
  if (!destination) return reportGeneratedGroupCaptureUnavailable();
  saveAllTabsPending = true;
  syncOpenTabRailCaptureControls();
  try {
    let tabs;
    try {
      tabs = await chrome.tabs.query({ currentWindow: true });
    } catch {
      toast(tr('capture.windowReadFailed'), { danger: true, duration: 5000 });
      return false;
    }
    if (State.isRecoveryRequired()) return false;
    if (captureCommitPending) {
      toast(tr('capture.pending'), { danger: true, duration: 5000 });
      return false;
    }
    const valid = (tabs || []).filter(tab => isOpenableSavedTabUrl(tab?.url));
    if (!valid.length) {
      toast(tr('capture.noWindowTabs'));
      return false;
    }
    const target = resolveGeneratedGroupCaptureTarget(destination);
    if (!target) return reportGeneratedGroupCaptureUnavailable();

    let group;
    try {
      const allocateId = createOrganizationIdAllocator();
      group = {
        id: allocateId(),
        symbol: '💾',
        color: '#06b6d4',
        collapsed: false,
        name: generatedCaptureGroupName(),
        items: valid.map(tab => {
          const meta = captureTabFields(tab);
          return stampNew({
            id: allocateId(),
            type: 'tab',
            title: meta.title,
            url: tab.url,
            fav: meta.fav,
          });
        }),
      };
    } catch {
      return reportGeneratedGroupCaptureUnavailable();
    }

    const closeSources = State.get().settings.closeTabOnSave;
    const actionId = State.snapshot(tr('capture.snapshotWindow', { count: valid.length }));
    target.space.groups.push(group);
    const listContext = createItemListCaptureContext(group.items);
    const receiptContext = createCaptureDestinationReceiptContext(listContext, group.items);
    const receiptTarget = resolveItemListCaptureTarget(listContext);
    const receiptMessage = captureDestinationReceiptMessage(receiptTarget, {
      count: valid.length,
      closeSources: !!closeSources,
    });
    if (!receiptContext || !receiptMessage) {
      State.rollbackSnapshot(actionId);
      renderAll();
      return reportGeneratedGroupCaptureUnavailable();
    }
    const result = await commitCapturedTabs(valid, {
      actionId,
      closeSources,
      validateDestination: () => !!resolveCaptureDestinationReceiptTarget(receiptContext),
    });
    if (!result) return false;
    renderBoard();
    toastCaptureDestinationReceipt(receiptContext, receiptMessage, result);
    return true;
  } finally {
    saveAllTabsPending = false;
    syncOpenTabRailCaptureControls();
  }
}

// ════════════════════════════════════════════════════════════════
// RENDER (diff-based for items)
// ════════════════════════════════════════════════════════════════
function renderAll() {
  const headerReady = renderHeader();
  renderWsList();
  renderCategoryTabs();
  renderBoard();
  renderItemDetail();
  Router.sync();
  return headerReady;
}

function topbarContextPresentation({
  surface = 'board',
  workspace = null,
  space = null,
  group = null,
  libraryMode = null,
} = {}) {
  const libraryKeys = {
    all: 'nav.allLinks',
    favorites: 'nav.favorites',
    'read-later': 'nav.readLater',
    archive: 'nav.archive',
    trash: 'nav.trash',
  };
  const librarySymbols = {
    all: '🔗',
    favorites: '★',
    'read-later': '🔖',
    archive: '🗄',
    trash: '🗑',
  };
  if (surface === 'home') return { label: tr('nav.home'), symbol: '🏠' };
  if (surface === 'search') return { label: tr('search.title'), symbol: '⌕' };
  if (surface === 'calendar') return { label: tr('cal.title'), symbol: '📅' };
  if (surface === 'plan') return { label: tr('nav.plan'), symbol: '📅' };
  if (surface === 'library') {
    const mode = libraryKeys[libraryMode] ? libraryMode : 'all';
    return { label: tr(libraryKeys[mode]), symbol: librarySymbols[mode] };
  }
  if (surface === 'group' && group) {
    const label = group.name === 'Inbox' ? tr('nav.inbox') : String(group.name || '').trim();
    if (label) return { label, symbol: String(group.symbol || '📁') };
  }
  const spaceLabel = String(space?.name || '').trim();
  if (spaceLabel) return { label: spaceLabel, symbol: String(space?.symbol || '🗂') };
  const workspaceLabel = String(workspace?.name || '').trim();
  if (workspaceLabel) return { label: workspaceLabel, symbol: String(workspace?.symbol || '🏠') };
  return { label: 'Locus', symbol: '⌂' };
}

function renderTopbarContext() {
  const workspace = activeWs();
  const space = activeCat();
  const group = activeGroupPage ? findGroup(activeGroupPage.groupId)?.group || null : null;
  const surface = activeSearch
    ? 'search'
    : activeCalendar
      ? (typeof PLAN_VIEWS !== 'undefined' && PLAN_VIEWS.includes(activeCalendar.view) ? 'plan' : 'calendar')
      : activeGroupPage
        ? 'group'
        : activeLibraryMode
          ? 'library'
          : activeHome
            ? 'home'
            : 'board';
  const presentation = topbarContextPresentation({
    surface,
    workspace,
    space,
    group,
    libraryMode: activeLibraryMode,
  });
  const title = document.getElementById('ws-title');
  const symbol = document.getElementById('ws-title-sym');
  const name = document.getElementById('ws-title-name');
  if (!title || !symbol || !name) return false;
  symbol.textContent = presentation.symbol;
  name.textContent = presentation.label;
  const workspaceLabel = String(workspace?.name || '').trim();
  title.title = [workspaceLabel, presentation.label]
    .filter((value, index, values) => value && values.indexOf(value) === index)
    .join(' › ');
  return true;
}

async function renderHeader() {
  const ws = activeWs(); if (!ws) return;
  renderTopbarContext();
  const undoBtn = document.getElementById('undo-btn');
  if (undoBtn) undoBtn.classList.toggle('disabled', !State.canUndo());
  await renderWsChips();
}

// ─── Workspace chips (one per open browser window) ───
async function renderWsChips() {
  const $stack = document.getElementById('ws-chips-stack');
  if (!$stack) return;
  const s = State.get();

  let windows = [];
  try { windows = await chrome.windows.getAll({ populate: false }); } catch {}

  if (s.settings.windowSync !== false) {
    for (const w of windows) {
      const boundWs = s.workspaces.find(ws => ws.windowId === w.id);
      if (!boundWs) {
        const orphan = s.workspaces.find(ws => !ws.windowId);
        if (orphan && !s.workspaces.some(x => x.windowId === w.id)) orphan.windowId = w.id;
      }
    }
    const openIds = new Set(windows.map(w => w.id));
    s.workspaces.forEach(ws => { if (ws.windowId && !openIds.has(ws.windowId)) delete ws.windowId; });
    try {
      const cur = await chrome.windows.getCurrent();
      if (s.settings.autoSwitchWorkspace) {
        const match = s.workspaces.find(ws => ws.windowId === cur.id);
        if (match && match.id !== s.activeWsId) s.activeWsId = match.id;
      }
    } catch {}
  }

  $stack.innerHTML = '';
  const liveWorkspaces = s.workspaces.filter(ws => ws.windowId && windows.some(w => w.id === ws.windowId));
  liveWorkspaces.forEach(ws => $stack.appendChild(buildWsChip(ws, { live: true })));

  // If the active workspace is NOT bound to any window (saved/dormant), show it as active chip too
  const activeW = activeWs();
  if (activeW && !liveWorkspaces.some(x => x.id === activeW.id)) {
    $stack.appendChild(buildWsChip(activeW, { live: false }));
  }

  const otherCount = s.workspaces.length - liveWorkspaces.length - (activeW && !liveWorkspaces.some(x => x.id === activeW.id) ? 1 : 0);
  if (otherCount > 0) {
    const more = document.createElement('button');
    more.className = 'ws-chip ws-chip-more';
    more.title = `${otherCount} saved workspace${otherCount > 1 ? 's' : ''}`;
    more.innerHTML = `<span>+${otherCount}</span>`;
    more.onclick = event => openWsGrid(event.currentTarget);
    $stack.appendChild(more);
  }
}

function buildWsChip(ws, { live }) {
  const chip = document.createElement('button');
  chip.className = 'ws-chip' + (ws.id === State.get().activeWsId ? ' active' : '') + (live ? ' live' : '');
  chip.dataset.wsid = ws.id;
  chip.title = ws.name + (live ? ' · live window' : '');
  chip.innerHTML = `
    <span class="ws-chip-sym">${esc(ws.symbol || '🏠')}</span>
    <span class="ws-chip-name">${esc(ws.name)}</span>
    ${live ? '<span class="ws-chip-live-dot"></span>' : ''}`;
  chip.onclick = async () => {
    State.get().activeWsId = ws.id;
    State.persist();
    renderAll();
    if (ws.windowId) { try { await chrome.windows.update(ws.windowId, { focused: true }); } catch {} }
  };
  const workspaceMenuItems = () => {
    const items = [
      { text: tr('organization.renameMenu'), icon: cmIcons.edit, action: () => openOrganizationName('workspace', ws.id, chip) },
      { text: tr('organization.changeSymbol'), icon: cmIcons.symbol, action: () => openEmojiPicker({ kind:'workspace', id: ws.id }, chip) },
      { sep: true }
    ];
    if (ws.windowId) items.push({ text:'Unbind from window', icon: cmIcons.move, action: () => { State.snapshot('Unbind'); delete ws.windowId; State.persist(); renderAll(); } });
    if (State.get().workspaces.length > 1) items.push({ text: tr('organization.workspace.delete'), icon: cmIcons.delete, danger: true, action: () => openOrganizationDelete('workspace', ws.id, chip) });
    return items;
  };
  bindAnchoredContextMenu(chip, workspaceMenuItems);
  return chip;
}

function renderWsList() {
  const $l = document.getElementById('ws-list');
  $l.innerHTML = '';
  const s = State.get();
  s.workspaces.forEach(ws => {
    const el = document.createElement('div');
    el.className = 'ws-item' + (ws.id === s.activeWsId ? ' active' : '');
    el.innerHTML = `<span class="sym">${esc(ws.symbol||'🏠')}</span><span class="name">${esc(ws.name)}</span>`;
    el.onclick = () => { State.get().activeWsId = ws.id; $l.classList.add('hidden'); State.persist(); renderAll(); };
    $l.appendChild(el);
  });
}

function categoryReminderMenuItem(cat, opener) {
  // Reopen existing reminders before offering another one. This keeps delivered
  // and legacy multi-reminder records reachable through the picker's Remove
  // action, which is required before an otherwise-empty Space can be deleted.
  const hasReminder = Array.isArray(cat?.reminders) && cat.reminders.length > 0;
  return {
    text: `${tr(hasReminder ? 'reminder.editTitle' : 'reminder.setTitle')}…`,
    icon: cmIcons.clock,
    action: () => openEntityReminderPickerOrReport(
      'category',
      cat.id,
      hasReminder ? cat.reminders[0].id : undefined,
      { opener },
    ),
  };
}

let _catTabsInitialized = false;
function renderCategoryTabs() {
  const ws = activeWs(); if (!ws) return;
  const $c = document.getElementById('cat-tabs');
  // Preserve keyboard focus across re-renders (otherwise arrow-key nav resets focus to body).
  const refocusActive = $c.contains(document.activeElement) && document.activeElement.classList?.contains('cat-tab');
  $c.innerHTML = '';
  const frag = document.createDocumentFragment();
  ws.categories.forEach(cat => {
    const b = document.createElement('button');
    b.className = 'cat-tab' + (cat.id === ws.activeCatId ? ' active' : '');
    b.dataset.cid = cat.id;
    b.textContent = cat.name;
    b.onclick = () => openCategory(cat.id);
    bindAnchoredContextMenu(b, () => [
        categoryReminderMenuItem(cat, b),
        ws.categories.length > 1 ? { text: tr('organization.space.delete'), icon: cmIcons.delete, danger: true, action: () => openOrganizationDelete('space', cat.id, b) } : null
      ].filter(Boolean));

    // Drag reorder
    b.draggable = true;
    b.ondragstart = e => {
      drag = { kind:'cat', srcId: cat.id };
      b.classList.add('dragging');
      e.dataTransfer.effectAllowed = 'move';
    };
    b.ondragend = () => { b.classList.remove('dragging'); document.querySelectorAll('.cat-tab').forEach(x => { x.classList.remove('drop-before'); x.classList.remove('drop-after'); }); drag = null; };
    b.ondragover = e => {
      if (drag?.kind === 'cat' && drag.srcId !== cat.id) {
        e.preventDefault();
        const r = b.getBoundingClientRect();
        const after = e.clientX > r.left + r.width / 2;
        document.querySelectorAll('.cat-tab').forEach(x => { x.classList.remove('drop-before'); x.classList.remove('drop-after'); });
        b.classList.add(after ? 'drop-after' : 'drop-before');
      }
    };
    b.ondrop = e => {
      if (drag?.kind === 'cat' && drag.srcId !== cat.id) {
        e.preventDefault();
        const r = b.getBoundingClientRect();
        const after = e.clientX > r.left + r.width / 2;
        State.snapshot('Reorder cat');
        const srcIdx = ws.categories.findIndex(c => c.id === drag.srcId);
        const [src] = ws.categories.splice(srcIdx, 1);
        let tgtIdx = ws.categories.findIndex(c => c.id === cat.id);
        if (after) tgtIdx++;
        ws.categories.splice(tgtIdx, 0, src);
        State.persist(); renderCategoryTabs();
      }
    };
    frag.appendChild(b);
  });
  $c.appendChild(frag);
  // Scroll the active tab into view; first render snaps without animation.
  const activeBtn = $c.querySelector('.cat-tab.active');
  if (activeBtn) {
    if (_catTabsInitialized) activeBtn.scrollIntoView({ inline: 'nearest', block: 'nearest', behavior: 'smooth' });
    else activeBtn.scrollIntoView({ inline: 'nearest', block: 'nearest', behavior: 'auto' });
    if (refocusActive) { try { activeBtn.focus({ preventScroll: true }); } catch { activeBtn.focus(); } }
  }
  _catTabsInitialized = true;
  updateCatScrollState();
  // The sidebar SPACES list is the primary category nav in the refreshed shell;
  // keep it in sync with the (now hidden) top strip on every category re-render.
  renderSpaceNav();
}

function updateCatScrollState() {
  const $c = document.getElementById('cat-tabs');
  const $w = document.getElementById('cat-tabs-wrap');
  if (!$c || !$w) return;
  const max = $c.scrollWidth - $c.clientWidth;
  const left = $c.scrollLeft;
  // 2px tolerance for sub-pixel rounding.
  $w.classList.toggle('can-scroll-left', left > 2);
  $w.classList.toggle('can-scroll-right', left < max - 2);
}

function bindCatScroll() {
  const $c = document.getElementById('cat-tabs');
  const $w = document.getElementById('cat-tabs-wrap');
  if (!$c || !$w) return;
  const STEP = 160;
  const left = document.getElementById('cat-scroll-left');
  const right = document.getElementById('cat-scroll-right');
  if (left) left.addEventListener('click', () => $c.scrollBy({ left: -STEP, behavior: 'smooth' }));
  if (right) right.addEventListener('click', () => $c.scrollBy({ left: STEP, behavior: 'smooth' }));
  $c.addEventListener('scroll', rafThrottle(updateCatScrollState), { passive: true });
  if (typeof ResizeObserver === 'function') {
    const ro = new ResizeObserver(rafThrottle(updateCatScrollState));
    ro.observe($c);
    ro.observe($w);
  } else {
    window.addEventListener('resize', rafThrottle(updateCatScrollState));
  }
  // Keyboard navigation between categories when a .cat-tab has focus.
  $c.addEventListener('keydown', e => {
    if (e.key !== 'ArrowLeft' && e.key !== 'ArrowRight') return;
    const tab = e.target.closest('.cat-tab');
    if (!tab) return;
    e.preventDefault(); e.stopPropagation();
    const all = Array.from($c.querySelectorAll('.cat-tab'));
    const idx = all.indexOf(tab);
    if (idx < 0) return;
    const nextIdx = e.key === 'ArrowLeft' ? Math.max(0, idx - 1) : Math.min(all.length - 1, idx + 1);
    const next = all[nextIdx];
    if (next && next !== tab) { next.focus(); next.click(); }
  });
  updateCatScrollState();
}

// Layout registry (§2.2) — every registered layout is a pure renderer over the
// active category, sharing the same data, search filter, drag/drop and
// selection, so adding a layout is registering an entry here rather than
// touching the data model. The active layout is stored per category
// (`category.layout`, §7) and falls back to the legacy `settings.viewMode`.
const LAYOUTS = {
  board:    { label: 'Board',    render: renderBoardView },
  list:     { label: 'List',     render: renderListView },
  canvas:   { label: 'Canvas',   render: renderCanvasView },
  explorer: { label: 'Explorer', render: renderExplorerView },
  timeline: { label: 'Timeline', render: renderTimelineView },
  gallery:  { label: 'Gallery',  render: renderGalleryView },
  graph:    { label: 'Graph',    render: renderGraphView },
};
// The order of the Space page's view tabs (all seven; see SPACE PAGE).
const LAYOUT_ORDER = ['board', 'list', 'canvas', 'explorer', 'timeline', 'gallery', 'graph'];

function layoutLabel(mode) {
  return LAYOUTS[mode] ? tr(`layout.${mode}`) : '';
}

// Single dispatch point: pick the active layout and render it. Everything that
// mutates state calls renderBoard() to re-render whatever layout is showing.
function renderBoard() {
  invalidateItemCache();
  updateCalendarButton();
  updateNavChrome();
  // Home is a block-scrolling surface; clear its class up front so the calendar
  // and group-page gates (which early-return below) never inherit it. renderHome()
  // re-adds it when Home is the active surface.
  document.getElementById('board').classList.remove('home-mode', 'library-mode', 'archive-mode', 'trash-mode', 'read-later-mode', 'plan-mode');
  // Find again keeps its mark through its own repaint, like the pages below.
  if (!activeSearch) document.getElementById('board').classList.remove('search-mode');
  // The Inbox and Library pages keep their marks through their own repaint, so
  // the board's padding never drops out mid-render and clamps the scroll position.
  if (activeSearch || activeCalendar || !isInboxPageActive()) {
    document.getElementById('board').classList.remove('inbox-mode');
    if (document.body.dataset.page === 'inbox') delete document.body.dataset.page;
  }
  if (!isLibraryPageActive()) {
    document.getElementById('board').classList.remove('lib-mode');
    if (document.body.dataset.page === 'library') delete document.body.dataset.page;
  }
  if (!isSpacePageActive()) {
    document.getElementById('board').classList.remove('spc-mode');
    if (document.body.dataset.page === 'space') delete document.body.dataset.page;
  }
  // Reflect the active surface on <body> (diagnostic / styling hook), computed
  // from the flags so it stays correct through every early-returning gate.
  document.body.dataset.surface = activeSearch ? 'search' : activeCalendar ? 'calendar' : activeGroupPage ? 'group' : activeLibraryMode ? 'library' : activeHome ? 'home' : 'board';
  renderTopbarContext();
  // Today's open-tabs drawer belongs to Home only.
  if (document.body.dataset.surface !== 'home' && typeof isTodayTabsDrawerOpen === 'function' && isTodayTabsDrawerOpen()) {
    setTodayTabsDrawer(false, { restoreFocus: false });
  }
  // Sort inbox's session (answers, skipped cards) lasts only while Sort shows.
  if (typeof planSortSession !== 'undefined' && planSortSession && activeCalendar?.view !== 'sort') planSortSession = null;
  // So does the Inbox page's triage session, and its Space picker.
  if (inboxPageSession && !isInboxPageActive()) {
    inboxPageSession = null;
    closeInboxSpacePicker();
  }
  if (libraryPageSession && !isLibraryPageActive()) libraryPageSession = null;
  if (spacePageSession && !isSpacePageActive()) spacePageSession = null;
  if (searchPageSession && !activeSearch) searchPageSession = null;
  if (calendarPageSession && !(activeCalendar && CAL_VIEWS.includes(activeCalendar.view))) calendarPageSession = null;
  // The calendar (§5) and group pages (§4.1) are surfaces that sit above the
  // layout registry: when one is open every re-render keeps showing it. Each
  // renderer returns false if the user has navigated away, so we fall through to
  // the normal board in that case.
  if (activeSearch && renderSearchSurface()) return;
  if (activeCalendar && renderCalendar()) return;
  // A group page (§4.1) is a surface that sits above the layout registry: when
  // one is open every re-render keeps showing it. renderGroupPage() returns
  // false if its group vanished or the user navigated away, so we fall through
  // to the normal board in that case.
  if (activeGroupPage && renderGroupPage()) return;
  if (activeLibraryMode && renderLibrarySurface()) return;
  // Home (workspace overview) is the third surface above the layout registry, and
  // the default landing on a fresh new-tab. renderHome() returns false and clears
  // the flag if the workspace vanished, falling through to the category board.
  if (activeHome && renderHome()) return;
  hideBreadcrumb();
  document.body.dataset.surface = 'board';
  renderTopbarContext();
  if (typeof isTodayTabsDrawerOpen === 'function' && isTodayTabsDrawerOpen()) {
    setTodayTabsDrawer(false, { restoreFocus: false });
  }
  const $b = document.getElementById('board');
  $b.classList.remove('group-page-mode', 'list-mode', 'canvas-mode', 'explorer-mode', 'timeline-mode', 'gallery-mode', 'graph-mode', 'calendar-mode', 'home-mode');
  const mode = getViewMode();
  document.body.dataset.viewMode = mode;
  // The Space page carries the view switcher and draws the layout inside it.
  if (renderSpacePage(mode)) return;
  const layout = LAYOUTS[mode] || LAYOUTS.board;
  layout.render();
}

// ════════════════════════════════════════════════════════════════
// HOME SURFACE — Waypoint-style workspace overview
// ════════════════════════════════════════════════════════════════
// The dashboard landing: a greeting hero + one card per category, sitting above
// the layout registry like the calendar and group page. The left nav and the
// right Opened-Tabs rail frame it unchanged; only the middle column swaps.

// Enter Home. Clears the other above-registry surfaces so Home wins the next
// renderBoard() dispatch, then mirrors `…/home` into the URL.
function goHome() {
  activeSearch = null;
  activeLibraryMode = null;
  activeHome = true;
  activeGroupPage = null;
  activeCalendar = null;
  boardDetailItemId = null;
  renderBoard();
  renderSpaceNav();
  Router.sync();
}

// Open a category's board (the legacy layout in the middle column). Usable from
// any surface — clears Home / group page / calendar first.
function openCategory(catId) {
  const ws = activeWs(); if (!ws) return;
  if (!ws.categories.some(c => c.id === catId)) return;
  activeSearch = null;
  activeLibraryMode = null;
  activeHome = false;
  activeGroupPage = null;
  activeCalendar = null;
  ws.activeCatId = catId;
  State.persist();
  renderCategoryTabs();
  renderBoard();
  Router.sync();
}

function reportInboxNavigationUnavailable(opener = null) {
  toast(tr('nav.inboxUnavailable'), { danger: true, duration: 5000 });
  if (opener && typeof opener.focus === 'function') {
    requestAnimationFrame(() => {
      if (!opener.isConnected) return;
      try { opener.focus({ preventScroll: true }); } catch { opener.focus(); }
    });
  }
  return false;
}

// Inbox is a read-only shell destination. Capture and explicit content creation
// retain their own reviewed provisioning paths; navigation never guesses or
// creates a Group.
function openInboxView(context = createLandingInboxContext(), opener = null) {
  const target = resolveLandingInboxTarget(context);
  if (!target) return reportInboxNavigationUnavailable(opener);
  const navigated = Router.navigate({
    type: 'group',
    wsId: target.workspace.id,
    groupId: target.group.id,
    itemId: null,
    query: {},
  }, { persist: false });
  return navigated || reportInboxNavigationUnavailable(opener);
}

function collectWorkspaceTabs(ws = activeWs()) {
  if (!ws) return [];
  const rows = [];
  const walk = (items, cat, group, parents = []) => {
    (items || []).forEach(it => {
      if (it.type === 'stack') walk(it.items, cat, group, [...parents, it]);
      else if (it.type === 'tab') rows.push({ ws, item: it, cat, group, parents });
    });
  };
  ws.categories.forEach(cat => cat.groups.forEach(group => walk(group.items, cat, group)));
  return rows;
}

function libraryRowsForState(ws, state) {
  if (!ws || !state) return [];
  const needle = String(state.query || '').trim().toLocaleLowerCase();
  let rows = collectWorkspaceTabs(ws);
  if (state.mode === 'favorites') rows = rows.filter(row => !!row.item.favorite);
  if (state.mode === 'read-later') {
    rows = rows.filter(row => !!row.item.readLaterAt);
    if (state.status === 'read') rows = rows.filter(row => !!row.item.readAt);
    else if (state.status !== 'all') rows = rows.filter(row => !row.item.readAt);
  }
  if (needle) {
    rows = rows.filter(row => [
      row.item.title,
      row.item.url,
      row.ws?.name,
      row.cat?.name,
      row.group?.name,
      ...(row.parents || []).map(parent => parent.name),
    ].join(' ').toLocaleLowerCase().includes(needle));
  }
  const timeFor = row => state.mode === 'read-later'
    ? Number(row.item.readLaterAt || 0)
    : Number(row.item.createdAt || 0);
  return [...rows].sort((left, right) => {
    if (state.sort === 'title') {
      const titleOrder = String(left.item.title || '').localeCompare(String(right.item.title || ''));
      if (titleOrder) return titleOrder;
    } else if (state.sort === 'oldest') {
      const oldestOrder = timeFor(left) - timeFor(right);
      if (oldestOrder) return oldestOrder;
    } else {
      const newestOrder = timeFor(right) - timeFor(left);
      if (newestOrder) return newestOrder;
    }
    return String(left.item.id || '').localeCompare(String(right.item.id || ''));
  });
}

function libraryDetailItemIdForRoute(ws, state, itemId) {
  if (!ws || !state || !itemId || !LIBRARY_LEDGER_MODES.includes(state.mode)) return null;
  const target = resolveUniqueHomePreviewItem(ws.id, itemId);
  if (!target || target.ws !== ws) return null;
  const visible = libraryRowsForState(ws, state).some(row => (
    row.ws === target.ws
    && row.cat === target.cat
    && row.group === target.group
    && row.item === target.item
  ));
  return visible ? target.item.id : null;
}

function libraryDestinationText(row) {
  if (!row?.ws || !row?.cat || !row?.group) return '';
  let path = tr('library.destinationPath', {
    workspace: row.ws.name,
    space: row.cat.name,
    group: row.group.name,
  });
  (row.parents || []).forEach(parent => {
    path = tr('library.destinationStack', { path, stack: parent.name || '' });
  });
  return path;
}

function libraryLedgerRowModel(row, mode) {
  const item = row?.item || {};
  const timestamp = mode === 'read-later' ? item.readLaterAt : item.createdAt;
  return {
    id: String(item.id || ''),
    title: String(item.title || '').trim() || tr('itemAction.untitled'),
    url: dispUrl(item.url),
    destination: libraryDestinationText(row),
    openLabel: tr('library.openPage'),
    detailsLabel: tr('library.viewDetails'),
    age: timestamp ? fmtTimeRelative(timestamp) : '',
    statusLabel: mode === 'read-later'
      ? tr(item.readAt ? 'library.markUnread' : 'library.markRead')
      : '',
  };
}

function libraryRowFocusKey(row, state = activeLibraryState) {
  return [row?.ws?.id, state?.mode, row?.item?.id]
    .map(value => encodeURIComponent(String(value || '')))
    .join(':');
}

function createLibraryRecoveryContext(row, state = activeLibraryState) {
  if (!row || !state || row.ws !== activeWs() || state.mode !== activeLibraryMode) return null;
  const recovery = createSavedItemRecoveryContext(row);
  if (!recovery.workspaceId || !recovery.itemId) return null;
  return {
    ...recovery,
    mode: state.mode,
    routeFingerprint: JSON.stringify(libraryRouteQuery(state, null)),
    focusKey: libraryRowFocusKey(row, state),
  };
}

function resolveLibraryRecoveryTarget(context) {
  const ws = activeWs();
  if (!context || !ws || context.mode !== activeLibraryMode || ws.id !== context.workspaceId) return null;
  if (JSON.stringify(libraryRouteQuery(activeLibraryState, null)) !== context.routeFingerprint) return null;
  const target = resolveSavedItemRecoveryTarget(context);
  if (!target) return null;
  const visible = libraryRowsForState(ws, activeLibraryState)
    .find(row => row.item === target.item
      && row.cat === target.cat
      && row.group === target.group
      && (row.parents || []).length === (target.parents || []).length
      && (row.parents || []).every((parent, index) => parent === target.parents[index]));
  return visible ? target : null;
}

function activateLibraryRecovery(context, action, opener = null) {
  const target = resolveLibraryRecoveryTarget(context);
  if (!target) {
    toast(tr('library.itemUnavailable'), { danger: true, duration: 5000 });
    focusDialogOpener(opener);
    return false;
  }
  if (action === 'open') {
    return openSavedTabItem(target.item, { focus: true, opener });
  }
  if (action === 'details') {
    focusDialogOpener(opener);
    openItemDetail(target.item.id, { returnFocusKey: context.focusKey });
    return true;
  }
  return false;
}

// Search uses every saved item kind, including stack containers and their
// descendants. Parent stack names travel with each row so `in:` works without
// reading rendered DOM or duplicating layout-specific traversal.
function collectWorkspaceItems(ws = activeWs()) {
  if (!ws) return [];
  const rows = [];
  const walk = (items, cat, group, parents = []) => {
    (items || []).forEach(item => {
      rows.push({ item, cat, group, parents });
      if (item.type === 'stack') walk(item.items, cat, group, [...parents, item]);
    });
  };
  ws.categories.forEach(cat => cat.groups.forEach(group => walk(group.items, cat, group)));
  return rows;
}

// ── Zen launch layer ──────────────────────────────────────────────────────
let _landingClockTimer = null;
let _landingResultIndex = -1;
let _landingInboxContext = null;

function syncLandingComboboxState(input, results, expanded) {
  if (!results) return;
  const options = [...results.querySelectorAll('.landing-result')];
  const popupOpen = !!expanded && !results.classList.contains('hidden');
  const selected = popupOpen && _landingResultIndex >= 0
    ? options[_landingResultIndex] || null
    : null;
  input?.setAttribute('aria-expanded', String(popupOpen));
  options.forEach(option => {
    const active = option === selected;
    option.classList.toggle('active', active);
    option.setAttribute('aria-selected', String(active));
  });
  if (selected?.id) input?.setAttribute('aria-activedescendant', selected.id);
  else input?.removeAttribute('aria-activedescendant');
}

function handleLandingSearchInput(input, results, queuePaint) {
  if (!input || !results) return false;
  _landingResultIndex = -1;
  results.classList.add('hidden');
  syncLandingComboboxState(input, results, false);
  if (typeof queuePaint === 'function') queuePaint();
  return true;
}

function handleLandingSearchKeydown(event, input, results) {
  if (!event || !input || !results || event.isComposing || event.keyCode === 229) return false;
  const options = [...results.querySelectorAll('.landing-result')];
  const popupOpen = !results.classList.contains('hidden');
  if ((event.key === 'ArrowDown' || event.key === 'ArrowUp') && popupOpen && options.length) {
    event.preventDefault();
    _landingResultIndex = (_landingResultIndex + (event.key === 'ArrowDown' ? 1 : options.length - 1)) % options.length;
    syncLandingComboboxState(input, results, true);
    options[_landingResultIndex].scrollIntoView({ block: 'nearest' });
    return true;
  }
  if (event.key === 'Enter' && popupOpen && _landingResultIndex >= 0 && options[_landingResultIndex]) {
    event.preventDefault();
    options[_landingResultIndex].click();
    return true;
  }
  if (event.key === 'Enter') {
    event.preventDefault();
    submitLandingSearch();
    return true;
  }
  if (event.key === 'Escape' && popupOpen) {
    event.preventDefault();
    event.stopPropagation();
    results.classList.add('hidden');
    _landingResultIndex = -1;
    syncLandingComboboxState(input, results, false);
    return true;
  }
  return false;
}

function createLandingInboxContext(ws = activeWs()) {
  if (!ws || activeWs() !== ws || !Array.isArray(ws.categories)) return null;
  const cat = ws.categories.find(candidate => candidate?.id === ws.activeCatId) || ws.categories[0] || null;
  if (!cat || activeCat() !== cat || !Array.isArray(cat.groups)) return null;
  const context = homeTrailDestinationContext(ws, cat);
  const groupId = String(context?.inboxRef?.id || '');
  return context?.inboxCount === 1 && groupId ? { ...context, groupId } : null;
}

function resolveLandingInboxTarget(context) {
  if (!context?.groupId || context.inboxCount !== 1) return null;
  try {
    if (!homeTrailDestinationStillMatches(context)) return null;
    const target = identityGroupTarget(context.groupId);
    if (!target
        || target.workspace !== context.workspaceRef
        || target.space !== context.spaceRef
        || target.group !== context.inboxRef
        || target.group?.name !== 'Inbox') return null;
    return target;
  } catch {
    return null;
  }
}

function reportLandingInboxUnavailable(opener = null) {
  renderLandingLayer();
  toast(tr('landing.inboxUnavailable'), { danger: true, duration: 5000 });
  const button = document.getElementById('landing-unsorted');
  const input = document.getElementById('landing-search-input');
  const focusTarget = opener?.isConnected && !opener.hidden
    ? opener
    : button && !button.hidden ? button : input;
  requestAnimationFrame(() => {
    if (!focusTarget?.isConnected) return;
    try { focusTarget.focus({ preventScroll: true }); } catch { focusTarget.focus(); }
  });
  return false;
}

function activateLandingInbox(context, opener = null) {
  const target = resolveLandingInboxTarget(context);
  if (!target) return reportLandingInboxUnavailable(opener);
  const navigated = Router.navigate({
    type: 'group',
    wsId: target.workspace.id,
    groupId: target.group.id,
    itemId: null,
    query: {},
  }, { persist: false });
  if (!navigated) return reportLandingInboxUnavailable(opener);
  closeLandingLayer({ immediate: true });
  return true;
}

function landingLinkMatches(row, query) {
  return !!String(query || '').trim() && searchItemMatches({ ...row, parents: row.parents || [] }, query);
}

function landingResults(query) {
  return collectWorkspaceTabs(activeWs())
    .filter(row => landingLinkMatches(row, query))
    .map((row, index) => ({
      row,
      index,
      score: _searchScore(row, query),
      createdAt: Number(row.item.createdAt || 0),
      itemId: String(row.item.id || ''),
    }))
    .sort((a, b) => b.score - a.score
      || b.createdAt - a.createdAt
      || a.itemId.localeCompare(b.itemId)
      || a.index - b.index)
    .slice(0, 6)
    .map(entry => entry.row);
}

function landingResultDestinationText(row) {
  const parents = Array.isArray(row?.parents) ? row.parents : [];
  const parts = [
    row?.ws?.name,
    row?.cat?.name,
    homeTrailGroupName(row?.group),
    ...parents.map(parent => parent?.name),
  ].map(value => String(value || '').trim()).filter(Boolean);
  return homeTrailPathText(parts);
}

function createLandingRecoveryContext(row, ws = activeWs()) {
  if (!row?.item || !row?.cat || !row?.group || !ws) return null;
  const context = createSavedItemRecoveryContext({ ws, ...row });
  return context.workspaceId && context.itemId ? context : null;
}

function resolveLandingRecoveryTarget(context) {
  if (!context || activeWs() !== context.workspaceRef) return null;
  return resolveSavedItemRecoveryTarget(context);
}

function activateLandingRecovery(context, opener = null) {
  const target = resolveLandingRecoveryTarget(context);
  if (!target || target.item?.type !== 'tab' || !isOpenableSavedTabUrl(target.item.url)) {
    return reportSearchRecoveryUnavailable(opener);
  }
  if (!openSavedTabItem(target.item, {
    focus: true,
    opener,
    reportUnavailable: false,
    onConfirmed: () => closeLandingLayer({ immediate: true }),
  })) return reportSearchRecoveryUnavailable(opener);
  return true;
}

function paintLandingResults(query) {
  const host = document.getElementById('landing-search-results');
  if (!host) return;
  const input = document.getElementById('landing-search-input');
  const raw = String(query || '').trim();
  _landingResultIndex = -1;
  if (!raw) {
    host.innerHTML = '';
    host.classList.add('hidden');
    syncLandingComboboxState(input, host, false);
    return;
  }
  const rows = landingResults(raw);
  const ws = activeWs();
  const recoveryContexts = rows.map(row => createLandingRecoveryContext(row, ws));
  host.classList.remove('hidden');
  if (!rows.length) {
    host.innerHTML = `<div class="landing-result-empty">${esc(tr('landing.noResults'))}</div>`;
    syncLandingComboboxState(input, host, true);
    return;
  }
  host.innerHTML = rows.map((row, index) => {
    const { item } = row;
    const destination = landingResultDestinationText(row);
    return `
      <button id="landing-result-${index}" class="landing-result" type="button" role="option" aria-selected="false" data-index="${index}" data-id="${esc(item.id)}">
        <img src="${esc(favUrl(item.url) || BLANK_FAV)}" alt="" loading="lazy" decoding="async">
        <span class="landing-result-copy">
          <span class="landing-result-title">${esc(item.title || item.url || 'Untitled')}</span>
          <span class="landing-result-url">${esc(dispUrl(item.url))}</span>
        </span>
        <span class="landing-result-space" title="${esc(destination)}">${esc(destination)}</span>
      </button>`;
  }).join('');
  syncLandingComboboxState(input, host, true);
  host.querySelectorAll('.landing-result').forEach((button, index) => {
    button.onclick = () => {
      activateLandingRecovery(recoveryContexts[index], button);
    };
  });
}

function updateLandingClock() {
  const time = document.getElementById('landing-time');
  const date = document.getElementById('landing-date');
  if (!time || !date) return;
  const now = new Date();
  const locale = appLocale() === 'zh-TW' ? 'zh-TW' : 'en-US';
  // The zen clock reads "9:41" — 12-hour time with no meridiem (the scene art
  // already says morning/evening), matching the landing preview.
  time.textContent = new Intl.DateTimeFormat(locale, { hour: 'numeric', minute: '2-digit', hour12: appLocale() !== 'zh-TW' })
    .formatToParts(now).filter(part => part.type !== 'dayPeriod').map(part => part.value).join('').trim();
  date.textContent = appLocale() === 'zh-TW'
    ? new Intl.DateTimeFormat(locale, { weekday: 'short', month: 'short', day: 'numeric' }).format(now)
    : now.toLocaleDateString('en-GB', { weekday: 'short' }) + ', ' + now.toLocaleDateString('en-GB', { day: 'numeric', month: 'long' });
  paintLandingFlip(now);
}

// Calm new tab (2026-11 canvas): a split-flap clock. Each digit card keeps the
// previous digit on its lower half and folds the new one down over it.
function paintLandingFlip(now = new Date()) {
  const flip = document.getElementById('landing-flip');
  const dateLine = document.getElementById('landing-flip-date');
  if (!flip) return;
  const pad = value => String(value).padStart(2, '0');
  const digits = `${pad(now.getHours())}${pad(now.getMinutes())}`;
  if (!flip.children.length) {
    flip.innerHTML = [0, 1, 'sep', 2, 3].map(slot => (slot === 'sep'
      ? '<span class="fl-sep" aria-hidden="true"><i></i><i></i></span>'
      : `<span class="fl-card" aria-hidden="true" data-slot="${slot}"><span class="fl-half fl-top"><b></b></span><span class="fl-half fl-bot"><b></b></span><span class="fl-flap fl-ftop"><b></b></span><span class="fl-flap fl-fbot"><b></b></span><i class="fl-hinge"></i></span>`)).join('');
  }
  flip.querySelectorAll('.fl-card').forEach(card => {
    const next = digits[Number(card.dataset.slot)];
    const previous = card.dataset.digit;
    if (previous === next) return;
    const [top, bottom, flapTop, flapBottom] = card.querySelectorAll('b');
    top.textContent = next;
    bottom.textContent = previous ?? next;
    flapTop.textContent = previous ?? next;
    flapBottom.textContent = next;
    card.dataset.digit = next;
    card.classList.remove('is-flipping');
    if (previous != null) {
      void card.offsetWidth;
      card.classList.add('is-flipping');
      setTimeout(() => { bottom.textContent = next; card.classList.remove('is-flipping'); }, 800);
    }
  });
  flip.setAttribute('aria-label', tr('landing.timeLabel', { time: `${digits.slice(0, 2)}:${digits.slice(2)}` }));
  if (dateLine) {
    dateLine.textContent = appLocale() === 'zh-TW'
      ? new Intl.DateTimeFormat('zh-TW', { month: 'long', day: 'numeric', weekday: 'long' }).format(now)
      : now.toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long' });
  }
}

// Three most recently saved pages, opened through the shared Reopen path.
function renderLandingRecent(ws) {
  const host = document.getElementById('landing-recent');
  if (!host) return;
  const rows = ws ? collectWorkspaceTabs(ws)
    .filter(row => isOpenableSavedTabUrl(row.item.url))
    .sort((a, b) => (Number(b.item.createdAt) || 0) - (Number(a.item.createdAt) || 0))
    .slice(0, 3) : [];
  host.innerHTML = rows.map((row, index) => {
    let domain = '';
    try { domain = new URL(row.item.url).hostname.replace(/^www\./, ''); } catch {}
    const title = String(row.item.title || domain || row.item.url || '').trim();
    const initial = (domain || title || '•').charAt(0).toUpperCase();
    return `<button type="button" class="landing-recent-page" data-index="${index}"><span class="landing-recent-icon" aria-hidden="true">${esc(initial)}</span><span class="landing-recent-title">${esc(title)}</span></button>`;
  }).join('');
  host.hidden = rows.length === 0;
  host.querySelectorAll('.landing-recent-page').forEach(button => {
    button.onclick = () => {
      const row = rows[Number(button.dataset.index)];
      if (!row) return;
      closeLandingLayer({ immediate: true });
      openSavedTabItem(row.item, { opener: button });
    };
  });
}

// Dark by default, with a light option remembered on this device.
function landingTone() {
  try { return localStorage.getItem('locus.landing.tone') === 'light' ? 'light' : 'dark'; } catch { return 'dark'; }
}
function applyLandingTone(tone = landingTone()) {
  const layer = document.getElementById('landing-layer');
  const button = document.getElementById('landing-tone');
  if (layer) layer.dataset.tone = tone;
  if (button) {
    // One fixed label; the pressed state says whether the light tone is on.
    button.setAttribute('aria-pressed', String(tone === 'light'));
    button.setAttribute('aria-label', tr('landing.light'));
    button.title = tr('landing.light');
  }
}

function renderLandingLayer() {
  const layer = document.getElementById('landing-layer');
  const ws = activeWs();
  if (!layer || !ws) return;
  const now = new Date();
  const hour = now.getHours();
  const tod = hour < 12 ? 'morning' : hour < 18 ? 'noon' : 'night';
  const greetingKey = hour < 12 ? 'home.greeting.morning' : hour < 18 ? 'home.greeting.afternoon' : 'home.greeting.evening';
  // Greet with the profile name only — the workspace name is an organizational
  // label ("My Workspace"), not something to address the user by.
  const name = ((State.get().settings.profile && State.get().settings.profile.name) || '').trim().split(/\s+/)[0];
  document.getElementById('landing-greeting').textContent = name
    ? tr('landing.greeting', { greeting: tr(greetingKey), name })
    : tr('landing.greetingNoName', { greeting: tr(greetingKey) });
  const scene = document.getElementById('landing-scene');
  if (scene) scene.src = `media/png/${activeThemeMode() === 'dark' ? 'night' : tod}_transparent_corners.png`;
  const face = document.getElementById('landing-avatar-face');
  if (face) face.textContent = (name || ws.name || 'L').charAt(0).toUpperCase();
  _landingInboxContext = createLandingInboxContext(ws);
  const inboxButton = document.getElementById('landing-unsorted');
  const inboxCount = document.getElementById('landing-unsorted-count');
  const count = Array.isArray(_landingInboxContext?.inboxRef?.items)
    ? _landingInboxContext.inboxRef.items.length
    : 0;
  const reminders = collectPendingReminders({ scope: ws.id }).length;
  inboxButton.hidden = !_landingInboxContext;
  inboxCount.hidden = count === 0;
  inboxCount.textContent = String(count);
  document.getElementById('landing-reminder-count').textContent = String(reminders);
  inboxButton.setAttribute('aria-label', count > 0 ? `${tr('nav.inbox')}: ${count}` : tr('nav.inbox'));
  document.getElementById('landing-reminders').setAttribute('aria-label', `${tr('landing.reminders')}: ${reminders}`);
  // A "0 Reminders" pill is noise on a calm surface — the segment only earns
  // its place when something is actually pending.
  document.getElementById('landing-reminders').classList.toggle('hidden', reminders === 0);
  renderLandingRecent(ws);
  applyLandingTone();
  updateLandingClock();
}

function showLandingLayer() {
  const layer = document.getElementById('landing-layer');
  if (!layer || State.get().settings.showLanding !== true) return false;
  rememberOpener(layer);
  renderLandingLayer();
  layer.classList.remove('hidden', 'landing-exit');
  // Staggered entrance (greeting → search → footer). Re-trigger per show; the
  // global data-anim/reduced-motion gates neutralize it when motion is off.
  layer.classList.remove('landing-in');
  void layer.offsetWidth;
  layer.classList.add('landing-in');
  scheduleLandingClock();
  setTimeout(() => document.getElementById('landing-search-input')?.focus({ preventScroll: true }), 50);
  return true;
}

// The flip clock turns on the minute: each tick schedules the next at the next
// minute boundary (plus a small margin), instead of polling every 30 s (S6).
// closeLandingLayer's clearInterval also clears it: timer IDs share one pool.
function scheduleLandingClock(now = Date.now()) {
  clearTimeout(_landingClockTimer);
  _landingClockTimer = setTimeout(() => {
    updateLandingClock();
    scheduleLandingClock();
  }, 60000 - (now % 60000) + 50);
  return _landingClockTimer;
}

function closeLandingLayer({ immediate = false } = {}) {
  const layer = document.getElementById('landing-layer');
  if (!layer || layer.classList.contains('hidden')) return;
  clearInterval(_landingClockTimer);
  const noMotion = immediate || prefersReducedMotion() || !State.get().settings.animate;
  const finish = () => {
    layer.classList.add('hidden');
    layer.classList.remove('landing-exit', 'landing-in');
    // Reset the search so a later reopen starts fresh instead of resurfacing
    // a stale query.
    const input = document.getElementById('landing-search-input');
    if (input) input.value = '';
    const results = document.getElementById('landing-search-results');
    _landingResultIndex = -1;
    if (results) {
      results.innerHTML = '';
      results.classList.add('hidden');
      syncLandingComboboxState(input, results, false);
    }
    restoreOpener(layer);
  };
  if (noMotion) finish();
  else { layer.classList.add('landing-exit'); setTimeout(finish, 430); }
}

function submitLandingSearch() {
  const input = document.getElementById('landing-search-input');
  const query = input ? input.value.trim() : '';
  if (!query) { input?.focus(); return; }
  const active = document.querySelector('.landing-result.active');
  if (active) { active.click(); return; }
  closeLandingLayer({ immediate: true });
  openSearchSurface(query);
}

function bindLandingLayer() {
  const layer = document.getElementById('landing-layer');
  const input = document.getElementById('landing-search-input');
  const results = document.getElementById('landing-search-results');
  if (!layer || !input || !results) return;
  layer.addEventListener('keydown', e => trapTabKey(e, layer));
  document.getElementById('landing-search-form').onsubmit = e => { e.preventDefault(); submitLandingSearch(); };
  const queueLandingResults = debounce(() => paintLandingResults(input.value), 70);
  input.oninput = () => handleLandingSearchInput(input, results, queueLandingResults);
  input.onkeydown = e => handleLandingSearchKeydown(e, input, results);
  document.getElementById('landing-enter').onclick = () => closeLandingLayer();
  const inboxButton = document.getElementById('landing-unsorted');
  inboxButton.onclick = () => activateLandingInbox(_landingInboxContext, inboxButton);
  document.getElementById('landing-reminders').onclick = () => { closeLandingLayer({ immediate: true }); openCalendar(); };
  const landingToday = document.getElementById('landing-today');
  if (landingToday) landingToday.onclick = () => closeLandingLayer();
  const landingToneButton = document.getElementById('landing-tone');
  if (landingToneButton) landingToneButton.onclick = () => {
    const next = landingTone() === 'light' ? 'dark' : 'light';
    try { localStorage.setItem('locus.landing.tone', next); } catch {}
    applyLandingTone(next);
  };
  document.getElementById('landing-tools').onclick = () => {
    closeLandingLayer({ immediate: true });
    openToolsHub();
  };
  document.getElementById('landing-menu').onclick = e => {
    const rect = e.currentTarget.getBoundingClientRect();
    closeLandingLayer({ immediate: true });
    openAppMenu({ getBoundingClientRect: () => rect });
  };
  layer.addEventListener('wheel', e => { if (e.deltaY > 28) closeLandingLayer(); }, { passive: true });
}

let savedTabReturnMutationPending = null;
let savedTabReturnMutationInertElements = [];

function isSavedTabReturnMutationPending() {
  return !!savedTabReturnMutationPending;
}

function createSavedTabReturnMutationContext(item) {
  const context = createItemReminderMutationContext(item?.id);
  if (!context || context.itemRef !== item || context.itemType !== 'tab') return null;
  return {
    context,
    itemId: context.itemId,
    itemRef: item,
    favorite: !!item.favorite,
    readLaterAt: item.readLaterAt ?? null,
    readAt: item.readAt ?? null,
  };
}

function resolveSavedTabReturnMutationTarget(review) {
  if (!review?.context || review.itemRef !== review.context.itemRef) return null;
  const target = resolveItemReminderMutationTarget(review.context);
  if (!target || target.item !== review.itemRef || target.item.type !== 'tab') return null;
  return target;
}

function planSavedTabReturnMutation(review, action, now = Date.now()) {
  if (!review) return null;
  if (action === 'favorite') {
    return {
      kind: 'favorite',
      value: !review.favorite,
      historyKey: review.favorite ? 'itemAction.removeFavorite' : 'itemAction.addFavorite',
      successKey: review.favorite ? 'itemAction.removedFavorite' : 'itemAction.addedFavorite',
    };
  }
  if (action === 'read-later') {
    const removing = !!review.readLaterAt;
    const timestamp = Number(now);
    if (!removing && (!Number.isFinite(timestamp) || timestamp <= 0)) return null;
    return {
      kind: 'read-later',
      removing,
      timestamp,
      historyKey: removing ? 'itemAction.removeReadLater' : 'itemAction.saveReadLater',
      successKey: removing ? 'itemAction.removedReadLater' : 'itemAction.savedReadLater',
    };
  }
  if (action === 'read-status' && review.readLaterAt) {
    const markingUnread = !!review.readAt;
    const timestamp = Number(now);
    if (!markingUnread && (!Number.isFinite(timestamp) || timestamp <= 0)) return null;
    return {
      kind: 'read-status',
      markingUnread,
      timestamp,
      historyKey: markingUnread ? 'library.markUnread' : 'library.markRead',
      successKey: markingUnread ? 'library.markedUnread' : 'library.markedRead',
    };
  }
  return null;
}

function setSavedTabReturnMutationInterlock(opener, enabled) {
  if (enabled) {
    const owned = new Set();
    let current = opener;
    while (current?.parentElement) {
      const parent = current.parentElement;
      for (const sibling of parent.children) {
        if (sibling === current || sibling.id === 'state-recovery-overlay') continue;
        setElementInertOwner(sibling, 'saved-tab-return', true);
        owned.add(sibling);
      }
      if (parent === document.body) break;
      current = parent;
    }
    savedTabReturnMutationInertElements = [...owned];
    return;
  }
  const owned = savedTabReturnMutationInertElements;
  savedTabReturnMutationInertElements = [];
  owned.forEach(element => setElementInertOwner(element, 'saved-tab-return', false));
}

function setSavedTabReturnMutationBusy(review, candidateOpener, busy) {
  const itemId = String(review?.itemId || '');
  const escaped = itemId ? CSS.escape(itemId) : '';
  const fallback = escaped
    ? document.querySelector(
        `.library-row[data-id="${escaped}"] [data-return-marker], `
        + `.item[data-id="${escaped}"] [data-item-primary="true"]`,
      )
    : null;
  const opener = candidateOpener?.isConnected ? candidateOpener : fallback;
  if (!busy) setSavedTabReturnMutationInterlock(null, false);
  if (!opener) return !busy;
  if (busy) {
    try { opener.focus({ preventScroll: true }); } catch { try { opener.focus(); } catch {} }
    setSavedTabReturnMutationInterlock(opener, true);
  }
  opener.setAttribute('aria-busy', String(busy));
  opener.setAttribute('aria-disabled', String(busy));
  if (!busy) opener.removeAttribute('aria-disabled');
  const owner = opener.closest('.library-row, .item.tab');
  owner?.classList.toggle('is-return-marker-pending', busy);
  if (owner) {
    if (busy) owner.setAttribute('aria-busy', 'true');
    else owner.removeAttribute('aria-busy');
  }
  return true;
}

function focusSavedTabReturnMutationOpener(opener) {
  if (!opener?.isConnected || typeof opener.focus !== 'function') return false;
  try { opener.focus({ preventScroll: true }); } catch { try { opener.focus(); } catch { return false; } }
  return true;
}

async function commitSavedTabReturnMutation(review, action, opener = null, now = Date.now(), receipt = null) {
  if (!review
      || isSavedTabReturnMutationPending()
      || (typeof isSavedPageArchivePending === 'function' && isSavedPageArchivePending())
      || State.isRecoveryRequired?.()) return false;
  const plan = planSavedTabReturnMutation(review, action, now);
  if (!plan) return false;

  const transaction = { review, action, opener };
  savedTabReturnMutationPending = transaction;
  if (!setSavedTabReturnMutationBusy(review, opener, true)) {
    savedTabReturnMutationPending = null;
    return false;
  }

  const target = resolveSavedTabReturnMutationTarget(review);
  if (!target) {
    requestAnimationFrame(() => {
      if (savedTabReturnMutationPending !== transaction) return;
      savedTabReturnMutationPending = null;
      setSavedTabReturnMutationBusy(review, opener, false);
      toast(tr('detail.changed'), { danger: true, duration: 6000 });
      focusSavedTabReturnMutationOpener(opener);
    });
    return false;
  }

  try {
    State.snapshot(tr(plan.historyKey));
    if (plan.kind === 'favorite') {
      target.item.favorite = plan.value;
    } else if (plan.kind === 'read-later') {
      if (plan.removing) {
        delete target.item.readLaterAt;
        delete target.item.readAt;
      } else {
        target.item.readLaterAt = plan.timestamp;
        delete target.item.readAt;
      }
    } else if (plan.markingUnread) {
      delete target.item.readAt;
    } else {
      target.item.readAt = plan.timestamp;
    }
  } catch (error) {
    if (savedTabReturnMutationPending === transaction) savedTabReturnMutationPending = null;
    setSavedTabReturnMutationBusy(review, opener, false);
    State.requireRecovery?.();
    if (typeof showStateRecoveryRequired === 'function') showStateRecoveryRequired(error);
    return false;
  }

  try {
    await State.persistNow();
  } catch (error) {
    if (savedTabReturnMutationPending === transaction) savedTabReturnMutationPending = null;
    setSavedTabReturnMutationBusy(review, opener, false);
    if (State.isRecoveryRequired?.() && typeof showStateRecoveryRequired === 'function') {
      showStateRecoveryRequired(error);
    }
    return false;
  }

  if (savedTabReturnMutationPending !== transaction) {
    setSavedTabReturnMutationBusy(review, opener, false);
    return false;
  }
  savedTabReturnMutationPending = null;
  setSavedTabReturnMutationBusy(review, opener, false);
  renderBoard();
  toast(tr(plan.successKey), receipt || {});
  return true;
}

function reportSavedTabReturnMutationUnavailable(opener) {
  toast(tr('detail.changed'), { danger: true, duration: 6000 });
  requestAnimationFrame(() => focusSavedTabReturnMutationOpener(opener));
  return false;
}

// `receipt` adds toast options to the success receipt; the Library page passes
// { undo: true, sub } so its receipts offer Undo.
async function toggleFavorite(it, opener = null, receipt = null) {
  const context = createSavedTabReturnMutationContext(it);
  if (!context) return reportSavedTabReturnMutationUnavailable(opener);
  return commitSavedTabReturnMutation(context, 'favorite', opener, Date.now(), receipt);
}

// Read Later is additive metadata on the existing tab item. Keeping the item in
// its original group preserves every legacy import and lets this surface act as
// a cross-space queue rather than another storage silo.
async function toggleReadLater(it, opener = null, receipt = null) {
  const context = createSavedTabReturnMutationContext(it);
  if (!context) return reportSavedTabReturnMutationUnavailable(opener);
  return commitSavedTabReturnMutation(context, 'read-later', opener, Date.now(), receipt);
}

async function toggleReadStatus(it, opener = null, receipt = null) {
  const context = createSavedTabReturnMutationContext(it);
  if (!context) return reportSavedTabReturnMutationUnavailable(opener);
  return commitSavedTabReturnMutation(context, 'read-status', opener, Date.now(), receipt);
}

// Shared empty-state system. The reference image defines these as calm starting
// points, not decorative placeholders: every state explains why it is empty and
// exposes no more than two actions that enter an existing product flow.
const SYSTEM_EMPTY_ICONS = {
  inbox: `<svg viewBox="0 0 64 64" fill="none"><path d="M14 31h36l5 19H9l5-19Z" fill="currentColor" opacity=".14"/><path d="M17 31l5-17h20l5 17" stroke="currentColor" stroke-width="2.4" stroke-linejoin="round"/><path d="M10 31h44l-3 20H13l-3-20Z" stroke="currentColor" stroke-width="2.4" stroke-linejoin="round"/><path d="M10 37h13a9 9 0 0018 0h13" stroke="currentColor" stroke-width="2.4" stroke-linejoin="round"/></svg>`,
  space: `<svg viewBox="0 0 64 64" fill="none"><path d="M9 21h18l5 6h23v25H9V21Z" fill="currentColor" opacity=".15"/><path d="M9 18h18l5 6h23v28H9V18Z" stroke="currentColor" stroke-width="2.4" stroke-linejoin="round"/><path d="M32 32v12M26 38h12" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"/></svg>`,
  search: `<svg viewBox="0 0 64 64" fill="none"><circle cx="27" cy="27" r="17" fill="currentColor" opacity=".12"/><circle cx="27" cy="27" r="17" stroke="currentColor" stroke-width="3"/><path d="m40 40 13 13" stroke="currentColor" stroke-width="4" stroke-linecap="round"/></svg>`,
  read: `<svg viewBox="0 0 64 64" fill="none"><path d="M19 9h26v46L32 47 19 55V9Z" fill="currentColor" opacity=".15"/><path d="M19 9h26v46L32 47 19 55V9Z" stroke="currentColor" stroke-width="2.5" stroke-linejoin="round"/></svg>`,
  favorites: `<svg viewBox="0 0 64 64" fill="none"><path d="m32 8 7 15 17 2-12 12 3 17-15-8-15 8 3-17L8 25l17-2 7-15Z" fill="currentColor" opacity=".16"/><path d="m32 8 7 15 17 2-12 12 3 17-15-8-15 8 3-17L8 25l17-2 7-15Z" stroke="currentColor" stroke-width="2.4" stroke-linejoin="round"/></svg>`,
  trash: `<svg viewBox="0 0 64 64" fill="none"><path d="M17 19h30l-3 37H20l-3-37Z" fill="currentColor" opacity=".13"/><path d="M17 19h30l-3 37H20l-3-37Z" stroke="currentColor" stroke-width="2.4" stroke-linejoin="round"/><path d="M13 19h38M25 19v-7h14v7M27 28v18M37 28v18" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"/></svg>`,
  archive: `<svg viewBox="0 0 64 64" fill="none"><path d="M11 20h42v34H11V20Z" fill="currentColor" opacity=".13"/><path d="M11 20h42v34H11V20ZM8 11h48v9H8v-9Z" stroke="currentColor" stroke-width="2.4" stroke-linejoin="round"/><path d="M25 31h14" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"/></svg>`,
  library: `<svg viewBox="0 0 64 64" fill="none"><path d="M25 39 19 45a9 9 0 01-13-13l9-9a9 9 0 0113 0" stroke="currentColor" stroke-width="2.7" stroke-linecap="round"/><path d="m39 25 6-6a9 9 0 0113 13l-9 9a9 9 0 01-13 0" stroke="currentColor" stroke-width="2.7" stroke-linecap="round"/><path d="m23 41 18-18" stroke="currentColor" stroke-width="2.7" stroke-linecap="round"/></svg>`,
};
let _systemEmptySeq = 0;

function buildSystemEmptyState({ kind = 'library', title, body, actions = [], note = '', compact = false } = {}) {
  const safeKind = Object.prototype.hasOwnProperty.call(SYSTEM_EMPTY_ICONS, kind) ? kind : 'library';
  const section = document.createElement('section');
  const titleId = `system-empty-title-${++_systemEmptySeq}`;
  section.className = 'system-empty' + (compact ? ' compact' : '');
  section.dataset.kind = safeKind;
  section.setAttribute('aria-labelledby', titleId);
  section.innerHTML = `
    <div class="system-empty-visual" aria-hidden="true"><span>${SYSTEM_EMPTY_ICONS[safeKind]}</span><i></i><i></i></div>
    <div class="system-empty-copy">
      <h2 id="${titleId}">${esc(title || '')}</h2>
      <p>${esc(body || '')}</p>
      <div class="system-empty-actions"></div>
      ${note ? `<div class="system-empty-note"><span aria-hidden="true">✓</span>${esc(note)}</div>` : ''}
    </div>`;
  const actionHost = section.querySelector('.system-empty-actions');
  actions.filter(action => action && action.label && typeof action.run === 'function').slice(0, 2).forEach((action, index) => {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = (index === 0 ? 'btn-primary' : 'btn-secondary') + ' system-empty-action';
    if (action.hasPopup) {
      button.setAttribute('aria-haspopup', action.hasPopup === true ? 'menu' : action.hasPopup);
      button.setAttribute('aria-expanded', 'false');
    }
    if (action.icon) {
      const icon = document.createElement('span');
      icon.className = 'system-empty-action-icon';
      icon.setAttribute('aria-hidden', 'true');
      icon.textContent = action.icon;
      button.appendChild(icon);
    }
    const label = document.createElement('span');
    label.textContent = action.label;
    button.appendChild(label);
    button.onclick = async () => {
      if (button.disabled) return;
      try {
        const outcome = action.run(button);
        if (outcome && typeof outcome.then === 'function') {
          button.disabled = true;
          await outcome;
        }
      }
      catch (error) { console.error(error); toast(error?.message || tr('search.error'), { danger: true }); }
      finally { if (button.isConnected) button.disabled = false; }
    };
    actionHost.appendChild(button);
  });
  if (!actionHost.children.length) actionHost.remove();
  return section;
}

function buildEmptySpaceState(cat) {
  const workspace = activeWs();
  const createGroup = {
    label: tr('empty.createGroup'),
    icon: '+',
    run: opener => openIdentityEditor('group', 'create', {
      workspaceId: workspace?.id,
      spaceId: cat?.id,
    }, opener),
  };
  const addSave = { label: tr('empty.addSave'), icon: '↗', run: () => openCommandPalette() };
  return buildSystemEmptyState({
    kind: 'space',
    title: tr('empty.spaceTitle', { space: cat?.name || tr('search.space') }),
    body: tr('empty.spaceBody'),
    actions: cat?.groups?.length ? [addSave, createGroup] : [createGroup, addSave],
    note: tr('empty.localNote'),
  });
}

function openLibrarySurface(mode) {
  const ws = activeWs();
  if (!ws) return;
  const normalized = LIBRARY_MODES.includes(mode) ? mode : 'all';
  Router.navigate({ type: 'library', wsId: ws.id, mode: normalized, query: {} }, { persist: false });
}

// ── Library page (2026-11 canvas) ─────────────────────────────────
// All links, Favorites and Read later are one page: a view switch whose pill
// slides and whose counts roll, the reading-status switch in Read later, one
// filter field and the sort, then the saved pages as quiet rows in one card. A
// highlight glides to the row under the pointer or keyboard focus, and the
// row's actions (Details, Favorite, Read later, Archive) show on hover; at
// phone width and on touch screens they fold into the row's More menu. Every
// write is the same receipt-gated transaction as before; on this page its
// receipt offers Undo.

const LIBRARY_PATHS = {
  star: 'M7.5 1.8l1.7 3.45 3.8.55-2.75 2.68.65 3.78-3.4-1.79-3.4 1.79.65-3.78L2 5.8l3.8-.55L7.5 1.8z',
  later: 'M4 2.2h7a1 1 0 0 1 1 1V13l-4.5-2.55L3 13V3.2a1 1 0 0 1 1-1z',
  laterLines: 'M5.3 5.4h4.4M5.3 7.6h3.1',
  archive: 'M2.8 2.5h9.4a.8.8 0 0 1 .8.8v1.4a.8.8 0 0 1-.8.8H2.8a.8.8 0 0 1-.8-.8V3.3a.8.8 0 0 1 .8-.8zM3 5.5V12a1 1 0 0 0 1 1h7a1 1 0 0 0 1-1V5.5M6 8h3',
  go: 'M5 10 10 5M5.8 5H10v4.2',
  check: 'M3.5 8l2.8 2.8L11.6 5',
  close: 'M4 4l7 7M11 4l-7 7',
  chevron: 'M4 6l3.5 3.5L11 6',
  search: 'M6.6 11.2a4.6 4.6 0 1 0 0-9.2 4.6 4.6 0 0 0 0 9.2zM9.9 9.9l2.8 2.8',
  link: 'M6.2 8.8a2.4 2.4 0 0 0 3.4 0l2.5-2.5a2.4 2.4 0 1 0-3.4-3.4l-1 1M8.8 6.2a2.4 2.4 0 0 0-3.4 0L2.9 8.7a2.4 2.4 0 1 0 3.4 3.4l1-1',
};
const LIBRARY_MODE_LABELS = { all: 'library.all', favorites: 'nav.favorites', 'read-later': 'nav.readLater' };

function librarySvg(name, size = 16, stroke = 1.4, cls = '') {
  return `<svg${cls ? ` class="${cls}"` : ''} width="${size}" height="${size}" viewBox="0 0 15 15" fill="none" stroke="currentColor" stroke-width="${stroke}" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${LIBRARY_PATHS[name] || ''}"/></svg>`;
}

// The bookmark keeps its two text lines as their own path, so the filled
// (queued) mark can draw them in white.
function libraryLaterSvg(size = 17, cls = '') {
  return `<svg${cls ? ` class="${cls}"` : ''} width="${size}" height="${size}" viewBox="0 0 15 15" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path class="lib-bm" d="${LIBRARY_PATHS.later}"/><path class="lib-bm-lines" d="${LIBRARY_PATHS.laterLines}" stroke-width="1.25"/></svg>`;
}

function isLibraryPageActive() {
  return !activeSearch && !activeCalendar && !activeGroupPage
    && LIBRARY_LEDGER_MODES.includes(activeLibraryMode) && !!activeWs();
}

// What the last paint showed, so counts roll and rows animate only when
// something changed; `fx` names the row control whose write is landing, and
// `holdRender` keeps a leaving row on screen until it has folded away.
function libraryPageState(wsId) {
  if (!libraryPageSession || libraryPageSession.wsId !== wsId) {
    libraryPageSession = { wsId, mode: null, counts: null, viewKey: null, query: null, seen: null, fx: null, holdRender: false };
  }
  return libraryPageSession;
}

// The view switch counts: every saved page, the favourites, and the unread
// Read later queue.
function libraryModeCounts(ws) {
  const counts = { all: 0, favorites: 0, 'read-later': 0 };
  collectWorkspaceTabs(ws).forEach(({ item }) => {
    counts.all += 1;
    if (item.favorite) counts.favorites += 1;
    if (item.readLaterAt && !item.readAt) counts['read-later'] += 1;
  });
  return counts;
}

// A count that changed rolls to its new value, using the Inbox count's roll.
// The resting position always shows the new number.
function libraryRollMarkup(count, previous) {
  if (previous == null || previous === count) {
    return `<span class="ibx-roll"><span class="ibx-roll-stack"><span>${count}</span></span></span>`;
  }
  const up = count > previous;
  const digits = up ? `<span>${previous}</span><span>${count}</span>` : `<span>${count}</span><span>${previous}</span>`;
  return `<span class="ibx-roll"><span class="ibx-roll-stack is-${up ? 'up' : 'down'}">${digits}</span></span>`;
}

// The filter's match inside a title, marked for the highlight.
function libraryTitleMarkup(title, query) {
  const text = String(title || '');
  const needle = String(query || '').trim().toLocaleLowerCase();
  const lower = text.toLocaleLowerCase();
  const at = needle && lower.length === text.length ? lower.indexOf(needle) : -1;
  if (at < 0) return esc(text);
  return `${esc(text.slice(0, at))}<mark class="lib-hit">${esc(text.slice(at, at + needle.length))}</mark>${esc(text.slice(at + needle.length))}`;
}

function libraryPageRoot() {
  return document.querySelector('#board > .lib');
}

function restartLibraryMotion(el, cls) {
  if (!el) return;
  el.classList.remove(cls);
  void el.offsetWidth;
  el.classList.add(cls);
}

// The highlight behind the rows moves to the row under the pointer or focus.
// It appears in place, then glides between rows.
function placeLibraryGlide(page, row) {
  const glide = page?.querySelector('.lib-glide');
  if (!glide) return;
  if (!row || !row.isConnected || row.classList.contains('is-gone')) {
    glide.classList.remove('is-on');
    if (libraryPageSession) libraryPageSession.glideId = null;
    return;
  }
  const appearing = !glide.classList.contains('is-on');
  if (appearing) glide.classList.add('is-jump');
  glide.style.setProperty('--lib-y', `${row.offsetTop}px`);
  glide.style.setProperty('--lib-h', `${row.offsetHeight}px`);
  if (appearing) {
    void glide.offsetWidth;
    glide.classList.remove('is-jump');
  }
  glide.classList.add('is-on');
  if (libraryPageSession) libraryPageSession.glideId = row.dataset.id || null;
}

function pressLibraryGlide() {
  restartLibraryMotion(libraryPageRoot()?.querySelector('.lib-glide.is-on .lib-gi'), 'is-press');
}

// A row that leaves this view after an accepted write: its control shows the
// new state, a read tick fills first, then the row folds away.
function foldLibraryRow(itemId, opener = null) {
  const page = libraryPageRoot();
  const row = page && itemId ? page.querySelector(`.lib-row[data-id="${CSS.escape(String(itemId))}"]`) : null;
  if (!row || planReducedMotion()) return Promise.resolve(false);
  const control = opener?.isConnected && row.contains(opener) && opener.hasAttribute('aria-pressed') ? opener : null;
  if (control) {
    const pressed = control.getAttribute('aria-pressed') !== 'true';
    control.classList.toggle('is-on', pressed);
    control.setAttribute('aria-pressed', String(pressed));
    if (pressed && control.classList.contains('lib-check')) restartLibraryMotion(control, 'is-tick');
  }
  const tick = control?.classList.contains('lib-check') && control.classList.contains('is-on');
  return new Promise(resolve => {
    setTimeout(() => {
      if (!row.isConnected) { resolve(false); return; }
      row.style.height = `${row.offsetHeight}px`;
      void row.offsetWidth;
      row.classList.add('is-gone');
      if (libraryPageSession?.glideId === row.dataset.id) placeLibraryGlide(page, null);
      setTimeout(() => resolve(true), 300);
    }, tick ? 220 : 0);
  });
}

function buildLibraryEmpty({ icon, done = false, title, actions = [] }) {
  const box = document.createElement('div');
  box.className = 'lib-empty';
  box.setAttribute('role', 'status');
  box.innerHTML = `
    <span class="lib-eico${done ? ' is-done' : ''}" aria-hidden="true">${icon}</span>
    <h2 class="lib-etitle">${esc(title)}</h2>
    <div class="lib-eacts"></div>`;
  const host = box.querySelector('.lib-eacts');
  actions.forEach((action, index) => {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = `lib-ebtn${index === 0 ? ' is-primary' : ''}`;
    button.dataset.libFocus = `empty:${index}`;
    button.textContent = action.label;
    button.addEventListener('click', () => action.run(button));
    host.appendChild(button);
  });
  if (!actions.length) host.remove();
  return box;
}

function focusLibraryLedgerTarget(itemId, action = 'open') {
  const escaped = itemId && typeof CSS !== 'undefined' && typeof CSS.escape === 'function'
    ? CSS.escape(String(itemId))
    : String(itemId || '').replace(/["\\]/g, '\\$&');
  const actionClass = action === 'favorite'
    ? '.library-star'
    : action === 'status'
      ? '.read-later-status'
      : action === 'details'
        ? '.library-details'
        : action === 'later'
          ? '.lib-later'
          : action === 'more'
            ? '.library-more'
            : '.library-primary';
  const target = escaped
    ? document.querySelector(`.library-row[data-id="${escaped}"] ${actionClass}`)
    : null;
  const fallback = target
    || document.querySelector('.library-row .library-primary')
    || document.querySelector('.lib-empty .lib-ebtn')
    || document.querySelector('.lib-field input')
    || document.getElementById('library-title');
  if (!fallback || typeof fallback.focus !== 'function') return false;
  try { fallback.focus({ preventScroll: true }); } catch { try { fallback.focus(); } catch { return false; } }
  if (typeof fallback.scrollIntoView === 'function') fallback.scrollIntoView({ block: 'nearest' });
  return true;
}

async function runLibraryLedgerMutation(rows, index, mutation, { itemRemains = false, action = 'open', fx = '', opener = null } = {}) {
  const stateRef = activeLibraryState;
  const mode = activeLibraryMode;
  const itemId = rows[index]?.item?.id || '';
  const fallbackId = rows[index + 1]?.item?.id || rows[index - 1]?.item?.id || '';
  const session = libraryPageSession;
  if (session) {
    session.fx = fx ? { id: String(itemId), kind: fx } : null;
    session.holdRender = !itemRemains;
  }
  let changed = false;
  try {
    changed = await mutation();
  } finally {
    if (session && !itemRemains) {
      if (changed !== false) await foldLibraryRow(itemId, opener);
      session.holdRender = false;
      renderBoard();
    }
    if (session) session.fx = null;
  }
  if (changed === false) return false;
  requestAnimationFrame(() => {
    if (activeLibraryState !== stateRef || activeLibraryMode !== mode) return;
    focusLibraryLedgerTarget(itemRemains ? itemId : fallbackId, itemRemains ? action : 'open');
  });
  return true;
}

// One saved page as a quiet row. The title is the Open action and covers the
// row; Details, the markers and Archive show on hover or focus. `paint` carries
// the filter text, the row's entry motion and the control whose write landed.
function buildLibraryLedgerRow(rowData, state, rows, index, paint = {}) {
  const item = rowData.item;
  const model = libraryLedgerRowModel(rowData, state.mode);
  const recovery = createLibraryRecoveryContext(rowData, state);
  const later = state.mode === 'read-later';
  const key = esc(model.id);
  const fx = paint.fx && paint.fx.id === model.id ? paint.fx.kind : '';
  const row = document.createElement('div');
  row.className = 'library-row lib-row' + (later && item.readAt ? ' is-read' : '') + (paint.motion ? ` ${paint.motion}` : '');
  row.setAttribute('role', 'listitem');
  row.dataset.id = model.id;
  row.dataset.libraryFocusKey = recovery?.focusKey || libraryRowFocusKey(rowData, state);
  if (paint.delay) row.style.setProperty('--lib-d', `${paint.delay}ms`);
  const timestamp = Number(later ? item.readLaterAt : item.createdAt);
  const timeCopy = model.age
    ? tr(later ? 'library.queuedWhen' : 'library.savedWhen', { time: model.age })
    : '';
  const shortTime = Number.isFinite(timestamp) && timestamp > 0 ? inboxSavedLabel(timestamp) : '';
  const favoriteLabel = tr(item.favorite ? 'itemAction.removeFavorite' : 'itemAction.addFavorite');
  const laterLabel = tr(item.readLaterAt ? 'itemAction.removeReadLater' : 'itemAction.saveReadLater');
  const readStatusAction = later
    ? `<button class="read-later-status lib-check${item.readAt ? ' is-on' : ''}${fx === 'read' ? ' is-tick' : ''}" data-return-marker="read-status" data-lib-focus="check:${key}" type="button" aria-pressed="${!!item.readAt}" title="${esc(model.statusLabel)}" aria-label="${esc(model.statusLabel)}"><span class="lib-ring">${librarySvg('check', 13, 2.4)}</span></button>`
    : '';
  const burst = fx === 'favorite-on'
    ? `<span class="lib-burst" aria-hidden="true">${INBOX_BURST_RAYS.map(angle => `<span class="ibx-ray" style="--a:${angle}deg"><span class="lib-pt"></span></span>`).join('')}</span>`
    : '';
  const toggleAction = later
    ? ''
    : `<button class="library-star lib-ai lib-star${item.favorite ? ' is-on' : ''}${fx === 'favorite-on' ? ' is-pop' : ''}" data-return-marker="favorite" data-lib-focus="star:${key}" type="button" aria-pressed="${!!item.favorite}" title="${esc(favoriteLabel)}" aria-label="${esc(favoriteLabel)}">${librarySvg('star', 18, 1.35)}${burst}</button>`;
  const marks = later ? '' : `${item.favorite ? `<span class="lib-mark is-star">${librarySvg('star', 13, 1.2)}</span>` : ''}${item.readLaterAt ? `<span class="lib-mark is-later">${libraryLaterSvg(13)}</span>` : ''}`;
  const dot = reminderDotColor(rowData.group?.color || null);
  row.innerHTML = `
    ${readStatusAction}
    ${inboxFavMarkup(item)}
    <div class="library-copy lib-copy">
      <button class="library-primary lib-open" data-lib-focus="open:${key}" type="button" aria-label="${esc(tr('library.openPageFor', { title: model.title }))}"><span class="library-title lib-tt">${libraryTitleMarkup(model.title, paint.query)}</span>${librarySvg('go', 13, 1.9, 'lib-go')}</button>
      <span class="lib-meta"><span class="lib-dot" style="--dot:${esc(dot)}" aria-hidden="true"></span><span class="library-destination">${esc(model.destination)}</span><span class="library-url">${esc(planSortMeta(item).domain || model.url)}</span>${marks || shortTime ? `<span class="lib-meta-when" aria-hidden="true">${marks}${shortTime ? `<span>${esc(shortTime)}</span>` : ''}</span>` : ''}</span>
    </div>
    <span class="lib-when">${marks}${shortTime ? `<time${Number.isFinite(timestamp) && timestamp > 0 ? ` datetime="${new Date(timestamp).toISOString()}"` : ''}><span class="sr-only">${esc(timeCopy)}</span><span aria-hidden="true">${esc(shortTime)}</span></time>` : ''}</span>
    <div class="lib-acts">
      <button class="library-details lib-text" data-lib-focus="details:${key}" type="button" aria-label="${esc(tr('library.viewDetailsFor', { title: model.title }))}">${esc(model.detailsLabel)}</button>
      ${toggleAction}
      <button class="lib-ai lib-later${item.readLaterAt ? ' is-on' : ''}${fx === 'later-on' ? ' is-sent' : ''}" data-return-marker="read-later" data-lib-focus="later:${key}" type="button" aria-pressed="${!!item.readLaterAt}" title="${esc(laterLabel)}" aria-label="${esc(laterLabel)}">${libraryLaterSvg(18)}${fx === 'later-on' ? libraryLaterSvg(13, 'lib-fly') : ''}</button>
      <button class="lib-ai lib-archive" data-item-archive="row" data-lib-focus="archive:${key}" type="button" title="${esc(tr('itemAction.archive'))}" aria-label="${esc(tr('library.archiveNamed', { title: model.title }))}">${librarySvg('archive', 17, 1.4)}</button>
      <span class="lib-cap" aria-hidden="true">${esc(model.openLabel)}<span class="lib-kbd">↵</span></span>
    </div>
    <button class="library-more lib-ai lib-more" data-return-marker="more" data-item-archive="menu" data-lib-focus="more:${key}" type="button" aria-haspopup="menu" title="${esc(tr('library.moreActions', { title: model.title }))}" aria-label="${esc(tr('library.moreActions', { title: model.title }))}">${inboxDotsIcon(17)}</button>`;
  bindInboxFavicons(row);

  const primary = row.querySelector('.library-primary');
  const details = row.querySelector('.library-details');
  primary.onclick = () => {
    pressLibraryGlide();
    activateLibraryRecovery(recovery, 'open', primary);
  };
  details.onclick = () => activateLibraryRecovery(recovery, 'details', details);

  const receipt = { undo: true, sub: planSortMeta(item).domain || model.url };
  const shown = element => !!element && element.isConnected && element.getClientRects().length > 0;
  const toggleFavoriteFrom = opener => runLibraryLedgerMutation(rows, index, () => toggleFavorite(item, opener, receipt), {
    itemRemains: state.mode !== 'favorites' || !item.favorite,
    action: opener === favorite ? 'favorite' : (opener === more && shown(more) ? 'more' : 'open'),
    fx: item.favorite ? '' : 'favorite-on',
    opener,
  });
  const toggleReadLaterFrom = opener => runLibraryLedgerMutation(rows, index, () => toggleReadLater(item, opener, receipt), {
    itemRemains: state.mode !== 'read-later',
    action: opener === laterButton ? 'later' : (opener === more && shown(more) ? 'more' : 'open'),
    fx: item.readLaterAt ? '' : 'later-on',
    opener,
  });
  const favorite = row.querySelector('.library-star');
  if (favorite) favorite.onclick = () => toggleFavoriteFrom(favorite);
  const readStatus = row.querySelector('.read-later-status');
  if (readStatus) readStatus.onclick = () => {
    runLibraryLedgerMutation(rows, index, () => toggleReadStatus(item, readStatus, receipt), {
      itemRemains: state.status === 'all', action: 'status', fx: item.readAt ? '' : 'read', opener: readStatus,
    });
  };
  const laterButton = row.querySelector('.lib-later');
  laterButton.onclick = () => toggleReadLaterFrom(laterButton);
  const archiveButton = row.querySelector('.lib-archive');
  archiveButton.onclick = () => runLibraryLedgerMutation(rows, index, () => archiveSavedPage(item, archiveButton));

  // More, right-click and Shift+F10 open the row menu: Read later and Archive,
  // plus whatever the row is not showing (Details and Favorite at phone width
  // and on touch screens, where the hover actions fold away).
  const more = row.querySelector('.library-more');
  bindBoardItemContextMenu(row, opener => {
    const owner = shown(opener) ? opener : (shown(more) ? more : primary);
    const readLaterAction = () => toggleReadLaterFrom(owner);
    const archiveAction = () => runLibraryLedgerMutation(rows, index, () => archiveSavedPage(item, owner));
    const folded = shown(row.querySelector('.lib-acts')) ? [] : [
      { text: model.detailsLabel, icon: cmIcons.detail, action: () => activateLibraryRecovery(recovery, 'details', owner) },
      ...(favorite ? [{ text: favoriteLabel, icon: cmIcons.favorite, action: () => toggleFavoriteFrom(owner) }] : []),
    ];
    const actions = [
      ...folded,
      {
        text: laterLabel,
        icon: item.readLaterAt ? cmIcons.delete : cmIcons.readLater,
        action: readLaterAction,
      },
      { sep: true },
      { text: tr('itemAction.archive'), icon: cmIcons.archive, action: archiveAction },
    ];
    return actions;
  }, { menuButton: more });
  return row;
}

function bindLibraryQueryControl(input, applyQuery) {
  if (!input || typeof applyQuery !== 'function') return false;
  let committedValue = String(input.value ?? '');
  const commit = value => {
    const nextValue = String(value ?? '');
    if (nextValue === committedValue) return false;
    committedValue = nextValue;
    applyQuery(nextValue);
    return true;
  };
  input.oncompositionstart = () => {
    input.dataset.libraryComposing = 'true';
    delete input.dataset.libraryCompositionValue;
    return true;
  };
  input.oninput = event => {
    if (event?.isComposing || input.dataset.libraryComposing === 'true') return false;
    const value = String(input.value ?? '');
    if (input.dataset.libraryCompositionValue === value) {
      delete input.dataset.libraryCompositionValue;
      return false;
    }
    delete input.dataset.libraryCompositionValue;
    return commit(value);
  };
  input.oncompositionend = () => {
    delete input.dataset.libraryComposing;
    const value = String(input.value ?? '');
    input.dataset.libraryCompositionValue = value;
    return commit(value);
  };
  input.onkeydown = event => {
    if (event?.isComposing || event?.keyCode === 229 || input.dataset.libraryComposing === 'true') return false;
    if (event?.key !== 'Escape' || !input.value) return false;
    event.preventDefault();
    input.value = '';
    delete input.dataset.libraryCompositionValue;
    commit('');
    input.blur();
    return true;
  };
  return true;
}

// Renders the Library page into #board. The page root stays across repaints of
// the same workspace, so the view switch's pill slides, the filter keeps its
// caret and a repaint keeps the scroll position; the rows are rebuilt.
function renderLibraryLedgerSurface() {
  const ws = activeWs();
  const mode = activeLibraryMode;
  if (!ws || !LIBRARY_LEDGER_MODES.includes(mode)) return false;
  if (!activeLibraryState || activeLibraryState.mode !== mode) {
    activeLibraryState = libraryStateFromRoute(mode, {});
  }
  const state = activeLibraryState;
  const session = libraryPageState(ws.id);
  hideBreadcrumb();
  const board = document.getElementById('board');
  document.body.dataset.page = 'library';
  board.classList.remove('group-page-mode', 'list-mode', 'canvas-mode', 'explorer-mode', 'timeline-mode', 'gallery-mode', 'graph-mode', 'calendar-mode', 'home-mode', 'archive-mode', 'trash-mode');
  board.classList.add('lib-mode');
  let page = libraryPageRoot();
  if (page && page.dataset.ws !== String(ws.id)) page = null;
  // A row that is leaving holds the repaint until it has folded away.
  if (session.holdRender && page) return true;
  const firstShow = !page;
  const keepScroll = firstShow ? 0 : board.scrollTop;
  const active = document.activeElement;
  const focusKey = page && active && page.contains(active)
    ? active.closest('[data-lib-focus]')?.dataset.libFocus || null
    : null;

  // Query, status and sort ride the URL (replaceState), never storage.
  const updateState = patch => {
    const current = activeLibraryState;
    if (!current) return;
    const next = libraryStateFromRoute(current.mode, {
      q: Object.prototype.hasOwnProperty.call(patch, 'query') ? patch.query : current.query,
      status: Object.prototype.hasOwnProperty.call(patch, 'status') ? patch.status : current.status,
      sort: Object.prototype.hasOwnProperty.call(patch, 'sort') ? patch.sort : current.sort,
    });
    Object.assign(current, next);
    boardDetailItemId = null;
    Router.sync({ replace: true });
  };

  // The heading, the view switch with its counts, the reading status, the
  // filter and the sort, from the current route state.
  const sync = () => {
    const root = libraryPageRoot();
    const current = activeLibraryState;
    const workspace = activeWs();
    if (!root || !current || !workspace) return;
    const s = libraryPageSession || session;
    const currentMode = current.mode;
    const counts = libraryModeCounts(workspace);
    const previous = s.counts;
    root.dataset.mode = currentMode;
    const title = root.querySelector('.lib-title');
    title.textContent = tr(currentMode === 'favorites' ? 'nav.favorites' : currentMode === 'read-later' ? 'nav.readLater' : 'nav.allLinks');
    if (s.mode != null && s.mode !== currentMode) restartLibraryMotion(title, 'is-swap');
    root.querySelector('#library-sub').textContent = tr(currentMode === 'favorites' ? 'library.subtitleFavorites' : currentMode === 'read-later' ? 'readLater.subtitle' : 'library.subtitleAll');
    const modes = root.querySelector('.lib-modes');
    modes.setAttribute('aria-label', tr('library.view'));
    modes.style.setProperty('--lib-i', String(LIBRARY_LEDGER_MODES.indexOf(currentMode)));
    modes.querySelectorAll('[data-lib-mode]').forEach(button => {
      const id = button.dataset.libMode;
      const label = tr(LIBRARY_MODE_LABELS[id]);
      button.setAttribute('aria-pressed', String(id === currentMode));
      button.setAttribute('aria-label', tr('library.modeCount', { label, count: counts[id] }));
      button.querySelector('.lib-seg-label').textContent = label;
      const count = button.querySelector('.lib-cnt');
      if (!previous || previous[id] !== counts[id] || !count.firstChild) {
        count.innerHTML = libraryRollMarkup(counts[id], previous ? previous[id] : null);
      }
      // Read later's count ticks up with a bump when a row is sent to it.
      if (id === 'read-later' && s.fx?.kind === 'later-on' && previous && counts[id] > previous[id]) {
        restartLibraryMotion(count, 'is-bump');
      }
    });
    const later = currentMode === 'read-later';
    const status = root.querySelector('.lib-status');
    status.setAttribute('aria-label', tr('library.readingStatus'));
    if (status.hidden === later) {
      status.hidden = !later;
      if (later && s.mode != null) restartLibraryMotion(status, 'is-rise');
    }
    status.style.setProperty('--lib-i', String(Math.max(0, LIBRARY_READ_STATUSES.indexOf(current.status))));
    status.querySelectorAll('[data-status]').forEach(button => {
      button.textContent = tr(`library.${button.dataset.status}`);
      button.setAttribute('aria-pressed', String(button.dataset.status === current.status));
    });
    const note = root.querySelector('.library-local-note');
    note.hidden = !later;
    note.textContent = tr('library.localStorage');
    const search = root.querySelector('.lib-field input');
    search.placeholder = tr('library.filterLinks');
    search.setAttribute('aria-label', tr('library.filterLinks'));
    if (document.activeElement !== search && search.value !== current.query) {
      // A query restored from the URL starts the field's controller afresh.
      search.value = current.query;
      bindLibraryQueryControl(search, query => {
        updateState({ query });
        paint();
      });
    }
    const clear = root.querySelector('.lib-clear');
    clear.setAttribute('aria-label', tr('empty.clearSearch'));
    clear.title = tr('empty.clearSearch');
    root.querySelector('.lib-sort .sr-only').textContent = tr('library.sort');
    const sort = root.querySelector('.lib-sort select');
    [...sort.options].forEach(option => {
      option.textContent = tr(option.value === 'oldest' ? 'library.sortOldest' : option.value === 'title' ? 'library.sortTitle' : 'library.sortNewest');
    });
    sort.value = current.sort;
    s.mode = currentMode;
    s.counts = counts;
  };

  const clearFilter = () => {
    const input = libraryPageRoot()?.querySelector('.lib-field input');
    if (!input) return;
    input.value = '';
    input.dispatchEvent(new Event('input'));
    inboxFocus(input);
  };
  const setStatus = status => {
    updateState({ status });
    sync();
    paint();
    inboxFocus(libraryPageRoot()?.querySelector(`.lib-status [data-status="${status}"]`));
  };

  // The rows, the live count and the empty states. Typing in the filter
  // repaints only this.
  const paint = () => {
    const root = libraryPageRoot();
    const current = activeLibraryState;
    const workspace = activeWs();
    if (!root || !current || !workspace) return;
    const s = libraryPageSession || session;
    const list = root.querySelector('.lib-list');
    const card = root.querySelector('.lib-card');
    root.querySelector('.lib-clear').hidden = !root.querySelector('.lib-field input').value;
    const rows = libraryRowsForState(workspace, current);
    root.querySelector('.library-result-count').textContent = tr(rows.length === 1 ? 'library.resultCountOne' : 'library.resultCount', { count: rows.length });
    const viewKey = `${current.mode}|${current.status}|${current.sort}`;
    const changedView = s.viewKey != null && s.viewKey !== viewKey;
    const sameList = s.viewKey === viewKey && s.query === current.query && !!s.seen;
    list.innerHTML = '';
    card.querySelector(':scope > .lib-empty')?.remove();
    rows.forEach((row, index) => {
      // A new view rises in; a row that comes back (Undo) flashes in place.
      const motion = changedView ? 'is-rise' : (sameList && !s.seen.has(String(row.item.id)) ? 'is-back' : '');
      list.appendChild(buildLibraryLedgerRow(row, current, rows, index, {
        query: current.query,
        fx: s.fx,
        motion,
        delay: changedView ? Math.min(index, 10) * 24 : 0,
      }));
    });
    s.viewKey = viewKey;
    s.query = current.query;
    s.seen = new Set(rows.map(row => String(row.item.id)));
    if (rows.length) return;
    const unfiltered = libraryRowsForState(workspace, {
      ...current,
      query: '',
      status: current.mode === 'read-later' ? 'all' : current.status,
    });
    const browse = { label: tr('empty.browseLibrary'), run: () => openLibrarySurface('all') };
    const addSave = { label: tr('empty.addSave'), run: () => openCommandPalette() };
    let empty;
    if (!unfiltered.length) {
      if (current.mode === 'favorites') {
        empty = buildLibraryEmpty({ icon: librarySvg('star', 28, 1.2), title: tr('empty.favoritesTitle'), actions: [browse] });
      } else if (current.mode === 'read-later') {
        empty = buildLibraryEmpty({ icon: libraryLaterSvg(26), title: tr('empty.readLaterTitle'), actions: [browse, addSave] });
      } else {
        empty = buildLibraryEmpty({
          icon: librarySvg('link', 26, 1.3),
          title: tr('empty.libraryTitle'),
          actions: [addSave, { label: tr('empty.importBookmarks'), run: () => importBookmarks() }],
        });
      }
    } else if (current.query) {
      empty = buildLibraryEmpty({
        icon: librarySvg('search', 26, 1.5),
        title: tr('empty.searchTitle', { query: current.query }),
        actions: [{ label: tr('empty.clearSearch'), run: clearFilter }],
      });
    } else if (current.status === 'unread') {
      empty = buildLibraryEmpty({
        icon: librarySvg('check', 28, 2.2),
        done: true,
        title: tr('library.allCaughtUp'),
        actions: [{ label: tr('empty.showAll'), run: () => setStatus('all') }],
      });
    } else {
      empty = buildLibraryEmpty({
        icon: libraryLaterSvg(26),
        title: tr('library.nothingRead'),
        actions: [{ label: tr('library.showUnread'), run: () => setStatus('unread') }],
      });
    }
    card.appendChild(empty);
  };

  if (!page) {
    board.innerHTML = '';
    page = document.createElement('div');
    page.className = 'lib';
    page.dataset.ws = String(ws.id);
    page.innerHTML = `
      <p class="sr-only library-result-count" aria-live="polite"></p>
      <header class="lib-hd">
        <h1 class="lib-title" id="library-title" tabindex="-1"></h1>
        <p class="sr-only" id="library-sub"></p>
      </header>
      <div class="lib-tools">
        <div class="lib-seg lib-modes" role="group">
          <span class="lib-thumb" aria-hidden="true"></span>
          ${LIBRARY_LEDGER_MODES.map(id => `<button type="button" class="lib-seg-btn" data-lib-mode="${id}" data-lib-focus="mode:${id}"><span class="lib-seg-label"></span><span class="lib-cnt" aria-hidden="true"></span></button>`).join('')}
        </div>
        <div class="lib-seg lib-status" role="group" hidden>
          <span class="lib-thumb" aria-hidden="true"></span>
          ${LIBRARY_READ_STATUSES.map(id => `<button type="button" class="lib-seg-btn" data-status="${id}" data-lib-focus="status:${id}"></button>`).join('')}
        </div>
        <span class="lib-gap" aria-hidden="true"></span>
        <div class="lib-field">
          ${librarySvg('search', 16, 1.5)}
          <input type="search" autocomplete="off" spellcheck="false" data-lib-focus="filter">
          <button type="button" class="lib-clear" data-lib-focus="clear" hidden>${librarySvg('close', 14, 1.8)}</button>
        </div>
        <label class="lib-sort"><span class="sr-only"></span><select data-lib-focus="sort">${LIBRARY_SORTS.map(id => `<option value="${id}"></option>`).join('')}</select>${librarySvg('chevron', 14, 1.6)}</label>
      </div>
      <p class="library-local-note" hidden>${esc(tr('library.localStorage'))}</p>
      <div class="lib-card">
        <span class="lib-glide" aria-hidden="true"><span class="lib-gi"></span></span>
        <div class="library-list lib-list" role="list" aria-labelledby="library-title" aria-describedby="library-sub"></div>
      </div>`;
    board.appendChild(page);

    const search = page.querySelector('.lib-field input');
    bindLibraryQueryControl(search, query => {
      updateState({ query });
      paint();
    });
    // Down (or Enter) from the filter goes to the first row. An Escape that
    // just cleared the filter stops here, so it does not also leave the page.
    search.addEventListener('keydown', event => {
      if (event.isComposing || event.keyCode === 229) return;
      if (event.key === 'Escape' && event.defaultPrevented) {
        event.stopPropagation();
        return;
      }
      if (event.key !== 'ArrowDown' && event.key !== 'Enter') return;
      const first = libraryPageRoot()?.querySelector('.lib-row .library-primary');
      if (!first) return;
      event.preventDefault();
      inboxFocus(first);
    });
    page.querySelector('.lib-clear').addEventListener('click', clearFilter);
    const sort = page.querySelector('.lib-sort select');
    sort.onchange = () => { updateState({ sort: sort.value }); paint(); };
    page.querySelectorAll('[data-lib-mode]').forEach(button => {
      button.addEventListener('click', () => {
        if (activeLibraryMode !== button.dataset.libMode) openLibrarySurface(button.dataset.libMode);
      });
    });
    page.querySelectorAll('.lib-status [data-status]').forEach(button => {
      button.addEventListener('click', () => {
        if (activeLibraryState?.status !== button.dataset.status) setStatus(button.dataset.status);
      });
    });

    // The highlight follows the pointer and the keyboard.
    const card = page.querySelector('.lib-card');
    card.addEventListener('pointerover', event => {
      const row = event.target.closest?.('.lib-row');
      if (row) placeLibraryGlide(page, row);
    });
    card.addEventListener('pointerleave', () => {
      if (!card.contains(document.activeElement)) placeLibraryGlide(page, null);
    });
    card.addEventListener('focusin', event => placeLibraryGlide(page, event.target.closest?.('.lib-row') || null));
    card.addEventListener('focusout', event => {
      if (!card.contains(event.relatedTarget) && !card.matches(':hover')) placeLibraryGlide(page, null);
    });
    // Rows change height after a font loads, the language changes or the
    // window narrows; the highlight stays on its row.
    if (typeof ResizeObserver === 'function') {
      new ResizeObserver(() => {
        const id = libraryPageSession?.glideId;
        if (id) placeLibraryGlide(page, page.querySelector(`.lib-row[data-id="${CSS.escape(id)}"]`));
      }).observe(page.querySelector('.lib-list'));
    }
    // Up and Down move between rows, to the same control in the next row.
    page.querySelector('.lib-list').addEventListener('keydown', event => {
      if (event.ctrlKey || event.metaKey || event.altKey || event.shiftKey) return;
      if (event.key !== 'ArrowDown' && event.key !== 'ArrowUp') return;
      const row = event.target.closest?.('.lib-row');
      if (!row || event.target.tagName === 'SELECT') return;
      event.preventDefault();
      const rows = [...page.querySelectorAll('.lib-list > .lib-row:not(.is-gone)')];
      const index = rows.indexOf(row) + (event.key === 'ArrowDown' ? 1 : -1);
      if (index < 0) { inboxFocus(search); return; }
      const next = rows[index];
      if (!next) return;
      const kind = String(event.target.dataset?.libFocus || '').split(':')[0];
      const target = (kind && next.querySelector(`[data-lib-focus^="${kind}:"]`)) || next.querySelector('.library-primary');
      if (inboxFocus(target)) next.scrollIntoView({ block: 'nearest' });
    });
  }

  const viewChanged = !firstShow && session.viewKey != null
    && session.viewKey !== `${state.mode}|${state.status}|${state.sort}`;
  sync();
  paint();
  session.fx = null;
  if (viewChanged) {
    placeLibraryGlide(page, null);
    board.scrollTo({ top: 0, behavior: 'instant' });
  } else {
    // A repaint keeps the reader where they were in a long list.
    if (!firstShow && board.scrollTop !== keepScroll) board.scrollTo({ top: keepScroll, behavior: 'instant' });
    const glideId = session.glideId;
    if (glideId) placeLibraryGlide(page, page.querySelector(`.lib-row[data-id="${CSS.escape(glideId)}"]`));
  }
  if (focusKey && !page.contains(document.activeElement)) {
    inboxFocus(page.querySelector(`[data-lib-focus="${CSS.escape(focusKey)}"]`));
  }
  updateNavChrome();
  return true;
}

function renderLibrarySurface() {
  if (!activeWs() || !activeLibraryMode) return false;
  if (activeLibraryMode === 'archive') return renderArchiveSurface();
  if (activeLibraryMode === 'trash') return renderTrashSurface();
  if (activeLibraryMode === 'read-later') return renderReadLaterSurface();
  return renderLibraryLedgerSurface();
}

function renderReadLaterSurface() {
  return renderLibraryLedgerSurface();
}

function archiveEntryTitle(entry) {
  if (!entry || !entry.data) return 'Untitled';
  if (entry.kind === 'group') return entry.data.name || 'Untitled group';
  const it = entry.data;
  if (it.type === 'note') return String(it.html || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim() || 'Note';
  if (it.type === 'todo') return it.text || it.title || 'To-do';
  if (it.type === 'stack') return it.name || 'Stack';
  return it.title || dispUrl(it.url) || 'Untitled link';
}

function archiveEntryType(entry) {
  if (entry.kind === 'group') return 'groups';
  const type = entry.data?.type;
  if (type === 'note') return 'notes';
  if (type === 'todo') return 'todos';
  if (type === 'stack') return 'groups';
  return 'links';
}

function archiveEntryIcon(entry) {
  if (entry.kind === 'group') return entry.data?.symbol || '📁';
  if (entry.data?.type === 'note') return '✎';
  if (entry.data?.type === 'todo') return entry.data.done ? '✓' : '○';
  if (entry.data?.type === 'stack') return '▱';
  return '↗';
}

function archiveEntryCount(entry) {
  if (entry.kind !== 'group') return 1;
  let count = 0;
  const walk = items => (items || []).forEach(it => { count++; if (it.type === 'stack') walk(it.items); });
  walk(entry.data?.items);
  return count;
}

function archiveEntryTimestamp(entry) {
  const value = Number(entry?.at);
  return Number.isFinite(value) && value > 0 ? value : 0;
}

function focusArchivedPageRestoreTarget(itemId) {
  const escaped = itemId && typeof CSS !== 'undefined' && typeof CSS.escape === 'function'
    ? CSS.escape(String(itemId))
    : String(itemId || '').replace(/["\\]/g, '\\$&');
  const target = escaped
    ? document.querySelector(
        `.archive-row[data-archive-item-id="${escaped}"] [data-archived-page-restore="true"]`,
      )
    : null;
  const fallback = target
    || document.querySelector('.archive-shell .library-search input')
    || document.getElementById('nav-archive')
    || document.querySelector('.archive-shell h1');
  if (!fallback || typeof fallback.focus !== 'function') return false;
  try { fallback.focus({ preventScroll: true }); } catch { try { fallback.focus(); } catch { return false; } }
  if (typeof fallback.scrollIntoView === 'function') fallback.scrollIntoView({ block: 'nearest' });
  return true;
}

function focusArchivedPageRestoreReview(context) {
  const target = resolveArchivedPageRestoreTarget(context);
  const row = target
    ? [...document.querySelectorAll('.archive-row')]
        .find(candidate => candidate.__archivedPageRestoreEntry === target.entry)
    : null;
  const exact = row?.querySelector('[data-archived-page-restore="true"]') || null;
  if (!exact || typeof exact.focus !== 'function') {
    focusArchivedPageRestoreTarget('');
    return false;
  }
  try { exact.focus({ preventScroll: true }); } catch { try { exact.focus(); } catch { return false; } }
  if (typeof exact.scrollIntoView === 'function') exact.scrollIntoView({ block: 'nearest' });
  return true;
}

