function archiveDateBucket(at) {
  const value = Number(at) || 0;
  const day = new Date(value); day.setHours(0, 0, 0, 0);
  const today = new Date(); today.setHours(0, 0, 0, 0);
  const delta = Math.round((today - day) / 86400000);
  if (delta <= 0) return 'Today';
  if (delta === 1) return 'Yesterday';
  if (delta < 7) return 'This week';
  return 'Earlier';
}

// Dedicated desktop archive: the old Settings list remains as a compact
// secondary view, while this primary surface supports finding and restoring
// whole archived sessions without changing the legacy archive schema.
function renderArchiveSurface() {
  hideBreadcrumb();
  const board = document.getElementById('board');
  board.classList.remove('group-page-mode', 'list-mode', 'canvas-mode', 'explorer-mode', 'timeline-mode', 'gallery-mode', 'graph-mode', 'calendar-mode', 'home-mode');
  board.classList.add('library-mode', 'archive-mode');
  board.innerHTML = '';

  // Keep malformed legacy/import records in storage for lossless export, but
  // do not let one incomplete record prevent the rest of the archive loading.
  const allEntries = (State.get().archive || [])
    .filter(entry => entry && entry.data)
    .sort((a, b) => archiveEntryTimestamp(b) - archiveEntryTimestamp(a));
  const itemTotal = allEntries.reduce((sum, entry) => sum + archiveEntryCount(entry), 0);
  const groupTotal = allEntries.filter(entry => entry.kind === 'group').length;
  const selected = new Set();
  let query = '';
  let type = 'all';

  const shell = document.createElement('section');
  shell.className = 'library-shell archive-shell';
  shell.innerHTML = `
    <header class="library-head archive-head">
      <div>
        <h1>${esc(tr('nav.archive'))}</h1>
        <p>${esc(tr('archive.subtitle'))}</p>
      </div>
      <label class="library-search">
        <svg width="15" height="15" viewBox="0 0 16 16" fill="none" aria-hidden="true"><circle cx="6.5" cy="6.5" r="4.5" stroke="currentColor" stroke-width="1.5"/><path d="M10 10l3 3" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/></svg>
        <input type="search" placeholder="${esc(tr('archive.search'))}" aria-label="${esc(tr('archive.search'))}">
      </label>
    </header>
    <div class="archive-summary" aria-label="${esc(tr('nav.archive'))}">
      <div><strong>${allEntries.length}</strong><span>${esc(tr('archive.summary.entries', { count: allEntries.length }))}</span></div>
      <div><strong>${itemTotal}</strong><span>${esc(tr('archive.summary.items', { count: itemTotal }))}</span></div>
      <div><strong>${groupTotal}</strong><span>${esc(tr('archive.summary.groups', { count: groupTotal }))}</span></div>
      <div class="archive-local"><strong>${esc(tr('archive.summary.local'))}</strong><span>${esc(tr('archive.summary.localBody'))}</span></div>
    </div>
    <div class="archive-toolbar">
      <div class="archive-filters" role="group" aria-label="${esc(tr('nav.archive'))}">
        ${[['all','search.all'],['links','search.links'],['notes','search.notes'],['todos','search.todos'],['groups','trash.groups']].map(([value, key]) => `<button type="button" data-type="${value}" aria-pressed="${value === 'all'}" class="${value === 'all' ? 'active' : ''}">${esc(tr(key))}</button>`).join('')}
      </div>
      <div class="archive-selection" aria-live="polite">
        <span class="archive-selection-count">${esc(tr('archive.selected', { count: 0 }))}</span>
        <span class="archive-selection-route" hidden></span>
        <details class="archive-selection-destinations" hidden>
          <summary></summary>
          <ul></ul>
        </details>
        <button type="button" class="btn-primary" data-archived-page-batch-restore="true" data-archived-group-batch-restore="true" data-archived-local-item-batch-restore="true" disabled>${esc(tr('archive.restoreSelected'))}</button>
        <button type="button" class="btn-secondary archive-trash-selected" disabled>${tr('archive.moveToTrash')}</button>
      </div>
    </div>
    <div class="archive-results" aria-live="polite"></div>`;
  board.appendChild(shell);

  const results = shell.querySelector('.archive-results');
  const selectionText = shell.querySelector('.archive-selection-count');
  const selectionRoute = shell.querySelector('.archive-selection-route');
  const selectionDestinations = shell.querySelector('.archive-selection-destinations');
  const selectionDestinationSummary = selectionDestinations.querySelector('summary');
  const selectionDestinationList = selectionDestinations.querySelector('ul');
  const restoreSelected = shell.querySelector('[data-archived-page-batch-restore="true"]');
  const trashSelected = shell.querySelector('.archive-trash-selected');
  const search = shell.querySelector('.library-search input');
  let selectedRestoreReview = null;
  const syncSelection = () => {
    selectionText.textContent = tr('archive.selected', { count: selected.size });
    selectionRoute.hidden = true;
    selectionRoute.textContent = '';
    selectionDestinations.hidden = true;
    selectionDestinations.open = false;
    selectionDestinationSummary.textContent = '';
    selectionDestinationList.innerHTML = '';
    selectedRestoreReview = null;
    const selectedEntries = [...selected];
    const containsArchivedPage = selectedEntries.some(
      entry => entry?.kind === 'item' && entry.data?.type === 'tab',
    );
    const containsArchivedGroup = selectedEntries.some(entry => entry?.kind === 'group');
    const containsArchivedLocalItem = selectedEntries.some(
      entry => entry?.kind === 'item' && ['note', 'todo', 'stack'].includes(entry.data?.type),
    );
    const containsLocalItem = selectedEntries.some(
      entry => entry?.kind !== 'group'
        && (entry?.kind !== 'item' || entry.data?.type !== 'tab'),
    );
    const containsUnsupportedStoredEntry = selectedEntries.some(
      entry => entry?.kind !== 'group'
        && !(entry?.kind === 'item'
          && ['tab', 'note', 'todo', 'stack'].includes(entry.data?.type)),
    );
    restoreSelected.disabled = selectedEntries.length === 0;
    if (containsArchivedPage && (containsArchivedGroup || containsLocalItem)) {
      selectionRoute.textContent = tr('archive.restorePagesSeparately');
      selectionRoute.hidden = false;
      restoreSelected.disabled = true;
    } else if (containsArchivedPage) {
      selectedRestoreReview = createArchivedPageBatchRestoreContext([...selected]);
      if (!selectedRestoreReview) {
        selectionRoute.textContent = tr('archive.restoreUnavailable');
        selectionRoute.hidden = false;
        restoreSelected.disabled = true;
      } else if (selectedRestoreReview.destinations.length === 1) {
        selectionRoute.textContent = archivedPageRestoreDestinationText(
          selectedRestoreReview.reviews[0],
        );
        selectionRoute.hidden = false;
      } else {
        selectionDestinationSummary.textContent = tr('archive.restoreDestinations', {
          count: selectedRestoreReview.destinations.length,
        });
        selectionDestinationList.innerHTML = selectedRestoreReview.destinations.map(({ destination, count }) => {
          const path = tr('library.destinationPath', {
            workspace: destination.workspaceName,
            space: destination.spaceName,
            group: destination.groupName,
          });
          return `<li><span>${esc(path)}</span><strong>${count}</strong></li>`;
        }).join('');
        selectionDestinations.hidden = false;
      }
    } else if (containsArchivedGroup && containsLocalItem) {
      selectionRoute.textContent = tr('archive.restoreGroupsSeparately');
      selectionRoute.hidden = false;
      restoreSelected.disabled = true;
    } else if (containsArchivedGroup) {
      selectedRestoreReview = createArchivedGroupBatchRestoreContext([...selected], 'archive');
      if (!selectedRestoreReview) {
        selectionRoute.textContent = tr('archive.restoreUnavailable');
        selectionRoute.hidden = false;
        restoreSelected.disabled = true;
      } else if (selectedRestoreReview.destinations.length === 1) {
        selectionRoute.textContent = archivedGroupRestoreDestinationText(
          selectedRestoreReview.reviews[0],
        );
        selectionRoute.hidden = false;
      } else {
        selectionDestinationSummary.textContent = tr('archive.restoreDestinations', {
          count: selectedRestoreReview.destinations.length,
        });
        selectionDestinationList.innerHTML = selectedRestoreReview.destinations.map(({ destination, count }) => {
          const path = tr('library.spaceDestinationPath', {
            workspace: destination.workspaceName,
            space: destination.spaceName,
          });
          return `<li><span>${esc(path)}</span><strong>${count}</strong></li>`;
        }).join('');
        selectionDestinations.hidden = false;
      }
    } else if (containsArchivedLocalItem && containsUnsupportedStoredEntry) {
      selectionRoute.textContent = tr('archive.restoreUnavailable');
      selectionRoute.hidden = false;
      restoreSelected.disabled = true;
    } else if (containsArchivedLocalItem) {
      selectedRestoreReview = createArchivedLocalItemBatchRestoreContext([...selected], 'archive');
      if (!selectedRestoreReview) {
        selectionRoute.textContent = tr('archive.restoreUnavailable');
        selectionRoute.hidden = false;
        restoreSelected.disabled = true;
      } else if (selectedRestoreReview.destinations.length === 1) {
        selectionRoute.textContent = archivedLocalItemRestoreDestinationText(
          selectedRestoreReview.reviews[0],
        );
        selectionRoute.hidden = false;
      } else {
        selectionDestinationSummary.textContent = tr('archive.restoreDestinations', {
          count: selectedRestoreReview.destinations.length,
        });
        selectionDestinationList.innerHTML = selectedRestoreReview.destinations.map(({ destination, count }) => {
          const path = tr('library.destinationPath', {
            workspace: destination.workspaceName,
            space: destination.spaceName,
            group: destination.groupName,
          });
          return `<li><span>${esc(path)}</span><strong>${count}</strong></li>`;
        }).join('');
        selectionDestinations.hidden = false;
      }
    }
    restoreSelected.setAttribute('aria-disabled', String(restoreSelected.disabled));
    trashSelected.disabled = selected.size === 0;
  };
  selectionDestinations.onkeydown = event => {
    if (event.key !== 'Escape' || !selectionDestinations.open) return;
    event.preventDefault();
    event.stopPropagation();
    selectionDestinations.open = false;
    selectionDestinationSummary.focus();
  };
  function resetFilters() {
    query = '';
    type = 'all';
    search.value = '';
    shell.querySelectorAll('.archive-filters button').forEach(button => {
      const active = button.dataset.type === 'all';
      button.classList.toggle('active', active);
      button.setAttribute('aria-pressed', String(active));
    });
    paint();
    search.focus();
  }

  const paint = () => {
    const needle = query.trim().toLowerCase();
    const visible = allEntries.filter(entry => {
      if (type !== 'all' && archiveEntryType(entry) !== type) return false;
      return !needle || archiveEntryText(entry).includes(needle);
    });
    results.innerHTML = '';
    if (!visible.length) {
      results.appendChild(allEntries.length
        ? buildSystemEmptyState({
            kind: 'search', compact: true, title: tr('empty.noMatchTitle'), body: tr('empty.noMatchBody'),
            actions: [{ label: tr('empty.clearFilters'), icon: '×', run: resetFilters }],
          })
        : buildSystemEmptyState({
            kind: 'archive', title: tr('empty.archiveTitle'), body: tr('empty.archiveBody'),
            actions: [
              { label: tr('empty.browseLibrary'), icon: '↗', run: () => openLibrarySurface('all') },
              { label: tr('empty.returnHome'), icon: '⌂', run: goHome },
            ],
            note: tr('empty.localNote'),
          }));
      return;
    }

    const buckets = new Map();
    visible.forEach(entry => {
      const bucket = archiveDateBucket(archiveEntryTimestamp(entry));
      if (!buckets.has(bucket)) buckets.set(bucket, []);
      buckets.get(bucket).push(entry);
    });
    buckets.forEach((entries, label) => {
      const section = document.createElement('section');
      section.className = 'archive-group';
      section.innerHTML = `<h2>${label}<span>${entries.length}</span></h2><div class="archive-list" role="list"></div>`;
      const list = section.querySelector('.archive-list');
      entries.forEach(entry => {
        const row = document.createElement('article');
        const title = archiveEntryTitle(entry);
        const origin = [entry.catName, entry.groupName].filter(Boolean).join(' / ') || 'Archive';
        const isArchivedPage = entry.kind === 'item' && entry.data?.type === 'tab';
        const isArchivedGroup = entry.kind === 'group';
        const isArchivedLocalItem = entry.kind === 'item'
          && ['note', 'todo', 'stack'].includes(entry.data?.type);
        const restoreContext = isArchivedPage ? createArchivedPageRestoreContext(entry) : null;
        const restoreDestination = isArchivedPage
          ? archivedPageRestoreDestinationText(restoreContext)
          : '';
        const localRestoreContext = isArchivedLocalItem
          ? createArchivedLocalItemRestoreContext(entry, 'archive')
          : null;
        const localRestoreDestination = isArchivedLocalItem
          ? archivedLocalItemRestoreDestinationText(localRestoreContext)
          : '';
        const localRestorePath = isArchivedLocalItem
          ? archivedLocalItemRestorePathText(localRestoreContext)
          : '';
        const groupRestoreContext = isArchivedGroup
          ? createArchivedGroupRestoreContext(entry, 'archive')
          : null;
        const groupRestoreDestination = isArchivedGroup
          ? archivedGroupRestoreDestinationText(groupRestoreContext)
          : '';
        const groupRestorePath = isArchivedGroup
          ? archivedGroupRestorePathText(groupRestoreContext)
          : '';
        const groupItemCount = isArchivedGroup ? archiveEntryCount(entry) : 0;
        const groupItemCountText = groupItemCount === 1
          ? tr('groupAction.oneItem')
          : tr('groupAction.items', { count: groupItemCount });
        const visibleIndex = visible.indexOf(entry);
        const neighbor = visible[visibleIndex + 1] || visible[visibleIndex - 1] || null;
        const neighborId = neighbor?.kind === 'item' ? String(neighbor.data?.id || '') : '';
        const neighborGroupId = neighbor?.kind === 'group' ? String(neighbor.data?.id || '') : '';
        const timestamp = archiveEntryTimestamp(entry);
        const date = timestamp ? new Intl.DateTimeFormat(undefined, { dateStyle:'medium', timeStyle:'short' }).format(new Date(timestamp)) : 'Date unavailable';
        row.className = 'archive-row';
        row.setAttribute('role', 'listitem');
        if (isArchivedPage || isArchivedLocalItem) row.dataset.archiveItemId = String(entry.data.id || '');
        if (isArchivedGroup) row.dataset.archiveGroupId = String(entry.data.id || '');
        const secondary = isArchivedPage
          ? restoreDestination
          : (isArchivedGroup
            ? `${groupRestoreDestination} · ${groupItemCountText}`
            : (isArchivedLocalItem
              ? localRestoreDestination
              : `${origin} · ${archiveEntryType(entry).replace(/s$/, '')}`));
        const restoreLabel = isArchivedGroup
          ? tr('archive.restoreGroupToFor', { title, destination: groupRestorePath })
          : (isArchivedLocalItem
            ? tr('archive.restoreToFor', { title, destination: localRestorePath })
            : tr('archive.restoreFor', { title }));
        row.innerHTML = `
          <label class="archive-check"><input type="checkbox" aria-label="Select ${esc(title)}"><span aria-hidden="true"></span></label>
          <span class="archive-icon" aria-hidden="true">${esc(archiveEntryIcon(entry))}</span>
          <span class="archive-copy"><strong>${esc(title)}</strong><span${isArchivedPage || isArchivedGroup || isArchivedLocalItem ? ' class="archive-restore-destination"' : ''}>${esc(secondary)}</span></span>
          <time datetime="${timestamp ? new Date(timestamp).toISOString() : ''}" title="${esc(date)}">${timestamp ? esc(fmtTimeRelative(timestamp)) : 'Date unavailable'}</time>
          <button type="button" class="archive-restore"${isArchivedPage ? ' data-archived-page-restore="true"' : (isArchivedGroup ? ' data-archived-group-restore="true"' : (isArchivedLocalItem ? ' data-archived-local-item-restore="true"' : ''))} aria-label="${esc(restoreLabel)}" title="${esc(isArchivedPage ? restoreDestination : (isArchivedGroup ? groupRestoreDestination : (isArchivedLocalItem ? localRestoreDestination : tr('archive.restore'))))}">${esc(tr('archive.restore'))}</button>
          <button type="button" class="archive-delete" aria-label="${esc(tr('archive.moveToTrash'))}: ${esc(title)}" title="${esc(tr('archive.moveToTrash'))}">×</button>`;
        const checkbox = row.querySelector('input');
        checkbox.checked = selected.has(entry);
        checkbox.onchange = () => { checkbox.checked ? selected.add(entry) : selected.delete(entry); row.classList.toggle('selected', checkbox.checked); syncSelection(); };
        row.classList.toggle('selected', checkbox.checked);
        const restoreButton = row.querySelector('.archive-restore');
        if (isArchivedPage) {
          row.__archivedPageRestoreEntry = entry;
          restoreButton.disabled = !restoreContext;
          restoreButton.setAttribute('aria-disabled', String(!restoreContext));
          restoreButton.onclick = async () => {
            const changed = await restoreArchivedPage(restoreContext, restoreButton);
            if (!changed) return;
            requestAnimationFrame(() => focusArchivedPageRestoreTarget(neighborId));
          };
        } else if (isArchivedGroup) {
          row.__archivedGroupRestoreEntry = entry;
          restoreButton.disabled = !groupRestoreContext;
          restoreButton.setAttribute('aria-disabled', String(!groupRestoreContext));
          restoreButton.onclick = async () => {
            const changed = await commitArchivedGroupRestore(groupRestoreContext, restoreButton);
            if (!changed) return;
            requestAnimationFrame(() => focusArchivedGroupRestoreTarget(neighborGroupId));
          };
        } else if (isArchivedLocalItem) {
          row.__archivedLocalItemRestoreEntry = entry;
          restoreButton.disabled = !localRestoreContext;
          restoreButton.setAttribute('aria-disabled', String(!localRestoreContext));
          restoreButton.onclick = async () => {
            const changed = await commitArchivedLocalItemRestore(localRestoreContext, restoreButton);
            if (!changed) return;
            requestAnimationFrame(() => focusArchivedLocalItemRestoreTarget(neighborId));
          };
        } else restoreButton.onclick = () => restoreArchiveEntries([entry]);
        row.querySelector('.archive-delete').onclick = () => moveArchiveEntriesToTrash([entry]);
        list.appendChild(row);
      });
      results.appendChild(section);
    });
  };

  search.oninput = e => { query = e.target.value; paint(); };
  shell.querySelectorAll('.archive-filters button').forEach(button => {
    button.onclick = () => {
      type = button.dataset.type;
      shell.querySelectorAll('.archive-filters button').forEach(b => { const on = b === button; b.classList.toggle('active', on); b.setAttribute('aria-pressed', String(on)); });
      paint();
    };
  });
  restoreSelected.onclick = async () => {
    const selectedEntries = [...selected];
    const containsArchivedPage = selectedEntries.some(
      entry => entry?.kind === 'item' && entry.data?.type === 'tab',
    );
    const containsArchivedGroup = selectedEntries.some(entry => entry?.kind === 'group');
    const containsArchivedLocalItem = selectedEntries.some(
      entry => entry?.kind === 'item' && ['note', 'todo', 'stack'].includes(entry.data?.type),
    );
    if (!containsArchivedPage && !containsArchivedGroup && !containsArchivedLocalItem) {
      restoreArchiveEntries(selectedEntries);
      return;
    }
    if (!selectedRestoreReview
        || selectedEntries.length !== selectedRestoreReview.entryRefs.length
        || selectedEntries.some((entry, index) => entry !== selectedRestoreReview.entryRefs[index])) {
      syncSelection();
      return;
    }
    const changed = containsArchivedPage
      ? await commitArchivedPageBatchRestore(selectedRestoreReview, restoreSelected)
      : (containsArchivedGroup
        ? await commitArchivedGroupBatchRestore(selectedRestoreReview, restoreSelected)
        : await commitArchivedLocalItemBatchRestore(selectedRestoreReview, restoreSelected));
    if (!changed) return;
    requestAnimationFrame(() => {
      if (containsArchivedPage) focusArchivedPageRestoreTarget('');
      else if (containsArchivedGroup) focusArchivedGroupRestoreTarget('');
      else focusArchivedLocalItemRestoreTarget('');
    });
  };
  trashSelected.onclick = () => moveArchiveEntriesToTrash([...selected]);
  paint();
  syncSelection();
  updateNavChrome();
  return true;
}

function trashDateBucket(at) {
  const bucket = archiveDateBucket(at);
  return tr({ Today:'trash.today', Yesterday:'trash.yesterday', 'This week':'trash.thisWeek', Earlier:'trash.earlier' }[bucket] || 'trash.earlier');
}

function trashDaysLeft(entry, now = Date.now()) {
  return Math.max(0, Math.ceil((TRASH_RETENTION_MS - (now - trashTimestamp(entry))) / 86400000));
}

function renderTrashSurface() {
  purgeExpiredTrash();
  hideBreadcrumb();
  const board = document.getElementById('board');
  board.classList.remove('group-page-mode', 'list-mode', 'canvas-mode', 'explorer-mode', 'timeline-mode', 'gallery-mode', 'graph-mode', 'calendar-mode', 'home-mode', 'archive-mode');
  board.classList.add('library-mode', 'trash-mode');
  board.innerHTML = '';

  const stored = State.get().trash || [];
  const allEntries = stored
    .filter(entry => entry && entry.data)
    .sort((a, b) => trashTimestamp(b) - trashTimestamp(a));
  const invalidCount = stored.length - allEntries.length;
  const itemTotal = allEntries.reduce((sum, entry) => sum + archiveEntryCount(entry), 0);
  const bytes = jsonSize(allEntries);
  const selected = new Set();
  let query = '';
  let type = 'all';

  const shell = document.createElement('section');
  shell.className = 'library-shell archive-shell trash-shell';
  shell.innerHTML = `
    <header class="library-head archive-head">
      <div>
        <h1>${tr('trash.title')}</h1>
        <p>${tr('trash.subtitle')}</p>
      </div>
      <label class="library-search">
        <svg width="15" height="15" viewBox="0 0 16 16" fill="none" aria-hidden="true"><circle cx="6.5" cy="6.5" r="4.5" stroke="currentColor" stroke-width="1.5"/><path d="M10 10l3 3" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/></svg>
        <input type="search" placeholder="${esc(tr('trash.search'))}" aria-label="${esc(tr('trash.search'))}">
      </label>
    </header>
    <div class="trash-retention" role="note">
      <span class="trash-retention-icon" aria-hidden="true">⌫</span>
      <strong>${tr('trash.retention')}</strong>
      <span>${tr('trash.localOnly')}</span>
    </div>
    ${invalidCount ? `<div class="trash-error" role="status">${esc(tr('trash.invalid', { count: invalidCount }))}</div>` : ''}
    <div class="archive-summary trash-summary" aria-label="${esc(tr('trash.title'))}">
      <div><strong>${allEntries.length}</strong><span>${tr('trash.summary.entries', { count: allEntries.length })}</span></div>
      <div><strong>${itemTotal}</strong><span>${tr('trash.summary.items', { count: itemTotal })}</span></div>
      <div><strong>${_formatBytes(bytes)}</strong><span>${tr('trash.summary.space')}</span></div>
      <div class="archive-local"><strong>30</strong><span>${tr('trash.summary.retention')}</span></div>
    </div>
    <div class="archive-toolbar">
      <div class="archive-filters" role="group" aria-label="${esc(tr('trash.title'))}">
        ${[['all','trash.all'],['links','trash.links'],['notes','trash.notes'],['todos','trash.todos'],['groups','trash.groups']].map(([value, key]) => `<button type="button" data-type="${value}" aria-pressed="${value === 'all'}" class="${value === 'all' ? 'active' : ''}">${tr(key)}</button>`).join('')}
      </div>
      <div class="archive-selection trash-selection" aria-live="polite">
        <span class="archive-selection-count">${tr('trash.selected', { count: 0 })}</span>
        <span class="archive-selection-route" hidden></span>
        <details class="archive-selection-destinations" hidden>
          <summary></summary>
          <ul></ul>
        </details>
        <button type="button" class="btn-primary trash-restore-selected" data-archived-page-batch-restore="true" data-archived-group-batch-restore="true" data-archived-local-item-batch-restore="true" disabled>${tr('trash.restoreSelected')}</button>
        <button type="button" class="btn-secondary trash-delete-selected" disabled>${tr('trash.deleteSelected')}</button>
      </div>
    </div>
    <div class="archive-results" aria-live="polite"></div>`;
  board.appendChild(shell);

  const results = shell.querySelector('.archive-results');
  const selectionText = shell.querySelector('.archive-selection-count');
  const selectionRoute = shell.querySelector('.archive-selection-route');
  const selectionDestinations = shell.querySelector('.archive-selection-destinations');
  const selectionDestinationSummary = selectionDestinations.querySelector('summary');
  const selectionDestinationList = selectionDestinations.querySelector('ul');
  const restoreSelected = shell.querySelector('.trash-restore-selected');
  const deleteSelected = shell.querySelector('.trash-delete-selected');
  const search = shell.querySelector('.library-search input');
  let selectedRestoreReview = null;
  const syncSelection = () => {
    selectionText.textContent = tr('trash.selected', { count: selected.size });
    selectionRoute.hidden = true;
    selectionRoute.textContent = '';
    selectionDestinations.hidden = true;
    selectionDestinations.open = false;
    selectionDestinationSummary.textContent = '';
    selectionDestinationList.innerHTML = '';
    selectedRestoreReview = null;
    const selectedEntries = [...selected];
    const containsTrashedPage = selectedEntries.some(
      entry => entry?.kind === 'item' && entry.data?.type === 'tab',
    );
    const containsTrashedGroup = selectedEntries.some(entry => entry?.kind === 'group');
    const containsTrashedLocalItem = selectedEntries.some(
      entry => entry?.kind === 'item' && ['note', 'todo', 'stack'].includes(entry.data?.type),
    );
    const containsLocalItem = selectedEntries.some(
      entry => entry?.kind !== 'group'
        && (entry?.kind !== 'item' || entry.data?.type !== 'tab'),
    );
    const containsUnsupportedStoredEntry = selectedEntries.some(
      entry => entry?.kind !== 'group'
        && !(entry?.kind === 'item'
          && ['tab', 'note', 'todo', 'stack'].includes(entry.data?.type)),
    );
    restoreSelected.disabled = selectedEntries.length === 0;
    if (containsTrashedPage && (containsTrashedGroup || containsLocalItem)) {
      selectionRoute.textContent = tr('trash.restorePagesSeparately');
      selectionRoute.hidden = false;
      restoreSelected.disabled = true;
    } else if (containsTrashedPage) {
      selectedRestoreReview = createTrashedPageBatchRestoreContext([...selected]);
      if (!selectedRestoreReview) {
        selectionRoute.textContent = tr('archive.restoreUnavailable');
        selectionRoute.hidden = false;
        restoreSelected.disabled = true;
      } else if (selectedRestoreReview.destinations.length === 1) {
        selectionRoute.textContent = archivedPageRestoreDestinationText(
          selectedRestoreReview.reviews[0],
        );
        selectionRoute.hidden = false;
      } else {
        selectionDestinationSummary.textContent = tr('archive.restoreDestinations', {
          count: selectedRestoreReview.destinations.length,
        });
        selectionDestinationList.innerHTML = selectedRestoreReview.destinations.map(({ destination, count }) => {
          const path = tr('library.destinationPath', {
            workspace: destination.workspaceName,
            space: destination.spaceName,
            group: destination.groupName,
          });
          return `<li><span>${esc(path)}</span><strong>${count}</strong></li>`;
        }).join('');
        selectionDestinations.hidden = false;
      }
    } else if (containsTrashedGroup && containsLocalItem) {
      selectionRoute.textContent = tr('trash.restoreGroupsSeparately');
      selectionRoute.hidden = false;
      restoreSelected.disabled = true;
    } else if (containsTrashedGroup) {
      selectedRestoreReview = createTrashedGroupBatchRestoreContext([...selected]);
      if (!selectedRestoreReview) {
        selectionRoute.textContent = tr('archive.restoreUnavailable');
        selectionRoute.hidden = false;
        restoreSelected.disabled = true;
      } else if (selectedRestoreReview.destinations.length === 1) {
        selectionRoute.textContent = archivedGroupRestoreDestinationText(
          selectedRestoreReview.reviews[0],
        );
        selectionRoute.hidden = false;
      } else {
        selectionDestinationSummary.textContent = tr('archive.restoreDestinations', {
          count: selectedRestoreReview.destinations.length,
        });
        selectionDestinationList.innerHTML = selectedRestoreReview.destinations.map(({ destination, count }) => {
          const path = tr('library.spaceDestinationPath', {
            workspace: destination.workspaceName,
            space: destination.spaceName,
          });
          return `<li><span>${esc(path)}</span><strong>${count}</strong></li>`;
        }).join('');
        selectionDestinations.hidden = false;
      }
    } else if (containsTrashedLocalItem && containsUnsupportedStoredEntry) {
      selectionRoute.textContent = tr('archive.restoreUnavailable');
      selectionRoute.hidden = false;
      restoreSelected.disabled = true;
    } else if (containsTrashedLocalItem) {
      selectedRestoreReview = createTrashedLocalItemBatchRestoreContext([...selected]);
      if (!selectedRestoreReview) {
        selectionRoute.textContent = tr('archive.restoreUnavailable');
        selectionRoute.hidden = false;
        restoreSelected.disabled = true;
      } else if (selectedRestoreReview.destinations.length === 1) {
        selectionRoute.textContent = archivedLocalItemRestoreDestinationText(
          selectedRestoreReview.reviews[0],
        );
        selectionRoute.hidden = false;
      } else {
        selectionDestinationSummary.textContent = tr('archive.restoreDestinations', {
          count: selectedRestoreReview.destinations.length,
        });
        selectionDestinationList.innerHTML = selectedRestoreReview.destinations.map(({ destination, count }) => {
          const path = tr('library.destinationPath', {
            workspace: destination.workspaceName,
            space: destination.spaceName,
            group: destination.groupName,
          });
          return `<li><span>${esc(path)}</span><strong>${count}</strong></li>`;
        }).join('');
        selectionDestinations.hidden = false;
      }
    }
    restoreSelected.setAttribute('aria-disabled', String(restoreSelected.disabled));
    deleteSelected.disabled = selected.size === 0;
  };
  selectionDestinations.onkeydown = event => {
    if (event.key !== 'Escape' || !selectionDestinations.open) return;
    event.preventDefault();
    event.stopPropagation();
    selectionDestinations.open = false;
    selectionDestinationSummary.focus();
  };
  function resetFilters() {
    query = '';
    type = 'all';
    search.value = '';
    shell.querySelectorAll('.archive-filters button').forEach(button => {
      const active = button.dataset.type === 'all';
      button.classList.toggle('active', active);
      button.setAttribute('aria-pressed', String(active));
    });
    paint();
    search.focus();
  }

  const paint = () => {
    const needle = query.trim().toLowerCase();
    const visible = allEntries.filter(entry => {
      if (type !== 'all' && archiveEntryType(entry) !== type) return false;
      return !needle || archiveEntryText(entry).includes(needle);
    });
    results.innerHTML = '';
    if (!visible.length) {
      const noMatch = allEntries.length > 0;
      results.appendChild(noMatch
        ? buildSystemEmptyState({
            kind: 'search', compact: true, title: tr('empty.noMatchTitle'), body: tr('empty.noMatchBody'),
            actions: [{ label: tr('empty.clearFilters'), icon: '×', run: resetFilters }],
          })
        : buildSystemEmptyState({
            kind: 'trash', title: tr('empty.trashTitle'), body: tr('empty.trashBody'),
            actions: [
              { label: tr('empty.browseArchive'), icon: '↗', run: () => openLibrarySurface('archive') },
              { label: tr('empty.returnHome'), icon: '⌂', run: goHome },
            ],
          }));
      return;
    }

    const buckets = new Map();
    visible.forEach(entry => {
      const bucket = trashDateBucket(trashTimestamp(entry));
      if (!buckets.has(bucket)) buckets.set(bucket, []);
      buckets.get(bucket).push(entry);
    });
    buckets.forEach((entries, label) => {
      const section = document.createElement('section');
      section.className = 'archive-group';
      section.innerHTML = `<h2>${esc(label)}<span>${entries.length}</span></h2><div class="archive-list" role="list"></div>`;
      const list = section.querySelector('.archive-list');
      entries.forEach(entry => {
        const row = document.createElement('article');
        const title = archiveEntryTitle(entry);
        const origin = [entry.catName, entry.groupName].filter(Boolean).join(' / ') || tr('nav.archive');
        const isTrashedPage = entry.kind === 'item' && entry.data?.type === 'tab';
        const isTrashedGroup = entry.kind === 'group';
        const isTrashedLocalItem = entry.kind === 'item'
          && ['note', 'todo', 'stack'].includes(entry.data?.type);
        const restoreContext = isTrashedPage ? createTrashedPageRestoreContext(entry) : null;
        const restoreDestination = isTrashedPage
          ? archivedPageRestoreDestinationText(restoreContext)
          : '';
        const restorePath = isTrashedPage
          ? (restoreContext?.destination
            ? tr('library.destinationPath', {
                workspace: restoreContext.destination.workspaceName,
                space: restoreContext.destination.spaceName,
                group: restoreContext.destination.groupName,
              })
            : tr('archive.restoreUnavailable'))
          : '';
        const localRestoreContext = isTrashedLocalItem
          ? createTrashedLocalItemRestoreContext(entry)
          : null;
        const localRestoreDestination = isTrashedLocalItem
          ? archivedLocalItemRestoreDestinationText(localRestoreContext)
          : '';
        const localRestorePath = isTrashedLocalItem
          ? archivedLocalItemRestorePathText(localRestoreContext)
          : '';
        const groupRestoreContext = isTrashedGroup ? createTrashedGroupRestoreContext(entry) : null;
        const groupRestoreDestination = isTrashedGroup
          ? archivedGroupRestoreDestinationText(groupRestoreContext)
          : '';
        const groupRestorePath = isTrashedGroup
          ? archivedGroupRestorePathText(groupRestoreContext)
          : '';
        const groupItemCount = isTrashedGroup ? archiveEntryCount(entry) : 0;
        const groupItemCountText = groupItemCount === 1
          ? tr('groupAction.oneItem')
          : tr('groupAction.items', { count: groupItemCount });
        const visibleIndex = visible.indexOf(entry);
        const neighbor = visible[visibleIndex + 1] || visible[visibleIndex - 1] || null;
        const neighborId = neighbor?.kind === 'item' ? String(neighbor.data?.id || '') : '';
        const neighborGroupId = neighbor?.kind === 'group' ? String(neighbor.data?.id || '') : '';
        const timestamp = trashTimestamp(entry);
        const days = trashDaysLeft(entry);
        const daysLabel = days === 0 ? tr('trash.expiresToday') : days === 1 ? tr('trash.dayLeft') : tr('trash.daysLeft', { count: days });
        row.className = 'archive-row trash-row';
        row.setAttribute('role', 'listitem');
        if (isTrashedPage || isTrashedLocalItem) row.dataset.archiveItemId = String(entry.data.id || '');
        if (isTrashedGroup) row.dataset.archiveGroupId = String(entry.data.id || '');
        const secondary = isTrashedPage
          ? restoreDestination
          : (isTrashedGroup
            ? `${groupRestoreDestination} · ${groupItemCountText}`
            : (isTrashedLocalItem ? localRestoreDestination : origin));
        const restoreLabel = isTrashedPage
          ? tr('trash.restoreToFor', { title, destination: restorePath })
          : (isTrashedGroup
            ? tr('trash.restoreGroupToFor', { title, destination: groupRestorePath })
            : (isTrashedLocalItem
              ? tr('trash.restoreToFor', { title, destination: localRestorePath })
              : `${tr('trash.restore')}: ${title}`));
        row.innerHTML = `
          <label class="archive-check"><input type="checkbox" aria-label="${esc(tr('trash.select', { title }))}"><span aria-hidden="true"></span></label>
          <span class="archive-icon" aria-hidden="true">${esc(archiveEntryIcon(entry))}</span>
          <span class="archive-copy"><strong>${esc(title)}</strong><span${isTrashedPage || isTrashedGroup || isTrashedLocalItem ? ' class="archive-restore-destination"' : ''}>${esc(secondary)}</span></span>
          <time class="trash-expiry" datetime="${new Date(timestamp).toISOString()}" title="${esc(new Intl.DateTimeFormat(undefined, { dateStyle:'medium', timeStyle:'short' }).format(new Date(timestamp)))}">${esc(daysLabel)}</time>
          <button type="button" class="archive-restore"${isTrashedPage ? ' data-archived-page-restore="true"' : (isTrashedGroup ? ' data-archived-group-restore="true"' : (isTrashedLocalItem ? ' data-archived-local-item-restore="true"' : ''))} aria-label="${esc(restoreLabel)}" title="${esc(isTrashedPage ? restoreDestination : (isTrashedGroup ? groupRestoreDestination : (isTrashedLocalItem ? localRestoreDestination : tr('trash.restore'))))}">${tr('trash.restore')}</button>
          <button type="button" class="archive-delete" aria-label="${esc(tr('trash.deleteForever'))}: ${esc(title)}" title="${esc(tr('trash.deleteForever'))}">×</button>`;
        const checkbox = row.querySelector('input');
        checkbox.checked = selected.has(entry);
        checkbox.onchange = () => { checkbox.checked ? selected.add(entry) : selected.delete(entry); row.classList.toggle('selected', checkbox.checked); syncSelection(); };
        row.classList.toggle('selected', checkbox.checked);
        const restoreButton = row.querySelector('.archive-restore');
        if (isTrashedPage) {
          row.__archivedPageRestoreEntry = entry;
          restoreButton.disabled = !restoreContext;
          restoreButton.setAttribute('aria-disabled', String(!restoreContext));
          restoreButton.onclick = async () => {
            const changed = await commitTrashedPageRestore(restoreContext, restoreButton);
            if (!changed) return;
            requestAnimationFrame(() => focusArchivedPageRestoreTarget(neighborId));
          };
        } else if (isTrashedGroup) {
          row.__archivedGroupRestoreEntry = entry;
          restoreButton.disabled = !groupRestoreContext;
          restoreButton.setAttribute('aria-disabled', String(!groupRestoreContext));
          restoreButton.onclick = async () => {
            const changed = await commitTrashedGroupRestore(groupRestoreContext, restoreButton);
            if (!changed) return;
            requestAnimationFrame(() => focusArchivedGroupRestoreTarget(neighborGroupId));
          };
        } else if (isTrashedLocalItem) {
          row.__archivedLocalItemRestoreEntry = entry;
          restoreButton.disabled = !localRestoreContext;
          restoreButton.setAttribute('aria-disabled', String(!localRestoreContext));
          restoreButton.onclick = async () => {
            const changed = await commitTrashedLocalItemRestore(localRestoreContext, restoreButton);
            if (!changed) return;
            requestAnimationFrame(() => focusArchivedLocalItemRestoreTarget(neighborId));
          };
        } else restoreButton.onclick = () => restoreTrashEntries([entry]);
        row.querySelector('.archive-delete').onclick = () => permanentlyDeleteTrashEntries([entry]);
        list.appendChild(row);
      });
      results.appendChild(section);
    });
  };

  search.oninput = e => { query = e.target.value; paint(); };
  search.onkeydown = e => {
    if (e.key !== 'Escape') return;
    e.stopPropagation();
    if (search.value) { search.value = ''; query = ''; paint(); }
    else search.blur();
  };
  shell.querySelectorAll('.archive-filters button').forEach(button => {
    button.onclick = () => {
      type = button.dataset.type;
      shell.querySelectorAll('.archive-filters button').forEach(b => { const on = b === button; b.classList.toggle('active', on); b.setAttribute('aria-pressed', String(on)); });
      paint();
    };
  });
  restoreSelected.onclick = async () => {
    const selectedEntries = [...selected];
    const containsTrashedPage = selectedEntries.some(
      entry => entry?.kind === 'item' && entry.data?.type === 'tab',
    );
    const containsTrashedGroup = selectedEntries.some(entry => entry?.kind === 'group');
    const containsTrashedLocalItem = selectedEntries.some(
      entry => entry?.kind === 'item' && ['note', 'todo', 'stack'].includes(entry.data?.type),
    );
    if (!containsTrashedPage && !containsTrashedGroup && !containsTrashedLocalItem) {
      restoreTrashEntries(selectedEntries);
      return;
    }
    if (!selectedRestoreReview
        || selectedEntries.length !== selectedRestoreReview.entryRefs.length
        || selectedEntries.some((entry, index) => entry !== selectedRestoreReview.entryRefs[index])) {
      syncSelection();
      return;
    }
    const changed = containsTrashedPage
      ? await commitTrashedPageBatchRestore(selectedRestoreReview, restoreSelected)
      : (containsTrashedGroup
        ? await commitTrashedGroupBatchRestore(selectedRestoreReview, restoreSelected)
        : await commitTrashedLocalItemBatchRestore(selectedRestoreReview, restoreSelected));
    if (!changed) return;
    requestAnimationFrame(() => {
      if (containsTrashedPage) focusArchivedPageRestoreTarget('');
      else if (containsTrashedGroup) focusArchivedGroupRestoreTarget('');
      else focusArchivedLocalItemRestoreTarget('');
    });
  };
  deleteSelected.onclick = () => permanentlyDeleteTrashEntries([...selected]);
  paint();
  syncSelection();
  updateNavChrome();
  return true;
}

// Save the currently dragged tab / multi-selection into a category's Inbox group.
// Backs the "drag a tab into a space to save it" affordance on the SPACES list.
async function dropTabsIntoCategory(cat) {
  const draggedTabs = captureEligibleTabs(drag?.kind === 'tab' ? [drag.data]
    : drag?.kind === 'tabs-multi' ? [...drag.data]
    : []);
  if (!draggedTabs.length) return false;

  const ws = activeWs();
  const destination = createInboxCaptureContext(ws, cat);
  if (!destination) return reportInboxCaptureUnavailable();
  const actionId = State.snapshot(tr(
    draggedTabs.length === 1 ? 'capture.snapshotInboxTab' : 'capture.snapshotInboxTabs',
    { count: draggedTabs.length },
  ));
  const target = materializeInboxCaptureTarget(destination);
  if (!target) {
    State.rollbackSnapshot(actionId);
    return reportInboxCaptureUnavailable();
  }
  const inbox = target.inbox;

  const savedTabs = [];
  const savedItems = [];
  try {
    const allocateId = createOrganizationIdAllocator();
    for (const tab of draggedTabs) {
      if (captureDuplicateExists(inbox.items, tab.url)) continue;
      const meta = captureTabFields(tab);
      const item = stampNew({
        id: allocateId(), type: 'tab', title: meta.title,
        url: tab.url, fav: meta.fav
      });
      inbox.items.push(item);
      savedItems.push(item);
      savedTabs.push(tab);
    }
  } catch {
    State.rollbackSnapshot(actionId);
    renderAll();
    return reportInboxCaptureUnavailable();
  }
  if (!savedTabs.length) {
    State.rollbackSnapshot(actionId);
    toast(tr('capture.alreadySaved'), { danger: true });
    return;
  }
  const closeSources = State.get().settings.closeTabOnSave;
  const listContext = createItemListCaptureContext(inbox.items, { allowInactiveSpace: true });
  const receiptContext = createCaptureDestinationReceiptContext(listContext, savedItems);
  const receiptMessage = inboxCaptureReceiptMessage(target, {
    count: savedTabs.length,
    closeSources: !!closeSources,
  });
  if (!receiptContext || !receiptMessage) {
    State.rollbackSnapshot(actionId);
    renderAll();
    return reportInboxCaptureUnavailable();
  }
  const result = await commitCapturedTabs(savedTabs, {
    actionId,
    refreshSources: true,
    closeSources,
    validateDestination: () => !!resolveCaptureDestinationReceiptTarget(receiptContext),
  });
  if (!result) return;
  clearCapturedTabSelection(draggedTabs);
  renderBoard();
  renderOpenTabs();
  updateSelectedBadge();
  toastCaptureDestinationReceipt(receiptContext, receiptMessage, result);
  renderSpaceNav();
}

function homeTrailItemCanOfferOpen(item) {
  return item?.type === 'tab'
    && typeof item.id === 'string'
    && !!item.id.trim()
    && isOpenableSavedTabUrl(item.url);
}

function homeTrailRecoveryActionPlan(item) {
  const keys = homeTrailItemCanOfferOpen(item) ? ['open', 'review'] : ['review'];
  return keys.map((key, index) => ({
    key,
    className: `${index === 0 ? 'btn-primary' : 'btn-secondary'} home-trail-${key}`,
  }));
}

function homeTrailCaptureActionPlan({ closePrimary, recoveryHasPrimary }) {
  return [
    {
      key: 'save-primary',
      closeSource: !!closePrimary,
      className: `${recoveryHasPrimary ? 'btn-secondary' : 'btn-primary'} home-trail-save`,
    },
    {
      key: 'save-alternate',
      closeSource: !closePrimary,
      className: 'btn-secondary home-trail-save',
    },
  ];
}

function homeTrailBlockedDestinationActionPlan(cat, destination = null, { recoveryHasPrimary = false } = {}) {
  if (!cat) return [{
    key: 'create-space',
    className: 'btn-primary home-trail-create-space',
    labelKey: 'organization.space.createTitle',
  }];
  if (destination?.inboxCount > 1) return [{
    key: 'review-space',
    className: `${recoveryHasPrimary ? 'btn-secondary' : 'btn-primary'} home-trail-review-space`,
    labelKey: 'home.trail.openSpace',
    ariaLabelKey: 'home.trail.openSpaceFor',
  }];
  return [];
}

function newestHomeRows(rows, limit = 1, { preferReopenableTab = false } = {}) {
  return (rows || [])
    .map((row, index) => ({
      row,
      index,
      createdAt: Number(row?.item?.createdAt) || 0,
      reopenable: preferReopenableTab && homeTrailItemCanOfferOpen(row?.item),
    }))
    .sort((a, b) => Number(b.reopenable) - Number(a.reopenable)
      || b.createdAt - a.createdAt
      || b.index - a.index)
    .slice(0, limit)
    .map(entry => entry.row);
}

function recentSaveCandidate(tabs = allOpenTabs) {
  const entries = (tabs || [])
    .map((tab, index) => ({ tab, index }))
    .filter(({ tab }) => isOpenableSavedTabUrl(tab?.url)
      && (!tab.pendingUrl || String(tab.pendingUrl) === String(tab.url)))
    .sort((a, b) => Number(b.tab.lastAccessed || 0) - Number(a.tab.lastAccessed || 0)
      || b.index - a.index);
  return entries[0]?.tab || null;
}

function homeTrailSaveCandidate(tabs = allOpenTabs, cat = activeCat()) {
  if (State.get().settings.captureDeduplicate === false) return recentSaveCandidate(tabs);
  const inbox = cat?.groups?.find(group => group.name === 'Inbox');
  return recentSaveCandidate((tabs || [])
    .filter(tab => !captureDuplicateExists(inbox, tab?.url)));
}

function homeTrailCandidateFingerprint() {
  if (openTabsLoadState !== 'ready') return openTabsLoadState;
  const candidate = homeTrailSaveCandidate();
  return JSON.stringify({
    state: openTabsLoadState,
    id: candidate?.id ?? null,
    windowId: candidate?.windowId ?? null,
    url: candidate?.url || '',
    pendingUrl: candidate?.pendingUrl || '',
    title: candidate?.title || '',
    fav: candidate?.favIconUrl || candidate?.fav || '',
  });
}

function activeHomeTrailFocusKey() {
  const active = document.activeElement?.closest?.('[data-home-trail-focus]');
  return active?.dataset?.homeTrailFocus || null;
}

function restoreHomeTrailFocus(key) {
  if (!key) return false;
  const target = document.querySelector(`[data-home-trail-focus="${key}"]`);
  if (!target || target.disabled) return false;
  try { target.focus({ preventScroll: true }); } catch { try { target.focus(); } catch { return false; } }
  return true;
}

function homeTrailPrimaryCloseSource(settings = State.get().settings) {
  return settings?.closeTabOnSave !== false;
}

function homeTrailGroupName(group) {
  return group?.name === 'Inbox' ? tr('nav.inbox') : String(group?.name || '');
}

function homeTrailPathParts(ws, cat, groupName) {
  return [ws?.name, cat?.name, groupName].map(value => String(value || '').trim()).filter(Boolean);
}

function homeTrailPathText(parts) {
  return (parts || []).join(' › ');
}

function homeTrailPathHtml(parts) {
  return `<ol class="home-trail-path">${(parts || []).map((part, index) =>
    `<li${index === (parts.length - 1) ? ' aria-current="location"' : ''}>${esc(part)}</li>`
  ).join('')}</ol>`;
}

function homeTrailItemVisual(item) {
  if (item?.type === 'tab') {
    return `<img class="home-trail-fav" src="${esc(favUrl(item.url) || BLANK_FAV)}" alt="" loading="lazy" decoding="async">`;
  }
  const glyph = item?.type === 'note' ? '📝'
    : item?.type === 'todo' ? (item.done ? '✓' : '○')
    : item?.type === 'stack' ? '▱'
    : '•';
  return `<span class="home-trail-glyph" aria-hidden="true">${glyph}</span>`;
}

function homeTrailDestinationContext(ws, cat) {
  if (!ws || !cat) return null;
  const inboxes = (cat.groups || []).filter(group => group?.name === 'Inbox');
  const parts = homeTrailPathParts(ws, cat, tr('nav.inbox'));
  return {
    workspaceId: String(ws.id || ''),
    spaceId: String(cat.id || ''),
    workspaceRef: ws,
    spaceRef: cat,
    workspaceName: String(ws.name || ''),
    spaceName: String(cat.name || ''),
    inboxCount: inboxes.length,
    inboxRef: inboxes.length === 1 ? inboxes[0] : null,
    parts,
    label: homeTrailPathText(parts),
  };
}

function homeTrailDestinationStillMatches(expected) {
  if (!expected?.workspaceId || !expected?.spaceId || expected.inboxCount > 1) return false;
  const state = State.get();
  const workspaces = (state.workspaces || []).filter(ws => String(ws?.id || '') === expected.workspaceId);
  if (workspaces.length !== 1 || workspaces[0] !== expected.workspaceRef
      || String(workspaces[0].name || '') !== expected.workspaceName
      || activeWs() !== workspaces[0]) return false;
  const spaces = (workspaces[0].categories || [])
    .filter(cat => String(cat?.id || '') === expected.spaceId);
  if (spaces.length !== 1 || spaces[0] !== expected.spaceRef
      || String(spaces[0].name || '') !== expected.spaceName
      || activeCat() !== spaces[0]) return false;
  const inboxes = (spaces[0].groups || []).filter(group => group?.name === 'Inbox');
  return inboxes.length === expected.inboxCount
    && (inboxes.length === 0 || inboxes[0] === expected.inboxRef);
}

function resolveHomeTrailSpaceReviewTarget(context) {
  if (!context?.workspaceId || !context?.spaceId || context.inboxCount <= 1) return null;
  try {
    const target = identitySpaceTarget(context.workspaceId, context.spaceId);
    if (!target
        || target.workspace !== context.workspaceRef
        || target.space !== context.spaceRef
        || String(target.workspace.name || '') !== context.workspaceName
        || String(target.space.name || '') !== context.spaceName
        || activeWs() !== target.workspace
        || activeCat() !== target.space) return null;
    return target;
  } catch {
    return null;
  }
}

function reportHomeTrailSpaceReviewUnavailable(opener = null) {
  toast(tr('home.trail.spaceUnavailable'), { danger: true, duration: 5000 });
  if (opener && typeof opener.focus === 'function') {
    requestAnimationFrame(() => {
      if (!opener.isConnected) return;
      try { opener.focus({ preventScroll: true }); } catch { opener.focus(); }
    });
  }
  return false;
}

function openHomeTrailSpaceReview(context, opener = null) {
  const target = resolveHomeTrailSpaceReviewTarget(context);
  if (!target) return reportHomeTrailSpaceReviewUnavailable(opener);
  const navigated = Router.navigate({
    type: 'board', wsId: target.workspace.id, catId: target.space.id, query: {},
  }, { persist: false });
  return navigated || reportHomeTrailSpaceReviewUnavailable(opener);
}

function setHomeTrailSaveBusy(pending) {
  const lane = document.querySelector('.home-trail-capture');
  lane?.setAttribute('aria-busy', String(!!pending));
  document.querySelectorAll('.home-trail-save').forEach(button => {
    button.disabled = !!pending || State.isRecoveryRequired();
  });
}

function createSavedItemRecoveryContext(target) {
  return {
    workspaceId: String(target?.ws?.id || ''),
    itemId: String(target?.item?.id || ''),
    workspaceRef: target?.ws || null,
    spaceRef: target?.cat || null,
    groupRef: target?.group || null,
    parentRefs: [...(target?.parents || [])],
    itemRef: target?.item || null,
    itemFingerprint: itemDetailValueFingerprint(target?.item),
    locationFingerprint: itemDetailLocationFingerprint(target),
  };
}

function resolveSavedItemRecoveryTarget(context) {
  if (!context?.workspaceId || !context?.itemId) return null;
  const target = resolveUniqueHomePreviewItem(context.workspaceId, context.itemId);
  if (!target
      || target.ws !== context.workspaceRef
      || target.cat !== context.spaceRef
      || target.group !== context.groupRef
      || target.item !== context.itemRef
      || (target.parents || []).length !== context.parentRefs.length
      || (target.parents || []).some((parent, index) => parent !== context.parentRefs[index])
      || itemDetailValueFingerprint(target.item) !== context.itemFingerprint
      || itemDetailLocationFingerprint(target) !== context.locationFingerprint) return null;
  return target;
}

function openHomeTrailSavedTab(context, opener = null) {
  const target = resolveSavedItemRecoveryTarget(context);
  if (!target || target.item?.type !== 'tab' || !isOpenableSavedTabUrl(target.item.url)) {
    toast(tr('home.trail.openUnavailable'), { danger: true, duration: 5000 });
    return false;
  }
  return openSavedTabItem(target.item, { focus: true, opener });
}

async function saveHomeTrailCandidate(candidate, destination, closeSource, restoreKeyboardFocus = false) {
  if (!candidate || homeTrailSavePending || captureCommitPending || State.isRecoveryRequired()) return false;
  homeTrailSavePending = true;
  setHomeTrailSaveBusy(true);
  const previousStatus = document.getElementById('home-trail-status');
  if (previousStatus) previousStatus.textContent = '';
  try {
    if (!homeTrailDestinationStillMatches(destination)) {
      toast(tr('home.trail.destinationChanged'), { danger: true, duration: 5000 });
      renderBoard();
      return false;
    }
    let currentTab = null;
    try { currentTab = await chrome.tabs.get(candidate.id); } catch {}
    if (!capturedTabStillMatches(candidate, currentTab)) {
      toast(tr('home.trail.candidateChanged'), { danger: true, duration: 5000 });
      await refreshOpenTabs();
      return false;
    }
    // The browser read above yields. Reconfirm the visible destination before
    // the shared capture controller performs its synchronous graph mutation.
    if (!homeTrailDestinationStillMatches(destination)) {
      toast(tr('home.trail.destinationChanged'), { danger: true, duration: 5000 });
      renderBoard();
      return false;
    }
    const outcome = await saveTabToInbox(currentTab, {
      closeSource: !!closeSource,
      returnOutcome: true,
    });
    if (outcome?.accepted !== true || !outcome.item) return false;
    if (!outcome.destinationConfirmed) {
      if (restoreKeyboardFocus) restoreHomeTrailFocus('capture');
      return true;
    }
    const trail = document.querySelector('.home-trail');
    trail?.classList.add('is-confirmed');
    const status = document.getElementById('home-trail-status');
    if (status) status.textContent = tr('home.trail.saved', { destination: destination.label });
    if (restoreKeyboardFocus) restoreHomeTrailFocus('open');
    setTimeout(() => trail?.classList.remove('is-confirmed'), 520);
    return true;
  } finally {
    homeTrailSavePending = false;
    setHomeTrailSaveBusy(false);
  }
}

function buildHomeTrail(ws) {
  const section = document.createElement('section');
  section.className = 'home-trail';
  section.setAttribute('aria-labelledby', 'home-trail-title');

  const latest = newestHomeRows(collectWorkspaceItems(ws), 1, { preferReopenableTab: true })[0] || null;
  if (latest?.item?.id) section.dataset.featuredItemId = String(latest.item.id);
  const header = document.createElement('header');
  header.className = 'home-trail-head';
  header.innerHTML = `
    <div>
      <h2 id="home-trail-title">${esc(tr('home.trail.latest'))}</h2>
      <p>${esc(ws.name)}</p>
    </div>
    <span id="home-trail-status" class="home-trail-status"></span>`;
  section.appendChild(header);

  const recovery = document.createElement('div');
  recovery.className = 'home-trail-recovery';
  if (!latest) {
    recovery.classList.add('is-empty');
    recovery.innerHTML = `
      <div class="home-trail-empty-mark" aria-hidden="true">◎</div>
      <div class="home-trail-empty-copy">
        <strong>${esc(tr('home.trail.emptyTitle'))}</strong>
        <span>${esc(tr('home.trail.emptyBody'))}</span>
      </div>`;
  } else {
    const { item, cat, group } = latest;
    const targetContext = createSavedItemRecoveryContext({ ws, ...latest });
    const title = _searchItemTitle(item);
    let detail = tr(homePreviewTypeKey(item.type));
    if (item.type === 'tab') {
      try { detail = new URL(item.url).hostname.replace(/^www\./, ''); } catch {}
    }
    const path = homeTrailPathParts(ws, cat, homeTrailGroupName(group));
    recovery.innerHTML = `
      <div class="home-trail-item">
        ${homeTrailItemVisual(item)}
        <div class="home-trail-item-copy">
          <strong>${esc(title)}</strong>
          <span>${esc(detail)}</span>
        </div>
      </div>
      <div class="home-trail-line" aria-hidden="true"><span></span></div>
      <div class="home-trail-destination">
        <span class="home-trail-label">${esc(tr('home.trail.savedDestination'))}</span>
        ${homeTrailPathHtml(path)}
      </div>`;
    const actions = document.createElement('div');
    actions.className = 'home-trail-recovery-actions';
    for (const action of homeTrailRecoveryActionPlan(item)) {
      const button = document.createElement('button');
      button.type = 'button';
      button.className = action.className;
      button.dataset.homeTrailFocus = action.key;
      if (action.key === 'open') {
        button.textContent = tr('home.trail.openPage');
        button.setAttribute('aria-label', tr('home.trail.openItem', { title }));
        button.addEventListener('click', () => openHomeTrailSavedTab(targetContext, button));
      } else {
        button.textContent = tr('home.trail.review');
        button.setAttribute('aria-label', tr('home.trail.reviewItem', { title }));
        button.addEventListener('click', event => {
          if (!resolveSavedItemRecoveryTarget(targetContext)) {
            toast(tr('home.trail.itemUnavailable'), { danger: true, duration: 5000 });
            return;
          }
          openHomePreviewItem(ws.id, item.id, homePreviewFocusKey(ws.id, 'trail', item.id), event.currentTarget);
        });
      }
      actions.appendChild(button);
    }
    recovery.appendChild(actions);
  }
  section.appendChild(recovery);

  const cat = activeCat();
  const destination = homeTrailDestinationContext(ws, cat);
  const destinationAvailable = !!destination && destination.inboxCount <= 1;
  const destinationParts = destination?.parts || [];
  const destinationLabel = destination?.label || '';
  const candidate = homeTrailSaveCandidate(allOpenTabs, cat);
  const capture = document.createElement('div');
  capture.className = 'home-trail-capture';
  capture.tabIndex = -1;
  capture.dataset.homeTrailFocus = 'capture';
  capture.setAttribute('role', 'group');
  capture.setAttribute('aria-labelledby', 'home-trail-candidate-label');
  capture.setAttribute('aria-busy', String(openTabsLoadState === 'loading' || homeTrailSavePending));
  capture.innerHTML = `
    <div class="home-trail-next">
      <span id="home-trail-candidate-label" class="home-trail-label">${esc(tr('home.trail.candidate'))}</span>
      <div class="home-trail-candidate"></div>
    </div>
    <div class="home-trail-next-destination">
      <span class="home-trail-label">${esc(tr('home.trail.saveDestination'))}</span>
      ${destinationAvailable ? homeTrailPathHtml(destinationParts) : `<p id="home-trail-destination-message" class="home-trail-unavailable">${esc(tr(cat ? 'home.trail.destinationConflict' : 'home.trail.noDestination'))}</p>`}
    </div>
    <div class="home-trail-save-area"></div>`;

  const candidateNode = capture.querySelector('.home-trail-candidate');
  const saveArea = capture.querySelector('.home-trail-save-area');
  const blockedDestinationActions = homeTrailBlockedDestinationActionPlan(
    cat, destination, { recoveryHasPrimary: !!latest },
  );
  for (const action of blockedDestinationActions) {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = action.className;
    button.textContent = tr(action.labelKey);
    button.dataset.homeTrailFocus = action.key;
    button.setAttribute('aria-describedby', 'home-trail-destination-message');
    if (action.ariaLabelKey) button.setAttribute('aria-label', tr(action.ariaLabelKey, { name: cat?.name || '' }));
    button.disabled = State.isRecoveryRequired();
    button.addEventListener('click', event => {
      if (action.key === 'create-space') openOrganizationCreate('space', {}, event.currentTarget);
      else if (action.key === 'review-space') openHomeTrailSpaceReview(destination, event.currentTarget);
    });
    saveArea.appendChild(button);
  }
  if (openTabsLoadState === 'loading') {
    candidateNode.innerHTML = `<span class="home-trail-loading" aria-hidden="true"></span><span>${esc(tr('home.trail.checking'))}</span>`;
  } else if (openTabsLoadState === 'error') {
    candidateNode.textContent = tr('home.trail.queryError');
    const retry = document.createElement('button');
    retry.type = 'button';
    retry.className = 'btn-secondary';
    retry.textContent = tr('home.trail.retry');
    retry.dataset.homeTrailFocus = 'retry';
    retry.addEventListener('click', async event => {
      const restoreKeyboardFocus = event.detail === 0;
      openTabsLoadState = 'loading';
      capture.setAttribute('aria-busy', 'true');
      retry.disabled = true;
      retry.textContent = tr('home.trail.checking');
      await refreshOpenTabs();
      if (restoreKeyboardFocus) {
        restoreHomeTrailFocus('save-primary') || restoreHomeTrailFocus('retry') || restoreHomeTrailFocus('capture');
      }
    });
    if (!blockedDestinationActions.length) saveArea.appendChild(retry);
  } else if (!candidate) {
    candidateNode.textContent = tr('home.trail.noCandidate');
  } else {
    let domain = candidate.url;
    try { domain = new URL(candidate.url).hostname.replace(/^www\./, ''); } catch {}
    candidateNode.innerHTML = `
      <img class="home-trail-fav" src="${esc(favUrl(candidate.url) || BLANK_FAV)}" alt="" loading="lazy" decoding="async">
      <span class="home-trail-item-copy">
        <strong>${esc(String(candidate.title || domain || candidate.url).trim())}</strong>
        <span>${esc(domain)}</span>
      </span>`;
    if (destinationAvailable) {
      const closePrimary = homeTrailPrimaryCloseSource();
      const hintId = 'home-trail-save-hint';
      const captureActions = homeTrailCaptureActionPlan({
        closePrimary,
        recoveryHasPrimary: !!latest,
      });
      const buttons = captureActions.map(action => {
        const button = document.createElement('button');
        button.type = 'button';
        button.className = action.className;
        button.textContent = tr(action.closeSource ? 'home.trail.saveClose' : 'home.trail.saveKeepOpen');
        button.dataset.homeTrailFocus = action.key;
        if (action.key === 'save-primary') button.setAttribute('aria-describedby', hintId);
        button.disabled = homeTrailSavePending || State.isRecoveryRequired();
        button.addEventListener('click', event => saveHomeTrailCandidate(
          candidate,
          destination,
          action.closeSource,
          event.detail === 0,
        ));
        return button;
      });
      const hint = document.createElement('p');
      hint.id = hintId;
      hint.className = 'home-trail-save-hint';
      hint.textContent = tr(closePrimary ? 'home.trail.saveCloseHint' : 'home.trail.saveKeepOpenHint', {
        destination: destinationLabel,
      });
      saveArea.append(...buttons, hint);
    }
  }
  section.appendChild(capture);
  return section;
}

// Home previews show real saved records and route directly into their existing
// recovery sheet. They keep only primitive identity across the Home render.
function resolveUniqueHomePreviewItem(workspaceId, itemId) {
  if (!workspaceId || !itemId) return null;
  const state = State.get();
  const workspaces = (state.workspaces || []).filter(workspace => workspace.id === workspaceId);
  if (workspaces.length !== 1) return null;
  const matches = (state.workspaces || []).flatMap(workspace =>
    collectWorkspaceItems(workspace)
      .filter(row => row.item?.id === itemId)
      .map(row => ({ ws: workspace, ...row }))
  );
  if (matches.length !== 1 || matches[0].ws !== workspaces[0]) return null;
  const target = matches[0];
  const spaces = (target.ws.categories || []).filter(space => space.id === target.cat?.id);
  return spaces.length === 1 ? target : null;
}

function homePreviewFocusKey(workspaceId, origin, itemId) {
  return [workspaceId, origin, itemId].map(value => encodeURIComponent(String(value || ''))).join(':');
}

function homePreviewRoute(target) {
  if (!target?.ws?.id || !target?.cat?.id || !target?.item?.id) return null;
  return { type: 'home', wsId: target.ws.id, query: { item: target.item.id } };
}

function openHomePreviewItem(workspaceId, itemId, returnFocusKey, opener) {
  focusDialogOpener(opener);
  const target = resolveUniqueHomePreviewItem(workspaceId, itemId);
  const route = homePreviewRoute(target);
  if (!target || !route) {
    toast(tr('home.previewUnavailable'), { danger: true, duration: 5000 });
    return false;
  }
  prepareItemDetailOpen(target.item.id, returnFocusKey);
  // The hash is the navigation record. Keeping the detail over Home avoids
  // selecting or rendering its owning Space, so a recovery view cannot create
  // an incidental whole-state or advanced-layout write.
  Router.navigate(route, { persist: false });
  return true;
}

function homePreviewTypeKey(type) {
  return `home.previewType.${['tab', 'note', 'todo', 'stack'].includes(type) ? type : 'item'}`;
}

function buildHomePreviewRow(it, { workspaceId, origin }) {
  const row = document.createElement('button');
  row.type = 'button';
  row.className = 'home-prow';
  row.dataset.itemId = String(it?.id || '');
  const returnFocusKey = homePreviewFocusKey(workspaceId, origin, it?.id);
  row.dataset.homePreviewKey = returnFocusKey;
  let icon, label, sub = '';
  if (it.type === 'tab') {
    icon = `<img class="home-prow-fav" src="${esc(favUrl(it.url) || BLANK_FAV)}" alt="" loading="lazy" decoding="async">`;
    label = _searchItemTitle(it);
    try { sub = new URL(it.url).hostname.replace(/^www\./, ''); } catch {}
  } else if (it.type === 'note') {
    icon = `<span class="home-prow-glyph">📝</span>`;
    label = _searchItemTitle(it);
  } else if (it.type === 'todo') {
    icon = `<span class="home-prow-glyph">${it.done ? '☑' : '☐'}</span>`;
    label = _searchItemTitle(it);
  } else if (it.type === 'stack') {
    icon = `<span class="home-prow-glyph">📚</span>`;
    label = _searchItemTitle(it);
  } else {
    icon = `<span class="home-prow-glyph">•</span>`;
    label = _searchItemTitle(it) || tr('home.previewType.item');
  }
  const text = sub
    ? `<span class="home-prow-text"><span class="home-prow-title">${esc(label)}</span><span class="home-prow-domain">${esc(sub)}</span></span>`
    : `<span class="home-prow-text"><span class="home-prow-title">${esc(label)}</span></span>`;
  row.innerHTML = `${icon}${text}`;
  row.setAttribute('aria-label', tr('home.previewOpen', {
    type: tr(homePreviewTypeKey(it.type)),
    title: label,
  }));
  row.addEventListener('click', event => {
    openHomePreviewItem(workspaceId, it.id, returnFocusKey, event.currentTarget);
  });
  return row;
}

function newestHomeItems(items, limit = 3) {
  return (items || [])
    .map((item, index) => ({ item, index, createdAt: Number(item?.createdAt) || 0 }))
    .sort((a, b) => b.createdAt - a.createdAt || b.index - a.index)
    .slice(0, limit)
    .map(entry => entry.item);
}

function homeProgressiveZonePlan(ws, inboxContext) {
  const showSpaces = Array.isArray(ws?.categories) && ws.categories.length > 0;
  const showInbox = showSpaces
    && inboxContext?.inboxCount === 1
    && !!inboxContext.inboxRef
    && !!String(inboxContext.groupId || '').trim();
  return { showInbox, showSpaces };
}

function buildHomeInboxZone({ context, excludeItemId = null } = {}) {
  const ws = context?.workspaceRef || null;
  const cat = context?.spaceRef || null;
  const inbox = context && context.inboxRef;
  const items = Array.isArray(inbox?.items) ? inbox.items : [];
  const previewItems = items.filter(item => item?.id !== excludeItemId);
  const section = document.createElement('section');
  section.className = 'home-loop-zone';
  section.setAttribute('aria-labelledby', 'home-loop-title');

  const header = document.createElement('div');
  header.className = 'home-loop-head';
  header.innerHTML = `
    <div>
      <h2 id="home-loop-title">${esc(tr('home.inboxZone'))}</h2>
      <p>${esc(tr('home.inboxHint'))}</p>
    </div>
    <span class="home-loop-count">${esc(tr('home.items', { n: items.length }))}</span>`;
  section.appendChild(header);

  const preview = document.createElement('div');
  preview.className = 'home-loop-preview';
  if (previewItems.length) newestHomeItems(previewItems).forEach(item => preview.appendChild(buildHomePreviewRow(item, {
    workspaceId: ws?.id,
    origin: `inbox:${cat?.id || ''}`,
  })));
  else {
    const empty = document.createElement('p');
    empty.className = 'home-card-empty';
    empty.textContent = items.length ? tr('home.inboxNoOtherItems') : tr('home.empty');
    preview.appendChild(empty);
  }
  section.appendChild(preview);

  const actions = document.createElement('div');
  actions.className = 'home-loop-actions';
  const open = document.createElement('button');
  open.type = 'button';
  open.className = 'btn-secondary';
  open.textContent = tr('home.openInbox');
  open.disabled = !inbox;
  open.addEventListener('click', event => openInboxView(context, event.currentTarget));
  actions.appendChild(open);
  section.appendChild(actions);
  return section;
}

// ════════════════════════════════════════════════════════════════
// TODAY BOARD (2026-11 canvas)
// ════════════════════════════════════════════════════════════════
// Home renders the Today board: a rolling clock, one Now card, the rest of
// today, and a capture bar. Every task is an ordinary to-do in the active
// Workspace. "Today" is derived from fields that already exist: a reminder time
// today, an open reminder from an earlier day, or (with no reminder) a to-do
// created today. No stored field is added. The Later order is per-device view
// state in localStorage, scoped to the calendar day, like the theme mirror.
const TODAY_LATER_STORAGE_KEY = 'locus.today.later';
const TODAY_LATER_LIMIT = 200;
let todayLaterMemory = { day: '', ids: [] };
let todayCaptureDraft = '';
let todayCapturePending = null;
let todayCaptureComposing = false;
let todayCaptureTokenKeys = new Set();
let todayRenderDeferred = false;
let todayMotionPending = false;
let todayClockTimer = null;
let todayJustAddedId = null;
let todayNowEnters = false;

function todayPad2(value) {
  return String(value).padStart(2, '0');
}

function todayDayKey(now = Date.now()) {
  const date = new Date(now);
  return `${date.getFullYear()}-${todayPad2(date.getMonth() + 1)}-${todayPad2(date.getDate())}`;
}

function todayDayBounds(now = Date.now()) {
  const start = new Date(now);
  start.setHours(0, 0, 0, 0);
  const end = new Date(start);
  end.setDate(end.getDate() + 1);
  return { start: start.getTime(), end: end.getTime(), key: todayDayKey(now) };
}

function todayClockText(at) {
  const date = new Date(at);
  return `${todayPad2(date.getHours())}:${todayPad2(date.getMinutes())}`;
}

// Today's to-dos for one Workspace, in board order: open reminders from an
// earlier day, reminders due now, anytime to-dos (created today, no reminder),
// reminders later today; then IDs deferred with Later, in deferral order; done
// to-dos last. A duplicated stable ID is left out because no exact-identity
// action could reach it. A repeating reminder shows today's occurrence: the one
// the background fired today (reminder.firedAt, recorded when it re-arms the
// series) or the next one from a stale stored `at`, never a missed earlier day
// and never a series that has not started. A repeating to-do marked done stays
// off the board. Undated to-dos marked Someday in Plan are not "anytime".
function todayTaskModel(workspace, now = Date.now(), laterIds = [], somedayIds = null) {
  const someday = somedayIds instanceof Set ? somedayIds : new Set(Array.isArray(somedayIds) ? somedayIds.map(String) : []);
  const { start, end } = todayDayBounds(now);
  const todos = [];
  const walk = items => (Array.isArray(items) ? items : []).forEach(item => {
    if (!item || typeof item !== 'object') return;
    if (item.type === 'stack') { walk(item.items); return; }
    if (item.type === 'todo') todos.push(item);
  });
  (Array.isArray(workspace?.categories) ? workspace.categories : []).forEach(space => {
    (Array.isArray(space?.groups) ? space.groups : []).forEach(group => walk(group?.items));
  });
  const idCounts = new Map();
  todos.forEach(item => {
    const id = String(item.id || '');
    idCounts.set(id, (idCounts.get(id) || 0) + 1);
  });
  const entries = [];
  todos.forEach(item => {
    const id = String(item.id || '');
    if (!id || idCounts.get(id) !== 1) return;
    const done = item.done === true;
    const storedAt = item.reminder && item.reminder.at != null ? Number(item.reminder.at) : NaN;
    let at = Number.isFinite(storedAt) ? storedAt : null;
    const createdAt = Number(item.createdAt);
    const recur = ['day', 'week', 'month'].includes(item.reminder?.recur?.every) ? item.reminder.recur : null;
    let repeating = false;
    if (at != null && recur && done) {
      // Done on a repeating to-do is permanent while its alarms keep re-arming;
      // it is not today's work any more.
      return;
    }
    if (at != null && recur) {
      const firedAt = Number(item.reminder.firedAt);
      if (at < start) {
        const next = nextReminderOccurrenceForDisplay(at, recur, start - 1);
        if (Number.isFinite(next)) { at = next; repeating = true; }
      } else if (at >= end) {
        // The alarm fired earlier today and re-armed the series past today.
        if (Number.isFinite(firedAt) && firedAt >= start && firedAt < end && firedAt <= now) at = firedAt;
        repeating = true;
      } else repeating = true;
    }
    let kind = null;
    if (at != null) {
      if (at >= start && at < end) kind = at <= now ? 'due' : 'upcoming';
      else if (at < start && !done && !repeating) kind = 'overdue';
    } else if (Number.isFinite(createdAt) && createdAt >= start && createdAt < end && !someday.has(id)) {
      kind = 'anytime';
    }
    if (!kind) return;
    entries.push({
      item,
      id,
      at,
      done,
      kind,
      createdAt: Number.isFinite(createdAt) ? createdAt : 0,
      title: String(item.text || '').trim(),
    });
  });
  const rank = { overdue: 0, due: 1, anytime: 2, upcoming: 3 };
  const order = (a, b) => (rank[a.kind] - rank[b.kind])
    || ((a.at ?? a.createdAt) - (b.at ?? b.createdAt))
    || (a.id < b.id ? -1 : (a.id > b.id ? 1 : 0));
  const openEntries = entries.filter(entry => !entry.done).sort(order);
  const deferred = [];
  (Array.isArray(laterIds) ? laterIds : []).forEach(raw => {
    const match = openEntries.find(entry => entry.id === String(raw));
    if (match && !deferred.includes(match)) deferred.push(match);
  });
  const open = openEntries.filter(entry => !deferred.includes(entry)).concat(deferred);
  const finished = entries.filter(entry => entry.done).sort(order);
  return {
    open,
    finished,
    now: open[0] || null,
    rest: open.slice(1).concat(finished),
    total: entries.length,
    doneCount: finished.length,
  };
}

function readTodayLaterIds(now = Date.now()) {
  const day = todayDayKey(now);
  const clean = ids => ids.filter(id => typeof id === 'string' && id).slice(-TODAY_LATER_LIMIT);
  try {
    const raw = localStorage.getItem(TODAY_LATER_STORAGE_KEY);
    if (raw != null) {
      const stored = JSON.parse(raw);
      return stored && stored.day === day && Array.isArray(stored.ids) ? clean(stored.ids) : [];
    }
  } catch {}
  return todayLaterMemory.day === day ? clean(todayLaterMemory.ids) : [];
}

// Later moves a task behind every other open task for the rest of the day. It
// is view order only, so it never enters Undo history or the stored graph.
function deferTodayTask(id, now = Date.now()) {
  const key = String(id || '');
  if (!key) return false;
  const ids = readTodayLaterIds(now).filter(existing => existing !== key);
  ids.push(key);
  todayLaterMemory = { day: todayDayKey(now), ids: ids.slice(-TODAY_LATER_LIMIT) };
  try {
    localStorage.setItem(TODAY_LATER_STORAGE_KEY, JSON.stringify(todayLaterMemory));
  } catch {}
  return true;
}

function todayShortDay(at) {
  const zh = appLocale() === 'zh-TW';
  return new Intl.DateTimeFormat(zh ? 'zh-TW' : 'en-GB', zh
    ? { month: 'numeric', day: 'numeric', weekday: 'short' }
    : { weekday: 'short', day: 'numeric', month: 'short' }).format(new Date(at));
}

function todayDateLine(now = Date.now()) {
  const zh = appLocale() === 'zh-TW';
  return new Intl.DateTimeFormat(zh ? 'zh-TW' : 'en-GB', zh
    ? { month: 'long', day: 'numeric', weekday: 'long' }
    : { weekday: 'long', day: 'numeric', month: 'long' }).format(new Date(now));
}

function todayWhenLabel(entry) {
  if (entry.done) return { text: tr('today.done'), tone: 'done' };
  if (entry.at == null) return { text: tr('today.anytime'), tone: 'anytime' };
  if (entry.kind === 'overdue') return { text: `${todayShortDay(entry.at)} ${todayClockText(entry.at)}`, tone: 'when' };
  return { text: todayClockText(entry.at), tone: 'when' };
}

function todayTaskTitle(entry) {
  return entry?.title || tr('detail.emptyTodo');
}

function todayReducedMotion() {
  if (document.body?.dataset.anim === 'off') return true;
  try { return window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch { return false; }
}

function todayWait(ms) {
  return ms > 0 ? new Promise(resolve => setTimeout(resolve, ms)) : Promise.resolve();
}

// Reads one capture line into a to-do title, an optional reminder time, and an
// optional #space. The words it understands are the ones highlighted while
// typing. Zone, day arithmetic, and DST gaps come from plan-contract.js.
function parseTodayCapture(text, { now = Date.now(), timeZone = '', spaces = [] } = {}) {
  const source = String(text || '');
  const Plan = typeof LocusPlan !== 'undefined' ? LocusPlan : null;
  const result = {
    title: '',
    tokens: [],
    at: null,
    dayOffset: null,
    minutes: null,
    rolled: false,
    spaceId: null,
    spaceName: '',
  };
  const found = [];
  // Full-width digits and letters are read as ASCII one character at a time, so
  // token offsets still point into the text exactly as typed.
  const scan = Array.from(source).map(ch => {
    const folded = ch.normalize('NFKC');
    return folded.length === ch.length ? folded : ch;
  }).join('');
  // Words inside quotes stay literal: `read "today's report"` schedules nothing.
  const quoted = [];
  const quotePattern = /\x22[^\x22]*\x22|“[^”]*”|「[^」]*」|『[^』]*』/g;
  // A bare H:MM without am/pm counts only after at/by, with a two-digit hour,
  // or beside a day or part-of-day word, so "read John 3:16" stays a title.
  const enWhen = /\b(?:(at|on|by|this)\s+)?(today|tonight|tomorrow|next\s+week|weekend|monday|mon|tuesday|tues|tue|wednesday|thursday|thurs|thur|thu|friday|fri|saturday|sunday|morning|afternoon|evening|noon|(\d{1,2})(?::([0-5]\d))?\s?(am|pm)|([01]?\d|2[0-3]):([0-5]\d))(?![\x27’\w])/gi;
  const zhWhen = /(下(?:[週周]|星期|禮拜)[一二三四五六日天]|(?:[週周]|星期|禮拜)[一二三四五六日天]|下[週周]|下星期|下禮拜|今天|今晚|明天|後天|[週周]末|早上|上午|中午|下午|晚上)|(\d{1,2})\s*點(?![心數子餐名擊閱菜火播評選])(?:\s*(半)|(\d{1,2})分?|\s+(\d{1,2})\s*分)?/g;
  const tagPattern = /#([\p{L}\p{N}_-]+)/gu;
  let match;
  while ((match = quotePattern.exec(scan))) quoted.push([match.index, match.index + match[0].length]);
  const inQuote = (start, end) => quoted.some(([a, b]) => start < b && end > a);
  while ((match = enWhen.exec(scan))) {
    const prefix = String(match[1] || '').toLowerCase();
    found.push({
      start: match.index,
      end: match.index + match[0].length,
      kind: 'when',
      word: match[2].toLowerCase().replace(/\s+/g, ' '),
      clock: match[3] != null
        ? { hour: Number(match[3]), minute: Number(match[4] || 0), meridiem: match[5].toLowerCase() }
        : (match[6] != null ? { hour: Number(match[6]), minute: Number(match[7]), meridiem: null } : null),
      bare: match[6] != null && match[6].length < 2 && prefix !== 'at' && prefix !== 'by',
    });
  }
  while ((match = zhWhen.exec(scan))) {
    found.push({
      start: match.index,
      end: match.index + match[0].length,
      kind: 'when',
      word: String(match[1] || '').replace(/周/g, '週'),
      clock: match[2] != null
        ? { hour: Number(match[2]), minute: match[3] ? 30 : Number(match[4] || match[5] || 0), meridiem: null }
        : null,
    });
  }
  const hasDayWord = found.some(token => token.kind === 'when' && !token.clock && !inQuote(token.start, token.end));
  for (let i = found.length - 1; i >= 0; i -= 1) {
    const token = found[i];
    if (inQuote(token.start, token.end) || (token.bare && !hasDayWord)) found.splice(i, 1);
  }
  const normalize = value => String(value || '').normalize('NFKC').toLowerCase().replace(/[\s_-]+/g, '');
  const candidates = (Array.isArray(spaces) ? spaces : [])
    .map(space => ({ id: String(space?.id || ''), name: String(space?.name || ''), key: normalize(space?.name) }))
    .filter(space => space.id && space.key);
  const resolveSpace = tag => {
    const key = normalize(tag);
    if (!key) return null;
    const exact = candidates.filter(space => space.key === key);
    if (exact.length) return exact.length === 1 ? exact[0] : null;
    const prefix = candidates.filter(space => space.key.startsWith(key));
    return prefix.length === 1 ? prefix[0] : null;
  };
  while ((match = tagPattern.exec(scan))) {
    const space = resolveSpace(match[1]);
    if (space && !inQuote(match.index, match.index + match[0].length)) {
      found.push({ start: match.index, end: match.index + match[0].length, kind: 'where', space });
    }
  }
  found.sort((a, b) => a.start - b.start || b.end - a.end);
  const kept = [];
  found.forEach(token => {
    const last = kept[kept.length - 1];
    if (!last || token.start >= last.end) kept.push(token);
  });

  const weekdays = { monday: 0, mon: 0, tuesday: 1, tues: 1, tue: 1, wednesday: 2, thursday: 3, thurs: 3, thur: 3, thu: 3, friday: 4, fri: 4, saturday: 5, sunday: 6 };
  const zhWeekdays = { '一': 0, '二': 1, '三': 2, '四': 3, '五': 4, '六': 5, '日': 6, '天': 6 };
  const partMinutes = { morning: 540, noon: 720, afternoon: 840, evening: 1140, '早上': 540, '上午': 540, '中午': 720, '下午': 840, '晚上': 1140 };
  const afternoonParts = ['afternoon', 'evening', '下午', '晚上'];
  let day = null;
  let part = null;
  let clock = null;
  let spaceToken = null;
  kept.forEach(token => {
    if (token.kind === 'where') {
      if (!spaceToken) spaceToken = token;
      return;
    }
    if (token.clock) {
      if (!clock) clock = token.clock;
      return;
    }
    const word = token.word;
    const last = word.slice(-1);
    if (word === 'today' || word === '今天') day = day || { offset: 0 };
    else if (word === 'tonight' || word === '今晚') {
      day = day || { offset: 0 };
      part = part || 'evening';
    } else if (word === 'tomorrow' || word === '明天') day = day || { offset: 1 };
    else if (word === '後天') day = day || { offset: 2 };
    else if (word === 'next week' || word === '下週' || word === '下星期' || word === '下禮拜') day = day || { nextWeek: true, weekday: 0 };
    else if (word === 'weekend' || word === '週末') day = day || { weekday: 5, defaultMinutes: 600, weekend: true };
    else if (weekdays[word] != null) day = day || { weekday: weekdays[word] };
    else if (word.startsWith('下') && zhWeekdays[last] != null) day = day || { nextWeek: true, weekday: zhWeekdays[last] };
    else if (zhWeekdays[last] != null) day = day || { weekday: zhWeekdays[last] };
    else if (partMinutes[word] != null) part = part || word;
  });

  let minutes = null;
  let fromClock = false;
  let nextDay = 0;
  if (clock && clock.minute <= 59) {
    let hour = clock.hour;
    const evening = part === 'evening' || part === '晚上';
    if (clock.meridiem === 'pm' && hour >= 1 && hour < 12) hour += 12;
    else if (clock.meridiem === 'am' && hour === 12) {
      hour = 0;
      if (evening) nextDay = 1;
    } else if (!clock.meridiem && hour === 12 && evening) {
      // "12 tonight" / 晚上12點 is the midnight that ends the evening.
      hour = 0;
      nextDay = 1;
    } else if (!clock.meridiem && part && afternoonParts.includes(part) && hour >= 1 && hour < 12) hour += 12;
    const meridiemValid = !clock.meridiem || (clock.hour >= 1 && clock.hour <= 12);
    if (hour <= 23 && meridiemValid) {
      minutes = hour * 60 + clock.minute;
      fromClock = true;
    } else nextDay = 0;
  }
  if (minutes == null && part) minutes = partMinutes[part];
  if (minutes == null && day) minutes = day.defaultMinutes ?? 540;

  if (minutes != null && Plan) {
    let zone = timeZone ? Plan.canonicalTimeZone(timeZone) : null;
    if (!zone) {
      try { zone = Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC'; } catch { zone = 'UTC'; }
    }
    const todayIso = Plan.todayInZone(zone, now);
    const todayIndex = Plan.weekdayIndex(todayIso);
    let offset = 0;
    if (day?.offset != null) offset = day.offset;
    else if (day?.nextWeek) offset = (7 - todayIndex) + day.weekday;
    else if (day?.weekday != null) offset = (day.weekday - todayIndex + 7) % 7;
    const resolve = dayOffset => {
      const iso = Plan.addDays(todayIso, dayOffset);
      let wall = Plan.zonedWallToEpoch(iso, minutes, zone);
      if (wall.status === 'gap') wall = Plan.zonedWallToEpoch(iso, Plan.parseHm(wall.suggestion), zone);
      return wall.status === 'ok' || wall.status === 'ambiguous' ? wall.at : null;
    };
    offset += nextDay;
    let at = resolve(offset);
    if (at != null && at <= now) {
      if (!day) {
        // No day word: a passed time means the same time tomorrow.
        offset += 1;
        at = resolve(offset);
        result.rolled = true;
      } else if (!fromClock && day.weekday != null && !day.nextWeek) {
        // A default time on a weekday that is today and already past means the
        // next one; on a Saturday afternoon the weekend still has its Sunday.
        offset += day.weekend ? 1 : 7;
        at = resolve(offset);
        result.rolled = true;
      } else if (!fromClock && day.offset === 0) {
        // "today" / "tonight" with no clock and the default gone: next whole hour.
        const nowMinutes = Plan.epochToZoned(now, zone).minutes;
        const nextHour = (Math.floor(nowMinutes / 60) + 1) * 60;
        offset = nextHour >= 1440 ? 1 : 0;
        minutes = nextHour >= 1440 ? 0 : nextHour;
        at = resolve(offset);
        result.rolled = true;
      }
    }
    if (at != null) {
      result.at = at;
      result.dayOffset = offset;
      result.minutes = minutes;
    }
  }

  let title = '';
  let cursor = 0;
  kept.forEach(token => {
    title += `${source.slice(cursor, token.start)} `;
    cursor = token.end;
  });
  title += source.slice(cursor);
  result.title = title
    .replace(/\s+/g, ' ')
    .replace(/^[\s,;:·，、。-]+|[\s,;:·，、。-]+$/g, '')
    .trim();
  result.tokens = kept.map(token => ({ start: token.start, end: token.end, kind: token.kind }));
  if (spaceToken) {
    result.spaceId = spaceToken.space.id;
    result.spaceName = spaceToken.space.name;
  }
  return result;
}

// ── Clock ──
function buildTodayClock(now = Date.now()) {
  const block = document.createElement('div');
  block.className = 'today-clock-block';
  const clock = document.createElement('div');
  clock.className = 'today-clock';
  clock.setAttribute('role', 'img');
  const stack = Array.from({ length: 12 }, (_, index) => `<span>${index % 10}</span>`).join('');
  const digit = `<span class="today-digit" aria-hidden="true"><span class="today-digit-stack">${stack}</span></span>`;
  clock.innerHTML = `${digit}${digit}<span class="today-colon" aria-hidden="true">:</span>${digit}${digit}`;
  const minute = document.createElement('div');
  minute.className = 'today-minute';
  minute.setAttribute('aria-hidden', 'true');
  minute.innerHTML = '<span class="today-minute-fill"></span>';
  const date = document.createElement('p');
  date.className = 'today-date';
  block.append(clock, minute, date);
  paintTodayClock(block, { now, animate: false });
  return block;
}

// Digits roll upward. A digit that wraps (9→0, 5→0, 2→0) rolls on to the
// repeated 0 at the bottom of its stack, then snaps back without a transition.
function paintTodayClock(block, { now = Date.now(), animate = true } = {}) {
  const clock = block?.querySelector?.('.today-clock');
  if (!clock) return false;
  const date = new Date(now);
  const hours = date.getHours();
  const minutes = date.getMinutes();
  const seconds = date.getSeconds();
  const digits = [Math.floor(hours / 10), hours % 10, Math.floor(minutes / 10), minutes % 10];
  const motion = animate && !todayReducedMotion();
  clock.querySelectorAll('.today-digit-stack').forEach((stack, index) => {
    const digit = digits[index];
    const known = stack.dataset.digit !== undefined;
    const last = Number(stack.dataset.digit);
    if (known && last === digit) return;
    clearTimeout(Number(stack.dataset.snapTimer) || 0);
    let position = digit;
    let snapBack = false;
    if (motion && known) {
      if (digit < last && digit + 10 <= 11) {
        position = digit + 10;
        snapBack = true;
      }
      stack.classList.toggle('is-snap', !(digit > last || snapBack));
    } else {
      stack.classList.add('is-snap');
    }
    stack.style.transform = `translateY(${-position}em)`;
    stack.dataset.digit = String(digit);
    if (snapBack) {
      stack.dataset.snapTimer = String(setTimeout(() => {
        stack.classList.add('is-snap');
        stack.style.transform = `translateY(${-digit}em)`;
      }, 900));
    }
  });
  clock.setAttribute('aria-label', `${todayPad2(hours)}:${todayPad2(minutes)}`);
  const fill = block.querySelector('.today-minute-fill');
  if (fill) {
    fill.classList.toggle('is-snap', !motion || seconds === 0);
    fill.style.transform = `scaleX(${(seconds / 60).toFixed(4)})`;
  }
  const line = block.querySelector('.today-date');
  if (line) {
    const text = todayDateLine(now);
    if (line.textContent !== text) line.textContent = text;
  }
  return true;
}

function stopTodayClock() {
  if (todayClockTimer) clearTimeout(todayClockTimer);
  todayClockTimer = null;
}

// One self-aligning tick per second while Today is mounted; it stops itself
// once the board is gone and repaints Home when the calendar day changes.
function startTodayClock() {
  stopTodayClock();
  const schedule = () => {
    todayClockTimer = setTimeout(tick, 1000 - (Date.now() % 1000) + 20);
  };
  const tick = () => {
    todayClockTimer = null;
    const board = document.querySelector('#board .today');
    if (!board || !board.isConnected) return;
    if (!document.hidden) {
      const now = Date.now();
      if (board.dataset.todayDay !== todayDayKey(now)
          && activeHome
          && !todayMotionPending
          && !todayCapturePending
          && !isBoardTodoCompletionPending()) {
        renderBoard();
        return;
      }
      paintTodayClock(board.querySelector('.today-clock-block'), { now, animate: true });
    }
    schedule();
  };
  schedule();
}

// ── Now card + rest of today ──
const TODAY_ARROW_ICON = '<svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 8h10M9 4l4 4-4 4"/></svg>';

function buildTodayNow(workspace, model) {
  const section = document.createElement('section');
  section.className = `today-now${todayNowEnters ? ' is-entering' : ''}`;
  todayNowEnters = false;
  section.setAttribute('aria-labelledby', 'today-now-title');
  const entry = model.now;
  if (entry) section.dataset.todayId = entry.id;

  const head = document.createElement('div');
  head.className = 'today-now-head';
  head.innerHTML = `<span class="today-now-beat" aria-hidden="true"></span><h2 id="today-now-title">${esc(tr('today.now'))}</h2>`;
  if (model.total) {
    const progress = document.createElement('div');
    progress.className = 'today-progress';
    progress.setAttribute('role', 'img');
    progress.setAttribute('aria-label', tr('today.progress', { done: model.doneCount, total: model.total }));
    const pills = Math.min(model.total, 12);
    const filled = model.total <= 12 ? model.doneCount : Math.round((model.doneCount / model.total) * 12);
    for (let index = 0; index < pills; index += 1) {
      const pill = document.createElement('span');
      pill.className = `today-progress-pill${index < filled ? ' is-done' : ''}`;
      progress.appendChild(pill);
    }
    head.appendChild(progress);
  }
  section.appendChild(head);

  const body = document.createElement('div');
  body.className = 'today-now-body';
  if (entry) {
    const title = todayTaskTitle(entry);
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'today-now-title';
    button.dataset.itemId = entry.id;
    button.dataset.todayFocus = `now-title:${entry.id}`;
    button.tabIndex = 0;
    button.setAttribute('aria-label', tr('home.trail.reviewItem', { title }));
    const text = document.createElement('span');
    text.className = 'today-now-title-text';
    text.textContent = title;
    button.appendChild(text);
    button.addEventListener('click', event => openTodayTaskDetail(workspace.id, entry.id, event.currentTarget));
    body.appendChild(button);
    if (entry.at != null) {
      const when = document.createElement('p');
      when.className = 'today-now-when';
      when.textContent = todayWhenLabel(entry).text;
      body.appendChild(when);
    }
  } else {
    const empty = document.createElement('p');
    empty.className = 'today-now-empty';
    empty.textContent = tr('today.nothingLeft');
    body.appendChild(empty);
  }
  section.appendChild(body);

  if (entry) {
    const title = todayTaskTitle(entry);
    const actions = document.createElement('div');
    actions.className = 'today-now-actions';
    const check = document.createElement('button');
    check.type = 'button';
    check.className = 'today-now-check';
    check.dataset.todayFocus = `now-check:${entry.id}`;
    check.setAttribute('aria-pressed', 'false');
    check.setAttribute('aria-label', tr('today.markDone', { title }));
    const rays = Array.from({ length: 8 }, () => '<span class="today-ray"><span class="today-ray-dot"></span></span>').join('');
    check.innerHTML = `<svg width="28" height="28" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M5 12.5l4.5 4.5L19 7.5" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/></svg><span class="today-burst" aria-hidden="true">${rays}</span>`;
    check.addEventListener('click', event => { void checkTodayNow(event.currentTarget); });
    actions.appendChild(check);
    // Later is offered only when another open task exists to take its place.
    if (model.open.length > 1) {
      const later = document.createElement('button');
      later.type = 'button';
      later.className = 'today-now-later';
      later.dataset.todayFocus = `now-later:${entry.id}`;
      later.setAttribute('aria-label', tr('today.laterLabel', { title }));
      later.innerHTML = `<span>${esc(tr('today.later'))}</span>${TODAY_ARROW_ICON}`;
      later.addEventListener('click', event => { void laterTodayNow(event.currentTarget); });
      actions.appendChild(later);
    }
    section.appendChild(actions);
  }
  return section;
}

function buildTodayCard(workspace, entry) {
  const card = document.createElement('li');
  card.className = `today-card${entry.done ? ' is-done' : ''}${todayJustAddedId === entry.id ? ' is-new' : ''}`;
  card.dataset.todayId = entry.id;
  const title = todayTaskTitle(entry);
  const when = todayWhenLabel(entry);
  const check = document.createElement('button');
  check.type = 'button';
  check.className = 'today-card-check';
  check.dataset.todayFocus = `card-check:${entry.id}`;
  check.setAttribute('aria-pressed', String(entry.done));
  check.setAttribute('aria-label', tr(entry.done ? 'today.markNotDone' : 'today.markDone', { title }));
  check.innerHTML = '<svg width="14" height="14" viewBox="0 0 16 16" fill="none" aria-hidden="true"><path d="M3.5 8.5l3 3 6-7" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/></svg>';
  check.addEventListener('click', event => { void toggleTodayCard(event.currentTarget); });
  const text = document.createElement('div');
  text.className = 'today-card-text';
  const whenLabel = document.createElement('span');
  whenLabel.className = `today-card-when is-${when.tone}`;
  whenLabel.textContent = when.text;
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'today-card-title';
  button.dataset.itemId = entry.id;
  button.dataset.todayFocus = `card-title:${entry.id}`;
  button.tabIndex = 0;
  button.setAttribute('aria-label', tr('home.trail.reviewItem', { title }));
  const titleText = document.createElement('span');
  titleText.className = 'today-card-title-text';
  titleText.textContent = title;
  button.appendChild(titleText);
  button.addEventListener('click', event => openTodayTaskDetail(workspace.id, entry.id, event.currentTarget));
  text.append(whenLabel, button);
  card.append(check, text);
  return card;
}

function buildTodayRest(workspace, model) {
  const section = document.createElement('section');
  section.className = 'today-rest';
  section.setAttribute('aria-labelledby', 'today-rest-title');
  const head = document.createElement('div');
  head.className = 'today-rest-head';
  head.innerHTML = `<h2 id="today-rest-title">${esc(tr('today.rest'))}</h2>`;
  const week = document.createElement('button');
  week.type = 'button';
  week.className = 'today-week';
  week.dataset.todayFocus = 'week';
  week.innerHTML = `<span>${esc(tr('today.thisWeek'))}</span>${TODAY_ARROW_ICON}`;
  week.addEventListener('click', () => openTodayWeek());
  head.appendChild(week);
  section.appendChild(head);
  const list = document.createElement('ul');
  list.className = 'today-rest-list';
  model.rest.forEach(entry => list.appendChild(buildTodayCard(workspace, entry)));
  section.appendChild(list);
  return section;
}

function openTodayTaskDetail(workspaceId, itemId, opener) {
  return openHomePreviewItem(workspaceId, itemId, `today:${itemId}`, opener);
}

function openTodayWeek() {
  const workspace = activeWs();
  if (!workspace) return false;
  Router.navigate({ type: 'calendar', wsId: workspace.id, query: { cal: 'week' } });
  return true;
}

function focusTodayTarget(selectors) {
  for (const selector of selectors) {
    const target = document.querySelector(selector);
    if (!target || typeof target.focus !== 'function') continue;
    try { target.focus({ preventScroll: true }); } catch { try { target.focus(); } catch {} }
    if (document.activeElement === target) return true;
  }
  return false;
}

function setTodayBoardBusy(busy) {
  const board = document.querySelector('#board .today');
  if (!board) return;
  board.classList.toggle('is-busy', !!busy);
  if (busy) board.setAttribute('aria-busy', 'true');
  else board.removeAttribute('aria-busy');
}

// Completion reuses the Board to-do transaction: the same exact-identity
// context, one localized snapshot (so Undo works), one acknowledged write, and
// the shared pending token that other writers already respect.
async function commitTodayTodoToggle(itemId, opener = null, { workspaceId = null } = {}) {
  if (isBoardTodoCompletionPending()
      || todayCapturePending
      || (typeof isBoardLocalRecordCreatePending === 'function' && isBoardLocalRecordCreatePending())) return false;
  if (State.isRecoveryRequired?.()) return false;
  // The due card answers a to-do in whichever workspace holds it.
  const workspace = workspaceId != null
    ? (State.get()?.workspaces || []).find(candidate => String(candidate?.id) === String(workspaceId)) || null
    : activeWs();
  const row = workspace
    ? collectWorkspaceItems(workspace).find(candidate => candidate.item?.type === 'todo' && String(candidate.item.id || '') === String(itemId))
    : null;
  const context = row ? createBoardTodoCompletionContext(row.item) : null;
  const target = context ? resolveBoardTodoCompletionTarget(context) : null;
  if (!target) return false;

  const transaction = { context, itemId: context.itemId, opener, surface: 'today' };
  boardTodoCompletionMutationPending = transaction;
  setTodayBoardBusy(true);
  try {
    State.snapshot(tr(target.item.done ? 'detail.markIncomplete' : 'detail.markComplete'));
    target.item.done = !target.item.done;
  } catch (error) {
    if (boardTodoCompletionMutationPending === transaction) boardTodoCompletionMutationPending = null;
    setTodayBoardBusy(false);
    State.requireRecovery?.();
    if (typeof showStateRecoveryRequired === 'function') showStateRecoveryRequired(error);
    return false;
  }

  try {
    await State.persistNow();
  } catch (error) {
    if (boardTodoCompletionMutationPending === transaction) boardTodoCompletionMutationPending = null;
    setTodayBoardBusy(false);
    if (State.isRecoveryRequired?.() && typeof showStateRecoveryRequired === 'function') {
      showStateRecoveryRequired(error);
    }
    return false;
  }

  if (boardTodoCompletionMutationPending !== transaction) {
    setTodayBoardBusy(false);
    return false;
  }
  boardTodoCompletionMutationPending = null;
  setTodayBoardBusy(false);
  return true;
}

// Check: the box fills, the title is struck, and the write is acknowledged;
// then the task leaves and the next one slides in.
async function checkTodayNow(button) {
  const card = button?.closest('.today-now');
  const itemId = card?.dataset.todayId;
  if (!itemId || todayMotionPending) return false;
  todayMotionPending = true;
  const reduce = todayReducedMotion();
  card.classList.add('is-checking');
  card.querySelector('.today-progress-pill:not(.is-done)')?.classList.add('is-done', 'is-pulse');
  button.setAttribute('aria-pressed', 'true');
  const [accepted] = await Promise.all([commitTodayTodoToggle(itemId, button), todayWait(reduce ? 0 : 600)]);
  if (!accepted) {
    card.classList.remove('is-checking');
    card.querySelector('.today-progress-pill.is-pulse')?.classList.remove('is-done', 'is-pulse');
    button.setAttribute('aria-pressed', 'false');
    todayMotionPending = false;
    return false;
  }
  card.classList.add('is-leaving');
  await todayWait(reduce ? 0 : 240);
  todayMotionPending = false;
  todayNowEnters = !reduce;
  renderBoard();
  focusTodayTarget(['#board .today-now-check', '#today-capture-input']);
  return true;
}

async function laterTodayNow(button) {
  const card = button?.closest('.today-now');
  const itemId = card?.dataset.todayId;
  if (!itemId || todayMotionPending) return false;
  todayMotionPending = true;
  const reduce = todayReducedMotion();
  card.classList.add('is-leaving');
  await todayWait(reduce ? 0 : 240);
  deferTodayTask(itemId);
  todayMotionPending = false;
  todayNowEnters = !reduce;
  renderBoard();
  focusTodayTarget(['#board .today-now-later', '#board .today-now-check', '#today-capture-input']);
  return true;
}

async function toggleTodayCard(button) {
  const card = button?.closest('.today-card');
  const itemId = card?.dataset.todayId;
  if (!itemId || todayMotionPending) return false;
  todayMotionPending = true;
  const reduce = todayReducedMotion();
  const wasDone = card.classList.contains('is-done');
  card.classList.add(wasDone ? 'is-unchecking' : 'is-checking');
  const [accepted] = await Promise.all([commitTodayTodoToggle(itemId, button), todayWait(reduce ? 0 : 340)]);
  todayMotionPending = false;
  if (!accepted) {
    card.classList.remove('is-checking', 'is-unchecking');
    return false;
  }
  renderBoard();
  const escaped = CSS.escape(String(itemId));
  focusTodayTarget([
    `#board .today-card[data-today-id="${escaped}"] .today-card-check`,
    `#board .today-now[data-today-id="${escaped}"] .today-now-check`,
    '#today-capture-input',
  ]);
  return true;
}

// ── Capture bar ──
function todayCaptureSpaces() {
  return (activeWs()?.categories || []).map(space => ({ id: space.id, name: space.name }));
}

function buildTodayCapture() {
  const wrap = document.createElement('div');
  wrap.className = 'today-capture';
  wrap.innerHTML = `
    <label class="sr-only" for="today-capture-input">${esc(tr('today.capture.label'))}</label>
    <div class="today-capture-box">
      <span class="today-capture-plus" aria-hidden="true"><svg width="14" height="14" viewBox="0 0 16 16" fill="none"><path d="M8 3v10M3 8h10" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg></span>
      <div class="today-capture-field">
        <div class="today-capture-mirror" aria-hidden="true"></div>
        <input id="today-capture-input" class="today-capture-input" type="text" autocomplete="off" autocapitalize="off" spellcheck="false" writingsuggestions="false" enterkeyhint="done" aria-describedby="today-capture-status">
      </div>
      <kbd class="today-capture-enter" aria-hidden="true">${esc(tr('today.capture.enter'))}</kbd>
    </div>
    <p id="today-capture-status" class="today-capture-status" role="status" aria-live="polite"></p>`;
  const input = wrap.querySelector('.today-capture-input');
  input.placeholder = tr('today.capture.placeholder');
  input.value = todayCaptureDraft;
  bindTodayCapture(wrap);
  return wrap;
}

function setTodayCaptureStatus(wrap, message) {
  const status = wrap?.querySelector('.today-capture-status');
  if (!status) return;
  status.textContent = message || '';
  wrap.classList.toggle('has-status', !!message);
}

function setTodayCaptureBusy(wrap, busy) {
  const input = wrap?.querySelector('.today-capture-input');
  const box = wrap?.querySelector('.today-capture-box');
  if (input) input.readOnly = !!busy;
  if (box) {
    if (busy) box.setAttribute('aria-busy', 'true');
    else box.removeAttribute('aria-busy');
  }
  wrap?.classList.toggle('is-busy', !!busy);
}

// The input text is transparent; this mirror draws the same characters with
// the understood words marked. Only newly understood words animate in.
function paintTodayCaptureMirror(wrap) {
  const input = wrap?.querySelector('.today-capture-input');
  const mirror = wrap?.querySelector('.today-capture-mirror');
  if (!input || !mirror) return;
  const value = input.value;
  const parsed = parseTodayCapture(value, { spaces: todayCaptureSpaces() });
  const nextKeys = new Set();
  const seen = new Map();
  // One inline line inside the (flex-centred) mirror: a flex container would
  // drop the whitespace-only text between two marks and drift from the input.
  const line = document.createElement('span');
  line.className = 'today-capture-mirror-line';
  mirror.textContent = '';
  mirror.appendChild(line);
  let cursor = 0;
  parsed.tokens.forEach(token => {
    if (token.start > cursor) line.appendChild(document.createTextNode(value.slice(cursor, token.start)));
    const text = value.slice(token.start, token.end);
    const base = `${token.kind}:${text.toLowerCase()}`;
    const occurrence = (seen.get(base) || 0) + 1;
    seen.set(base, occurrence);
    const key = `${base}:${occurrence}`;
    const mark = document.createElement('mark');
    mark.className = `today-hl is-${token.kind}${todayCaptureTokenKeys.has(key) ? '' : ' is-new'}`;
    mark.textContent = text;
    line.appendChild(mark);
    nextKeys.add(key);
    cursor = token.end;
  });
  if (cursor < value.length) line.appendChild(document.createTextNode(value.slice(cursor)));
  todayCaptureTokenKeys = nextKeys;
  wrap.querySelector('.today-capture-box')?.classList.toggle('has-text', !!value.trim());
  mirror.scrollLeft = input.scrollLeft;
}

function bindTodayCapture(wrap) {
  const input = wrap.querySelector('.today-capture-input');
  const mirror = wrap.querySelector('.today-capture-mirror');
  if (!input || !mirror) return;
  const sync = () => { mirror.scrollLeft = input.scrollLeft; };
  input.addEventListener('input', () => {
    todayCaptureDraft = input.value;
    setTodayCaptureStatus(wrap, '');
    paintTodayCaptureMirror(wrap);
  });
  ['scroll', 'keyup', 'click', 'select', 'focus'].forEach(type => {
    input.addEventListener(type, () => requestAnimationFrame(sync));
  });
  input.addEventListener('compositionstart', () => { todayCaptureComposing = true; });
  input.addEventListener('compositionend', () => {
    todayCaptureComposing = false;
    if (todayRenderDeferred) {
      todayRenderDeferred = false;
      requestAnimationFrame(() => { if (activeHome) renderBoard(); });
    }
  });
  input.addEventListener('keydown', event => {
    if (event.isComposing || event.keyCode === 229) return;
    if (event.key === 'Enter') {
      event.preventDefault();
      void submitTodayCapture(input);
      return;
    }
    if (event.key === 'Escape' && input.value) {
      event.preventDefault();
      event.stopPropagation();
      input.value = '';
      todayCaptureDraft = '';
      setTodayCaptureStatus(wrap, '');
      paintTodayCaptureMirror(wrap);
      return;
    }
    requestAnimationFrame(sync);
  });
  paintTodayCaptureMirror(wrap);
}

async function submitTodayCapture(input) {
  const wrap = input?.closest('.today-capture');
  if (!wrap || todayCapturePending) return false;
  const workspace = activeWs();
  if (!workspace) return false;
  if (!Array.isArray(workspace.categories) || !workspace.categories.length) {
    setTodayCaptureStatus(wrap, tr('cal.needSpace'));
    return false;
  }
  const parsed = parseTodayCapture(input.value, { spaces: todayCaptureSpaces() });
  if (!parsed.title) {
    if (input.value.trim()) {
      setTodayCaptureStatus(wrap, tr('today.capture.needTitle'));
      wrap.classList.remove('is-shake');
      void wrap.offsetWidth;
      wrap.classList.add('is-shake');
    }
    return false;
  }
  return commitTodayCapture(parsed, wrap);
}

// The capture destination is the exact Space (the #space named in the line,
// else the active Space) and its single Inbox, which is created only when
// absent. Two Inboxes, a vanished Space, or a changed graph add nothing.
function createTodayCaptureContext(spaceId) {
  const state = State.get();
  const workspaceId = String(state.activeWsId || '');
  const workspace = organizationWorkspaceTarget(workspaceId);
  if (!workspace) return null;
  const location = identitySpaceTarget(workspaceId, String(spaceId || ''));
  if (!location || location.workspace !== workspace || !Array.isArray(location.space.groups)) return null;
  const inboxes = location.space.groups.filter(group => group?.name === 'Inbox');
  if (inboxes.length > 1) return null;
  const inbox = inboxes[0] || null;
  if (inbox && (!inbox.id || !Array.isArray(inbox.items))) return null;
  if (inbox) {
    const exactInbox = organizationGroupTarget(String(inbox.id));
    if (!exactInbox
        || exactInbox.workspace !== workspace
        || exactInbox.space !== location.space
        || exactInbox.group !== inbox) return null;
  }
  return {
    workspaceId,
    workspaceRef: workspace,
    spaceId: String(location.space.id || ''),
    spaceRef: location.space,
    spaceName: String(location.space.name || ''),
    inboxId: inbox ? String(inbox.id) : null,
    inboxRef: inbox,
  };
}

function resolveTodayCaptureTarget(context) {
  if (!context || !context.workspaceId || !context.spaceId) return null;
  const state = State.get();
  if (String(state.activeWsId || '') !== context.workspaceId) return null;
  const workspace = organizationWorkspaceTarget(context.workspaceId);
  if (!workspace || workspace !== context.workspaceRef) return null;
  const location = identitySpaceTarget(context.workspaceId, context.spaceId);
  if (!location
      || location.workspace !== workspace
      || location.space !== context.spaceRef
      || !Array.isArray(location.space.groups)) return null;
  const inboxes = location.space.groups.filter(group => group?.name === 'Inbox');
  if (context.inboxRef) {
    if (inboxes.length !== 1
        || inboxes[0] !== context.inboxRef
        || String(inboxes[0].id || '') !== context.inboxId
        || !Array.isArray(inboxes[0].items)) return null;
    const exactInbox = organizationGroupTarget(context.inboxId);
    if (!exactInbox
        || exactInbox.workspace !== workspace
        || exactInbox.space !== location.space
        || exactInbox.group !== context.inboxRef) return null;
    return { workspace, space: location.space, inbox: context.inboxRef };
  }
  if (context.inboxId != null || inboxes.length) return null;
  return { workspace, space: location.space, inbox: null };
}

function todayCaptureReceiptText(parsed, context, now = Date.now()) {
  const { end } = todayDayBounds(now);
  let message;
  if (parsed.at == null || parsed.at < end) {
    message = tr('today.capture.added');
  } else {
    const day = parsed.at < todayDayBounds(end).end ? tr('today.capture.tomorrow') : todayShortDay(parsed.at);
    message = tr('today.capture.planned', { when: `${day} ${todayClockText(parsed.at)}` });
  }
  return parsed.spaceId && context?.spaceName
    ? tr('today.capture.inSpace', { message, space: context.spaceName })
    : message;
}

async function commitTodayCapture(parsed, wrap = null) {
  if (todayCapturePending
      || isBoardTodoCompletionPending()
      || (typeof isCalendarTaskMutationPending === 'function' && isCalendarTaskMutationPending())) return false;
  if (State.isRecoveryRequired?.()) {
    const error = new Error(tr('stateRecovery.detail'));
    error.code = 'LOCUS_STATE_RECOVERY_REQUIRED';
    if (typeof showStateRecoveryRequired === 'function') showStateRecoveryRequired(error);
    return false;
  }
  const workspace = activeWs();
  const context = createTodayCaptureContext(parsed.spaceId || String(workspace?.activeCatId || ''));
  const target = context ? resolveTodayCaptureTarget(context) : null;
  if (!target) {
    setTodayCaptureStatus(wrap, tr('today.capture.unavailable'));
    return false;
  }

  let inbox = target.inbox;
  let todo;
  try {
    const allocateId = createOrganizationIdAllocator();
    if (!inbox) {
      inbox = {
        id: allocateId(),
        name: 'Inbox',
        symbol: '📥',
        color: '#6366f1',
        collapsed: false,
        items: [],
      };
    }
    todo = stampNew({ id: allocateId(), type: 'todo', text: parsed.title, done: false });
    if (parsed.at != null) todo.reminder = { at: parsed.at, notified: false };
  } catch {
    setTodayCaptureStatus(wrap, tr('today.capture.unavailable'));
    return false;
  }

  const transaction = { context, itemId: todo.id, inboxWasCreated: !target.inbox };
  todayCapturePending = transaction;
  setTodayCaptureBusy(wrap, true);
  let actionId;
  try {
    actionId = State.snapshot(tr('today.history.add'));
    if (transaction.inboxWasCreated) target.space.groups.unshift(inbox);
    inbox.items.push(todo);
  } catch (error) {
    if (todayCapturePending === transaction) todayCapturePending = null;
    setTodayCaptureBusy(wrap, false);
    State.requireRecovery?.();
    if (typeof showStateRecoveryRequired === 'function') showStateRecoveryRequired(error);
    return false;
  }

  let receipt;
  try {
    receipt = await State.persistNow(parsed.at != null ? { reconcileReminders: true } : {});
  } catch (error) {
    if (todayCapturePending === transaction) todayCapturePending = null;
    setTodayCaptureBusy(wrap, false);
    State.requireRecovery?.();
    if (State.isRecoveryRequired?.() && typeof showStateRecoveryRequired === 'function') {
      showStateRecoveryRequired(error);
    }
    return false;
  }

  if (todayCapturePending !== transaction) return false;
  todayCapturePending = null;
  todayCaptureDraft = '';
  todayCaptureTokenKeys = new Set();
  todayJustAddedId = todo.id;
  setTodayCaptureBusy(wrap, false);
  renderBoard();
  renderSpaceNav();
  if (parsed.at == null || receipt?.reminderReconciliation?.ok === true) {
    toast(todayCaptureReceiptText(parsed, context), { undo: actionId });
  } else {
    toast(tr('cal.addScheduleWarning'), { tone: 'warning', duration: 8000, undo: actionId });
  }
  return true;
}

// ── Open-tabs edge tab ──
// The edge tab opens the existing Opened Tabs rail as a temporary drawer. The
// open state lives on <body> so the shared rail helpers can read it without a
// second copy of rail state, and the saved rail preference is never touched.
function isTodayTabsDrawerOpen() {
  return !!document.body && document.body.classList.contains('today-tabs-open');
}

function todayTabsDrawerAvailable() {
  return !!activeHome && document.body?.dataset.surface === 'home' && isOpenTabsRailAvailable();
}

function syncTodayTabsEar(value = null) {
  const ear = document.getElementById('today-tabs-ear');
  const badge = document.getElementById('today-tabs-badge');
  if (!ear || !badge) return false;
  const raw = value == null ? (openTabsLoadState === 'ready' ? allOpenTabs.length : null) : value;
  const count = Number.isInteger(raw) && raw > 0 ? raw : 0;
  const text = count > 99 ? '99+' : String(count);
  if (count) {
    if (badge.hidden || badge.textContent !== text) {
      badge.textContent = text;
      badge.hidden = false;
      badge.classList.remove('is-pop');
      void badge.offsetWidth;
      badge.classList.add('is-pop');
    }
  } else {
    badge.hidden = true;
    badge.textContent = '';
  }
  const label = count ? tr('today.tabs.open', { count }) : tr('today.tabs.openNone');
  ear.setAttribute('aria-label', label);
  ear.title = label;
  ear.setAttribute('aria-expanded', String(isTodayTabsDrawerOpen()));
  return true;
}

// The drawer's visibility flips on the next frame (a zero-length visibility
// transition), so focus retries there and once more after a short timeout,
// which also covers a background tab whose frames are paused.
let todayTabsFocusRequest = 0;
function focusTodayTabsDrawerTarget(id) {
  const request = ++todayTabsFocusRequest;
  const attempt = () => {
    const target = document.getElementById(id);
    if (request !== todayTabsFocusRequest || !target || !isTodayTabsDrawerOpen()) return true;
    // Never pull focus back once the person has moved within the drawer.
    const rail = document.getElementById('tabrail');
    if (rail?.contains(document.activeElement) && document.activeElement !== target) return true;
    try { target.focus({ preventScroll: true }); } catch {}
    return document.activeElement === target;
  };
  if (attempt()) return;
  requestAnimationFrame(attempt);
  setTimeout(attempt, 60);
}

function setTodayTabsDrawer(open, { opener = null, restoreFocus = true } = {}) {
  const rail = document.getElementById('tabrail');
  const ear = document.getElementById('today-tabs-ear');
  const scrim = document.getElementById('today-tabs-scrim');
  if (!rail || !ear || !document.body) return false;
  const next = !!open && todayTabsDrawerAvailable();
  if (next === isTodayTabsDrawerOpen()) return next;
  document.body.classList.toggle('today-tabs-open', next);
  if (scrim) scrim.hidden = !next;
  updateRailToggleLabel();
  syncTodayTabsEar();
  if (next) {
    rememberOpener(rail, opener && opener !== document.body ? opener : ear);
    focusTodayTabsDrawerTarget('tabrail-toggle');
  } else if (restoreFocus) {
    if (!restoreOpener(rail)) {
      try { ear.focus({ preventScroll: true }); } catch {}
    }
  } else {
    _overlayOpeners.delete(rail);
  }
  return next;
}

function bindTodayBoard() {
  const ear = document.getElementById('today-tabs-ear');
  const scrim = document.getElementById('today-tabs-scrim');
  const rail = document.getElementById('tabrail');
  ear?.addEventListener('click', event => {
    setTodayTabsDrawer(!isTodayTabsDrawerOpen(), { opener: event.currentTarget });
  });
  scrim?.addEventListener('click', () => setTodayTabsDrawer(false));
  rail?.addEventListener('keydown', event => {
    if (isTodayTabsDrawerOpen()) trapTabKey(event, rail);
  });
  window.addEventListener('resize', rafThrottle(() => {
    if (isTodayTabsDrawerOpen() && !todayTabsDrawerAvailable()) setTodayTabsDrawer(false, { restoreFocus: false });
  }));
  document.addEventListener('visibilitychange', () => {
    if (document.hidden) return;
    const board = document.querySelector('#board .today');
    if (board) paintTodayClock(board.querySelector('.today-clock-block'), { animate: false });
  });
}

function buildTodayBoard(workspace, now = Date.now()) {
  const somedayIds = typeof planSomedayIds === 'function' ? planSomedayIds() : null;
  const model = todayTaskModel(workspace, now, readTodayLaterIds(now), somedayIds);
  const root = document.createElement('div');
  root.className = 'today';
  root.dataset.todayDay = todayDayKey(now);
  const top = document.createElement('div');
  top.className = 'today-top';
  top.append(buildTodayClock(now), buildTodayNow(workspace, model));
  root.appendChild(top);
  if (model.rest.length) root.appendChild(buildTodayRest(workspace, model));
  root.appendChild(buildTodayCapture());
  return root;
}

// Home surface renderer. Returns false (and drops the flag) if the workspace
// vanished, so renderBoard() falls through to the category board.
function renderHome() {
  const ws = activeWs();
  if (!ws) { activeHome = false; return false; }
  hideBreadcrumb();
  const $b = document.getElementById('board');
  $b.classList.remove('group-page-mode', 'list-mode', 'canvas-mode', 'explorer-mode', 'timeline-mode', 'gallery-mode', 'graph-mode', 'calendar-mode');
  $b.classList.add('home-mode');
  // An IME composition in the capture bar must not be torn down by a repaint
  // (tab events and storage sync both repaint Home). Finish it first.
  if (todayCaptureComposing && $b.querySelector('.today')) {
    todayRenderDeferred = true;
    return true;
  }
  const capture = document.getElementById('today-capture-input');
  const captureFocused = !!capture && document.activeElement === capture;
  const selection = captureFocused ? [capture.selectionStart, capture.selectionEnd] : null;
  // Any other Today control carries a stable data-today-focus key, so focus on
  // it survives a repaint (storage sync, a toggle elsewhere) instead of falling
  // to <body>.
  const todayFocusKey = captureFocused
    ? null
    : (document.activeElement?.closest?.('#board [data-today-focus]')?.dataset?.todayFocus || null);
  $b.innerHTML = '';

  // Home is the Today board (2026-11 canvas): clock, one Now card, the rest of
  // today, and the capture bar. Saved-page recovery lives in Search and All
  // links, Inbox review in the rail, and open tabs behind the edge tab, so the
  // former Trail, Inbox zone, and Space register are no longer rendered here.
  $b.appendChild(buildTodayBoard(ws));
  todayJustAddedId = null;
  if (captureFocused) {
    const rebuilt = document.getElementById('today-capture-input');
    if (rebuilt) {
      try { rebuilt.focus({ preventScroll: true }); } catch { try { rebuilt.focus(); } catch {} }
      try { if (selection) rebuilt.setSelectionRange(selection[0], selection[1]); } catch {}
    }
  } else if (todayFocusKey) {
    const rebuilt = [...$b.querySelectorAll('[data-today-focus]')]
      .find(element => element.dataset.todayFocus === todayFocusKey);
    if (rebuilt) {
      try { rebuilt.focus({ preventScroll: true }); } catch { try { rebuilt.focus(); } catch {} }
    }
  }
  syncTodayTabsEar();
  startTodayClock();
  return true;
}

// SPACES list in the left nav — one entry per category, plus the smart-view
// counts. Called from renderCategoryTabs() and renderBoard() so counts and the
// active highlight stay fresh across every mutation.
function renderSpaceNav() {
  const ws = activeWs();
  const $nav = document.getElementById('space-nav');
  if ($nav && ws) {
    $nav.innerHTML = '';
    ws.categories.forEach((cat, categoryIndex) => {
      const count = cat.groups.reduce((n, g) => n + g.items.length, 0);
      const el = document.createElement('button');
      const inbox = cat.groups.find(g => g.name === 'Inbox');
      const showingInbox = !!activeGroupPage && activeGroupPage.groupId === inbox?.id;
      el.className = 'space-item' + (!activeSearch && !activeHome && !activeLibraryMode && !activeCalendar && !showingInbox && cat.id === ws.activeCatId ? ' active' : '');
      el.dataset.catId = cat.id;
      const duplicateName = ws.categories.some((candidate, candidateIndex) => (
        candidateIndex !== categoryIndex && candidate.name === cat.name
      ));
      const position = duplicateName
        ? tr('organization.space.position', {
          position: categoryIndex + 1,
          count: ws.categories.length,
        })
        : '';
      el.setAttribute('aria-label', duplicateName
        ? tr('organization.space.duplicateLabel', { name: cat.name, position })
        : cat.name);
      el.innerHTML =
        `<span class="space-sym">${esc(cat.symbol || '🗂')}</span>` +
        `<span class="space-name">${esc(cat.name)}</span>` +
        `<span class="nav-count">${count}</span>`;
      el.onclick = () => openCategory(cat.id);
      enableKeyboardClick(el);
      bindAnchoredContextMenu(el, () => [
          { text: 'Open', icon: cmIcons.open, action: () => openCategory(cat.id) },
          { text: tr('organization.renameMenu'), icon: cmIcons.edit, action: () => openOrganizationName('space', cat.id, el) },
          categoryReminderMenuItem(cat, el),
          ws.categories.length > 1 ? { text: tr('organization.space.delete'), icon: cmIcons.delete, danger: true, action: () => openOrganizationDelete('space', cat.id, el) } : null
        ].filter(Boolean));
      // Drop a dragged tab onto a space to save it into that category's Inbox.
      el.ondragover = e => { if (drag?.kind === 'tab' || drag?.kind === 'tabs-multi') { e.preventDefault(); el.classList.add('drop-target'); } };
      el.ondragleave = () => el.classList.remove('drop-target');
      el.ondrop = async e => { if (drag?.kind === 'tab' || drag?.kind === 'tabs-multi') { e.preventDefault(); el.classList.remove('drop-target'); await dropTabsIntoCategory(cat); } };
      $nav.appendChild(el);
    });
  }
  updateNavChrome();
}

// Refresh the smart-view counts and active states in the left nav.
function updateNavChrome() {
  const ws = activeWs();
  const s = State.get();
  const linkCount = ws ? collectWorkspaceTabs(ws).length : 0;
  const inboxTarget = resolveLandingInboxTarget(createLandingInboxContext(ws));
  const inbox = inboxTarget?.group || null;
  const setCount = (id, val) => { const el = document.getElementById(id); if (el) el.textContent = val > 0 ? String(val) : ''; };
  setCount('nav-all-count', linkCount);
  const favoriteCount = ws ? collectWorkspaceTabs(ws).filter(row => row.item.favorite).length : 0;
  setCount('nav-favorites-count', favoriteCount);
  const readLaterCount = ws ? collectWorkspaceTabs(ws).filter(row => row.item.readLaterAt && !row.item.readAt).length : 0;
  setCount('nav-read-later-count', readLaterCount);
  setCount('nav-inbox-count', Array.isArray(inbox?.items) ? inbox.items.length : 0);
  setCount('nav-archive-count', (s.archive || []).length);
  setCount('nav-trash-count', (s.trash || []).length);
  const home = document.getElementById('nav-home');
  if (home) home.classList.toggle('active', !!activeHome);
  const search = document.getElementById('nav-search');
  if (search) search.classList.toggle('active', !!activeSearch);
  const all = document.getElementById('nav-all');
  if (all) all.classList.toggle('active', activeLibraryMode === 'all');
  const favorites = document.getElementById('nav-favorites');
  if (favorites) favorites.classList.toggle('active', activeLibraryMode === 'favorites');
  const readLater = document.getElementById('nav-read-later');
  if (readLater) readLater.classList.toggle('active', activeLibraryMode === 'read-later');
  const archive = document.getElementById('nav-archive');
  if (archive) archive.classList.toggle('active', activeLibraryMode === 'archive');
  const trash = document.getElementById('nav-trash');
  if (trash) trash.classList.toggle('active', activeLibraryMode === 'trash');
  const inboxNav = document.getElementById('nav-inbox');
  if (inboxNav) {
    const catName = activeCat()?.name || '';
    const scopedLabel = catName ? `${tr('nav.inbox')} · ${catName}` : tr('nav.inbox');
    inboxNav.classList.toggle('active', !!activeGroupPage && activeGroupPage.groupId === (inbox && inbox.id));
    inboxNav.setAttribute('aria-label', scopedLabel);
    inboxNav.title = scopedLabel;
    const label = inboxNav.querySelector('.nav-lbl');
    if (label) label.textContent = scopedLabel;
  }
  // Plan owns the calendar surface (Upcoming, Sort inbox, and the Calendar).
  const planNav = document.getElementById('nav-plan');
  if (planNav) {
    planNav.classList.toggle('active', !!activeCalendar);
    if (activeCalendar) planNav.setAttribute('aria-current', 'page'); else planNav.removeAttribute('aria-current');
    let todayCount = 0;
    try { todayCount = typeof planTodayCount === 'function' ? planTodayCount(ws) : 0; } catch {}
    const planCount = document.getElementById('nav-plan-count');
    if (planCount) planCount.textContent = todayCount > 0 ? tr('plan.navToday', { count: todayCount }) : '';
    planNav.setAttribute('aria-label', todayCount > 0 ? `${tr('nav.plan')}, ${tr('plan.navToday', { count: todayCount })}` : tr('nav.plan'));
  }
  // A reminder card whose to-do was finished or moved elsewhere closes on the
  // next render rather than waiting for the next poll.
  if (typeof checkPlanDue === 'function' && typeof planDueShown !== 'undefined' && planDueShown) checkPlanDue();
  const moreNav = document.getElementById('nav-more');
  if (moreNav) moreNav.classList.toggle('active', !!activeSearch || (!!activeCalendar && !planNav) || ['favorites', 'read-later', 'archive', 'trash'].includes(activeLibraryMode));
  let pending = 0;
  try { pending = collectPendingReminders({ scope: ws ? ws.id : undefined }).length; } catch {}
  _pendingReminderCount = pending;
  syncTopbarMoreState();
}
// Cached so the visible overflow can signal pending reminders and label the
// Calendar route without recomputing during menu focus movement.
let _pendingReminderCount = 0;

// The bento-board layout itself (formerly the body of renderBoard).
function renderBoardView() {
  const $b = spaceViewHost();
  $b.classList.remove('list-mode', 'canvas-mode');
  $b.innerHTML = '';
  const cat = activeCat(); if (!cat) return;

  if (!cat.groups.length) {
    $b.appendChild(buildEmptySpaceState(cat));
    return;
  }

  // The board's columns wrap into a grid; New group lives in the view bar.
  const grid = document.createElement('div');
  grid.className = 'spc-board';
  cat.groups.forEach(g => grid.appendChild(buildSpaceColumn(g)));
  $b.appendChild(grid);
  applySearchFilter();
}

function nextKeyboardGroupColumnSize(currentSize, key, mode, shiftKey = false, viewportHeight = window.innerHeight) {
  const step = shiftKey ? 48 : 16;
  const currentWidth = Number.isFinite(Number(currentSize?.w)) ? Math.round(Number(currentSize.w)) : 200;
  const currentHeight = Number.isFinite(Number(currentSize?.h)) ? Math.round(Number(currentSize.h)) : 120;
  const maxHeight = Math.max(120, Math.round(Number(viewportHeight) || 0) - 200);

  if ((mode === 'width' || mode === 'corner') && key === 'ArrowLeft') {
    return { w: Math.max(200, Math.min(900, currentWidth - step)), h: currentHeight };
  }
  if ((mode === 'width' || mode === 'corner') && key === 'ArrowRight') {
    return { w: Math.max(200, Math.min(900, currentWidth + step)), h: currentHeight };
  }
  if (mode === 'corner' && key === 'ArrowUp') {
    return { w: currentWidth, h: Math.max(120, Math.min(maxHeight, currentHeight - step)) };
  }
  if (mode === 'corner' && key === 'ArrowDown') {
    return { w: currentWidth, h: Math.max(120, Math.min(maxHeight, currentHeight + step)) };
  }
  return null;
}

function nextPointerGroupColumnSize(startSize, startPoint, pointerPoint, mode, viewportHeight = window.innerHeight) {
  const maxHeight = Math.max(120, Math.round(Number(viewportHeight) || 0) - 200);
  const width = Math.max(200, Math.min(900, Math.round(startSize.w + (pointerPoint.x - startPoint.x))));
  const height = mode === 'corner'
    ? Math.max(120, Math.min(maxHeight, Math.round(startSize.h + (pointerPoint.y - startPoint.y))))
    : startSize.h;
  return { w: width, h: height };
}

function persistGroupColumnSize(groupId, size) {
  const state = State.get();
  if (!state.columnSizes || typeof state.columnSizes !== 'object' || Array.isArray(state.columnSizes)) {
    state.columnSizes = {};
  }
  state.columnSizes[groupId] = { w: size.w, h: size.h };
  State.persist();
}

function groupRecordCreationMenuItems(group, opener) {
  const identity = identityGroupTarget(group?.id);
  if (!identity || identity.group !== group) return [];
  const identityParams = {
    workspaceId: identity.workspace.id,
    spaceId: identity.space.id,
    groupId: identity.group.id,
  };
  return [
    { text: tr('groupAction.addNote'), icon: cmIcons.note, action: () => void createBoardLocalRecord(identity.group, 'note', opener) },
    { text: tr('groupAction.addTodo'), icon: cmIcons.todo, action: () => void createBoardLocalRecord(identity.group, 'todo', opener) },
    { text: tr('groupAction.addStack'), icon: cmIcons.stack, action: () => openIdentityEditor('stack', 'create', identityParams, opener) },
  ];
}

function openGroupRecordCreationMenu(group, opener) {
  const items = groupRecordCreationMenuItems(group, opener);
  if (!items.length) {
    toast(tr('detail.changed'), { danger: true, duration: 6000 });
    focusDialogOpener(opener);
    return false;
  }
  focusDialogOpener(opener);
  return showAnchoredContextMenu(opener, items, {
    ariaLabel: tr('groupAction.addRecordFor', { name: group.name }),
    expandedOwner: opener,
  });
}

function groupActionMenuItems(group, opener, options = {}) {
  const identity = identityGroupTarget(group?.id);
  if (!identity || identity.group !== group) return [];
  const identityParams = {
    workspaceId: identity.workspace.id,
    spaceId: identity.space.id,
    groupId: identity.group.id,
  };
  const toggleCollapse = typeof options.toggleCollapse === 'function'
    ? options.toggleCollapse
    : null;
  const recordCreationItems = options.includeRecordCreation === false
    ? []
    : groupRecordCreationMenuItems(identity.group, opener);
  const canOpenAll = groupHasReopenableSavedTab(identity.group);
  return [
    { text: tr('groupAction.edit'), icon: cmIcons.edit, action: () => openIdentityEditor('group', 'edit', identityParams, opener) },
    { text: tr('groupAction.editIntention'), icon: cmIcons.edit, action: () => openIntentEditor('group', identity.group.id) },
    { text: tr('groupAction.setReminder'), icon: cmIcons.clock, action: () => openEntityReminderPickerOrReport('group', identity.group.id) },
    ...(toggleCollapse ? [{ text: tr(group.collapsed ? 'groupAction.expand' : 'groupAction.collapse'), icon: cmIcons.edit, action: toggleCollapse }] : []),
    { sep: true },
    ...(canOpenAll ? [{ text: tr('groupAction.openAll'), icon: cmIcons.open, action: () => openGroupAll(group, opener) }] : []),
    { text: tr('groupAction.openAsPage'), icon: cmIcons.expand || cmIcons.open, action: () => openGroupPage(identity.group.id) },
    { text: tr('groupAction.duplicate'), icon: cmIcons.copy, action: () => openIdentityEditor('group', 'duplicate', identityParams, opener) },
    ...(recordCreationItems.length ? [{ sep: true }, ...recordCreationItems] : []),
    { sep: true },
    ...organizationGroupMoveMenuItems(identity.group.id, opener),
    { sep: true },
    { text: tr('groupAction.archive'), icon: cmIcons.archive, action: () => archiveGroup(identity.group.id) },
  ];
}

function buildGroupCol(g, options = {}) {
  const forceExpanded = options.forceExpanded === true;
  const renderedCollapsed = !forceExpanded && !!g.collapsed;
  const col = document.createElement('div');
  col.className = 'gcol' + (renderedCollapsed ? ' collapsed' : '');
  col.dataset.gid = g.id;
  col.style.setProperty('--gcol-tint', g.color);

  // Todo counter
  const todos = g.items.filter(it => it.type === 'todo');
  const done = todos.filter(it => it.done).length;
  const todoStr = todos.length ? `<span class="todo-count${done === todos.length ? ' all-done' : ''}">${done}/${todos.length}</span>` : '';

  const itemCnt = g.items.length;
  const canOpenAll = groupHasReopenableSavedTab(g);
  col.innerHTML = `
    <div class="gcol-hd" role="group" aria-label="${esc(tr('groupAction.aria', { name: g.name }))}">
      <button class="gcol-sym-wrap" type="button" aria-label="${esc(tr('groupAction.editFor', { name: g.name }))}">
        <span>${esc(g.symbol || '📁')}</span>
      </button>
      <div class="gcol-info">
        <button class="gcol-name" type="button" data-act="focus" title="${esc(`${g.name} · ${tr('groupAction.openAsPage')}`)}" aria-label="${esc(`${g.name} · ${tr('groupAction.openAsPage')}`)}">${esc(g.name)}</button>
        <div class="gcol-meta">
          <button class="chev gcol-toggle${forceExpanded ? ' hidden' : ''}" type="button" aria-expanded="${!renderedCollapsed}" aria-label="${esc(tr(renderedCollapsed ? 'groupAction.expandFor' : 'groupAction.collapseFor', { name: g.name }))}"><svg width="8" height="8" viewBox="0 0 8 8" aria-hidden="true"><path d="M2 3l2 2 2-2" stroke="currentColor" stroke-width="1.3" fill="none" stroke-linecap="round"/></svg></button>
          <span>${esc(itemCnt === 1 ? tr('groupAction.oneItem') : tr('groupAction.items', { count: itemCnt }))}</span>
          ${todoStr}
        </div>
        ${renderIntentPills(g)}
      </div>
      <div class="gcol-acts">
        <button class="gcol-btn go" data-act="open-all"${canOpenAll ? '' : ' disabled aria-disabled="true"'} title="${esc(tr('groupAction.openAll'))}" aria-label="${esc(tr('groupAction.openAll'))}">
          <svg width="12" height="12" viewBox="0 0 12 12" fill="none"><path d="M4 2.5H2a1 1 0 00-1 1v6.5A1 1 0 002 11h6.5a1 1 0 001-1V8M7 1h4m0 0v4M11 1L5.5 6.5" stroke="currentColor" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round"/></svg>
        </button>
        <button class="gcol-btn" data-act="more" title="${esc(tr('groupAction.more'))}" aria-label="${esc(tr('groupAction.moreFor', { name: g.name }))}" aria-haspopup="menu">
          <svg width="12" height="12" viewBox="0 0 12 12" fill="none"><circle cx="2.5" cy="6" r="1" fill="currentColor"/><circle cx="6" cy="6" r="1" fill="currentColor"/><circle cx="9.5" cy="6" r="1" fill="currentColor"/></svg>
        </button>
      </div>
    </div>
    <div class="gcol-scroll-wrap">
      <div class="gcol-cards"></div>
    </div>
    <div class="gcol-ft">
      <button class="primary" type="button" data-act="add-tab" title="${esc(tr('groupAction.saveHereFor', { name: g.name }))}" aria-label="${esc(tr('groupAction.saveHereFor', { name: g.name }))}">
        <svg viewBox="0 0 12 12" fill="none" aria-hidden="true"><path d="M6 1.5v5.8M3.8 5.2 6 7.5l2.2-2.3M2 9.5h8" stroke="currentColor" stroke-width="1.25" stroke-linecap="round" stroke-linejoin="round"/></svg>
        <span>${esc(tr('groupAction.saveHere'))}</span>
      </button>
      <button class="gcol-add-record" type="button" data-act="add-record" title="${esc(tr('groupAction.addRecordFor', { name: g.name }))}" aria-label="${esc(tr('groupAction.addRecordFor', { name: g.name }))}" aria-haspopup="menu" aria-expanded="false">
        <svg viewBox="0 0 12 12" fill="none" aria-hidden="true"><path d="M2 3h4M2 6h4M2 9h4M9 4.5v4M7 6.5h4" stroke="currentColor" stroke-width="1.2" stroke-linecap="round"/></svg>
        <span>${esc(tr('groupAction.addRecord'))}</span>
      </button>
    </div>
    <button type="button" class="gcol-resize" data-resize-mode="width" title="${esc(tr('groupAction.resizeWidthHint', { name: g.name }))}" aria-label="${esc(tr('groupAction.resizeWidth', { name: g.name }))}"></button>
    <button type="button" class="gcol-resize-corner" data-resize-mode="corner" title="${esc(tr('groupAction.resizeBothHint', { name: g.name }))}" aria-label="${esc(tr('groupAction.resizeBoth', { name: g.name }))}"></button>
  `;

  // Header
  const hd = col.querySelector('.gcol-hd');
  const toggleButton = col.querySelector('.gcol-toggle');
  const toggleCollapse = () => {
    if (forceExpanded) return;
    State.snapshot('Toggle collapse');
    g.collapsed = !g.collapsed;
    col.classList.toggle('collapsed');
    toggleButton.setAttribute('aria-expanded', String(!g.collapsed));
    toggleButton.setAttribute('aria-label', tr(g.collapsed ? 'groupAction.expandFor' : 'groupAction.collapseFor', { name: g.name }));
    State.persist();
  };
  hd.addEventListener('click', e => {
    if (forceExpanded) return;
    if (e.target.closest('button')) return;
    toggleCollapse();
  });
  toggleButton.addEventListener('click', e => { e.stopPropagation(); toggleCollapse(); });
  // Group menu — one actual-opener path for More, pointer context, Context Menu,
  // and Shift+F10, matching saved-record interaction and focus return.
  const menuButton = col.querySelector('[data-act="more"]');
  const groupMenuItems = opener => groupActionMenuItems(g, opener, {
    toggleCollapse: forceExpanded ? null : toggleCollapse,
    includeRecordCreation: false,
  });
  bindBoardItemContextMenu(hd, groupMenuItems, { menuButton });

  // Symbol
  col.querySelector('.gcol-sym-wrap').addEventListener('click', (e) => {
    e.stopPropagation();
    const identity = identityGroupTarget(g.id);
    openIdentityEditor('group', 'edit', {
      workspaceId: identity?.workspace.id,
      spaceId: identity?.space.id,
      groupId: g.id,
      focusField: 'symbol',
    }, e.currentTarget);
  });

  // Primary routes remain visible without hover discovery.
  col.querySelector('.gcol-name').addEventListener('click', e => {
    e.stopPropagation();
    openGroupPage(g.id);
  });
  col.querySelector('[data-act="open-all"]').addEventListener('click', e => {
    e.stopPropagation();
    const btn = e.currentTarget;
    openGroupAll(g, btn);
  });

  // Keep capture primary; local record types stay behind one contextual menu.
  const saveHereButton = col.querySelector('[data-act="add-tab"]');
  saveHereButton.addEventListener('click', async event => {
    event.stopPropagation();
    await addSidebarOrActiveTabToGroup(g);
  });
  const addRecordButton = col.querySelector('[data-act="add-record"]');
  addRecordButton.addEventListener('click', event => {
    event.stopPropagation();
    openGroupRecordCreationMenu(g, event.currentTarget);
  });

  // Items
  const cardsEl = col.querySelector('.gcol-cards');
  const scrollWrap = col.querySelector('.gcol-scroll-wrap');
  if (!g.items.length) {
    const isInbox = g.name === 'Inbox';
    cardsEl.appendChild(buildSystemEmptyState({
      kind: isInbox ? 'inbox' : 'space',
      title: isInbox ? tr('empty.inboxTitle') : tr('empty.spaceTitle', { space: g.name }),
      body: isInbox ? tr('empty.inboxBody') : tr('empty.spaceBody'),
      actions: isInbox
        ? [
            { label: tr('empty.addSave'), icon: '+', run: () => openCommandPalette() },
            { label: tr('empty.importBookmarks'), icon: '⇩', run: () => importBookmarks() },
          ]
        : [
            { label: tr('groupAction.saveHere'), icon: '↗', run: () => addSidebarOrActiveTabToGroup(g) },
            { label: tr('groupAction.addRecord'), icon: '+', hasPopup: 'menu', run: opener => openGroupRecordCreationMenu(g, opener) },
          ],
      compact: true,
    }));
  } else {
    g.items.forEach(it => cardsEl.appendChild(buildItem(it, g.items, g)));
  }
  makeGroupDropZone(cardsEl, col, g, g.items);

  // Scroll fade indicators
  const updateFade = () => {
    if (!scrollWrap) return;
    const atTop = cardsEl.scrollTop > 4;
    const atBot = cardsEl.scrollHeight - cardsEl.scrollTop - cardsEl.clientHeight > 4;
    scrollWrap.classList.toggle('scroll-top', atTop);
    scrollWrap.classList.toggle('scroll-bot', atBot);
  };
  cardsEl.addEventListener('scroll', updateFade, { passive: true });
  requestAnimationFrame(updateFade);

  // Column reorder (drag group header)
  col.addEventListener('dragstart', e => {
    if (e.target.closest('input') || e.target.closest('button') || e.target.closest('.item') || e.target.closest('.gcol-resize') || e.target.closest('.gcol-acts')) return;
    drag = { kind:'group', srcId: g.id };
    col.classList.add('dragging');
    e.dataTransfer.effectAllowed = 'move';
  });
  col.addEventListener('dragend', () => { col.classList.remove('dragging'); document.querySelectorAll('.gcol').forEach(x => { x.classList.remove('drop-before'); x.classList.remove('drop-after'); }); drag = null; });
  col.addEventListener('dragover', e => {
    if (drag?.kind === 'group' && drag.srcId !== g.id) {
      e.preventDefault();
      const r = col.getBoundingClientRect();
      const after = e.clientX > r.left + r.width / 2;
      document.querySelectorAll('.gcol').forEach(x => { x.classList.remove('drop-before'); x.classList.remove('drop-after'); });
      col.classList.add(after ? 'drop-after' : 'drop-before');
    }
  });
  col.addEventListener('drop', e => {
    if (drag?.kind === 'group' && drag.srcId !== g.id) {
      e.preventDefault();
      const cat = activeCat();
      const r = col.getBoundingClientRect();
      const after = e.clientX > r.left + r.width / 2;
      State.snapshot('Reorder groups');
      const srcIdx = cat.groups.findIndex(x => x.id === drag.srcId);
      const [src] = cat.groups.splice(srcIdx, 1);
      let tgtIdx = cat.groups.findIndex(x => x.id === g.id);
      if (after) tgtIdx++;
      cat.groups.splice(tgtIdx, 0, src);
      State.persist(); renderBoard();
    }
  });
  col.draggable = true;

  // Apply saved size
  const savedSize = State.get().columnSizes?.[g.id] ?? State.get().columnWidths?.[g.id];
  if (savedSize) {
    if (typeof savedSize === 'number') col.style.width = savedSize + 'px';
    else {
      if (savedSize.w) col.style.width = savedSize.w + 'px';
      if (savedSize.h) {
        const cards = col.querySelector('.gcol-cards');
        if (cards) { cards.style.maxHeight = savedSize.h + 'px'; cards.style.height = savedSize.h + 'px'; }
      }
    }
  }

  // Resize handles (corner = both axes). All pointer listeners stay on the
  // captured handle so detached Board columns do not leave global listeners.
  const resizerH = col.querySelector('.gcol-resize');
  const resizerCorner = col.querySelector('.gcol-resize-corner');
  const cardsEl2 = col.querySelector('.gcol-cards');
  let resizing = null;

  function readVisibleGroupColumnSize() {
    const colRect = col.getBoundingClientRect();
    const cardsRect = cardsEl2?.getBoundingClientRect();
    return {
      w: Math.round(colRect.width || col.offsetWidth),
      h: cardsEl2 ? Math.round(cardsRect?.height || cardsEl2.offsetHeight) : null,
    };
  }

  function applyVisibleGroupColumnSize(size) {
    col.style.width = `${size.w}px`;
    if (cardsEl2 && Number.isFinite(size.h)) {
      cardsEl2.style.maxHeight = `${size.h}px`;
      cardsEl2.style.height = `${size.h}px`;
    }
  }

  function beginPointerResize(mode, handle, e) {
    if (e.button !== 0 || resizing) return;
    resizing = {
      mode,
      handle,
      pointerId: e.pointerId,
      startX: e.clientX,
      startY: e.clientY,
      startSize: readVisibleGroupColumnSize(),
      wasDraggable: col.draggable,
    };
    col.draggable = false;
    handle.focus({ preventScroll: true });
    handle.setPointerCapture(e.pointerId);
    handle.classList.add('dragging');
    document.body.classList.add('resizing');
    document.body.classList.toggle('resizing-width', mode === 'width');
    e.preventDefault();
    e.stopPropagation();
  }

  function movePointerResize(handle, e) {
    if (!resizing || resizing.handle !== handle) return;
    const nextSize = nextPointerGroupColumnSize(
      resizing.startSize,
      { x: resizing.startX, y: resizing.startY },
      { x: e.clientX, y: e.clientY },
      resizing.mode,
      window.innerHeight,
    );
    applyVisibleGroupColumnSize(nextSize);
    e.preventDefault();
  }

  function finishPointerResize(handle, e) {
    if (!resizing || resizing.handle !== handle) return;
    const activeResize = resizing;
    resizing = null;
    handle.classList.remove('dragging');
    document.body.classList.remove('resizing', 'resizing-width');
    col.draggable = activeResize.wasDraggable;
    if (e.type !== 'lostpointercapture' && handle.hasPointerCapture?.(activeResize.pointerId)) {
      handle.releasePointerCapture(activeResize.pointerId);
    }
    persistGroupColumnSize(g.id, readVisibleGroupColumnSize());
    e.preventDefault?.();
  }

  function resizeWithKeyboard(mode, e) {
    const nextSize = nextKeyboardGroupColumnSize(readVisibleGroupColumnSize(), e.key, mode, e.shiftKey, window.innerHeight);
    if (!nextSize) return;
    e.preventDefault();
    e.stopPropagation();
    applyVisibleGroupColumnSize(nextSize);
    persistGroupColumnSize(g.id, readVisibleGroupColumnSize());
  }

  for (const [handle, mode] of [[resizerH, 'width'], [resizerCorner, 'corner']]) {
    if (!handle) continue;
    handle.addEventListener('keydown', e => resizeWithKeyboard(mode, e));
    handle.addEventListener('pointerdown', e => beginPointerResize(mode, handle, e));
    handle.addEventListener('pointermove', e => movePointerResize(handle, e));
    handle.addEventListener('pointerup', e => finishPointerResize(handle, e));
    handle.addEventListener('pointercancel', e => finishPointerResize(handle, e));
    handle.addEventListener('lostpointercapture', e => finishPointerResize(handle, e));
  }

  return col;
}

// ════════════════════════════════════════════════════════════════
// ITEMS
// ════════════════════════════════════════════════════════════════
function buildItem(it, parentItems, group) {
  let el;
  if (it.type === 'note') el = buildNote(it, parentItems, group);
  else if (it.type === 'todo') el = buildTodo(it, parentItems, group);
  else if (it.type === 'stack') el = buildStack(it, parentItems, group);
  else el = buildTab(it, parentItems, group);
  attachItemSelection(el, it);
  return el;
}

const ITEM_MARKER_COLORS = Object.freeze(['none', 'red', 'orange', 'yellow', 'green', 'blue']);

function itemMarkerChoice(item) {
  const stored = typeof item?.color === 'string' && item.color ? item.color : null;
  if (!stored) return 'none';
  return ITEM_MARKER_COLORS.includes(stored) ? stored : 'custom';
}

function itemMarkerFocusKey(item) {
  return `marker-${itemMarkerChoice(item)}`;
}

function applyBoardRecordMarker(element, item) {
  const stored = typeof item?.color === 'string' && item.color ? item.color : null;
  if (!stored || stored === 'none') return;
  element.dataset.color = stored;
  if (!ITEM_MARKER_COLORS.includes(stored)) {
    // Imported custom bytes remain compatible and visible, but only flow into
    // the color-only property consumed by CSS. Invalid values simply do not paint.
    element.style.setProperty('--record-custom-marker', stored);
  }
}

function boardNotePreviewText(item) {
  try {
    const doc = new DOMParser().parseFromString(sanitizeHtml(item?.html || ''), 'text/html');
    return String(doc.body?.textContent || '').replace(/\s+/g, ' ').trim();
  } catch {
    return '';
  }
}

function openBoardRecordDetail(item, opener = null, initialFocusKey = '') {
  if (!item?.id || !findItem(item.id)) return false;
  if (opener?.isConnected && typeof opener.focus === 'function') focusDialogOpener(opener);
  openItemDetail(item.id, { initialFocusKey });
  return true;
}

let boardLocalRecordCreatePending = null;
let boardLocalRecordCreateInertElements = [];

function isBoardLocalRecordCreatePending() {
  return !!boardLocalRecordCreatePending;
}

function createBoardLocalRecordContext(group, type) {
  if (!group || !['note', 'todo'].includes(type) || !Array.isArray(group.items)) return null;
  const destinationContext = createItemListCaptureContext(group.items);
  const target = resolveItemListCaptureTarget(destinationContext);
  if (!target || target.group !== group) return null;
  return Object.freeze({
    type,
    groupId: String(group.id),
    groupRef: group,
    destinationContext,
  });
}

function resolveBoardLocalRecordCreateTarget(context) {
  const target = resolveItemListCaptureTarget(context?.destinationContext);
  if (!target
      || !['note', 'todo'].includes(context?.type)
      || target.group !== context.groupRef
      || String(target.group.id) !== context.groupId) return null;
  return target;
}

function setBoardLocalRecordCreateInterlock(opener, enabled) {
  if (enabled) {
    if (!opener?.isConnected) return true;
    const owned = new Set();
    let current = opener;
    while (current?.parentElement) {
      const parent = current.parentElement;
      for (const sibling of parent.children) {
        if (sibling === current || sibling.id === 'state-recovery-overlay') continue;
        setElementInertOwner(sibling, 'board-local-record-create', true);
        owned.add(sibling);
      }
      if (parent === document.body) break;
      current = parent;
    }
    boardLocalRecordCreateInertElements = [...owned];
    return true;
  }
  const owned = boardLocalRecordCreateInertElements;
  boardLocalRecordCreateInertElements = [];
  owned.forEach(element => setElementInertOwner(element, 'board-local-record-create', false));
  return true;
}

function setBoardLocalRecordCreateBusy(opener, busy) {
  if (!busy) setBoardLocalRecordCreateInterlock(null, false);
  if (!opener?.isConnected) return true;
  if (busy) {
    try { opener.focus({ preventScroll: true }); } catch { try { opener.focus(); } catch {} }
    setBoardLocalRecordCreateInterlock(opener, true);
  }
  opener.setAttribute('aria-busy', String(busy));
  if (busy) opener.setAttribute('aria-disabled', 'true');
  else opener.removeAttribute('aria-disabled');
  return true;
}

function focusBoardLocalRecordCreateOpener(opener) {
  if (!opener?.isConnected || typeof opener.focus !== 'function') return false;
  try { opener.focus({ preventScroll: true }); } catch { try { opener.focus(); } catch { return false; } }
  return true;
}

async function createBoardLocalRecord(group, type, opener = null, {
  prepend = false,
  revealGroup = false,
  takeSnapshot = true,
} = {}) {
  if (isBoardLocalRecordCreatePending() || State.isRecoveryRequired?.()) return false;
  const context = createBoardLocalRecordContext(group, type);
  const target = resolveBoardLocalRecordCreateTarget(context);
  if (!target) {
    toast(tr('detail.changed'), { danger: true, duration: 6000 });
    focusBoardLocalRecordCreateOpener(opener);
    return false;
  }

  let item;
  try {
    const allocateId = createOrganizationIdAllocator();
    item = type === 'note'
      ? stampNew({ id: allocateId(), type: 'note', html: '' })
      : stampNew({ id: allocateId(), type: 'todo', text: '', done: false });
  } catch {
    toast(tr('detail.changed'), { danger: true, duration: 6000 });
    focusBoardLocalRecordCreateOpener(opener);
    return false;
  }
  const transaction = { context, item, opener };
  boardLocalRecordCreatePending = transaction;
  setBoardLocalRecordCreateBusy(opener, true);
  let receipt = null;

  try {
    if (takeSnapshot) State.snapshot(tr(type === 'note' ? 'groupAction.addNote' : 'groupAction.addTodo'));
    if (prepend) target.list.unshift(item);
    else target.list.push(item);
    receipt = createCaptureDestinationReceiptContext(context.destinationContext, [item]);
    if (!receipt) throw new Error('New local record destination was not exact');
  } catch (error) {
    if (boardLocalRecordCreatePending === transaction) boardLocalRecordCreatePending = null;
    setBoardLocalRecordCreateBusy(opener, false);
    State.requireRecovery?.();
    if (typeof showStateRecoveryRequired === 'function') showStateRecoveryRequired(error);
    return false;
  }

  try {
    await State.persistNow();
  } catch (error) {
    if (boardLocalRecordCreatePending === transaction) boardLocalRecordCreatePending = null;
    setBoardLocalRecordCreateBusy(opener, false);
    if (State.isRecoveryRequired?.() && typeof showStateRecoveryRequired === 'function') {
      showStateRecoveryRequired(error);
    }
    return false;
  }

  if (boardLocalRecordCreatePending !== transaction) {
    setBoardLocalRecordCreateBusy(opener, false);
    return false;
  }
  boardLocalRecordCreatePending = null;
  setBoardLocalRecordCreateBusy(opener, false);
  if (!resolveCaptureDestinationReceiptTarget(receipt)) {
    renderAll();
    toast(tr('detail.changed'), { danger: true, duration: 6000 });
    requestAnimationFrame(() => focusBoardLocalRecordCreateOpener(opener));
    return false;
  }

  if (revealGroup) openGroupPage(context.groupId);
  else renderBoard();
  requestAnimationFrame(() => {
    const card = document.querySelector(`.item[data-id="${CSS.escape(String(item.id))}"]`);
    const primary = itemFocusTarget(card);
    if (!openBoardRecordDetail(item, primary, type === 'note' ? 'note-body' : 'task')) {
      focusBoardLocalRecordCreateOpener(opener);
    }
  });
  return item;
}

function commonActs(it, extra = [], options = {}) {
  const afterToggle = typeof options.afterToggle === 'function' ? options.afterToggle : () => {};
  const mutationOpener = options.mutationOpener || null;
  const archiveOpener = options.archiveOpener || mutationOpener;
  const acts = [
    { text: tr('itemAction.details'), icon: cmIcons.detail, action: () => openBoardRecordDetail(it, mutationOpener) },
    ...(it.type === 'tab' ? [{
      text: tr(it.favorite ? 'itemAction.removeFavorite' : 'itemAction.addFavorite'),
      icon: cmIcons.favorite,
      action: async () => {
        const changed = await toggleFavorite(it, mutationOpener);
        if (changed) afterToggle();
        return changed;
      },
    }] : []),
    ...(it.type === 'tab' ? [{
      text: tr(it.readLaterAt ? 'itemAction.removeReadLater' : 'itemAction.saveReadLater'),
      icon: cmIcons.readLater,
      action: async () => {
        const changed = await toggleReadLater(it, mutationOpener);
        if (changed) afterToggle();
        return changed;
      },
    }] : []),
    ...(it.type === 'stack' || options.includeColor === false ? [] : [{
      text: tr('itemAction.changeMarker'),
      icon: cmIcons.color,
      action: () => openBoardRecordDetail(it, mutationOpener, itemMarkerFocusKey(it)),
    }]),
    ...(options.includeReminder === false ? [] : [
      { text: tr('itemAction.setReminder'), icon: cmIcons.clock, action: () => openReminderPicker(it.id) },
      ...(it.reminder ? [{ text: tr('itemAction.clearReminder'), icon: cmIcons.clock, action: () => clearReminder(it.id) }] : []),
    ]),
    ...extra,
    { sep: true },
    {
      text: tr('itemAction.archive'),
      icon: cmIcons.archive,
      action: options.archiveAction || (it.type === 'tab'
        ? (() => archiveSavedPage(it, archiveOpener))
        : (() => archiveItem(it.id))),
    }
  ];
  return acts;
}

async function archiveBoardLocalItemWithFocus(item, parentItems, group, opener = null) {
  const itemId = String(item?.id || '');
  const index = Array.isArray(parentItems)
    ? parentItems.findIndex(candidate => String(candidate?.id || '') === itemId)
    : -1;
  if (!itemId || index < 0) return false;
  const neighborId = parentItems[index + 1]?.id || parentItems[index - 1]?.id || '';
  const changed = await archiveBoardLocalItem(item, opener, Date.now());
  if (!changed) return false;
  requestAnimationFrame(() => {
    if (neighborId) {
      focusItem(neighborId);
      if (document.activeElement?.closest?.(`.item[data-id="${CSS.escape(neighborId)}"]`)) return;
    }
    if (group?.id && focusIdentityTarget('group', group.id)) return;
    const board = document.getElementById('board');
    focusItemDetailTarget(board?.querySelector('h1, [role="heading"]') || board);
  });
  return true;
}

function renderReminderBadge(it) {
  const now = Date.now();
  const at = pendingReminderTime(it.reminder, now);
  if (at == null) return '';
  const past = at < now;
  const cls = past ? 'past' : (at - now < 86400000 ? '' : 'future');
  return `<span class="rem-badge ${cls}"><svg width="8" height="8" viewBox="0 0 12 12"><circle cx="6" cy="6" r="4.5" stroke="currentColor" stroke-width="1.3" fill="none"/><path d="M6 3v3l2 1" stroke="currentColor" stroke-width="1.3" stroke-linecap="round"/></svg>${fmtTimeRelative(at)}</span>`;
}

function attachItemSelection(el, it, { target: suppliedTarget = null, bindContainer = true } = {}) {
  const itemId = String(it?.id || '');
  if (!itemId) return null;
  const selected = selectedItemIds.has(itemId);
  const itemTitle = String(it.type === 'stack'
    ? (it.name || tr('stackEditor.defaultName'))
    : reminderItemTitle(it)).trim() || tr('cal.untitledFallback');
  const chk = document.createElement('button');
  chk.type = 'button';
  chk.className = 'item-check' + (selected ? ' checked' : '');
  chk.dataset.itemSelectId = itemId;
  chk.setAttribute('role', 'checkbox');
  chk.setAttribute('aria-checked', String(selected));
  chk.setAttribute('aria-label', tr(selected ? 'selection.deselectItem' : 'selection.selectItem', { title: itemTitle }));
  chk.title = chk.getAttribute('aria-label');
  el.classList.toggle('item-selected', selected);
  chk.addEventListener('click', (ev) => {
    ev.stopPropagation();
    ev.preventDefault();
    if (ev.shiftKey) selectRangeTo(itemId);
    else toggleItemSelect(itemId);
    requestAnimationFrame(() => {
      const escaped = CSS.escape(itemId);
      const rebuilt = document.querySelector(`[data-item-select-id="${escaped}"]`);
      if (!rebuilt?.isConnected || typeof rebuilt.focus !== 'function') return;
      try { rebuilt.focus({ preventScroll: true }); } catch { rebuilt.focus(); }
    });
  });
  // The selector is a persistent filing-index slot in every record header. List
  // Stacks supply their separately built header and reuse the same native control.
  const target = suppliedTarget
    || el.querySelector('.board-record-head')
    || el.querySelector('.stack-hd')
    || el.querySelector('.item-top')
    || el;
  target.insertBefore(chk, target.firstChild);

  if (bindContainer) {
    // Whole-item click toggles selection when in selection mode.
    el.addEventListener('click', (ev) => {
      if (!itemSelMode && !ev.shiftKey) return;
      if (ev.target.closest('.item-check') || ev.target.closest('button') || ev.target.closest('input, textarea, select, [contenteditable="true"]')) return;
      ev.stopPropagation();
      ev.preventDefault();
      if (ev.shiftKey) selectRangeTo(itemId);
      else toggleItemSelect(itemId);
    }, true);  // capture phase to beat link openers
  }
  return chk;
}

function visibleItemSelectionOrder() {
  const root = document.getElementById('board') || document;
  return Array.from(root.querySelectorAll('.item[data-id], .lv-stack[data-id]'))
    .filter(el => {
      if (el.classList.contains('hidden') || !el.getClientRects().length) return false;
      const closedStack = el.parentElement?.closest('.stack:not(.expanded):not(.search-expand), .lv-stack:not(.expanded):not(.search-expand)');
      return !closedStack;
    })
    .map(el => el.dataset.id)
    .filter(id => id && findItem(id));
}

// Range selection in the current visual order, with a data-list fallback.
function selectRangeTo(itemId) {
  if (!lastSelectedItemId) {
    selectedItemIds.add(itemId);
    lastSelectedItemId = itemId;
    syncItemSelMode();
    renderBoard();
    renderItemSelToolbar();
    return;
  }
  const order = visibleItemSelectionOrder();
  const aI = order.indexOf(lastSelectedItemId);
  const bI = order.indexOf(itemId);
  if (aI > -1 && bI > -1) {
    const [lo, hi] = aI < bI ? [aI, bI] : [bI, aI];
    for (let i = lo; i <= hi; i++) selectedItemIds.add(order[i]);
    lastSelectedItemId = itemId;
    syncItemSelMode();
    renderBoard();
    renderItemSelToolbar();
    return;
  }
  const a = findItem(lastSelectedItemId), b = findItem(itemId);
  if (!a || !b || a.parent !== b.parent) { toggleItemSelect(itemId); lastSelectedItemId = itemId; return; }
  const [lo, hi] = a.index < b.index ? [a.index, b.index] : [b.index, a.index];
  for (let i = lo; i <= hi; i++) selectedItemIds.add(a.parent[i].id);
  lastSelectedItemId = itemId;
  syncItemSelMode();
  renderBoard();
  renderItemSelToolbar();
}

// Decorate a freshly-built item card with the §4.2 metadata: expose tags to the
// tag: search operator (dataset.tags), paint an optional cover chip, surface tag
// chips, and flag cards that carry hidden detail so the board hints at it. Called
// at the tail of every item builder so all kinds get it uniformly.
function applyItemMeta(el, it) {
  const tags = Array.isArray(it.tags) ? it.tags.filter(Boolean) : [];
  if (tags.length) el.dataset.tags = tags.map(t => String(t).toLowerCase()).join(',');

  // Stacks are containers with their own header-first layout; only expose their
  // tags to search and skip the card-style cover/chip/meta chrome.
  if (it.type === 'stack') return;

  if (it.cover) {
    const cov = document.createElement('div');
    cov.className = 'item-cover';
    if (it.cover.emoji) { cov.classList.add('emoji'); cov.textContent = it.cover.emoji; }
    else if (it.cover.color) { cov.classList.add('color'); cov.style.backgroundColor = it.cover.color; }
    el.insertBefore(cov, el.firstChild);
    el.classList.add('has-cover');
  }

  if (tags.length) {
    const wrap = document.createElement('div');
    wrap.className = 'item-tags';
    tags.slice(0, 4).forEach(t => { const c = document.createElement('span'); c.className = 'item-tag'; c.textContent = t; wrap.appendChild(c); });
    if (tags.length > 4) { const m = document.createElement('span'); m.className = 'item-tag more'; m.textContent = '+' + (tags.length - 4); wrap.appendChild(m); }
    el.appendChild(wrap);
  }

  const checked = Array.isArray(it.checklist) ? it.checklist.filter(x => x.done).length : 0;
  const total = Array.isArray(it.checklist) ? it.checklist.length : 0;
  const hasNotes = !!(it.notes && it.notes.replace(/<[^>]*>/g, '').trim());
  const hasFields = Array.isArray(it.customFields) && it.customFields.length > 0;
  if (hasNotes || total || hasFields) {
    el.classList.add('has-detail');
    const meta = document.createElement('button');
    meta.type = 'button';
    meta.className = 'item-detail-meta';
    meta.dataset.itemDetailTrigger = 'true';
    const itemTitle = reminderItemTitle(it);
    const detailsLabel = tr('itemAction.detailsFor', { title: itemTitle });
    meta.setAttribute('aria-label', detailsLabel);
    meta.title = detailsLabel;
    const label = document.createElement('span');
    label.className = 'idm-label';
    label.textContent = tr('itemAction.details');
    meta.appendChild(label);
    const facts = document.createElement('span');
    facts.className = 'idm-facts';
    const addFact = (className, text) => {
      const fact = document.createElement('span');
      fact.className = `idm-fact ${className}`;
      fact.textContent = text;
      facts.appendChild(fact);
    };
    if (hasNotes) addFact('idm-note', tr('detail.whySaved'));
    if (total) addFact('idm-check', `${tr('detail.checklist')} ${checked}/${total}`);
    if (hasFields) addFact('idm-fields', `${tr('detail.customFields')} ${it.customFields.length}`);
    meta.appendChild(facts);
    meta.addEventListener('click', e => {
      e.stopPropagation();
      openItemDetail(it.id, { returnFocusKey: 'board-item-details' });
    });
    el.appendChild(meta);
  }
}

function buildTab(it, parentItems, group) {
  const el = document.createElement('div');
  el.className = 'item tab';
  el.dataset.id = it.id;
  // The saved page is one local record: a truthful filing label, one explicit
  // recovery action, its source, and one shared secondary-action entry.
  el.tabIndex = -1;
  applyBoardRecordMarker(el, it);
  const savedUrl = typeof it.url === 'string' ? it.url : '';
  const savedTitle = typeof it.title === 'string' ? it.title.trim() : '';
  const itemTitle = savedTitle || dispUrl(savedUrl) || tr('itemAction.untitled');
  const canOpen = isOpenableSavedTabUrl(savedUrl);
  const primaryLabel = canOpen
    ? tr('itemAction.open', { title: itemTitle })
    : tr('itemAction.openUnavailable', { title: itemTitle });
  const recordKind = tr('home.previewType.tab');
  const moreLabel = tr('library.moreActions', { title: itemTitle });
  // Expose the URL for the domain:/site:/url: search operators. dataset.host is the
  // bare hostname (matched by domain:/site:), dataset.url the full URL (matched by url:).
  // Stored lowercase so the operator parse (which lowercases the query) can substring-match.
  if (savedUrl) {
    el.dataset.url = savedUrl.toLowerCase();
    try { el.dataset.host = new URL(savedUrl).hostname.toLowerCase(); } catch {}
  }
  el.draggable = true;

  const fav = favUrl(savedUrl) || BLANK_FAV;
  el.innerHTML = `
    <div class="board-record-head">
      <span class="board-record-kind">${esc(recordKind)}</span>
      <span class="board-record-head-spacer" aria-hidden="true"></span>
      ${renderReminderBadge(it)}
      <button type="button" class="board-record-menu" data-item-archive="menu" aria-haspopup="menu" title="${esc(moreLabel)}" aria-label="${esc(moreLabel)}">
        <svg width="16" height="16" viewBox="0 0 16 16" aria-hidden="true"><circle cx="3" cy="8" r="1.25" fill="currentColor"/><circle cx="8" cy="8" r="1.25" fill="currentColor"/><circle cx="13" cy="8" r="1.25" fill="currentColor"/></svg>
      </button>
    </div>
    <div class="item-top board-record-body board-page-body">
      <img class="item-fav" src="${esc(fav)}" alt="" loading="lazy" decoding="async">
      <button type="button" class="item-title item-primary" data-item-primary="true"
        aria-label="${esc(primaryLabel)}"${canOpen ? '' : ' aria-disabled="true" data-unavailable="true"'}
        title="${esc(primaryLabel)}">${esc(itemTitle)}</button>
    </div>
    <div class="item-url">${esc(dispUrl(savedUrl))}</div>`;

  const primary = el.querySelector(':scope > .item-top > [data-item-primary="true"]');
  const menuButton = el.querySelector('.board-record-menu');
  primary.addEventListener('click', e => {
    e.stopPropagation();
    if (!canOpen) {
      e.preventDefault();
      return;
    }
    openSavedTabItem(it, { focus: true, opener: primary });
  });
  const archiveSavedTab = async (archiveOpener = menuButton || primary) => {
    const index = parentItems.findIndex(item => item?.id === it.id);
    const neighborId = parentItems[index + 1]?.id || parentItems[index - 1]?.id || '';
    const changed = await archiveSavedPage(it, archiveOpener, Date.now());
    if (!changed) return false;
    requestAnimationFrame(() => {
      if (neighborId) {
        focusItem(neighborId);
        if (document.activeElement?.closest?.(`.item[data-id="${CSS.escape(neighborId)}"]`)) return;
      }
      if (group?.id && focusIdentityTarget('group', group.id)) return;
      const board = document.getElementById('board');
      focusItemDetailTarget(board?.querySelector('h1, [role="heading"]') || board);
    });
    return true;
  };
  const savedTabMenuItems = opener => {
    const stableOpener = opener || menuButton || primary;
    const wrapAction = action => () => {
      focusDialogOpener(stableOpener);
      return action();
    };
    const restoreSavedTabFocus = () => requestAnimationFrame(() => focusItem(it.id));
    return [
      ...(canOpen ? [
        { text: tr('itemAction.openFocused'), icon: cmIcons.open, action: () => openSavedTabItem(it, { focus: true, opener: stableOpener }) },
        { text: tr('itemAction.openBackground'), icon: cmIcons.open, action: () => openSavedTabItem(it, { focus: false, reuse: false, opener: stableOpener }) },
      ] : []),
      ...(savedUrl ? [
        { text: tr('itemAction.copyUrl'), icon: cmIcons.copy, action: () => copySavedTabUrl(savedUrl) },
      ] : []),
      { text: tr('itemAction.editTitle'), icon: cmIcons.edit, action: () => openItemDetail(it.id, { initialFocusKey: 'title' }) },
      ...commonActs(it, [], {
        includeColor: false,
        includeReminder: false,
        mutationOpener: stableOpener,
        afterToggle: restoreSavedTabFocus,
        archiveAction: () => archiveSavedTab(stableOpener),
      }),
    ].map(item => item.action ? { ...item, action: wrapAction(item.action) } : item);
  };
  bindBoardItemContextMenu(el, savedTabMenuItems, { menuButton });
  applyItemMeta(el, it);
  attachItemDrag(el, it, parentItems, group);
  return el;
}

function buildNote(it, parentItems, group) {
  const el = document.createElement('div');
  el.className = 'item note';
  el.dataset.id = it.id;
  el.tabIndex = -1;
  applyBoardRecordMarker(el, it);
  el.draggable = true;

  const noteText = boardNotePreviewText(it);
  const preview = noteText || tr('detail.emptyNote');
  const moreLabel = tr('library.moreActions', { title: reminderItemTitle(it) });
  const editLabel = tr('itemAction.editNoteFor', { title: preview.slice(0, 80) });
  el.innerHTML = `
    <div class="board-record-head">
      <span class="board-record-kind">${esc(tr('home.previewType.note'))}</span>
      <span class="board-record-head-spacer"></span>
      ${renderReminderBadge(it)}
      <button type="button" class="board-record-menu" data-item-archive="menu" aria-haspopup="menu" title="${esc(moreLabel)}" aria-label="${esc(moreLabel)}">
        <svg width="16" height="16" viewBox="0 0 16 16" aria-hidden="true"><circle cx="3" cy="8" r="1.25" fill="currentColor"/><circle cx="8" cy="8" r="1.25" fill="currentColor"/><circle cx="13" cy="8" r="1.25" fill="currentColor"/></svg>
      </button>
    </div>
    <button type="button" class="item-top board-record-body board-record-primary" data-item-primary="true" data-empty="${!noteText}" aria-label="${esc(editLabel)}">
      <span class="note-text">${esc(preview)}</span>
    </button>`;

  const primary = el.querySelector('.board-record-primary');
  const menuButton = el.querySelector('.board-record-menu');
  primary.addEventListener('click', event => {
    openBoardRecordDetail(it, event.currentTarget, 'note-body');
  });
  bindBoardItemContextMenu(el, opener => [
    { text: tr('itemAction.editNote'), icon: cmIcons.edit, action: () => openBoardRecordDetail(it, opener, 'note-body') },
    ...commonActs(it, [], {
      mutationOpener: opener,
      archiveAction: () => {
        const receiptOpener = document.querySelector(
          `.item.note[data-id="${CSS.escape(it.id)}"] .board-record-menu`,
        ) || menuButton;
        return archiveBoardLocalItemWithFocus(it, parentItems, group, receiptOpener);
      },
    }),
  ], { menuButton });
  applyItemMeta(el, it);
  attachItemDrag(el, it, parentItems, group);
  return el;
}

function autoLinkify(html) {
  // Only if not already linked
  const urlRe = /(?<!href=")(?<!>)(https?:\/\/[^\s<>"']+)/gi;
  return html.replace(urlRe, '<a href="$1" target="_blank" rel="noopener">$1</a>');
}

let boardTodoCompletionMutationPending = null;
let boardTodoCompletionInertElements = [];

function isBoardTodoCompletionPending() {
  return !!boardTodoCompletionMutationPending;
}

function createBoardTodoCompletionContext(item) {
  const context = createItemReminderMutationContext(item?.id);
  if (!context || context.itemRef !== item || context.itemType !== 'todo') return null;
  return context;
}

function resolveBoardTodoCompletionTarget(context) {
  const target = resolveItemReminderMutationTarget(context);
  if (!target || target.item !== context.itemRef || target.item.type !== 'todo') return null;
  return target;
}

function setBoardTodoCompletionInterlock(button, enabled) {
  if (enabled) {
    const owned = new Set();
    let current = button;
    while (current?.parentElement) {
      const parent = current.parentElement;
      for (const sibling of parent.children) {
        if (sibling === current || sibling.id === 'state-recovery-overlay') continue;
        setElementInertOwner(sibling, 'board-todo-completion', true);
        owned.add(sibling);
      }
      if (parent === document.body) break;
      current = parent;
    }
    boardTodoCompletionInertElements = [...owned];
    return;
  }
  const owned = boardTodoCompletionInertElements;
  boardTodoCompletionInertElements = [];
  owned.forEach(element => setElementInertOwner(element, 'board-todo-completion', false));
}

function setBoardTodoCompletionBusy(context, opener, busy) {
  const itemId = String(context?.itemId || '');
  const fallback = itemId
    ? document.querySelector(`.item[data-id="${CSS.escape(itemId)}"] .todo-check`)
    : null;
  const button = opener?.matches?.('.todo-check') && opener.isConnected ? opener : fallback;
  if (!busy) setBoardTodoCompletionInterlock(null, false);
  if (!button) return !busy;
  if (busy) setBoardTodoCompletionInterlock(button, true);
  button.setAttribute('aria-busy', String(busy));
  button.disabled = busy;
  if (busy) button.setAttribute('aria-disabled', 'true');
  else button.removeAttribute('aria-disabled');
  const card = button.closest('.item.todo');
  card?.classList.toggle('is-todo-pending', busy);
  if (card) {
    if (busy) card.setAttribute('aria-busy', 'true');
    else card.removeAttribute('aria-busy');
  }
  return true;
}

async function toggleBoardTodoCompletion(it, opener = null) {
  if (!it
      || it.type !== 'todo'
      || isBoardTodoCompletionPending()
      || (typeof isBoardLocalRecordCreatePending === 'function' && isBoardLocalRecordCreatePending())) return false;
  if (State.isRecoveryRequired?.()) return false;
  const context = createBoardTodoCompletionContext(it);
  if (!context) return false;
  const target = resolveBoardTodoCompletionTarget(context);
  if (!target) return false;

  const transaction = { context, itemId: context.itemId, opener };
  boardTodoCompletionMutationPending = transaction;
  if (!setBoardTodoCompletionBusy(context, opener, true)) {
    boardTodoCompletionMutationPending = null;
    return false;
  }
  try {
    State.snapshot(tr(target.item.done ? 'detail.markIncomplete' : 'detail.markComplete'));
    target.item.done = !target.item.done;
  } catch (error) {
    if (boardTodoCompletionMutationPending === transaction) boardTodoCompletionMutationPending = null;
    setBoardTodoCompletionBusy(context, opener, false);
    State.requireRecovery?.();
    if (typeof showStateRecoveryRequired === 'function') showStateRecoveryRequired(error);
    return false;
  }

  try {
    await State.persistNow();
  } catch (error) {
    if (boardTodoCompletionMutationPending === transaction) boardTodoCompletionMutationPending = null;
    setBoardTodoCompletionBusy(context, opener, false);
    if (State.isRecoveryRequired?.() && typeof showStateRecoveryRequired === 'function') {
      showStateRecoveryRequired(error);
    }
    return false;
  }

  if (boardTodoCompletionMutationPending !== transaction) {
    setBoardTodoCompletionBusy(context, opener, false);
    return false;
  }
  boardTodoCompletionMutationPending = null;
  setBoardTodoCompletionBusy(context, opener, false);
  renderBoard();
  requestAnimationFrame(() => {
    document.querySelector(`.item[data-id="${CSS.escape(String(it.id))}"] .todo-check`)?.focus();
  });
  return true;
}

function buildTodo(it, parentItems, group) {
  const el = document.createElement('div');
  el.className = 'item todo' + (it.done ? ' done' : '');
  el.dataset.id = it.id;
  el.tabIndex = -1;
  applyBoardRecordMarker(el, it);
  el.draggable = true;

  const storedTaskText = String(it.text || '').trim();
  const taskText = storedTaskText || tr('detail.emptyTodo');
  const moreLabel = tr('library.moreActions', { title: taskText });
  const editLabel = tr('itemAction.editTodoFor', { title: taskText.slice(0, 80) });
  el.innerHTML = `
    <div class="board-record-head">
      <span class="board-record-kind">${esc(tr('home.previewType.todo'))}</span>
      <span class="board-record-head-spacer"></span>
      ${renderReminderBadge(it)}
      <button type="button" class="board-record-menu" data-item-archive="menu" aria-haspopup="menu" title="${esc(moreLabel)}" aria-label="${esc(moreLabel)}">
        <svg width="16" height="16" viewBox="0 0 16 16" aria-hidden="true"><circle cx="3" cy="8" r="1.25" fill="currentColor"/><circle cx="8" cy="8" r="1.25" fill="currentColor"/><circle cx="13" cy="8" r="1.25" fill="currentColor"/></svg>
      </button>
    </div>
    <div class="item-top board-record-body board-record-todo-body">
      <button type="button" class="todo-check ${it.done ? 'checked' : ''}" aria-pressed="${!!it.done}" aria-label="${esc(tr(it.done ? 'detail.markIncomplete' : 'detail.markComplete'))}"></button>
      <button type="button" class="board-record-primary board-record-todo-primary" data-item-primary="true" data-empty="${!storedTaskText}" aria-label="${esc(editLabel)}">
        <span class="todo-text">${esc(taskText)}</span>
      </button>
    </div>`;

  const todoCheck = el.querySelector('.todo-check');
  const primary = el.querySelector('.board-record-primary');
  const menuButton = el.querySelector('.board-record-menu');
  todoCheck.addEventListener('click', e => {
    e.stopPropagation();
    void toggleBoardTodoCompletion(it, e.currentTarget);
  });
  primary.addEventListener('click', event => {
    openBoardRecordDetail(it, event.currentTarget, 'task');
  });
  bindBoardItemContextMenu(el, opener => [
    { text: tr('itemAction.editTodo'), icon: cmIcons.edit, action: () => openBoardRecordDetail(it, opener, 'task') },
    { text: tr(it.done ? 'detail.markIncomplete' : 'detail.markComplete'), icon: cmIcons.edit, action: () => toggleBoardTodoCompletion(it, todoCheck) },
    ...commonActs(it, [], {
      mutationOpener: opener,
      archiveAction: () => {
        const receiptOpener = document.querySelector(
          `.item.todo[data-id="${CSS.escape(it.id)}"] .board-record-menu`,
        ) || menuButton;
        return archiveBoardLocalItemWithFocus(it, parentItems, group, receiptOpener);
      },
    }),
  ], { menuButton });
  applyItemMeta(el, it);
  attachItemDrag(el, it, parentItems, group);
  return el;
}

function createStackDropPreview(container, toggleButton, item) {
  let timer = null;
  const onDragEnd = () => clear();

  function clear() {
    if (timer != null) {
      clearTimeout(timer);
      timer = null;
    }
    document.removeEventListener('dragend', onDragEnd, true);
    if (!item.expanded) {
      container.classList.remove('expanded');
      toggleButton.setAttribute('aria-expanded', 'false');
    }
  }

  function schedule() {
    if (item.expanded || timer != null) return false;
    document.addEventListener('dragend', onDragEnd, { capture: true, once: true });
    timer = setTimeout(() => {
      timer = null;
      if (item.expanded) return;
      container.classList.add('expanded');
      toggleButton.setAttribute('aria-expanded', 'true');
    }, 500);
    return true;
  }

  function commit() {
    clear();
    item.expanded = true;
    container.classList.add('expanded');
    toggleButton.setAttribute('aria-expanded', 'true');
    return true;
  }

  return { schedule, clear, commit };
}

function stackActionMenuItems(stack, opener, options = {}) {
  if (!Array.isArray(options.parentItems) || !options.group) return [];
  const identity = identityStackTarget(stack?.id);
  if (!identity
      || identity.item !== stack
      || identity.parentItems !== options.parentItems
      || identity.group !== options.group) return [];
  const identityParams = {
    workspaceId: identity.workspace.id,
    spaceId: identity.space.id,
    groupId: identity.group.id,
    stackId: identity.item.id,
  };
  const toggleCollapse = typeof options.toggleCollapse === 'function'
    ? options.toggleCollapse
    : null;
  const archiveAction = typeof options.archiveAction === 'function'
    ? options.archiveAction
    : () => archiveBoardLocalItemWithFocus(
        stack,
        identity.parentItems,
        identity.group,
        opener,
      );
  return [
    { text: tr('stackAction.edit'), icon: cmIcons.edit, action: () => openIdentityEditor('stack', 'edit', identityParams, opener) },
    { text: tr('stackAction.editIntention'), icon: cmIcons.edit, action: () => openIntentEditor('stack', identity.item.id) },
    ...(toggleCollapse ? [{
      text: tr(stack.expanded ? 'stackAction.collapse' : 'stackAction.expand'),
      icon: cmIcons.edit,
      action: toggleCollapse,
    }] : []),
    { sep: true },
    ...commonActs(stack, [], {
      mutationOpener: opener,
      archiveOpener: opener,
      archiveAction,
    }),
  ];
}

function buildStack(it, parentItems, group) {
  const el = document.createElement('div');
  el.className = 'item stack' + (it.expanded ? ' expanded' : '');
  el.dataset.id = it.id;
  el.tabIndex = -1;
  if (it.color) {
    el.dataset.color = it.color;
    el.style.setProperty('--stack-tint', it.color);
  }
  el.draggable = true;

  const stackName = it.name || tr('stackEditor.defaultName');
  const stackKind = tr('home.previewType.stack');
  const itemCnt = (it.items || []).length;
  const itemLabel = itemCnt === 1
    ? tr('groupAction.oneItem')
    : tr('groupAction.items', { count: itemCnt });
  el.innerHTML = `
    <div class="stack-hd" role="group" aria-label="${esc(tr('stackAction.aria', { name: stackName }))}">
      <button class="stack-chev stack-toggle" type="button" aria-expanded="${!!it.expanded}" aria-label="${esc(tr(it.expanded ? 'stackAction.collapseFor' : 'stackAction.expandFor', { name: stackName }))}"><svg width="10" height="10" viewBox="0 0 10 10" aria-hidden="true"><path d="M3 4l2 2 2-2" stroke="currentColor" stroke-width="1.5" fill="none" stroke-linecap="round"/></svg></button>
      <button class="stack-sym" type="button" aria-label="${esc(tr('stackAction.editFor', { name: stackName }))}">${esc(it.symbol || '📚')}</button>
      <div class="stack-copy">
        <span class="stack-name">${esc(stackName)}</span>
        <span class="stack-meta"><span class="stack-kind">${esc(stackKind)}</span><span class="stack-cnt">${esc(itemLabel)}</span></span>
      </div>
      <button class="stack-more" type="button" data-act="more" data-item-archive="menu" title="${esc(tr('library.moreActions', { title: stackName }))}" aria-label="${esc(tr('library.moreActions', { title: stackName }))}" aria-haspopup="menu">
        <svg width="12" height="12" viewBox="0 0 12 12" fill="currentColor" aria-hidden="true"><circle cx="3" cy="6" r="1"/><circle cx="6" cy="6" r="1"/><circle cx="9" cy="6" r="1"/></svg>
      </button>
    </div>
    <div class="stack-items"></div>`;

  const hd = el.querySelector('.stack-hd');
  const toggleButton = el.querySelector('.stack-toggle');
  const dropPreview = createStackDropPreview(el, toggleButton, it);
  const toggleStack = () => {
    State.snapshot('Toggle stack');
    it.expanded = !it.expanded;
    el.classList.toggle('expanded');
    toggleButton.setAttribute('aria-expanded', String(!!it.expanded));
    toggleButton.setAttribute('aria-label', tr(it.expanded ? 'stackAction.collapseFor' : 'stackAction.expandFor', { name: it.name || tr('stackEditor.defaultName') }));
    State.persist();
  };
  const openStackIdentity = (opener, focusField) => {
    const identity = identityStackTarget(it.id);
    if (!identity || identity.item !== it) return false;
    return openIdentityEditor('stack', 'edit', {
      workspaceId: identity.workspace.id,
      spaceId: identity.space.id,
      groupId: identity.group.id,
      stackId: it.id,
      focusField,
    }, opener);
  };
  hd.addEventListener('click', e => {
    if (e.target.closest('button') || e.target.closest('.stack-sym')) return;
    toggleStack();
  });
  toggleButton.addEventListener('click', e => { e.stopPropagation(); toggleStack(); });
  const menuButton = el.querySelector('[data-act="more"]');
  const stackMenuItems = opener => stackActionMenuItems(it, opener, {
    parentItems,
    group,
    toggleCollapse: toggleStack,
  });
  bindBoardItemContextMenu(hd, stackMenuItems, { menuButton });
  el.querySelector('.stack-sym').addEventListener('click', e => { e.stopPropagation(); openStackIdentity(e.currentTarget, 'symbol'); });

  const inner = el.querySelector('.stack-items');
  (it.items || []).forEach(sub => inner.appendChild(buildItem(sub, it.items, group)));
  makeGroupDropZone(inner, el, group, it.items, dropPreview);

  // Auto-expand stack when dragging over its header
  hd.addEventListener('dragover', (e) => {
    if (!drag) return;
    if (drag.kind === 'tab' && !isOpenableSavedTabUrl(drag.data?.url)) return;
    if (drag.kind === 'tabs-multi' && !captureEligibleTabs(drag.data).length) return;
    e.preventDefault();
    e.stopPropagation();
    hd.classList.add('drop-target');
    dropPreview.schedule();
  });
  hd.addEventListener('dragleave', (e) => {
    if (!el.contains(e.relatedTarget)) {
      hd.classList.remove('drop-target');
      dropPreview.clear();
    }
  });
  hd.addEventListener('drop', async (e) => {
    if (!drag) return;
    e.preventDefault();
    e.stopPropagation();
    hd.classList.remove('drop-target');
    dropPreview.clear();
    // Expand and drop at end of stack only after the capture is eligible and
    // the original collapsed state belongs to Undo.
    if (drag.kind === 'tab') {
      await handleTabDropIntoList(drag.data, it.items, it.items.length, {
        afterSnapshot: () => dropPreview.commit(),
      });
    }
    else if (drag.kind === 'tabs-multi') {
      await handleTabDropIntoList(drag.data, it.items, it.items.length, {
        afterSnapshot: () => dropPreview.commit(),
      });
    } else if (drag.kind === 'item') {
      const info = findItem(drag.id);
      if (!info) return;
      if (info.item.type === 'stack' && isDescendantOf(it.items, info.item)) { toast(tr('feedback.stackSelf'), { danger: true }); return; }
      if (info.item.id === it.id) return;
      State.snapshot('Move to stack');
      dropPreview.commit();
      const [moved] = info.parent.splice(info.index, 1);
      it.items.push(moved);
      State.persist(); renderBoard();
    }
  });

  applyItemMeta(el, it);
  attachItemDrag(el, it, parentItems, group);
  return el;
}

// ════════════════════════════════════════════════════════════════
// DRAG & DROP
// ════════════════════════════════════════════════════════════════
let drag = null;

// ─── Item selection (for groups/stacks batch actions) ───
let selectedItemIds = new Set();
let itemSelMode = false;       // derived: explicit mode on, OR something is selected
let explicitSelMode = false;   // sticky mode toggled via the select-mode button
let lastSelectedItemId = null;
let selectedItemMutationPending = null;
let selectedItemMutationInertElements = [];

function isSelectedItemMutationPending() {
  return !!selectedItemMutationPending;
}

function selectedItemSetMatches(itemIds) {
  if (!Array.isArray(itemIds) || selectedItemIds.size !== itemIds.length) return false;
  return itemIds.every(itemId => selectedItemIds.has(itemId));
}

// Move destinations use the same exact list shape as capture receipts, but may
// live outside the active Space. IDs reject ambiguity; runtime references and
// names reject storage adoption, object replacement, and rename drift.
function createSelectedItemDestinationContext(list) {
  if (!Array.isArray(list)) return null;
  const matches = collectItemListCaptureTargets().filter(target => target.list === list);
  if (matches.length !== 1) return null;
  const target = matches[0];
  const ids = [target.workspace?.id, target.space?.id, target.group?.id, ...target.stacks.map(stack => stack?.id)];
  if (ids.some(id => typeof id !== 'string' || !id.trim())) return null;
  const context = Object.freeze({
    workspaceId: target.workspace.id,
    spaceId: target.space.id,
    groupId: target.group.id,
    stackIds: Object.freeze(target.stacks.map(stack => stack.id)),
    workspaceName: String(target.workspace.name || ''),
    spaceName: String(target.space.name || ''),
    groupName: String(target.group.name || ''),
    stackNames: Object.freeze(target.stacks.map(stack => String(stack.name || ''))),
    workspaceRef: target.workspace,
    spaceRef: target.space,
    groupRef: target.group,
    stackRefs: Object.freeze([...target.stacks]),
    listRef: list,
  });
  return resolveItemListCaptureTarget(context) ? context : null;
}

function createSelectedItemMutationContext(itemIds, { selectionOwned = false } = {}) {
  const requestedIds = Array.from(itemIds || []).map(itemId => String(itemId));
  if (!requestedIds.length
      || requestedIds.some(itemId => !itemId.trim())
      || new Set(requestedIds).size !== requestedIds.length) return null;
  const resolved = identityItemTargets(requestedIds);
  if (!resolved || resolved.nested || resolved.targets.length !== requestedIds.length) return null;
  const targets = resolved.targets;
  const sourceContexts = targets.map(target => createSelectedItemDestinationContext(target.parentItems));
  if (sourceContexts.some(context => !context)) return null;
  const context = Object.freeze({
    itemIds: Object.freeze(targets.map(target => String(target.item.id))),
    itemRefs: Object.freeze(targets.map(target => target.item)),
    itemFingerprints: Object.freeze(targets.map(target => itemDetailValueFingerprint(target.item))),
    sourceContexts: Object.freeze(sourceContexts),
    selectionOwned: !!selectionOwned,
  });
  return resolveSelectedItemMutationTargets(context) ? context : null;
}

function resolveSelectedItemMutationTargets(context) {
  if (!context || !Array.isArray(context.itemIds) || !context.itemIds.length
      || !Array.isArray(context.itemRefs) || !Array.isArray(context.itemFingerprints)
      || !Array.isArray(context.sourceContexts)
      || context.itemIds.length !== context.itemRefs.length
      || context.itemIds.length !== context.itemFingerprints.length
      || context.itemIds.length !== context.sourceContexts.length
      || new Set(context.itemIds).size !== context.itemIds.length
      || (context.selectionOwned && !selectedItemSetMatches(context.itemIds))) return null;
  const resolved = identityItemTargets(context.itemIds);
  if (!resolved || resolved.nested || resolved.targets.length !== context.itemIds.length) return null;
  const byId = new Map(resolved.targets.map(target => [String(target.item?.id), target]));
  const targets = [];
  for (let index = 0; index < context.itemIds.length; index += 1) {
    const target = byId.get(context.itemIds[index]);
    const source = resolveItemListCaptureTarget(context.sourceContexts[index]);
    if (!target || !source
        || target.item !== context.itemRefs[index]
        || itemDetailValueFingerprint(target.item) !== context.itemFingerprints[index]
        || target.parentItems !== source.list
        || target.workspace !== source.workspace
        || target.space !== source.space
        || target.group !== source.group
        || target.ancestorStackIds.length !== source.stacks.length
        || target.ancestorStackIds.some((itemId, stackIndex) => String(itemId) !== String(source.stacks[stackIndex].id))
        || target.parentItems[target.index] !== target.item) return null;
    targets.push(target);
  }
  return { targets };
}

function selectedItemMoveOptions(context) {
  const resolved = resolveSelectedItemMutationTargets(context);
  if (!resolved) return null;
  const sourceLists = new Set(resolved.targets.map(target => target.parentItems));
  const selectedIds = new Set(context.itemIds);
  const options = [];
  for (const target of collectItemListCaptureTargets()) {
    if (sourceLists.has(target.list)) continue;
    if (target.stacks.some(stack => selectedIds.has(String(stack.id)))) continue;
    const destinationContext = createSelectedItemDestinationContext(target.list);
    if (!destinationContext) continue;
    const label = homeTrailPathText([
      ...homeTrailPathParts(target.workspace, target.space, homeTrailGroupName(target.group)),
      ...target.stacks.map(stack => String(stack.name || '').trim()).filter(Boolean),
    ]);
    if (!label) continue;
    options.push(Object.freeze({ destinationContext, label }));
  }
  return Object.freeze(options);
}

function selectedItemMutationBlocked() {
  return isSelectedItemMutationPending()
    || State.isRecoveryRequired?.()
    || (typeof isSavedPageArchivePending === 'function' && isSavedPageArchivePending())
    || (typeof isArchivedPageRestorePending === 'function' && isArchivedPageRestorePending())
    || (typeof isSavedTabReturnMutationPending === 'function' && isSavedTabReturnMutationPending())
    || (typeof isBoardLocalRecordCreatePending === 'function' && isBoardLocalRecordCreatePending())
    || (typeof isBoardTodoCompletionPending === 'function' && isBoardTodoCompletionPending())
    || (typeof isItemDetailMutationPending === 'function' && isItemDetailMutationPending())
    || (typeof isReminderMutationPending === 'function' && isReminderMutationPending())
    || (typeof isCalendarTaskMutationPending === 'function' && isCalendarTaskMutationPending())
    || (typeof isPlannerMutationPending === 'function' && isPlannerMutationPending())
    || (typeof isPasteImportPending === 'function' && isPasteImportPending());
}

function setSelectedItemMutationInterlock(opener, enabled) {
  if (enabled) {
    const owned = new Set();
    let current = opener;
    while (current?.parentElement) {
      const parent = current.parentElement;
      for (const sibling of parent.children) {
        if (sibling === current || sibling.id === 'state-recovery-overlay') continue;
        setElementInertOwner(sibling, 'selected-item-mutation', true);
        owned.add(sibling);
      }
      if (parent === document.body) break;
      current = parent;
    }
    selectedItemMutationInertElements = [...owned];
    return;
  }
  const owned = selectedItemMutationInertElements;
  selectedItemMutationInertElements = [];
  owned.forEach(element => setElementInertOwner(element, 'selected-item-mutation', false));
}

function setSelectedItemMutationBusy(kind, candidateOpener, busy) {
  const fallback = document.querySelector(`#item-sel-toolbar [data-act="${kind === 'move' ? 'move' : 'archive'}"]`);
  const opener = candidateOpener?.isConnected ? candidateOpener : fallback;
  if (!busy) setSelectedItemMutationInterlock(null, false);
  const bar = document.getElementById('item-sel-toolbar');
  if (bar) {
    bar.classList.toggle('is-pending', busy);
    if (busy) bar.setAttribute('aria-busy', 'true');
    else bar.removeAttribute('aria-busy');
  }
  if (!opener) return !busy;
  if (busy) {
    try { opener.focus({ preventScroll: true }); } catch { try { opener.focus(); } catch {} }
    setSelectedItemMutationInterlock(opener, true);
  }
  opener.setAttribute('aria-busy', String(busy));
  if (busy) opener.setAttribute('aria-disabled', 'true');
  else opener.removeAttribute('aria-disabled');
  return true;
}

function focusSelectedItemMutationOpener(opener) {
  if (!opener?.isConnected || typeof opener.focus !== 'function') return false;
  try { opener.focus({ preventScroll: true }); } catch { try { opener.focus(); } catch { return false; } }
  return true;
}

function focusSelectedItemMutationTarget(itemId, groupId = null) {
  if (itemId) {
    const value = typeof CSS !== 'undefined' && CSS.escape ? CSS.escape(String(itemId)) : String(itemId).replace(/["\\]/g, '\\$&');
    const item = document.querySelector(`.item[data-id="${value}"]`);
    const target = itemFocusTarget(item);
    if (target && typeof target.focus === 'function') {
      try { target.focus({ preventScroll: true }); } catch { try { target.focus(); } catch {} }
      if (document.activeElement === target) return true;
    }
  }
  if (groupId && focusIdentityTarget('group', groupId)) return true;
  const fallback = document.getElementById('board') || document.getElementById('nav-home');
  try { fallback?.focus({ preventScroll: true }); } catch { try { fallback?.focus(); } catch {} }
  return !!fallback;
}

function reportSelectedItemMutationUnavailable(opener) {
  toast(tr('selection.changed'), { danger: true, duration: 6000 });
  requestAnimationFrame(() => focusSelectedItemMutationOpener(opener));
  return false;
}
// Single source of truth: keep the derived flag, the body class, and the
// toolbar button's active state in lockstep. Previously these were mutated in
// several places independently, so deselecting the last item (or toggling the
// button) could leave the flag and the button visually out of sync.
function syncItemSelMode() {
  itemSelMode = explicitSelMode || selectedItemIds.size > 0;
  document.body.classList.toggle('item-sel-mode', itemSelMode);
  updateModeButtonState();
}
function toggleItemSelect(itemId) {
  if (isSelectedItemMutationPending()) return false;
  if (selectedItemIds.has(itemId)) selectedItemIds.delete(itemId);
  else selectedItemIds.add(itemId);
  // Keep the shift-range anchor on the clicked item, but drop it when the
  // selection is now empty — otherwise a later shift-click (while explicit
  // mode keeps the mode active) would span a range from a stale anchor.
  lastSelectedItemId = selectedItemIds.size ? itemId : null;
  syncItemSelMode();
  renderBoard();
  renderItemSelToolbar();
  return true;
}
function clearItemSelection() {
  if (isSelectedItemMutationPending()) return false;
  selectedItemIds.clear();
  explicitSelMode = false;
  lastSelectedItemId = null;
  syncItemSelMode();
  renderBoard();
  renderItemSelToolbar();
  return true;
}

function renderItemSelToolbar() {
  let bar = document.getElementById('item-sel-toolbar');
  if (!selectedItemIds.size) {
    if (bar) bar.remove();
    return;
  }
  if (!bar) {
    bar = document.createElement('div');
    bar.id = 'item-sel-toolbar';
    bar.setAttribute('role', 'toolbar');
    document.body.appendChild(bar);
  }
  bar.setAttribute('aria-label', tr('selection.toolbarLabel'));
  const count = selectedItemIds.size;
  const canOpenSavedTabs = getSelectedItemsInfo().some(info => (
    info.item?.type === 'tab' && isOpenableSavedTabUrl(info.item.url)
  ));
  bar.innerHTML = `
    <div class="isl-summary" aria-live="polite" aria-atomic="true">
      <span class="isl-count">${count}</span>
      <span class="isl-lbl">${esc(tr('selection.selected'))}</span>
    </div>
    <div class="isl-actions">
    <button type="button" data-act="open" title="${esc(tr(canOpenSavedTabs ? 'selection.openTitle' : 'selection.openUnavailable'))}"${canOpenSavedTabs ? '' : ' disabled aria-disabled="true"'}>
      <svg width="13" height="13" viewBox="0 0 12 12" fill="none"><path d="M4 2.5H2a1 1 0 00-1 1v6.5A1 1 0 002 11h6.5a1 1 0 001-1V8M7 1h4m0 0v4M11 1L5.5 6.5" stroke="currentColor" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round"/></svg>
      ${esc(tr('selection.open'))}
    </button>
    <button type="button" data-act="move" title="${esc(tr('selection.moveTitle'))}">
      <svg width="13" height="13" viewBox="0 0 12 12" fill="none"><path d="M6 2v8M2 6h8M4 4l-2 2 2 2M8 4l2 2-2 2" stroke="currentColor" stroke-width="1.3" stroke-linecap="round" stroke-linejoin="round"/></svg>
      ${esc(tr('selection.move'))}
    </button>
    <button type="button" data-act="stack" title="${esc(tr('selection.stackTitle'))}">
      <svg width="13" height="13" viewBox="0 0 12 12" fill="none"><path d="M2 3l4-2 4 2-4 2-4-2zM2 6l4 2 4-2M2 9l4 2 4-2" stroke="currentColor" stroke-width="1.3" stroke-linejoin="round"/></svg>
      ${esc(tr('selection.stack'))}
    </button>
    <button type="button" data-act="archive" title="${esc(tr('selection.archiveTitle'))}">
      <svg width="13" height="13" viewBox="0 0 12 12" fill="none"><rect x="1.5" y="2" width="9" height="2" stroke="currentColor" stroke-width="1.3"/><path d="M2.5 4v6h7V4M5 7h2" stroke="currentColor" stroke-width="1.3" stroke-linecap="round"/></svg>
      ${esc(tr('selection.archive'))}
    </button>
    <button type="button" data-act="clear" title="${esc(tr('selection.clearTitle'))}" aria-label="${esc(tr('selection.clearTitle'))}">
      <svg width="11" height="11" viewBox="0 0 10 10"><path d="M2 2l6 6M8 2l-6 6" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg>
    </button>`;
  bar.querySelectorAll('button').forEach(b => {
    b.onclick = event => runBatchAction(b.dataset.act, event.currentTarget);
  });
}

function getSelectedItemsInfo() {
  const out = [];
  for (const id of selectedItemIds) {
    const info = findItem(id);
    if (info) out.push(info);
  }
  return out;
}

async function runBatchAction(act, opener) {
  if (isSelectedItemMutationPending()) return false;
  if (act === 'clear') return clearItemSelection();
  if (act === 'stack') {
    openIdentityEditor('stack', 'batch-create', { itemIds: [...selectedItemIds] }, opener);
    return;
  }
  const infos = getSelectedItemsInfo();
  if (!infos.length) return reportSelectedItemMutationUnavailable(opener);
  if (act === 'open') {
    openSavedTabItems(infos.map(info => info.item), { opener });
    return true;
  }
  const review = createSelectedItemMutationContext([...selectedItemIds], { selectionOwned: true });
  if (!review) return reportSelectedItemMutationUnavailable(opener);
  if (act === 'archive') {
    return commitSelectedItemArchive(review, opener);
  }
  if (act === 'move') {
    // The Inbox and Space pages move through the filterable Space picker; the
    // commit is the same selection transaction.
    if ((typeof isInboxPageActive === 'function' && isInboxPageActive())
        || (typeof isSpacePageActive === 'function' && isSpacePageActive())) return openInboxBulkMovePicker(review, opener);
    return openMoveTargetPicker(review, opener);
  }
  return false;
}

function selectedItemArchiveFocusPlan(targets, selectedIds) {
  const first = targets[0];
  if (!first) return { itemId: null, groupId: null };
  const list = first.parentItems;
  for (let index = first.index + 1; index < list.length; index += 1) {
    if (!selectedIds.has(String(list[index]?.id))) return { itemId: list[index]?.id || null, groupId: first.group.id };
  }
  for (let index = first.index - 1; index >= 0; index -= 1) {
    if (!selectedIds.has(String(list[index]?.id))) return { itemId: list[index]?.id || null, groupId: first.group.id };
  }
  return { itemId: null, groupId: first.group.id };
}

function removeSelectedItemTargets(targets) {
  const byParent = new Map();
  for (const target of targets) {
    if (!byParent.has(target.parentItems)) byParent.set(target.parentItems, []);
    byParent.get(target.parentItems).push(target);
  }
  for (const entries of byParent.values()) {
    entries.sort((a, b) => b.index - a.index);
    for (const target of entries) {
      if (target.parentItems[target.index] !== target.item) throw new Error('Selected item changed before mutation');
      const [removed] = target.parentItems.splice(target.index, 1);
      if (removed !== target.item) throw new Error('Selected item removal was not exact');
    }
  }
}

async function commitSelectedItemArchive(review, opener = null, now = Date.now()) {
  if (!review || selectedItemMutationBlocked()) return false;
  const timestamp = Number(now);
  if (!Number.isFinite(timestamp) || timestamp <= 0) return false;
  const transaction = { kind: 'archive', review, opener };
  selectedItemMutationPending = transaction;
  if (!setSelectedItemMutationBusy('archive', opener, true)) {
    selectedItemMutationPending = null;
    return false;
  }
  const resolved = resolveSelectedItemMutationTargets(review);
  if (!resolved) {
    selectedItemMutationPending = null;
    setSelectedItemMutationBusy('archive', opener, false);
    return reportSelectedItemMutationUnavailable(opener);
  }
  const count = resolved.targets.length;
  const selectedIds = new Set(review.itemIds);
  const focusPlan = selectedItemArchiveFocusPlan(resolved.targets, selectedIds);
  let actionId = null;
  try {
    actionId = State.snapshot(tr(count === 1 ? 'selection.archiveHistoryOne' : 'selection.archiveHistoryMany', { count }));
    const entries = resolved.targets.map(target => ({
      kind: 'item',
      data: target.item,
      wsId: target.workspace.id,
      catId: target.space.id,
      groupId: target.group.id,
      catName: target.space.name,
      groupName: target.group.name,
      at: timestamp,
    }));
    removeSelectedItemTargets(resolved.targets);
    State.get().archive.unshift(...entries);
  } catch (error) {
    if (selectedItemMutationPending === transaction) selectedItemMutationPending = null;
    setSelectedItemMutationBusy('archive', opener, false);
    State.requireRecovery?.();
    if (typeof showStateRecoveryRequired === 'function') showStateRecoveryRequired(error);
    return false;
  }
  try {
    await State.persistNow();
  } catch (error) {
    if (selectedItemMutationPending === transaction) selectedItemMutationPending = null;
    setSelectedItemMutationBusy('archive', opener, false);
    if (State.isRecoveryRequired?.() && typeof showStateRecoveryRequired === 'function') showStateRecoveryRequired(error);
    return false;
  }
  if (selectedItemMutationPending !== transaction) {
    setSelectedItemMutationBusy('archive', opener, false);
    return false;
  }
  selectedItemMutationPending = null;
  setSelectedItemMutationBusy('archive', opener, false);
  if (review.selectionOwned) clearItemSelection();
  else renderBoard();
  renderArchiveList();
  requestAnimationFrame(() => focusSelectedItemMutationTarget(focusPlan.itemId, focusPlan.groupId));
  toast(tr(count === 1 ? 'selection.archivedOne' : 'selection.archivedMany', { count }), { undo: actionId });
  return true;
}

function selectedItemMoveDestinationTarget(review, destinationContext) {
  const resolved = resolveSelectedItemMutationTargets(review);
  const destination = resolveItemListCaptureTarget(destinationContext);
  if (!resolved || !destination) return null;
  const sourceLists = new Set(resolved.targets.map(target => target.parentItems));
  const selectedIds = new Set(review.itemIds);
  if (sourceLists.has(destination.list)
      || destination.stacks.some(stack => selectedIds.has(String(stack.id)))) return null;
  return { targets: resolved.targets, destination };
}

// `messageKey` lets a single-item surface (Item details) word its receipt.
async function commitSelectedItemMove(review, destinationContext, opener = null, { messageKey = '' } = {}) {
  if (!review || !destinationContext || selectedItemMutationBlocked()) return false;
  const transaction = { kind: 'move', review, destinationContext, opener };
  selectedItemMutationPending = transaction;
  if (!setSelectedItemMutationBusy('move', opener, true)) {
    selectedItemMutationPending = null;
    return false;
  }
  const resolved = selectedItemMoveDestinationTarget(review, destinationContext);
  if (!resolved) {
    selectedItemMutationPending = null;
    setSelectedItemMutationBusy('move', opener, false);
    return reportSelectedItemMutationUnavailable(opener);
  }
  const moved = resolved.targets.map(target => target.item);
  const count = moved.length;
  const destinationText = homeTrailPathText([
    ...homeTrailPathParts(resolved.destination.workspace, resolved.destination.space, homeTrailGroupName(resolved.destination.group)),
    ...resolved.destination.stacks.map(stack => String(stack.name || '').trim()).filter(Boolean),
  ]);
  let actionId = null;
  let receipt = null;
  try {
    actionId = State.snapshot(tr(count === 1 ? 'selection.moveHistoryOne' : 'selection.moveHistoryMany', { count }));
    removeSelectedItemTargets(resolved.targets);
    resolved.destination.list.push(...moved);
    receipt = createCaptureDestinationReceiptContext(destinationContext, moved);
    if (!receipt) throw new Error('Moved item destination receipt was not exact');
  } catch (error) {
    if (selectedItemMutationPending === transaction) selectedItemMutationPending = null;
    setSelectedItemMutationBusy('move', opener, false);
    State.requireRecovery?.();
    if (typeof showStateRecoveryRequired === 'function') showStateRecoveryRequired(error);
    return false;
  }
  try {
    await State.persistNow();
  } catch (error) {
    if (selectedItemMutationPending === transaction) selectedItemMutationPending = null;
    setSelectedItemMutationBusy('move', opener, false);
    if (State.isRecoveryRequired?.() && typeof showStateRecoveryRequired === 'function') showStateRecoveryRequired(error);
    return false;
  }
  if (selectedItemMutationPending !== transaction) {
    setSelectedItemMutationBusy('move', opener, false);
    return false;
  }
  selectedItemMutationPending = null;
  setSelectedItemMutationBusy('move', opener, false);
  if (review.selectionOwned) clearItemSelection();
  else renderBoard();
  requestAnimationFrame(() => focusSelectedItemMutationTarget(moved[0]?.id || null));
  if (resolveCaptureDestinationReceiptTarget(receipt)) {
    toast(tr(messageKey || (count === 1 ? 'selection.movedToOne' : 'selection.movedToMany'), {
      count,
      destination: destinationText,
    }), {
      undo: actionId,
      duration: 8000,
      actionLabel: tr('capture.openDestination'),
      action: () => openCaptureDestinationReceipt(receipt),
    });
  } else {
    toast(tr('selection.moveDestinationChanged'), { undo: actionId, tone: 'warning', duration: 8000 });
  }
  return true;
}

function openMoveTargetPicker(review, opener = document.activeElement) {
  const options = selectedItemMoveOptions(review);
  if (!options) return reportSelectedItemMutationUnavailable(opener);
  if (!options.length) {
    toast(tr('selection.noMoveDestination'), { danger: true, duration: 5000 });
    requestAnimationFrame(() => focusSelectedItemMutationOpener(opener));
    return false;
  }
  const count = review.itemIds.length;
  const items = [{ label: tr(count === 1 ? 'selection.movePickerOne' : 'selection.movePickerMany', { count }) }];
  options.forEach(option => {
    items.push({
      text: option.label,
      icon: option.destinationContext.stackIds.length ? cmIcons.stack : (cmIcons.folder || cmIcons.open),
      action: () => { void commitSelectedItemMove(review, option.destinationContext, opener); },
    });
  });
  // Anchor: above the multi-select toolbar if present; otherwise next to the
  // focused item card; otherwise centered near the top.
  let x, y;
  const bar = document.getElementById('item-sel-toolbar');
  if (bar) {
    const rect = bar.getBoundingClientRect();
    x = rect.left;
    y = Math.max(8, rect.top - 320);
  } else {
    const anchor = opener?.closest?.('.item') || opener;
    if (anchor && typeof anchor.getBoundingClientRect === 'function') {
      const rect = anchor.getBoundingClientRect();
      x = rect.right + 8;
      y = rect.top;
    } else {
      x = window.innerWidth / 2 - 150;
      y = 80;
    }
  }
  showContextMenu(x, y, items, { focusFirst: true });
  return true;
}

function attachItemDrag(el, it, parentItems, group) {
  el.addEventListener('dragstart', e => {
    e.stopPropagation();
    drag = { kind:'item', id: it.id, srcList: parentItems };
    el.classList.add('dragging');
    e.dataTransfer.effectAllowed = it.type === 'tab' && it.url ? 'copyMove' : 'move';
    try { e.dataTransfer.setData('text/plain', it.url || ''); } catch {}
  });
  el.addEventListener('dragend', () => {
    el.classList.remove('dragging');
    document.querySelectorAll('.dragover, .drop-target').forEach(x => { x.classList.remove('dragover'); x.classList.remove('drop-target'); });
    document.querySelectorAll('.drag-ghost').forEach(x => x.remove());
    drag = null;
  });
}

function makeGroupDropZone(cardsEl, colEl, g, targetList, stackDropPreview = null) {
  let lastOverY = 0;
  let lastGhostIdx = -1;

  function computeInsertIdx(clientY) {
    const children = [...cardsEl.querySelectorAll(':scope > .item:not(.dragging)')];
    for (let i = 0; i < children.length; i++) {
      const r = children[i].getBoundingClientRect();
      if (clientY < r.top + r.height / 2) return i;
    }
    return children.length;
  }

  function updateGhost(clientY) {
    const idx = computeInsertIdx(clientY);
    if (idx === lastGhostIdx) return;
    lastGhostIdx = idx;
    // Remove existing ghost only from THIS zone
    cardsEl.querySelectorAll(':scope > .drag-ghost').forEach(x => x.remove());
    const children = [...cardsEl.querySelectorAll(':scope > .item:not(.dragging)')];
    const ghost = document.createElement('div');
    ghost.className = 'drag-ghost';
    if (idx >= children.length) cardsEl.appendChild(ghost);
    else cardsEl.insertBefore(ghost, children[idx]);
  }

  cardsEl.addEventListener('dragover', e => {
    if (!drag) return;
    e.preventDefault();
    e.stopPropagation();
    e.dataTransfer.dropEffect = 'move';
    cardsEl.classList.add('dragover');
    if (colEl) colEl.classList.add('drop-target');
    // Throttle - only update when Y changed by >4px
    if (Math.abs(e.clientY - lastOverY) < 4) return;
    lastOverY = e.clientY;
    updateGhost(e.clientY);
  });

  cardsEl.addEventListener('dragleave', e => {
    // Only clear if we truly left this zone (not entered a child)
    if (cardsEl.contains(e.relatedTarget)) return;
    cardsEl.classList.remove('dragover');
    if (colEl) colEl.classList.remove('drop-target');
    cardsEl.querySelectorAll(':scope > .drag-ghost').forEach(x => x.remove());
    lastGhostIdx = -1;
  });

  cardsEl.addEventListener('drop', async e => {
    if (!drag) return;
    e.preventDefault();
    e.stopPropagation();
    cardsEl.classList.remove('dragover');
    if (colEl) colEl.classList.remove('drop-target');

    const insertIdx = computeInsertIdx(e.clientY);
    cardsEl.querySelectorAll(':scope > .drag-ghost').forEach(x => x.remove());
    lastGhostIdx = -1;
    stackDropPreview?.clear();

    if (drag.kind === 'tab') {
      await handleTabDropIntoList(drag.data, targetList, insertIdx, {
        afterSnapshot: stackDropPreview ? () => stackDropPreview.commit() : null,
      });
    } else if (drag.kind === 'tabs-multi') {
      await handleTabDropIntoList(drag.data, targetList, insertIdx, {
        afterSnapshot: stackDropPreview ? () => stackDropPreview.commit() : null,
      });
    } else if (drag.kind === 'item') {
      const info = findItem(drag.id);
      if (!info) return;
      // Prevent dropping a stack into itself or its descendants
      if (info.item.type === 'stack' && isDescendantOf(targetList, info.item)) {
        toast(tr('feedback.stackSelf'), { danger: true });
        return;
      }
      State.snapshot('Move item');
      stackDropPreview?.commit();
      const srcList = info.parent;
      const srcIdx = info.index;
      const [moved] = srcList.splice(srcIdx, 1);
      let ii = insertIdx;
      if (srcList === targetList && ii > srcIdx) ii--;
      if (ii >= targetList.length) targetList.push(moved);
      else targetList.splice(ii, 0, moved);
      State.persist(); renderBoard();
    }
  });
}

// Returns true if `list` is *inside* stackItem (i.e. dropping into it would
// create a cycle). When walking, skip stackItem itself - finding stackItem
// in its own parent list means the user is reordering it within its parent,
// which is allowed.
function isDescendantOf(list, stackItem) {
  if (list === stackItem.items) return true;
  for (const it of list) {
    if (it === stackItem) continue;  // skip the dragged stack itself
    if (it.type === 'stack' && it.items && isDescendantOf(it.items, stackItem)) return true;
  }
  return false;
}

async function handleTabDropIntoList(tabValue, list, insertIdx, { afterSnapshot = null } = {}) {
  const candidateTabs = captureEligibleTabs(Array.isArray(tabValue) ? tabValue : [tabValue]);
  if (!candidateTabs.length || State.isRecoveryRequired()) return false;
  if (captureCommitPending || saveAllTabsPending) {
    toast(tr('capture.pending'), { danger: true, duration: 5000 });
    return false;
  }
  const destination = createItemListCaptureContext(list);
  let target = resolveItemListCaptureTarget(destination);
  if (!target) {
    toast(tr('capture.dropDestinationUnavailable'), { danger: true, duration: 5000 });
    return false;
  }
  const sourcePairs = candidateTabs.map(tab => ({ tab, source: capturedTabSourceDescriptor(tab) }));
  if (sourcePairs.some(pair => !pair.source)) return false;
  const acceptBatchSource = createCaptureBatchDuplicateFilter(target.list);
  const savedPairs = sourcePairs.filter(pair => acceptBatchSource(pair.source));
  if (!savedPairs.length) {
    toast(tr('capture.alreadySaved'), { danger: true });
    return false;
  }
  let savedItems;
  try {
    const allocateId = createOrganizationIdAllocator();
    savedItems = savedPairs.map(({ source }) => {
      const meta = captureTabFields(source);
      return stampNew({
        id: allocateId(),
        type: 'tab',
        title: meta.title,
        url: source.url,
        fav: meta.fav,
      });
    });
  } catch {
    toast(tr('capture.dropDestinationUnavailable'), { danger: true, duration: 5000 });
    return false;
  }
  const snapshotKey = target.stack
    ? (savedItems.length === 1 ? 'capture.snapshotStackTab' : 'capture.snapshotStackTabs')
    : (savedItems.length === 1 ? 'capture.snapshotGroupTab' : 'capture.snapshotGroupTabs');
  const actionId = State.snapshot(tr(snapshotKey, { count: savedItems.length }));
  try { afterSnapshot?.(); } catch {
    State.rollbackSnapshot(actionId);
    renderAll();
    toast(tr('capture.dropDestinationUnavailable'), { danger: true, duration: 5000 });
    return false;
  }
  target = resolveItemListCaptureTarget(destination);
  if (!target) {
    State.rollbackSnapshot(actionId);
    renderAll();
    toast(tr('capture.dropDestinationUnavailable'), { danger: true, duration: 5000 });
    return false;
  }
  let index = Number.isInteger(insertIdx)
    ? Math.max(0, Math.min(insertIdx, target.list.length))
    : target.list.length;
  for (const item of savedItems) target.list.splice(index++, 0, item);
  const closeSources = State.get().settings.closeTabOnSave;
  const receiptContext = createCaptureDestinationReceiptContext(destination, savedItems);
  const receiptTarget = resolveItemListCaptureTarget(destination);
  const receiptMessage = captureDestinationReceiptMessage(receiptTarget, {
    count: savedItems.length,
    closeSources: !!closeSources,
  });
  if (!receiptContext || !receiptMessage) {
    State.rollbackSnapshot(actionId);
    renderAll();
    toast(tr('capture.dropDestinationUnavailable'), { danger: true, duration: 5000 });
    return false;
  }
  const result = await commitCapturedTabs(savedPairs.map(pair => pair.source), {
    actionId,
    refreshSources: true,
    closeSources,
    validateDestination: () => !!resolveCaptureDestinationReceiptTarget(receiptContext),
  });
  if (!result) return false;
  clearCapturedTabSelection(candidateTabs);
  renderBoard();
  renderOpenTabs();
  updateSelectedBadge();
  restoreOpenTabCaptureFocus();
  toastCaptureDestinationReceipt(receiptContext, receiptMessage, result);
  return result;
}
async function handleTabDropIntoGroup(tabObj, group) {
  return handleTabDropIntoList(tabObj, group.items);
}

// ════════════════════════════════════════════════════════════════
// RICH TEXT TOOLBAR
// ════════════════════════════════════════════════════════════════
let richTextLinkContext = null;
const RICH_TEXT_LINK_CONFLICTING_IDS = [
  'state-recovery-overlay',
  'paste-overlay',
  'reminder-overlay',
  'calendar-task-overlay',
  'modal-overlay',
  'import-overlay',
  'ws-grid-overlay',
  'organization-name-overlay',
  'organization-delete-overlay',
  'trash-delete-overlay',
  'settings-drawer',
  'cmd-palette',
  'emoji-picker',
];

function richTextEditorForNode(node) {
  if (!node) return null;
  const element = node.nodeType === 1 ? node : node.parentElement;
  return element?.closest?.('.note-text') || null;
}

function richTextLinkNodeWithinEditor(editor, node) {
  return !!(editor && node && (node === editor || editor.contains?.(node)));
}

function captureRichTextLinkSelection() {
  const selection = window.getSelection?.();
  if (!selection || selection.rangeCount !== 1 || selection.isCollapsed) return null;
  const sourceRange = selection.getRangeAt(0);
  if (!sourceRange || sourceRange.collapsed) return null;
  const startEditor = richTextEditorForNode(sourceRange.startContainer);
  const endEditor = richTextEditorForNode(sourceRange.endContainer);
  if (!startEditor || startEditor !== endEditor) return null;
  if (startEditor.isConnected !== true || startEditor.isContentEditable !== true) return null;
  if (!richTextLinkNodeWithinEditor(startEditor, sourceRange.startContainer)
    || !richTextLinkNodeWithinEditor(startEditor, sourceRange.endContainer)) return null;
  const selectedText = sourceRange.toString();
  if (!selectedText || !selectedText.trim()) return null;
  const range = sourceRange.cloneRange();
  return {
    editor: startEditor,
    range,
    html: startEditor.innerHTML,
    selectedText,
    startContainer: range.startContainer,
    startOffset: range.startOffset,
    endContainer: range.endContainer,
    endOffset: range.endOffset,
    errorKey: null,
  };
}

function richTextLinkContextStillMatches(context) {
  if (!context?.editor || !context.range) return false;
  const { editor, range } = context;
  if (editor.isConnected !== true || editor.isContentEditable !== true) return false;
  if (!editor.classList?.contains('note-text') || editor.innerHTML !== context.html) return false;
  if (range.collapsed
    || range.startContainer !== context.startContainer
    || range.startOffset !== context.startOffset
    || range.endContainer !== context.endContainer
    || range.endOffset !== context.endOffset) return false;
  if (!richTextLinkNodeWithinEditor(editor, range.startContainer)
    || !richTextLinkNodeWithinEditor(editor, range.endContainer)) return false;
  try {
    return range.toString() === context.selectedText;
  } catch {
    return false;
  }
}

function normalizeRichTextLinkUrl(value) {
  const candidate = String(value ?? '').trim();
  if (!/^https?:\/\//i.test(candidate) || /\s/.test(candidate)) return null;
  try {
    const parsed = new URL(candidate);
    if ((parsed.protocol !== 'http:' && parsed.protocol !== 'https:') || !parsed.hostname) return null;
    return parsed.href;
  } catch {
    return null;
  }
}

function isRichTextLinkEditorOwned(editor) {
  const overlay = document.getElementById('rich-text-link-overlay');
  return !!(editor
    && richTextLinkContext?.editor === editor
    && overlay
    && !overlay.classList.contains('hidden'));
}

function setRichTextLinkInterlock(enabled) {
  const overlay = document.getElementById('rich-text-link-overlay');
  const recovery = document.getElementById('state-recovery-overlay');
  for (const child of document.body.children) {
    if (child === overlay || child === recovery) continue;
    setElementInertOwner(child, 'rich-text-link', enabled);
  }
}

function focusRichTextLinkInput() {
  const input = document.getElementById('rich-text-link-input');
  try { input?.focus({ preventScroll: true }); } catch { try { input?.focus(); } catch {} }
}

function paintRichTextLinkDialog() {
  const input = document.getElementById('rich-text-link-input');
  const selection = document.getElementById('rich-text-link-selection');
  const error = document.getElementById('rich-text-link-error');
  if (selection) selection.textContent = richTextLinkContext?.selectedText || '';
  const errorKey = richTextLinkContext?.errorKey || null;
  if (error) error.textContent = errorKey ? tr(errorKey) : '';
  if (input) input.setAttribute('aria-invalid', String(!!errorKey));
}

function setRichTextLinkError(errorKey) {
  if (!richTextLinkContext) return false;
  richTextLinkContext.errorKey = errorKey;
  paintRichTextLinkDialog();
  // The address field shakes once per rejected address.
  const field = document.getElementById('rich-text-link-input');
  if (errorKey && field?.classList) {
    field.classList.remove('is-shake');
    void field.offsetWidth;
    field.classList.add('is-shake');
  }
  const recovery = document.getElementById('state-recovery-overlay');
  if (!recovery || recovery.classList.contains('hidden')) requestAnimationFrame(focusRichTextLinkInput);
  return false;
}

function restoreRichTextLinkSelection(context) {
  if (!richTextLinkContextStillMatches(context)) return false;
  try {
    context.editor.focus({ preventScroll: true });
  } catch {
    try { context.editor.focus(); } catch { return false; }
  }
  if (document.activeElement !== context.editor) return false;
  try {
    const selection = window.getSelection();
    selection.removeAllRanges();
    selection.addRange(context.range);
    return selection.rangeCount === 1
      && selection.getRangeAt(0).startContainer === context.startContainer
      && selection.getRangeAt(0).startOffset === context.startOffset
      && selection.getRangeAt(0).endContainer === context.endContainer
      && selection.getRangeAt(0).endOffset === context.endOffset;
  } catch {
    return false;
  }
}

function closeRichTextLinkDialog({ restoreSelection = true } = {}) {
  const overlay = document.getElementById('rich-text-link-overlay');
  if (!overlay || overlay.classList.contains('hidden')) return false;
  const context = richTextLinkContext;
  overlay.classList.add('hidden');
  unlockBodyScroll();
  setRichTextLinkInterlock(false);
  richTextLinkContext = null;
  const restored = restoreSelection && restoreRichTextLinkSelection(context);
  if (restored) _overlayOpeners.delete(overlay);
  else restoreOpener(overlay);
  return true;
}

function richTextLinkHasConflict() {
  return RICH_TEXT_LINK_CONFLICTING_IDS.some(id => {
    const element = document.getElementById(id);
    return element && !element.classList.contains('hidden');
  });
}

function openRichTextLinkDialog() {
  const overlay = document.getElementById('rich-text-link-overlay');
  if (!overlay || !overlay.classList.contains('hidden') || richTextLinkContext || richTextLinkHasConflict()) return false;
  const context = captureRichTextLinkSelection();
  if (!context) return false;
  const input = document.getElementById('rich-text-link-input');
  richTextLinkContext = context;
  rememberOpener(overlay, context.editor);
  input.value = 'https://';
  input.setAttribute('aria-invalid', 'false');
  document.getElementById('rt-toolbar')?.classList.add('hidden');
  setRichTextLinkInterlock(true);
  overlay.classList.remove('hidden');
  lockBodyScroll();
  paintRichTextLinkDialog();
  requestAnimationFrame(() => {
    focusRichTextLinkInput();
    try { input.setSelectionRange(input.value.length, input.value.length); } catch {}
  });
  return true;
}

function finishRichTextLinkSuccess(context) {
  const overlay = document.getElementById('rich-text-link-overlay');
  overlay?.classList.add('hidden');
  unlockBodyScroll();
  setRichTextLinkInterlock(false);
  richTextLinkContext = null;
  if (overlay) _overlayOpeners.delete(overlay);
  try { context.editor.focus({ preventScroll: true }); } catch { try { context.editor.focus(); } catch {} }
}

function applyRichTextLink() {
  const context = richTextLinkContext;
  if (!context || !richTextLinkContextStillMatches(context)) {
    return setRichTextLinkError('richText.selectionChanged');
  }
  const input = document.getElementById('rich-text-link-input');
  const normalizedUrl = normalizeRichTextLinkUrl(input?.value);
  if (!normalizedUrl) return setRichTextLinkError('richText.invalidUrl');

  // The exact editor is inert while the dialog owns focus. Release only this
  // dialog's owner for the synchronous selection restore and command, then
  // either finish or re-establish the interlock before yielding.
  setRichTextLinkInterlock(false);
  if (!restoreRichTextLinkSelection(context)) {
    setRichTextLinkInterlock(true);
    return setRichTextLinkError('richText.selectionChanged');
  }

  let applied = false;
  try {
    applied = document.execCommand('createLink', false, normalizedUrl) === true;
    if (applied) context.editor.dispatchEvent(new Event('input', { bubbles: true }));
  } catch {
    applied = false;
  }
  if (!applied) {
    if (context.editor.isConnected === true && context.editor.innerHTML !== context.html) {
      context.editor.innerHTML = context.html;
    }
    setRichTextLinkInterlock(true);
    return setRichTextLinkError('richText.applyFailed');
  }

  finishRichTextLinkSuccess(context);
  return true;
}

function handleRichTextLinkGlobalKey(event) {
  const overlay = document.getElementById('rich-text-link-overlay');
  if (!overlay || overlay.classList.contains('hidden')) return false;
  const recovery = document.getElementById('state-recovery-overlay');
  if (recovery && !recovery.classList.contains('hidden') && recovery.contains(event.target)) return false;
  if (overlay.contains(event.target)) return true;
  event.preventDefault();
  event.stopImmediatePropagation();
  if (event.key === 'Escape') closeRichTextLinkDialog();
  else focusRichTextLinkInput();
  return true;
}

function bindRichTextLinkDialog() {
  const overlay = document.getElementById('rich-text-link-overlay');
  if (!overlay || overlay.dataset.bound === '1') return;
  overlay.dataset.bound = '1';
  const input = document.getElementById('rich-text-link-input');
  const close = () => closeRichTextLinkDialog();
  document.getElementById('rich-text-link-close').onclick = close;
  document.getElementById('rich-text-link-cancel').onclick = close;
  document.getElementById('rich-text-link-form').addEventListener('submit', event => {
    event.preventDefault();
    applyRichTextLink();
  });
  input.addEventListener('input', () => {
    if (!richTextLinkContext) return;
    richTextLinkContext.errorKey = null;
    paintRichTextLinkDialog();
  });
  overlay.addEventListener('click', event => {
    if (event.target === overlay) closeRichTextLinkDialog();
  });
  overlay.addEventListener('keydown', event => {
    if (event.key === 'Escape') {
      event.preventDefault();
      event.stopPropagation();
      closeRichTextLinkDialog();
      return;
    }
    if (event.key === 'Tab') trapTabKey(event, overlay);
    event.stopPropagation();
  });
}

function maybeShowRtToolbar() {
  const tb = document.getElementById('rt-toolbar');
  if (richTextLinkContext) { tb.classList.add('hidden'); return; }
  const context = captureRichTextLinkSelection();
  if (!context) { tb.classList.add('hidden'); return; }
  const rect = context.range.getBoundingClientRect();
  tb.classList.remove('hidden');
  let top = rect.top - tb.offsetHeight - 8;
  let left = rect.left + rect.width / 2 - tb.offsetWidth / 2;
  if (top < 10) top = rect.bottom + 8;
  if (left < 10) left = 10;
  if (left + tb.offsetWidth > window.innerWidth - 10) left = window.innerWidth - tb.offsetWidth - 10;
  tb.style.top = top + 'px';
  tb.style.left = left + 'px';
}

function rtCreateLink() {
  return openRichTextLinkDialog();
}

function bindRtToolbar() {
  const tb = document.getElementById('rt-toolbar');
  tb.querySelectorAll('button').forEach(b => {
    b.onmousedown = e => e.preventDefault(); // preserve selection
    b.onclick = e => {
      e.preventDefault();
      const cmd = b.dataset.cmd;
      if (cmd === 'bold') document.execCommand('bold');
      else if (cmd === 'italic') document.execCommand('italic');
      else if (cmd === 'underline') document.execCommand('underline');
      else if (cmd === 'strike') document.execCommand('strikeThrough');
      else if (cmd === 'h') document.execCommand('formatBlock', false, '<h3>');
      else if (cmd === 'ul') document.execCommand('insertUnorderedList');
      else if (cmd === 'link') rtCreateLink();
      else if (cmd === 'color-red') document.execCommand('foreColor', false, '#ef4444');
      else if (cmd === 'color-green') document.execCommand('foreColor', false, '#22c55e');
      else if (cmd === 'color-yellow') document.execCommand('foreColor', false, '#eab308');
      else if (cmd === 'color-clear') document.execCommand('removeFormat');
    };
  });
  document.addEventListener('selectionchange', debounce(maybeShowRtToolbar, 50));
  const rtToolbarTick = rafThrottle(maybeShowRtToolbar);
  document.addEventListener('mouseup', rtToolbarTick);
  document.addEventListener('keyup', rtToolbarTick);
  document.addEventListener('keydown', event => {
    if ((!event.ctrlKey && !event.metaKey)
      || event.altKey
      || event.shiftKey
      || event.key.toLowerCase() !== 'k') return;
    const editor = event.target?.closest?.('.note-text');
    if (!editor || editor.isContentEditable !== true) return;
    event.preventDefault();
    rtCreateLink();
  });
}

// ════════════════════════════════════════════════════════════════
// SEARCH
// ════════════════════════════════════════════════════════════════
const SEARCH_COLORS = ['red','orange','yellow','green','blue'];
// type: operator vocabulary → canonical item type (singular/plural + synonyms).
const SEARCH_TYPES = {
  tab:'tab', tabs:'tab', link:'tab', links:'tab',
  note:'note', notes:'note',
  todo:'todo', todos:'todo', task:'todo', tasks:'todo',
  stack:'stack', stacks:'stack', group:'stack', groups:'stack',
};
// Canonical DOM type of an item node (mirrors the build* classNames).
function itemNodeType(el) {
  const c = el.classList;
  if (c.contains('stack')) return 'stack';
  if (c.contains('todo')) return 'todo';
  if (c.contains('note')) return 'note';
  if (c.contains('tab')) return 'tab';
  return '';
}

// Shared parser for board filtering and the launch layer's saved-link search.
// Keeping the vocabulary in one place prevents the two search entry points
// from drifting as operators are added.
function parseSearchQuery(rawValue) {
  const raw = String(rawValue || '').toLowerCase().trim();
  const makeBucket = () => ({ color: [], type: [], state: [], domain: [], url: [], in: [], tag: [], text: [] });
  const pos = makeBucket(), neg = makeBucket();
  (raw.match(/-?"[^"]*"|\S+/g) || []).forEach(token => {
    let tok = token;
    let bucket = pos;
    if (tok[0] === '-' && tok.length > 1) { bucket = neg; tok = tok.slice(1); }
    if (tok.length > 1 && tok[0] === '"' && tok[tok.length - 1] === '"') {
      const phrase = tok.slice(1, -1).trim();
      if (phrase) bucket.text.push(phrase);
      return;
    }
    let m;
    if ((m = /^colou?r:(.+)$/.exec(tok))) {
      m[1].split(',').forEach(c => { if (SEARCH_COLORS.includes(c)) bucket.color.push(c); });
    } else if ((m = /^type:(.+)$/.exec(tok))) {
      m[1].split(',').forEach(t => { const ct = SEARCH_TYPES[t]; if (ct && !bucket.type.includes(ct)) bucket.type.push(ct); });
    } else if ((m = /^is:(.+)$/.exec(tok))) {
      m[1].split(',').forEach(s => {
        if (s === 'done' || s === 'checked' || s === 'complete') bucket.state.push('done');
        else if (s === 'open' || s === 'undone' || s === 'todo' || s === 'incomplete') bucket.state.push('open');
      });
    } else if ((m = /^(?:domain|site|host):(.+)$/.exec(tok))) {
      m[1].split(',').forEach(d => { const value = d.trim(); if (value) bucket.domain.push(value); });
    } else if ((m = /^url:(.+)$/.exec(tok))) {
      m[1].split(',').forEach(u => { const value = u.trim(); if (value) bucket.url.push(value); });
    } else if ((m = /^in:(.+)$/.exec(tok))) {
      m[1].split(',').forEach(g => { const value = g.trim(); if (value) bucket.in.push(value); });
    } else if ((m = /^tag:(.+)$/.exec(tok))) {
      m[1].split(',').forEach(t => { const value = t.trim(); if (value) bucket.tag.push(value); });
    } else {
      bucket.text.push(tok);
    }
  });
  return { raw, pos, neg };
}

function applySearchFilter() {
  const raw = document.getElementById('search-input').value.toLowerCase().trim();
  // Clear any stack we force-opened on a previous keystroke; the reveal pass below
  // re-adds it only for stacks that still contain a match (so cleared/changed queries
  // restore the user's real collapse state).
  document.querySelectorAll('.search-expand').forEach(n => n.classList.remove('search-expand'));
  // Tokenize honoring "quoted phrases" BEFORE pulling operators, so a quoted phrase
  // survives intact next to an operator (e.g. type:todo "due today"). Structured
  // operators (the plan's borrowed-from-Refern search operators):
  //   color:red[,blue]   — filter by item color
  //   type:tab[,note]    — filter by item kind (tab/note/todo/stack, plus synonyms)
  //   is:done | is:open  — filter todos by completion state
  //   domain:host[,host] — filter tabs by hostname substring (alias site:)
  //   url:frag[,frag]    — filter tabs by full-URL substring
  //   in:name[,name]     — filter by the name of a containing group/stack (scope)
  //   -<term>            — negate any operator or word: EXCLUDE items it matches
  //                        (e.g. -type:todo, -domain:github.com, -"in progress")
  // Everything else (bare words and quoted phrases) becomes a text needle that must
  // appear as a substring; a quoted phrase is one needle so its spaces match verbatim.
  // Each token routes into a positive (must-match, AND across families) or a negative
  // (must-NOT-match, hide if ANY negative family matches) bucket with identical shape.
  const { pos, neg } = parseSearchQuery(raw);
  // Positive filters keep their original names so the match logic below is unchanged.
  const colorFilters = pos.color, typeFilters = pos.type, stateFilters = pos.state,
        domainFilters = pos.domain, urlFilters = pos.url, inFilters = pos.in, tagFilters = pos.tag, textNeedles = pos.text;
  const hasColor = colorFilters.length > 0;
  const hasType = typeFilters.length > 0;
  const hasState = stateFilters.length > 0;
  const hasDomain = domainFilters.length > 0;
  const hasUrl = urlFilters.length > 0;
  const hasIn = inFilters.length > 0;
  const hasTag = tagFilters.length > 0;
  const hasText = textNeedles.length > 0;
  const hasNeg = neg.color.length || neg.type.length || neg.state.length ||
                 neg.domain.length || neg.url.length || neg.in.length || neg.tag.length || neg.text.length;
  // Names of every group/stack a node is nested inside (board + list structures),
  // lowercased — powers the in:<name> scope operator. Walks ancestors only (a node isn't
  // "in" itself): board group names live in .gcol-name, board stack names in .stack-name,
  // list group names in .lv-group-name, list stack names in .lv-stack-name.
  const containerNamesOf = node => {
    const names = [];
    const add = v => { if (v) names.push(v.toLowerCase()); };
    let bs = node.parentElement?.closest('.item.stack');
    while (bs) { add(bs.querySelector(':scope > .stack-hd > .stack-name')?.textContent); bs = bs.parentElement?.closest('.item.stack'); }
    add(node.closest('.gcol')?.querySelector(':scope > .gcol-hd .gcol-name')?.textContent);
    add(node.closest('.spc-col')?.querySelector(':scope > .spc-gh .spc-gname')?.textContent);
    let ls = node.parentElement?.closest('.lv-stack');
    while (ls) { add(ls.querySelector(':scope > .lv-stack-hd > .lv-stack-name')?.textContent); ls = ls.parentElement?.closest('.lv-stack'); }
    add(node.closest('.lv-group')?.querySelector(':scope > .lv-group-hd .lv-group-name')?.textContent);
    return names;
  };
  const matchIn = (filters, node) => { const ns = containerNamesOf(node); return filters.some(f => ns.some(n => n.includes(f))); };
  // Tags are exposed on each node as a comma-joined, lowercased dataset.tags blob
  // (see the item builders). tag:<x> matches when any of the node's tags contains
  // <x> as a substring — same substring semantics as in:/domain:.
  const tagsOf = node => (node.dataset.tags ? node.dataset.tags.split(',').filter(Boolean) : []);
  const matchTag = (filters, node) => { const ts = tagsOf(node); return filters.some(f => ts.some(t => t.includes(f))); };
  // Lowercased text to match an element against. For a board/canvas stack, use ONLY its own
  // header/name — not descendant cards, which surface on their own as .item matches and
  // reveal their parent. This keeps results consistent with list view (which evaluates
  // just .lv-stack-hd) and avoids type:stack false positives.
  const elemText = el => {
    const hd = el.querySelector(':scope > .stack-hd');
    const t = hd ? hd.textContent : el.textContent;
    return t.toLowerCase();
  };
  const matchText = el => { const t = elemText(el); return textNeedles.every(n => t.includes(n)); };
  // Per-family matchers reused for negation. A todo's completion state, a tab's host/url,
  // and a container scope are the only ones that can ever be true for the relevant kinds;
  // for any other kind they're false, so e.g. -domain:x leaves notes/todos/stacks visible.
  const mState = el => { const isTodo = el.classList.contains('todo'); const done = isTodo && el.classList.contains('done'); return f => isTodo && (f === 'done' ? done : !done); };
  // An .item node is EXCLUDED if it matches any active negative family.
  const excludedItem = el => (
    (neg.color.length && neg.color.includes(el.dataset.color)) ||
    (neg.type.length && neg.type.includes(itemNodeType(el))) ||
    (neg.state.length && neg.state.some(mState(el))) ||
    (neg.domain.length && !!el.dataset.host && neg.domain.some(d => el.dataset.host.includes(d))) ||
    (neg.url.length && !!el.dataset.url && neg.url.some(u => el.dataset.url.includes(u))) ||
    (neg.in.length && matchIn(neg.in, el)) ||
    (neg.tag.length && matchTag(neg.tag, el)) ||
    (neg.text.length && (t => neg.text.some(n => t.includes(n)))(elemText(el)))
  );
  // A list-view stack header is EXCLUDED similarly. A stack has no completion state, host,
  // or URL, so -is:/-domain:/-url: never exclude it; type is hardcoded 'stack' as elsewhere.
  const excludedStack = (st, hd) => (
    (neg.color.length && neg.color.includes(st.dataset.color)) ||
    (neg.type.length && neg.type.includes('stack')) ||
    (neg.in.length && matchIn(neg.in, st)) ||
    (neg.tag.length && matchTag(neg.tag, st)) ||
    (neg.text.length && (t => neg.text.some(n => t.includes(n)))(elemText(hd)))
  );
  getItemNodes().forEach(el => {
    if (!raw) { el.classList.remove('hidden'); return; }
    let match = true;
    if (hasColor) match = colorFilters.includes(el.dataset.color);
    if (match && hasType) match = typeFilters.includes(itemNodeType(el));
    if (match && hasState) {
      // Completion state only applies to todos; non-todos can't satisfy is:done/is:open.
      const isTodo = el.classList.contains('todo');
      const done = isTodo && el.classList.contains('done');
      match = stateFilters.some(s => isTodo && (s === 'done' ? done : !done));
    }
    // domain:/url: only apply to tabs (the only items with a URL); other kinds can't satisfy them.
    if (match && hasDomain) { const h = el.dataset.host || ''; match = !!h && domainFilters.some(d => h.includes(d)); }
    if (match && hasUrl) { const u = el.dataset.url || ''; match = !!u && urlFilters.some(f => u.includes(f)); }
    if (match && hasIn) match = matchIn(inFilters, el);
    if (match && hasTag) match = matchTag(tagFilters, el);
    if (match && hasText) match = matchText(el);
    if (match && hasNeg) match = !excludedItem(el);
    el.classList.toggle('hidden', !match);
  });
  // List view renders stacks as .lv-stack / .lv-stack-hd, not .item.stack, so the loop
  // above never evaluates them. Filter the stack header here (its own children are
  // independent .item nodes handled above; header & children are siblings, so a hidden
  // header doesn't hide a matching child the way a board .item.stack ancestor would).
  document.querySelectorAll('.lv-stack').forEach(st => {
    const hd = st.querySelector(':scope > .lv-stack-hd');
    if (!hd) return;
    if (!raw) { hd.classList.remove('hidden'); return; }
    let match = true;
    if (hasColor) match = colorFilters.includes(st.dataset.color);
    if (match && hasType) match = typeFilters.includes('stack');
    if (match && hasState) match = false; // a stack has no completion state
    if (match && (hasDomain || hasUrl)) match = false; // a stack has no URL
    if (match && hasIn) match = matchIn(inFilters, st); // scope by the stack's ancestor groups/stacks
    if (match && hasTag) match = matchTag(tagFilters, st);
    if (match && hasText) match = matchText(hd);
    if (match && hasNeg) match = !excludedStack(st, hd);
    hd.classList.toggle('hidden', !match);
  });
  // Reveal the ancestor stacks of every visible match so it's actually shown, even when
  // an ancestor didn't match or is collapsed. Matches live on two kinds of node: board/
  // list .item nodes AND list-view .lv-stack-hd headers (a nested stack whose own name
  // matches, e.g. type:stack alpha) — headers aren't .item nodes, so walk both sets.
  if (raw) {
    const revealAncestors = node => {
      // Board: the .item.stack wraps its children — unhide it and force it open
      // (collapsed stacks clip children to max-height:0 via CSS).
      let bp = node.parentElement?.closest('.item.stack');
      while (bp) { bp.classList.remove('hidden'); bp.classList.add('search-expand'); bp = bp.parentElement?.closest('.item.stack'); }
      // List view: open each ancestor .lv-stack and keep its header visible so the whole
      // path down to the match is shown (header & children are siblings inside .lv-stack).
      let lp = node.closest('.lv-stack');
      while (lp) {
        lp.classList.add('search-expand');
        lp.querySelector(':scope > .lv-stack-hd')?.classList.remove('hidden');
        lp = lp.parentElement?.closest('.lv-stack');
      }
    };
    getItemNodes().forEach(el => { if (!el.classList.contains('hidden')) revealAncestors(el); });
    document.querySelectorAll('.lv-stack-hd:not(.hidden)').forEach(revealAncestors);
  }
  document.querySelectorAll('.gcol, .spc-col').forEach(col => {
    const any = col.querySelectorAll('.item:not(.hidden)').length > 0;
    col.style.display = (!raw || any) ? '' : 'none';
  });
  // Gallery (§3.3) groups its masonry into .gl-section blocks (not .gcol); collapse
  // any whose cards are all filtered out so a query doesn't leave empty headers.
  document.querySelectorAll('.gl-section').forEach(sec => {
    const any = sec.querySelectorAll('.item:not(.hidden)').length > 0;
    sec.style.display = (!raw || any) ? '' : 'none';
  });
  // Archive matches on text only. Structured operators (color/type/is) can't be applied
  // faithfully to heterogeneous archive entries — especially whole-group entries — so when
  // any operator is active, suppress archive results rather than surface false positives
  // (e.g. type:todo urgent must not list archived notes/tabs/groups containing "urgent").
  // Negative structured operators count as ops too (can't be faithfully applied to
  // heterogeneous archive entries); negative TEXT needles, though, just exclude matching
  // entries, so they're passed through to filter the archive result list.
  const hasNegOps = neg.color.length || neg.type.length || neg.state.length ||
                    neg.domain.length || neg.url.length || neg.in.length || neg.tag.length;
  const hasOps = hasColor || hasType || hasState || hasDomain || hasUrl || hasIn || hasTag || hasNegOps;
  renderArchiveSearchResults(hasText && !hasOps ? textNeedles : null, neg.text);
}
// Build a normalized search blob for an archive entry (group or item).
// Memoized in a WeakMap so we don't strip HTML on every keystroke.
const _archiveBlobCache = new WeakMap();
function archiveEntryText(entry) {
  const cached = _archiveBlobCache.get(entry);
  if (cached !== undefined) return cached;
  const parts = [];
  if (entry.catName) parts.push(entry.catName);
  if (entry.groupName) parts.push(entry.groupName);
  const pushItem = it => {
    if (!it) return;
    if (it.title) parts.push(it.title);
    if (it.url) parts.push(it.url);
    if (it.text) parts.push(it.text);
    if (it.html) parts.push(it.html.replace(/<[^>]+>/g, ' '));
    if (it.name) parts.push(it.name);
    if (it.type === 'stack' && Array.isArray(it.items)) it.items.forEach(pushItem);
  };
  if (entry.kind === 'group') {
    parts.push(entry.data.name || '');
    (entry.data.items || []).forEach(pushItem);
  } else {
    pushItem(entry.data);
  }
  const blob = parts.join(' ').toLowerCase();
  _archiveBlobCache.set(entry, blob);
  return blob;
}
function renderArchiveSearchResults(textNeedles, negTextNeedles) {
  const $r = document.getElementById('search-archive-results');
  if (!$r) return;
  if (!textNeedles || !textNeedles.length) { $r.classList.add('hidden'); $r.innerHTML = ''; return; }
  const negs = negTextNeedles || [];
  const arr = State.get().archive || [];
  const matches = [];
  arr.forEach((e, i) => {
    const text = archiveEntryText(e);
    if (textNeedles.every(n => text.includes(n)) && !negs.some(n => text.includes(n))) matches.push({ entry: e, idx: i });
  });
  if (!matches.length) { $r.classList.add('hidden'); $r.innerHTML = ''; return; }
  const cap = 20;
  const shown = matches.slice(0, cap).map(match => {
    const isArchivedPage = match.entry.kind === 'item' && match.entry.data?.type === 'tab';
    const isArchivedGroup = match.entry.kind === 'group';
    const isArchivedLocalItem = match.entry.kind === 'item'
      && ['note', 'todo', 'stack'].includes(match.entry.data?.type);
    return {
      ...match,
      isArchivedPage,
      isArchivedGroup,
      isArchivedLocalItem,
      restoreContext: isArchivedPage
        ? createArchivedPageRestoreContext(match.entry)
        : (isArchivedGroup
          ? createArchivedGroupRestoreContext(match.entry, 'archive')
          : (isArchivedLocalItem
            ? createArchivedLocalItemRestoreContext(match.entry, 'archive')
            : null)),
    };
  });
  const overflow = matches.length - shown.length;
  const head = `<div class="sar-hd">From archive · ${matches.length} result${matches.length === 1 ? '' : 's'}${overflow ? ` (showing ${shown.length})` : ''}</div>`;
  const rows = shown.map(({
    entry, idx, isArchivedPage, isArchivedGroup, isArchivedLocalItem, restoreContext,
  }) => {
    const name = entry.kind === 'group'
      ? (entry.data.name || 'Group')
      : (entry.data.title || (entry.data.html ? entry.data.html.replace(/<[^>]+>/g, ' ').slice(0, 60) : entry.data.text) || 'Item');
    const reviewedRestore = isArchivedPage || isArchivedGroup || isArchivedLocalItem;
    const reviewUnavailable = reviewedRestore && !restoreContext;
    const viewLabel = isArchivedPage
      ? `${tr('settings.openArchive')} — ${archivedPageRestoreDestinationText(restoreContext)}`
      : (isArchivedGroup
        ? `${tr('settings.openArchive')} — ${archivedGroupRestoreDestinationText(restoreContext)}`
        : (isArchivedLocalItem
          ? `${tr('settings.openArchive')} — ${archivedLocalItemRestoreDestinationText(restoreContext)}`
          : tr('settings.openArchive')));
    const icon = entry.kind === 'group' ? '📁' : (entry.data.type === 'note' ? '📝' : entry.data.type === 'todo' ? '✓' : '🔗');
    return `<div class="ar-entry sar-row" data-idx="${idx}">
      <span>${icon}</span>
      <span class="ar-t">${esc(name)}</span>
      <span class="ar-d">${esc(fmtTimeRelative(entry.at))}</span>
      <button type="button" class="sar-view" title="${esc(viewLabel)}" aria-label="${esc(viewLabel)}"${reviewUnavailable ? ' disabled aria-disabled="true"' : ''}><svg width="11" height="11" viewBox="0 0 11 11" fill="none"><path d="M2 6h7M6 3l3 3-3 3" stroke="currentColor" stroke-width="1.3" stroke-linecap="round" stroke-linejoin="round"/></svg></button>
      ${reviewedRestore ? '' : `<button type="button" class="restore" title="${esc(tr('archive.restore'))}" aria-label="${esc(tr('archive.restoreFor', { title: name }))}"><svg width="11" height="11" viewBox="0 0 11 11" fill="none"><path d="M3 5.5L5.5 3l2.5 2.5M5.5 3v6" stroke="currentColor" stroke-width="1.3" stroke-linecap="round" stroke-linejoin="round"/></svg></button>`}
    </div>`;
  }).join('');
  $r.innerHTML = head + rows;
  $r.classList.remove('hidden');
  $r.querySelectorAll('.sar-row').forEach((row, shownIndex) => {
    const {
      idx, isArchivedPage, isArchivedGroup, isArchivedLocalItem, restoreContext,
    } = shown[shownIndex];
    const viewButton = row.querySelector('.sar-view');
    if (isArchivedPage || isArchivedGroup || isArchivedLocalItem) {
      viewButton.onclick = () => {
        const opened = isArchivedPage
          ? openArchivedPageRestoreReview(restoreContext, viewButton)
          : (isArchivedGroup
            ? openArchivedGroupRestoreReview(restoreContext, viewButton)
            : openArchivedLocalItemRestoreReview(restoreContext, viewButton));
        if (!opened) return;
        toggleSearchBar(false);
      };
    } else {
      row.querySelector('.restore').onclick = () => {
        restoreArchive(idx);
        toggleSearchBar(false);
      };
      viewButton.onclick = () => {
        toggleSearchBar(false);
        openLibrarySurface('archive');
      };
    }
  });
}
function toggleSearchBar(force) {
  const bar = document.getElementById('search-bar');
  const hide = force === false || !bar.classList.contains('hidden');
  if (hide) { bar.classList.add('hidden'); document.getElementById('search-input').value = ''; applySearchFilter(); }
  else { bar.classList.remove('hidden'); setTimeout(() => document.getElementById('search-input').focus(), 40); }
}

// ── Dedicated search surface ────────────────────────────────────
let _searchRenderTimer = null;

function _searchPlainHtml(html) {
  const source = String(html || '');
  if (!source) return '';
  // Find again re-reads every saved note on each keystroke; the text of an
  // unchanged html string is remembered (keyed by the string itself, so an
  // edit is simply a new key).
  const cache = _searchPlainHtml.cache || (_searchPlainHtml.cache = new Map());
  let text = cache.get(source);
  if (text === undefined) {
    text = source.replace(/<br\s*\/?>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/\s+/g, ' ').trim();
    if (cache.size >= 5000) cache.clear();
    cache.set(source, text);
  }
  return text;
}

function _searchNoteParts(item) {
  const text = String(item?.html || '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p\s*>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ');
  const lines = text.split(/\n+/).map(line => line.replace(/\s+/g, ' ').trim()).filter(Boolean);
  const first = lines[0] || '';
  const clipped = first.length > 72 ? `${first.slice(0, 69).trimEnd()}…` : first;
  const remainder = lines.slice(1).join(' ') || (first.length > 72 ? first.slice(69).trim() : '');
  return { title: clipped, snippet: remainder };
}

function _searchItemTitle(item) {
  if (!item) return '';
  if (item.type === 'tab') return item.title || dispUrl(item.url || '') || tr('search.links');
  if (item.type === 'note') return _searchNoteParts(item).title || tr('search.notes');
  if (item.type === 'todo') return item.text || tr('search.todos');
  if (item.type === 'stack') return item.name || tr('search.stacks');
  return item.title || item.text || item.name || item.type || '';
}

function _searchTypeLabel(type) {
  return tr(type === 'tab' ? 'search.links' : type === 'note' ? 'search.notes' : type === 'todo' ? 'search.todos' : 'search.stacks');
}

function _searchItemBlob(row) {
  const { item, cat, group, parents = [] } = row;
  return [
    _searchItemTitle(item), item.url, item.text, _searchPlainHtml(item.html), _searchPlainHtml(item.notes),
    item.name, ...(item.tags || []), cat?.name, group?.name, ...parents.map(parent => parent.name),
  ].filter(Boolean).join(' ').toLowerCase();
}

// Data-level counterpart to applySearchFilter's DOM matcher. The launch layer,
// command palette, and search page now share this exact operator behavior.
// `parsed` lets a caller that tests many rows parse the query once.
function searchItemMatches(row, query, parsed = null) {
  const { item, cat, group, parents = [] } = row;
  if (!item) return false;
  const { pos, neg } = parsed || parseSearchQuery(query);
  let host = '';
  try { host = new URL(item.url || '').hostname.toLowerCase(); } catch {}
  const url = String(item.url || '').toLowerCase();
  const color = String(item.color || '').toLowerCase();
  const type = SEARCH_TYPES[item.type] || item.type;
  const tags = (item.tags || []).map(tag => String(tag).toLowerCase());
  const containers = [cat?.name, group?.name, ...parents.map(parent => parent.name)].filter(Boolean).map(name => String(name).toLowerCase());
  const text = _searchItemBlob(row);
  const matchesBucket = (bucket, negative = false) => {
    const checks = [];
    if (bucket.color.length) checks.push(bucket.color.includes(color));
    if (bucket.type.length) checks.push(bucket.type.includes(type));
    if (bucket.state.length) checks.push(item.type === 'todo' && bucket.state.some(state => state === (item.done ? 'done' : 'open')));
    if (bucket.domain.length) checks.push(item.type === 'tab' && !!host && bucket.domain.some(value => host.includes(value)));
    if (bucket.url.length) checks.push(item.type === 'tab' && !!url && bucket.url.some(value => url.includes(value)));
    if (bucket.in.length) checks.push(bucket.in.some(value => containers.some(name => name.includes(value))));
    if (bucket.tag.length) checks.push(bucket.tag.some(value => tags.some(tag => tag.includes(value))));
    if (bucket.text.length) checks.push(negative ? bucket.text.some(value => text.includes(value)) : bucket.text.every(value => text.includes(value)));
    return negative ? checks.some(Boolean) : checks.every(Boolean);
  };
  return matchesBucket(pos) && !matchesBucket(neg, true);
}

function _searchTimeCutoff(time) {
  const now = new Date();
  if (time === 'today') return new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
  if (time === 'week') return Date.now() - 7 * 86400000;
  if (time === 'month') return Date.now() - 30 * 86400000;
  return 0;
}

function _searchScore(row, query, parsed = null) {
  const raw = String(query || '').trim().toLowerCase();
  if (!raw) return Number(row.item.createdAt || 0);
  const title = _searchItemTitle(row.item).toLowerCase();
  const blob = _searchItemBlob(row);
  const words = (parsed || parseSearchQuery(raw)).pos.text;
  let score = 0;
  words.forEach(word => {
    if (title === word) score += 500;
    else if (title.startsWith(word)) score += 300;
    else if (title.includes(word)) score += 180;
    else if (blob.includes(word)) score += 80;
  });
  return score + Math.min(50, Number(row.item.createdAt || 0) / 1e12);
}

function _searchRowsForState(state = activeSearch, { ignoreType = false } = {}) {
  const cutoff = _searchTimeCutoff(state.time);
  const parsed = state.query ? parseSearchQuery(state.query) : null;
  const rows = collectWorkspaceItems(activeWs()).filter(row => {
    if (state.query && !searchItemMatches(row, state.query, parsed)) return false;
    if (!ignoreType && state.type !== 'all' && row.item.type !== state.type) return false;
    if (state.spaceId !== 'all' && row.cat.id !== state.spaceId) return false;
    if (cutoff && (!row.item.createdAt || row.item.createdAt < cutoff)) return false;
    if (state.hasTags && !(row.item.tags || []).length) return false;
    if (state.tag && !(row.item.tags || []).some(tag => String(tag).toLowerCase() === state.tag.toLowerCase())) return false;
    return true;
  });
  if (state.sort === 'recent' || !state.query) {
    rows.sort((a, b) => Number(b.item.createdAt || 0) - Number(a.item.createdAt || 0));
    return rows;
  }
  // Score each row once; a large library would otherwise rebuild every row's
  // text on each comparison of the sort.
  const scores = new Map(rows.map(row => [row, _searchScore(row, state.query, parsed)]));
  rows.sort((a, b) => scores.get(b) - scores.get(a));
  return rows;
}

function openSearchSurface(prefill = '') {
  const ws = activeWs();
  if (!ws) return;
  // One floating layer at a time: a menu gives way to Search. Leaving the page
  // underneath already closes Details and the Today drawer.
  if (typeof hideContextMenu === 'function') hideContextMenu();
  const query = {};
  if (prefill) query.q = String(prefill);
  Router.navigate({ type: 'search', wsId: ws.id, query }, { persist: false });
  setTimeout(() => document.getElementById('search-surface-input')?.focus({ preventScroll: true }), 40);
}

function closeSearchSurface() {
  const ws = activeWs();
  if (!ws) return;
  Router.navigate({ type: 'home', wsId: ws.id, query: {} }, { persist: false });
}

function createSearchRecoveryContext(row, ws = activeWs()) {
  if (!row?.item || !row?.cat || !row?.group || !ws) return null;
  return createSavedItemRecoveryContext({ ws, ...row });
}

function resolveSearchRecoveryTarget(context) {
  if (!context || activeWs() !== context.workspaceRef) return null;
  return resolveSavedItemRecoveryTarget(context);
}

function searchRecoveryContextMatchesRow(context, row) {
  const parents = row?.parents || [];
  return !!context
    && row?.item === context.itemRef
    && row?.cat === context.spaceRef
    && row?.group === context.groupRef
    && parents.length === context.parentRefs.length
    && parents.every((parent, index) => parent === context.parentRefs[index]);
}

function resolveCurrentSearchRecoveryTarget(context) {
  if (!activeSearch || activeSearch.loading) return null;
  let rows = [];
  try { rows = searchVisibleRows(activeSearch); } catch { return null; }
  if (!rows.some(row => searchRecoveryContextMatchesRow(context, row))) return null;
  return resolveSearchRecoveryTarget(context);
}

function searchRecoveryCanOpen(context) {
  return context?.itemRef?.type === 'tab' && isOpenableSavedTabUrl(context.itemRef.url);
}

function searchRecoveryPathParts(context) {
  return [
    context?.workspaceRef?.name,
    context?.spaceRef?.name,
    homeTrailGroupName(context?.groupRef),
    ...(Array.isArray(context?.parentRefs) ? context.parentRefs.map(parent => parent?.name) : []),
  ].map(value => String(value || '').trim()).filter(Boolean);
}

function searchRecoveryLocationText(context) {
  return homeTrailPathText(searchRecoveryPathParts(context));
}

function searchRecoveryPathHtml(context) {
  const parts = searchRecoveryPathParts(context);
  return `<ol class="search-recovery-path">${parts.map((part, index) =>
    `<li${index === parts.length - 1 ? ' aria-current="location"' : ''}>${esc(part)}</li>`
  ).join('')}</ol>`;
}

function reportSearchRecoveryUnavailable(opener) {
  toast(tr('search.recoveryUnavailable'), { danger: true, duration: 5000 });
  if (opener && typeof opener.focus === 'function') {
    requestAnimationFrame(() => {
      if (opener.isConnected) {
        try { opener.focus({ preventScroll: true }); } catch { opener.focus(); }
      }
    });
  }
  return false;
}

function cancelSearchItemDetailPreparation(itemId) {
  const root = document.getElementById('item-detail');
  if (!root || root.classList.contains('open')
      || root.dataset.returnItemId !== String(itemId || '')) return false;
  delete root.dataset.returnItemId;
  delete root.dataset.returnFocusKey;
  delete root.dataset.initialFocusKey;
  return restoreOpener(root);
}

function _searchOpenDetails(context, opener = null) {
  const target = resolveCurrentSearchRecoveryTarget(context);
  if (!target) return reportSearchRecoveryUnavailable(opener);
  const route = searchDetailRoute(activeSearch, target.ws.id, target.item.id, true);
  if (!route) return reportSearchRecoveryUnavailable(opener);
  focusDialogOpener(opener);
  prepareItemDetailOpen(target.item.id);
  const navigated = Router.navigate(route, { persist: false });
  if (!navigated) {
    const restored = cancelSearchItemDetailPreparation(target.item.id);
    return reportSearchRecoveryUnavailable(restored ? null : opener);
  }
  return true;
}

function _searchOpenPrimary(context, opener = null) {
  const target = resolveCurrentSearchRecoveryTarget(context);
  if (!target) return reportSearchRecoveryUnavailable(opener);
  if (target.item.type !== 'tab' || !isOpenableSavedTabUrl(target.item.url)) {
    return _searchOpenDetails(context, opener);
  }
  if (!openSavedTabItem(target.item, { focus: true, opener, reportUnavailable: false })) {
    return reportSearchRecoveryUnavailable(opener);
  }
  return true;
}

function searchRecoveryContextForActivation(state = activeSearch, ws = activeWs()) {
  if (!state || state !== activeSearch || state.loading || !ws || activeWs() !== ws) return null;
  let rows = [];
  try { rows = searchVisibleRows(state); } catch { return null; }
  const row = rows.find(candidate => candidate.item.id === state.selectedId) || rows[0] || null;
  return row ? createSearchRecoveryContext(row, ws) : null;
}

function handleSearchQueryKeydown(event, state, ws) {
  if (event.isComposing || event.keyCode === 229) return false;
  if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
    event.preventDefault();
    const delta = event.key === 'ArrowDown' ? 1 : -1;
    const edge = state.selectedId ? '' : (delta > 0 ? 'first' : 'last');
    _searchMoveSelection(delta, true, edge);
    return true;
  }
  if (event.key === 'Enter') {
    event.preventDefault();
    const context = searchRecoveryContextForActivation(state, ws);
    return context ? _searchOpenPrimary(context, event.currentTarget) : false;
  }
  if (event.key === 'Escape') {
    event.preventDefault();
    event.stopPropagation();
    // Escape clears a typed query first (as the Library filter does); the next
    // Escape leaves Search.
    if (String(event.currentTarget?.value || '')) {
      _searchSet({ query: '', selectedId: null }, 'search-surface-input');
      return true;
    }
    closeSearchSurface();
    return true;
  }
  return false;
}

function _searchSet(patch, focus = '') {
  if (!activeSearch) return;
  const nextPatch = { ...patch };
  const changesResultMeaning = ['query', 'type', 'spaceId', 'time', 'hasTags', 'tag', 'sort']
    .some(key => Object.prototype.hasOwnProperty.call(nextPatch, key) && nextPatch[key] !== activeSearch[key]);
  if (changesResultMeaning) nextPatch.resultLimit = SEARCH_RESULT_BATCH_SIZE;
  Object.assign(activeSearch, nextPatch, { loading: false });
  renderBoard();
  Router.sync({ replace: true });
  if (focus) setTimeout(() => document.getElementById(focus)?.focus({ preventScroll: true }), 0);
}

function showNextSearchResultBatch() {
  const state = activeSearch;
  if (!state || state.loading) return false;
  let rows = [];
  try { rows = _searchRowsForState(state); } catch { return false; }
  const visibleRows = searchVisibleRows(state, rows);
  if (!visibleRows.length || visibleRows.length >= rows.length) return false;
  const nextRowIndex = visibleRows.length;
  const nextRow = rows[nextRowIndex];
  const nextItemId = nextRow?.item?.id == null ? '' : String(nextRow.item.id);
  const nextLimit = searchResultLimit(state.resultLimit) + SEARCH_RESULT_BATCH_SIZE;
  if (!nextItemId || !Number.isSafeInteger(nextLimit)) return false;
  state.resultLimit = nextLimit;
  state.selectedId = nextItemId;
  state.detailOpen = false;
  renderBoard();
  Router.sync({ replace: true });
  setTimeout(() => {
    if (activeSearch !== state
      || state.loading
      || searchResultLimit(state.resultLimit) !== nextLimit
      || String(state.selectedId || '') !== nextItemId) return;
    const result = document.getElementById(`search-result-${nextRowIndex}`);
    if (!result?.isConnected || String(result.dataset.itemId || '') !== nextItemId) return;
    try { result.focus({ preventScroll: true }); } catch { try { result.focus(); } catch {} }
    try { result.scrollIntoView({ block: 'nearest' }); } catch {}
  }, 0);
  return true;
}

function ensureSearchLiveRegion() {
  let region = document.getElementById('search-live-region');
  if (region) return region;
  region = document.createElement('div');
  region.id = 'search-live-region';
  region.className = 'sr-only';
  region.setAttribute('role', 'status');
  region.setAttribute('aria-live', 'polite');
  region.setAttribute('aria-atomic', 'true');
  document.body.appendChild(region);
  return region;
}

function resetSearchAnnouncement() {
  const region = document.getElementById('search-live-region');
  if (!region) return false;
  region.textContent = '';
  delete region.dataset.searchAnnouncement;
  return true;
}

function searchAnnouncementSignature(state, count = null, phase = 'results', shown = null) {
  return JSON.stringify({
    phase,
    query: state?.query || '',
    type: state?.type || 'all',
    spaceId: state?.spaceId || 'all',
    time: state?.time || 'any',
    hasTags: !!state?.hasTags,
    tag: state?.tag || '',
    sort: state?.sort || 'best',
    ...(phase === 'results'
      ? { count: Number(count || 0), ...(shown == null ? {} : { shown: Number(shown || 0) }) }
      : {}),
  });
}

function announceSearchStatus(message, signature = message) {
  const region = ensureSearchLiveRegion();
  const nextSignature = String(signature ?? '');
  if (region.dataset.searchAnnouncement === nextSignature) return false;
  region.dataset.searchAnnouncement = nextSignature;
  region.textContent = '';
  requestAnimationFrame(() => {
    if (region.isConnected && region.dataset.searchAnnouncement === nextSignature) {
      region.textContent = String(message || '');
    }
  });
  return true;
}

function suspendSearchRecoveryActions() {
  if (!activeSearch) return false;
  activeSearch.loading = true;
  activeSearch.detailOpen = false;
  const list = document.getElementById('search-result-list');
  if (list) {
    list.setAttribute('aria-busy', 'true');
    list.inert = true;
  }
  return true;
}

function startSearchQueryComposition(input) {
  if (!input) return false;
  input.dataset.searchComposing = 'true';
  delete input.dataset.searchCompositionValue;
  clearTimeout(_searchRenderTimer);
  suspendSearchRecoveryActions();
  return true;
}

function queueSearchQueryInput(event) {
  const input = event?.currentTarget || event?.target;
  if (!input) return false;
  if (event.isComposing || input.dataset.searchComposing === 'true') return false;
  if (input.dataset.searchCompositionValue === input.value) {
    delete input.dataset.searchCompositionValue;
    return false;
  }
  delete input.dataset.searchCompositionValue;
  _searchQueueQuery(input.value);
  return true;
}

function endSearchQueryComposition(input) {
  if (!input) return false;
  delete input.dataset.searchComposing;
  input.dataset.searchCompositionValue = input.value;
  _searchQueueQuery(input.value);
  return true;
}

function _searchQueueQuery(query) {
  if (!activeSearch) return;
  const scheduledState = activeSearch;
  const scheduledQuery = String(query ?? '');
  suspendSearchRecoveryActions();
  scheduledState.query = scheduledQuery;
  scheduledState.selectedId = null;
  scheduledState.detailOpen = false;
  scheduledState.resultLimit = SEARCH_RESULT_BATCH_SIZE;
  Router.sync({ replace: true });
  announceSearchStatus(tr('search.loading'), searchAnnouncementSignature(scheduledState, null, 'loading'));
  const list = document.getElementById('search-result-list');
  if (list) {
    // The old rows stay on screen until the new ones replace them in place, so
    // the page does not jump on every keystroke; they leave the list semantics
    // and stay inert meanwhile.
    list.setAttribute('aria-busy', 'true');
    list.removeAttribute('role');
    list.removeAttribute('aria-labelledby');
  }
  clearTimeout(_searchRenderTimer);
  _searchRenderTimer = setTimeout(() => {
    if (activeSearch !== scheduledState || scheduledState.query !== scheduledQuery) return;
    scheduledState.loading = false;
    renderBoard();
    Router.sync({ replace: true });
    // The field survives the repaint with its caret; focus comes back only if a
    // rebuild dropped it.
    const input = document.getElementById('search-surface-input');
    const active = document.activeElement;
    if (input && (!active || active === document.body)) input.focus({ preventScroll: true });
  }, 90);
}

// ── Find again page (2026-11 canvas) ──────────────────────────────
// One heading; one search field whose operators are marked as the shared parser
// understands them; the content-type switch (its pill slides, its counts roll),
// Filters and the sort; then the results in one card. The result count in the
// field rolls as the matches change and the matched words are marked in each
// title. A highlight glides to the row under the pointer or the keyboard, and
// the selected row shows what Enter does. The page root stays across repaints,
// so the field keeps its caret while the results change under it.

const SEARCH_TYPE_ORDER = ['all', 'tab', 'note', 'todo', 'stack'];
const SEARCH_TYPE_LABELS = { all: 'search.all', tab: 'search.links', note: 'search.notes', todo: 'search.todos', stack: 'search.stacks' };
const SEARCH_FILTER_PATH = 'M2.5 3.5h10l-3.9 4.7v4.2l-2.2-1.1V8.2z';
// Details as a panel glyph, shown in place of its word at phone width.
const SEARCH_DETAILS_PATH = 'M2.5 3h10v9h-10zM9 3v9';
const SEARCH_FIRST_PAINT_ROWS = 24;
// What the last paint showed, so counts roll, rows rise and marks animate only
// when something changed.
let searchPageSession = null;

function searchPageState(wsId) {
  if (!searchPageSession || searchPageSession.wsId !== wsId) {
    searchPageSession = { wsId, count: null, typeCounts: null, hiddenCount: 0, viewKey: null, query: null, opKeys: new Set(), filtersOpen: null };
  }
  return searchPageSession;
}

function searchPageRoot() {
  return document.querySelector('#board > .search-page');
}

// The operators the shared parser understands, found in the field's own text:
// blue for where (in:, domain:, site:, host:, url:, tag:), green for is:, grey
// for type: and colour:, struck through for a minus.
function searchQueryMarks(value) {
  const text = String(value || '');
  const marks = [];
  const pattern = /-?"[^"]*"|\S+/g;
  let match;
  while ((match = pattern.exec(text))) {
    let token = match[0].toLowerCase();
    const negative = token[0] === '-' && token.length > 1;
    if (negative) token = token.slice(1);
    let kind = '';
    if (/^(?:colou?r|type):./.test(token)) kind = 'type';
    else if (/^is:./.test(token)) kind = 'done';
    else if (/^(?:domain|site|host|url|in|tag):./.test(token)) kind = 'where';
    if (negative) kind = 'not';
    if (kind) marks.push({ start: match.index, end: match.index + match[0].length, kind });
  }
  return marks;
}

// The field's text is transparent; this mirror draws the same characters with
// the operators marked, as Today's capture bar does. A mark animates only when
// it is new, not while its value is still being typed.
function paintSearchQueryMirror(page = searchPageRoot()) {
  const input = page?.querySelector('#search-surface-input');
  const mirror = page?.querySelector('.fnd-mirror');
  if (!input || !mirror) return false;
  const value = String(input.value || '');
  const known = searchPageSession?.opKeys || new Set();
  const next = new Set();
  const perKind = {};
  // One inline line: a flex mirror would drop the spaces between two marks.
  const line = document.createElement('span');
  line.className = 'fnd-mirror-line';
  let cursor = 0;
  searchQueryMarks(value).forEach(mark => {
    if (mark.start > cursor) line.appendChild(document.createTextNode(value.slice(cursor, mark.start)));
    perKind[mark.kind] = (perKind[mark.kind] || 0) + 1;
    const key = `${mark.kind}:${perKind[mark.kind]}`;
    const node = document.createElement('mark');
    node.className = `fnd-op is-${mark.kind}${known.has(key) ? '' : ' is-new'}`;
    node.textContent = value.slice(mark.start, mark.end);
    line.appendChild(node);
    next.add(key);
    cursor = mark.end;
  });
  if (cursor < value.length) line.appendChild(document.createTextNode(value.slice(cursor)));
  mirror.replaceChildren(line);
  if (searchPageSession) searchPageSession.opKeys = next;
  mirror.scrollLeft = input.scrollLeft;
  return true;
}

// Escaped text with the given [from, to) ranges wrapped in one <mark> each
// (overlapping and touching ranges merge).
function hitRangesMarkup(text, ranges, className) {
  const value = String(text || '');
  const merged = [];
  (ranges || []).slice().sort((a, b) => a[0] - b[0]).forEach(range => {
    const last = merged[merged.length - 1];
    if (last && range[0] <= last[1]) last[1] = Math.max(last[1], range[1]);
    else merged.push(range.slice());
  });
  let html = '';
  let cursor = 0;
  merged.forEach(([from, to]) => {
    html += `${esc(value.slice(cursor, from))}<mark class="${className}">${esc(value.slice(from, to))}</mark>`;
    cursor = to;
  });
  return html + esc(value.slice(cursor));
}

// The query's words marked inside a title, a domain or a snippet. The parser
// lowercases its words, so text whose lowercase changes length stays unmarked.
function searchHitMarkup(text, needles) {
  const value = String(text || '');
  const lower = value.toLowerCase();
  const words = (needles || []).filter(Boolean);
  if (!words.length || lower.length !== value.length) return esc(value);
  const ranges = [];
  words.forEach(word => {
    for (let at = lower.indexOf(word); at >= 0; at = lower.indexOf(word, at + word.length)) ranges.push([at, at + word.length]);
  });
  return hitRangesMarkup(value, ranges, 'fnd-hit');
}

// A line of the note body or the why-you-saved-it notes around the first
// match, shown under the title only when the words matched there.
function searchResultSnippet(item, needles) {
  const words = (needles || []).filter(Boolean);
  if (!words.length || !item) return '';
  const text = [item.type === 'note' ? _searchNoteParts(item).snippet : '', _searchPlainHtml(item.notes)]
    .filter(Boolean).join(' · ');
  const lower = text.toLowerCase();
  const hits = words.map(word => lower.indexOf(word)).filter(index => index >= 0);
  if (!hits.length) return '';
  // A match deep in long notes starts the line a few words before it.
  const first = Math.min(...hits);
  let start = 0;
  if (first > 60) {
    const space = text.indexOf(' ', first - 40);
    start = space >= 0 && space < first ? space + 1 : first - 40;
  }
  return `${start ? '…' : ''}${searchHitMarkup(text.slice(start, start + 160), words)}`;
}

// A highlight behind a list's rows (Find again, the command palette): it
// appears in place on its first row, then glides from row to row.
function placeRowGlide(glide, row) {
  if (!glide) return;
  if (!row || !row.isConnected) {
    glide.classList.remove('is-on');
    return;
  }
  const appearing = !glide.classList.contains('is-on');
  if (appearing) glide.classList.add('is-jump');
  glide.style.setProperty('--glide-y', `${row.offsetTop}px`);
  glide.style.setProperty('--glide-h', `${row.offsetHeight}px`);
  if (appearing) {
    void glide.offsetWidth;
    glide.classList.remove('is-jump');
  }
  glide.classList.add('is-on');
}

// On Find again it sits on the selected row, or on the row under the pointer.
function placeSearchGlide(page, row) {
  placeRowGlide(page?.querySelector('.fnd-glide'), row);
}

function searchSelectedRowEl(page = searchPageRoot()) {
  return page?.querySelector('#search-result-list .search-result-row.selected') || null;
}

function pressSearchGlide() {
  restartLibraryMotion(searchPageRoot()?.querySelector('.fnd-glide.is-on .fnd-gi'), 'is-press');
}

function _searchSelectResult(row, index, result, { focus = true } = {}) {
  if (!activeSearch || activeSearch.loading || !row?.item || !result?.isConnected) return false;
  const changed = activeSearch.selectedId !== row.item.id;
  const owner = result.closest('.search-result-row');
  if (changed) {
    activeSearch.selectedId = row.item.id;
    const list = result.closest('#search-result-list');
    list?.querySelectorAll('.search-result-row').forEach(candidate => {
      const selected = candidate === owner;
      candidate.classList.toggle('selected', selected);
      candidate.querySelectorAll('button').forEach(button => { button.tabIndex = selected ? 0 : -1; });
    });
    Router.sync({ replace: true });
  }
  placeSearchGlide(result.closest('.search-page'), owner);
  if (focus) {
    try { result.focus({ preventScroll: true }); } catch { try { result.focus(); } catch {} }
  }
  try { result.scrollIntoView({ block: 'nearest' }); } catch {}
  return true;
}

// The title button covers its row: a click opens the result (the page through
// the shared reopen coordinator, anything else in Details) and focus selects it.
function bindSearchResultActivation(result, row, index, recoveryContext) {
  result.addEventListener('focus', event => _searchSelectResult(row, index, event.currentTarget));
  result.addEventListener('click', event => {
    pressSearchGlide();
    _searchOpenPrimary(recoveryContext, event.currentTarget);
  });
  result.addEventListener('keydown', event => {
    if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault();
      _searchMoveSelection(event.key === 'ArrowDown' ? 1 : -1, true);
    } else if (event.key === 'Home' || event.key === 'End') {
      event.preventDefault();
      _searchMoveSelection(0, true, event.key === 'Home' ? 'first' : 'last');
    } else if (event.key === 'Enter') {
      event.preventDefault();
      pressSearchGlide();
      _searchOpenPrimary(recoveryContext, event.currentTarget);
    } else if (event.key === 'Escape') {
      event.preventDefault();
      event.stopPropagation();
      closeSearchSurface();
    }
  });
}

function _searchMoveSelection(delta, focusRow = false, edge = '') {
  if (!activeSearch) return false;
  const rows = searchVisibleRows(activeSearch);
  if (!rows.length) return false;
  let index = rows.findIndex(row => row.item.id === activeSearch.selectedId);
  if (index < 0) index = 0;
  if (edge === 'first') index = 0;
  else if (edge === 'last') index = rows.length - 1;
  else index = (index + delta + rows.length) % rows.length;
  const result = document.getElementById(`search-result-${index}`);
  if (!result) return false;
  return _searchSelectResult(rows[index], index, result, { focus: focusRow });
}

function _searchStateNode(kind, title, body) {
  const node = document.createElement('div');
  node.className = `search-state ${kind}`;
  if (kind === 'error') node.setAttribute('role', 'alert');
  node.innerHTML = `<span class="search-state-icon" aria-hidden="true">${kind === 'error' ? '!' : librarySvg('search', 22, 1.5)}</span><strong>${esc(title)}</strong>${body ? `<p>${esc(body)}</p>` : ''}`;
  return node;
}

// One result: the icon, the title (the matched words marked) over the exact
// saved place and the source, a line of the note when the words matched there,
// the saved age, and on hover or selection Details and what Enter does.
function _searchResultRow(row, index, selected, needles = []) {
  const item = row.item;
  const title = _searchItemTitle(item);
  const recoveryContext = createSearchRecoveryContext(row);
  const location = searchRecoveryLocationText(recoveryContext);
  const canOpen = searchRecoveryCanOpen(recoveryContext);
  const savedAgo = item.createdAt ? fmtTimeRelative(item.createdAt) : tr('search.unknownDate');
  const host = item.type === 'tab' ? planSortMeta(item).domain : '';
  const nested = item.type === 'stack' ? tr('search.stackItems', { count: (item.items || []).length }) : '';
  const snippet = searchResultSnippet(item, needles);
  const node = document.createElement('div');
  node.className = 'search-result-row fnd-row' + (selected ? ' selected' : '') + (item.type === 'todo' && item.done ? ' is-done' : '');
  node.setAttribute('role', 'listitem');
  node.dataset.itemId = String(item.id);
  node.innerHTML = `
    ${inboxFavMarkup(item)}
    <div class="fnd-copy">
      <button type="button" class="fnd-open" id="search-result-${index}"><span class="fnd-tt">${searchHitMarkup(title, needles)}</span>${librarySvg('go', 13, 1.9, 'fnd-go')}</button>
      <span class="search-result-location fnd-meta"><span class="fnd-dot" style="--dot:${esc(reminderDotColor(row.group?.color || null))}" aria-hidden="true"></span>${searchRecoveryPathHtml(recoveryContext)}${host ? `<span class="fnd-src">${searchHitMarkup(host, needles)}</span>` : ''}${nested ? `<span class="fnd-src">${esc(nested)}</span>` : ''}<span class="fnd-meta-when" aria-hidden="true">${esc(savedAgo)}</span></span>
      ${snippet ? `<span class="search-result-snippet fnd-snip">${snippet}</span>` : ''}
    </div>
    <span class="search-result-time fnd-when">${esc(savedAgo)}</span>
    <div class="fnd-acts">
      ${canOpen ? `<button type="button" class="fnd-details"><svg width="18" height="18" viewBox="0 0 15 15" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linejoin="round" aria-hidden="true"><path d="${SEARCH_DETAILS_PATH}"/></svg><span class="fnd-details-label">${esc(tr('search.details'))}</span></button>` : ''}
      <span class="fnd-cap" aria-hidden="true">${esc(tr(canOpen ? 'search.open' : 'search.details'))}<kbd>↵</kbd></span>
    </div>`;
  const result = node.querySelector('.fnd-open');
  result.dataset.itemId = String(item.id);
  result.tabIndex = selected ? 0 : -1;
  result.setAttribute('aria-label', tr(canOpen ? 'search.resultOpenAria' : 'search.resultDetailsAria', {
    title,
    location,
  }));
  // Details sits beside Open only for pages that open; anything else opens
  // Details from its title.
  const details = node.querySelector('.fnd-details');
  if (details) {
    details.tabIndex = selected ? 0 : -1;
    details.setAttribute('aria-label', tr('search.detailsItem', { title }));
    details.addEventListener('focus', () => _searchSelectResult(row, index, result, { focus: false }));
    details.addEventListener('click', event => _searchOpenDetails(recoveryContext, event.currentTarget));
  }
  bindSearchResultActivation(result, row, index, recoveryContext);
  bindInboxFavicons(node);
  return node;
}

function _searchFilterButton(label, active, onclick, count = null, id = '') {
  const button = document.createElement('button');
  button.type = 'button';
  if (id) button.id = id;
  button.className = 'search-filter-option fnd-chip' + (active ? ' active' : '');
  button.setAttribute('aria-pressed', active ? 'true' : 'false');
  button.textContent = label;
  if (count != null) button.setAttribute('aria-label', tr('library.modeCount', { label, count }));
  button.onclick = onclick;
  return button;
}

function reconcileSearchSelection(state, visibleRows) {
  const selected = state?.selectedId
    ? (visibleRows.find(row => row.item.id === state.selectedId) || null)
    : null;
  if (state?.selectedId && !selected) state.selectedId = null;
  const coherentDetail = !!state?.detailOpen
    && !!selected
    && boardDetailItemId === selected.item.id;
  if (!coherentDetail) {
    if (state) state.detailOpen = false;
    boardDetailItemId = null;
  }
  return selected;
}

function searchHiddenFilterCount(state = activeSearch) {
  if (!state) return 0;
  return Number(!!state.spaceId && state.spaceId !== 'all')
    + Number(!!state.time && state.time !== 'any')
    + Number(!!state.hasTags || !!state.tag);
}

function searchFiltersActive(state = activeSearch) {
  if (!state) return false;
  return (!!state.type && state.type !== 'all')
    || (!!state.spaceId && state.spaceId !== 'all')
    || (!!state.time && state.time !== 'any')
    || !!state.hasTags
    || !!state.tag;
}

function searchFilterResetPatch() {
  return { type: 'all', spaceId: 'all', time: 'any', hasTags: false, tag: '', selectedId: null };
}

function syncSearchQueryClear(input, clearButton = null) {
  const button = clearButton || input?.parentElement?.querySelector?.('.search-query-clear');
  if (!input || !button) return false;
  const available = String(input.value ?? '').length > 0;
  button.hidden = !available;
  button.disabled = !available;
  return available;
}

// The empty result's title names what was searched and where; its one action
// widens the search: every Space when it was scoped, else no filters, else no
// query.
function searchEmptyCopy(state, ws) {
  const parsed = parseSearchQuery(state.query);
  const words = parsed.pos.text.join(' ');
  const inValue = parsed.pos.in[0] || '';
  const names = [
    ...ws.categories.map(cat => cat.name),
    ...ws.categories.flatMap(cat => cat.groups.map(group => group.name)),
  ].filter(Boolean);
  const scope = inValue
    ? (names.find(name => String(name).toLowerCase().includes(inValue)) || inValue)
    : (state.spaceId !== 'all' ? (ws.categories.find(cat => cat.id === state.spaceId)?.name || '') : '');
  const title = words
    ? (scope ? tr('search.noResultsIn', { query: words, scope }) : tr('empty.searchTitle', { query: words }))
    : (scope ? tr('search.nothingIn', { scope }) : tr('empty.noMatchTitle'));
  return { title, scoped: !!scope };
}

// Renders Find again into #board. The page root stays across repaints of the
// same workspace (the field keeps its caret, the type pill slides, counts
// roll); the result rows are rebuilt on each settled query.
function renderSearchSurface() {
  const state = activeSearch;
  const ws = activeWs();
  if (!state || !ws) return false;
  hideBreadcrumb();
  const board = document.getElementById('board');
  board.classList.remove('group-page-mode', 'list-mode', 'canvas-mode', 'explorer-mode', 'timeline-mode', 'gallery-mode', 'graph-mode', 'calendar-mode', 'home-mode', 'library-mode');
  board.classList.add('search-mode');
  const session = searchPageState(ws.id);
  let page = searchPageRoot();
  const firstShow = !page || page.dataset.wsId !== ws.id;
  const keepScroll = board.scrollTop;

  let baseRows = [], rows = [], failure = null;
  try {
    if (state.spaceId !== 'all' && !ws.categories.some(cat => cat.id === state.spaceId)) state.spaceId = 'all';
    baseRows = _searchRowsForState(state, { ignoreType: true });
    rows = state.type === 'all' ? baseRows : baseRows.filter(row => row.item.type === state.type);
  } catch (err) {
    console.error(err);
    failure = err;
  }
  const visibleRows = searchVisibleRows(state, rows);
  const routedSelection = reconcileSearchSelection(state, failure ? [] : visibleRows);
  const selected = !failure ? (routedSelection || visibleRows[0] || null) : null;
  const typeCounts = { all: baseRows.length, tab: 0, note: 0, todo: 0, stack: 0 };
  baseRows.forEach(row => { if (typeCounts[row.item.type] != null) typeCounts[row.item.type]++; });
  const resultCount = tr(rows.length === 1 ? 'search.resultCountOne' : 'search.resultCount', { count: rows.length });
  const hiddenFilterCount = searchHiddenFilterCount(state);
  const filtersActive = searchFiltersActive(state);
  const filterToggleText = tr('search.filters');
  const filterToggleLabel = hiddenFilterCount
    ? `${filterToggleText}, ${tr('search.activeFilterCount', { count: hiddenFilterCount })}`
    : filterToggleText;
  const allItems = collectWorkspaceItems(ws);
  const needles = state.query ? parseSearchQuery(state.query).pos.text : [];
  const viewKey = [state.type, state.spaceId, state.time, state.hasTags, state.tag, state.sort].join('|');
  const viewChanged = !firstShow && session.viewKey != null && session.viewKey !== viewKey;
  const queryChanged = session.query !== state.query;

  if (firstShow) {
    board.innerHTML = '';
    page = document.createElement('section');
    page.className = 'search-page fnd';
    page.dataset.wsId = ws.id;
    page.innerHTML = `
      <h1 class="fnd-title" id="search-title" tabindex="-1"></h1>
      <p class="sr-only" id="search-sub"></p>
      <div class="search-query-box fnd-q">
        ${librarySvg('search', 20, 1.5, 'fnd-q-icon')}
        <div class="fnd-field">
          <div class="fnd-mirror" aria-hidden="true"></div>
          <input id="search-surface-input" type="search" aria-controls="search-result-list" aria-describedby="search-sub" autocomplete="off" spellcheck="false">
        </div>
        <span class="fnd-count" aria-hidden="true" hidden><span class="fnd-num"></span><span class="fnd-word"></span></span>
        <button type="button" class="search-query-clear fnd-clear">${librarySvg('close', 14, 1.8)}</button>
      </div>
      <div class="fnd-tools">
        <div class="search-type-tabs fnd-seg" role="group">
          <span class="fnd-thumb" aria-hidden="true"></span>
          ${SEARCH_TYPE_ORDER.map(type => `<button type="button" class="fnd-seg-btn" id="search-type-${type}" data-type="${type}"><span class="fnd-seg-label"></span><span class="fnd-cnt" aria-hidden="true"></span></button>`).join('')}
        </div>
        <span class="fnd-gap" aria-hidden="true"></span>
        <button type="button" class="search-filter-toggle fnd-fbtn" id="search-filter-toggle" aria-controls="search-filter-panel"></button>
        <label class="fnd-sort"><span class="sr-only"></span><select class="search-sort" id="search-sort"><option value="best"></option><option value="recent"></option></select>${librarySvg('chevron', 14, 1.6)}</label>
      </div>
      <div class="search-filters fnd-panel" id="search-filter-panel" hidden>
        <div class="search-filter-sections"></div>
        <button type="button" class="fnd-reset" id="search-clear-filters"></button>
      </div>
      <h2 class="fnd-recent" id="search-results-title"></h2>
      <div class="search-results fnd-card">
        <span class="fnd-glide" aria-hidden="true"><span class="fnd-gi"></span></span>
        <div id="search-result-list"></div><footer class="search-result-continuation" hidden><span></span><button type="button"></button></footer>
      </div>`;
    board.appendChild(page);

    const input = page.querySelector('#search-surface-input');
    const clearQueryButton = page.querySelector('.search-query-clear');
    input.value = state.query;
    syncSearchQueryClear(input, clearQueryButton);
    input.oncompositionstart = () => startSearchQueryComposition(input);
    input.oninput = event => {
      syncSearchQueryClear(input, clearQueryButton);
      paintSearchQueryMirror(page);
      queueSearchQueryInput(event);
    };
    input.oncompositionend = () => {
      syncSearchQueryClear(input, clearQueryButton);
      endSearchQueryComposition(input);
    };
    input.onkeydown = event => handleSearchQueryKeydown(event, activeSearch, activeWs());
    const mirror = page.querySelector('.fnd-mirror');
    ['scroll', 'keyup', 'click', 'select', 'focus'].forEach(type => {
      input.addEventListener(type, () => requestAnimationFrame(() => { mirror.scrollLeft = input.scrollLeft; }));
    });
    clearQueryButton.onclick = () => _searchSet({ query: '', selectedId: null }, 'search-surface-input');

    // The highlight follows the pointer over the card and returns to the
    // selected row when the pointer leaves.
    const card = page.querySelector('.fnd-card');
    card.addEventListener('pointerover', event => {
      const row = event.target.closest?.('.search-result-row');
      if (row && !row.closest('[inert]')) placeSearchGlide(page, row);
    });
    card.addEventListener('pointerleave', () => placeSearchGlide(page, searchSelectedRowEl(page)));
    // Rows change height when a font loads, the language changes or the
    // window narrows; the highlight stays on its row.
    if (typeof ResizeObserver === 'function') {
      new ResizeObserver(() => {
        if (!card.matches(':hover')) placeSearchGlide(page, searchSelectedRowEl(page));
      }).observe(page.querySelector('#search-result-list'));
    }
  }

  page.querySelector('#search-title').textContent = tr('search.title');
  page.querySelector('#search-sub').textContent = tr('search.subtitle');
  const input = page.querySelector('#search-surface-input');
  const clearQueryButton = page.querySelector('.search-query-clear');
  input.placeholder = tr('search.inputPlaceholder');
  input.setAttribute('aria-label', tr('search.inputPlaceholder'));
  // A query that changed elsewhere (Clear, Escape, a route) reaches the field;
  // an IME composition in progress is never overwritten.
  if (input.value !== state.query && input.dataset.searchComposing !== 'true') input.value = state.query;
  syncSearchQueryClear(input, clearQueryButton);
  clearQueryButton.setAttribute('aria-label', tr('search.clear'));
  clearQueryButton.title = tr('search.clear');
  paintSearchQueryMirror(page);

  // The result count in the field rolls to its new value.
  const count = page.querySelector('.fnd-count');
  count.hidden = !state.query || state.loading || !!failure;
  const countNum = count.querySelector('.fnd-num');
  if (session.count !== rows.length || !countNum.firstChild) {
    countNum.innerHTML = libraryRollMarkup(rows.length, session.count);
  }
  count.querySelector('.fnd-word').textContent = tr(rows.length === 1 ? 'search.resultWordOne' : 'search.resultWord');

  // Content type: the pill slides to the pressed type; counts ignore the type.
  const typeTabs = page.querySelector('.search-type-tabs');
  typeTabs.setAttribute('aria-label', tr('search.contentType'));
  typeTabs.style.setProperty('--fnd-i', String(Math.max(0, SEARCH_TYPE_ORDER.indexOf(state.type))));
  typeTabs.querySelectorAll('[data-type]').forEach(button => {
    const type = button.dataset.type;
    const label = tr(SEARCH_TYPE_LABELS[type]);
    const pressed = state.type === type;
    button.classList.toggle('active', pressed);
    button.setAttribute('aria-pressed', pressed ? 'true' : 'false');
    button.setAttribute('aria-label', tr('library.modeCount', { label, count: typeCounts[type] }));
    button.querySelector('.fnd-seg-label').textContent = label;
    const cnt = button.querySelector('.fnd-cnt');
    const previous = session.typeCounts ? session.typeCounts[type] : null;
    if (previous !== typeCounts[type] || !cnt.firstChild) cnt.innerHTML = libraryRollMarkup(typeCounts[type], previous);
    button.onclick = () => _searchSet({ type, selectedId: null }, button.id);
  });

  // Filters: the button turns dark while the panel is open and carries a
  // bubble with the number of filters the closed panel hides.
  const toggle = page.querySelector('#search-filter-toggle');
  toggle.classList.toggle('has-active-filters', hiddenFilterCount > 0);
  toggle.setAttribute('aria-expanded', state.filtersOpen ? 'true' : 'false');
  toggle.setAttribute('aria-label', filterToggleLabel);
  const bubblePops = hiddenFilterCount > 0 && hiddenFilterCount !== session.hiddenCount;
  toggle.innerHTML = `<svg width="15" height="15" viewBox="0 0 15 15" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round" aria-hidden="true"><path d="${SEARCH_FILTER_PATH}"/></svg><span>${esc(filterToggleText)}</span>${hiddenFilterCount ? `<b class="search-filter-count" aria-hidden="true">${hiddenFilterCount}</b>` : ''}`;
  if (bubblePops) toggle.querySelector('.search-filter-count')?.classList.add('is-pop');
  toggle.onclick = () => _searchSet({ filtersOpen: !activeSearch.filtersOpen }, 'search-filter-toggle');

  const panel = page.querySelector('#search-filter-panel');
  const opening = state.filtersOpen && panel.hidden;
  panel.hidden = !state.filtersOpen;
  if (opening && session.filtersOpen != null) restartLibraryMotion(panel, 'is-rise');
  panel.classList.toggle('is-opening', opening);
  const filterSections = panel.querySelector('.search-filter-sections');
  filterSections.replaceChildren();
  if (state.filtersOpen) {
    let chipIndex = 0;
    const addFilterSection = title => {
      const section = document.createElement('div');
      section.className = 'fnd-fgroup';
      section.setAttribute('role', 'group');
      section.setAttribute('aria-label', title);
      section.innerHTML = `<h3 class="fnd-fgl" aria-hidden="true">${esc(title)}</h3><div class="fnd-chips"></div>`;
      filterSections.appendChild(section);
      const chips = section.querySelector('.fnd-chips');
      return { appendChild(chip) { chip.style.setProperty('--fnd-d', `${Math.min(chipIndex++, 10) * 24}ms`); chips.appendChild(chip); } };
    };
    const itemsPerSpace = new Map();
    allItems.forEach(({ cat }) => itemsPerSpace.set(cat.id, (itemsPerSpace.get(cat.id) || 0) + 1));
    const spaces = addFilterSection(tr('search.space'));
    const allSpacesFilterId = 'search-filter-space-all';
    spaces.appendChild(_searchFilterButton(tr('search.allSpaces'), state.spaceId === 'all', () => _searchSet({ spaceId: 'all', selectedId: null }, allSpacesFilterId), allItems.length, allSpacesFilterId));
    ws.categories.forEach((cat, index) => {
      const focusId = `search-filter-space-${index}`;
      spaces.appendChild(_searchFilterButton(cat.name, state.spaceId === cat.id, () => _searchSet({ spaceId: cat.id, selectedId: null }, focusId), itemsPerSpace.get(cat.id) || 0, focusId));
    });
    const times = addFilterSection(tr('search.time'));
    [['any', tr('search.anyTime')], ['today', tr('search.today')], ['week', tr('search.thisWeek')], ['month', tr('search.thisMonth')]].forEach(([time, label]) => {
      const focusId = `search-filter-time-${time}`;
      times.appendChild(_searchFilterButton(label, state.time === time, () => _searchSet({ time, selectedId: null }, focusId), null, focusId));
    });
    const tagCounts = new Map();
    const activeTag = String(state.tag || '');
    allItems.forEach(({ item }) => (item.tags || []).forEach(rawTag => {
      const label = String(rawTag || '').trim();
      if (!label) return;
      const key = label.toLowerCase();
      const current = tagCounts.get(key);
      tagCounts.set(key, { label: current?.label || label, count: (current?.count || 0) + 1 });
    }));
    const tags = addFilterSection(tr('search.tags'));
    const hasTagsFilterId = 'search-filter-has-tags';
    tags.appendChild(_searchFilterButton(tr('search.hasTags'), state.hasTags, () => _searchSet({ hasTags: !state.hasTags, tag: '', selectedId: null }, hasTagsFilterId), null, hasTagsFilterId));
    [...tagCounts.values()]
      .sort((a, b) => b.count - a.count || a.label.localeCompare(b.label, appLocale()))
      .slice(0, 8)
      .forEach(({ label, count }, index) => {
        const focusId = `search-filter-tag-${index}`;
        tags.appendChild(_searchFilterButton(label, activeTag.toLowerCase() === label.toLowerCase(), () => _searchSet({ tag: activeTag.toLowerCase() === label.toLowerCase() ? '' : label, hasTags: false, selectedId: null }, focusId), count, focusId));
      });
  }
  const clearFiltersButton = page.querySelector('#search-clear-filters');
  clearFiltersButton.textContent = tr('search.clearFilters');
  clearFiltersButton.disabled = !filtersActive;
  clearFiltersButton.onclick = () => _searchSet(searchFilterResetPatch(), 'search-surface-input');

  const sortLabel = page.querySelector('.fnd-sort .sr-only');
  sortLabel.textContent = tr('search.sortBy');
  const sort = page.querySelector('.search-sort');
  [...sort.options].forEach(option => { option.textContent = tr(option.value === 'recent' ? 'search.newest' : 'search.bestMatch'); });
  sort.value = state.sort;
  sort.onchange = () => _searchSet({ sort: sort.value, selectedId: null }, 'search-sort');

  // "Recently saved" heads the list only without a query; with one, the same
  // heading names the list for assistive tech.
  const listTitle = page.querySelector('#search-results-title');
  listTitle.textContent = state.query ? tr('search.results') : tr('search.recent');
  listTitle.classList.toggle('sr-only', !!state.query || !rows.length || !!failure || state.loading);

  const list = page.querySelector('#search-result-list');
  // A repaint supersedes rows still waiting from the previous one.
  session.restToken = (session.restToken || 0) + 1;
  list.replaceChildren();
  list.removeAttribute('role');
  list.removeAttribute('aria-labelledby');
  list.removeAttribute('aria-busy');
  list.inert = false;
  list.classList.toggle('is-fresh', queryChanged);
  if (state.loading) {
    list.setAttribute('aria-busy', 'true');
    list.appendChild(_searchStateNode('loading', tr('search.loading'), ''));
  } else if (failure) {
    list.appendChild(_searchStateNode('error', tr('search.error'), tr('search.errorBody')));
  } else if (!allItems.length) {
    list.appendChild(buildLibraryEmpty({
      icon: librarySvg('search', 26, 1.5),
      title: tr('empty.libraryTitle'),
      actions: [
        { label: tr('empty.addSave'), run: () => openCommandPalette() },
        { label: tr('empty.importBookmarks'), run: () => importBookmarks() },
      ],
    }));
  } else if (!rows.length) {
    const copy = searchEmptyCopy(state, ws);
    const clearFilters = () => _searchSet(searchFilterResetPatch(), 'search-surface-input');
    const clearSearch = () => _searchSet({ query: '', selectedId: null }, 'search-surface-input');
    const searchAllSpaces = () => _searchSet({
      query: state.query.replace(/(^|\s)in:\S+/gi, ' ').replace(/\s+/g, ' ').trim(),
      spaceId: 'all',
      selectedId: null,
    }, 'search-surface-input');
    const action = copy.scoped
      ? { label: tr('empty.searchAllSpaces'), run: searchAllSpaces }
      : { label: tr(filtersActive ? 'empty.clearFilters' : 'empty.clearSearch'), run: filtersActive ? clearFilters : clearSearch };
    list.appendChild(buildLibraryEmpty({ icon: librarySvg('search', 26, 1.5), title: copy.title, actions: [action] }));
  } else {
    list.setAttribute('role', 'list');
    list.setAttribute('aria-labelledby', 'search-results-title');
    const selectedId = () => activeSearch?.selectedId || selected?.item.id;
    const appendRows = (from, to) => {
      const fragment = document.createDocumentFragment();
      for (let index = from; index < to; index += 1) {
        const row = visibleRows[index];
        const node = _searchResultRow(row, index, row.item.id === selectedId(), needles);
        if (viewChanged && index < 12) {
          node.classList.add('is-rise');
          node.style.setProperty('--fnd-d', `${Math.min(index, 8) * 24}ms`);
        }
        fragment.appendChild(node);
      }
      list.appendChild(fragment);
    };
    // The rows on screen (and the selected one) are built at once; the rest of
    // the result window follows on the next frame, so a keystroke on a large
    // library repaints quickly.
    const selectedIndex = visibleRows.findIndex(row => row.item.id === selectedId());
    const firstPart = Math.min(visibleRows.length, Math.max(SEARCH_FIRST_PAINT_ROWS, selectedIndex + 1));
    appendRows(0, firstPart);
    if (firstPart < visibleRows.length) {
      const token = session.restToken;
      const rest = () => {
        if (session.restToken !== token || searchPageSession !== session || !list.isConnected) return;
        session.restToken += 1;
        appendRows(firstPart, visibleRows.length);
      };
      requestAnimationFrame(rest);
      setTimeout(rest, 60);
    }
  }
  const continuation = page.querySelector('.search-result-continuation');
  continuation.hidden = true;
  const showingResults = tr('search.showingResults', { shown: visibleRows.length, total: rows.length });
  if (!state.loading && !failure && rows.length > SEARCH_RESULT_BATCH_SIZE) {
    continuation.hidden = false;
    continuation.querySelector('span').textContent = showingResults;
    const more = continuation.querySelector('button');
    const remaining = Math.max(0, rows.length - visibleRows.length);
    more.hidden = remaining === 0;
    if (remaining) {
      more.textContent = tr('search.showMore', { count: Math.min(SEARCH_RESULT_BATCH_SIZE, remaining) });
      more.onclick = () => showNextSearchResultBatch();
    }
  }
  if (failure) {
    resetSearchAnnouncement();
  } else {
    const announcementSignature = searchAnnouncementSignature(
      state,
      rows.length,
      state.loading ? 'loading' : 'results',
      visibleRows.length,
    );
    const announcement = !state.loading && rows.length > SEARCH_RESULT_BATCH_SIZE
      ? showingResults
      : resultCount;
    announceSearchStatus(state.loading ? tr('search.loading') : announcement, announcementSignature);
  }

  session.count = rows.length;
  session.typeCounts = typeCounts;
  session.hiddenCount = hiddenFilterCount;
  session.viewKey = viewKey;
  session.query = state.query;
  session.filtersOpen = state.filtersOpen;
  if (viewChanged || (queryChanged && !firstShow)) board.scrollTo({ top: 0, behavior: 'instant' });
  else if (!firstShow && board.scrollTop !== keepScroll) board.scrollTo({ top: keepScroll, behavior: 'instant' });
  placeSearchGlide(page, page.querySelector('#search-result-list .search-result-row:hover') || searchSelectedRowEl(page));
  return true;
}

// ════════════════════════════════════════════════════════════════
// WORKSPACE GRID
// ════════════════════════════════════════════════════════════════
function setWorkspaceGridInterlock(enabled) {
  const allowed = new Set([
    'ws-grid-overlay',
    'state-recovery-overlay',
    'organization-name-overlay',
    'organization-delete-overlay',
    'context-menu',
    'emoji-picker',
  ]);
  for (const child of document.body.children) {
    if (allowed.has(child.id)) continue;
    setElementInertOwner(child, 'workspace-grid', enabled);
  }
}

function focusWorkspaceGridFallback(workspaceId) {
  const chip = [...document.querySelectorAll('.ws-chip')]
    .find(element => element.dataset.wsid === workspaceId);
  const candidates = [chip, document.getElementById('ws-menu-btn'), document.getElementById('add-ws-btn')];
  for (const target of candidates) {
    if (!target || typeof target.focus !== 'function') continue;
    try { target.focus({ preventScroll: true }); } catch { try { target.focus(); } catch {} }
    if (document.activeElement === target) return true;
  }
  return false;
}

function closeWsGrid() {
  const overlay = document.getElementById('ws-grid-overlay');
  if (!overlay || overlay.classList.contains('hidden')) return false;
  overlay.classList.add('hidden');
  setWorkspaceGridInterlock(false);
  unlockBodyScroll();
  if (!restoreOpener(overlay)) setTimeout(() => focusWorkspaceGridFallback(State.get().activeWsId), 0);
  return true;
}

async function openWsGrid(opener) {
  const overlay = document.getElementById('ws-grid-overlay');
  const wasOpen = !overlay.classList.contains('hidden');
  if (!wasOpen) {
    const explicitOpener = opener?.currentTarget || opener;
    if (explicitOpener && typeof explicitOpener.focus === 'function') {
      focusDialogOpener(explicitOpener);
    } else if (document.activeElement?.closest?.('#context-menu')) {
      focusDialogOpener(document.getElementById('ws-menu-btn'));
    }
    rememberOpener(overlay);
  }
  const s = State.get();
  const g = document.getElementById('wsg-grid');
  g.innerHTML = '';
  s.workspaces.forEach(ws => {
    const count = ws.categories.reduce((a, c) => a + c.groups.reduce((b, gp) => b + gp.items.length, 0), 0);
    const card = document.createElement('div');
    card.className = 'wsg-card' + (ws.id === s.activeWsId ? ' active' : '');
    card.dataset.wsId = ws.id;
    card.setAttribute('aria-label', tr('palette.workspace', { name: ws.name }));
    card.innerHTML = `
      ${s.workspaces.length > 1 ? `<button class="del" title="${esc(tr('organization.workspace.delete'))}" aria-label="${esc(tr('organization.workspace.delete'))}"><svg width="10" height="10" viewBox="0 0 11 11"><path d="M1.5 1.5l8 8M9.5 1.5l-8 8" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/></svg></button>` : ''}
      <span class="sym">${esc(ws.symbol||'🏠')}</span>
      <div class="nm">${esc(ws.name)}</div>
      <div class="cnt">${esc(tr('workspaceManager.items', { count }))}</div>`;
    card.onclick = async e => {
      if (e.target.closest('.del')) {
        openOrganizationDelete('workspace', ws.id, e.target.closest('.del'));
        return;
      }
      s.activeWsId = ws.id;
      State.persist();
      const headerReady = renderAll();
      closeWsGrid();
      try { await headerReady; } catch {}
      focusWorkspaceGridFallback(ws.id);
    };
    enableKeyboardClick(card);
    bindAnchoredContextMenu(card, () => [
        { text: tr('organization.renameMenu'), icon: cmIcons.edit, action: () => openOrganizationName('workspace', ws.id, card) }
      ]);
    g.appendChild(card);
  });
  if (!wasOpen) {
    overlay.classList.remove('hidden');
    setWorkspaceGridInterlock(true);
    lockBodyScroll();
    setTimeout(() => {
      const activeCard = [...document.querySelectorAll('.wsg-card')]
        .find(element => element.dataset.wsId === s.activeWsId);
      (activeCard || document.getElementById('wsg-close'))?.focus({ preventScroll: true });
    }, 0);
  }
}

// ════════════════════════════════════════════════════════════════
// ARCHIVE LIST
// ════════════════════════════════════════════════════════════════
function renderArchiveList() {
  const $l = document.getElementById('archive-list');
  if (!$l) return;
  const arr = State.get().archive;
  $l.innerHTML = '';
  if (!arr.length) { $l.innerHTML = `<div class="ar-empty">Archive is empty.</div>`; return; }
  arr.forEach((e, i) => {
    const el = document.createElement('div');
    el.className = 'ar-entry';
    const name = e.kind === 'group' ? (e.data.name || 'Group') : (e.data.title || (e.data.html ? e.data.html.slice(0, 60) : e.data.text) || 'Item');
    const isArchivedPage = e.kind === 'item' && e.data?.type === 'tab';
    const isArchivedGroup = e.kind === 'group';
    const isArchivedLocalItem = e.kind === 'item'
      && ['note', 'todo', 'stack'].includes(e.data?.type);
    const reviewedRestore = isArchivedPage || isArchivedGroup || isArchivedLocalItem;
    const restoreContext = isArchivedPage
      ? createArchivedPageRestoreContext(e)
      : (isArchivedGroup
        ? createArchivedGroupRestoreContext(e, 'archive')
        : (isArchivedLocalItem ? createArchivedLocalItemRestoreContext(e, 'archive') : null));
    const reviewUnavailable = reviewedRestore && !restoreContext;
    const actionLabel = isArchivedPage
      ? `${tr('settings.openArchive')} — ${archivedPageRestoreDestinationText(restoreContext)}`
      : (isArchivedGroup
        ? `${tr('settings.openArchive')} — ${archivedGroupRestoreDestinationText(restoreContext)}`
        : (isArchivedLocalItem
          ? `${tr('settings.openArchive')} — ${archivedLocalItemRestoreDestinationText(restoreContext)}`
          : tr('archive.restoreFor', { title: name })));
    const actionIcon = reviewedRestore
      ? '<path d="M2 6h7M6 3l3 3-3 3" stroke="currentColor" stroke-width="1.3" stroke-linecap="round" stroke-linejoin="round"/>'
      : '<path d="M3 5.5L5.5 3l2.5 2.5M5.5 3v6" stroke="currentColor" stroke-width="1.3" stroke-linecap="round" stroke-linejoin="round"/>';
    el.innerHTML = `
      <span>${e.kind === 'group' ? '📁' : (e.data.type === 'note' ? '📝' : e.data.type === 'todo' ? '✓' : '🔗')}</span>
      <span class="ar-t">${esc(name)}</span>
      <span class="ar-d">${fmtTimeRelative(e.at)}</span>
      <button type="button" class="${reviewedRestore ? 'archive-review' : 'restore'}" title="${esc(actionLabel)}" aria-label="${esc(actionLabel)}"${reviewUnavailable ? ' disabled aria-disabled="true"' : ''}><svg width="11" height="11" viewBox="0 0 11 11" fill="none">${actionIcon}</svg></button>
      <button class="del" title="${esc(tr('archive.moveToTrash'))}"><svg width="11" height="11" viewBox="0 0 11 11"><path d="M2 3h7M4.5 3V1.5h2V3M3 3v6.5a0.5 0.5 0 00.5.5h4a0.5 0.5 0 00.5-.5V3" stroke="currentColor" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round" fill="none"/></svg></button>`;
    const actionButton = el.querySelector(reviewedRestore ? '.archive-review' : '.restore');
    if (reviewedRestore) {
      actionButton.onclick = () => {
        const opened = isArchivedPage
          ? openArchivedPageRestoreReview(restoreContext, actionButton)
          : (isArchivedGroup
            ? openArchivedGroupRestoreReview(restoreContext, actionButton)
            : openArchivedLocalItemRestoreReview(restoreContext, actionButton));
        if (!opened) return;
        const drawer = document.getElementById('settings-drawer');
        drawer?.classList.add('hidden');
        if (drawer) restoreOpener(drawer);
      };
    } else actionButton.onclick = () => restoreArchive(i);
    el.querySelector('.del').onclick = () => moveArchiveEntriesToTrash([e]);
    $l.appendChild(el);
  });
}

// ════════════════════════════════════════════════════════════════
// BOOKMARKS / EXPORT / IMPORT
// ════════════════════════════════════════════════════════════════
async function importBookmarks() {
  if (dataBookmarksBusy) return false;
  if (!chrome.bookmarks) {
    toast(tr('feedback.bookmarksUnavailable'), { danger: true });
    return false;
  }
  const workspace = activeWs();
  const space = activeCat();
  const reviewedTarget = workspace && space
    ? {
        workspaceId: String(workspace.id || ''),
        spaceId: String(space.id || ''),
        workspaceName: String(workspace.name || ''),
        spaceName: String(space.name || ''),
        workspaceRef: workspace,
        spaceRef: space,
      }
    : null;
  if (!reviewedTarget?.workspaceId || !reviewedTarget.spaceId) {
    toast(tr('feedback.bookmarksUnavailable'), { danger: true });
    return false;
  }
  dataBookmarksBusy = true;
  renderDataSettings();
  let tree;
  try {
    tree = await chrome.bookmarks.getTree();
  } catch {
    dataBookmarksBusy = false;
    renderDataSettings();
    toast(tr('feedback.bookmarksReadFailed'), { danger: true, duration: 5000 });
    return false;
  }
  const target = identitySpaceTarget(reviewedTarget.workspaceId, reviewedTarget.spaceId);
  if (!target
    || target.workspace !== reviewedTarget.workspaceRef
    || target.space !== reviewedTarget.spaceRef
    || String(target.workspace.name || '') !== reviewedTarget.workspaceName
    || String(target.space.name || '') !== reviewedTarget.spaceName) {
    dataBookmarksBusy = false;
    renderDataSettings();
    toast(tr('feedback.bookmarksDestinationChanged'), { danger: true, duration: 6000 });
    return false;
  }
  let allocateId;
  try {
    allocateId = createOrganizationIdAllocator();
  } catch {
    dataBookmarksBusy = false;
    renderDataSettings();
    toast(tr('feedback.bookmarksSaveFailed'), { danger: true, duration: 7000 });
    return false;
  }
  const MAX_BOOKMARK_DEPTH = 50;
  let imported = 0;
  let skipped = 0;
  const groups = [];
  function walk(nodes, folderName, depth) {
    if (depth >= MAX_BOOKMARK_DEPTH) { skipped++; return; }
    const g = { id: allocateId(), name: folderName || tr('import.bookmarksDefaultGroup'), symbol:'🔖', color:'#eab308', collapsed:false, items:[] };
    let has = false;
    for (const n of nodes) {
      if (isOpenableSavedTabUrl(n.url)) { g.items.push(stampNew({ id: allocateId(), type:'tab', title:n.title||n.url, url:n.url, fav:'' })); has = true; imported++; }
      else if (n.children) walk(n.children, n.title, depth + 1);
    }
    if (has) groups.push(g);
  }
  if (!Array.isArray(tree)) {
    dataBookmarksBusy = false;
    renderDataSettings();
    toast(tr('feedback.bookmarksReadFailed'), { danger: true, duration: 5000 });
    return false;
  }
  try {
    tree.forEach(r => (r.children || []).forEach(c => walk(c.children || [], c.title, 0)));
  } catch {
    dataBookmarksBusy = false;
    renderDataSettings();
    toast(tr('feedback.bookmarksReadFailed'), { danger: true, duration: 5000 });
    return false;
  }
  if (!groups.length) {
    dataBookmarksBusy = false;
    renderDataSettings();
    toast(tr(skipped ? 'feedback.bookmarksImportedWithSkipped' : 'feedback.bookmarksImported', {
      count: imported,
      skipped,
    }));
    return true;
  }
  const actionId = State.snapshot(tr('history.importBookmarks'));
  target.space.groups.push(...groups);
  try {
    await State.persistNow();
  } catch (error) {
    State.rollbackSnapshot(actionId);
    renderBoard();
    dataBookmarksBusy = false;
    renderDataSettings();
    toast(tr('feedback.bookmarksSaveFailed'), { danger: true, duration: 7000 });
    return false;
  }
  renderBoard();
  dataBookmarksBusy = false;
  renderDataSettings();
  toast(tr(skipped ? 'feedback.bookmarksImportedWithSkipped' : 'feedback.bookmarksImported', {
    count: imported,
    skipped,
  }), { undo: actionId });
  return true;
}
function countState(s) {
  let workspaces = 0, categories = 0, groups = 0, items = 0;
  const countItems = (list) => {
    for (const it of (list || [])) {
      items++;
      if (it && it.type === 'stack') countItems(it.items);
    }
  };
  for (const ws of (s.workspaces || [])) {
    workspaces++;
    for (const cat of (ws.categories || [])) {
      categories++;
      for (const g of (cat.groups || [])) {
        groups++;
        countItems(g.items);
      }
    }
  }
  return { workspaces, categories, groups, items, archived: (s.archive || []).length, trashed: (s.trash || []).length };
}

function exportJSON(options = {}) {
  const data = { ...State.get() };
  // Revision is a live concurrency token for this browser profile, not
  // portable user data. Importing it would create a false write conflict.
  delete data._revision;
  const counts = countState(data);
  const payload = {
    app: 'locus',
    schema: CURRENT_SCHEMA,
    exportedAt: new Date().toISOString(),
    counts,
    data
  };
  const blob = new Blob([JSON.stringify(payload, null, 2)], { type:'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  const wsTag = counts.workspaces ? `-${counts.workspaces}ws` : '';
  a.href = url;
  const prefix = typeof options.prefix === 'string' && options.prefix ? options.prefix : 'locus';
  a.download = `${prefix}${wsTag}-${new Date().toISOString().slice(0,10)}.json`;
  a.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
  if (!options.silent) toast(tr('feedback.exported', {
    workspaces: counts.workspaces,
    items: counts.items,
  }));
}

let importCtx = null;
let importBusy = false;
let importReadGeneration = 0;
const MAX_IMPORT_BYTES = 20 * 1024 * 1024;
const MAX_IMPORT_NODES = 120000;
const MAX_IMPORT_DEPTH = 30;
const MAX_IMPORT_STRING = 1024 * 1024;
const IMPORT_ITEM_TYPES = new Set(['tab', 'note', 'todo', 'stack']);
const IMPORT_DANGEROUS_KEYS = new Set(['__proto__', 'prototype', 'constructor']);

function validateImportData(data, schema) {
  if (Number.isFinite(Number(schema)) && Number(schema) > CURRENT_SCHEMA) {
    throw new Error(`This backup uses newer schema ${schema}. Update Locus before importing it.`);
  }
  let nodes = 0;
  const inspect = (value, depth, label) => {
    if (depth > MAX_IMPORT_DEPTH) throw new Error(`${label} is nested too deeply`);
    if (++nodes > MAX_IMPORT_NODES) throw new Error('Backup contains too many values');
    if (typeof value === 'string' && value.length > MAX_IMPORT_STRING) {
      throw new Error(`${label} contains an oversized text value`);
    }
    if (!value || typeof value !== 'object') return;
    if (Array.isArray(value)) {
      for (let i = 0; i < value.length; i++) inspect(value[i], depth + 1, `${label}[${i}]`);
      return;
    }
    for (const [key, child] of Object.entries(value)) {
      if (IMPORT_DANGEROUS_KEYS.has(key)) throw new Error(`${label} contains unsafe key "${key}"`);
      inspect(child, depth + 1, `${label}.${key}`);
    }
  };
  inspect(data, 0, 'data');

  const isRecord = value => value && typeof value === 'object' && !Array.isArray(value);
  const requiresStableReminderIds = Number.isFinite(Number(schema)) && Number(schema) >= 12;
  if (!isRecord(data) || !Array.isArray(data.workspaces) || !data.workspaces.length) {
    throw new Error('Backup must contain at least one workspace');
  }
  if (data.settings != null && !isRecord(data.settings)) throw new Error('settings must be an object');
  if (data.archive != null && !Array.isArray(data.archive)) throw new Error('archive must be an array');
  if (data.trash != null && !Array.isArray(data.trash)) throw new Error('trash must be an array');

  const activeIds = new Set();
  const registerId = (value, label, ids = activeIds) => {
    if (typeof value !== 'string' || !value || value.length > 200) throw new Error(`${label} has an invalid id`);
    if (ids.has(value)) throw new Error(`${label} reuses id "${value}"`);
    ids.add(value);
  };
  const validateUrl = (value, label) => {
    if (typeof value !== 'string' || !value) throw new Error(`${label} is missing its URL`);
    if (/^data:image\/(?:png|jpe?g|gif|webp);/i.test(value)) return;
    let parsed;
    try { parsed = new URL(value); } catch { throw new Error(`${label} has an invalid URL`); }
    if (!['http:', 'https:', 'ftp:', 'file:'].includes(parsed.protocol)) {
      throw new Error(`${label} uses unsupported URL scheme ${parsed.protocol}`);
    }
  };
  const validateItem = (item, label, ids, stackDepth = 0) => {
    if (!isRecord(item)) throw new Error(`${label} must be an object`);
    registerId(item.id, label, ids);
    if (!IMPORT_ITEM_TYPES.has(item.type)) throw new Error(`${label} has unsupported type "${item.type}"`);
    if (item.type === 'tab') validateUrl(item.url, label);
    if (item.type === 'stack') {
      if (stackDepth >= 12) throw new Error(`${label} contains stacks nested too deeply`);
      if (!Array.isArray(item.items)) throw new Error(`${label}.items must be an array`);
      item.items.forEach((child, index) => validateItem(child, `${label}.items[${index}]`, ids, stackDepth + 1));
    }
  };
  const validateReminderList = (entity, label) => {
    if (entity.reminders == null) return;
    if (!Array.isArray(entity.reminders)) throw new Error(`${label}.reminders must be an array`);
    const reminderIds = new Set();
    entity.reminders.forEach((reminder, index) => {
      const reminderLabel = `${label}.reminders[${index}]`;
      if (!isRecord(reminder)) throw new Error(`${reminderLabel} must be an object`);
      if (requiresStableReminderIds) registerId(reminder.id, reminderLabel, reminderIds);
    });
  };
  const validateGroup = (group, label, ids) => {
    if (!isRecord(group)) throw new Error(`${label} must be an object`);
    registerId(group.id, label, ids);
    validateReminderList(group, label);
    if (!Array.isArray(group.items)) throw new Error(`${label}.items must be an array`);
    group.items.forEach((item, index) => validateItem(item, `${label}.items[${index}]`, ids));
  };

  data.workspaces.forEach((workspace, wi) => {
    const wp = `workspaces[${wi}]`;
    if (!isRecord(workspace)) throw new Error(`${wp} must be an object`);
    registerId(workspace.id, wp);
    if (!Array.isArray(workspace.categories) || !workspace.categories.length) {
      throw new Error(`${wp} must contain at least one category`);
    }
    workspace.categories.forEach((category, ci) => {
      const cp = `${wp}.categories[${ci}]`;
      if (!isRecord(category)) throw new Error(`${cp} must be an object`);
      registerId(category.id, cp);
      validateReminderList(category, cp);
      if (!Array.isArray(category.groups)) throw new Error(`${cp}.groups must be an array`);
      category.groups.forEach((group, gi) => validateGroup(group, `${cp}.groups[${gi}]`, activeIds));
    });
  });

  for (const [collectionName, collection] of [['archive', data.archive || []], ['trash', data.trash || []]]) {
    collection.forEach((entry, index) => {
      const label = `${collectionName}[${index}]`;
      if (!isRecord(entry) || !['item', 'group'].includes(entry.kind) || !isRecord(entry.data)) {
        throw new Error(`${label} is not a valid archived entry`);
      }
      const ids = new Set();
      if (entry.kind === 'group') validateGroup(entry.data, `${label}.data`, ids);
      else validateItem(entry.data, `${label}.data`, ids);
    });
  }
}

function sanitizeImportedRichText(value, depth = 0) {
  if (!value || typeof value !== 'object' || depth > MAX_IMPORT_DEPTH) return;
  for (const [key, child] of Object.entries(value)) {
    if ((key === 'html' || key === 'readme' || key === 'annotation') && typeof child === 'string') {
      value[key] = sanitizeHtml(child);
    } else if (child && typeof child === 'object') {
      sanitizeImportedRichText(child, depth + 1);
    }
  }
}

function localizeImportDiagnosticPath(label) {
  const raw = String(label || '').trim();
  if (!raw) return tr('import.path.data');
  const parts = [];
  const tokenPattern = /(?:^|\.)([A-Za-z_$][\w$]*)(?:\[(\d+)\])?/g;
  let token;
  while ((token = tokenPattern.exec(raw))) {
    const name = token[1];
    const position = token[2] == null ? null : Number(token[2]) + 1;
    if (name === 'data') {
      parts.push(tr(parts.length ? 'import.path.content' : 'import.path.data'));
    } else if (name === 'settings') {
      parts.push(tr('import.path.settings'));
    } else if (name === 'workspaces') {
      parts.push(position == null
        ? tr('import.path.workspaces')
        : tr('import.path.workspace', { position }));
    } else if (name === 'categories') {
      parts.push(position == null
        ? tr('import.path.spaces')
        : tr('import.path.space', { position }));
    } else if (name === 'groups') {
      parts.push(position == null
        ? tr('import.path.groups')
        : tr('import.path.group', { position }));
    } else if (name === 'items') {
      parts.push(position == null
        ? tr('import.path.items')
        : tr('import.path.item', { position }));
    } else if (name === 'reminders') {
      parts.push(position == null
        ? tr('import.path.reminders')
        : tr('import.path.reminder', { position }));
    } else if (name === 'archive') {
      parts.push(position == null
        ? tr('import.path.archive')
        : tr('import.path.archiveEntry', { position }));
    } else if (name === 'trash') {
      parts.push(position == null
        ? tr('import.path.trash')
        : tr('import.path.trashEntry', { position }));
    } else {
      parts.push(position == null ? name : `${name} ${position}`);
    }
  }
  return parts.join(' › ') || raw;
}

function localizeImportValidationError(error) {
  const message = String(error?.message || error || '').trim();
  let match;
  const withPath = (key, label, vars = {}) => tr(key, {
    path: localizeImportDiagnosticPath(label),
    ...vars,
  });

  if ((match = /^This backup uses newer schema (.+)\. Update Locus before importing it\.$/.exec(message))) {
    return tr('import.error.newerSchema', { schema: match[1] });
  }
  if (message === 'Backup contains too many values') return tr('import.error.tooManyValues');
  if (message === 'Backup must contain at least one workspace') return tr('import.error.workspaceRequired');
  if (message === 'settings must be an object') return tr('import.error.settingsObject');
  if (message === 'archive must be an array') return tr('import.error.archiveArray');
  if (message === 'trash must be an array') return tr('import.error.trashArray');
  if ((match = /^(.+) contains stacks nested too deeply$/.exec(message))) {
    return withPath('import.error.stackDepth', match[1]);
  }
  if ((match = /^(.+) is nested too deeply$/.exec(message))) {
    return withPath('import.error.nestedTooDeep', match[1]);
  }
  if ((match = /^(.+) contains an oversized text value$/.exec(message))) {
    return withPath('import.error.oversizedText', match[1]);
  }
  if ((match = /^(.+) contains unsafe key "([\s\S]*)"$/.exec(message))) {
    return withPath('import.error.unsafeKey', match[1], { key: match[2] });
  }
  if ((match = /^(.+) has an invalid id$/.exec(message))) {
    return withPath('import.error.invalidId', match[1]);
  }
  if ((match = /^(.+) reuses id "([\s\S]*)"$/.exec(message))) {
    return withPath('import.error.reusedId', match[1], { id: match[2] });
  }
  if ((match = /^(.+) is missing its URL$/.exec(message))) {
    return withPath('import.error.missingUrl', match[1]);
  }
  if ((match = /^(.+) has an invalid URL$/.exec(message))) {
    return withPath('import.error.invalidUrl', match[1]);
  }
  if ((match = /^(.+) uses unsupported URL scheme (.+)$/.exec(message))) {
    return withPath('import.error.unsupportedScheme', match[1], { scheme: match[2] });
  }
  if ((match = /^(.+) has unsupported type "([\s\S]*)"$/.exec(message))) {
    return withPath('import.error.unsupportedType', match[1], { type: match[2] });
  }
  if ((match = /^(workspaces\[\d+\]) must contain at least one category$/.exec(message))) {
    return withPath('import.error.spaceRequired', match[1]);
  }
  if ((match = /^(.+) must be an object$/.exec(message))) {
    return withPath('import.error.objectRequired', match[1]);
  }
  if ((match = /^(.+) must be an array$/.exec(message))) {
    return withPath('import.error.arrayRequired', match[1]);
  }
  if ((match = /^(.+) is not a valid archived entry$/.exec(message))) {
    return withPath('import.error.archivedEntry', match[1]);
  }

  const localizedPaths = message.replace(
    /\b(?:data|settings|workspaces(?:\[\d+\])?|archive(?:\[\d+\])?|trash(?:\[\d+\])?)(?:\.[A-Za-z_$][\w$]*(?:\[\d+\])?)*/g,
    path => localizeImportDiagnosticPath(path),
  );
  return localizedPaths.split(/("[^"]*")/g).map((part, index) => (
    index % 2
      ? part
      : part
        .replace(/\bcategories\b/gi, tr('import.term.spaces'))
        .replace(/\bcategory\b/gi, tr('import.term.space'))
  )).join('');
}

function importCountPhrase(count, oneKey, manyKey) {
  return tr(Number(count) === 1 ? oneKey : manyKey, { count: Number(count) || 0 });
}

function importJSON(file, opener = null) {
  if (!file) {
    setDataTransferFileStatus('settings.dataChooseStatus');
    resetImportFileInput();
    return false;
  }
  const generation = ++importReadGeneration;
  const filename = String(file.name || 'backup.json');
  const fail = (key, vars = {}, duration = 5000) => {
    if (generation !== importReadGeneration) return false;
    setDataTransferFileStatus('settings.dataReviewFailed', { file: filename }, 'error');
    resetImportFileInput();
    toast(tr(key, vars), { danger: true, duration });
    return false;
  };
  if (file.size > MAX_IMPORT_BYTES) return fail('import.error.tooLarge');
  setDataTransferFileStatus('settings.dataReadingFile', { file: filename }, 'loading');
  const r = new FileReader();
  r.onload = () => {
    if (generation !== importReadGeneration) return;
    let parsed;
    try { parsed = JSON.parse(r.result); }
    catch (e) {
      const m = (e && e.message || '').match(/position (\d+)/i);
      fail(m ? 'import.error.invalidJsonAt' : 'import.error.invalidJson', {
        position: m?.[1] || '',
      });
      return;
    }
    let data, schema, exportedAt;
    if (parsed && (parsed.app === 'locus' || parsed.app === 'folio' || parsed.app === 'stow' || parsed.app === 'tabento' || parsed.app === 'tabnest' || parsed.app === 'tabextend') && parsed.data && typeof parsed.data === 'object') {
      data = parsed.data;
      schema = parsed.schema;
      exportedAt = parsed.exportedAt;
    } else if (parsed && Array.isArray(parsed.workspaces)) {
      data = parsed;
      schema = 'legacy';
    } else {
      fail('import.error.missingWorkspaces');
      return;
    }
    if (!Array.isArray(data.workspaces)) {
      fail('import.error.workspacesArray');
      return;
    }
    try {
      data = LocusImportUtils.normalizeLegacy(data, { makeId: uid, schema });
      validateImportData(data, schema);
      sanitizeImportedRichText(data);
    } catch (error) {
      fail('import.error.invalidBackup', {
        detail: localizeImportValidationError(error),
      }, 7000);
      return;
    }
    const counts = countState(data);
    importCtx = { data, counts, filename, exportedAt, schema, opener, errorKey: null };
    setDataTransferFileStatus('settings.dataReviewReady', { file: filename }, 'ready');
    if (!openImportPreview()) {
      importCtx = null;
      setDataTransferFileStatus('settings.dataReviewBlocked', { file: filename }, 'error');
      resetImportFileInput();
    }
  };
  r.onerror = () => fail('import.error.readFailed');
  r.onabort = () => fail('import.error.readFailed');
  try { r.readAsText(file); }
  catch { return fail('import.error.readFailed'); }
  return true;
}

function paintImportPreview() {
  if (!importCtx) return false;
  const { counts, filename, exportedAt, schema } = importCtx;
  const overlay = document.getElementById('import-overlay');
  const filenameElement = document.getElementById('import-filename');
  const dateElement = document.getElementById('import-date');
  const schemaElement = document.getElementById('import-schema');
  const countHost = document.getElementById('import-counts');
  const status = document.getElementById('import-status');
  const close = document.getElementById('import-x');
  const cancel = document.getElementById('import-cancel');
  const confirm = document.getElementById('import-confirm');
  if (!overlay || !filenameElement || !dateElement || !schemaElement || !countHost
    || !status || !close || !cancel || !confirm) return false;

  filenameElement.textContent = filename || '—';
  dateElement.textContent = exportedAt
    ? new Date(exportedAt).toLocaleString(appLocale())
    : tr('import.schemaUnknown');
  schemaElement.textContent =
    schema === 'legacy' ? tr('import.schemaLegacy') : (schema != null ? String(schema) : '—');
  const cells = [
    ['workspaces', 'import.count.workspaces'],
    ['categories', 'import.count.spaces'],
    ['groups', 'import.count.groups'],
    ['items', 'import.count.items'],
    ['archived', 'import.count.archived'],
    ['trashed', 'import.count.trashed']
  ];
  countHost.textContent = '';
  countHost.setAttribute('aria-label', tr('import.countsAria'));
  cells.forEach(([k, labelKey]) => {
    const el = document.createElement('div');
    el.className = 'import-count';
    el.setAttribute('role', 'listitem');
    const num = document.createElement('div');
    num.className = 'import-count-num';
    num.textContent = String(counts[k] ?? 0);
    const lblEl = document.createElement('div');
    lblEl.className = 'import-count-lbl';
    lblEl.textContent = tr(labelKey);
    el.append(num, lblEl);
    countHost.append(el);
  });

  const mode = document.querySelector('input[name="import-mode"]:checked')?.value || 'replace';
  importCtx.mode = mode;
  overlay.setAttribute('aria-busy', String(importBusy));
  for (const radio of document.querySelectorAll('input[name="import-mode"]')) radio.disabled = importBusy;
  close.disabled = importBusy;
  cancel.disabled = importBusy;
  confirm.disabled = importBusy;
  confirm.setAttribute('aria-disabled', String(importBusy));
  confirm.textContent = tr(importBusy
    ? (mode === 'merge' ? 'import.importingMerge' : 'import.importingReplace')
    : (mode === 'merge' ? 'import.confirmMerge' : 'import.confirmReplace'));
  status.textContent = tr(importCtx.errorKey || (importBusy
    ? (mode === 'merge' ? 'import.importingMerge' : 'import.importingReplace')
    : 'import.ready'));
  status.dataset.state = importCtx.errorKey ? 'error' : (importBusy ? 'loading' : 'idle');
  return true;
}

function setImportBusy(busy) {
  importBusy = !!busy;
  paintImportPreview();
}

function setImportInterlock(enabled) {
  const overlay = document.getElementById('import-overlay');
  const recovery = document.getElementById('state-recovery-overlay');
  const quota = document.getElementById('quota-overlay');
  for (const child of document.body.children) {
    if (child === overlay || child === recovery || child === quota) continue;
    setElementInertOwner(child, 'json-import', enabled);
  }
}

function isImportPending() {
  return importBusy;
}

function focusImportFallback() {
  const drawer = document.getElementById('settings-drawer');
  const trigger = document.getElementById('import-json-btn');
  const target = drawer && !drawer.classList.contains('hidden') ? trigger : document.getElementById('nav-home');
  if (!target || typeof target.focus !== 'function') return false;
  try { target.focus({ preventScroll: true }); } catch { try { target.focus(); } catch {} }
  return document.activeElement === target;
}

function focusImportControl(id) {
  const element = document.getElementById(id);
  try { element?.focus({ preventScroll: true }); } catch { try { element?.focus(); } catch {} }
}

function openImportPreview() {
  const overlay = document.getElementById('import-overlay');
  if (!importCtx || !overlay || !overlay.classList.contains('hidden')) return false;
  const opener = importCtx.opener || null;
  const conflictingIds = [
    'state-recovery-overlay',
    'quota-overlay',
    'paste-overlay',
    'modal-overlay',
    'reminder-overlay',
    'calendar-task-overlay',
    'organization-name-overlay',
    'organization-delete-overlay',
    'trash-delete-overlay',
  ];
  if (conflictingIds.some(id => {
    const element = document.getElementById(id);
    return element && !element.classList.contains('hidden');
  })) return false;
  const replaceRadio = document.querySelector('input[name="import-mode"][value="replace"]');
  if (replaceRadio) replaceRadio.checked = true;
  importCtx.mode = 'replace';
  importCtx.errorKey = null;
  focusDialogOpener(opener);
  rememberOpener(overlay);
  importBusy = false;
  setImportInterlock(true);
  overlay.classList.remove('hidden');
  lockBodyScroll();
  paintImportPreview();
  requestAnimationFrame(() => {
    if (replaceRadio) {
      try { replaceRadio.focus({ preventScroll: true }); } catch { try { replaceRadio.focus(); } catch {} }
    } else focusImportControl('import-cancel');
  });
  return true;
}

function closeImportPreview({ restoreFocus = true, force = false, outcome = 'cancel' } = {}) {
  const overlay = document.getElementById('import-overlay');
  if (!overlay || overlay.classList.contains('hidden') || (importBusy && !force)) return false;
  overlay.classList.add('hidden');
  unlockBodyScroll();
  setImportInterlock(false);
  importBusy = false;
  importCtx = null;
  resetImportFileInput();
  if (outcome === 'success') {
    setDataTransferFileStatus('settings.dataImportCompleted', {}, 'success');
  } else {
    setDataTransferFileStatus('settings.dataReviewCanceled', {}, 'idle');
  }
  if (restoreFocus) {
    if (!restoreOpener(overlay)) setTimeout(focusImportFallback, 0);
  } else {
    _overlayOpeners.delete(overlay);
  }
  return true;
}

function resetSurfaceAfterImportReplace() {
  activeHome = true;
  activeSearch = null;
  activeLibraryMode = null;
  activeGroupPage = null;
  activeCalendar = null;
  boardDetailItemId = null;
  explorerSel = { groupId: null, stackPath: [], itemId: null };
  calendarFilter = '';
  selectedItemIds.clear();
  lastSelectedItemId = null;
  itemSelMode = false;
  explicitSelMode = false;
  document.body.classList.remove('detail-open', 'reorder-mode');
  document.getElementById('settings-drawer')?.classList.add('hidden');
  document.getElementById('tools-hub')?.classList.add('hidden');
  history.replaceState(null, '', '#' + Router.build({
    type: 'home',
    wsId: State.get().activeWsId,
    query: {},
  }));
}

async function applyImportReplace(data) {
  // Replace is intentionally destructive, so first start a user-owned backup
  // download of the exact current graph.
  exportJSON({ prefix: 'locus-before-import', silent: true });
  State.snapshot(tr('history.importReplace'));
  const s = State.get();
  try {
    const currentRevision = s._revision;
    const currentSettings = s.settings || {};
    const incoming = LocusImportUtils.normalizeForReplace(data, {
      makeId: uid,
      now: Date.now(),
      retentionMs: TRASH_RETENTION_MS,
    });
    const mergedSettings = {
      ...currentSettings,
      ...(incoming.settings || {}),
      onboarding: {
        ...(currentSettings.onboarding || {}),
        ...(incoming.settings?.onboarding || {}),
      },
    };
    Object.keys(s).forEach(key => { if (key !== '_revision') delete s[key]; });
    Object.assign(s, incoming);
    s._revision = currentRevision;
    s.settings = mergedSettings;
    s.archive = Array.isArray(incoming.archive) ? incoming.archive : [];
    s.trash = Array.isArray(incoming.trash) ? incoming.trash : [];
    s.recentEmoji = Array.isArray(incoming.recentEmoji) ? incoming.recentEmoji : [];
    s.columnWidths = incoming.columnWidths && typeof incoming.columnWidths === 'object' ? incoming.columnWidths : {};
    migrate();
    await State.persistNow();
  } catch (error) {
    State.rollbackSnapshot();
    renderAll();
    handleStorageError(error);
    return false;
  }
  resetSurfaceAfterImportReplace();
  applySettings();
  renderAll();
  const c = countState(s);
  toast(tr('import.success.replace', {
    workspaces: importCountPhrase(c.workspaces, 'import.count.workspaceOne', 'import.count.workspaceMany'),
    items: importCountPhrase(c.items, 'import.count.itemOne', 'import.count.itemMany'),
  }), { undo: true });
  chrome.runtime.sendMessage({ type: 'reconcile-reminders' })
    .then(result => {
      if (result?.ok === false) toast(tr('import.warning.replaceReminders'), { tone: 'warning', duration: 8000 });
    })
    .catch(() => {
      toast(tr('import.warning.replaceRestart'), { tone: 'warning', duration: 8000 });
    });
  return true;
}

async function applyImportMerge(data) {
  const s = State.get();
  const before = countState(s);
  State.snapshot(tr('history.importMerge'));
  let addedWs = 0;
  try {
    const prepared = LocusImportUtils.prepareMerge(data, s, {
      makeId: uid,
      now: Date.now(),
      retentionMs: TRASH_RETENTION_MS,
    });
    addedWs = prepared.workspaces.length;
    s.workspaces.push(...prepared.workspaces);
    s.archive = s.archive || [];
    s.archive.push(...prepared.archive);
    s.trash = s.trash || [];
    s.trash.push(...prepared.trash);
    if (Array.isArray(data.recentEmoji)) {
      s.recentEmoji = s.recentEmoji || [];
      const seen = new Set(s.recentEmoji);
      for (const e of data.recentEmoji) if (!seen.has(e)) { s.recentEmoji.push(e); seen.add(e); }
    }
    s.columnWidths = { ...(s.columnWidths || {}), ...prepared.columnWidths };
    if (Object.keys(prepared.columnSizes).length) {
      s.columnSizes = { ...(s.columnSizes || {}), ...prepared.columnSizes };
    }
    migrate();
    await State.persistNow();
  } catch (error) {
    State.rollbackSnapshot();
    renderAll();
    handleStorageError(error);
    return false;
  }
  renderAll();
  const after = countState(s);
  const addedItems = after.items - before.items;
  toast(tr('import.success.merge', {
    workspaces: importCountPhrase(addedWs, 'import.count.workspaceOne', 'import.count.workspaceMany'),
    items: importCountPhrase(addedItems, 'import.count.itemOne', 'import.count.itemMany'),
  }), { undo: true });
  chrome.runtime.sendMessage({ type: 'reconcile-reminders' })
    .then(result => {
      if (result?.ok === false) toast(tr('import.warning.mergeReminders'), { tone: 'warning', duration: 8000 });
    })
    .catch(() => {
      toast(tr('import.warning.mergeRestart'), { tone: 'warning', duration: 8000 });
    });
  return true;
}

async function confirmImportPreview() {
  if (!importCtx || importBusy) return false;
  const mode = document.querySelector('input[name="import-mode"]:checked')?.value || 'replace';
  const { data } = importCtx;
  importCtx.mode = mode;
  importCtx.errorKey = null;
  setImportBusy(true);
  let applied = false;
  try {
    applied = mode === 'merge'
      ? await applyImportMerge(data)
      : await applyImportReplace(data);
  } catch (error) {
    handleStorageError(error);
  }
  setImportBusy(false);
  if (!applied) {
    if (importCtx) importCtx.errorKey = 'import.saveFailed';
    paintImportPreview();
    const recovery = document.getElementById('state-recovery-overlay');
    const quota = document.getElementById('quota-overlay');
    const recoveryOwnsFocus = (recovery && !recovery.classList.contains('hidden'))
      || (quota && !quota.classList.contains('hidden'));
    if (!recoveryOwnsFocus) focusImportControl('import-confirm');
    return false;
  }
  const replaced = mode !== 'merge';
  closeImportPreview({ restoreFocus: !replaced, outcome: 'success' });
  if (replaced) setTimeout(focusImportFallback, 0);
  return true;
}

function handleImportGlobalKey(event) {
  const overlay = document.getElementById('import-overlay');
  if (!overlay || overlay.classList.contains('hidden')) return false;
  for (const id of ['state-recovery-overlay', 'quota-overlay']) {
    const upper = document.getElementById(id);
    if (upper && !upper.classList.contains('hidden') && upper.contains(event.target)) return false;
  }
  if (overlay.contains(event.target)) return true;
  event.preventDefault();
  event.stopImmediatePropagation();
  if (!importBusy && event.key === 'Escape') closeImportPreview();
  else focusImportControl(importCtx?.mode === 'merge'
    ? 'import-confirm'
    : 'import-cancel');
  return true;
}

function bindImportUI() {
  const overlay = document.getElementById('import-overlay');
  if (!overlay || overlay.dataset.bound === '1') return;
  overlay.dataset.bound = '1';
  document.getElementById('import-x').onclick = () => closeImportPreview();
  document.getElementById('import-cancel').onclick = () => closeImportPreview();
  overlay.addEventListener('click', event => {
    if (event.target === overlay && !importBusy) closeImportPreview();
  });
  overlay.addEventListener('keydown', event => {
    if (importBusy) {
      if (event.key === 'Tab') trapTabKey(event, overlay);
      else event.preventDefault();
      event.stopPropagation();
      return;
    }
    if (event.key === 'Escape') {
      event.preventDefault();
      event.stopPropagation();
      closeImportPreview();
      return;
    }
    if (event.key === 'Tab') trapTabKey(event, overlay);
    event.stopPropagation();
  });
  document.querySelectorAll('input[name="import-mode"]').forEach(radio => {
    radio.addEventListener('change', paintImportPreview);
  });
  document.getElementById('import-confirm').onclick = confirmImportPreview;
}

// ════════════════════════════════════════════════════════════════
// PASTE LINKS IMPORT
// ════════════════════════════════════════════════════════════════
let pasteImportCtx = null;
let pasteImportBusy = false;

function analyzePastedLinks(text) {
  const urls = [];
  const seen = new Set();
  let skipped = 0;
  for (const rawLine of String(text || '').split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line) continue;
    let valid = false;
    try {
      const url = new URL(line);
      valid = url.protocol === 'http:' || url.protocol === 'https:';
    } catch {}
    if (!valid || seen.has(line)) {
      skipped += 1;
      continue;
    }
    seen.add(line);
    urls.push(line);
  }
  return { urls, skipped };
}

function parsePastedLinks(text) {
  return analyzePastedLinks(text).urls;
}

function pasteImportGroupOptions(target) {
  if (!target || !Array.isArray(target.space?.groups)) return null;
  const nameCounts = new Map();
  for (const group of target.space.groups) {
    if (!group || !Array.isArray(group.items)) return null;
    const name = String(group?.name || '');
    nameCounts.set(name, (nameCounts.get(name) || 0) + 1);
  }
  const namePositions = new Map();
  const options = [];
  const seenIds = new Set();
  for (const group of target.space.groups) {
    const id = String(group?.id || '');
    const exact = id ? identityGroupTarget(id) : null;
    if (!id || seenIds.has(id)
      || exact?.workspace !== target.workspace
      || exact?.space !== target.space
      || exact?.group !== group) return null;
    seenIds.add(id);
    const name = String(group.name || '');
    const position = (namePositions.get(name) || 0) + 1;
    namePositions.set(name, position);
    options.push({
      id,
      name,
      symbol: String(group.symbol || ''),
      ref: group,
      duplicateName: (nameCounts.get(name) || 0) > 1,
      position,
      count: nameCounts.get(name) || 1,
    });
  }
  return options;
}

function createPasteImportContext({ workspaceId = null, spaceId = null } = {}) {
  const activeWorkspace = activeWs();
  const activeSpace = activeCat();
  const reviewedWorkspaceId = String(workspaceId ?? activeWorkspace?.id ?? '');
  const reviewedSpaceId = String(spaceId ?? activeSpace?.id ?? '');
  const target = reviewedWorkspaceId && reviewedSpaceId
    ? identitySpaceTarget(reviewedWorkspaceId, reviewedSpaceId)
    : null;
  const activeRefsMatch = workspaceId != null || spaceId != null
    || (target?.workspace === activeWorkspace && target?.space === activeSpace);
  if (!target || !activeRefsMatch) {
    return {
      workspaceId: reviewedWorkspaceId,
      spaceId: reviewedSpaceId,
      workspaceName: String(activeWorkspace?.name || ''),
      spaceName: String(activeSpace?.name || ''),
      workspaceRef: null,
      spaceRef: null,
      groupOptions: [],
      selectedGroupId: '__new__',
      errorKey: 'paste.spaceUnavailable',
      unavailable: true,
    };
  }
  const groupOptions = pasteImportGroupOptions(target);
  return {
    workspaceId: reviewedWorkspaceId,
    spaceId: reviewedSpaceId,
    workspaceName: String(target.workspace.name || ''),
    spaceName: String(target.space.name || ''),
    workspaceRef: target.workspace,
    spaceRef: target.space,
    groupOptions: groupOptions || [],
    selectedGroupId: groupOptions?.[0]?.id || '__new__',
    errorKey: groupOptions ? null : 'paste.destinationUnavailable',
    unavailable: !groupOptions,
  };
}

function pasteImportTarget() {
  if (!pasteImportCtx?.workspaceId || !pasteImportCtx?.spaceId) return null;
  return identitySpaceTarget(pasteImportCtx.workspaceId, pasteImportCtx.spaceId);
}

function refreshPasteImportReview(errorKey = 'paste.destinationChanged') {
  if (!pasteImportCtx) return false;
  const previousSelection = pasteImportCtx.selectedGroupId;
  const refreshed = createPasteImportContext({
    workspaceId: pasteImportCtx.workspaceId,
    spaceId: pasteImportCtx.spaceId,
  });
  if (!refreshed || refreshed.unavailable) {
    pasteImportCtx = refreshed || {
      ...pasteImportCtx,
      errorKey: 'paste.spaceUnavailable',
      unavailable: true,
    };
    paintPasteImportDialog();
    return false;
  }
  if (previousSelection === '__new__'
    || refreshed.groupOptions.some(option => option.id === previousSelection)) {
    refreshed.selectedGroupId = previousSelection;
  }
  refreshed.errorKey = errorKey;
  pasteImportCtx = refreshed;
  paintPasteImportDialog();
  return true;
}

function pasteImportOptionLabel(option) {
  const name = option.name || tr('paste.defaultGroupName');
  const label = option.duplicateName
    ? tr('paste.duplicateGroup', {
        name,
        position: option.position,
        count: option.count,
      })
    : name;
  return `${option.symbol ? `${option.symbol} ` : ''}${label}`;
}

function setPasteImportError(errorKey = '', { unavailable = false } = {}) {
  if (!pasteImportCtx) return;
  pasteImportCtx.errorKey = errorKey || null;
  pasteImportCtx.unavailable = !!unavailable;
  paintPasteImportDialog();
}

function paintPasteImportDialog() {
  const overlay = document.getElementById('paste-overlay');
  const area = document.getElementById('paste-area');
  const dest = document.getElementById('paste-dest');
  const nameField = document.getElementById('paste-group-name-field');
  const nameInput = document.getElementById('paste-group-name');
  const preview = document.getElementById('paste-preview');
  const status = document.getElementById('paste-status');
  const spaceContext = document.getElementById('paste-space-context');
  const close = document.getElementById('paste-x');
  const cancel = document.getElementById('paste-cancel');
  const confirm = document.getElementById('paste-go');
  if (!overlay || !area || !dest || !nameField || !nameInput
    || !preview || !status || !spaceContext || !close || !cancel || !confirm) return;

  const analysis = analyzePastedLinks(area.value);
  const count = analysis.urls.length;
  const typed = !!area.value.trim();
  const selected = pasteImportCtx?.selectedGroupId || '__new__';
  const options = pasteImportCtx?.groupOptions || [];

  dest.replaceChildren();
  for (const option of options) {
    const element = document.createElement('option');
    element.value = option.id;
    element.textContent = pasteImportOptionLabel(option);
    dest.appendChild(element);
  }
  const newOption = document.createElement('option');
  newOption.value = '__new__';
  newOption.textContent = tr('paste.newGroup');
  dest.appendChild(newOption);
  dest.value = options.some(option => option.id === selected) ? selected : '__new__';
  if (pasteImportCtx) pasteImportCtx.selectedGroupId = dest.value;

  const isNewGroup = dest.value === '__new__';
  nameField.classList.toggle('hidden', !isNewGroup);
  spaceContext.textContent = pasteImportCtx
      && (pasteImportCtx.workspaceName || pasteImportCtx.spaceName)
    ? tr('paste.location', {
        workspace: pasteImportCtx.workspaceName,
        space: pasteImportCtx.spaceName,
      })
    : '';
  if (!typed) preview.textContent = '';
  else if (!count) preview.textContent = tr('paste.noneValid');
  else preview.textContent = tr(analysis.skipped ? 'paste.readySkipped' : 'paste.ready', {
    count,
    skipped: analysis.skipped,
  });
  status.textContent = pasteImportCtx?.errorKey ? tr(pasteImportCtx.errorKey) : '';
  if (pasteImportCtx?.errorKey) status.dataset.tone = 'error';
  else delete status.dataset.tone;

  const unavailable = !pasteImportCtx || !!pasteImportCtx.unavailable;
  overlay.setAttribute('aria-busy', String(pasteImportBusy));
  area.readOnly = pasteImportBusy;
  nameInput.readOnly = pasteImportBusy;
  dest.disabled = pasteImportBusy || unavailable;
  close.disabled = pasteImportBusy;
  cancel.disabled = pasteImportBusy;
  nameInput.disabled = unavailable;
  confirm.disabled = pasteImportBusy || unavailable || count === 0;
  confirm.setAttribute('aria-disabled', String(confirm.disabled));
  confirm.textContent = pasteImportBusy
    ? tr('paste.importing')
    : tr(count === 1 ? 'paste.importOne' : 'paste.importMany', { count });
  area.setAttribute('aria-invalid', String(typed && count === 0));
  dest.setAttribute('aria-invalid', String(unavailable));
}

function setPasteImportBusy(busy) {
  pasteImportBusy = !!busy;
  paintPasteImportDialog();
  if (pasteImportBusy) {
    const area = document.getElementById('paste-area');
    try { area?.focus({ preventScroll: true }); } catch { try { area?.focus(); } catch {} }
  }
}

function setPasteImportInterlock(enabled) {
  const overlay = document.getElementById('paste-overlay');
  const recovery = document.getElementById('state-recovery-overlay');
  for (const child of document.body.children) {
    if (child === overlay || child === recovery) continue;
    setElementInertOwner(child, 'paste-import', enabled);
  }
}

function isPasteImportPending() {
  return pasteImportBusy;
}

function focusPasteImportFallback() {
  const fallback = document.getElementById('paste-import-btn');
  if (!fallback || typeof fallback.focus !== 'function') return false;
  try { fallback.focus({ preventScroll: true }); } catch { try { fallback.focus(); } catch {} }
  return document.activeElement === fallback;
}

function openPasteOverlay(opener) {
  const overlay = document.getElementById('paste-overlay');
  if (!overlay || !overlay.classList.contains('hidden')) return false;
  const conflictingIds = [
    'state-recovery-overlay',
    'reminder-overlay',
    'modal-overlay',
    'import-overlay',
    'organization-name-overlay',
    'organization-delete-overlay',
    'trash-delete-overlay',
  ];
  if (conflictingIds.some(id => {
    const element = document.getElementById(id);
    return element && !element.classList.contains('hidden');
  })) return false;
  const area = document.getElementById('paste-area');
  const nameInput = document.getElementById('paste-group-name');
  const explicitOpener = opener?.currentTarget || opener;
  focusDialogOpener(explicitOpener);
  rememberOpener(overlay);
  pasteImportCtx = createPasteImportContext();
  pasteImportBusy = false;
  area.value = '';
  nameInput.value = '';
  setPasteImportInterlock(true);
  overlay.classList.remove('hidden');
  lockBodyScroll();
  paintPasteImportDialog();
  requestAnimationFrame(() => {
    const initial = pasteImportCtx?.unavailable
      ? document.getElementById('paste-cancel')
      : area;
    try { initial?.focus({ preventScroll: true }); } catch { try { initial?.focus(); } catch {} }
  });
  return true;
}

function closePasteOverlay({ restoreFocus = true } = {}) {
  const overlay = document.getElementById('paste-overlay');
  if (!overlay || overlay.classList.contains('hidden') || pasteImportBusy) return false;
  overlay.classList.add('hidden');
  unlockBodyScroll();
  setPasteImportInterlock(false);
  pasteImportCtx = null;
  pasteImportBusy = false;
  if (restoreFocus && !restoreOpener(overlay)) setTimeout(focusPasteImportFallback, 0);
  else if (!restoreFocus) _overlayOpeners.delete(overlay);
  return true;
}

function focusPasteImportControl(id) {
  const element = document.getElementById(id);
  try { element?.focus({ preventScroll: true }); } catch { try { element?.focus(); } catch {} }
}

async function applyPasteImport() {
  if (!pasteImportCtx || pasteImportBusy || pasteImportCtx.unavailable) return false;
  const area = document.getElementById('paste-area');
  const dest = document.getElementById('paste-dest');
  const nameInput = document.getElementById('paste-group-name');
  const analysis = analyzePastedLinks(area.value);
  if (!analysis.urls.length) {
    paintPasteImportDialog();
    focusPasteImportControl('paste-area');
    return false;
  }
  pasteImportCtx.selectedGroupId = dest.value;

  if (State.isRecoveryRequired?.()) {
    setPasteImportError('paste.saveFailed', { unavailable: true });
    const error = new Error(tr('paste.saveFailed'));
    error.code = 'LOCUS_STATE_RECOVERY_REQUIRED';
    if (typeof showStateRecoveryRequired === 'function') showStateRecoveryRequired(error);
    return false;
  }

  let target = pasteImportTarget();
  if (!target) {
    setPasteImportError('paste.spaceUnavailable', { unavailable: true });
    focusPasteImportControl('paste-cancel');
    return false;
  }
  if (target.workspace !== pasteImportCtx.workspaceRef
    || target.space !== pasteImportCtx.spaceRef
    || String(target.workspace.name || '') !== pasteImportCtx.workspaceName
    || String(target.space.name || '') !== pasteImportCtx.spaceName) {
    const refreshed = refreshPasteImportReview();
    focusPasteImportControl(refreshed ? 'paste-dest' : 'paste-cancel');
    return false;
  }

  const destinationId = pasteImportCtx.selectedGroupId;
  const liveOptions = pasteImportGroupOptions(target);
  if (!liveOptions) {
    setPasteImportError('paste.destinationUnavailable', { unavailable: true });
    focusPasteImportControl('paste-cancel');
    return false;
  }
  let destinationOption = null;
  let targetGroup = null;
  if (destinationId !== '__new__') {
    destinationOption = pasteImportCtx.groupOptions.find(option => option.id === destinationId) || null;
    const exact = identityGroupTarget(destinationId);
    if (!destinationOption
      || exact?.workspace !== target.workspace
      || exact?.space !== target.space
      || exact?.group !== destinationOption.ref
      || String(exact.group.name || '') !== destinationOption.name
      || String(exact.group.symbol || '') !== destinationOption.symbol) {
      const refreshed = refreshPasteImportReview();
      focusPasteImportControl(refreshed ? 'paste-dest' : 'paste-cancel');
      return false;
    }
    targetGroup = exact.group;
  }

  let groupName = destinationOption?.name || nameInput.value.trim() || tr('paste.defaultGroupName');
  let importedItems;
  let newGroup = null;
  try {
    const allocateId = createOrganizationIdAllocator();
    if (destinationId === '__new__') {
      newGroup = {
        id: allocateId(),
        name: groupName,
        symbol: '📋',
        color: '#6366f1',
        collapsed: false,
        items: [],
      };
      targetGroup = newGroup;
    }
    importedItems = analysis.urls.map(url => {
      let host = '';
      try { host = new URL(url).hostname; } catch {}
      return stampNew({
        id: allocateId(),
        type: 'tab',
        url,
        title: host || url,
        fav: favUrl(url),
      });
    });
  } catch {
    setPasteImportError('paste.prepareFailed');
    return false;
  }

  setPasteImportBusy(true);
  const historyKey = analysis.urls.length === 1 ? 'paste.historyOne' : 'paste.historyMany';
  let actionId;
  try {
    actionId = State.snapshot(tr(historyKey, {
      count: analysis.urls.length,
      group: groupName,
    }));
    if (newGroup) target.space.groups.push(newGroup);
    targetGroup.items.push(...importedItems);
  } catch (error) {
    State.requireRecovery?.();
    setPasteImportBusy(false);
    setPasteImportError('paste.saveFailed', { unavailable: true });
    if (typeof showStateRecoveryRequired === 'function') showStateRecoveryRequired(error);
    return false;
  }

  try {
    await State.persistNow();
  } catch (error) {
    setPasteImportBusy(false);
    setPasteImportError('paste.saveFailed', { unavailable: true });
    if (State.isRecoveryRequired?.() && typeof showStateRecoveryRequired === 'function') {
      showStateRecoveryRequired(error);
    }
    return false;
  }

  renderAll();
  setPasteImportBusy(false);
  closePasteOverlay();
  const successKey = analysis.urls.length === 1 ? 'paste.successOne' : 'paste.successMany';
  toast(tr(successKey, {
    count: analysis.urls.length,
    group: groupName,
  }), { undo: actionId });
  return true;
}

function handlePasteImportGlobalKey(event) {
  const overlay = document.getElementById('paste-overlay');
  if (!overlay || overlay.classList.contains('hidden')) return false;
  const recovery = document.getElementById('state-recovery-overlay');
  if (recovery && !recovery.classList.contains('hidden') && recovery.contains(event.target)) return false;
  const inside = overlay.contains(event.target);
  if (inside) return true;
  event.preventDefault();
  event.stopImmediatePropagation();
  if (!pasteImportBusy && event.key === 'Escape') closePasteOverlay();
  else focusPasteImportControl(pasteImportCtx?.unavailable ? 'paste-cancel' : 'paste-area');
  return true;
}

function bindPasteImportUI() {
  const overlay = document.getElementById('paste-overlay');
  if (!overlay || overlay.dataset.bound === '1') return;
  overlay.dataset.bound = '1';
  const area = document.getElementById('paste-area');
  const btn = document.getElementById('paste-go');
  const dest = document.getElementById('paste-dest');
  const nameInput = document.getElementById('paste-group-name');

  document.getElementById('paste-x').onclick = () => closePasteOverlay();
  document.getElementById('paste-cancel').onclick = () => closePasteOverlay();
  overlay.addEventListener('click', event => {
    if (event.target === overlay && !pasteImportBusy) closePasteOverlay();
  });
  overlay.addEventListener('keydown', event => {
    if (pasteImportBusy) {
      if (event.key === 'Tab') trapTabKey(event, overlay);
      else event.preventDefault();
      event.stopPropagation();
      return;
    }
    if (event.key === 'Escape') {
      event.preventDefault();
      event.stopPropagation();
      closePasteOverlay();
      return;
    }
    if (event.key === 'Tab') trapTabKey(event, overlay);
    event.stopPropagation();
  });

  area.addEventListener('input', () => {
    if (pasteImportCtx && !pasteImportCtx.unavailable) pasteImportCtx.errorKey = null;
    paintPasteImportDialog();
  });

  dest.addEventListener('change', () => {
    if (!pasteImportCtx || pasteImportBusy) return;
    pasteImportCtx.selectedGroupId = dest.value;
    pasteImportCtx.errorKey = null;
    paintPasteImportDialog();
    if (dest.value === '__new__') focusPasteImportControl('paste-group-name');
  });
  nameInput.addEventListener('input', () => {
    if (pasteImportCtx && !pasteImportCtx.unavailable) pasteImportCtx.errorKey = null;
    paintPasteImportDialog();
  });

  btn.onclick = () => { void applyPasteImport(); };

  document.getElementById('paste-import-btn').onclick = event => openPasteOverlay(event.currentTarget);
}

// ════════════════════════════════════════════════════════════════
// REMINDER UI bind
// ════════════════════════════════════════════════════════════════
// Route a picker commit to the item or entity write path, carrying the label
// (entities only) and the chosen recurrence.
function commitReminderSet(ts, recur) {
  const c = reminderCtx; if (!c) return;
  if (c.kind === 'item' && c.detailContext) {
    return commitItemDetailReminderMutation(c.detailContext, { at: ts, recur }, { fromPicker: true });
  }
  if (c.kind === 'item' && c.mutationContext) {
    return commitItemReminderMutation(c.mutationContext, { at: ts, recur }, { fromPicker: true });
  }
  if (c.kind === 'item') return false;
  if (c.mutationContext) {
    const label = (document.getElementById('rm-label')?.value || '').trim();
    return commitEntityReminderMutation(
      c.mutationContext,
      { at: ts, label, recur },
      { fromPicker: true },
    );
  }
  return false;
}
function commitReminderClear() {
  const c = reminderCtx; if (!c) return;
  if (c.kind === 'item' && c.detailContext) {
    return commitItemDetailReminderMutation(c.detailContext, null, { fromPicker: true });
  }
  if (c.kind === 'item' && c.mutationContext) {
    return commitItemReminderMutation(c.mutationContext, null, { fromPicker: true });
  }
  if (c.kind === 'item') return false;
  else if (c.removalContext) return commitEntityReminderRemoval(c.removalContext);
}
function bindReminderUI() {
  const overlay = document.getElementById('reminder-overlay');
  document.getElementById('rm-x').onclick = closeReminderPicker;
  document.getElementById('rm-clear').onclick = () => {
    if (reminderCtx?.unavailable) return;
    clearReminderTimeError();
    const receiptCommit = reminderCtx?.kind === 'item'
      || !!reminderCtx?.removalContext;
    const result = commitReminderClear();
    if (receiptCommit) void result;
    else closeReminderPicker();
  };
  document.getElementById('rm-save').onclick = () => {
    if (!reminderCtx || reminderCtx.unavailable) return;
    const dt = document.getElementById('rm-datetime').value;
    if (!dt) { showReminderTimeError(); return; }
    const ts = new Date(dt).getTime();
    if (isNaN(ts) || ts <= Date.now()) { showReminderTimeError(); return; }
    clearReminderTimeError();
    const receiptCommit = reminderCtx.kind === 'item' || !!reminderCtx.mutationContext;
    const result = commitReminderSet(ts, readRecurControl());
    if (receiptCommit) void result;
    else closeReminderPicker();
  };
  document.querySelectorAll('.rm-quick button').forEach(b => {
    b.onclick = () => {
      if (!reminderCtx || reminderCtx.unavailable) return;
      clearReminderTimeError();
      const receiptCommit = reminderCtx.kind === 'item' || !!reminderCtx.mutationContext;
      const result = commitReminderSet(Date.now() + (+b.dataset.offset), readRecurControl());
      if (receiptCommit) void result;
      else closeReminderPicker();
    };
  });
  document.getElementById('rm-datetime').addEventListener('input', clearReminderTimeError);
  overlay.addEventListener('keydown', e => {
    if (e.key === 'Tab') {
      trapTabKey(e, overlay);
      return;
    }
    if (isReminderMutationPending()) {
      e.preventDefault();
      e.stopImmediatePropagation();
      return;
    }
    if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); closeReminderPicker(); }
  }, true);
  overlay.addEventListener('click', e => {
    if (isReminderMutationPending()) {
      e.preventDefault();
      e.stopImmediatePropagation();
      return;
    }
    if (e.target === overlay) closeReminderPicker();
  }, true);
  overlay.addEventListener('pointerdown', e => {
    if (!isReminderMutationPending()) return;
    e.preventDefault();
    e.stopImmediatePropagation();
  }, true);
}

// ════════════════════════════════════════════════════════════════
// SUBSCRIPTION TRACKER
// ════════════════════════════════════════════════════════════════
const CURRENCY_SYMBOL = { USD:'$', EUR:'€', GBP:'£', TWD:'NT$', JPY:'¥', CNY:'¥', KRW:'₩' };
// Very rough static FX for aggregation when mixed currencies
const FX_TO_USD = { USD:1, EUR:1.09, GBP:1.28, TWD:0.031, JPY:0.0067, CNY:0.14, KRW:0.00074 };
const SUB_CAT_META = {
  entertainment:{ icon:'🎬', label:'Entertainment' },
  productivity: { icon:'💼', label:'Productivity' },
  cloud:        { icon:'☁️', label:'Cloud & Hosting' },
  dev:          { icon:'💻', label:'Developer tools' },
  ai:           { icon:'🤖', label:'AI' },
  music:        { icon:'🎵', label:'Music' },
  news:         { icon:'📰', label:'News' },
  fitness:      { icon:'💪', label:'Fitness' },
  utilities:    { icon:'🔌', label:'Utilities' },
  other:        { icon:'📦', label:'Other' }
};

let subEditingId = null;
let subFilter = 'all';

function getSubs() {
  const s = State.get();
  if (!s.subscriptions) s.subscriptions = [];
  if (!s.subSettings) s.subSettings = { defaultCurrency: 'USD' };
  return s.subscriptions;
}

function subMonthlyCostUSD(sub) {
  if (sub.paused) return 0;
  const base = Number(sub.cost || 0) * (FX_TO_USD[sub.currency] || 1);
  const p = sub.period || 'monthly';
  if (p === 'weekly') return base * 52 / 12;
  if (p === 'yearly') return base / 12;
  if (p === 'quarterly') return base / 3;
  if (p === 'oneoff') return 0;
  return base; // monthly
}

function formatMoney(val, currency = 'USD') {
  const sym = CURRENCY_SYMBOL[currency] || '$';
  const n = Math.abs(val);
  const decimals = (currency === 'JPY' || currency === 'KRW') ? 0 : 2;
  return `${val < 0 ? '-' : ''}${sym}${n.toLocaleString(appLocale(), { minimumFractionDigits: decimals, maximumFractionDigits: decimals })}`;
}

function daysUntil(dateStr) {
  if (!dateStr) return null;
  const d = new Date(dateStr + 'T00:00');
  const today = new Date();
  today.setHours(0,0,0,0);
  return Math.round((d - today) / 86400000);
}

function openSubsTracker() {
  const ov = document.getElementById('subs-overlay');
  rememberOpener(ov);
  ov.classList.remove('hidden');
  renderSubs();
  lockBodyScroll();
  focusFirstIn(ov);
}
function closeSubsTracker() {
  const ov = document.getElementById('subs-overlay');
  ov.classList.add('hidden');
  unlockBodyScroll();
  restoreOpener(ov);
}

function renderSubs() {
  const subs = getSubs();
  const list = document.getElementById('subs-list');
  const empty = document.getElementById('subs-empty');
  const mainCur = State.get().subSettings?.defaultCurrency || 'USD';
  document.getElementById('subs-currency').value = mainCur;

  // Filter
  let filtered = subs;
  if (subFilter === 'monthly') filtered = subs.filter(s => !s.paused && (s.period === 'monthly' || s.period === 'weekly' || s.period === 'quarterly'));
  else if (subFilter === 'yearly') filtered = subs.filter(s => !s.paused && s.period === 'yearly');
  else if (subFilter === 'paused') filtered = subs.filter(s => s.paused);
  else filtered = subs;

  // Sort: active first, then by days-until ascending
  filtered = [...filtered].sort((a, b) => {
    if (a.paused !== b.paused) return a.paused ? 1 : -1;
    const ad = daysUntil(a.nextBilling) ?? 9999;
    const bd = daysUntil(b.nextBilling) ?? 9999;
    return ad - bd;
  });

  // Stats (on ALL subs, not filtered)
  const monthlyUSD = subs.reduce((a, s) => a + subMonthlyCostUSD(s), 0);
  const annualUSD = monthlyUSD * 12;
  const active = subs.filter(s => !s.paused).length;

  // Upcoming in 7 days
  let upcoming = 0;
  subs.forEach(s => {
    if (s.paused) return;
    const d = daysUntil(s.nextBilling);
    if (d != null && d >= 0 && d <= 7) upcoming += Number(s.cost || 0) * (FX_TO_USD[s.currency] || 1);
  });

  // Convert to display currency
  const toDisp = v => v / (FX_TO_USD[mainCur] || 1);
  document.getElementById('subs-monthly').textContent = formatMoney(toDisp(monthlyUSD), mainCur);
  document.getElementById('subs-annual').textContent = formatMoney(toDisp(annualUSD), mainCur);
  document.getElementById('subs-count').textContent = active;
  document.getElementById('subs-upcoming').textContent = formatMoney(toDisp(upcoming), mainCur);

  // Filter chips
  document.querySelectorAll('.subs-chip').forEach(c => c.classList.toggle('active', c.dataset.filter === subFilter));

  list.innerHTML = '';
  if (!filtered.length) {
    empty.classList.remove('hidden');
    list.style.display = 'none';
    return;
  }
  empty.classList.add('hidden');
  list.style.display = '';

  filtered.forEach(sub => {
    const row = document.createElement('div');
    row.className = 'sub-row' + (sub.paused ? ' paused' : '');
    row.style.setProperty('--sub-tint', sub.color || '#6366f1');
    row.style.setProperty('--sub-tint-bg', (sub.color || '#6366f1') + '22');
    const days = daysUntil(sub.nextBilling);
    const catMeta = SUB_CAT_META[sub.category] || SUB_CAT_META.other;
    let nextLabel = '—';
    let nextClass = '';
    if (sub.paused) { nextLabel = 'Paused'; nextClass = 'paused'; }
    else if (days != null) {
      if (days < 0) { nextLabel = `Overdue ${-days}d`; nextClass = 'due'; }
      else if (days === 0) { nextLabel = 'Today'; nextClass = 'due'; }
      else if (days === 1) { nextLabel = 'Tomorrow'; nextClass = 'soon'; }
      else if (days <= 3) { nextLabel = `In ${days} days`; nextClass = 'soon'; }
      else if (days <= 30) { nextLabel = `In ${days} days`; }
      else { const d = new Date(sub.nextBilling); nextLabel = d.toLocaleDateString(appLocale(), { month:'short', day:'numeric' }); }
    }
    const period = sub.period || 'monthly';
    const periodLabel = period === 'monthly' ? '/mo' : period === 'yearly' ? '/yr' : period === 'weekly' ? '/wk' : period === 'quarterly' ? '/qtr' : '';

    row.innerHTML = `
      <div class="sub-icon-box">${esc(sub.icon || catMeta.icon)}</div>
      <div class="sub-info">
        <div class="sub-name-row">
          <span class="sub-name">${esc(sub.name || 'Untitled')}</span>
          <span class="sub-cat-badge">${catMeta.icon} ${catMeta.label}</span>
        </div>
        <div class="sub-meta">
          <span class="sub-meta-next ${nextClass}">
            <svg width="10" height="10" viewBox="0 0 12 12" fill="none"><rect x="1.5" y="2.5" width="9" height="8" rx="1" stroke="currentColor" stroke-width="1.2"/><path d="M4 1v2M8 1v2M1.5 5h9" stroke="currentColor" stroke-width="1.2" stroke-linecap="round"/></svg>
            ${esc(nextLabel)}
          </span>
          ${sub.notes ? `<span title="${esc(sub.notes)}">📝</span>` : ''}
          ${sub.url ? `<span title="${esc(sub.url)}">🔗</span>` : ''}
        </div>
      </div>
      <div class="sub-cost">
        <div class="sub-cost-val">${formatMoney(sub.cost || 0, sub.currency || 'USD')}</div>
        <div class="sub-cost-period">${esc(periodLabel)}</div>
      </div>
      <div class="sub-actions">
        <button class="sub-action-btn" data-act="pause" title="${sub.paused ? 'Resume' : 'Pause'}">
          ${sub.paused
            ? '<svg width="11" height="11" viewBox="0 0 11 11" fill="none"><path d="M3 2l6 3.5L3 9V2z" fill="currentColor"/></svg>'
            : '<svg width="11" height="11" viewBox="0 0 11 11" fill="none"><rect x="3" y="2" width="2" height="7" fill="currentColor"/><rect x="6" y="2" width="2" height="7" fill="currentColor"/></svg>'}
        </button>
        ${sub.url ? `<button class="sub-action-btn" data-act="open" title="Open website"><svg width="11" height="11" viewBox="0 0 12 12" fill="none"><path d="M4 2.5H2a1 1 0 00-1 1v6.5A1 1 0 002 11h6.5a1 1 0 001-1V8M7 1h4m0 0v4M11 1L5.5 6.5" stroke="currentColor" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round"/></svg></button>` : ''}
        <button class="sub-action-btn" data-act="edit" title="Edit"><svg width="11" height="11" viewBox="0 0 12 12" fill="none"><path d="M8.5 1.5l2 2L4 10l-2.5.5L2 8l6.5-6.5z" stroke="currentColor" stroke-width="1.2" stroke-linejoin="round"/></svg></button>
        <button class="sub-action-btn danger" data-act="del" title="Delete"><svg width="11" height="11" viewBox="0 0 12 12" fill="none"><path d="M2 3h8M4.5 3V1.5h3V3M3 3v7a1 1 0 001 1h4a1 1 0 001-1V3" stroke="currentColor" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round"/></svg></button>
      </div>`;

    row.addEventListener('click', e => {
      const act = e.target.closest('.sub-action-btn')?.dataset.act;
      if (act === 'pause') { State.snapshot('Pause sub'); sub.paused = !sub.paused; State.persist(); renderSubs(); return; }
      if (act === 'open') { chrome.tabs.create({ url: sub.url }); return; }
      if (act === 'del') {
        // Deleting takes an Undo snapshot, so it happens at once and offers Undo.
        State.snapshot(tr('tools.history.delete', { name: sub.name }));
        const subs = getSubs(); const i = subs.findIndex(x => x.id === sub.id); if (i > -1) subs.splice(i, 1);
        State.persist(); renderSubs();
        toast(tr('tools.deleted', { name: sub.name }), { undo: true });
        return;
      }
      // default → edit
      openSubForm(sub);
    });
    list.appendChild(row);
  });
}

function openSubForm(existing) {
  subEditingId = existing?.id || null;
  document.getElementById('sub-form-title').textContent = existing ? 'Edit subscription' : 'New subscription';
  document.getElementById('sub-name').value = existing?.name || '';
  document.getElementById('sub-cost').value = existing?.cost || '';
  document.getElementById('sub-cur').value = existing?.currency || (State.get().subSettings?.defaultCurrency || 'USD');
  document.getElementById('sub-period').value = existing?.period || 'monthly';
  document.getElementById('sub-next').value = existing?.nextBilling || nextMonthStr();
  document.getElementById('sub-cat').value = existing?.category || 'entertainment';
  document.getElementById('sub-url').value = existing?.url || '';
  document.getElementById('sub-notes').value = existing?.notes || '';
  document.getElementById('sub-remind').checked = existing?.remind !== false;
  document.getElementById('sub-paused').checked = !!existing?.paused;
  const icon = document.getElementById('sub-icon-val');
  icon.textContent = existing?.icon || SUB_CAT_META[existing?.category || 'entertainment'].icon;
  delete icon.dataset.emojiChosen;
  document.querySelectorAll('#sub-color-row .csw').forEach(c => c.classList.toggle('active', c.dataset.c === (existing?.color || '#6366f1')));
  document.getElementById('sub-form-delete').style.display = existing ? '' : 'none';
  document.getElementById('sub-form').classList.remove('hidden');
  setTimeout(() => document.getElementById('sub-name').focus(), 40);
}
function closeSubForm() { document.getElementById('sub-form').classList.add('hidden'); subEditingId = null; }
function nextMonthStr() {
  const d = new Date();
  d.setMonth(d.getMonth() + 1);
  return d.toISOString().slice(0, 10);
}

async function saveSubForm() {
  const name = document.getElementById('sub-name').value.trim();
  if (!name) { toast('Name is required', { danger: true }); return; }
  const cost = parseFloat(document.getElementById('sub-cost').value) || 0;
  const currency = document.getElementById('sub-cur').value;
  const period = document.getElementById('sub-period').value;
  const nextBilling = document.getElementById('sub-next').value;
  const category = document.getElementById('sub-cat').value;
  const url = document.getElementById('sub-url').value.trim();
  const notes = document.getElementById('sub-notes').value.trim();
  const remind = document.getElementById('sub-remind').checked;
  const paused = document.getElementById('sub-paused').checked;
  const iconElement = document.getElementById('sub-icon-val');
  const icon = iconElement.textContent;
  const color = document.querySelector('#sub-color-row .csw.active')?.dataset.c || '#6366f1';

  State.snapshot(subEditingId ? 'Edit sub' : 'Add sub');
  const subs = getSubs();
  let sub;
  if (subEditingId) {
    sub = subs.find(x => x.id === subEditingId);
    if (!sub) return;
    Object.assign(sub, { name, cost, currency, period, nextBilling, category, url, notes, remind, paused, icon, color });
  } else {
    sub = { id: uid(), name, cost, currency, period, nextBilling, category, url, notes, remind, paused, icon, color };
    subs.push(sub);
  }
  // Set alarm for reminder
  try {
    await chrome.alarms.clear('te-sub-' + sub.id);
    if (!paused && remind && nextBilling) {
      const d = new Date(nextBilling + 'T09:00');
      d.setDate(d.getDate() - 3);
      if (d.getTime() > Date.now()) await chrome.alarms.create('te-sub-' + sub.id, { when: d.getTime() });
    }
  } catch {}
  if (iconElement.dataset.emojiChosen === 'true') rememberRecentEmoji(icon);
  delete iconElement.dataset.emojiChosen;
  State.persist();
  closeSubForm();
  renderSubs();
}

function deleteSubForm() {
  if (!subEditingId) return;
  const subs = getSubs();
  const i = subs.findIndex(x => x.id === subEditingId);
  const name = i > -1 ? subs[i].name : '';
  State.snapshot(tr('tools.history.delete', { name }));
  if (i > -1) subs.splice(i, 1);
  try { chrome.alarms.clear('te-sub-' + subEditingId); } catch {}
  State.persist();
  closeSubForm();
  renderSubs();
  // Like the list's delete: it happens at once and offers Undo.
  toast(tr('tools.deleted', { name }), { undo: true });
}

function bindSubs() {
  // Subscriptions are now opened from the Tools Hub (see bindToolsHub)
  document.getElementById('subs-close').onclick = closeSubsTracker;
  document.getElementById('subs-overlay').addEventListener('click', e => {
    if (e.target.id === 'subs-overlay') closeSubsTracker();
  });
  document.getElementById('subs-add-btn').onclick = () => openSubForm(null);
  document.getElementById('subs-empty-add').onclick = () => openSubForm(null);
  document.getElementById('subs-currency').onchange = e => {
    const s = State.get();
    if (!s.subSettings) s.subSettings = {};
    s.subSettings.defaultCurrency = e.target.value;
    State.persist(); renderSubs();
  };
  document.querySelectorAll('.subs-chip').forEach(c => {
    c.onclick = () => { subFilter = c.dataset.filter; renderSubs(); };
  });
  // Form
  document.getElementById('sub-form-x').onclick = closeSubForm;
  document.getElementById('sub-form-cancel').onclick = closeSubForm;
  document.getElementById('sub-form-save').onclick = saveSubForm;
  document.getElementById('sub-form-delete').onclick = deleteSubForm;
  document.getElementById('sub-form').addEventListener('click', e => {
    if (e.target.id === 'sub-form') closeSubForm();
  });
  document.getElementById('sub-icon-trigger').onclick = (e) => {
    e.stopPropagation();
    openEmojiPicker({ kind: 'sub-modal' }, e.currentTarget);
  };
  // Color row in sub form
  document.querySelectorAll('#sub-color-row .csw').forEach(c => {
    c.onclick = () => {
      document.querySelectorAll('#sub-color-row .csw').forEach(x => x.classList.remove('active'));
      c.classList.add('active');
    };
    c.setAttribute('aria-label', 'Color ' + (c.dataset.c || ''));
    enableKeyboardClick(c);
  });
  // Auto-icon when category changes (only if not manually set)
  document.getElementById('sub-cat').onchange = e => {
    if (!subEditingId) {
      const icon = document.getElementById('sub-icon-val');
      icon.textContent = SUB_CAT_META[e.target.value].icon;
      delete icon.dataset.emojiChosen;
    }
  };
}

// ════════════════════════════════════════════════════════════════
// GROUP PAGE (§4.1) — a group promoted from a modal overlay to a
// first-class, deep-linkable page with a breadcrumb and real history.
// ════════════════════════════════════════════════════════════════
// Navigate to a group's page. This is a route change (pushState), so browser
// back/forward and reload all work; the old openGroupFocus overlay is gone.
function openGroupPage(gId) {
  const info = findGroup(gId);
  if (!info) return;
  Router.navigate({ type: 'group', wsId: info.ws.id, groupId: gId, itemId: null, query: {} });
}
// Leave the group page, returning to the board it belongs to. A route change,
// so it pushes a board entry and the URL/back-forward stay consistent. We let
// Router.apply() clear activeGroupPage (nulling it here first would make apply
// see no change and skip the re-render).
function closeGroupPage() {
  const ws = activeWs();
  const cat = activeCat();
  Router.navigate({ type: 'board', wsId: ws ? ws.id : null, catId: cat ? cat.id : null, query: {} });
}

// Open the per-item detail sheet (§4.2). Group pages use an item path; Home,
// board, and library surfaces carry `?item=<id>`. Each form is deep-linkable and
// survives reload because Router.sync reflects the active selection into the URL.
function openItemDetail(id, options = {}) {
  const ws = activeWs();
  const surface = activeGroupPage
    ? { wsId: ws?.id, groupId: activeGroupPage.groupId }
    : activeLibraryMode
      ? { wsId: ws?.id, libraryMode: activeLibraryMode }
      : { wsId: ws?.id, catId: activeCat()?.id };
  const validId = activeLibraryMode
    ? libraryDetailItemIdForRoute(ws, activeLibraryState, id)
    : validDetailItemIdForSurface(id, surface);
  if (!validId) return;
  prepareItemDetailOpen(id, options.returnFocusKey, options.initialFocusKey);
  if (activeGroupPage) {
    Router.navigate({ type: 'group', wsId: State.get().activeWsId, groupId: activeGroupPage.groupId, itemId: id, query: {} });
  } else if (activeLibraryMode) {
    if (!ws) return;
    Router.navigate({
      type: 'library', wsId: ws.id, mode: activeLibraryMode,
      query: libraryRouteQuery(activeLibraryState, id),
    }, { persist: false });
  } else {
    if (!ws) return;
    const cat = activeCat();
    const query = {};
    const mode = getViewMode();
    if (mode && mode !== 'board') query.view = mode;
    query.item = id;
    Router.navigate({ type: 'board', wsId: ws.id, catId: cat ? cat.id : null, query });
  }
}
// Close the detail sheet without leaving its Home, Search, board, group, or Library surface.
// A route change keeps Back/Forward and reload semantics consistent.
function closeItemDetail() {
  if (isItemDetailMutationPending()) return false;
  if (activeGroupPage) {
    return Router.navigate({ type: 'group', wsId: State.get().activeWsId, groupId: activeGroupPage.groupId, itemId: null, query: {} });
  } else if (activeLibraryMode) {
    const ws = activeWs();
    return Router.navigate({
      type: 'library', wsId: ws ? ws.id : null, mode: activeLibraryMode,
      query: libraryRouteQuery(activeLibraryState, null),
    }, { persist: false });
  } else if (activeSearch) {
    const ws = activeWs();
    const route = searchDetailRoute(activeSearch, ws?.id, activeSearch.selectedId, false);
    return route ? Router.navigate(route, { persist: false }) : false;
  } else if (activeHome) {
    const ws = activeWs();
    return Router.navigate({ type: 'home', wsId: ws ? ws.id : null, query: {} }, { persist: false });
  } else {
    const ws = activeWs();
    const cat = activeCat();
    const query = {};
    const mode = getViewMode();
    if (mode && mode !== 'board') query.view = mode;
    return Router.navigate({ type: 'board', wsId: ws ? ws.id : null, catId: cat ? cat.id : null, query });
  }
}

function hideBreadcrumb() {
  const bar = document.getElementById('breadcrumb-bar');
  if (bar && !bar.classList.contains('hidden')) { bar.classList.add('hidden'); bar.innerHTML = ''; }
}

// Render the Workspace › Category › Group breadcrumb under the top bar. Earlier
// crumbs are clickable and route back to the board; the trailing group crumb is
// the current location.
function renderBreadcrumb(ws, cat, g) {
  const bar = document.getElementById('breadcrumb-bar');
  if (!bar) return;
  bar.classList.remove('hidden');
  bar.innerHTML = '';

  const back = document.createElement('button');
  back.className = 'bc-back';
  back.type = 'button';
  back.title = 'Back to board';
  back.innerHTML = `<svg width="12" height="12" viewBox="0 0 14 14" fill="none"><path d="M9 3L5 7l4 4" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg> Back`;
  back.onclick = closeGroupPage;
  bar.appendChild(back);

  const crumb = (label, sym, onClick) => {
    const b = document.createElement('button');
    b.className = 'bc-crumb' + (onClick ? '' : ' current');
    b.type = 'button';
    b.innerHTML = (sym ? `<span class="bc-sym">${esc(sym)}</span>` : '') + `<span>${esc(label)}</span>`;
    if (onClick) b.onclick = onClick; else b.setAttribute('aria-current', 'page');
    return b;
  };
  const sep = () => { const s = document.createElement('span'); s.className = 'bc-sep'; s.textContent = '›'; return s; };

  bar.appendChild(crumb(ws.name, ws.symbol, closeGroupPage));
  bar.appendChild(sep());
  bar.appendChild(crumb(cat.name, null, () => {
    // Selecting the category returns to the board with that category active
    // (Router.apply clears the group-page surface for a board route).
    Router.navigate({ type: 'board', wsId: ws.id, catId: cat.id, query: {} });
  }));
  bar.appendChild(sep());
  bar.appendChild(crumb(g.name, g.symbol, null));
}

// Render the active group page into #board. Returns false (leaving the board to
// render) when the group no longer exists or the user has navigated to a
// different workspace/category — which is how a category-tab click or a
// workspace switch transparently exits the page without per-call-site patches.
function renderGroupPage() {
  const info = activeGroupPage ? findGroup(activeGroupPage.groupId) : null;
  const cat = activeCat();
  if (!info || !cat || info.cat.id !== cat.id || info.ws.id !== State.get().activeWsId) {
    activeGroupPage = null;
    return false;
  }
  const g = info.group;
  // The Inbox has its own page: a triage card over clean rows.
  if (isInboxPageGroup(g)) return renderInboxPage(info);

  renderBreadcrumb(info.ws, cat, g);

  const $b = document.getElementById('board');
  $b.classList.remove('list-mode', 'canvas-mode', 'explorer-mode', 'timeline-mode', 'calendar-mode');
  $b.classList.add('group-page-mode');
  $b.innerHTML = '';

  const page = document.createElement('div');
  page.className = 'group-page';

  // Description / README — rich text reusing the note editor (so the RT toolbar
  // works on selection); its own placeholder overrides the note default.
  const readme = document.createElement('div');
  readme.className = 'gp-readme';
  readme.innerHTML = `<div class="gp-readme-editor note-text" contenteditable="true" spellcheck="false">${sanitizeHtml(g.readme || '')}</div>`;
  const rmEd = readme.querySelector('.gp-readme-editor');
  let rmDirty = false;
  rmEd.addEventListener('input', () => { rmDirty = true; });
  rmEd.addEventListener('blur', () => {
    if (isRichTextLinkEditorOwned(rmEd)) return;
    if (!rmDirty) return;
    rmDirty = false;
    const html = sanitizeHtml(rmEd.innerHTML.trim());
    if (html !== (g.readme || '')) { State.snapshot('Edit group description'); g.readme = html; State.persist(); }
  });
  page.appendChild(readme);

  // The group's own reminders (§6) — e.g. "review this reading list every
  // Friday" — listed with edit/remove and an add affordance.
  const rem = document.createElement('div');
  rem.className = 'gp-reminders';
  renderGroupReminders(rem, g);
  page.appendChild(rem);

  // The group's items, reusing the fully-wired bento column (drag/drop, add
  // buttons, context menu, reminders all keep working), sized to the page.
  const body = document.createElement('div');
  body.className = 'gp-body';
  const col = buildGroupCol(g, { forceExpanded: true });
  col.classList.add('gcol-focused');
  body.appendChild(col);
  page.appendChild(body);

  $b.appendChild(page);
  applySearchFilter();
  return true;
}

// The reminders strip on a group page: a header with an add button, then one
// row per reminder with its next fire time, recurrence, and edit/remove.
function renderGroupReminders(container, g) {
  container.innerHTML = '';
  container.dataset.entityId = g.id;
  const list = Array.isArray(g.reminders) ? g.reminders : [];

  const head = document.createElement('div');
  head.className = 'gp-rem-head';
  const title = document.createElement('span');
  title.className = 'gp-rem-title';
  title.textContent = tr('reminder.listTitle');
  head.appendChild(title);
  const add = document.createElement('button');
  add.type = 'button'; add.className = 'gp-rem-add';
  add.textContent = `+ ${tr(list.length ? 'reminder.addAnother' : 'reminder.add')}`;
  add.onclick = () => openEntityReminderPickerOrReport('group', g.id, undefined, { opener: add });
  head.appendChild(add);
  container.appendChild(head);

  if (!list.length) return;
  const ul = document.createElement('div');
  ul.className = 'gp-rem-list';
  list.forEach((r, i) => {
    const row = document.createElement('div');
    row.className = 'gp-rem-item' + (r.at < Date.now() && !r.recur ? ' past' : '');
    row.dataset.entityReminderId = r.id;
    const when = new Date(r.at).toLocaleString(appLocale(), { dateStyle: 'medium', timeStyle: 'short' });
    const rec = r.recur ? ` · ${tr('detail.repeats', { schedule: recurLabel(r.recur) })}` : '';
    const dot = document.createElement('span');
    dot.className = 'gp-rem-dot';
    dot.style.setProperty('--dot', reminderDotColor(r.color || g.color));
    const label = document.createElement('span');
    label.className = 'gp-rem-label';
    label.textContent = r.label || g.name;
    const time = document.createElement('span');
    time.className = 'gp-rem-when';
    time.textContent = when + rec;
    row.appendChild(dot);
    row.appendChild(label);
    row.appendChild(time);
    const edit = document.createElement('button');
    edit.type = 'button'; edit.className = 'gp-rem-btn'; edit.textContent = tr('reminder.edit');
    edit.dataset.reminderAction = 'edit';
    edit.setAttribute('aria-label', tr('reminder.editNamed', { name: r.label || g.name }));
    edit.onclick = () => openEntityReminderPickerOrReport('group', g.id, r.id, { opener: edit });
    const del = document.createElement('button');
    del.type = 'button'; del.className = 'gp-rem-btn danger'; del.textContent = tr('reminder.remove');
    del.dataset.reminderAction = 'remove';
    del.setAttribute('aria-label', tr('reminder.removeNamed', { name: r.label || g.name }));
    del.onclick = () => openEntityReminderPickerOrReport('group', g.id, r.id, {
      opener: del,
      initialFocus: 'remove',
    });
    row.appendChild(edit); row.appendChild(del);
    ul.appendChild(row);
  });
  container.appendChild(ul);
}

// ════════════════════════════════════════════════════════════════
// INBOX PAGE (2026-11 canvas)
// ════════════════════════════════════════════════════════════════
// The Inbox group opens on its own page instead of the generic group page: a
// dark triage card for the next waiting item, then the other Inbox items as
// quiet rows. The card answers 1, 2, 3, A and → like Plan's Sort, through the
// same planSortQueue / planSortDecide / planSortTally, and leaves toward where
// the item went. The group page's description, reminders, record creation,
// Open all and group actions live in the header's More menu; rows keep the
// item menu, drag, selection, reminders and details. Inbox is still an
// ordinary group in the stored data.

const INBOX_ICONS = {
  save: 'M4.5 2.5h7a1 1 0 0 1 1 1v10L8 11l-4.5 2.5v-10a1 1 0 0 1 1-1z',
  folder: 'M1.8 4.6a1 1 0 0 1 1-1h3.3l1.4 1.5h5.7a1 1 0 0 1 1 1v6a1 1 0 0 1-1 1H2.8a1 1 0 0 1-1-1z',
  archive: 'M2 2.8h12v3.2H2zM3.1 6v6.8a1 1 0 0 0 1 1h7.8a1 1 0 0 0 1-1V6M6.4 8.7h3.2',
  check: 'M3.5 8.5l3 3 6-7',
  note: 'M4 4.5h8M4 8h8M4 11.5h5',
  todo: 'M2.5 3.5a1 1 0 0 1 1-1h9a1 1 0 0 1 1 1v9a1 1 0 0 1-1 1h-9a1 1 0 0 1-1-1zM5.2 8.2l2 2 3.8-4.4',
  stack: 'M2 5l6-3 6 3-6 3zM2 8l6 3 6-3M2 11l6 3 6-3',
  search: 'M7 12a5 5 0 1 0 0-10 5 5 0 0 0 0 10zM10.6 10.6 13.5 13.5',
  arrow: 'M3 8h10M9 4l4 4-4 4',
  download: 'M8 2.5v7.5M4.8 7 8 10.2 11.2 7M2.5 13h11',
};

function inboxIcon(name, size = 16, stroke = 1.6) {
  return `<svg width="${size}" height="${size}" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="${stroke}" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${INBOX_ICONS[name] || ''}"/></svg>`;
}

function inboxDotsIcon(size = 16) {
  return `<svg width="${size}" height="${size}" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true"><circle cx="3.5" cy="8" r="1.3"/><circle cx="8" cy="8" r="1.3"/><circle cx="12.5" cy="8" r="1.3"/></svg>`;
}

function isInboxPageGroup(group) {
  return !!group && group.name === 'Inbox';
}

function isInboxPageActive() {
  if (!activeGroupPage) return false;
  return isInboxPageGroup(findGroup(activeGroupPage.groupId)?.group);
}

// One triage session per visit, like Plan's Sort session: the answers behind
// the tally, the skip order, and what the last paint showed so motion only
// plays when something changed.
function inboxPageState(groupId) {
  if (!inboxPageSession || inboxPageSession.groupId !== groupId) {
    inboxPageSession = {
      groupId,
      decided: new Map(),
      skipped: [],
      busy: false,
      holdRender: false,
      entering: false,
      shown: false,
      count: null,
      cardId: null,
      hadCard: false,
      seen: null,
      aboutOpen: false,
      aboutOpening: false,
    };
  }
  return inboxPageSession;
}

// What the page shows for one Inbox group. The waiting queue is Plan's Sort
// queue; a skipped item waits at its end, so Skip rotates instead of hiding.
function inboxPageModel(group, somedayIds, session, now = Date.now()) {
  const items = (Array.isArray(group?.items) ? group.items : []).filter(item => item && typeof item === 'object');
  const queue = planSortQueue(group, somedayIds);
  const waiting = new Set(queue.map(item => String(item.id)));
  const skipped = session.skipped.filter(id => waiting.has(id));
  const order = queue.filter(item => !skipped.includes(String(item.id)))
    .concat(skipped.map(id => queue.find(item => String(item.id) === id)));
  const current = order[0] || null;
  const tally = planSortTally(session, queue);
  tally.move = 0;
  session.decided.forEach((choice, id) => {
    if (choice === 'move' && !waiting.has(id)) tally.move += 1;
  });
  const done = tally.today + tally.week + tally.someday + tally.archive + tally.move;
  return {
    items,
    queue,
    current,
    canSkip: order.length > 1,
    tally,
    done,
    total: done + queue.length,
    somedayIds,
    rows: items
      .filter(item => item !== current)
      .map(item => ({ item, waiting: waiting.has(String(item.id)), status: inboxItemStatus(item, somedayIds, now) })),
  };
}

// The status chip on a row: when it is planned, Someday, or done.
function inboxItemStatus(item, somedayIds, now = Date.now()) {
  if (item?.type === 'todo' && item.done === true) return { kind: 'done', label: tr('inbox.status.done') };
  const stored = Number(item?.reminder?.at);
  if (item?.reminder && Number.isFinite(stored)) {
    const at = pendingReminderTime(item.reminder, now) ?? stored;
    return { kind: 'when', at, overdue: at < now, label: inboxWhenLabel(at, now) };
  }
  if (somedayIds.has(String(item?.id))) return { kind: 'someday', label: tr('plan.lane.someday') };
  return { kind: '', label: '' };
}

function inboxWhenLabel(at, now = Date.now()) {
  const day = planDayStart(at);
  const today = planDayStart(now);
  if (day === today) return `${tr('plan.lane.today')} ${planTimeLabel(at)}`;
  if (day === planAddDays(today, 1)) return `${tr('plan.lane.tomorrow')} ${planTimeLabel(at)}`;
  if (day > today && day < planAddDays(today, 7)) return `${planWeekdayLabel(at)} ${planTimeLabel(at)}`;
  return new Date(at).toLocaleDateString(appLocale(), { month: 'short', day: 'numeric' });
}

// A waiting row's quiet right edge: the time it was saved today, the weekday
// this week, else the date.
function inboxSavedLabel(createdAt, now = Date.now()) {
  const at = Number(createdAt);
  if (!Number.isFinite(at) || at <= 0) return '';
  const day = planDayStart(at);
  const today = planDayStart(now);
  if (day === today) return planTimeLabel(at);
  if (day > planAddDays(today, -7)) return planWeekdayLabel(at);
  return new Date(at).toLocaleDateString(appLocale(), { month: 'short', day: 'numeric' });
}

function inboxSpaceMatches(option, query) {
  const words = String(query || '').toLocaleLowerCase().split(/\s+/).filter(Boolean);
  const text = String(option?.label || '').toLocaleLowerCase();
  return words.every(word => text.includes(word));
}

// Where a drop before (or after) a row lands in the group's stored order.
function inboxDropIndex(items, targetId, after) {
  const index = (Array.isArray(items) ? items : []).findIndex(item => String(item?.id) === String(targetId));
  if (index < 0) return Array.isArray(items) ? items.length : 0;
  return after ? index + 1 : index;
}

function inboxItemTitle(item) {
  if (item?.type === 'stack') return String(item.name || '').trim() || tr('stackEditor.defaultName');
  if (item?.type === 'note') return boardNotePreviewText(item) || tr('detail.emptyNote');
  if (item?.type === 'todo') return String(item.text || '').trim() || tr('detail.emptyTodo');
  return String(item?.title || '').trim() || dispUrl(item?.url || '') || tr('itemAction.untitled');
}

function inboxItemSource(item) {
  if (item?.type === 'tab') return planSortMeta(item).domain || dispUrl(item.url || '');
  if (item?.type === 'stack') {
    const count = Array.isArray(item.items) ? item.items.length : 0;
    return count === 1 ? tr('groupAction.oneItem') : tr('groupAction.items', { count });
  }
  return tr(item?.type === 'todo' ? 'inbox.kind.todo' : 'inbox.kind.note');
}

function inboxFavMarkup(item, large = false) {
  const size = large ? ' is-lg' : '';
  if (['note', 'todo', 'stack'].includes(item?.type)) {
    return `<span class="ibx-fav is-${item.type}${size}" aria-hidden="true">${inboxIcon(item.type, large ? 20 : 15, 1.8)}</span>`;
  }
  const meta = planSortMeta(item);
  const src = favUrl(item?.url, large ? 64 : 32);
  return `<span class="ibx-fav${size}${src ? ' has-img' : ''}" aria-hidden="true"><span class="ibx-fav-letter">${esc(meta.initial)}</span>${src ? `<img src="${esc(src)}" alt="" decoding="async">` : ''}</span>`;
}

function bindInboxFavicons(root) {
  root.querySelectorAll('.ibx-fav img').forEach(img => {
    img.addEventListener('error', () => {
      img.closest('.ibx-fav')?.classList.remove('has-img');
      img.remove();
    }, { once: true });
  });
}

function inboxFocus(target) {
  if (!target || typeof target.focus !== 'function') return false;
  try { target.focus({ preventScroll: true }); } catch { try { target.focus(); } catch { return false; } }
  return document.activeElement === target;
}

function inboxPageRoot() {
  return document.querySelector('#board > .ibx');
}

function focusInboxCard(page = inboxPageRoot()) {
  return inboxFocus(page?.querySelector('.ibx-card[tabindex="0"]') || page?.querySelector('.ibx-title'));
}

function focusInboxKey(key, page = inboxPageRoot()) {
  if (!key || !page) return false;
  return inboxFocus(page.querySelector(`[data-ibx-focus="${CSS.escape(String(key))}"]`));
}

// focusItem() lands here for the Inbox page (Welcome's first save, Locate
// receipts): focus the card or row and ring it once.
function focusInboxPageItem(id) {
  const page = inboxPageRoot();
  if (!page || !id) return false;
  const key = CSS.escape(String(id));
  const target = page.querySelector(`.ibx-card[data-id="${key}"]`) || page.querySelector(`.ibx-row[data-ibx-id="${key}"]`);
  if (!target) return false;
  inboxFocus(target);
  try { target.scrollIntoView({ block: 'nearest' }); } catch {}
  target.classList.remove('is-located');
  void target.offsetWidth;
  target.classList.add('is-located');
  return true;
}

function inboxOpenItem(item, opener = null) {
  if (!item) return false;
  if (item.type === 'tab') return openSavedTabItem(item, { focus: true, opener });
  if (item.type === 'note') return openBoardRecordDetail(item, opener, 'note-body');
  if (item.type === 'todo') return openBoardRecordDetail(item, opener, 'task');
  return openBoardRecordDetail(item, opener);
}

function inboxToggleStack(stack) {
  State.snapshot('Toggle stack');
  stack.expanded = !stack.expanded;
  State.persist();
  renderBoard();
}

// The to-do check reuses the Board's receipt-gated completion, which needs a
// .todo-check button as its owner.
async function inboxToggleTodo(item) {
  const id = String(item?.id || '');
  const button = document.querySelector(`.ibx [data-ibx-focus="done:${CSS.escape(id)}"]`);
  if (!button) return false;
  const changed = await toggleBoardTodoCompletion(item, button);
  focusInboxKey(`done:${id}`);
  return changed;
}

// ── Space picker: one filterable floating layer for card, row and bulk Move ──
function closeInboxSpacePicker({ restoreFocus = false } = {}) {
  const picker = inboxSpacePicker;
  if (!picker) return false;
  inboxSpacePicker = null;
  picker.cleanup();
  picker.el.remove();
  const owner = picker.owner?.isConnected ? picker.owner : (picker.ownerKey ? document.querySelector(`[data-ibx-focus="${CSS.escape(picker.ownerKey)}"]`) : null);
  owner?.setAttribute?.('aria-expanded', 'false');
  if (restoreFocus) inboxFocus(owner);
  return true;
}

function inboxSpaceOptions(review) {
  const options = selectedItemMoveOptions(review);
  if (!options) return null;
  const ws = activeWs();
  return options.map(option => {
    const destination = option.destinationContext;
    const group = destination.groupName === 'Inbox' ? tr('nav.inbox') : destination.groupName;
    return {
      review,
      destinationContext: destination,
      label: option.label,
      space: destination.workspaceRef === ws ? destination.spaceName : `${destination.workspaceName} › ${destination.spaceName}`,
      where: [group, ...destination.stackNames].filter(Boolean).join(' › '),
      color: reminderDotColor(destination.groupRef?.color || null),
    };
  });
}

// `host` mounts the same picker inline (Item details folds it open under its
// location) instead of floating it beside the anchor.
function openInboxSpacePicker(anchor, review, onPick, { host = null } = {}) {
  if (inboxSpacePicker && inboxSpacePicker.owner === anchor) return closeInboxSpacePicker({ restoreFocus: true });
  closeInboxSpacePicker();
  hideContextMenu();
  const options = review ? inboxSpaceOptions(review) : null;
  if (!options) return reportSelectedItemMutationUnavailable(anchor);
  if (!options.length) {
    toast(tr('selection.noMoveDestination'), { danger: true, duration: 5000 });
    return false;
  }
  const el = document.createElement('div');
  el.className = host ? 'ibx-pop is-inline' : 'ibx-pop';
  el.setAttribute('role', host ? 'group' : 'dialog');
  el.setAttribute('aria-label', tr('inbox.moveToSpace'));
  el.innerHTML = `
    <label class="ibx-pf">${inboxIcon('search', 14, 1.6)}<span class="sr-only">${esc(tr('inbox.findSpace'))}</span><input type="text" autocomplete="off" spellcheck="false" placeholder="${esc(tr('inbox.findSpace'))}"></label>
    <div class="ibx-pop-list" role="group" aria-label="${esc(tr('inbox.moveToSpace'))}"></div>`;
  const input = el.querySelector('input');
  const list = el.querySelector('.ibx-pop-list');
  let shown = [];
  const pick = option => {
    const owner = anchor?.isConnected ? anchor : (anchor?.dataset?.ibxFocus ? document.querySelector(`[data-ibx-focus="${CSS.escape(anchor.dataset.ibxFocus)}"]`) : null);
    closeInboxSpacePicker();
    onPick(option, owner || anchor);
  };
  const paint = () => {
    shown = options.filter(option => inboxSpaceMatches(option, input.value));
    list.replaceChildren(...shown.map(option => {
      const button = document.createElement('button');
      button.type = 'button';
      button.className = 'ibx-mi';
      button.innerHTML = `<span class="ibx-dot" aria-hidden="true" style="--dot:${esc(option.color)}"></span><span class="ibx-mi-space">${esc(option.space)}</span><span class="ibx-mi-where">› ${esc(option.where)}</span>`;
      button.addEventListener('click', () => pick(option));
      return button;
    }));
    if (!shown.length) {
      const none = document.createElement('p');
      none.className = 'ibx-pop-none';
      none.textContent = tr('inbox.noSpaceMatch');
      list.appendChild(none);
    }
  };
  paint();
  input.addEventListener('input', paint);
  el.addEventListener('keydown', event => {
    const buttons = [...list.querySelectorAll('.ibx-mi')];
    const index = buttons.indexOf(document.activeElement);
    if (event.key === 'Escape') {
      event.preventDefault();
      closeInboxSpacePicker({ restoreFocus: true });
    } else if (event.key === 'Enter' && event.target === input) {
      event.preventDefault();
      if (shown[0]) pick(shown[0]);
    } else if (event.key === 'ArrowDown') {
      event.preventDefault();
      inboxFocus(buttons[Math.min(index + 1, buttons.length - 1)] || input);
    } else if (event.key === 'ArrowUp') {
      event.preventDefault();
      inboxFocus(index > 0 ? buttons[index - 1] : input);
    }
    // Page keys (1, 2, 3, A, /, C) stay out of the picker.
    event.stopPropagation();
  });
  if (host) {
    host.appendChild(el);
  } else {
    document.body.appendChild(el);
    const rect = anchor.getBoundingClientRect();
    const width = Math.min(320, window.innerWidth - 32);
    el.style.width = `${width}px`;
    el.style.left = `${Math.max(16, Math.min(rect.left, window.innerWidth - width - 16))}px`;
    if (window.innerHeight - rect.bottom >= 300 || rect.top < 300) el.style.top = `${Math.round(rect.bottom + 8)}px`;
    else el.style.bottom = `${Math.round(window.innerHeight - rect.top + 8)}px`;
  }
  anchor.setAttribute('aria-expanded', 'true');
  const outside = event => {
    if (el.contains(event.target) || anchor.contains(event.target)) return;
    closeInboxSpacePicker();
  };
  // Focus moving back to the anchor keeps the picker, so that click closes it.
  const leave = event => {
    if (event.relatedTarget && !el.contains(event.relatedTarget) && !anchor.contains(event.relatedTarget)) closeInboxSpacePicker();
  };
  document.addEventListener('pointerdown', outside, true);
  el.addEventListener('focusout', leave);
  inboxSpacePicker = {
    el,
    owner: anchor,
    ownerKey: anchor.dataset?.ibxFocus || '',
    cleanup: () => document.removeEventListener('pointerdown', outside, true),
  };
  inboxFocus(input);
  return true;
}

function openInboxItemMovePicker(item, anchor, onPick, options = {}) {
  const review = createSelectedItemMutationContext([String(item?.id || '')]);
  if (!review) return reportSelectedItemMutationUnavailable(anchor);
  return openInboxSpacePicker(anchor, review, onPick, options);
}

function openInboxBulkMovePicker(review, opener) {
  return openInboxSpacePicker(opener, review, (option, owner) => {
    void commitSelectedItemMove(option.review, option.destinationContext, owner);
  });
}

// ── Triage: the card's answers and the rows' quick actions ──
async function inboxDecide(item, choice, opener, option) {
  if (choice === 'move') {
    if (!option?.review || !option.destinationContext) return false;
    return commitSelectedItemMove(option.review, option.destinationContext, opener);
  }
  return planSortDecide(item, choice, opener);
}

// The card's answer: the card leaves toward where the item went (Plan's Sort
// holds its repaint the same way), the count ticks down, and the next item
// enters. Undo from the receipt brings the card back from that direction.
async function inboxTriage(groupId, item, choice, opener = null, option = null) {
  const session = inboxPageState(groupId);
  if (session.busy || !item) return false;
  const group = findGroup(groupId)?.group;
  if (!group) return false;
  if (choice === 'skip' && !inboxPageModel(group, planSomedayIds(), session).canSkip) return false;
  const id = String(item.id);
  session.busy = true;
  const reduce = planReducedMotion();
  const page = inboxPageRoot();
  const leaving = reduce ? null : page?.querySelector(`.ibx-card-item[data-id="${CSS.escape(id)}"]`);
  if (leaving) leaving.classList.add(`is-leaving-${choice}`);
  page?.querySelector(`.ibx-card [data-sort="${choice}"]`)?.classList.add('is-hit');
  const leaveDone = new Promise(resolve => setTimeout(resolve, leaving ? 260 : 0));
  session.holdRender = true;
  let ok = false;
  try {
    if (choice === 'skip') {
      session.skipped = session.skipped.filter(skippedId => skippedId !== id).concat(id);
      ok = true;
    } else {
      ok = await inboxDecide(item, choice, opener, option);
    }
  } catch (error) {
    console.error('Inbox triage failed', error);
    ok = false;
  }
  if (!ok) {
    session.busy = false;
    session.holdRender = false;
    renderBoard();
    focusInboxCard();
    return false;
  }
  if (choice !== 'skip') session.decided.set(id, choice);
  await leaveDone;
  session.busy = false;
  session.holdRender = false;
  session.entering = !reduce;
  renderBoard();
  session.entering = false;
  focusInboxCard();
  if (choice === 'someday') toast(tr('inbox.somedaySaved'));
  return true;
}

// A row's quick action: the row stamps where it went, or folds away when it
// left the Inbox. Focus stays on the row, else moves to its neighbour.
async function inboxRowAct(groupId, id, choice, opener = null, option = null) {
  const session = inboxPageState(groupId);
  if (session.busy) return false;
  const group = findGroup(groupId)?.group;
  const found = findItem(id);
  const item = found?.item || null;
  if (!group || !item || found.group !== group) return false;
  const page = inboxPageRoot();
  const key = CSS.escape(String(id));
  const row = page?.querySelector(`.ibx-row[data-ibx-id="${key}"]`) || null;
  const rows = page ? [...page.querySelectorAll('.ibx-list > .ibx-row')] : [];
  const index = rows.indexOf(row);
  const neighbor = rows[index + 1] || rows[index - 1] || null;
  const leaves = choice === 'archive' || choice === 'move';
  const reduce = planReducedMotion();
  session.busy = true;
  session.holdRender = true;
  if (row && !reduce) {
    if (leaves) row.classList.add('is-gone', `is-gone-${choice}`);
    else {
      const stamp = row.querySelector('.ibx-stamp');
      const label = choice === 'someday'
        ? tr('plan.lane.someday')
        : inboxWhenLabel(choice === 'today' ? planSortTodayAt() : planSortWeekAt(planCollect(activeWs())));
      if (stamp) {
        stamp.classList.toggle('is-someday', choice === 'someday');
        stamp.querySelector('span').textContent = label;
      }
      row.classList.add('is-stamp');
    }
  }
  const settle = new Promise(resolve => setTimeout(resolve, row && !reduce ? (leaves ? 280 : 260) : 0));
  let ok = false;
  try {
    ok = await inboxDecide(item, choice, opener, option);
  } catch (error) {
    console.error('Inbox row action failed', error);
    ok = false;
  }
  if (ok) session.decided.set(String(id), choice);
  await settle;
  session.busy = false;
  session.holdRender = false;
  renderBoard();
  const fresh = inboxPageRoot();
  if (!ok || !leaves) {
    if (!focusInboxKey(`row:${id}`, fresh)) focusInboxCard(fresh);
  } else if (!(neighbor && focusInboxKey(neighbor.dataset.ibxFocus, fresh))) {
    focusInboxCard(fresh);
  }
  if (ok && choice === 'someday') toast(tr('inbox.somedaySaved'));
  return ok;
}

// The card item takes the card's motion; any other item acts as a row.
function inboxAct(groupId, item, choice, opener = null, option = null) {
  const card = inboxPageRoot()?.querySelector('.ibx-card[data-id]');
  if (card && card.dataset.id === String(item?.id)) return inboxTriage(groupId, item, choice, opener, option);
  return inboxRowAct(groupId, String(item?.id || ''), choice, opener, option);
}

// The same menu the Board's record cards offer, plus Move to a Space.
function inboxItemMenuItems(group, item, opener, parentItems) {
  const stableOpener = opener || null;
  const wrap = action => () => {
    focusDialogOpener(stableOpener);
    return action();
  };
  const topLevel = parentItems === group.items;
  const archiveAction = () => inboxAct(group.id, item, 'archive', stableOpener);
  const move = topLevel ? [{
    text: tr('inbox.moveToSpaceMenu'),
    icon: cmIcons.move,
    action: () => openInboxItemMovePicker(item, stableOpener, (option, owner) => inboxAct(group.id, item, 'move', owner, option)),
  }] : [];
  let items;
  if (item.type === 'stack') {
    items = [
      ...stackActionMenuItems(item, stableOpener, { parentItems, group, toggleCollapse: () => inboxToggleStack(item), archiveAction }),
      ...(move.length ? [{ sep: true }, ...move] : []),
    ];
    return items;
  }
  const common = commonActs(item, move, {
    includeColor: item.type !== 'tab',
    mutationOpener: stableOpener,
    archiveAction,
  });
  if (item.type === 'tab') {
    const url = typeof item.url === 'string' ? item.url : '';
    const canOpen = isOpenableSavedTabUrl(url);
    items = [
      ...(canOpen ? [
        { text: tr('itemAction.openFocused'), icon: cmIcons.open, action: () => openSavedTabItem(item, { focus: true, opener: stableOpener }) },
        { text: tr('itemAction.openBackground'), icon: cmIcons.open, action: () => openSavedTabItem(item, { focus: false, reuse: false, opener: stableOpener }) },
      ] : []),
      ...(url ? [{ text: tr('itemAction.copyUrl'), icon: cmIcons.copy, action: () => copySavedTabUrl(url) }] : []),
      { text: tr('itemAction.editTitle'), icon: cmIcons.edit, action: () => openItemDetail(item.id, { initialFocusKey: 'title' }) },
      ...common,
    ];
  } else if (item.type === 'todo') {
    items = [
      { text: tr('itemAction.editTodo'), icon: cmIcons.edit, action: () => openBoardRecordDetail(item, stableOpener, 'task') },
      { text: tr(item.done ? 'detail.markIncomplete' : 'detail.markComplete'), icon: cmIcons.edit, action: () => inboxToggleTodo(item) },
      ...common,
    ];
  } else {
    items = [
      { text: tr('itemAction.editNote'), icon: cmIcons.edit, action: () => openBoardRecordDetail(item, stableOpener, 'note-body') },
      ...common,
    ];
  }
  return items.map(entry => (entry.action ? { ...entry, action: wrap(entry.action) } : entry));
}

// The header's More menu keeps every group-page action one click away.
function inboxHeaderMenuItems(group, opener) {
  const session = inboxPageState(group.id);
  const openAsPage = tr('groupAction.openAsPage');
  const groupItems = groupActionMenuItems(group, opener, { includeRecordCreation: false })
    .filter(entry => entry.text !== openAsPage);
  if (!groupItems.length) return [];
  const reminders = Array.isArray(group.reminders) ? group.reminders.length : 0;
  return [
    { text: tr('groupAction.saveHere'), icon: MORE_MENU_ICONS.save, action: () => addSidebarOrActiveTabToGroup(group) },
    ...groupRecordCreationMenuItems(group, opener),
    { sep: true },
    {
      text: tr('inbox.about'),
      icon: cmIcons.detail,
      sub: session.aboutOpen ? '✓' : (reminders ? String(reminders) : ''),
      action: () => toggleInboxAbout(group.id),
    },
    ...groupItems,
  ];
}

function openInboxHeaderMenu(group, opener) {
  const items = inboxHeaderMenuItems(group, opener);
  if (!items.length) {
    toast(tr('detail.changed'), { danger: true, duration: 6000 });
    return false;
  }
  closeInboxSpacePicker();
  focusDialogOpener(opener);
  return showAnchoredContextMenu(opener, items, { ariaLabel: tr('inbox.more'), expandedOwner: opener });
}

function toggleInboxAbout(groupId) {
  const session = inboxPageState(groupId);
  session.aboutOpen = !session.aboutOpen;
  session.aboutOpening = session.aboutOpen;
  renderBoard();
  session.aboutOpening = false;
  if (session.aboutOpen) inboxFocus(document.querySelector('.ibx-about .gp-readme-editor'));
  else focusInboxKey('more');
}

// ── Builders ──
function buildInboxHeader(group, model, session) {
  const head = document.createElement('header');
  head.className = 'ibx-hd';
  const count = model.queue.length;
  const previous = session.count;
  const changed = previous != null && previous !== count && count > 0;
  const rolled = changed && previous > 0;
  const direction = count < previous ? 'down' : 'up';
  const digits = !rolled
    ? `<span>${count}</span>`
    : direction === 'up' ? `<span>${previous}</span><span>${count}</span>` : `<span>${count}</span><span>${previous}</span>`;
  head.innerHTML = `
    <h1 class="ibx-title" id="ibx-title" tabindex="-1" data-ibx-focus="title">${esc(tr('nav.inbox'))}</h1>
    ${count ? `<span class="ibx-bub${changed ? ' is-bump' : ''}" role="img" aria-label="${esc(tr('plan.leftToSort', { count }))}"><span class="ibx-roll" aria-hidden="true"><span class="ibx-roll-stack${rolled ? ` is-${direction}` : ''}">${digits}</span></span></span>` : ''}
    <span class="ibx-hd-gap" aria-hidden="true"></span>
    <button type="button" class="ibx-btn" data-ibx-act="save" data-ibx-focus="save" aria-haspopup="menu" aria-expanded="false">${inboxIcon('save', 16, 1.6)}<span class="ibx-btn-label">${esc(tr('action.saveTab'))}</span></button>
    <button type="button" class="ibx-ibtn" data-ibx-act="more" data-ibx-focus="more" aria-haspopup="menu" aria-expanded="false" aria-label="${esc(tr('inbox.more'))}" title="${esc(tr('inbox.more'))}">${inboxDotsIcon(18)}</button>`;
  const save = head.querySelector('[data-ibx-act="save"]');
  // The Space's Save tab review: the same menu the top bar's Save tab opens.
  save.addEventListener('click', () => {
    closeInboxSpacePicker();
    focusDialogOpener(save);
    void saveMostRecentOpenTab({ currentTarget: save });
  });
  const more = head.querySelector('[data-ibx-act="more"]');
  more.addEventListener('click', () => openInboxHeaderMenu(group, more));
  return head;
}

function buildInboxAbout(group, opening = false) {
  const about = document.createElement('section');
  about.className = `ibx-about${opening ? ' is-opening' : ''}`;
  about.setAttribute('aria-label', tr('inbox.about'));
  about.innerHTML = `
    ${renderIntentPills(group)}
    <div class="gp-readme ibx-readme"><div class="gp-readme-editor note-text" contenteditable="true" spellcheck="false" role="textbox" aria-multiline="true" aria-label="${esc(tr('inbox.description'))}" data-placeholder="${esc(tr('inbox.aboutPlaceholder'))}">${sanitizeHtml(group.readme || '')}</div></div>
    <div class="gp-reminders"></div>`;
  // The group page's description editor: blur saves with one Undo snapshot and
  // stays out of the way while the Link dialog owns focus.
  const editor = about.querySelector('.gp-readme-editor');
  let dirty = false;
  editor.addEventListener('input', () => { dirty = true; });
  editor.addEventListener('blur', () => {
    if (isRichTextLinkEditorOwned(editor)) return;
    if (!dirty) return;
    dirty = false;
    const current = findGroup(group.id)?.group;
    if (!current) return;
    const html = sanitizeHtml(editor.innerHTML.trim());
    if (html !== (current.readme || '')) {
      State.snapshot('Edit group description');
      current.readme = html;
      State.persist();
    }
  });
  renderGroupReminders(about.querySelector('.gp-reminders'), group);
  return about;
}

function buildInboxCard(group, model, session) {
  const card = document.createElement('section');
  card.className = 'ibx-card';
  const current = model.current;
  if (!current) {
    card.classList.add('is-clear');
    card.appendChild(buildInboxClear(model, session));
    return card;
  }
  const id = String(current.id);
  card.tabIndex = 0;
  card.dataset.ibxFocus = 'card';
  card.dataset.id = id;
  card.setAttribute('aria-label', tr('plan.sortKeys'));
  card.setAttribute('aria-describedby', 'ibx-card-title');
  let motion = '';
  if (session.cardId !== id) {
    const answered = session.decided.get(id);
    if (answered) {
      // Undo put this item back: it returns from where it went.
      motion = ` is-back-${answered}`;
      session.decided.delete(id);
    } else if (session.entering || (session.shown && session.cardId == null)) {
      motion = ' is-entering';
    }
  }
  const meta = planSortMeta(current);
  const title = inboxItemTitle(current);
  const shown = Math.min(model.total, 24);
  const filled = model.total ? Math.round((model.done / model.total) * shown) : 0;
  const segments = Array.from({ length: shown }, (_, index) => `<span class="ibx-seg${index < filled ? ' is-done' : ''}"></span>`).join('');
  const todoCheck = current.type === 'todo'
    ? `<button type="button" class="todo-check ibx-todo-check${current.done ? ' checked' : ''}" aria-pressed="${!!current.done}" data-ibx-focus="done:${esc(id)}" aria-label="${esc(tr(current.done ? 'detail.markIncomplete' : 'detail.markComplete'))}">${inboxIcon('check', 12, 2.4)}</button>`
    : '';
  card.innerHTML = `
    <div class="ibx-card-main">
      <div class="ibx-card-item${motion}" data-id="${esc(id)}">
        <div class="ibx-src">
          ${inboxFavMarkup(current, true)}
          <span class="ibx-src-text">
            <span class="ibx-domain">${esc(inboxItemSource(current))}</span>
            ${meta.age ? `<span class="ibx-age">${esc(meta.age)}</span>` : ''}
          </span>
          ${todoCheck}
        </div>
        <h2 class="ibx-card-title" id="ibx-card-title"><button type="button" class="ibx-card-open" data-ibx-focus="card-open">${esc(title)}</button></h2>
      </div>
      ${shown > 1 ? `<div class="ibx-segs" role="img" aria-label="${esc(tr('inbox.sortedOf', { done: model.done, total: model.total }))}">${segments}</div>` : ''}
    </div>
    <div class="ibx-card-side">
      <div class="ibx-bigs">
        <button type="button" class="ibx-big is-when" data-sort="today" data-ibx-focus="sort-today">${esc(tr('plan.lane.today'))}<span class="ibx-kbd" aria-hidden="true">1</span></button>
        <button type="button" class="ibx-big" data-sort="week" data-ibx-focus="sort-week">${esc(tr('plan.lane.week'))}<span class="ibx-kbd" aria-hidden="true">2</span></button>
        <button type="button" class="ibx-big" data-sort="someday" data-ibx-focus="sort-someday">${esc(tr('plan.lane.someday'))}<span class="ibx-kbd" aria-hidden="true">3</span></button>
        <button type="button" class="ibx-big is-quiet" data-sort="archive" data-ibx-focus="sort-archive">${esc(tr('itemAction.archive'))}<span class="ibx-kbd" aria-hidden="true">A</span></button>
      </div>
      <div class="ibx-card-foot">
        <button type="button" class="ibx-ghost is-where" data-sort="move" data-ibx-focus="card-move" aria-haspopup="dialog" aria-expanded="false">${inboxIcon('folder', 16, 1.5)}<span>${esc(tr('inbox.moveToSpace'))}</span></button>
        <span class="ibx-gap" aria-hidden="true"></span>
        <button type="button" class="ibx-ghost" data-sort="skip" data-ibx-focus="card-skip"${model.canSkip ? '' : ' aria-disabled="true"'}>${esc(tr('plan.skip'))}<span class="ibx-kbd" aria-hidden="true">→</span></button>
      </div>
    </div>`;
  bindInboxFavicons(card);
  const groupId = group.id;
  card.querySelectorAll('[data-sort]').forEach(button => {
    button.addEventListener('click', () => {
      const choice = button.dataset.sort;
      if (choice === 'move') {
        openInboxItemMovePicker(current, button, (option, owner) => inboxTriage(groupId, current, 'move', owner, option));
        return;
      }
      void inboxTriage(groupId, current, choice, button);
    });
  });
  card.querySelector('.ibx-card-open').addEventListener('click', event => inboxOpenItem(current, event.currentTarget));
  card.querySelector('.ibx-todo-check')?.addEventListener('click', event => {
    event.stopPropagation();
    void inboxToggleTodo(current);
  });
  card.addEventListener('keydown', event => {
    if (event.ctrlKey || event.metaKey || event.altKey) return;
    if (event.target.closest?.('input, textarea, select, [contenteditable="true"]')) return;
    const choice = { 1: 'today', 2: 'week', 3: 'someday', a: 'archive', A: 'archive', ArrowRight: 'skip' }[event.key];
    if (choice) {
      event.preventDefault();
      event.stopPropagation();
      void inboxTriage(groupId, current, choice, card.querySelector(`[data-sort="${choice}"]`));
    } else if (event.key === 'ArrowDown') {
      const first = inboxPageRoot()?.querySelector('.ibx-list > .ibx-row');
      if (first) {
        event.preventDefault();
        inboxFocus(first);
      }
    } else if (event.key === 'Enter' && event.target === card) {
      event.preventDefault();
      inboxOpenItem(current, card.querySelector('.ibx-card-open'));
    }
  });
  bindBoardItemContextMenu(card, opener => inboxItemMenuItems(group, current, opener, group.items));
  return card;
}

const INBOX_BURST_RAYS = [0, 45, 90, 135, 180, 225, 270, 315];

function buildInboxClear(model, session) {
  const wrap = document.createElement('div');
  // The burst plays once, when this visit sorted the last waiting item.
  const burst = session.hadCard;
  wrap.className = `ibx-clear${burst ? ' is-burst' : ''}`;
  const tally = model.tally;
  const counts = model.done ? [
    ['today', tally.today, 'plan.tally.today'],
    ['week', tally.week, 'plan.tally.week'],
    ['someday', tally.someday, 'plan.tally.someday'],
    ['archive', tally.archive, 'plan.tally.archive'],
    ...(tally.move ? [['move', tally.move, 'inbox.tally.moved']] : []),
  ] : [];
  wrap.innerHTML = `
    <span class="ibx-clear-mark${burst ? ' is-burst' : ''}" aria-hidden="true">${inboxIcon('check', 34, 2.4)}${burst ? `<span class="ibx-burst">${INBOX_BURST_RAYS.map(angle => `<span class="ibx-ray" style="--a:${angle}deg"><span class="ibx-pt"></span></span>`).join('')}</span>` : ''}</span>
    <div class="ibx-clear-copy">
      <h2 class="ibx-clear-title">${esc(tr('plan.inboxClear'))}</h2>
      ${counts.length ? `<div class="ibx-tally">${counts.map(([key, count, label]) => `<div class="ibx-tally-item is-${key}"><span>${count}</span>${esc(tr(label))}</div>`).join('')}</div>` : ''}
    </div>
    <div class="ibx-clear-acts">
      ${model.items.length ? '' : `<button type="button" class="ibx-ghost" data-ibx-act="import" data-ibx-focus="import">${inboxIcon('download', 16, 1.6)}<span>${esc(tr('empty.importBookmarks'))}</span></button>`}
      <button type="button" class="ibx-ghost" data-ibx-act="home" data-ibx-focus="home"><span>${esc(tr('plan.backToToday'))}</span>${inboxIcon('arrow', 14, 1.8)}</button>
    </div>`;
  wrap.querySelector('[data-ibx-act="import"]')?.addEventListener('click', () => importBookmarks());
  wrap.querySelector('[data-ibx-act="home"]').addEventListener('click', () => goHome());
  return wrap;
}

function buildInboxList(group, model, session) {
  const list = document.createElement('div');
  list.className = 'ibx-list';
  list.setAttribute('role', 'list');
  list.setAttribute('aria-label', tr('inbox.items'));
  const seen = session.seen;
  model.rows.forEach(({ item, waiting, status }) => {
    list.appendChild(buildInboxRow(group, item, {
      status,
      waiting,
      parentItems: group.items,
      fresh: !!seen && !seen.has(String(item.id)),
    }));
    if (item.type === 'stack' && item.expanded) {
      (Array.isArray(item.items) ? item.items : []).filter(child => child && typeof child === 'object').forEach(child => {
        list.appendChild(buildInboxRow(group, child, {
          status: inboxItemStatus(child, model.somedayIds),
          waiting: false,
          parentItems: item.items,
          child: true,
        }));
      });
    }
  });
  return list;
}

function buildInboxRow(group, item, { status, waiting, parentItems, child = false, fresh = false }) {
  const id = String(item.id);
  const key = esc(id);
  const title = inboxItemTitle(item);
  const selected = selectedItemIds.has(id);
  const row = document.createElement('div');
  row.className = `ibx-row${selected ? ' is-selected' : ''}${child ? ' is-child' : ''}${fresh ? ' is-new' : ''}`;
  row.dataset.ibxId = id;
  row.dataset.ibxFocus = `row:${id}`;
  row.dataset.kind = String(item.type || '');
  row.tabIndex = 0;
  row.draggable = true;
  row.setAttribute('role', 'listitem');
  row.setAttribute('aria-label', title);
  applyBoardRecordMarker(row, item);
  const chip = status.kind
    ? `<span class="ibx-chip is-${status.kind}${status.overdue ? ' is-overdue' : ''}">${status.kind === 'done' ? inboxIcon('check', 12, 2.4) : ''}${esc(status.label)}</span>`
    : `<span class="ibx-row-age">${esc(inboxSavedLabel(item.createdAt))}</span>`;
  const sorts = waiting && !child ? `
      <button type="button" class="ibx-ap is-when" data-row-sort="today" data-ibx-focus="today:${key}">${esc(tr('plan.lane.today'))}</button>
      <button type="button" class="ibx-ap" data-row-sort="week" data-ibx-focus="week:${key}">${esc(tr('plan.lane.week'))}</button>
      <button type="button" class="ibx-ap" data-row-sort="someday" data-ibx-focus="someday:${key}">${esc(tr('plan.lane.someday'))}</button>` : '';
  row.innerHTML = `
    <button type="button" class="ibx-pick" role="checkbox" aria-checked="${selected}" data-ibx-focus="pick:${key}" aria-label="${esc(tr(selected ? 'selection.deselectItem' : 'selection.selectItem', { title }))}">
      ${inboxFavMarkup(item)}
      <span class="ibx-cb" aria-hidden="true">${inboxIcon('check', 12, 2.6)}</span>
    </button>
    ${item.type === 'todo' ? `<button type="button" class="todo-check ibx-todo-check${item.done ? ' checked' : ''}" aria-pressed="${!!item.done}" data-ibx-focus="done:${key}" aria-label="${esc(tr(item.done ? 'detail.markIncomplete' : 'detail.markComplete'))}">${inboxIcon('check', 12, 2.4)}</button>` : ''}
    <div class="ibx-row-main">
      <button type="button" class="ibx-row-title" data-ibx-focus="title:${key}"${item.type === 'stack' ? ` aria-expanded="${!!item.expanded}"` : ''}>${esc(title)}</button>
      <span class="ibx-row-sub">${status.kind ? `<span class="ibx-sub-status is-${status.kind}">${esc(status.label)}</span>` : ''}<span>${esc(inboxItemSource(item))}</span></span>
    </div>
    ${chip}
    <div class="ibx-acts">${sorts}
      ${child ? '' : `<button type="button" class="ibx-ai ibx-ai-move" data-row-act="move" data-ibx-focus="move:${key}" aria-haspopup="dialog" aria-expanded="false" aria-label="${esc(tr('inbox.moveNamed', { title }))}" title="${esc(tr('inbox.moveToSpace'))}">${inboxIcon('folder', 17, 1.4)}</button>`}
      <button type="button" class="ibx-ai" data-row-act="archive" data-ibx-focus="archive:${key}" aria-label="${esc(tr('inbox.archiveNamed', { title }))}" title="${esc(tr('itemAction.archive'))}">${inboxIcon('archive', 17, 1.4)}</button>
      <button type="button" class="ibx-ai" data-row-act="more" data-ibx-focus="rowmore:${key}" aria-haspopup="menu" aria-label="${esc(tr('library.moreActions', { title }))}" title="${esc(tr('library.moreActions', { title }))}">${inboxDotsIcon(17)}</button>
    </div>
    <span class="ibx-stamp" aria-hidden="true">${inboxIcon('check', 13, 2.6)}<span></span></span>`;
  bindInboxFavicons(row);
  const groupId = group.id;
  row.querySelector('.ibx-pick').addEventListener('click', event => {
    event.stopPropagation();
    if (event.shiftKey) selectRangeTo(id);
    else toggleItemSelect(id);
  });
  row.querySelector('.ibx-row-title').addEventListener('click', event => {
    if (item.type === 'stack') inboxToggleStack(item);
    else inboxOpenItem(item, event.currentTarget);
  });
  row.querySelector('.ibx-todo-check')?.addEventListener('click', event => {
    event.stopPropagation();
    void inboxToggleTodo(item);
  });
  row.querySelectorAll('[data-row-sort]').forEach(button => {
    button.addEventListener('click', () => inboxRowAct(groupId, id, button.dataset.rowSort, button));
  });
  const moveButton = row.querySelector('[data-row-act="move"]');
  moveButton?.addEventListener('click', () => {
    openInboxItemMovePicker(item, moveButton, (option, owner) => inboxRowAct(groupId, id, 'move', owner, option));
  });
  const archiveButton = row.querySelector('[data-row-act="archive"]');
  archiveButton.addEventListener('click', () => inboxRowAct(groupId, id, 'archive', archiveButton));
  const menuButton = row.querySelector('[data-row-act="more"]');
  bindBoardItemContextMenu(row, opener => inboxItemMenuItems(group, item, opener, parentItems), { menuButton });
  // In select mode a click on the row's empty space selects it, as on cards.
  row.addEventListener('click', event => {
    if (!itemSelMode || event.target.closest('button')) return;
    toggleItemSelect(id);
  });
  row.addEventListener('keydown', event => {
    if (event.target !== row || event.ctrlKey || event.metaKey || event.altKey) return;
    const choice = { 1: 'today', 2: 'week', 3: 'someday', a: 'archive', A: 'archive' }[event.key];
    if (choice && (choice === 'archive' || (waiting && !child))) {
      event.preventDefault();
      event.stopPropagation();
      void inboxRowAct(groupId, id, choice, row);
    } else if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault();
      const rows = [...(inboxPageRoot()?.querySelectorAll('.ibx-list > .ibx-row') || [])];
      const index = rows.indexOf(row) + (event.key === 'ArrowDown' ? 1 : -1);
      if (index < 0) focusInboxCard();
      else inboxFocus(rows[index]);
    } else if (event.key === 'Enter') {
      event.preventDefault();
      row.querySelector('.ibx-row-title')?.click();
    } else if (event.key === ' ') {
      event.preventDefault();
      toggleItemSelect(id);
    }
  });
  attachItemDrag(row, item, parentItems, group);
  return row;
}

// Rows reorder by drag (one Undo snapshot), take open tabs dragged in from the
// open-tabs drawer, and a stack row takes a drop into the stack.
function bindInboxDropZone(page, groupId) {
  let line = null;
  let into = null;
  const clear = () => {
    line?.remove();
    line = null;
    into?.classList.remove('is-drop-into');
    into = null;
  };
  const targetAt = clientY => {
    const rows = [...page.querySelectorAll('.ibx-list > .ibx-row:not(.is-child):not(.dragging)')];
    for (const row of rows) {
      const rect = row.getBoundingClientRect();
      if (clientY < rect.top || clientY > rect.bottom) {
        if (clientY < rect.top) return { row, after: false, stack: false };
        continue;
      }
      const stack = row.dataset.kind === 'stack' && clientY > rect.top + rect.height * 0.25 && clientY < rect.bottom - rect.height * 0.25;
      return { row, after: !stack && clientY > rect.top + rect.height / 2, stack };
    }
    return { row: rows[rows.length - 1] || null, after: true, stack: false };
  };
  page.addEventListener('dragover', event => {
    if (!drag || drag.kind === 'group') return;
    event.preventDefault();
    event.dataTransfer.dropEffect = drag.kind === 'item' ? 'move' : 'copy';
    const target = targetAt(event.clientY);
    clear();
    if (target.stack && target.row.dataset.ibxId !== String(drag.id || '')) {
      into = target.row;
      into.classList.add('is-drop-into');
      return;
    }
    line = document.createElement('div');
    line.className = 'ibx-drop-line';
    line.setAttribute('aria-hidden', 'true');
    const list = page.querySelector('.ibx-list');
    if (!target.row) list?.appendChild(line);
    else if (target.after) target.row.after(line);
    else target.row.before(line);
  });
  page.addEventListener('dragleave', event => {
    if (!page.contains(event.relatedTarget)) clear();
  });
  page.addEventListener('drop', async event => {
    if (!drag || drag.kind === 'group') return;
    event.preventDefault();
    event.stopPropagation();
    const target = targetAt(event.clientY);
    clear();
    const group = findGroup(groupId)?.group;
    if (!group) return;
    const stack = target.stack ? group.items.find(item => String(item?.id) === target.row.dataset.ibxId && item.type === 'stack') : null;
    const list = stack ? stack.items : group.items;
    const index = stack ? list.length : (target.row ? inboxDropIndex(group.items, target.row.dataset.ibxId, target.after) : group.items.length);
    if (drag.kind === 'tab' || drag.kind === 'tabs-multi') {
      await handleTabDropIntoList(drag.data, list, index);
      return;
    }
    if (drag.kind !== 'item') return;
    const info = findItem(drag.id);
    if (!info || info.item === stack) return;
    if (info.item.type === 'stack' && isDescendantOf(list, info.item)) {
      toast(tr('feedback.stackSelf'), { danger: true });
      return;
    }
    State.snapshot(stack ? 'Move to stack' : 'Move item');
    const [moved] = info.parent.splice(info.index, 1);
    let at = index;
    if (info.parent === list && at > info.index) at -= 1;
    list.splice(Math.min(at, list.length), 0, moved);
    State.persist();
    renderBoard();
  });
}

// Renders the Inbox page into #board. The page root stays across repaints of
// the same Inbox, so an open description editor keeps its caret; the header,
// card and rows are rebuilt, and focus returns to the same control.
function renderInboxPage(info) {
  const group = info.group;
  const session = inboxPageState(group.id);
  const $b = document.getElementById('board');
  document.body.dataset.page = 'inbox';
  hideBreadcrumb();
  $b.classList.remove('list-mode', 'canvas-mode', 'explorer-mode', 'timeline-mode', 'calendar-mode');
  $b.classList.add('group-page-mode', 'inbox-mode');
  let page = $b.querySelector(`:scope > .ibx[data-gid="${CSS.escape(String(group.id))}"]`);
  // A triage answer is landing: keep the leaving card or row on screen until
  // it has gone, then inboxTriage/inboxRowAct repaint once.
  if (session.holdRender && page) return true;
  const active = document.activeElement;
  const focusKey = page && active && page.contains(active)
    ? active.closest('[data-ibx-focus]')?.dataset.ibxFocus || null
    : null;
  const firstShow = !page;
  const keepScroll = firstShow ? 0 : $b.scrollTop;
  if (!page) {
    $b.innerHTML = '';
    page = document.createElement('div');
    page.className = 'ibx';
    page.dataset.gid = String(group.id);
    page.setAttribute('aria-labelledby', 'ibx-title');
    const live = document.createElement('div');
    live.className = 'sr-only';
    live.setAttribute('aria-live', 'polite');
    live.dataset.ibxLive = 'true';
    page.appendChild(live);
    bindInboxDropZone(page, group.id);
    $b.appendChild(page);
  }
  const model = inboxPageModel(group, planSomedayIds(), session);
  const header = buildInboxHeader(group, model, session);
  let about = page.querySelector(':scope > .ibx-about');
  if (!session.aboutOpen) {
    about?.remove();
    about = null;
  } else if (!about || !about.contains(document.activeElement)) {
    const fresh = buildInboxAbout(group, session.aboutOpening);
    if (about) about.replaceWith(fresh);
    about = fresh;
  }
  const card = buildInboxCard(group, model, session);
  const list = buildInboxList(group, model, session);
  page.querySelectorAll(':scope > .ibx-hd, :scope > .ibx-card, :scope > .ibx-list').forEach(node => node.remove());
  const live = page.querySelector(':scope > [data-ibx-live]');
  if (about) {
    if (!about.isConnected) live.after(about);
    about.before(header);
    about.after(card);
  } else {
    live.after(header);
    header.after(card);
  }
  card.after(list);
  const cardId = model.current ? String(model.current.id) : null;
  if (!firstShow && cardId !== session.cardId) {
    live.textContent = model.current ? inboxItemTitle(model.current) : tr('plan.inboxClear');
  }
  session.count = model.queue.length;
  session.cardId = cardId;
  session.hadCard = !!model.current;
  session.seen = new Set(model.items.map(item => String(item.id)));
  session.shown = true;
  // A repaint keeps the reader where they were in a long Inbox.
  if (!firstShow && $b.scrollTop !== keepScroll) $b.scrollTo({ top: keepScroll, behavior: 'instant' });
  if (focusKey) {
    if (!focusInboxKey(focusKey, page) && focusKey === 'card') focusInboxCard(page);
  } else if (firstShow && !currentDetailItemId()) {
    // Like Plan's Sort, the keys answer as soon as the page opens.
    focusInboxCard(page);
  }
  return true;
}

// ════════════════════════════════════════════════════════════════
// ITEM DETAIL PANE (§4.2 — per-link content)
// ════════════════════════════════════════════════════════════════
// A right-docked modal context sheet for recovering a saved item: real title
// and location, open action, save context, reminder, and tags lead; cover,
// checklist, and custom fields stay progressive. It is addressable via board,
// library, or group routes so deep links and browser history remain coherent.
const DETAIL_COVER_COLORS = ['#ef4444', '#f97316', '#eab308', '#22c55e', '#06b6d4', '#6366f1', '#a855f7', '#ec4899'];
// Normalize a typed tag: trimmed, single-spaced, comma-free (commas delimit the
// dataset.tags blob the tag: operator reads), lowercased for case-insensitive
// matching.
const normalizeTag = s => String(s || '').trim().replace(/\s+/g, ' ').replace(/,/g, '').toLowerCase();

// Detail edits share one acknowledged-write boundary. The pending token is set
// before the graph changes, so blur, route, page-hide, and repeated activation
// all see the same transaction synchronously.
let itemDetailMutationPending = null;
let itemReminderMutationPending = null;
let itemDetailStatusTimer = null;
// A favourite or Read later toggle repaints the panel; the next paint plays its
// pop once ({ itemId, kind }).
let itemDetailFx = null;

function isItemDetailMutationPending() {
  return !!itemDetailMutationPending || !!itemReminderMutationPending;
}

function itemDetailValueFingerprint(value) {
  try { return JSON.stringify(value); } catch { return ''; }
}

function itemDetailSurfaceFingerprint() {
  const ws = activeWs();
  const itemId = currentDetailItemId() || null;
  if (activeGroupPage) {
    return itemDetailValueFingerprint({ kind: 'group', wsId: ws?.id || null, groupId: activeGroupPage.groupId, itemId });
  }
  if (activeLibraryMode) {
    return itemDetailValueFingerprint({ kind: 'library', wsId: ws?.id || null, mode: activeLibraryMode, itemId });
  }
  if (activeHome) {
    return itemDetailValueFingerprint({ kind: 'home', wsId: ws?.id || null, itemId });
  }
  return itemDetailValueFingerprint({ kind: 'board', wsId: ws?.id || null, spaceId: activeCat()?.id || null, itemId });
}

function itemDetailLocationFingerprint(target) {
  return itemDetailValueFingerprint({
    workspace: { id: target.ws?.id || null, name: target.ws?.name || '' },
    space: { id: target.cat?.id || null, name: target.cat?.name || '' },
    group: { id: target.group?.id || null, name: target.group?.name || '' },
    parents: (target.parents || []).map(parent => ({
      id: parent?.id || null,
      type: parent?.type || null,
      name: parent?.name || '',
    })),
  });
}

// Capture both primitive identity and runtime references. Primitive IDs make
// exhaustive re-resolution deterministic; references additionally reject an
// indistinguishable object replacement until the user reopens the sheet.
function createItemDetailMutationContext(info) {
  if (!info?.ws || !info?.item || !info?.cat || !info?.group) return null;
  let rows = [];
  try { rows = collectWorkspaceItems(info.ws).filter(row => row.item === info.item); } catch { return null; }
  if (rows.length !== 1) return null;
  const row = rows[0];
  const workspaceId = String(info.ws.id || '');
  const spaceId = String(row.cat?.id || '');
  const groupId = String(row.group?.id || '');
  const parentIds = (row.parents || []).map(parent => String(parent?.id || ''));
  const itemId = String(row.item.id || '');
  const itemType = String(row.item.type || '');
  if (!workspaceId || !spaceId || !groupId || !itemId || !itemType || parentIds.some(id => !id)) return null;
  return {
    workspaceId,
    spaceId,
    groupId,
    parentIds,
    itemId,
    itemType,
    itemFingerprint: itemDetailValueFingerprint(row.item),
    locationFingerprint: itemDetailLocationFingerprint({ ws: info.ws, ...row }),
    surfaceFingerprint: itemDetailSurfaceFingerprint(),
    workspaceRef: info.ws,
    spaceRef: row.cat,
    groupRef: row.group,
    parentRefs: [...(row.parents || [])],
    itemRef: row.item,
  };
}

function resolveItemDetailMutationTarget(context) {
  if (!context || context.surfaceFingerprint !== itemDetailSurfaceFingerprint()) return null;
  const state = State.get();
  const workspaces = (state.workspaces || []).filter(workspace => String(workspace?.id || '') === context.workspaceId);
  if (workspaces.length !== 1 || workspaces[0] !== context.workspaceRef) return null;
  const ws = workspaces[0];
  const spaces = (state.workspaces || []).flatMap(workspace => workspace.categories || [])
    .filter(space => String(space?.id || '') === context.spaceId);
  if (spaces.length !== 1 || spaces[0] !== context.spaceRef) return null;
  const cat = spaces[0];
  const groups = (state.workspaces || []).flatMap(workspace => workspace.categories || [])
    .flatMap(space => space.groups || [])
    .filter(group => String(group?.id || '') === context.groupId);
  if (groups.length !== 1 || groups[0] !== context.groupRef) return null;
  const group = groups[0];

  let rows = [];
  try {
    rows = (state.workspaces || []).flatMap(workspace =>
      collectWorkspaceItems(workspace).map(row => ({ ws: workspace, ...row }))
    );
  } catch { return null; }
  const matches = rows.filter(row => String(row.item?.id || '') === context.itemId);
  if (matches.length !== 1) return null;
  const target = matches[0];
  const parentIds = (target.parents || []).map(parent => String(parent?.id || ''));
  if (target.ws !== ws || target.cat !== cat || target.group !== group || target.item !== context.itemRef) return null;
  if (String(target.item?.type || '') !== context.itemType) return null;
  if (parentIds.length !== context.parentIds.length || parentIds.some((id, index) => id !== context.parentIds[index])) return null;
  if ((target.parents || []).some((parent, index) => parent !== context.parentRefs[index])) return null;
  for (let index = 0; index < context.parentIds.length; index += 1) {
    const ancestorMatches = rows.filter(row => String(row.item?.id || '') === context.parentIds[index]);
    if (ancestorMatches.length !== 1 || ancestorMatches[0].item !== target.parents[index] || target.parents[index]?.type !== 'stack') return null;
  }
  if (itemDetailValueFingerprint(target.item) !== context.itemFingerprint) return null;
  if (itemDetailLocationFingerprint(target) !== context.locationFingerprint) return null;
  return target;
}

function clearItemDetailStatusTimer() {
  if (itemDetailStatusTimer == null) return;
  clearTimeout(itemDetailStatusTimer);
  itemDetailStatusTimer = null;
}

function setItemDetailMutationStatus(root, key = '', tone = '') {
  const status = root?.querySelector?.('[data-idp-save-status]');
  if (!status) return;
  status.textContent = key ? tr(key) : '';
  if (tone) status.dataset.tone = tone;
  else delete status.dataset.tone;
}

function setItemDetailMutationBusy(root, busy) {
  if (!root) return;
  root.classList.toggle('idp-mutation-pending', busy);
  // Keep the live status outside the busy subtree so assistive technology can
  // announce “Saving…” immediately instead of deferring it until completion.
  const busyRegion = root.querySelector('.idp-body');
  if (busyRegion) busyRegion.setAttribute('aria-busy', String(busy));
  const selector = '.idp-actions button, .idp-hd button.dtl-loc, .dtl-foot button, .idp-body button, .idp-body input, .idp-body textarea, .idp-body select, .idp-body summary, .idp-body [contenteditable]';
  if (busy) {
    root.querySelectorAll(selector).forEach(control => {
      if (control.dataset.idpBusyControl === 'true') return;
      control.dataset.idpBusyControl = 'true';
      control.dataset.idpPreviousAriaDisabled = control.hasAttribute('aria-disabled')
        ? String(control.getAttribute('aria-disabled'))
        : '__missing__';
      control.setAttribute('aria-disabled', 'true');
      if ('readOnly' in control) {
        control.dataset.idpPreviousReadonly = String(!!control.readOnly);
        control.readOnly = true;
      }
      if (control.hasAttribute('contenteditable')) {
        control.dataset.idpPreviousContenteditable = String(control.getAttribute('contenteditable'));
        control.setAttribute('contenteditable', 'false');
      }
    });
    setItemDetailMutationStatus(root, 'detail.saving', 'pending');
    return;
  }
  root.querySelectorAll('[data-idp-busy-control="true"]').forEach(control => {
    if (control.dataset.idpPreviousAriaDisabled === '__missing__') control.removeAttribute('aria-disabled');
    else control.setAttribute('aria-disabled', control.dataset.idpPreviousAriaDisabled);
    if ('readOnly' in control && control.dataset.idpPreviousReadonly != null) {
      control.readOnly = control.dataset.idpPreviousReadonly === 'true';
    }
    if (control.dataset.idpPreviousContenteditable != null) {
      control.setAttribute('contenteditable', control.dataset.idpPreviousContenteditable);
    }
    delete control.dataset.idpBusyControl;
    delete control.dataset.idpPreviousAriaDisabled;
    delete control.dataset.idpPreviousReadonly;
    delete control.dataset.idpPreviousContenteditable;
  });
}

function handleItemDetailPendingClick(event) {
  if (!isItemDetailMutationPending()) return;
  const interactive = event.target?.closest?.('.idp-scrim, button, input, textarea, select, summary, [contenteditable]');
  if (!interactive) return;
  event.preventDefault();
  event.stopImmediatePropagation();
}

function handleItemDetailPendingKeydownCapture(event) {
  if (!isItemDetailMutationPending() || event.key === 'Tab') return;
  // Capture phase prevents target-level formatting/add-item handlers from running
  // against the immutable candidate while the receipt is unresolved.
  event.preventDefault();
  event.stopImmediatePropagation();
}

function cloneItemDetailJson(value) {
  if (value === undefined) return undefined;
  return JSON.parse(JSON.stringify(value));
}

function isItemDetailRecord(value) {
  return !!value && typeof value === 'object' && !Array.isArray(value);
}

// Apply only the JSON slots changed by the detached candidate. Same-length
// checklist/custom-field arrays retain their live row objects, which lets a
// pane-preserving text edit keep its existing DOM closures and focus.
function applyItemDetailCandidate(target, before, candidate) {
  if (Array.isArray(before) && Array.isArray(candidate)) {
    if (!Array.isArray(target)) throw new Error('Item detail candidate no longer matches the live array.');
    if (before.length !== candidate.length || target.length !== before.length) {
      target.splice(0, target.length, ...candidate.map(cloneItemDetailJson));
      return;
    }
    for (let index = 0; index < candidate.length; index += 1) {
      const beforeValue = before[index];
      const candidateValue = candidate[index];
      if (itemDetailValueFingerprint(beforeValue) === itemDetailValueFingerprint(candidateValue)) continue;
      if (Array.isArray(beforeValue) && Array.isArray(candidateValue) && Array.isArray(target[index])) {
        applyItemDetailCandidate(target[index], beforeValue, candidateValue);
      } else if (isItemDetailRecord(beforeValue) && isItemDetailRecord(candidateValue) && isItemDetailRecord(target[index])) {
        applyItemDetailCandidate(target[index], beforeValue, candidateValue);
      } else {
        target[index] = cloneItemDetailJson(candidateValue);
      }
    }
    return;
  }
  if (!isItemDetailRecord(before) || !isItemDetailRecord(candidate) || !isItemDetailRecord(target)) {
    throw new Error('Item detail candidate no longer matches the live item.');
  }
  const keys = new Set([...Object.keys(before), ...Object.keys(candidate)]);
  keys.forEach(key => {
    const beforeHas = Object.prototype.hasOwnProperty.call(before, key);
    const candidateHas = Object.prototype.hasOwnProperty.call(candidate, key);
    if (beforeHas === candidateHas
        && itemDetailValueFingerprint(before[key]) === itemDetailValueFingerprint(candidate[key])) return;
    if (!candidateHas) {
      delete target[key];
      return;
    }
    if (Array.isArray(before[key]) && Array.isArray(candidate[key]) && Array.isArray(target[key])) {
      applyItemDetailCandidate(target[key], before[key], candidate[key]);
    } else if (isItemDetailRecord(before[key]) && isItemDetailRecord(candidate[key]) && isItemDetailRecord(target[key])) {
      applyItemDetailCandidate(target[key], before[key], candidate[key]);
    } else {
      target[key] = cloneItemDetailJson(candidate[key]);
    }
  });
}

async function commitItemDetailMutation(context, label, mutate, opts = {}) {
  if (isItemDetailMutationPending()) return false;
  const root = document.getElementById('item-detail');
  if (State.isRecoveryRequired?.()) {
    setItemDetailMutationStatus(root, 'detail.saveFailed', 'error');
    return false;
  }
  const target = resolveItemDetailMutationTarget(context);
  if (!root?.classList.contains('open') || !target) {
    clearItemDetailStatusTimer();
    setItemDetailMutationStatus(root, 'detail.changed', 'error');
    return false;
  }

  // User-supplied field logic runs against a detached JSON candidate first. A
  // synchronous bug therefore cannot leave a partial live graph or phantom
  // history entry; the candidate diff is the only live mutation below.
  let before;
  let candidate;
  try {
    const beforeJson = JSON.stringify(target.item);
    before = JSON.parse(beforeJson);
    candidate = JSON.parse(beforeJson);
    mutate(candidate);
  } catch {
    clearItemDetailStatusTimer();
    setItemDetailMutationStatus(root, 'detail.saveFailed', 'error');
    return false;
  }
  if (itemDetailValueFingerprint(before) === itemDetailValueFingerprint(candidate)) return true;

  const transaction = { itemId: context.itemId };
  itemDetailMutationPending = transaction;
  clearItemDetailStatusTimer();
  setItemDetailMutationBusy(root, true);
  try {
    State.snapshot(label);
    applyItemDetailCandidate(target.item, before, candidate);
  } catch (error) {
    itemDetailMutationPending = null;
    setItemDetailMutationBusy(root, false);
    setItemDetailMutationStatus(root, 'detail.saveFailed', 'error');
    State.requireRecovery?.();
    if (typeof showStateRecoveryRequired === 'function') showStateRecoveryRequired(error);
    return false;
  }

  try {
    await State.persistNow();
  } catch (error) {
    if (itemDetailMutationPending === transaction) itemDetailMutationPending = null;
    setItemDetailMutationBusy(root, false);
    setItemDetailMutationStatus(root, 'detail.saveFailed', 'error');
    if (State.isRecoveryRequired?.() && typeof showStateRecoveryRequired === 'function') {
      showStateRecoveryRequired(error);
    }
    return false;
  }

  if (itemDetailMutationPending !== transaction) return false;
  itemDetailMutationPending = null;
  context.itemFingerprint = itemDetailValueFingerprint(target.item);
  context.locationFingerprint = itemDetailLocationFingerprint(target);
  setItemDetailMutationBusy(root, false);
  renderBoard();
  if (opts.pane !== false) renderItemDetail();
  else {
    syncItemDetailHeading(target.item);
    if (typeof opts.afterSuccess === 'function') opts.afterSuccess(target.item);
  }

  const liveRoot = document.getElementById('item-detail');
  if (liveRoot?.classList.contains('open') && liveRoot.dataset.itemId === context.itemId) {
    setItemDetailMutationStatus(liveRoot, 'detail.saved', 'success');
    itemDetailStatusTimer = setTimeout(() => {
      if (!isItemDetailMutationPending() && liveRoot.classList.contains('open') && liveRoot.dataset.itemId === context.itemId) {
        setItemDetailMutationStatus(liveRoot);
      }
      itemDetailStatusTimer = null;
    }, 2400);
  }
  return true;
}

function ensureItemDetailRoot() {
  let root = document.getElementById('item-detail');
  if (!root) {
    root = document.createElement('div');
    root.id = 'item-detail';
    document.body.appendChild(root);
    inheritActiveBodyInterlocks(root);
  }
  if (!root.__itemDetailPendingGuardBound) {
    root.addEventListener('click', handleItemDetailPendingClick, true);
    root.addEventListener('keydown', handleItemDetailPendingKeydownCapture, true);
    root.__itemDetailPendingGuardBound = true;
  }
  return root;
}

// Capture the invoking control before routed navigation rebuilds its surface.
// The item id is the fallback when that exact node no longer exists afterward.
function prepareItemDetailOpen(id, returnFocusKey = '', initialFocusKey = '') {
  const root = ensureItemDetailRoot();
  if (!root.classList.contains('open') || root.dataset.itemId !== String(id)) {
    rememberOpener(root);
    root.dataset.returnItemId = String(id);
    if (returnFocusKey) root.dataset.returnFocusKey = String(returnFocusKey);
    else delete root.dataset.returnFocusKey;
    if (initialFocusKey) root.dataset.initialFocusKey = String(initialFocusKey);
    else delete root.dataset.initialFocusKey;
  }
}

function setItemDetailBackgroundInert(enabled) {
  ['app', 'landing-layer'].forEach(id => {
    const el = document.getElementById(id);
    setElementInertOwner(el, 'detail', enabled);
  });
}

function focusItemDetailTarget(el, scroll = false) {
  if (!el || typeof el.focus !== 'function') return false;
  if (!el.matches(FOCUSABLE_SELECTOR) && !el.hasAttribute('tabindex')) el.setAttribute('tabindex', '-1');
  try {
    el.focus({ preventScroll: !scroll });
    if (scroll && typeof el.scrollIntoView === 'function') el.scrollIntoView({ block: 'nearest' });
  } catch {
    try { el.focus(); } catch {}
  }
  return document.activeElement === el;
}

function restoreItemDetailFocus(root, itemId, returnFocusKey = '') {
  if (restoreOpener(root)) return;
  const escaped = itemId && typeof CSS !== 'undefined' && typeof CSS.escape === 'function'
    ? CSS.escape(String(itemId))
    : String(itemId || '').replace(/["\\]/g, '\\$&');
  const escapedReturnKey = returnFocusKey && typeof CSS !== 'undefined' && typeof CSS.escape === 'function'
    ? CSS.escape(String(returnFocusKey))
    : String(returnFocusKey || '').replace(/["\\]/g, '\\$&');
  const selectors = [
    ...(escapedReturnKey ? [`.home-prow[data-home-preview-key="${escapedReturnKey}"]`] : []),
    ...(escaped ? [
      ...(escapedReturnKey === 'board-item-details'
        ? [`.item[data-id="${escaped}"] > .item-detail-meta`]
        : []),
      `.home-prow[data-item-id="${escaped}"]`,
      ...(escapedReturnKey ? [`.library-row[data-library-focus-key="${escapedReturnKey}"] .library-primary`] : []),
      `.library-row[data-id="${escaped}"] .library-more`,
      `.read-later-row[data-id="${escaped}"] .library-more`,
      `.item[data-id="${escaped}"] > .item-top[data-item-primary="true"]`,
      `.item[data-id="${escaped}"] > .item-top > [data-item-primary="true"]`,
      `.item[data-id="${escaped}"]`,
      `[data-item-id="${escaped}"][tabindex]`,
      `[data-id="${escaped}"] button`,
      `[data-id="${escaped}"]`,
    ] : []),
  ];
  const target = selectors.map(selector => document.querySelector(selector)).find(Boolean);
  if (focusItemDetailTarget(target, true)) return;
  const board = document.getElementById('board');
  focusItemDetailTarget(board?.querySelector('h1, [role="heading"]') || board);
}

function isItemDetailEditor(target) {
  if (!target || target.nodeType !== Node.ELEMENT_NODE) return false;
  if (['INPUT', 'TEXTAREA', 'SELECT'].includes(target.tagName)) return true;
  return !!target.closest('[contenteditable="true"]');
}

function flushActiveItemDetailEditor() {
  const root = document.getElementById('item-detail');
  const active = document.activeElement;
  if (!root?.classList.contains('open') || !root.contains(active) || !isItemDetailEditor(active)) return false;
  const editor = active.closest('[contenteditable="true"]') || active;
  try { editor.blur(); } catch { return false; }
  return true;
}

function flushItemDetailBeforePageHide() {
  if ((typeof isBoardLocalRecordCreatePending === 'function' && isBoardLocalRecordCreatePending())
      || isItemDetailMutationPending()
      || State.isRecoveryRequired?.()) return true;
  flushActiveItemDetailEditor();
  if (isItemDetailMutationPending() || State.isRecoveryRequired?.()) return true;
  // An editor may have blurred just before teardown, leaving its ordinary
  // debounce pending even though focus is now elsewhere or the sheet is closed.
  // Replace any dirty-state timer with an immediate write attempt;
  // recordMutation:false avoids counting the same edit twice.
  if (!State.needsPersistence()) return false;
  try { void State.persistNow({ recordMutation: false }); } catch {}
  return true;
}

function handleItemDetailKeydown(event, root) {
  if (event.key === 'Tab') {
    trapTabKey(event, root.querySelector('.idp-panel'));
    return;
  }
  const recovery = document.getElementById('state-recovery-overlay');
  if (recovery && !recovery.classList.contains('hidden')) return;
  if (isItemDetailMutationPending()) {
    event.preventDefault();
    event.stopPropagation();
    return;
  }
  if (event.key !== 'Escape') return;
  const reminder = document.getElementById('reminder-overlay');
  if (reminder && !reminder.classList.contains('hidden')) {
    event.preventDefault();
    event.stopPropagation();
    closeReminderPicker();
    return;
  }
  event.preventDefault();
  event.stopPropagation();
  if (isItemDetailEditor(event.target)) {
    const editor = event.target.closest('[contenteditable="true"]') || event.target;
    try { editor.blur(); } catch {}
    focusItemDetailTarget(root.querySelector('.idp-panel'));
    return;
  }
  closeItemDetail();
}

function detailRecurLabel(recur) {
  const interval = Math.max(1, Number(recur?.interval) || 1);
  if (recur?.every === 'day') return interval === 1 ? tr('detail.daily') : tr('detail.everyDays', { count: interval });
  if (recur?.every === 'week') return interval === 1 ? tr('detail.weekly') : tr('detail.everyWeeks', { count: interval });
  if (recur?.every === 'month') return interval === 1 ? tr('detail.monthly') : tr('detail.everyMonths', { count: interval });
  return '';
}

const DETAIL_PATHS = {
  chevron: 'M4.5 6.5 8 10l3.5-3.5',
  copy: 'M5.5 5.5h8v8h-8zM2.5 10.5v-8h8',
  clock: 'M8 14A6 6 0 1 0 8 2a6 6 0 0 0 0 12zM8 5v3.2l2 1.3',
  check: 'M3.5 8.5l3 3 6-7',
  repeat: 'M13 8a5 5 0 1 1-1.5-3.6M13 2.5v3h-3',
  archive: 'M2.5 3.5h11v3h-11zM3.5 6.5v6h9v-6M6.5 9h3',
};

function detailSvg(name, size = 16, stroke = 1.6, cls = '') {
  return `<svg${cls ? ` class="${cls}"` : ''} width="${size}" height="${size}" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="${stroke}" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${DETAIL_PATHS[name] || ''}"/></svg>`;
}

// The reminder chip's time: Today/Tomorrow/weekday as the Inbox rows say it,
// then the date with its time further out.
function detailWhenLabel(at, now = Date.now()) {
  const day = planDayStart(at);
  const today = planDayStart(now);
  if (day >= today && day < planAddDays(today, 7)) return inboxWhenLabel(at, now);
  return `${new Date(at).toLocaleDateString(appLocale(), { month: 'short', day: 'numeric' })} ${planTimeLabel(at)}`;
}

// A page title or a to-do's text is the panel's display title: one line of
// text that wraps and grows. Enter commits it, as Escape does.
function detailTitleField(value, label, focusKey) {
  const field = document.createElement('textarea');
  field.className = 'idp-title-input dtl-title';
  field.rows = 1;
  field.value = value || '';
  field.placeholder = label;
  field.setAttribute('aria-label', label);
  field.dataset.idpFocus = focusKey;
  field.spellcheck = false;
  const fit = () => {
    field.style.height = 'auto';
    if (field.scrollHeight) field.style.height = `${field.scrollHeight}px`;
  };
  field.addEventListener('input', () => {
    if (/[\r\n]/.test(field.value)) {
      const caret = field.selectionStart;
      field.value = field.value.replace(/[\r\n]+/g, ' ');
      field.setSelectionRange(caret, caret);
    }
    fit();
  });
  field.addEventListener('keydown', event => {
    if (event.key !== 'Enter' || event.isComposing) return;
    event.preventDefault();
    field.blur();
    focusItemDetailTarget(field.closest('.idp-panel'));
  });
  requestAnimationFrame(fit);
  return field;
}

// The underline under the title turns green once the edit is stored.
function flashDetailTitleSaved(field) {
  const line = field?.parentElement?.querySelector('.dtl-tline');
  if (!line) return;
  line.classList.remove('is-saved');
  void line.offsetWidth;
  line.classList.add('is-saved');
}

// Move from the panel: the Inbox page's filterable Space picker, folded open
// under the location, then the same move transaction and its Undo receipt.
// The panel repaints at the new location, or closes when the item has left
// the page it was opened from.
function openItemDetailMovePicker(it, anchor) {
  const host = anchor?.closest('.idp-panel')?.querySelector('.dtl-move');
  if (!host) return false;
  return openInboxItemMovePicker(it, anchor, (option, owner) => {
    void commitItemDetailMove(option, owner);
  }, { host });
}

async function commitItemDetailMove(option, opener) {
  if (!option?.review || !option.destinationContext) return false;
  const changed = await commitSelectedItemMove(option.review, option.destinationContext, opener, { messageKey: 'detail.movedTo' });
  if (changed) renderItemDetail();
  return changed;
}

// The quick reminder sheet folds open under the Reminder row.
function toggleItemDetailReminderSheet(root, open) {
  const sheet = root?.querySelector('.dtl-sheet');
  const toggle = root?.querySelector('[data-dtl-sheet-toggle]');
  if (!sheet || !toggle) return false;
  const next = open ?? sheet.hidden;
  if (next) {
    sheet.hidden = false;
    sheet.classList.remove('is-opening');
    void sheet.offsetWidth;
    sheet.classList.add('is-opening');
  } else {
    sheet.hidden = true;
  }
  toggle.setAttribute('aria-expanded', String(next));
  if (next) focusItemDetailTarget(sheet.querySelector('button'));
  return true;
}

function syncItemDetailHeading(it) {
  const heading = document.getElementById('idp-heading');
  if (heading) heading.textContent = _searchItemTitle(it) || _searchTypeLabel(it.type);
}

function detailItemMarkerPicker(it, commit) {
  const group = document.createElement('div');
  group.className = 'idp-marker-options';
  group.setAttribute('role', 'radiogroup');
  group.setAttribute('aria-label', tr('itemColor.menuLabel'));
  group.setAttribute('aria-orientation', 'horizontal');
  const storedColor = typeof it?.color === 'string' && it.color ? it.color : null;
  const current = itemMarkerChoice(it);
  const choices = current === 'custom'
    ? [...ITEM_MARKER_COLORS, 'custom']
    : ITEM_MARKER_COLORS;
  const buttons = [];

  const moveFocus = index => {
    const next = (index + buttons.length) % buttons.length;
    buttons.forEach((button, buttonIndex) => { button.tabIndex = buttonIndex === next ? 0 : -1; });
    buttons[next]?.focus({ preventScroll: true });
  };

  choices.forEach(color => {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'idp-marker-choice';
    button.dataset.marker = color;
    button.dataset.idpFocus = `marker-${color}`;
    button.setAttribute('role', 'radio');
    button.setAttribute('aria-checked', String(color === current));
    const label = color === 'custom'
      ? tr('groupEditor.color.custom')
      : (color === 'none'
        ? tr('itemColor.none')
        : tr('groupEditor.colorOption', { color: tr(`groupEditor.color.${color}`) }));
    button.setAttribute('aria-label', label);
    button.title = label;
    button.tabIndex = color === current ? 0 : -1;
    if (color === 'custom') button.style.setProperty('--item-custom-color', storedColor);
    button.addEventListener('click', () => {
      if (color === 'custom') return;
      void commit(tr('itemColor.history'), live => {
        if (color === 'none') delete live.color;
        else live.color = color;
      });
    });
    button.addEventListener('keydown', event => {
      const index = buttons.indexOf(button);
      if (event.key === 'ArrowRight' || event.key === 'ArrowDown') {
        event.preventDefault();
        moveFocus(index + 1);
      } else if (event.key === 'ArrowLeft' || event.key === 'ArrowUp') {
        event.preventDefault();
        moveFocus(index - 1);
      } else if (event.key === 'Home') {
        event.preventDefault();
        moveFocus(0);
      } else if (event.key === 'End') {
        event.preventDefault();
        moveFocus(buttons.length - 1);
      }
    });
    buttons.push(button);
    group.appendChild(button);
  });
  return group;
}

// The primary field(s) per item kind. Stack identity routes through the shared
// receipt-gated editor. Note and To-do cards stay read-only and route here.
function detailPrimaryEditor(it, commit) {
  const wrap = document.createElement('div');
  wrap.className = 'idp-primary';
  if (it.type === 'note') {
    const editor = document.createElement('div');
    editor.className = 'idp-note-editor note-text';
    editor.contentEditable = 'true';
    editor.spellcheck = false;
    editor.dataset.idpFocus = 'note-body';
    editor.setAttribute('role', 'textbox');
    editor.setAttribute('aria-multiline', 'true');
    editor.setAttribute('aria-label', tr('note.editorLabel'));
    editor.setAttribute('data-placeholder', tr('note.placeholder'));
    editor.innerHTML = sanitizeHtml(it.html || '');
    editor.addEventListener('blur', () => {
      if (isRichTextLinkEditorOwned(editor)) return;
      const rawHtml = editor.innerHTML;
      const html = autoLinkify(sanitizeHtml(rawHtml));
      if (html === (it.html || '')) {
        if (rawHtml !== (it.html || '')) editor.innerHTML = sanitizeHtml(it.html || '');
        return;
      }
      void commit(tr('note.history.edit'), live => { live.html = html; }, {
        pane: false,
        afterSuccess: live => { editor.innerHTML = sanitizeHtml(live.html || ''); },
      });
    });
    editor.addEventListener('keydown', event => {
      if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'b') { event.preventDefault(); document.execCommand('bold'); }
      if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'i') { event.preventDefault(); document.execCommand('italic'); }
      if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'u') { event.preventDefault(); document.execCommand('underline'); }
    });
    wrap.appendChild(editor);
    return wrap;
  }
  // Pages and stacks lead with their mark; a to-do leads with its check.
  wrap.classList.add('dtl-prim');
  const titleWrap = document.createElement('div');
  titleWrap.className = 'dtl-tw';
  const line = '<span class="dtl-tline" aria-hidden="true"></span>';
  if (it.type === 'tab') {
    wrap.insertAdjacentHTML('afterbegin', inboxFavMarkup(it, true));
    const t = detailTitleField(it.title, tr('detail.title'), 'title');
    const u = document.createElement('input');
    u.className = 'idp-url-input dtl-url';
    u.value = it.url || '';
    u.placeholder = tr('detail.url');
    u.setAttribute('aria-label', tr('detail.url'));
    u.dataset.idpFocus = 'url';
    u.spellcheck = false;
    u.autocomplete = 'off';
    t.addEventListener('change', () => {
      if (t.value !== it.title) {
        void commit(tr('detail.history.editTitle'), live => { live.title = t.value; }, {
          pane: false,
          afterSuccess: () => flashDetailTitleSaved(t),
        });
      }
    });
    u.addEventListener('change', () => {
      if (u.value !== it.url) {
        void commit(tr('detail.history.editUrl'), live => { live.url = u.value; }, { pane: false });
      }
    });
    const urlRow = document.createElement('div');
    urlRow.className = 'dtl-urow';
    const copy = document.createElement('button');
    copy.type = 'button';
    copy.className = 'dtl-ib';
    copy.dataset.idpFocus = 'copy-url';
    copy.setAttribute('aria-label', tr('itemAction.copyUrl'));
    copy.title = tr('itemAction.copyUrl');
    copy.innerHTML = detailSvg('copy', 15, 1.5);
    copy.onclick = () => { void copySavedTabUrl(it.url); };
    urlRow.appendChild(u);
    urlRow.appendChild(copy);
    titleWrap.appendChild(t);
    titleWrap.insertAdjacentHTML('beforeend', line);
    titleWrap.appendChild(urlRow);
    wrap.appendChild(titleWrap);
    bindInboxFavicons(wrap);
    return wrap;
  }
  if (it.type === 'todo') {
    wrap.classList.add('idp-todo-row');
    const chk = document.createElement('button'); chk.type = 'button'; chk.className = 'idp-todo-check' + (it.done ? ' done' : '');
    chk.dataset.idpFocus = 'todo-toggle';
    chk.setAttribute('aria-label', tr(it.done ? 'detail.markIncomplete' : 'detail.markComplete'));
    chk.setAttribute('aria-pressed', String(!!it.done));
    chk.innerHTML = `<span class="dtl-chk" aria-hidden="true">${detailSvg('check', 12, 2.6)}</span>`;
    chk.onclick = () => { void commit(tr('detail.history.updateTask'), live => { live.done = !live.done; }); };
    const t = detailTitleField(it.text, tr('detail.task'), 'task');
    t.addEventListener('change', () => {
      if (t.value !== it.text) {
        void commit(tr('detail.history.updateTask'), live => { live.text = t.value; }, {
          pane: false,
          afterSuccess: () => flashDetailTitleSaved(t),
        });
      }
    });
    titleWrap.appendChild(t);
    titleWrap.insertAdjacentHTML('beforeend', line);
    wrap.appendChild(chk);
    wrap.appendChild(titleWrap);
    return wrap;
  }
  // stack
  wrap.insertAdjacentHTML('afterbegin', inboxFavMarkup(it, true));
  const edit = document.createElement('button');
  edit.type = 'button';
  edit.className = 'idp-title-input idp-identity-button';
  edit.textContent = it.name || tr('stackEditor.defaultName');
  edit.dataset.idpFocus = 'stack-identity';
  edit.setAttribute('aria-label', tr('stackAction.editFor', { name: it.name || tr('stackEditor.defaultName') }));
  edit.onclick = event => {
    const identity = identityStackTarget(it.id);
    openIdentityEditor('stack', 'edit', {
      workspaceId: identity?.workspace.id,
      spaceId: identity?.space.id,
      groupId: identity?.group.id,
      stackId: it.id,
    }, event.currentTarget);
  };
  titleWrap.appendChild(edit);
  wrap.appendChild(titleWrap);
  return wrap;
}

// Re-render just the detail pane (used by paths that mutate an item's reminder
// through the shared setReminder/clearReminder flow, which only calls renderBoard).
function refreshDetailPane() { renderItemDetail(); }

function renderItemDetail() {
  let root = document.getElementById('item-detail');
  const id = currentDetailItemId();
  const ws = activeWs();
  const surface = activeGroupPage
    ? { wsId: ws?.id, groupId: activeGroupPage.groupId }
    : activeLibraryMode
      ? { wsId: ws?.id, libraryMode: activeLibraryMode }
      : activeHome
        ? { wsId: ws?.id }
        : (!activeSearch && !activeCalendar ? { wsId: ws?.id, catId: activeCat()?.id } : null);
  const homeTarget = activeHome ? resolveUniqueHomePreviewItem(ws?.id, id) : null;
  const searchTarget = activeSearch ? resolveUniqueHomePreviewItem(ws?.id, id) : null;
  const exactRecoveryTarget = homeTarget || searchTarget;
  const validId = activeHome || activeSearch
    ? (exactRecoveryTarget?.item?.id || null)
    : activeLibraryMode
      ? libraryDetailItemIdForRoute(ws, activeLibraryState, id)
      : (surface ? validDetailItemIdForSurface(id, surface) : null);
  const info = activeHome || activeSearch ? exactRecoveryTarget : (validId ? findItem(validId) : null);
  const wasOpen = !!root?.classList.contains('open');
  const previousItemId = root?.dataset.itemId || '';
  const returnItemId = root?.dataset.returnItemId || previousItemId || id || '';
  const returnFocusKey = root?.dataset.returnFocusKey || '';
  const initialFocusKey = root?.dataset.initialFocusKey || '';
  // The Move picker folds open inside the panel; a repaint replaces it.
  if (inboxSpacePicker?.el && root?.contains(inboxSpacePicker.el)) closeInboxSpacePicker();

  // Nothing open, or a stale/deleted id in the URL → tear the pane down and drop
  // the dead id so Router.sync() normalizes the address bar on the next tick.
  if (!info) {
    if (wasOpen) flushActiveItemDetailEditor();
    clearItemDetailStatusTimer();
    const reminderOverlay = document.getElementById('reminder-overlay');
    if (reminderOverlay && !reminderOverlay.classList.contains('hidden')) closeReminderPicker();
    if (root) {
      root.classList.remove('open');
      root.classList.remove('is-entering');
      setElementInertOwner(root, 'reminder', false);
      root.onkeydown = null;
      root.innerHTML = '';
      delete root.dataset.itemId;
      delete root.dataset.advancedItemId;
      delete root.dataset.advancedOpen;
      delete root.dataset.returnFocusKey;
      delete root.dataset.initialFocusKey;
      delete root.dataset.location;
      delete root.dataset.reminderAt;
    }
    document.body.classList.remove('detail-open');
    setItemDetailBackgroundInert(false);
    if (id) {
      if (activeGroupPage) activeGroupPage.itemId = null;
      else boardDetailItemId = null;
      if (activeSearch) activeSearch.detailOpen = false;
    }
    if (wasOpen && root) {
      setTimeout(() => {
        if (!root.classList.contains('open')) restoreItemDetailFocus(root, returnItemId, returnFocusKey);
      }, 0);
    }
    return;
  }
  const it = info.item;
  root = root || ensureItemDetailRoot();
  const sameItem = wasOpen && previousItemId === String(id);
  const focusOwner = sameItem && root.contains(document.activeElement)
    ? document.activeElement.closest('[data-idp-focus]')
    : null;
  const focusKey = focusOwner?.dataset.idpFocus || '';
  const savedAdvancedOpen = root.dataset.advancedItemId === String(id) ? root.dataset.advancedOpen : null;

  root.dataset.itemId = String(id);
  if (!sameItem) root.dataset.returnItemId = String(id);
  delete root.dataset.initialFocusKey;
  root.classList.add('open');
  // The panel slides in when it opens, not on every repaint after an edit.
  root.classList.toggle('is-entering', !wasOpen);
  // Details is the one floating layer: an open menu, the command palette or the
  // Today drawer gives way.
  if (!wasOpen) {
    hideContextMenu();
    closeCommandPalette();
    if (typeof isTodayTabsDrawerOpen === 'function' && isTodayTabsDrawerOpen()) {
      setTodayTabsDrawer(false, { restoreFocus: false });
    }
  }
  const reminderOverlay = document.getElementById('reminder-overlay');
  setElementInertOwner(root, 'reminder', !!(reminderOverlay && !reminderOverlay.classList.contains('hidden')));
  root.onkeydown = event => handleItemDetailKeydown(event, root);
  document.body.classList.add('detail-open');
  setItemDetailBackgroundInert(true);

  // Freeze the rendered owner/path/item before wiring fields. Every direct
  // detail edit re-resolves this context and crosses the shared receipt gate.
  const mutationContext = createItemDetailMutationContext(info);
  const commit = (label, fn, opts = {}) => commitItemDetailMutation(mutationContext, label, fn, opts);

  const heading = _searchItemTitle(it) || _searchTypeLabel(it.type);
  const locationLabel = [info.ws?.name || ws?.name, info.cat?.name, info.group?.name]
    .filter(Boolean)
    .join(' › ');
  const canOpenDetailTab = it.type === 'tab' && isOpenableSavedTabUrl(it.url);
  // What the last paint showed for this item: a new location rolls in after a
  // Move (or its Undo), and a new reminder time fills the chip once.
  const locationRolls = sameItem && root.dataset.location != null && root.dataset.location !== locationLabel;
  const storedReminderAt = it.reminder?.at ? String(it.reminder.at) : '';
  const reminderFills = sameItem && !!storedReminderAt && root.dataset.reminderAt != null
    && root.dataset.reminderAt !== storedReminderAt;
  root.dataset.location = locationLabel;
  root.dataset.reminderAt = storedReminderAt;
  const fx = itemDetailFx?.itemId === String(id) ? itemDetailFx.kind : '';
  itemDetailFx = null;
  const movable = !!createSelectedItemMutationContext([String(it.id)]);
  const kind = ['tab', 'note', 'todo', 'stack'].includes(it.type) ? it.type : 'tab';
  const groupColor = reminderDotColor(info.group?.color || null);
  const bandColor = typeof it.cover?.color === 'string' && it.cover.color ? it.cover.color : groupColor;
  const locationMarkup = `<span class="dtl-dot" aria-hidden="true" style="--dot:${esc(groupColor)}"></span><span class="idp-location${locationRolls ? ' is-moved' : ''}" id="idp-location">${esc(locationLabel)}</span>`;
  root.innerHTML = `
    <div class="idp-scrim" aria-hidden="true"></div>
    <aside class="idp-panel" role="dialog" aria-modal="true" aria-labelledby="idp-heading" aria-describedby="idp-location" tabindex="-1">
      <div class="dtl-band" aria-hidden="true" style="--dtl-band:${esc(bandColor)}"></div>
      <header class="idp-hd">
        <div class="idp-hd-copy">
          <div class="idp-docket-line">
            <span class="idp-type idp-type-${esc(it.type)}">${esc(tr(`detail.kind.${kind}`))}</span>
            ${movable
              ? `<button type="button" class="dtl-loc" data-idp-focus="move" aria-expanded="false" aria-label="${esc(tr('detail.moveFrom', { location: locationLabel }))}" title="${esc(tr('inbox.moveToSpace'))}">${locationMarkup}${detailSvg('chevron', 12, 1.9, 'dtl-loc-chev')}</button>`
              : `<span class="dtl-loc is-static">${locationMarkup}</span>`}
          </div>
          <h2 class="idp-heading sr-only" id="idp-heading">${esc(heading)}</h2>
          <span class="idp-save-status" data-idp-save-status role="status" aria-live="polite" aria-atomic="true"></span>
        </div>
        <div class="idp-actions">
          <button class="idp-close" type="button" data-idp-focus="close" title="${esc(tr('detail.closeTitle'))}" aria-label="${esc(tr('detail.close'))}">
            <svg width="14" height="14" viewBox="0 0 16 16" aria-hidden="true"><path d="M4 4l8 8M12 4l-8 8" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>
          </button>
        </div>
      </header>
      <div class="dtl-move"></div>
      <div class="idp-body"></div>
      <footer class="dtl-foot">
        <button type="button" class="dtl-fbtn" data-idp-focus="archive">${detailSvg('archive', 15, 1.5)}<span>${esc(tr('itemAction.archive'))}</span></button>
      </footer>
    </aside>`;
  root.querySelector('.idp-scrim').onclick = closeItemDetail;
  root.querySelector('.idp-close').onclick = closeItemDetail;
  const moveButton = root.querySelector('button.dtl-loc');
  if (moveButton) moveButton.onclick = () => openItemDetailMovePicker(it, moveButton);
  const archiveButton = root.querySelector('.dtl-fbtn');
  archiveButton.onclick = async () => {
    let changed;
    if (it.type === 'tab') changed = await archiveSavedPage(it, archiveButton);
    else if (it.type === 'stack') changed = archiveItem(it.id) !== false;
    else changed = await archiveBoardLocalItem(it, archiveButton);
    if (changed) renderItemDetail();
  };
  const body = root.querySelector('.idp-body');

  const section = (title, parent = body, extraClass = '') => {
    const s = document.createElement('section');
    s.className = `idp-sec${extraClass ? ` ${extraClass}` : ''}`;
    if (title) { const h = document.createElement('h3'); h.className = 'idp-sec-t'; h.textContent = title; s.appendChild(h); }
    if (parent) parent.appendChild(s);
    return s;
  };

  // ── Primary editor ───────────────────────────────────────────────
  const primarySection = section(null, body, 'idp-primary-sec');
  primarySection.appendChild(detailPrimaryEditor(it, commit));
  // A page's actions: Open, then its Favorite and Read later marks, which use
  // the Library's receipt-gated toggles and their Undo receipts.
  if (it.type === 'tab') {
    const favoriteLabel = tr(it.favorite ? 'itemAction.removeFavorite' : 'itemAction.addFavorite');
    const laterLabel = tr(it.readLaterAt ? 'itemAction.removeReadLater' : 'itemAction.saveReadLater');
    const burst = fx === 'favorite'
      ? `<span class="dtl-burst" aria-hidden="true">${INBOX_BURST_RAYS.map(angle => `<span class="ibx-ray" style="--a:${angle}deg"><span class="dtl-pt"></span></span>`).join('')}</span>`
      : '';
    const acts = document.createElement('div');
    acts.className = 'dtl-acts';
    acts.innerHTML = `
      ${canOpenDetailTab ? `<button class="idp-open idp-btn primary" type="button" data-idp-focus="open">${esc(tr('detail.open'))}</button>` : ''}
      <button type="button" class="dtl-tgl dtl-star${it.favorite ? ' is-on' : ''}${fx === 'favorite' ? ' is-pop' : ''}" data-idp-focus="favorite" aria-pressed="${!!it.favorite}" aria-label="${esc(favoriteLabel)}" title="${esc(favoriteLabel)}">${librarySvg('star', 19, 1.35)}${burst}</button>
      <button type="button" class="dtl-tgl dtl-later${it.readLaterAt ? ' is-on' : ''}${fx === 'later' ? ' is-pop' : ''}" data-idp-focus="read-later" aria-pressed="${!!it.readLaterAt}" aria-label="${esc(laterLabel)}" title="${esc(laterLabel)}">${libraryLaterSvg(18)}</button>`;
    primarySection.appendChild(acts);
    const receipt = { undo: true, sub: planSortMeta(it).domain || it.url || '' };
    const toggleFrom = (button, toggle, kindOn) => async () => {
      const turningOn = button.getAttribute('aria-pressed') !== 'true';
      const changed = await toggle(it, button, receipt);
      if (!changed) return;
      itemDetailFx = turningOn ? { itemId: String(it.id), kind: kindOn } : null;
      renderItemDetail();
    };
    const star = acts.querySelector('.dtl-star');
    const later = acts.querySelector('.dtl-later');
    star.onclick = toggleFrom(star, toggleFavorite, 'favorite');
    later.onclick = toggleFrom(later, toggleReadLater, 'later');
  }
  const openButton = root.querySelector('.idp-open');
  if (openButton) openButton.onclick = () => openSavedTabItem(it, { focus: true, opener: openButton });

  if (it.type === 'note' || it.type === 'todo') {
    const markerSection = section(tr('itemColor.menuLabel'), body, 'idp-context-sec idp-marker-sec');
    markerSection.appendChild(detailItemMarkerPicker(it, commit));
  }

  // ── Cover ────────────────────────────────────────────────────────
  const cov = section(tr('detail.cover'), null);
  const covRow = document.createElement('div'); covRow.className = 'idp-cover-row';
  DETAIL_COVER_COLORS.forEach((c, index) => {
    const b = document.createElement('button'); b.type = 'button';
    b.className = 'idp-swatch' + (it.cover && it.cover.color === c ? ' sel' : '');
    b.style.background = c;
    b.dataset.idpFocus = `cover-color-${index}`;
    b.setAttribute('aria-label', tr('detail.coverColor', { color: c }));
    b.setAttribute('aria-pressed', String(it.cover?.color === c));
    b.onclick = () => { void commit(tr('detail.history.updateCover'), live => { live.cover = { color: c }; }); };
    covRow.appendChild(b);
  });
  const emo = document.createElement('input'); emo.className = 'idp-cover-emoji'; emo.maxLength = 2; emo.placeholder = '😀';
  emo.value = (it.cover && it.cover.emoji) || '';
  emo.dataset.idpFocus = 'cover-emoji';
  emo.setAttribute('aria-label', tr('detail.coverEmoji'));
  emo.addEventListener('change', () => {
    const value = emo.value.trim();
    void commit(tr('detail.history.updateCover'), live => {
      if (value) live.cover = { emoji: value };
      else delete live.cover;
    });
  });
  covRow.appendChild(emo);
  const clr = document.createElement('button'); clr.type = 'button'; clr.className = 'idp-cover-clear'; clr.textContent = tr('detail.clearCover');
  clr.dataset.idpFocus = 'cover-clear';
  clr.onclick = () => { void commit(tr('detail.history.updateCover'), live => { delete live.cover; }); };
  covRow.appendChild(clr);
  cov.appendChild(covRow);

  // ── Reminder ─────────────────────────────────────────────────────
  // The orange "when" chip, its repeat, and Change / Clear; Change (or Set
  // reminder…) folds open quick times and "Pick a time…" for the full picker.
  // Every path is the same exact-item receipt controller with its Undo.
  const rem = section(tr('detail.reminder'), null, 'idp-context-sec');
  const remWrap = document.createElement('div'); remWrap.className = 'idp-rem';
  const now = Date.now();
  if (it.reminder && it.reminder.at) {
    const at = pendingReminderTime(it.reminder, now) ?? Number(it.reminder.at);
    const past = at < now;
    const recur = it.reminder.recur ? detailRecurLabel(it.reminder.recur) : '';
    const whenText = [past ? tr('detail.pastDue') : '', detailWhenLabel(at, now)].filter(Boolean).join(' · ');
    remWrap.innerHTML = `<span class="dtl-chip${past ? ' is-past' : ''}${reminderFills ? ' is-fill' : ''}">${detailSvg('clock', 14, 1.7, 'dtl-chip-clock')}${detailSvg('check', 14, 2.6, 'dtl-chip-tick')}<span>${esc(whenText)}</span></span>${recur ? `<span class="dtl-rep">${detailSvg('repeat', 11, 2)}${esc(tr('detail.repeats', { schedule: recur }))}</span>` : ''}<span class="dtl-remacts"></span>`;
    const remActs = remWrap.querySelector('.dtl-remacts');
    const change = document.createElement('button'); change.type = 'button'; change.className = 'dtl-lnk'; change.textContent = tr('detail.changeReminder'); change.dataset.idpFocus = 'reminder-change'; change.dataset.dtlSheetToggle = 'true'; change.setAttribute('aria-expanded', 'false');
    const clr2 = document.createElement('button'); clr2.type = 'button'; clr2.className = 'dtl-lnk is-quiet'; clr2.textContent = tr('detail.clearReminder'); clr2.dataset.idpFocus = 'reminder-clear'; clr2.onclick = () => { void commitItemDetailReminderMutation(mutationContext, null); };
    remActs.appendChild(change); remActs.appendChild(clr2);
  } else {
    const set = document.createElement('button'); set.type = 'button'; set.className = 'dtl-btn'; set.innerHTML = `${detailSvg('clock', 15, 1.6)}<span>${esc(tr('detail.setReminder'))}</span>`; set.dataset.idpFocus = 'reminder-set'; set.dataset.dtlSheetToggle = 'true'; set.setAttribute('aria-expanded', 'false');
    remWrap.appendChild(set);
  }
  rem.appendChild(remWrap);
  const sheet = document.createElement('div');
  sheet.className = 'dtl-sheet';
  sheet.hidden = true;
  sheet.setAttribute('role', 'group');
  sheet.setAttribute('aria-label', tr('space.reminderFor', { name: heading }));
  sheet.innerHTML = `${SPACE_QUICK_TIMES.map(([offset, key], index) => `<button type="button" class="dtl-sho" data-offset="${offset}" data-idp-focus="reminder-quick-${index}" style="--dtl-d:${index * 30}ms"><span>${esc(tr(key))}</span><span class="dtl-mono">${esc(inboxWhenLabel(now + offset, now))}</span></button>`).join('')}
    <button type="button" class="dtl-sho is-custom" data-idp-focus="reminder-custom" style="--dtl-d:120ms"><span>${esc(tr('space.reminderCustom'))}</span></button>`;
  sheet.querySelectorAll('[data-offset]').forEach(button => {
    button.onclick = () => {
      void commitItemDetailReminderMutation(mutationContext, { at: Date.now() + Number(button.dataset.offset), recur: it.reminder?.recur });
    };
  });
  sheet.querySelector('.is-custom').onclick = () => openReminderPicker(it.id, mutationContext);
  sheet.addEventListener('keydown', event => {
    if (event.key !== 'Escape') return;
    event.preventDefault();
    event.stopPropagation();
    toggleItemDetailReminderSheet(root, false);
    focusItemDetailTarget(root.querySelector('[data-dtl-sheet-toggle]'));
  });
  rem.appendChild(sheet);
  rem.querySelector('[data-dtl-sheet-toggle]').onclick = () => toggleItemDetailReminderSheet(root);

  // ── Notes annotation (rich text, reuses the .note-text RT toolbar) ─
  const nsec = section(tr('detail.whySaved'), null, 'idp-context-sec');
  const ned = document.createElement('div');
  ned.className = 'idp-notes note-text';
  ned.contentEditable = 'true'; ned.spellcheck = false;
  ned.dataset.idpFocus = 'notes';
  ned.setAttribute('aria-label', tr('detail.whySaved'));
  ned.setAttribute('data-ph', tr('detail.notesPlaceholder'));
  ned.innerHTML = sanitizeHtml(it.notes || '');
  ned.addEventListener('blur', () => {
    if (isRichTextLinkEditorOwned(ned)) return;
    const html = sanitizeHtml(ned.innerHTML);
    if (html !== (it.notes || '')) {
      void commit(tr('detail.history.editNotes'), live => { live.notes = autoLinkify(html); }, {
        pane: false,
        afterSuccess: live => { ned.innerHTML = sanitizeHtml(live.notes || ''); },
      });
    }
  });
  ned.addEventListener('keydown', e => {
    if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'b') { e.preventDefault(); document.execCommand('bold'); }
    if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'i') { e.preventDefault(); document.execCommand('italic'); }
    if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'u') { e.preventDefault(); document.execCommand('underline'); }
  });
  nsec.appendChild(ned);

  // ── Tags (feed the tag: search operator) ──────────────────────────
  const tsec = section(tr('detail.tags'), null, 'idp-context-sec');
  const chips = document.createElement('div'); chips.className = 'idp-tags';
  (it.tags || []).forEach((tg, i) => {
    const c = document.createElement('span'); c.className = 'idp-tag';
    c.innerHTML = `<span>${esc(tg)}</span>`;
    const x = document.createElement('button'); x.type = 'button'; x.className = 'idp-tag-x'; x.setAttribute('aria-label', tr('detail.removeTag', { tag: tg })); x.textContent = '×';
    x.dataset.idpFocus = `tag-remove-${i}`;
    x.onclick = () => {
      void commit(tr('detail.history.updateTags'), live => {
        live.tags.splice(i, 1);
        if (!live.tags.length) delete live.tags;
      });
    };
    c.appendChild(x); chips.appendChild(c);
  });
  const tin = document.createElement('input'); tin.id = 'idp-tag-input'; tin.className = 'idp-tag-input'; tin.placeholder = tr('detail.addTag'); tin.spellcheck = false;
  tin.dataset.idpFocus = 'tag-add';
  tin.setAttribute('aria-label', tr('detail.addTag'));
  tin.addEventListener('keydown', e => {
    if (e.key === 'Enter') {
      e.preventDefault();
      const v = normalizeTag(tin.value);
      if (!v || (it.tags || []).includes(v)) return;
      void commit(tr('detail.history.updateTags'), live => { (live.tags = live.tags || []).push(v); });
    }
  });
  chips.appendChild(tin);
  tsec.appendChild(chips);

  // ── Checklist (mini sub-todos on any item) ────────────────────────
  const csec = section(tr('detail.checklist'), null);
  const list = it.checklist || [];
  if (list.length) {
    const cnt = document.createElement('span'); cnt.className = 'idp-sec-count';
    cnt.textContent = `${list.filter(x => x.done).length}/${list.length}`;
    csec.querySelector('.idp-sec-t').appendChild(cnt);
  }
  const cl = document.createElement('div'); cl.className = 'idp-checklist';
  list.forEach((row, i) => {
    const r = document.createElement('div'); r.className = 'idp-cl-row' + (row.done ? ' done' : '');
    const chk = document.createElement('button'); chk.type = 'button'; chk.className = 'idp-cl-check' + (row.done ? ' done' : ''); chk.setAttribute('aria-label', tr('detail.toggleChecklist', { item: row.text || tr('detail.checklistItem') }));
    chk.dataset.idpFocus = `check-toggle-${i}`;
    chk.setAttribute('aria-pressed', String(!!row.done));
    chk.onclick = () => {
      void commit(tr('detail.history.updateChecklist'), live => { live.checklist[i].done = !live.checklist[i].done; });
    };
    const tx = document.createElement('input'); tx.className = 'idp-cl-text'; tx.value = row.text || ''; tx.placeholder = tr('detail.checklistItem');
    tx.dataset.idpFocus = `check-text-${i}`;
    tx.setAttribute('aria-label', tr('detail.checklistItem'));
    tx.addEventListener('change', () => {
      if (tx.value !== row.text) {
        void commit(tr('detail.history.updateChecklist'), live => { live.checklist[i].text = tx.value; }, { pane: false });
      }
    });
    const x = document.createElement('button'); x.type = 'button'; x.className = 'idp-cl-x'; x.setAttribute('aria-label', tr('detail.removeChecklist', { item: row.text || tr('detail.checklistItem') })); x.textContent = '×';
    x.dataset.idpFocus = `check-remove-${i}`;
    x.onclick = () => {
      void commit(tr('detail.history.updateChecklist'), live => {
        live.checklist.splice(i, 1);
        if (!live.checklist.length) delete live.checklist;
      });
    };
    r.appendChild(chk); r.appendChild(tx); r.appendChild(x); cl.appendChild(r);
  });
  const addIn = document.createElement('input'); addIn.id = 'idp-cl-input'; addIn.className = 'idp-cl-add'; addIn.placeholder = tr('detail.addChecklist');
  addIn.dataset.idpFocus = 'check-add';
  addIn.setAttribute('aria-label', tr('detail.addChecklist'));
  addIn.addEventListener('keydown', e => {
    if (e.key === 'Enter') {
      e.preventDefault();
      const v = addIn.value.trim();
      if (!v) return;
      void commit(tr('detail.history.updateChecklist'), live => {
        (live.checklist = live.checklist || []).push({ text: v, done: false });
      });
    }
  });
  cl.appendChild(addIn);
  csec.appendChild(cl);

  // ── Custom fields (arbitrary label/value pairs) ───────────────────
  const fsec = section(tr('detail.customFields'), null);
  const cfList = it.customFields || [];
  const cf = document.createElement('div'); cf.className = 'idp-fields';
  cfList.forEach((row, i) => {
    const r = document.createElement('div'); r.className = 'idp-cf-row';
    const l = document.createElement('input'); l.className = 'idp-cf-label'; l.value = row.label || ''; l.placeholder = tr('detail.fieldLabel');
    l.dataset.idpFocus = `field-label-${i}`;
    l.setAttribute('aria-label', tr('detail.fieldLabel'));
    l.addEventListener('change', () => {
      if (l.value !== row.label) {
        void commit(tr('detail.history.updateFields'), live => { live.customFields[i].label = l.value; }, { pane: false });
      }
    });
    const v = document.createElement('input'); v.className = 'idp-cf-value'; v.value = row.value || ''; v.placeholder = tr('detail.fieldValue');
    v.dataset.idpFocus = `field-value-${i}`;
    v.setAttribute('aria-label', tr('detail.fieldValue'));
    v.addEventListener('change', () => {
      if (v.value !== row.value) {
        void commit(tr('detail.history.updateFields'), live => { live.customFields[i].value = v.value; }, { pane: false });
      }
    });
    const x = document.createElement('button'); x.type = 'button'; x.className = 'idp-cf-x'; x.setAttribute('aria-label', tr('detail.removeField', { label: row.label || tr('detail.fieldLabel') })); x.textContent = '×';
    x.dataset.idpFocus = `field-remove-${i}`;
    x.onclick = () => {
      void commit(tr('detail.history.updateFields'), live => {
        live.customFields.splice(i, 1);
        if (!live.customFields.length) delete live.customFields;
      });
    };
    r.appendChild(l); r.appendChild(v); r.appendChild(x); cf.appendChild(r);
  });
  const addBtn = document.createElement('button'); addBtn.type = 'button'; addBtn.className = 'idp-add-field'; addBtn.textContent = `+ ${tr('detail.addField')}`;
  addBtn.dataset.idpFocus = 'field-add';
  addBtn.onclick = () => {
    void commit(tr('detail.history.updateFields'), live => {
      (live.customFields = live.customFields || []).push({ label: '', value: '' });
    });
  };
  cf.appendChild(addBtn);
  fsec.appendChild(cf);

  // Keep recovery context primary. Decoration, checklist, and arbitrary fields
  // stay available without competing with the reason an item was saved.
  body.appendChild(nsec);
  body.appendChild(rem);
  body.appendChild(tsec);
  const advanced = document.createElement('details');
  advanced.className = 'idp-advanced';
  const hasAdvancedData = !!it.cover || !!it.checklist?.length || !!it.customFields?.length;
  advanced.open = savedAdvancedOpen == null ? hasAdvancedData : savedAdvancedOpen === 'true';
  const advancedSummary = document.createElement('summary');
  advancedSummary.className = 'idp-advanced-summary';
  advancedSummary.dataset.idpFocus = 'advanced';
  advancedSummary.textContent = tr('detail.more');
  const advancedBody = document.createElement('div');
  advancedBody.className = 'idp-advanced-body';
  advancedBody.appendChild(cov);
  advancedBody.appendChild(csec);
  advancedBody.appendChild(fsec);
  advanced.appendChild(advancedSummary);
  advanced.appendChild(advancedBody);
  body.appendChild(advanced);
  root.dataset.advancedItemId = String(id);
  root.dataset.advancedOpen = String(advanced.open);
  advanced.addEventListener('toggle', () => { root.dataset.advancedOpen = String(advanced.open); });

  setTimeout(() => {
    if (!root.classList.contains('open') || root.dataset.itemId !== String(id) || root.inert) return;
    const panel = root.querySelector('.idp-panel');
    if (!sameItem) {
      if (initialFocusKey) {
        const escapedInitialKey = typeof CSS !== 'undefined' && typeof CSS.escape === 'function'
          ? CSS.escape(initialFocusKey)
          : initialFocusKey;
        if (focusItemDetailTarget(root.querySelector(`[data-idp-focus="${escapedInitialKey}"]`))) return;
      }
      focusItemDetailTarget(panel);
      return;
    }
    if (focusKey) {
      const escapedKey = typeof CSS !== 'undefined' && typeof CSS.escape === 'function' ? CSS.escape(focusKey) : focusKey;
      if (focusItemDetailTarget(root.querySelector(`[data-idp-focus="${escapedKey}"]`))) return;
    }
    if (!root.contains(document.activeElement)) focusItemDetailTarget(panel);
  }, 0);
}

// ════════════════════════════════════════════════════════════════
// FLOATING TOOL WIDGETS - pop tools out as draggable mini windows
// ════════════════════════════════════════════════════════════════
const FLOATING_TOOLS = {
  pomodoro: { title: 'Pomodoro', icon: '🍅' },
  finance:  { title: 'Finance',  icon: '💰' },
  habits:   { title: 'Habits',   icon: '🔁' },
  water:    { title: 'Water',    icon: '💧' },
  goals:    { title: 'Goals',    icon: '🎯' },
  subs:     { title: 'Subs',     icon: '💳' },
  books:    { title: 'Reading',  icon: '📚' },
  workout:  { title: 'Workout',  icon: '💪' }
};

function getFloating() {
  const s = State.get();
  if (!s.floating) s.floating = [];
  return s.floating;
}

function popOutTool(toolKey) {
  const f = getFloating();
  if (f.find(x => x.tool === toolKey)) {
    toast('Already floating');
    return;
  }
  f.push({
    tool: toolKey,
    x: 100 + f.length * 30,
    y: 100 + f.length * 30,
    w: 280,
    h: 200,
    minimized: false
  });
  // Close the source overlay
  const overlayMap = {
    pomodoro: 'pomo-overlay',
    finance:  'fin-overlay',
    habits:   'habit-overlay',
    water:    'water-overlay',
    goals:    'goals-overlay',
    subs:     'subs-overlay',
    books:    'books-overlay',
    workout:  'workout-overlay'
  };
  const ovId = overlayMap[toolKey];
  const ovEl = ovId ? document.getElementById(ovId) : null;
  if (ovEl && !ovEl.classList.contains('hidden')) {
    ovEl.classList.add('hidden');
    unlockBodyScroll();
  }
  State.persist();
  renderFloatingWidgets();
}

function closeFloating(toolKey) {
  const f = getFloating();
  const i = f.findIndex(x => x.tool === toolKey);
  if (i > -1) f.splice(i, 1);
  State.persist();
  renderFloatingWidgets();
}

function renderFloatingWidgets() {
  let layer = document.getElementById('floating-layer');
  if (!layer) {
    layer = document.createElement('div');
    layer.id = 'floating-layer';
    document.body.appendChild(layer);
  }
  const wanted = new Map(getFloating().map(w => [w.tool, w]));
  // Tear down widgets that are no longer in state. Leaving the rest alone
  // (instead of rebuilding everything) avoids the entrance animation
  // flickering on every open/close, and prevents global drag listeners
  // from being re-registered on widgets that didn't change.
  layer.querySelectorAll('.fw-window').forEach(el => {
    const tool = el.dataset.tool;
    if (!wanted.has(tool)) {
      if (el._abort) try { el._abort.abort(); } catch {}
      const body = el.querySelector('.fw-body');
      if (body && body._pomoUpdater) { clearInterval(body._pomoUpdater); body._pomoUpdater = null; }
      el.remove();
    } else {
      // Sync existing widget's position from state in case it changed.
      const w = wanted.get(tool);
      if (el.style.left !== w.x + 'px') el.style.left = w.x + 'px';
      if (el.style.top !== w.y + 'px') el.style.top = w.y + 'px';
      wanted.delete(tool);
    }
  });
  // Mount only newly added widgets — these animate in fresh.
  wanted.forEach(w => layer.appendChild(buildFloatingWidget(w)));
}

function buildFloatingWidget(w) {
  const meta = FLOATING_TOOLS[w.tool] || { title: w.tool, icon: '⚡' };
  const el = document.createElement('div');
  el.className = 'fw-window' + (w.minimized ? ' minimized' : '');
  el.dataset.tool = w.tool;
  el.style.left = w.x + 'px';
  el.style.top = w.y + 'px';
  if (!w.minimized) {
    el.style.width = w.w + 'px';
    el.style.height = w.h + 'px';
  }

  // Per-widget AbortController so global drag/resize listeners get cleaned
  // up when the widget is torn down (prevents listener-leak induced lag).
  const ac = new AbortController();
  el._abort = ac;
  const sig = ac.signal;

  el.innerHTML = `
    <div class="fw-titlebar">
      <span class="fw-icon">${meta.icon}</span>
      <span class="fw-title">${esc(meta.title)}</span>
      <div class="fw-actions">
        <button class="fw-btn" data-act="min" title="${w.minimized ? 'Restore' : 'Minimize'}">
          <svg width="10" height="10" viewBox="0 0 10 10"><path d="${w.minimized ? 'M2 4h6v2H2z' : 'M2 7h6'}" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" fill="none"/></svg>
        </button>
        <button class="fw-btn" data-act="open" title="Open full">
          <svg width="10" height="10" viewBox="0 0 10 10" fill="none"><path d="M3 1.5H2A.5.5 0 001.5 2v1M7 1.5h1A.5.5 0 018.5 2v1M3 8.5H2A.5.5 0 011.5 8V7M7 8.5h1A.5.5 0 008.5 8V7" stroke="currentColor" stroke-width="1.3" stroke-linecap="round"/></svg>
        </button>
        <button class="fw-btn fw-close" data-act="close" title="Close">
          <svg width="9" height="9" viewBox="0 0 10 10"><path d="M2 2l6 6M8 2l-6 6" stroke="currentColor" stroke-width="1.4" stroke-linecap="round"/></svg>
        </button>
      </div>
    </div>
    <div class="fw-body" id="fw-body-${w.tool}"></div>
    <div class="fw-resize"></div>`;

  // Render compact tool view
  const body = el.querySelector('.fw-body');
  if (!w.minimized) renderFloatingBody(w.tool, body);

  // Buttons
  el.querySelectorAll('.fw-btn').forEach(b => {
    b.onclick = (ev) => {
      ev.stopPropagation();
      const a = b.dataset.act;
      if (a === 'close') closeFloating(w.tool);
      else if (a === 'min') {
        w.minimized = !w.minimized;
        State.persist();
        toggleFloatingMinimize(el, w);
      } else if (a === 'open') {
        // Open the full tool overlay AND remove from floating
        closeFloating(w.tool);
        if (w.tool === 'pomodoro') openPomo();
        else if (w.tool === 'finance') openFin();
        else if (w.tool === 'habits') openHabits();
        else if (w.tool === 'water') openWater();
        else if (w.tool === 'goals') openGoals();
        else if (w.tool === 'subs') openSubsTracker();
        else if (w.tool === 'books') openBooks();
        else if (w.tool === 'workout') openWorkout();
      }
    };
  });

  // Drag the title bar — rAF throttled to keep at 60fps and avoid jank
  // even when several widgets are open.
  const tb = el.querySelector('.fw-titlebar');
  let dragging = false, startX = 0, startY = 0, startLeft = 0, startTop = 0;
  tb.addEventListener('mousedown', (e) => {
    if (e.target.closest('.fw-actions')) return;
    dragging = true;
    startX = e.clientX; startY = e.clientY;
    startLeft = w.x; startTop = w.y;
    el.classList.add('fw-dragging');
    el.style.zIndex = 9999;
    e.preventDefault();
  }, { signal: sig });
  const onMove = rafThrottle((e) => {
    if (!dragging) return;
    w.x = Math.max(0, Math.min(window.innerWidth - 60, startLeft + (e.clientX - startX)));
    w.y = Math.max(0, Math.min(window.innerHeight - 30, startTop + (e.clientY - startY)));
    el.style.left = w.x + 'px';
    el.style.top = w.y + 'px';
  });
  const onUp = () => {
    if (!dragging) return;
    dragging = false;
    el.classList.remove('fw-dragging');
    State.persist();
  };
  document.addEventListener('mousemove', onMove, { signal: sig });
  document.addEventListener('mouseup', onUp, { signal: sig });

  // Resize
  const resizer = el.querySelector('.fw-resize');
  if (resizer && !w.minimized) {
    let resizing = false, rsx = 0, rsy = 0, rsw = 0, rsh = 0;
    resizer.addEventListener('mousedown', (e) => {
      resizing = true;
      rsx = e.clientX; rsy = e.clientY;
      rsw = w.w; rsh = w.h;
      e.stopPropagation();
      e.preventDefault();
    }, { signal: sig });
    const onResMove = rafThrottle((e) => {
      if (!resizing) return;
      w.w = Math.max(220, rsw + (e.clientX - rsx));
      w.h = Math.max(120, rsh + (e.clientY - rsy));
      el.style.width = w.w + 'px';
      el.style.height = w.h + 'px';
    });
    const onResUp = () => {
      if (!resizing) return;
      resizing = false;
      State.persist();
      renderFloatingBody(w.tool, body);
    };
    document.addEventListener('mousemove', onResMove, { signal: sig });
    document.addEventListener('mouseup', onResUp, { signal: sig });
  }

  // Bring to front on click
  el.addEventListener('mousedown', () => {
    el.style.zIndex = 9999;
    document.querySelectorAll('.fw-window').forEach(o => { if (o !== el) o.style.zIndex = 9990; });
  }, { signal: sig });

  return el;
}

// In-place minimize/restore avoids the full rebuild that re-runs the
// fwIn entrance animation across every widget (which is what made
// the popouts flicker on toggle).
function toggleFloatingMinimize(el, w) {
  if (w.minimized) {
    el.classList.add('minimized');
    el.style.width = '';
    el.style.height = '';
  } else {
    el.classList.remove('minimized');
    el.style.width = w.w + 'px';
    el.style.height = w.h + 'px';
    const body = el.querySelector('.fw-body');
    if (body) renderFloatingBody(w.tool, body);
  }
  const minBtn = el.querySelector('.fw-btn[data-act="min"]');
  if (minBtn) {
    minBtn.title = w.minimized ? 'Restore' : 'Minimize';
    minBtn.innerHTML = `<svg width="10" height="10" viewBox="0 0 10 10"><path d="${w.minimized ? 'M2 4h6v2H2z' : 'M2 7h6'}" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" fill="none"/></svg>`;
  }
}

function renderFloatingBody(tool, container) {
  if (tool === 'pomodoro') renderFloatingPomo(container);
  else if (tool === 'finance') renderFloatingFin(container);
  else if (tool === 'habits') renderFloatingHabits(container);
  else if (tool === 'water') renderFloatingWater(container);
  else if (tool === 'goals') renderFloatingGoals(container);
  else if (tool === 'subs') renderFloatingSubs(container);
  else if (tool === 'books') renderFloatingBooks(container);
  else if (tool === 'workout') renderFloatingWorkout(container);
}

function renderFloatingBooks(c) {
  const books = getBooks();
  const reading = books.filter(b => b.status === 'reading').length;
  const finishedYr = books.filter(b => {
    if (b.status !== 'finished' || !b.date) return false;
    return new Date(b.date).getFullYear() === new Date().getFullYear();
  }).length;
  const goal = getBooksCfg().yearlyGoal || 12;
  c.innerHTML = `
    <div class="fw-fin">
      <div class="fw-fin-stat">
        <div class="fw-fin-lbl">Currently reading</div>
        <div class="fw-fin-val">${reading}</div>
        <div class="fw-fin-sub">${finishedYr}/${goal} done this year</div>
      </div>
      <button class="fw-quickadd-btn" data-a="add">📖 Open shelves</button>
    </div>`;
  c.querySelector('[data-a=add]').onclick = () => { closeFloating('books'); openBooks(); };
}

function renderFloatingWorkout(c) {
  const wos = getWorkouts();
  const now = Date.now();
  const weekMs = 7 * 86400000;
  const weekCt = wos.filter(w => now - new Date(w.date).getTime() < weekMs);
  const weekMin = weekCt.reduce((a, w) => a + (Number(w.duration) || 0), 0);
  c.innerHTML = `
    <div class="fw-fin">
      <div class="fw-fin-stat">
        <div class="fw-fin-lbl">This week</div>
        <div class="fw-fin-val">${weekCt.length} · ${weekMin}m</div>
        <div class="fw-fin-sub">🔥 ${computeWorkoutStreak()} day streak</div>
      </div>
      <button class="fw-quickadd-btn" data-a="add">+ Log workout</button>
    </div>`;
  c.querySelector('[data-a=add]').onclick = () => { closeFloating('workout'); openWorkout(); };
}

function renderFloatingPomo(c) {
  const p = getPomo();
  const total = (pomoState.mode === 'focus' ? p.settings.focus : pomoState.mode === 'short' ? p.settings.short : p.settings.long) * 60;
  const remaining = pomoState.remaining || total;
  const m = Math.floor(remaining / 60);
  const s = remaining % 60;
  c.innerHTML = `
    <div class="fw-pomo">
      <div class="fw-pomo-time">${m}:${String(s).padStart(2,'0')}</div>
      <div class="fw-pomo-mode">${pomoState.mode}</div>
      <div class="fw-pomo-ctrls">
        <button class="fw-mini-btn" data-a="reset"><svg width="11" height="11" viewBox="0 0 12 12" fill="none"><path d="M10 4.5a4 4 0 10-1 5m1-5V2m0 2.5h-2.5" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"/></svg></button>
        <button class="fw-mini-btn primary" data-a="toggle">${pomoState.running ? '⏸' : '▶'}</button>
        <button class="fw-mini-btn" data-a="skip"><svg width="11" height="11" viewBox="0 0 12 12" fill="none"><path d="M2 3l5 3-5 3V3zM9 3v6" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"/></svg></button>
      </div>
    </div>`;
  c.querySelectorAll('.fw-mini-btn').forEach(b => b.onclick = () => {
    const a = b.dataset.a;
    if (a === 'toggle') (pomoState.running ? pausePomoTimer() : startPomoTimer());
    else if (a === 'reset') resetPomo();
    else if (a === 'skip') onPomoFinish();
    setTimeout(() => renderFloatingBody('pomodoro', c), 50);
  });
  // Tick: only update the time text — full re-render only on state changes.
  if (pomoState.running && !c._pomoUpdater) {
    c._pomoUpdater = setInterval(() => {
      if (!document.contains(c)) { clearInterval(c._pomoUpdater); c._pomoUpdater = null; return; }
      const timeEl = c.querySelector('.fw-pomo-time');
      if (!timeEl) { clearInterval(c._pomoUpdater); c._pomoUpdater = null; return; }
      const mm = Math.floor(pomoState.remaining / 60);
      const ss = pomoState.remaining % 60;
      timeEl.textContent = `${mm}:${String(ss).padStart(2,'0')}`;
    }, 1000);
  } else if (!pomoState.running && c._pomoUpdater) {
    clearInterval(c._pomoUpdater);
    c._pomoUpdater = null;
  }
}

function renderFloatingFin(c) {
  const f = getFin();
  const cur = f.settings?.defaultCurrency || 'TWD';
  const sym = ({ USD:'$', EUR:'€', GBP:'£', TWD:'NT$', JPY:'¥', CNY:'¥', KRW:'₩' })[cur] || '$';
  const today = new Date().toISOString().slice(0, 10);
  const todayTxns = (f.txns || []).filter(t => (t.date || '').slice(0, 10) === today);
  const FX = { USD:1, EUR:1.09, GBP:1.28, TWD:0.031, JPY:0.0067, CNY:0.14, KRW:0.00074 };
  const totalToday = todayTxns.reduce((a, t) => a + Number(t.amount) * (FX[t.currency] || 1) / (FX[cur] || 1), 0);
  c.innerHTML = `
    <div class="fw-fin">
      <div class="fw-fin-stat">
        <div class="fw-fin-lbl">Today</div>
        <div class="fw-fin-val">${sym}${totalToday.toFixed(cur === 'JPY' || cur === 'KRW' ? 0 : 2)}</div>
        <div class="fw-fin-sub">${todayTxns.length} transactions</div>
      </div>
      <button class="fw-quickadd-btn" data-a="add">+ Quick log</button>
    </div>`;
  c.querySelector('[data-a=add]').onclick = () => { closeFloating('finance'); openFin(); };
}

function renderFloatingHabits(c) {
  const habits = getHabits();
  const today = new Date().toISOString().slice(0, 10);
  if (!habits.length) {
    c.innerHTML = `<div class="fw-empty">No habits yet</div>`;
    return;
  }
  c.innerHTML = `<div class="fw-habits">${habits.slice(0, 6).map(h => {
    const done = (h.dates || []).includes(today);
    return `<div class="fw-habit-row" data-id="${h.id}">
      <span class="fw-habit-icon">${esc(h.icon || '✅')}</span>
      <span class="fw-habit-name">${esc(h.name)}</span>
      <button class="fw-habit-toggle ${done ? 'done' : ''}" data-id="${h.id}">${done ? '✓' : ' '}</button>
    </div>`;
  }).join('')}</div>`;
  c.querySelectorAll('.fw-habit-toggle').forEach(btn => btn.onclick = () => {
    const h = habits.find(x => x.id === btn.dataset.id);
    if (!h) return;
    State.snapshot('Habit toggle');
    h.dates = h.dates || [];
    if (h.dates.includes(today)) h.dates = h.dates.filter(d => d !== today);
    else h.dates.push(today);
    State.persist();
    renderFloatingHabits(c);
  });
}

function renderFloatingWater(c) {
  const w = getWater();
  const today = new Date().toISOString().slice(0, 10);
  const cnt = w.days[today] || 0;
  const pct = Math.min(100, (cnt / w.goal) * 100);
  c.innerHTML = `
    <div class="fw-water">
      <div class="fw-water-bar"><div class="fw-water-fill" style="width:${pct}%"></div></div>
      <div class="fw-water-stat">${cnt} / ${w.goal} glasses</div>
      <div class="fw-water-ctrls">
        <button class="fw-mini-btn" data-a="-">−</button>
        <button class="fw-mini-btn primary" data-a="+">+ Glass</button>
      </div>
    </div>`;
  c.querySelectorAll('.fw-mini-btn').forEach(b => b.onclick = () => {
    State.snapshot('water');
    const w = getWater();
    if (b.dataset.a === '+') { w.days[today] = (w.days[today] || 0) + 1; w.total = (w.total || 0) + 1; }
    else { w.days[today] = Math.max(0, (w.days[today] || 0) - 1); w.total = Math.max(0, (w.total || 0) - 1); }
    State.persist();
    renderFloatingWater(c);
  });
}

function renderFloatingGoals(c) {
  const goals = getGoals();
  if (!goals.length) {
    c.innerHTML = `<div class="fw-empty">No goals yet</div>`;
    return;
  }
  c.innerHTML = `<div class="fw-goals">${goals.slice(0, 5).map(g => `
    <div class="fw-goal-row">
      <div class="fw-goal-name">${esc(g.name)}</div>
      <div class="fw-goal-bar"><div class="fw-goal-fill" style="width:${g.progress || 0}%"></div></div>
      <span class="fw-goal-pct">${g.progress || 0}%</span>
    </div>`).join('')}</div>`;
}

function renderFloatingSubs(c) {
  const subs = getSubs();
  if (!subs.length) {
    c.innerHTML = `<div class="fw-empty">No subscriptions yet</div>`;
    return;
  }
  const mainCur = State.get().subSettings?.defaultCurrency || 'USD';
  const monthlyUSD = subs.reduce((a, s) => a + subMonthlyCostUSD(s), 0);
  const monthly = monthlyUSD / (FX_TO_USD[mainCur] || 1);
  // Upcoming in 7 days (by next billing date)
  const upcoming = subs.filter(s => {
    if (s.paused) return false;
    const d = daysUntil(s.nextBilling);
    return d != null && d >= 0 && d <= 7;
  }).sort((a, b) => (daysUntil(a.nextBilling) ?? 9999) - (daysUntil(b.nextBilling) ?? 9999)).slice(0, 4);
  c.innerHTML = `
    <div class="fw-subs">
      <div class="fw-subs-stat">
        <div class="fw-subs-lbl">Monthly</div>
        <div class="fw-subs-val">${formatMoney(monthly, mainCur)}</div>
      </div>
      ${upcoming.length ? `<div class="fw-subs-up">${upcoming.map(s => `
        <div class="fw-subs-row">
          <span class="fw-subs-name">${esc(s.name)}</span>
          <span class="fw-subs-days">${(daysUntil(s.nextBilling) || 0)}d</span>
        </div>`).join('')}</div>` : `<div class="fw-empty">No upcoming bills</div>`}
    </div>`;
}

// ════════════════════════════════════════════════════════════════
// SPACE PAGE (2026-11 canvas)
// ════════════════════════════════════════════════════════════════
// A Space opens on one page: its name with the item count and its reminder,
// the Space actions, and one switcher for the seven views whose underline
// slides to the chosen view while the views crossfade. Board columns and List
// groups carry the group's count, to-dos, reminder chip and actions; Set
// reminder opens a sheet of quick times inside the page. Cards are the shared
// item builders, so their menus, selection, drag, reminders and Details keep
// working, and a card or group that was not on the last paint drops in. Every
// write is the same transaction as before, with its usual Undo.

const SPACE_VIEW_PATHS = {
  board: 'M2.5 3h4v10h-4zM9.5 3h4v10h-4z',
  list: 'M5.5 4h8M5.5 8h8M5.5 12h8M2.5 4h.01M2.5 8h.01M2.5 12h.01',
  canvas: 'M2 2h6v5H2zM9 3h5v4H9zM3 9h5v5H3zM9 9h5v3H9z',
  explorer: 'M2 3h3.6v10H2zM6.2 3h3.6v10H6.2zM10.4 3H14v10h-3.6z',
  timeline: 'M8 2v1M8 6v2M8 11v3M9.5 4.5H13M9.5 9.5H12M6.5 4.5a1.5 1.5 0 1 0 3 0 1.5 1.5 0 1 0-3 0M6.5 9.5a1.5 1.5 0 1 0 3 0 1.5 1.5 0 1 0-3 0',
  gallery: 'M2 2h5v6.5H2zM9 2h5v4H9zM2 10h5v4H2zM9 7.5h5V14H9z',
  graph: 'M6 4a2 2 0 1 0 4 0 2 2 0 1 0-4 0M1.8 11.5a1.7 1.7 0 1 0 3.4 0 1.7 1.7 0 1 0-3.4 0M10.8 11.5a1.7 1.7 0 1 0 3.4 0 1.7 1.7 0 1 0-3.4 0M6.8 5.7 4.7 10M9.2 5.7l2.1 4.3M5.2 11.5h5.6',
};
const SPACE_PATHS = {
  chevron: 'M4.5 6.5 8 10l3.5-3.5',
  openAll: 'M6.5 3.5H4a1 1 0 0 0-1 1V12a1 1 0 0 0 1 1h7.5a1 1 0 0 0 1-1V9.5M9.5 2.5h4v4M13.5 2.5 8 8',
  save: 'M8 2.5v7M5 6.8l3 3 3-3M3 12.5h10',
  addRecord: 'M2.5 4h6M2.5 8h6M2.5 12h4M12 7v6M9 10h6',
  plus: 'M8 3v10M3 8h10',
  clock: 'M8 14A6 6 0 1 0 8 2a6 6 0 0 0 0 12zM8 5v3.2l2 1.3',
  close: 'M4 4l8 8M12 4l-8 8',
  note: 'M3.5 2.5h6l3 3v8h-9zM9.5 2.5v3h3M5.5 8.5h5M5.5 11h3.5',
  stack: 'M2.5 5.5 8 3l5.5 2.5L8 8zM2.5 8.5 8 11l5.5-2.5M2.5 11.5 8 14l5.5-2.5',
  todo: 'M3 3h10v10H3zM5.5 8l2 2 3.5-4',
  tab: 'M6.2 9.8a2.6 2.6 0 0 0 3.7 0l2.7-2.7a2.6 2.6 0 1 0-3.7-3.7l-1 1M9.8 6.2a2.6 2.6 0 0 0-3.7 0L3.4 8.9a2.6 2.6 0 1 0 3.7 3.7l1-1',
  chevronRight: 'M6 3.5 10.5 8 6 12.5',
};
const SPACE_QUICK_TIMES = [
  [3600000, 'reminder.inOneHour'],
  [10800000, 'reminder.inThreeHours'],
  [86400000, 'reminder.tomorrow'],
  [604800000, 'reminder.nextWeek'],
];

function spaceSvg(path, size = 16, stroke = 1.6) {
  return `<svg width="${size}" height="${size}" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="${stroke}" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${SPACE_PATHS[path] || SPACE_VIEW_PATHS[path] || ''}"/></svg>`;
}

function isSpacePageActive() {
  return !activeSearch && !activeCalendar && !activeGroupPage && !activeLibraryMode && !activeHome && !!activeCat();
}

// What the last paint showed, so counts roll and new cards drop in only when
// something changed; `sheet` is the open reminder sheet and the control that
// opened it.
function spacePageState(catId) {
  if (!spacePageSession || spacePageSession.catId !== catId) {
    spacePageSession = {
      catId,
      view: null,
      host: null,
      total: null,
      remAt: undefined,
      counts: null,
      todos: null,
      groupRem: null,
      seenItems: null,
      seenGroups: null,
      sheet: null,
    };
  }
  return spacePageSession;
}

function spacePageRoot() {
  return document.querySelector('#board > .spc');
}

// The renderers draw into the Space page's current view, or into the board
// when no Space page is showing.
function spaceViewHost() {
  const host = spacePageSession?.host;
  return host?.isConnected && !host.classList.contains('is-out') ? host : document.getElementById('board');
}

function spaceReducedMotion() {
  return typeof planReducedMotion === 'function'
    ? planReducedMotion()
    : document.body?.dataset?.anim === 'off';
}

function spaceRestart(el, cls) {
  if (!el) return;
  el.classList.remove(cls);
  void el.offsetWidth;
  el.classList.add(cls);
}

// "N items" with the number rolling to its new value, in the locale's own
// word order.
function spaceItemsMarkup(count, previous, delay = 0) {
  const marker = '\u0001';
  const text = count === 1 ? tr('groupAction.oneItem') : tr('groupAction.items', { count: marker });
  const at = text.indexOf(marker);
  if (at < 0) return esc(text);
  return `${esc(text.slice(0, at))}<span class="spc-num">${spaceRollMarkup(count, previous, delay)}</span>${esc(text.slice(at + marker.length))}`;
}

// A count that changed rolls, using the Inbox count's roll; a repaint in the
// middle of the roll carries it on from where it was.
function spaceRollMarkup(count, previous, delay = 0) {
  const markup = libraryRollMarkup(count, previous);
  return delay > 0 ? markup.replace('<span class="ibx-roll-stack', `<span style="animation-delay:-${delay}ms" class="ibx-roll-stack`) : markup;
}

function spaceCountRoll(session, key, count) {
  if (!session) return { previous: null, delay: 0 };
  const now = Date.now();
  const previous = session.counts?.get(key);
  session.rolls = session.rolls || new Map();
  if (previous != null && previous !== count) session.rolls.set(key, { from: previous, to: count, at: now });
  const roll = session.rolls.get(key);
  if (!roll || roll.to !== count || now - roll.at > 400) return { previous: null, delay: 0 };
  return { previous: roll.from, delay: now - roll.at };
}

function spaceItemsLabel(count) {
  return count === 1 ? tr('groupAction.oneItem') : tr('groupAction.items', { count });
}

// The reminder a chip shows: the next pending one, else the first stored.
function spaceReminderTarget(entity, now = Date.now()) {
  const list = Array.isArray(entity?.reminders) ? entity.reminders : [];
  let best = null;
  list.forEach(reminder => {
    const at = pendingReminderTime(reminder, now);
    if (at == null) return;
    if (!best || at < best.at) best = { reminder, at };
  });
  if (best) return best;
  return list.length ? { reminder: list[0], at: null } : null;
}

function spaceCreateGroup(opener) {
  const workspace = activeWs();
  const cat = activeCat();
  return openIdentityEditor('group', 'create', {
    workspaceId: workspace?.id,
    spaceId: cat?.id,
  }, opener);
}

function spaceActionMenuItems(cat, opener) {
  const ws = activeWs();
  if (!ws || !cat) return [];
  const hasReminder = Array.isArray(cat.reminders) && cat.reminders.length > 0;
  return [
    { text: tr('organization.renameMenu'), icon: cmIcons.edit, action: () => openOrganizationName('space', cat.id, opener) },
    { text: `${tr(hasReminder ? 'reminder.editTitle' : 'reminder.setTitle')}…`, icon: cmIcons.clock, action: () => openSpaceSheet('category', cat.id, opener) },
    ...(ws.categories.length > 1 ? [
      { sep: true },
      { text: tr('organization.space.delete'), icon: cmIcons.delete, danger: true, action: () => openOrganizationDelete('space', cat.id, opener) },
    ] : []),
  ];
}

// On this page the shared Group menu's Set reminder opens the page's
// reminder sheet; every other action is unchanged.
function spaceGroupMenu(entries, g, opener) {
  const setReminder = tr('groupAction.setReminder');
  return entries.map(entry => (
    entry.text === setReminder ? { ...entry, action: () => openSpaceSheet('group', g.id, opener) } : entry
  ));
}

function focusSpaceKey(key) {
  if (!key) return false;
  const page = spacePageRoot();
  return inboxFocus(page?.querySelector(`[data-spc-focus="${CSS.escape(String(key))}"]`));
}

// ── The reminder sheet: quick times for the Space or one group ──
function openSpaceSheet(kind, id, opener = null) {
  const session = spacePageSession;
  if (!session || !findEntity(kind, id)) return false;
  hideContextMenu();
  const key = String(id);
  const ownerKey = opener?.closest?.('[data-spc-focus]')?.dataset.spcFocus
    || (kind === 'category' ? 'space-more' : `col:${key}:more`);
  if (session.sheet && session.sheet.kind === kind && session.sheet.id === key) return closeSpaceSheet({ restoreFocus: true });
  session.sheet = { kind, id: key, ownerKey, opening: true };
  renderBoard();
  if (spacePageSession?.sheet) spacePageSession.sheet.opening = false;
  focusSpaceKey('sheet:0');
  return true;
}

function closeSpaceSheet({ restoreFocus = false } = {}) {
  const session = spacePageSession;
  const sheet = session?.sheet;
  if (!sheet) return false;
  session.sheet = null;
  renderBoard();
  if (restoreFocus) focusSpaceKey(sheet.ownerKey);
  return true;
}

async function spaceSheetPick(kind, id, offset) {
  const target = spaceReminderTarget(findEntity(kind, id));
  const context = createEntityReminderMutationContext(kind, id, target?.reminder?.id ?? null);
  if (spacePageSession) spacePageSession.sheet = null;
  if (!context) {
    renderBoard();
    toast(tr('reminder.entityUnavailable'), { danger: true });
    return false;
  }
  const changed = await commitEntityReminderMutation(context, { at: Date.now() + offset });
  if (!changed) renderBoard();
  return changed;
}

async function spaceSheetClear(kind, id) {
  const target = spaceReminderTarget(findEntity(kind, id));
  const context = target ? createEntityReminderRemovalContext(kind, id, target.reminder?.id) : null;
  if (spacePageSession) spacePageSession.sheet = null;
  if (!context) {
    renderBoard();
    toast(tr('reminder.entityUnavailable'), { danger: true });
    return false;
  }
  const changed = await commitEntityReminderRemoval(context);
  if (!changed) renderBoard();
  return changed;
}

function spaceSheetCustom(kind, id) {
  const target = spaceReminderTarget(findEntity(kind, id));
  const ownerKey = spacePageSession?.sheet?.ownerKey;
  if (spacePageSession) spacePageSession.sheet = null;
  renderBoard();
  const opener = spacePageRoot()?.querySelector(`[data-spc-focus="${CSS.escape(String(ownerKey || ''))}"]`) || null;
  return openEntityReminderPickerOrReport(kind, id, target?.reminder?.id, { opener });
}

function buildSpaceSheet(kind, entity, opening = false) {
  const now = Date.now();
  const id = String(entity.id);
  const target = spaceReminderTarget(entity, now);
  const sheet = document.createElement('div');
  sheet.className = `spc-sheet${opening ? ' is-opening' : ''}`;
  sheet.setAttribute('role', 'group');
  sheet.setAttribute('aria-label', tr('space.reminderFor', { name: entity.name || '' }));
  sheet.innerHTML = `
    <div class="spc-shops">
      ${SPACE_QUICK_TIMES.map(([offset, key], index) => `<button type="button" class="spc-sho" data-offset="${offset}" data-spc-focus="sheet:${index}" style="--spc-d:${index * 30}ms"><span>${esc(tr(key))}</span><span class="spc-mono">${esc(inboxWhenLabel(now + offset, now))}</span></button>`).join('')}
      <button type="button" class="spc-sho" data-spc-sheet="custom" data-spc-focus="sheet:custom" style="--spc-d:120ms"><span>${esc(tr('space.reminderCustom'))}</span></button>
      ${target ? `<button type="button" class="spc-sho is-clear" data-spc-sheet="clear" data-spc-focus="sheet:clear" style="--spc-d:150ms"><span>${esc(tr('reminder.clear'))}</span>${target.at ? `<span class="spc-mono">${esc(inboxWhenLabel(target.at, now))}</span>` : ''}</button>` : ''}
    </div>
    <button type="button" class="spc-ibtn spc-shx" data-spc-sheet="close" data-spc-focus="sheet:close" aria-label="${esc(tr('organization.close'))}" title="${esc(tr('organization.close'))}">${spaceSvg('close', 13, 2)}</button>`;
  sheet.querySelectorAll('[data-offset]').forEach(button => {
    button.addEventListener('click', () => { void spaceSheetPick(kind, id, Number(button.dataset.offset)); });
  });
  sheet.querySelector('[data-spc-sheet="custom"]').addEventListener('click', () => spaceSheetCustom(kind, id));
  sheet.querySelector('[data-spc-sheet="clear"]')?.addEventListener('click', () => { void spaceSheetClear(kind, id); });
  sheet.querySelector('[data-spc-sheet="close"]').addEventListener('click', () => closeSpaceSheet({ restoreFocus: true }));
  sheet.addEventListener('keydown', event => {
    if (event.key !== 'Escape') return;
    event.preventDefault();
    event.stopPropagation();
    closeSpaceSheet({ restoreFocus: true });
  });
  return sheet;
}

// The orange chip for a Space or group reminder. It fills once when its time
// changes, and opens the sheet.
function buildSpaceReminderChip(kind, entity, focusKey, previousAt) {
  const target = spaceReminderTarget(entity);
  if (!target?.at) return null;
  const label = inboxWhenLabel(target.at);
  const chip = document.createElement('button');
  chip.type = 'button';
  chip.className = `spc-chip${target.at < Date.now() ? ' is-past' : ''}${previousAt !== undefined && previousAt !== target.at ? ' is-fill' : ''}`;
  chip.dataset.spcFocus = focusKey;
  chip.dataset.spcRemOwner = `${kind}:${entity.id}`;
  chip.setAttribute('aria-label', tr('space.reminderAt', { time: label }));
  chip.title = tr('space.reminderFor', { name: entity.name || '' });
  chip.innerHTML = `${spaceSvg('clock', 12, 1.9)}<span>${esc(label)}</span>`;
  chip.addEventListener('click', event => {
    event.stopPropagation();
    openSpaceSheet(kind, entity.id, chip);
  });
  return chip;
}

// A note or stack card leads with its kind tile, as a page does with its icon.
function decorateSpaceCards(root) {
  root.querySelectorAll('.item.note:not([data-spc-kind])').forEach(card => {
    card.dataset.spcKind = 'note';
    const body = card.querySelector(':scope > .board-record-body');
    body?.insertAdjacentHTML('beforebegin', `<span class="spc-kic" aria-hidden="true">${spaceSvg('note', 15, 1.4)}</span>`);
  });
  root.querySelectorAll('.item.stack:not([data-spc-kind])').forEach(card => {
    card.dataset.spcKind = 'stack';
    card.querySelector(':scope > .stack-hd > .stack-copy')?.insertAdjacentHTML('beforebegin', `<span class="spc-kic" aria-hidden="true">${spaceSvg('stack', 15, 1.4)}</span>`);
  });
  root.querySelectorAll('.lv-stack:not([data-spc-kind])').forEach(stack => {
    stack.dataset.spcKind = 'stack';
    stack.querySelector(':scope > .lv-stack-hd > .lv-stack-copy')?.insertAdjacentHTML('beforebegin', `<span class="spc-kic" aria-hidden="true">${spaceSvg('stack', 13, 1.5)}</span>`);
  });
}

// The group's meta line: its reminder chip, then its intention.
function buildSpaceGroupMeta(g, session) {
  const previous = session?.groupRem?.get(String(g.id));
  const chip = buildSpaceReminderChip('group', g, `col:${g.id}:rem`, previous);
  const intent = hasIntentMeta(g) ? ensureIntentMeta(g) : null;
  const next = String(intent?.nextAction || '').trim();
  if (!chip && !intent) return null;
  const meta = document.createElement('div');
  meta.className = 'spc-gmeta';
  if (chip) meta.appendChild(chip);
  if (intent) {
    meta.insertAdjacentHTML('beforeend', `<span class="spc-ipill">${esc(intent.status)}</span>${next ? `<span class="spc-inext">${esc(tr('space.next', { text: next }))}</span>` : ''}`);
  }
  return meta;
}

function spaceToggleGroup(g, section) {
  State.snapshot('Toggle collapse');
  g.collapsed = !g.collapsed;
  section.classList.toggle('is-folded', !!g.collapsed);
  const toggle = section.querySelector('[data-act="toggle"]');
  toggle?.setAttribute('aria-expanded', String(!g.collapsed));
  toggle?.setAttribute('aria-label', tr(g.collapsed ? 'groupAction.expandFor' : 'groupAction.collapseFor', { name: g.name }));
  State.persist();
}

// Drag a group onto another to reorder (before or after, by pointer side).
function bindSpaceGroupReorder(section, g, axis) {
  const selector = axis === 'x' ? '.spc-col' : '.spc-lg';
  const clear = () => document.querySelectorAll(selector).forEach(x => x.classList.remove('drop-before', 'drop-after'));
  const after = e => {
    const r = section.getBoundingClientRect();
    return axis === 'x' ? e.clientX > r.left + r.width / 2 : e.clientY > r.top + r.height / 2;
  };
  section.addEventListener('dragstart', e => {
    if (e.target !== section) return;
    drag = { kind: 'group', srcId: g.id };
    section.classList.add('dragging');
    e.dataTransfer.effectAllowed = 'move';
  });
  section.addEventListener('dragend', () => { section.classList.remove('dragging'); clear(); drag = null; });
  section.addEventListener('dragover', e => {
    if (drag?.kind !== 'group' || drag.srcId === g.id) return;
    e.preventDefault();
    clear();
    section.classList.add(after(e) ? 'drop-after' : 'drop-before');
  });
  section.addEventListener('drop', e => {
    if (drag?.kind !== 'group' || drag.srcId === g.id) return;
    e.preventDefault();
    const cat = activeCat();
    const place = after(e);
    State.snapshot('Reorder groups');
    const srcIdx = cat.groups.findIndex(x => x.id === drag.srcId);
    const [src] = cat.groups.splice(srcIdx, 1);
    let tgtIdx = cat.groups.findIndex(x => x.id === g.id);
    if (place) tgtIdx++;
    cat.groups.splice(tgtIdx, 0, src);
    State.persist(); renderBoard();
  });
}

// One Board column: chevron, the group's colour (which edits the group), its
// name (which opens its page), count and to-dos, Open all and More; the
// reminder chip and intention under it; the cards; Save here and Add record.
function buildSpaceColumn(g) {
  const session = spacePageSession;
  const id = String(g.id);
  const name = g.name;
  const items = Array.isArray(g.items) ? g.items : [];
  const todos = items.filter(it => it.type === 'todo');
  const done = todos.filter(it => it.done).length;
  const canOpenAll = groupHasReopenableSavedTab(g);
  const countRoll = spaceCountRoll(session, id, items.length);
  const previousTodos = session?.todos?.get(id);
  const todoText = `${done}/${todos.length}`;
  const col = document.createElement('section');
  col.className = 'spc-col' + (g.collapsed ? ' is-folded' : '');
  col.dataset.gid = id;
  col.dataset.spcGid = id;
  col.style.setProperty('--spc-tint', g.color || 'var(--accent)');
  col.setAttribute('aria-labelledby', `spc-gn-${id}`);
  col.innerHTML = `
    <div class="spc-gh" role="group" aria-label="${esc(tr('groupAction.aria', { name }))}">
      <button type="button" class="spc-ib spc-chev" data-act="toggle" data-spc-focus="col:${esc(id)}:toggle" aria-expanded="${!g.collapsed}" aria-label="${esc(tr(g.collapsed ? 'groupAction.expandFor' : 'groupAction.collapseFor', { name }))}">${spaceSvg('chevron', 14, 1.9)}</button>
      <button type="button" class="spc-gdot" data-act="identity" data-spc-focus="col:${esc(id)}:identity" aria-label="${esc(tr('groupAction.editFor', { name }))}" title="${esc(tr('groupAction.editFor', { name }))}"><span></span></button>
      <h2 class="spc-gh2"><button class="spc-gname" type="button" data-act="focus" id="spc-gn-${esc(id)}" data-spc-focus="col:${esc(id)}:name" title="${esc(`${name} · ${tr('groupAction.openAsPage')}`)}" aria-label="${esc(`${name} · ${tr('groupAction.openAsPage')}`)}">${esc(name)}</button></h2>
      <span class="spc-cnt"><span class="sr-only">${esc(spaceItemsLabel(items.length))}</span><span aria-hidden="true">${spaceRollMarkup(items.length, countRoll.previous, countRoll.delay)}</span></span>
      ${todos.length ? `<span class="spc-tdc${done === todos.length ? ' is-all' : ''}"><span class="sr-only">${esc(tr('space.todosDone', { done, total: todos.length }))}</span><span class="spc-tdc-n${previousTodos != null && previousTodos !== todoText ? ' is-tick' : ''}" aria-hidden="true">${todoText}</span></span>` : ''}
      <span class="spc-gap" aria-hidden="true"></span>
      <button type="button" class="spc-ib" data-act="open-all" data-spc-focus="col:${esc(id)}:open-all" title="${esc(tr('groupAction.openAll'))}" aria-label="${esc(tr('groupAction.openAllIn', { name }))}"${canOpenAll ? '' : ' disabled aria-disabled="true"'}>${spaceSvg('openAll', 16, 1.6)}</button>
      <button type="button" class="spc-ib" data-act="more" data-spc-focus="col:${esc(id)}:more" title="${esc(tr('groupAction.more'))}" aria-label="${esc(tr('groupAction.moreFor', { name }))}" aria-haspopup="menu" aria-expanded="false">${inboxDotsIcon(16)}</button>
    </div>
    <div class="spc-fold"><div class="spc-fold-in">
      <div class="spc-cards"></div>
      <div class="spc-gf">
        <button type="button" class="spc-fbtn" data-act="add-tab" data-spc-focus="col:${esc(id)}:save" title="${esc(tr('groupAction.saveHereFor', { name }))}" aria-label="${esc(tr('groupAction.saveHereFor', { name }))}">${spaceSvg('save', 15, 1.7)}<span>${esc(tr('groupAction.saveHere'))}</span></button>
        <button type="button" class="spc-fbtn is-quiet" data-act="add-record" data-spc-focus="col:${esc(id)}:add" title="${esc(tr('groupAction.addRecordFor', { name }))}" aria-label="${esc(tr('groupAction.addRecordFor', { name }))}" aria-haspopup="menu" aria-expanded="false">${spaceSvg('addRecord', 15, 1.6)}<span>${esc(tr('groupAction.addRecord'))}</span></button>
      </div>
    </div></div>`;

  const hd = col.querySelector('.spc-gh');
  const toggleCollapse = () => spaceToggleGroup(g, col);
  hd.addEventListener('click', e => {
    if (e.target.closest('button')) return;
    toggleCollapse();
  });
  col.querySelector('[data-act="toggle"]').addEventListener('click', e => { e.stopPropagation(); toggleCollapse(); });
  col.querySelector('[data-act="identity"]').addEventListener('click', e => {
    e.stopPropagation();
    const identity = identityGroupTarget(g.id);
    openIdentityEditor('group', 'edit', {
      workspaceId: identity?.workspace.id,
      spaceId: identity?.space.id,
      groupId: g.id,
    }, e.currentTarget);
  });
  col.querySelector('[data-act="focus"]').addEventListener('click', e => {
    e.stopPropagation();
    openGroupPage(g.id);
  });
  col.querySelector('[data-act="open-all"]').addEventListener('click', event => {
    event.stopPropagation();
    openGroupAll(g, event.currentTarget);
  });
  const menuButton = col.querySelector('[data-act="more"]');
  const groupMenuItems = opener => spaceGroupMenu(groupActionMenuItems(g, opener, {
    toggleCollapse,
    includeRecordCreation: false,
  }), g, opener);
  bindBoardItemContextMenu(hd, groupMenuItems, { menuButton });

  const saveHereButton = col.querySelector('[data-act="add-tab"]');
  saveHereButton.addEventListener('click', async event => {
    event.stopPropagation();
    await addSidebarOrActiveTabToGroup(g);
  });
  const addRecordButton = col.querySelector('[data-act="add-record"]');
  addRecordButton.addEventListener('click', event => {
    event.stopPropagation();
    openGroupRecordCreationMenu(g, event.currentTarget);
  });

  const meta = buildSpaceGroupMeta(g, session);
  if (meta) hd.after(meta);
  if (session?.sheet?.kind === 'group' && session.sheet.id === id) {
    (meta || hd).after(buildSpaceSheet('group', g, session.sheet.opening));
  }

  const cardsEl = col.querySelector('.spc-cards');
  if (!items.length && isInboxPageGroup(g)) {
    cardsEl.appendChild(buildSystemEmptyState({
      kind: 'inbox',
      title: tr('empty.inboxTitle'),
      body: tr('empty.inboxBody'),
      actions: [
        { label: tr('empty.addSave'), icon: '+', run: () => openCommandPalette() },
        { label: tr('empty.importBookmarks'), icon: '⇩', run: () => importBookmarks() },
      ],
      compact: true,
    }));
  }
  items.forEach(it => cardsEl.appendChild(buildItem(it, items, g)));
  decorateSpaceCards(cardsEl);
  makeGroupDropZone(cardsEl, col, g, items);

  col.draggable = true;
  bindSpaceGroupReorder(col, g, 'x');
  return col;
}

// ── The page shell ──
function buildSpacePage(cat) {
  const page = document.createElement('div');
  page.className = 'spc';
  page.dataset.cat = String(cat.id);
  page.innerHTML = `
    <p class="sr-only spc-live" aria-live="polite"></p>
    <header class="spc-hd">
      <span class="spc-dot" aria-hidden="true"></span>
      <h1 class="spc-title" id="space-title" tabindex="-1" data-spc-focus="title"></h1>
      <span class="spc-total" aria-hidden="true"></span>
      <span class="spc-rem-slot"></span>
      <span class="spc-gap" aria-hidden="true"></span>
      <button type="button" class="spc-ibtn" data-spc-act="space-more" data-spc-focus="space-more" aria-haspopup="menu" aria-expanded="false">${inboxDotsIcon(18)}</button>
    </header>
    <div class="spc-sheet-slot"></div>
    <div class="spc-bar">
      <div class="spc-tabs-scroll">
        <div class="spc-tabs" role="tablist">
          ${LAYOUT_ORDER.map(view => `<button type="button" role="tab" class="spc-tab" id="spc-tab-${view}" data-view="${view}" data-spc-focus="tab:${view}" aria-controls="space-view" aria-selected="false" tabindex="-1">${spaceSvg(view, 16, 1.5)}<span class="spc-tab-label"></span></button>`).join('')}
          <span class="spc-uline is-jump" aria-hidden="true"></span>
        </div>
      </div>
      <button type="button" class="spc-newg" data-spc-act="add-group" data-spc-focus="add-group">${spaceSvg('plus', 14, 1.8)}<span class="spc-newg-label"></span></button>
    </div>
    <div id="space-view" class="spc-views" role="tabpanel"></div>`;

  const more = page.querySelector('[data-spc-act="space-more"]');
  more.addEventListener('click', () => {
    const current = activeCat();
    const items = spaceActionMenuItems(current, more);
    if (!items.length) return;
    focusDialogOpener(more);
    showAnchoredContextMenu(more, items, { ariaLabel: tr('space.actionsFor', { name: current?.name || '' }), expandedOwner: more });
  });
  page.querySelector('[data-spc-act="add-group"]').addEventListener('click', event => spaceCreateGroup(event.currentTarget));
  const tabs = page.querySelector('.spc-tabs');
  tabs.addEventListener('click', event => {
    const tab = event.target.closest('.spc-tab');
    if (!tab || tab.dataset.view === getViewMode()) return;
    setViewMode(tab.dataset.view);
    focusSpaceKey(`tab:${tab.dataset.view}`);
  });
  // Arrows, Home and End move along the tabs and show the view (automatic
  // activation, as on the board).
  tabs.addEventListener('keydown', event => {
    const order = LAYOUT_ORDER.filter(view => LAYOUTS[view]);
    const index = order.indexOf(getViewMode());
    let next = -1;
    if (event.key === 'ArrowRight') next = (index + 1) % order.length;
    else if (event.key === 'ArrowLeft') next = (index - 1 + order.length) % order.length;
    else if (event.key === 'Home') next = 0;
    else if (event.key === 'End') next = order.length - 1;
    if (next < 0) return;
    event.preventDefault();
    event.stopPropagation();
    setViewMode(order[next]);
    focusSpaceKey(`tab:${order[next]}`);
  });
  return page;
}

// The underline sits under the chosen tab; between views it slides.
function placeSpaceUnderline(page, view) {
  const tab = page.querySelector(`.spc-tab[data-view="${view}"]`);
  const line = page.querySelector('.spc-uline');
  if (!tab || !line) return;
  const inset = Math.min(14, Math.max(0, (tab.offsetWidth - 24) / 2));
  line.style.setProperty('--spc-ul-x', `${tab.offsetLeft + inset}px`);
  line.style.setProperty('--spc-ul-w', `${Math.max(0, tab.offsetWidth - inset * 2)}px`);
  if (line.classList.contains('is-jump')) {
    void line.offsetWidth;
    line.classList.remove('is-jump');
  }
  const scroller = page.querySelector('.spc-tabs-scroll');
  if (scroller && scroller.scrollWidth > scroller.clientWidth) {
    const left = tab.offsetLeft - 16;
    const right = tab.offsetLeft + tab.offsetWidth + 16 - scroller.clientWidth;
    if (scroller.scrollLeft > left) scroller.scrollLeft = Math.max(0, left);
    else if (scroller.scrollLeft < right) scroller.scrollLeft = right;
  }
}

function syncSpacePage(page, ws, cat, mode, session) {
  const total = cat.groups.reduce((n, g) => n + (Array.isArray(g.items) ? g.items.length : 0), 0);
  page.dataset.view = mode;
  const title = page.querySelector('.spc-title');
  if (title.textContent !== cat.name) title.textContent = cat.name;
  const totalEl = page.querySelector('.spc-total');
  const totalText = tr('groupAction.items', { count: '#' });
  if (session.total !== total || session.totalText !== totalText || !totalEl.firstChild) {
    totalEl.innerHTML = spaceItemsMarkup(total, session.totalText === totalText ? session.total : null);
  }
  session.totalText = totalText;
  const live = page.querySelector('.spc-live');
  if (session.total != null && session.total !== total) live.textContent = spaceItemsLabel(total);
  const remSlot = page.querySelector('.spc-rem-slot');
  remSlot.innerHTML = '';
  const chip = buildSpaceReminderChip('category', cat, 'space-rem', session.remAt);
  if (chip) remSlot.appendChild(chip);
  const more = page.querySelector('[data-spc-act="space-more"]');
  more.setAttribute('aria-label', tr('space.actionsFor', { name: cat.name }));
  more.title = tr('space.actionsFor', { name: cat.name });
  const sheetSlot = page.querySelector('.spc-sheet-slot');
  sheetSlot.innerHTML = '';
  if (session.sheet?.kind === 'category' && session.sheet.id === String(cat.id)) {
    sheetSlot.appendChild(buildSpaceSheet('category', cat, session.sheet.opening));
  }
  const tabs = page.querySelector('.spc-tabs');
  tabs.setAttribute('aria-label', tr('layout.view'));
  tabs.querySelectorAll('.spc-tab').forEach(tab => {
    const selected = tab.dataset.view === mode;
    tab.setAttribute('aria-selected', String(selected));
    tab.tabIndex = selected ? 0 : -1;
    tab.querySelector('.spc-tab-label').textContent = layoutLabel(tab.dataset.view);
    if (selected && session.view != null && session.view !== mode) spaceRestart(tab, 'is-picked');
  });
  const newGroup = page.querySelector('[data-spc-act="add-group"]');
  newGroup.hidden = !['board', 'list'].includes(mode);
  newGroup.setAttribute('aria-label', tr('groupAction.new'));
  newGroup.querySelector('.spc-newg-label').textContent = tr('groupAction.new');
  page.querySelector('.spc-views').setAttribute('aria-labelledby', `spc-tab-${mode}`);
  session.total = total;
  session.remAt = spaceReminderTarget(cat)?.at ?? null;
}

// After a paint: a card or group that was not on the last paint of this view
// drops in; the remembered counts make the next change roll. A repaint while
// it is still dropping (Details opening, a receipt) carries the motion on from
// where it was instead of restarting it.
function markSpaceArrivals(host, session, fresh) {
  const cards = [...host.querySelectorAll('.item[data-id]')];
  const groups = [...host.querySelectorAll('[data-spc-gid]')];
  const now = Date.now();
  if (fresh || !session.arrived) session.arrived = new Map();
  session.arrived.forEach((at, key) => { if (now - at > 900) session.arrived.delete(key); });
  const land = (el, key, seen, cls) => {
    if (!fresh && seen && !seen.has(key.slice(2))) session.arrived.set(key, now);
    const at = session.arrived.get(key);
    if (at == null) return;
    el.classList.add(cls);
    if (now > at) el.style.animationDelay = `-${now - at}ms`;
  };
  cards.forEach(card => land(card, `i:${card.dataset.id}`, session.seenItems, 'spc-drop'));
  groups.forEach(group => land(group, `g:${group.dataset.spcGid}`, session.seenGroups, 'spc-back'));
  session.seenItems = new Set(cards.map(card => card.dataset.id));
  session.seenGroups = new Set(groups.map(group => group.dataset.spcGid));
  const cat = activeCat();
  session.counts = new Map((cat?.groups || []).map(g => [String(g.id), (g.items || []).length]));
  session.todos = new Map((cat?.groups || []).map(g => {
    const todos = (g.items || []).filter(it => it.type === 'todo');
    return [String(g.id), `${todos.filter(it => it.done).length}/${todos.length}`];
  }));
  session.groupRem = new Map((cat?.groups || []).map(g => [String(g.id), spaceReminderTarget(g)?.at ?? null]));
}

function renderSpacePage(mode) {
  const ws = activeWs();
  const cat = activeCat();
  const board = document.getElementById('board');
  if (!ws || !cat || !board) return false;
  const session = spacePageState(cat.id);
  document.body.dataset.page = 'space';
  board.classList.add('spc-mode');
  let page = spacePageRoot();
  if (page && page.dataset.cat !== String(cat.id)) page = null;
  const keepScroll = page ? board.scrollTop : 0;
  const active = document.activeElement;
  const focusKey = page && active && page.contains(active)
    ? active.closest('[data-spc-focus]')?.dataset.spcFocus || null
    : null;
  if (!page) {
    board.innerHTML = '';
    page = buildSpacePage(cat);
    board.appendChild(page);
    Object.assign(session, { view: null, host: null, total: null, remAt: undefined, seenItems: null, seenGroups: null });
  }
  const changed = session.view != null && session.view !== mode;
  syncSpacePage(page, ws, cat, mode, session);
  const views = page.querySelector('.spc-views');
  let host = session.host?.isConnected && !changed ? session.host : null;
  if (!host) {
    const previous = session.host?.isConnected ? session.host : null;
    host = document.createElement('div');
    host.className = 'spc-vw';
    views.prepend(host);
    if (previous) {
      if (changed && !spaceReducedMotion()) {
        host.classList.add('is-in');
        previous.classList.add('is-out');
        previous.setAttribute('aria-hidden', 'true');
        previous.inert = true;
        setTimeout(() => previous.remove(), 200);
      } else {
        previous.remove();
      }
    }
  }
  host.dataset.view = mode;
  session.host = host;
  (LAYOUTS[mode] || LAYOUTS.board).render();
  markSpaceArrivals(host, session, changed || session.view == null);
  placeSpaceUnderline(page, mode);
  session.view = mode;
  if (keepScroll && board.scrollTop !== keepScroll) board.scrollTo({ top: keepScroll, behavior: 'instant' });
  if (focusKey && !page.contains(document.activeElement)) focusSpaceKey(focusKey);
  return true;
}

// ════════════════════════════════════════════════════════════════
// CANVAS VIEW (free positioning, idea-board style)
// ════════════════════════════════════════════════════════════════
function getCanvasPositions() {
  const cat = activeCat();
  if (!cat) return {};
  if (!cat.canvasPositions) cat.canvasPositions = {};
  return cat.canvasPositions;
}

function getCanvasGroupEl(gId) {
  return Array.from(document.querySelectorAll('.gcol.cv-group')).find(el => el.dataset.gid === gId);
}

function canvasGroupFootprint(savedSize, fallback) {
  const width = typeof savedSize === 'number' ? savedSize : savedSize?.w;
  const cardsHeight = typeof savedSize === 'object' ? savedSize?.h : null;
  return {
    w: Number.isFinite(Number(width)) && Number(width) > 0 ? Number(width) : fallback.w,
    // Saved height belongs to the cards region; include conservative header,
    // composer, and spacing chrome for the complete column footprint.
    h: Number.isFinite(Number(cardsHeight)) && Number(cardsHeight) > 0
      ? Math.max(fallback.h, Number(cardsHeight) + 150)
      : fallback.h,
  };
}

function canvasGroupRect(g, positions, fallback, savedSize = null) {
  const el = getCanvasGroupEl(g.id);
  const pos = positions[g.id] || { x: 0, y: 0 };
  const footprint = canvasGroupFootprint(savedSize, fallback);
  return {
    x: Number(pos.x) || 0,
    y: Number(pos.y) || 0,
    w: el?.offsetWidth || footprint.w,
    h: el?.offsetHeight || footprint.h,
  };
}

function canvasRectsOverlap(a, b, gap = 24) {
  return a.x < b.x + b.w + gap &&
    a.x + a.w + gap > b.x &&
    a.y < b.y + b.h + gap &&
    a.y + a.h + gap > b.y;
}

function findOpenCanvasPosition(group, groups, positions, preferredSize = null, groupSizes = null) {
  const board = document.getElementById('board');
  const colW = parseFloat(getComputedStyle(document.body).getPropertyValue('--gw')) || 290;
  const viewportHeight = Number(window.innerHeight)
    || Number(document.documentElement?.clientHeight)
    || 720;
  // Unsized cards may occupy the full CSS 60vh cap. Include the same
  // conservative header/composer chrome used for saved card heights.
  const fallback = { w: colW, h: Math.max(330, Math.round(viewportHeight * 0.6) + 150) };
  const footprint = canvasGroupFootprint(preferredSize, fallback);
  const occupied = groups
    .filter(g => g.id !== group.id && positions[g.id])
    .map(g => canvasGroupRect(g, positions, fallback, groupSizes?.[g.id]));

  const startX = Math.max(30, (board?.scrollLeft || 0) + 30);
  const startY = Math.max(30, (board?.scrollTop || 0) + 30);
  const stepX = Math.max(footprint.w + 30, 320);
  const stepY = Math.max(footprint.h + 36, 366);
  const columns = Math.max(3, Math.ceil((board?.clientWidth || 960) / stepX) + 1);

  for (let row = 0; row < 24; row++) {
    for (let col = 0; col < columns; col++) {
      const candidate = { x: startX + col * stepX, y: startY + row * stepY, ...footprint };
      if (!occupied.some(rect => canvasRectsOverlap(candidate, rect))) return { x: candidate.x, y: candidate.y };
    }
  }

  const below = occupied.reduce((max, rect) => Math.max(max, rect.y + rect.h), startY);
  return { x: startX, y: below + 36 };
}

function placeMissingCanvasPositions(cat, positions) {
  let changed = false;
  const live = new Set(cat.groups.map(g => g.id));
  Object.keys(positions).forEach(id => {
    if (!live.has(id)) { delete positions[id]; changed = true; }
  });
  cat.groups.forEach(g => {
    if (!positions[g.id]) {
      positions[g.id] = findOpenCanvasPosition(g, cat.groups, positions);
      changed = true;
    }
  });
  const anchors = new Set();
  cat.groups.forEach(g => {
    const pos = positions[g.id];
    const key = `${Math.round((Number(pos?.x) || 0) / 20)}:${Math.round((Number(pos?.y) || 0) / 20)}`;
    if (anchors.has(key)) {
      positions[g.id] = findOpenCanvasPosition(g, cat.groups, positions);
      changed = true;
    }
    const next = positions[g.id];
    anchors.add(`${Math.round((Number(next?.x) || 0) / 20)}:${Math.round((Number(next?.y) || 0) / 20)}`);
  });
  return changed;
}

function renderCanvasView() {
  const $b = spaceViewHost();
  $b.innerHTML = '';
  $b.classList.remove('list-mode');
  $b.classList.add('canvas-mode');
  const cat = activeCat(); if (!cat) return;

  if (!cat.groups.length) {
    $b.appendChild(buildEmptySpaceState(cat));
    return;
  }

  // Canvas wrapper - large scrollable area
  const wrap = document.createElement('div');
  wrap.className = 'cv-canvas';
  $b.appendChild(wrap);

  const positions = getCanvasPositions();
  if (placeMissingCanvasPositions(cat, positions)) State.persist();

  cat.groups.forEach(g => {
    const pos = positions[g.id] || { x: 30, y: 30 };
    const col = buildGroupCol(g);
    col.classList.add('cv-group');
    col.style.left = (pos.x || 0) + 'px';
    col.style.top = (pos.y || 0) + 'px';
    if (!col.style.width) col.style.width = '290px';

    // Make the header a drag handle
    const hd = col.querySelector('.gcol-hd');
    if (hd) {
      let dragging = false, startX = 0, startY = 0, startLeft = 0, startTop = 0;
      hd.addEventListener('mousedown', (e) => {
        // Don't drag when clicking buttons or symbol or input
        if (e.target.closest('button') || e.target.closest('input') || e.target.closest('.gcol-sym-wrap') || e.target.closest('.gcol-acts')) return;
        dragging = true;
        startX = e.clientX; startY = e.clientY;
        startLeft = parseFloat(col.style.left) || 0;
        startTop = parseFloat(col.style.top) || 0;
        col.classList.add('cv-dragging');
        e.preventDefault();
      });
      const onMove = (e) => {
        if (!dragging) return;
        const dx = e.clientX - startX;
        const dy = e.clientY - startY;
        const newX = Math.max(0, startLeft + dx);
        const newY = Math.max(0, startTop + dy);
        col.style.left = newX + 'px';
        col.style.top = newY + 'px';
      };
      const onUp = () => {
        if (!dragging) return;
        dragging = false;
        col.classList.remove('cv-dragging');
        positions[g.id] = {
          x: parseFloat(col.style.left) || 0,
          y: parseFloat(col.style.top) || 0
        };
        State.persist();
        // Update wrap min-size to fit content
        sizeCanvas(wrap, cat.groups, positions);
      };
      document.addEventListener('mousemove', onMove);
      document.addEventListener('mouseup', onUp);
      // Cleanup when re-rendering
      col._cvCleanup = () => {
        document.removeEventListener('mousemove', onMove);
        document.removeEventListener('mouseup', onUp);
      };
    }

    wrap.appendChild(col);
  });

  sizeCanvas(wrap, cat.groups, positions);
  decorateSpaceCards(wrap);
  applySearchFilter();
}

function sizeCanvas(wrap, groups, positions) {
  let maxX = 0, maxY = 0;
  for (const g of groups) {
    const p = positions[g.id] || { x: 0, y: 0 };
    const el = wrap.querySelector(`.gcol[data-gid="${g.id}"]`);
    const w = el ? el.offsetWidth : 290;
    const h = el ? el.offsetHeight : 300;
    maxX = Math.max(maxX, p.x + w + 100);
    maxY = Math.max(maxY, p.y + h + 100);
  }
  wrap.style.minWidth = maxX + 'px';
  wrap.style.minHeight = maxY + 'px';
}

function renderListView() {
  const $b = spaceViewHost();
  $b.innerHTML = '';
  $b.classList.add('list-mode');
  const cat = activeCat(); if (!cat) return;

  if (!cat.groups.length) {
    $b.appendChild(buildEmptySpaceState(cat));
    return;
  }

  const wrap = document.createElement('div');
  wrap.className = 'lv-wrap spc-list';
  cat.groups.forEach(g => wrap.appendChild(buildLvGroup(g)));
  $b.appendChild(wrap);
  applySearchFilter();
}

// One List group: chevron, the group's colour (which edits the group), its
// name (which opens its page), the localized item count and to-do progress,
// then Open all, Save here and More, always visible. Its items are rows.
function buildLvGroup(g) {
  const session = spacePageSession;
  const id = String(g.id);
  const name = g.name;
  const items = Array.isArray(g.items) ? g.items : [];
  const itemCnt = items.length;
  const canOpenAll = groupHasReopenableSavedTab(g);
  const countRoll = spaceCountRoll(session, id, itemCnt);
  const itemLabel = itemCnt === 1
    ? tr('groupAction.oneItem')
    : tr('groupAction.items', { count: itemCnt });
  const todoStat = (() => {
    const todos = items.filter(it => it.type === 'todo');
    if (!todos.length) return '';
    const done = todos.filter(t => t.done).length;
    const todoLabel = tr('home.previewType.todo');
    const text = `${done}/${todos.length}`;
    const ticked = session?.todos?.get(id) != null && session.todos.get(id) !== text;
    return `<span class="spc-tdc is-text${done === todos.length ? ' is-all' : ''}"><span class="sr-only">${esc(tr('space.todosDone', { done, total: todos.length }))}</span><span class="spc-tdc-n${ticked ? ' is-tick' : ''}" aria-hidden="true">${esc(todoLabel)} ${text}</span></span>`;
  })();

  const wrap = document.createElement('section');
  wrap.className = 'lv-group spc-lg' + (g.collapsed ? ' is-folded' : '');
  wrap.dataset.gid = id;
  wrap.dataset.spcGid = id;
  wrap.style.setProperty('--spc-tint', g.color || 'var(--accent)');
  wrap.setAttribute('aria-labelledby', `spc-ln-${id}`);

  const hd = document.createElement('div');
  hd.className = 'lv-group-hd spc-lgh';
  hd.setAttribute('role', 'group');
  hd.setAttribute('aria-label', tr('groupAction.aria', { name }));
  hd.innerHTML = `
    <button class="lv-group-toggle spc-ib spc-chev" type="button" data-act="toggle" data-spc-focus="lg:${esc(id)}:toggle" aria-expanded="${!g.collapsed}" aria-label="${esc(tr(g.collapsed ? 'groupAction.expandFor' : 'groupAction.collapseFor', { name }))}">${spaceSvg('chevron', 14, 1.9)}</button>
    <button class="lv-group-sym spc-gdot" type="button" data-act="identity" data-spc-focus="lg:${esc(id)}:identity" aria-label="${esc(tr('groupAction.editFor', { name }))}" title="${esc(tr('groupAction.editFor', { name }))}"><span></span></button>
    <h2 class="spc-gh2"><button class="lv-group-name spc-gname" type="button" data-act="focus" id="spc-ln-${esc(id)}" data-spc-focus="lg:${esc(id)}:name" title="${esc(`${name} · ${tr('groupAction.openAsPage')}`)}" aria-label="${esc(`${name} · ${tr('groupAction.openAsPage')}`)}">${esc(name)}</button></h2>
    <span class="spc-cnt is-text"><span class="sr-only">${esc(itemLabel)}</span><span aria-hidden="true">${spaceItemsMarkup(itemCnt, countRoll.previous, countRoll.delay)}</span></span>
    ${todoStat}
    <span class="spc-gap" aria-hidden="true"></span>
    <div class="lv-group-acts spc-lacts">
      <button class="spc-ib" type="button" data-act="open-all" data-spc-focus="lg:${esc(id)}:open-all" title="${esc(tr('groupAction.openAll'))}" aria-label="${esc(tr('groupAction.openAllIn', { name }))}"${canOpenAll ? '' : ' disabled aria-disabled="true"'}>${spaceSvg('openAll', 16, 1.6)}</button>
      <button class="spc-fbtn" type="button" data-act="add-tab" data-spc-focus="lg:${esc(id)}:save" title="${esc(tr('groupAction.saveHereFor', { name }))}" aria-label="${esc(tr('groupAction.saveHereFor', { name }))}">${spaceSvg('save', 15, 1.7)}<span>${esc(tr('groupAction.saveHere'))}</span></button>
      <button class="spc-ib" type="button" data-act="more" data-spc-focus="lg:${esc(id)}:more" title="${esc(tr('groupAction.more'))}" aria-label="${esc(tr('groupAction.moreFor', { name }))}" aria-haspopup="menu" aria-expanded="false">${inboxDotsIcon(16)}</button>
    </div>`;

  const toggleGroup = () => spaceToggleGroup(g, wrap);
  hd.addEventListener('click', e => {
    if (e.target.closest('button') || e.target.closest('.lv-group-acts')) return;
    toggleGroup();
  });
  hd.querySelector('[data-act="toggle"]').addEventListener('click', event => { event.stopPropagation(); toggleGroup(); });
  hd.querySelector('[data-act="identity"]').addEventListener('click', (e) => {
    e.stopPropagation();
    const identity = identityGroupTarget(g.id);
    openIdentityEditor('group', 'edit', {
      workspaceId: identity?.workspace.id,
      spaceId: identity?.space.id,
      groupId: g.id,
    }, e.currentTarget);
  });
  hd.querySelector('.lv-group-name').addEventListener('click', event => {
    event.stopPropagation();
    openGroupPage(g.id);
  });
  hd.querySelector('[data-act="open-all"]').addEventListener('click', event => {
    event.stopPropagation();
    openGroupAll(g, event.currentTarget);
  });
  hd.querySelector('[data-act="add-tab"]').addEventListener('click', async event => {
    event.stopPropagation();
    await addSidebarOrActiveTabToGroup(g);
  });
  const menuButton = hd.querySelector('[data-act="more"]');
  const groupMenuItems = opener => spaceGroupMenu(groupActionMenuItems(g, opener, {
    toggleCollapse: toggleGroup,
  }), g, opener);
  bindBoardItemContextMenu(hd, groupMenuItems, { menuButton });
  wrap.appendChild(hd);

  const meta = buildSpaceGroupMeta(g, session);
  if (meta) wrap.appendChild(meta);
  if (session?.sheet?.kind === 'group' && session.sheet.id === id) wrap.appendChild(buildSpaceSheet('group', g, session.sheet.opening));

  const fold = document.createElement('div');
  fold.className = 'spc-fold';
  fold.innerHTML = '<div class="spc-fold-in"><div class="spc-rows"></div></div>';
  const children = fold.querySelector('.spc-rows');
  items.forEach(it => children.appendChild(buildLvItem(it, items, g, 0)));
  decorateSpaceCards(children);
  // Each row ends with the day it was saved, as on the board.
  const byId = new Map();
  const walk = list => list.forEach(it => { byId.set(String(it.id), it); if (it.type === 'stack') walk(it.items || []); });
  walk(items);
  children.querySelectorAll('.lv-row > .item[data-id]').forEach(card => {
    const label = inboxSavedLabel(byId.get(card.dataset.id)?.createdAt);
    if (label) card.insertAdjacentHTML('beforeend', `<span class="spc-added">${esc(label)}</span>`);
  });
  wrap.appendChild(fold);
  makeGroupDropZone(children, wrap, g, items);

  if (document.body.classList.contains('reorder-mode')) {
    wrap.draggable = true;
    bindSpaceGroupReorder(wrap, g, 'y');
  }
  return wrap;
}

function buildLvItem(it, parentItems, group, depth) {
  if (it.type === 'stack') return buildLvStack(it, parentItems, group, depth);
  const inner = buildItem(it, parentItems, group);
  inner.classList.add('lv-item-inner');
  const row = document.createElement('div');
  row.className = 'lv-row';
  row.style.paddingLeft = (16 + depth * 18) + 'px';
  row.appendChild(inner);
  return row;
}

function buildLvStack(it, parentItems, group, depth) {
  const wrap = document.createElement('div');
  wrap.className = 'lv-stack' + (it.expanded ? ' expanded' : '');
  wrap.dataset.id = it.id;
  if (it.color) {
    wrap.dataset.color = it.color;
    wrap.style.setProperty('--stack-tint', it.color);
  }
  wrap.style.setProperty('--stack-indent', `${16 + depth * 18}px`);

  const hd = document.createElement('div');
  hd.className = 'lv-stack-hd';
  const stackName = it.name || tr('stackEditor.defaultName');
  const stackKind = tr('home.previewType.stack');
  const itemCnt = (it.items || []).length;
  const itemLabel = itemCnt === 1
    ? tr('groupAction.oneItem')
    : tr('groupAction.items', { count: itemCnt });
  hd.setAttribute('role', 'group');
  hd.setAttribute('aria-label', tr('stackAction.aria', { name: stackName }));
  hd.innerHTML = `
    <button class="lv-chev lv-stack-toggle" type="button" aria-expanded="${!!it.expanded}" aria-label="${esc(tr(it.expanded ? 'stackAction.collapseFor' : 'stackAction.expandFor', { name: stackName }))}"><svg width="9" height="9" viewBox="0 0 10 10" aria-hidden="true"><path d="M3.5 2.5l3 2.5-3 2.5" stroke="currentColor" stroke-width="1.5" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg></button>
    <button class="lv-stack-sym" type="button" aria-label="${esc(tr('stackAction.editFor', { name: stackName }))}">${esc(it.symbol || '📚')}</button>
    <div class="lv-stack-copy">
      <span class="lv-stack-name">${esc(stackName)}</span>
      <span class="lv-stack-meta"><span class="lv-stack-kind">${esc(stackKind)}</span><span class="lv-stack-cnt">${esc(itemLabel)}</span></span>
    </div>
    <button class="lv-stack-more" type="button" data-act="more" data-item-archive="menu" title="${esc(tr('library.moreActions', { title: stackName }))}" aria-label="${esc(tr('library.moreActions', { title: stackName }))}" aria-haspopup="menu">
      <svg width="12" height="12" viewBox="0 0 12 12" fill="currentColor" aria-hidden="true"><circle cx="3" cy="6" r="1"/><circle cx="6" cy="6" r="1"/><circle cx="9" cy="6" r="1"/></svg>
    </button>
    </div>`;
  const toggleButton = hd.querySelector('.lv-stack-toggle');
  const dropPreview = createStackDropPreview(wrap, toggleButton, it);
  const toggleStack = () => {
    State.snapshot('Toggle stack');
    it.expanded = !it.expanded;
    wrap.classList.toggle('expanded');
    toggleButton.setAttribute('aria-expanded', String(!!it.expanded));
    toggleButton.setAttribute('aria-label', tr(it.expanded ? 'stackAction.collapseFor' : 'stackAction.expandFor', { name: it.name || tr('stackEditor.defaultName') }));
    State.persist();
  };
  const openStackIdentity = (opener, focusField) => {
    const identity = identityStackTarget(it.id);
    if (!identity || identity.item !== it) return false;
    return openIdentityEditor('stack', 'edit', {
      workspaceId: identity.workspace.id,
      spaceId: identity.space.id,
      groupId: identity.group.id,
      stackId: it.id,
      focusField,
    }, opener);
  };
  hd.addEventListener('click', e => {
    if (e.target.closest('button') || e.target.closest('.lv-stack-sym') || e.target.closest('.item-check')) return;
    if (itemSelMode || e.shiftKey) {
      e.stopPropagation();
      e.preventDefault();
      if (e.shiftKey) selectRangeTo(it.id);
      else toggleItemSelect(it.id);
      return;
    }
    toggleStack();
  });
  toggleButton.addEventListener('click', event => {
    event.stopPropagation();
    if (itemSelMode || event.shiftKey) {
      if (event.shiftKey) selectRangeTo(it.id);
      else toggleItemSelect(it.id);
      return;
    }
    toggleStack();
  });
  const menuButton = hd.querySelector('[data-act="more"]');
  const stackMenuItems = opener => stackActionMenuItems(it, opener, {
    parentItems,
    group,
    toggleCollapse: toggleStack,
  });
  bindBoardItemContextMenu(hd, stackMenuItems, { menuButton });
  hd.querySelector('.lv-stack-sym').addEventListener('click', (e) => {
    e.stopPropagation();
    openStackIdentity(e.currentTarget, 'symbol');
  });
  wrap.appendChild(hd);

  attachItemSelection(wrap, it, { target: hd, bindContainer: false });

  const inner = document.createElement('div');
  inner.className = 'lv-stack-children';
  (it.items || []).forEach(sub => inner.appendChild(buildLvItem(sub, it.items, group, depth + 1)));
  wrap.appendChild(inner);
  makeGroupDropZone(inner, wrap, group, it.items, dropPreview);

  // Drag stack itself (move to other group)
  wrap.draggable = true;
  wrap.addEventListener('dragstart', (e) => {
    e.stopPropagation();
    drag = { kind:'item', id: it.id, srcList: parentItems };
    wrap.classList.add('dragging');
    e.dataTransfer.effectAllowed = 'move';
  });
  wrap.addEventListener('dragend', () => {
    wrap.classList.remove('dragging');
    document.querySelectorAll('.dragover, .drop-target').forEach(x => { x.classList.remove('dragover'); x.classList.remove('drop-target'); });
    document.querySelectorAll('.drag-ghost').forEach(x => x.remove());
    drag = null;
  });

  // Auto-expand on hover-drag
  hd.addEventListener('dragover', (e) => {
    if (!drag) return;
    if (drag.kind === 'tab' && !isOpenableSavedTabUrl(drag.data?.url)) return;
    if (drag.kind === 'tabs-multi' && !captureEligibleTabs(drag.data).length) return;
    e.preventDefault();
    e.stopPropagation();
    hd.classList.add('drop-target');
    dropPreview.schedule();
  });
  hd.addEventListener('dragleave', (e) => {
    if (!wrap.contains(e.relatedTarget)) {
      hd.classList.remove('drop-target');
      dropPreview.clear();
    }
  });
  hd.addEventListener('drop', async (e) => {
    if (!drag) return;
    e.preventDefault();
    e.stopPropagation();
    hd.classList.remove('drop-target');
    dropPreview.clear();
    if (drag.kind === 'tab') {
      await handleTabDropIntoList(drag.data, it.items, it.items.length, {
        afterSnapshot: () => dropPreview.commit(),
      });
    }
    else if (drag.kind === 'tabs-multi') {
      await handleTabDropIntoList(drag.data, it.items, it.items.length, {
        afterSnapshot: () => dropPreview.commit(),
      });
    } else if (drag.kind === 'item') {
      const info = findItem(drag.id);
      if (!info) return;
      if (info.item.type === 'stack' && isDescendantOf(it.items, info.item)) { toast(tr('feedback.stackSelf'), { danger: true }); return; }
      if (info.item.id === it.id) return;
      State.snapshot('Move to stack');
      dropPreview.commit();
      const [moved] = info.parent.splice(info.index, 1);
      it.items.push(moved);
      State.persist(); renderBoard();
    }
  });

  return wrap;
}

// ════════════════════════════════════════════════════════════════
// EXPLORER LAYOUT (§3.1 — Miller / column browser)
// ════════════════════════════════════════════════════════════════
// A macOS-Finder / column-browser over the hierarchy: Spaces → Groups →
// items → (a stack's children as a further column). Selecting an item opens the
// §4.2 detail pane. Keyboard-first (arrows move/descend/ascend, Enter opens).
// Each column reuses the bento `.gcol` framing so it reads as Locus, not Finder.
const EX_CHEVRON = '<svg class="ex-row-chev" width="8" height="8" viewBox="0 0 8 8"><path d="M2.5 1.5L5.5 4l-3 2.5" stroke="currentColor" stroke-width="1.3" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>';

function explorerCopy() {
  return {
    spaces: tr('explorer.spaces'),
    groups: tr('explorer.groups'),
    items: tr('explorer.items'),
    stack: tr('explorer.stack'),
    noGroups: tr('explorer.noGroups'),
    empty: tr('explorer.empty'),
  };
}

function renderExplorerView() {
  const $b = spaceViewHost();
  $b.innerHTML = '';
  $b.classList.add('explorer-mode');
  const ws = activeWs(), cat = activeCat();
  const copy = explorerCopy();
  if (!ws || !cat) return;
  if (!cat.groups.length) {
    $b.appendChild(buildEmptySpaceState(cat));
    return;
  }

  const wrap = document.createElement('div');
  wrap.className = 'ex-wrap';

  // Validate the drilled-into group against the active category; a stale id
  // (deleted, or the category changed) resets the selection so a dead pointer
  // never wedges the columns.
  let group = cat.groups.find(g => g.id === explorerSel.groupId) || null;
  if (!group) { explorerSel.groupId = null; explorerSel.stackPath = []; explorerSel.itemId = null; }

  // Column 1 — Spaces in the active workspace. Selecting one makes its internal
  // category record active and resets the deeper selection.
  wrap.appendChild(buildExCol(copy.spaces, ws.categories.map(c => ({
    icon: explorerTile(c.name, 'var(--accent)'), label: c.name, meta: String(c.groups.length), hasChildren: true,
    active: c.id === cat.id,
    onSelect: () => {
      if (c.id === cat.id) return;
      ws.activeCatId = c.id;
      explorerSel = { groupId: null, stackPath: [], itemId: null };
      State.persist();
      renderAll();
    },
  }))));

  // Column 2 — Groups in the active Space. Select drills in; double-click /
  // Enter opens the full group page (§4.1).
  wrap.appendChild(buildExCol(copy.groups, cat.groups.map(g => ({
    icon: explorerTile(g.name, g.color || 'var(--accent)'), label: g.name, meta: String(g.items.length), color: g.color,
    hasChildren: true, active: group && g.id === group.id,
    onSelect: () => {
      explorerSel.groupId = g.id; explorerSel.stackPath = []; explorerSel.itemId = null;
      _exFocusAfter = 'deepest';
      renderBoard();
    },
    onOpen: () => openGroupPage(g.id),
  })), { emptyText: copy.noGroups }));

  // Columns 3+ — the selected group's items, plus one column per expanded stack
  // level along explorerSel.stackPath.
  if (group) {
    const levels = [group.items];
    let list = group.items;
    for (const sid of explorerSel.stackPath) {
      const st = list.find(x => x.id === sid && x.type === 'stack');
      if (!st) { explorerSel.stackPath = explorerSel.stackPath.slice(0, levels.length - 1); break; }
      levels.push(st.items); list = st.items;
    }
    levels.forEach((lvl, depth) => {
      const rows = lvl.map(it => explorerItemRow(it, lvl, group, depth));
      wrap.appendChild(buildExCol(depth === 0 ? copy.items : copy.stack, rows, { emptyText: copy.empty }));
    });
  }

  $b.appendChild(wrap);
  bindExplorerKeys(wrap);

  // Restore keyboard focus across the re-render a selection triggered.
  if (_exFocusAfter) {
    const cols = wrap.querySelectorAll('.ex-col');
    const target = _exFocusAfter === 'deepest' ? cols[cols.length - 1] : null;
    const row = target && (target.querySelector('.ex-row.active') || target.querySelector('.ex-row'));
    if (row) row.focus();
    _exFocusAfter = null;
  }
  applySearchFilter();
}

// Build a row descriptor for an item in an explorer column at the given stack depth.
function explorerItemRow(it, lvl, group, depth) {
  const isStack = it.type === 'stack';
  const label = it.type === 'note'
    ? (String(it.html || '').replace(/<[^>]*>/g, ' ').trim().slice(0, 60) || 'Empty note')
    : (it.title || it.text || it.name || 'Untitled');
  const icon = it.type === 'tab'
    ? `<img class="ex-fav" src="${esc(favUrl(it.url) || BLANK_FAV)}" alt="" decoding="async">`
    : `<span class="ex-kic${it.type === 'todo' && it.done ? ' is-done' : ''}">${spaceSvg(it.type === 'todo' && it.done ? 'todo' : (SPACE_PATHS[it.type] ? it.type : 'note'), 13, 1.5)}</span>`;
  const active = isStack ? explorerSel.stackPath.includes(it.id) : explorerSel.itemId === it.id;
  return {
    icon, label, color: it.color, hasChildren: isStack, active,
    meta: isStack ? String((it.items || []).length) : '',
    onSelect: () => {
      const prefix = explorerSel.stackPath.slice(0, depth);
      if (isStack) {
        explorerSel.stackPath = prefix.concat(it.id);
        explorerSel.itemId = null;
        _exFocusAfter = 'deepest';
        renderBoard();
      } else {
        explorerSel.stackPath = prefix;
        explorerSel.itemId = it.id;
        openItemDetail(it.id); // navigates + re-renders; opens the §4.2 pane
      }
    },
    onOpen: opener => {
      if (it.type === 'tab') openSavedTabItem(it, { focus: true, opener });
      else openItemDetail(it.id);
    },
  };
}

// A Space or group in the Explorer leads with a tile in its colour.
function explorerTile(name, color) {
  const initial = Array.from(String(name || '').trim())[0] || '·';
  return `<span class="ex-tile" style="--ex-c:${esc(color)}">${esc(initial.toLocaleUpperCase())}</span>`;
}

function buildExCol(title, rows, opts = {}) {
  const col = document.createElement('div');
  col.className = 'ex-col gcol';
  const hd = document.createElement('div');
  hd.className = 'ex-col-hd';
  hd.textContent = title;
  col.appendChild(hd);
  const body = document.createElement('div');
  body.className = 'ex-col-body';
  body.setAttribute('role', 'listbox');
  body.setAttribute('aria-label', title);
  if (!rows.length) {
    const em = document.createElement('div');
    em.className = 'ex-col-empty';
    em.textContent = opts.emptyText || '';
    body.appendChild(em);
  } else {
    rows.forEach(r => body.appendChild(buildExRow(r)));
  }
  col.appendChild(body);
  return col;
}

function buildExRow(r) {
  const b = document.createElement('button');
  b.type = 'button';
  b.className = 'ex-row' + (r.active ? ' active' : '');
  b.setAttribute('role', 'option');
  b.setAttribute('aria-selected', r.active ? 'true' : 'false');
  b.tabIndex = r.active ? 0 : -1;
  if (r.color) b.style.setProperty('--ex-tint', r.color);
  b.innerHTML =
    `<span class="ex-row-sym" aria-hidden="true">${r.icon || esc(r.sym || '')}</span>` +
    `<span class="ex-row-label">${esc(r.label)}</span>` +
    (r.meta ? `<span class="ex-row-meta">${esc(r.meta)}</span>` : '') +
    (r.hasChildren ? EX_CHEVRON : '');
  b.onclick = () => r.onSelect && r.onSelect();
  b.ondblclick = () => (r.onOpen || r.onSelect) && (r.onOpen ? r.onOpen(b) : r.onSelect());
  b._exOpen = r.onOpen ? () => r.onOpen(b) : null;
  return b;
}

// Keyboard model for the column browser: ↑/↓ move within a column, → descends
// into the next column, ← ascends, Enter opens. Rows are native buttons so
// focus/blur are free; we only translate the arrow keys into column moves.
function bindExplorerKeys(wrap) {
  wrap.addEventListener('keydown', (e) => {
    const cur = document.activeElement;
    if (!cur || !cur.classList || !cur.classList.contains('ex-row')) return;
    const col = cur.closest('.ex-col');
    if (!col) return;
    const rows = [...col.querySelectorAll('.ex-row')];
    const i = rows.indexOf(cur);
    if (e.key === 'ArrowDown') { e.preventDefault(); (rows[i + 1] || rows[0]).focus(); }
    else if (e.key === 'ArrowUp') { e.preventDefault(); (rows[i - 1] || rows[rows.length - 1]).focus(); }
    else if (e.key === 'ArrowRight') {
      e.preventDefault();
      const next = col.nextElementSibling;
      if (next && next.classList.contains('ex-col')) {
        (next.querySelector('.ex-row.active') || next.querySelector('.ex-row'))?.focus();
      } else {
        cur.click(); // no next column yet — selecting reveals/descends
      }
    } else if (e.key === 'ArrowLeft') {
      e.preventDefault();
      const prev = col.previousElementSibling;
      if (prev && prev.classList.contains('ex-col')) {
        (prev.querySelector('.ex-row.active') || prev.querySelector('.ex-row'))?.focus();
      }
    } else if (e.key === 'Enter') {
      e.preventDefault();
      cur._exOpen ? cur._exOpen() : cur.click();
    }
  });
}

// ════════════════════════════════════════════════════════════════
// TIMELINE LAYOUT (§3.2 — chronological, animated)
// ════════════════════════════════════════════════════════════════
// Items laid along a time axis by reminder.at when present, else createdAt, else
// (for pre-schema-4 items) their array order in an "Undated" lane. A "now"
// playhead separates overdue reminders (persimmon) from what's upcoming. Cards
// reuse buildItem(), so search / detail / drag keep working; entrance is
// staggered via IntersectionObserver and gated behind prefers-reduced-motion.
const _tlStartOfDay = ts => { const d = new Date(ts); d.setHours(0, 0, 0, 0); return d.getTime(); };
const _tlStartOfWeek = ts => { const d = new Date(ts); d.setHours(0, 0, 0, 0); d.setDate(d.getDate() - ((d.getDay() + 6) % 7)); return d.getTime(); };
const _tlStartOfMonth = ts => { const d = new Date(ts); return new Date(d.getFullYear(), d.getMonth(), 1).getTime(); };
function _tlBucketStart(ts, zoom) {
  return zoom === 'month' ? _tlStartOfMonth(ts) : zoom === 'week' ? _tlStartOfWeek(ts) : _tlStartOfDay(ts);
}
function _tlBucketLabel(start, zoom) {
  const d = new Date(start);
  const sameYear = d.getFullYear() === new Date().getFullYear();
  if (zoom === 'month') return d.toLocaleDateString(appLocale(), { month: 'long', year: 'numeric' });
  if (zoom === 'week') return tr('timeline.weekOf', { date: d.toLocaleDateString(appLocale(), sameYear ? { month: 'short', day: 'numeric' } : { year: 'numeric', month: 'short', day: 'numeric' }) });
  return d.toLocaleDateString(appLocale(), { weekday: 'short', month: 'short', day: 'numeric' }) + (sameYear ? '' : ', ' + d.getFullYear());
}

function setTimelineZoom(z) {
  if (!['day', 'week', 'month'].includes(z) || z === timelineZoom) return;
  timelineZoom = z;
  renderBoard();
}

function renderTimelineView() {
  const $b = spaceViewHost();
  $b.innerHTML = '';
  $b.classList.add('timeline-mode');
  const cat = activeCat(); if (!cat) return;

  // Flatten the category's items (recursing through stacks, whose container
  // cards aren't themselves timeline entries) and compute each one's moment.
  const entries = [];
  let order = 0;
  const walk = (list, group) => {
    list.forEach(it => {
      if (it.type === 'stack') { walk(it.items || [], group); return; }
      const time = (it.reminder && it.reminder.at != null) ? it.reminder.at
        : (it.createdAt != null ? it.createdAt : null);
      entries.push({
        it, group, parent: list, order: order++,
        time, dated: time != null,
        overdue: !!(it.reminder && it.reminder.at != null && it.reminder.at < Date.now()),
      });
    });
  };
  cat.groups.forEach(g => walk(g.items, g));

  if (!entries.length) {
    $b.appendChild(buildEmptySpaceState(cat));
    return;
  }

  const wrap = document.createElement('div');
  wrap.className = 'tl-wrap';

  // Zoom control (day / week / month granularity).
  // Zoom control (day / week / month granularity): one switch whose thumb
  // slides to the chosen scale.
  const zooms = ['day', 'week', 'month'];
  const ctrl = document.createElement('div');
  ctrl.className = 'tl-controls spc-seg';
  ctrl.setAttribute('role', 'group');
  ctrl.setAttribute('aria-label', tr('timeline.scale'));
  ctrl.style.setProperty('--spc-i', String(Math.max(0, zooms.indexOf(timelineShownZoom || timelineZoom))));
  ctrl.innerHTML = `<span class="spc-thumb" aria-hidden="true"></span>` +
    zooms.map(z =>
      `<button type="button" class="tl-zoom${z === timelineZoom ? ' active' : ''}" data-zoom="${z}" data-spc-focus="tl:${z}" aria-pressed="${z === timelineZoom}">${esc(tr(`timeline.${z}`))}</button>`
    ).join('');
  ctrl.querySelectorAll('.tl-zoom').forEach(b => b.onclick = () => setTimelineZoom(b.dataset.zoom));
  wrap.appendChild(ctrl);

  const track = document.createElement('div');
  track.className = 'tl-track';

  const dated = entries.filter(e => e.dated).sort((a, b) => a.time - b.time);
  const undated = entries.filter(e => !e.dated); // keep array order

  // Bucket the dated entries by the active granularity.
  const buckets = [];
  let curBucket = null;
  for (const e of dated) {
    const start = _tlBucketStart(e.time, timelineZoom);
    if (!curBucket || curBucket.start !== start) {
      curBucket = { start, label: _tlBucketLabel(start, timelineZoom), items: [] };
      buckets.push(curBucket);
    }
    curBucket.items.push(e);
  }

  // IntersectionObserver drives the staggered entrance; reduced-motion users get
  // the cards revealed instantly (CSS also disables the transition).
  const reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const io = (!reduce && 'IntersectionObserver' in window)
    ? new IntersectionObserver((obs) => obs.forEach(en => { if (en.isIntersecting) { en.target.classList.add('in'); io.unobserve(en.target); } }), { root: null, threshold: 0.05 })
    : null;

  const buildEntry = (e, idx) => {
    const entry = document.createElement('div');
    entry.className = 'tl-entry' + (e.overdue ? ' overdue' : '');
    entry.style.setProperty('--i', Math.min(idx, 12));
    const dot = document.createElement('span');
    dot.className = 'tl-dot';
    if (e.it.color || e.group.color) dot.style.background = e.it.color || e.group.color;
    entry.appendChild(dot);
    const card = document.createElement('div');
    card.className = 'tl-card';
    card.appendChild(buildItem(e.it, e.parent, e.group));
    entry.appendChild(card);
    if (io) io.observe(entry); else entry.classList.add('in');
    return entry;
  };

  const nowBucketStart = _tlBucketStart(Date.now(), timelineZoom);
  const nowDivider = () => {
    const d = document.createElement('div');
    d.className = 'tl-now';
    d.innerHTML = `<span class="tl-now-dot" aria-hidden="true"></span><span class="tl-now-label">${esc(tr('timeline.now'))}</span><span class="tl-now-time">${esc(planTimeLabel(Date.now()))}</span>`;
    return d;
  };

  let nowPlaced = false;
  buckets.forEach(bk => {
    if (!nowPlaced && bk.start >= nowBucketStart) { track.appendChild(nowDivider()); nowPlaced = true; }
    const section = document.createElement('div');
    section.className = 'tl-bucket' + (bk.start === nowBucketStart ? ' current' : '');
    const lab = document.createElement('div');
    lab.className = 'tl-bucket-label';
    lab.textContent = bk.label;
    section.appendChild(lab);
    const items = document.createElement('div');
    items.className = 'tl-bucket-items';
    bk.items.forEach((e, i) => items.appendChild(buildEntry(e, i)));
    section.appendChild(items);
    track.appendChild(section);
  });
  if (!nowPlaced) track.appendChild(nowDivider());

  if (undated.length) {
    const section = document.createElement('div');
    section.className = 'tl-bucket tl-undated';
    const lab = document.createElement('div');
    lab.className = 'tl-bucket-label';
    lab.textContent = tr('timeline.undated');
    section.appendChild(lab);
    const items = document.createElement('div');
    items.className = 'tl-bucket-items';
    undated.forEach((e, i) => items.appendChild(buildEntry(e, i)));
    section.appendChild(items);
    track.appendChild(section);
  }

  wrap.appendChild(track);
  $b.appendChild(wrap);
  decorateSpaceCards(wrap);
  const zoomIndex = String(zooms.indexOf(timelineZoom));
  if (ctrl.style.getPropertyValue('--spc-i') !== zoomIndex) {
    void ctrl.offsetWidth;
    ctrl.style.setProperty('--spc-i', zoomIndex);
  }
  timelineShownZoom = timelineZoom;
  applySearchFilter();
}

// ════════════════════════════════════════════════════════════════
// GALLERY LAYOUT (§3.3 — content-first masonry)
// ════════════════════════════════════════════════════════════════
// A masonry grid of the active category, split into labeled group sections that
// keep the bento compartment feel (gradient top-accent, group tint). Cards reuse
// buildItem(), so search / detail / drag and the item covers all keep working;
// covers and favicons read as "covers" for a quick visual scan. The masonry is
// pure CSS `columns` (no dependency); empty sections collapse under an active
// search via applySearchFilter's .gl-section pass. Clicking a section header
// opens that group's page (§4.1).
function renderGalleryView() {
  const $b = spaceViewHost();
  $b.innerHTML = '';
  $b.classList.add('gallery-mode');
  const cat = activeCat(); if (!cat) return;

  if (!cat.groups.length) {
    $b.appendChild(buildEmptySpaceState(cat));
    return;
  }

  const wrap = document.createElement('div');
  wrap.className = 'gl-wrap';

  cat.groups.forEach(g => {
    const section = document.createElement('section');
    section.className = 'gl-section';
    if (g.color) section.style.setProperty('--gl-tint', g.color);

    const heading = document.createElement('h2');
    heading.className = 'gl-sec-h';
    const hd = document.createElement('button');
    hd.type = 'button';
    hd.className = 'gl-section-hd';
    hd.dataset.spcFocus = `gl:${g.id}`;
    hd.title = `${g.name} · ${tr('groupAction.openAsPage')}`;
    hd.setAttribute('aria-label', `${g.name} · ${tr('groupAction.openAsPage')}`);
    hd.innerHTML =
      `<span class="gl-sec-dot" aria-hidden="true"></span>` +
      `<span class="gl-sec-name">${esc(g.name)}</span>` +
      `<span class="gl-sec-count" aria-hidden="true">${g.items.length}</span>`;
    hd.addEventListener('click', () => openGroupPage(g.id));
    heading.appendChild(hd);
    section.appendChild(heading);

    const grid = document.createElement('div');
    grid.className = 'gl-grid';
    if (!g.items.length) {
      const em = document.createElement('div');
      em.className = 'gl-empty';
      em.textContent = tr('explorer.empty');
      grid.appendChild(em);
    } else {
      // Items are placed directly as column children (not wrapped) so the shared
      // .hidden search class removes them from the masonry flow cleanly.
      g.items.forEach(it => grid.appendChild(buildItem(it, g.items, g)));
    }
    section.appendChild(grid);
    wrap.appendChild(section);
  });

  $b.appendChild(wrap);
  decorateSpaceCards(wrap);
  applySearchFilter();
}

// ════════════════════════════════════════════════════════════════
// GRAPH LAYOUT (§3.4 — relationship map, stretch)
// ════════════════════════════════════════════════════════════════
// A static radial relationship view of the active category: the category at the
// hub, its groups on a ring, each group's items fanned around it, plus faint
// cross-links between items that share a domain. Deterministic geometry (no
// physics sim) keeps it jank-free and reproducible; nodes are click/keyboard
// targets — a hub opens its group page (§4.1), a leaf opens the item. The whole
// figure fades in unless prefers-reduced-motion. Marked stretch in the plan;
// this is the readable "rings by group" variant rather than a force sim.
const _grReduceMotion = () => !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
function graphItemLabel(it) {
  if (it.type === 'todo') return it.text || 'Untitled';
  if (it.type === 'note') return (it.html || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim() || 'Note';
  if (it.type === 'stack') return it.name || 'Stack';
  return it.title || dispUrl(it.url) || 'Untitled';
}
function _grClip(s, n) { s = String(s); return s.length > n ? s.slice(0, n - 1) + '…' : s; }
function renderGraphView() {
  const $b = spaceViewHost();
  $b.innerHTML = '';
  $b.classList.add('graph-mode');
  const cat = activeCat(); if (!cat) return;

  // Flatten each group's items (a stack contributes its leaves, not itself).
  const groups = cat.groups.map(g => {
    const items = [];
    const walk = list => list.forEach(it => it.type === 'stack' ? walk(it.items || []) : items.push(it));
    walk(g.items);
    return { g, items };
  });
  if (!groups.length) {
    $b.appendChild(buildEmptySpaceState(cat));
    return;
  }
  const totalItems = groups.reduce((n, x) => n + x.items.length, 0);

  const W = 960, H = 640, cx = W / 2, cy = H / 2;
  const n = groups.length;
  const Rg = n <= 1 ? 0 : Math.min(232, 118 + n * 8);

  const hubs = [], leaves = [], spokes = [], links = [], cross = [];
  const domainMap = new Map();

  groups.forEach((grp, i) => {
    const ga = -Math.PI / 2 + i * (2 * Math.PI / n);
    const hx = n <= 1 ? cx : cx + Rg * Math.cos(ga);
    const hy = n <= 1 ? cy : cy + Rg * Math.sin(ga);
    const color = grp.g.color || 'var(--accent)';
    hubs.push({ x: hx, y: hy, g: grp.g, color, count: grp.items.length });
    if (n > 1) spokes.push([cx, cy, hx, hy]);

    const c = grp.items.length;
    const ri = Math.max(52, Math.min(120, 42 + c * 6));
    grp.items.forEach((it, j) => {
      // Fan the leaves around the hub, biased outward from the centre so they
      // don't pile onto the spoke.
      const ia = n <= 1
        ? (j * 2 * Math.PI / Math.max(c, 1))
        : ga + (c <= 1 ? 0 : (j - (c - 1) / 2) * Math.min(2 * Math.PI / c, 0.62));
      const ix = hx + ri * Math.cos(ia);
      const iy = hy + ri * Math.sin(ia);
      const node = { x: ix, y: iy, it, gid: grp.g.id, right: Math.cos(ia) >= -0.05, color: reminderDotColor(it.color || grp.g.color) };
      leaves.push(node);
      links.push([hx, hy, ix, iy, color, grp.g.id]);
      let host = '';
      if (it.type === 'tab' && it.url) { try { host = new URL(it.url).hostname.replace(/^www\./, ''); } catch {} }
      if (host) { if (!domainMap.has(host)) domainMap.set(host, []); domainMap.get(host).push(node); }
    });
  });

  // Shared-domain relationship edges (§3.4). Chain consecutive same-domain leaves
  // rather than every pair, so a big domain doesn't turn into a hairball.
  domainMap.forEach(list => { for (let k = 1; k < list.length; k++) cross.push([list[k-1].x, list[k-1].y, list[k].x, list[k].y]); });

  const f = v => v.toFixed(1);
  let s = `<svg class="gr-svg" viewBox="0 0 ${W} ${H}" preserveAspectRatio="xMidYMid meet" xmlns="http://www.w3.org/2000/svg">`;
  s += `<g class="gr-edges">`;
  cross.forEach(([x1,y1,x2,y2]) => { s += `<line class="gr-cross" x1="${f(x1)}" y1="${f(y1)}" x2="${f(x2)}" y2="${f(y2)}"/>`; });
  spokes.forEach(([x1,y1,x2,y2]) => { s += `<line class="gr-spoke" x1="${f(x1)}" y1="${f(y1)}" x2="${f(x2)}" y2="${f(y2)}"/>`; });
  links.forEach(([x1,y1,x2,y2,col,gid]) => { s += `<line class="gr-link" data-g="${esc(gid)}" x1="${f(x1)}" y1="${f(y1)}" x2="${f(x2)}" y2="${f(y2)}" style="stroke:${col}"/>`; });
  s += `</g>`;
  // The Space and its groups are pills; each pill is sized to its label once drawn.
  s += `<g class="gr-node gr-center"><rect class="gr-pill" rx="18"/><text class="gr-pill-text" x="${f(cx)}" y="${f(cy + 5.5)}">${esc(cat.name)}</text></g>`;
  leaves.forEach((node, i) => {
    const label = graphItemLabel(node.it);
    s += `<g class="gr-node gr-item" data-item-id="${esc(node.it.id)}" data-g="${esc(node.gid)}" style="--i:${Math.min(i,20)}" tabindex="0" role="button" aria-label="${esc(label)}">`
      + `<circle class="gr-hit" r="15" cx="${f(node.x)}" cy="${f(node.y)}"/>`
      + `<circle class="gr-leaf" r="5.5" cx="${f(node.x)}" cy="${f(node.y)}" style="fill:${node.color}"/>`
      + `<text class="gr-label" text-anchor="${node.right ? 'start' : 'end'}" x="${f(node.x + (node.right ? 12 : -12))}" y="${f(node.y + 4)}">${esc(_grClip(label, 26))}</text>`
      + `<title>${esc(label)}</title></g>`;
  });
  hubs.forEach((h, i) => {
    s += `<g class="gr-node gr-hub" data-group-id="${esc(h.g.id)}" data-g="${esc(h.g.id)}" style="--i:${Math.min(i,14)};--gr-c:${h.color}" tabindex="0" role="button" aria-label="${esc(`${h.g.name} · ${tr('groupAction.openAsPage')}`)}">`
      + `<rect class="gr-pill" rx="21"/>`
      + `<circle class="gr-hub-dot" r="4.5" cx="${f(h.x)}" cy="${f(h.y)}" style="fill:${h.color}"/>`
      + `<text class="gr-pill-text" x="${f(h.x)}" y="${f(h.y + 5)}">${esc(_grClip(h.g.name, 22))}<tspan class="gr-pill-n" dx="8">${h.count}</tspan></text>`
      + `<title>${esc(`${h.g.name} · ${tr('groupAction.openAsPage')}`)}</title></g>`;
  });
  s += `</svg>`;

  const wrap = document.createElement('div');
  wrap.className = 'gr-wrap';
  wrap.innerHTML = s;
  $b.appendChild(wrap);

  wrap.querySelectorAll('.gr-hub').forEach(el => {
    const id = el.dataset.groupId;
    const go = () => openGroupPage(id);
    el.addEventListener('click', go);
    el.addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); go(); } });
  });
  wrap.querySelectorAll('.gr-item').forEach(el => {
    const id = el.dataset.itemId;
    const act = () => {
      const info = findItem(id); if (!info) return;
      // A tab opens its page; every other kind opens its detail pane — the same
      // "click a node to act on it" model the other layouts use.
      if (info.item.type === 'tab') openSavedTabItem(info.item, { focus: true, opener: el });
      else openItemDetail(id);
    };
    el.addEventListener('click', act);
    el.addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); act(); } });
  });

  sizeGraphPills(wrap);
  // Pointing at (or focusing) a group lights its branch and dims the rest; a
  // click pins it until the next click.
  const light = id => {
    wrap.classList.toggle('has-hot', !!id);
    wrap.querySelectorAll('[data-g]').forEach(el => el.classList.toggle('is-hot', !!id && el.dataset.g === id));
  };
  wrap.querySelectorAll('.gr-hub').forEach(el => {
    el.addEventListener('mouseenter', () => light(el.dataset.groupId));
    el.addEventListener('focus', () => light(el.dataset.groupId));
    el.addEventListener('mouseleave', () => light(null));
    el.addEventListener('blur', () => light(null));
  });

  const svg = wrap.querySelector('.gr-svg');
  if (svg) { if (_grReduceMotion()) svg.classList.add('in'); else requestAnimationFrame(() => svg.classList.add('in')); }
}

// Fit each pill (the Space and its groups) to its drawn label.
function sizeGraphPills(wrap) {
  wrap.querySelectorAll('.gr-center, .gr-hub').forEach(node => {
    const text = node.querySelector('.gr-pill-text');
    const pill = node.querySelector('.gr-pill');
    if (!text || !pill || typeof text.getBBox !== 'function') return;
    let box;
    try { box = text.getBBox(); } catch { return; }
    if (!box || !box.width) return;
    const hub = node.classList.contains('gr-hub');
    const padX = hub ? 16 : 18;
    const dotRoom = hub ? 14 : 0;
    const height = hub ? 42 : 36;
    const width = box.width + padX * 2 + dotRoom;
    const cxv = box.x + box.width / 2;
    const cyv = Number(text.getAttribute('y')) - (hub ? 5 : 5.5);
    const left = cxv - width / 2 - dotRoom / 2;
    pill.setAttribute('x', left.toFixed(1));
    pill.setAttribute('y', (cyv - height / 2).toFixed(1));
    pill.setAttribute('width', width.toFixed(1));
    pill.setAttribute('height', String(height));
    if (hub) {
      const dot = node.querySelector('.gr-hub-dot');
      dot?.setAttribute('cx', (left + padX).toFixed(1));
      text.setAttribute('x', (Number(text.getAttribute('x')) + dotRoom / 2).toFixed(1));
    }
  });
}

// ════════════════════════════════════════════════════════════════
// CALENDAR (§5 — unified reminders surface)
// ════════════════════════════════════════════════════════════════
// A workspace-scoped calendar that projects the reminder aggregator (§2.3) onto
// a time axis. It is a routed surface (`…/calendar?cal=<view>`), not an overlay,
// so it deep-links and browser back/forward work. Three views share one data
// source and one filter language (the board search operators, §5.2): a Month
// grid, a Week column view, and an Agenda "reminders inbox". Item reminders can
// be dragged to another day (§5.3) — every write routes through the shared
// setReminder/clearReminder path so alarm scheduling stays correct.

// Drag-to-reschedule payload (the entry being dragged); null when idle.
let calDrag = null;
// Filter-input focus/caret to restore across the re-render each keystroke fires,
// so typing in the calendar filter never loses the cursor.
let _calFilterRestore = null;
let _calFilterTimer = null;

// Named item colors resolve to their theme token; group/category hex colors are
// used as-is. Absent → the accent.
const CAL_COLOR_VARS = { red: 'var(--red)', orange: 'var(--orange)', yellow: 'var(--yellow)', green: 'var(--green)', blue: 'var(--blue)' };
function reminderDotColor(color) {
  if (!color) return 'var(--accent)';
  return CAL_COLOR_VARS[color] || color;
}
function _calReduceMotion() {
  return !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
}

// ── Navigation ──────────────────────────────────────────────────
function openCalendar() {
  const ws = activeWs(); if (!ws) return;
  let reminderCount = 0;
  try { reminderCount = collectPendingReminders({ scope: ws.id }).length; } catch {}
  const current = activeCalendar && CAL_VIEWS.includes(activeCalendar.view) ? activeCalendar.view : null;
  const last = activeCalendar && CAL_VIEWS.includes(activeCalendar.lastCalendarView) ? activeCalendar.lastCalendarView : null;
  const view = current || last || (reminderCount < 5 ? 'agenda' : 'month');
  Router.navigate({ type: 'calendar', wsId: ws.id, query: view !== 'month' ? { cal: view } : {} });
}
function closeCalendar() {
  const ws = activeWs();
  const cat = activeCat();
  Router.navigate({ type: 'board', wsId: ws ? ws.id : null, catId: cat ? cat.id : null, query: {} });
}
function setCalendarView(view) {
  if (!CAL_VIEWS.includes(view) || !activeCalendar || activeCalendar.view === view) return;
  const ws = activeWs(); if (!ws) return;
  Router.navigate({ type: 'calendar', wsId: ws.id, query: view !== 'month' ? { cal: view } : {} });
}
// Prev/next page the anchor by the active granularity. Not a route change (the
// anchor is ephemeral), so it just re-renders. A month page keeps the selected
// day; a week page moves the selection by a week, as on the board.
function shiftCalendar(dir) {
  if (!activeCalendar) return;
  if (activeCalendar.view === 'week') {
    calSelectDay(planAddDays(calSelectedDay(), dir * 7));
    return;
  }
  const a = new Date(activeCalendar.anchor);
  a.setMonth(a.getMonth() + dir, 1);
  calSetAnchor(a.getTime());
  renderBoard();
}
function calendarToday() {
  if (!activeCalendar) return;
  calSetAnchor(Date.now());
  calSelectDay(_tlStartOfDay(Date.now()));
}
// Reflect calendar-open state on the top-bar button (called from renderBoard,
// which runs before the calendar's own early-return, so it toggles both ways).
function updateCalendarButton() {
  const b = document.getElementById('calendar-btn');
  if (b) { b.classList.toggle('active', !!activeCalendar); b.setAttribute('aria-pressed', activeCalendar ? 'true' : 'false'); }
}

// ── Data + filtering ────────────────────────────────────────────
// Every reminder in the active workspace, enriched with the group/category name
// so the in:/category: filter operators can match by name.
function buildCalendarEntries() {
  const ws = activeWs();
  if (!ws) return [];
  const catName = Object.create(null), groupName = Object.create(null);
  ws.categories.forEach(c => {
    catName[c.id] = c.name;
    c.groups.forEach(g => { groupName[g.id] = g.name; });
  });
  return collectPendingReminders({ scope: ws.id }).map(e => Object.assign({}, e, {
    catName: catName[e.catId] || '',
    groupName: e.groupId ? (groupName[e.groupId] || '') : '',
  }));
}

// Parse the calendar filter string into a predicate over reminder entries,
// reusing the board's operator grammar (§5.2): type:, color:, source:, in:,
// category:, bare/"quoted" text, all with `-` negation. Returns null for an
// empty query (meaning "keep everything").
function parseCalendarFilter(str) {
  const raw = String(str || '').toLowerCase().trim();
  if (!raw) return null;
  const pos = { type: [], color: [], source: [], in: [], category: [], text: [] };
  const neg = { type: [], color: [], source: [], in: [], category: [], text: [] };
  (raw.match(/-?"[^"]*"|\S+/g) || []).forEach(tok => {
    let bucket = pos;
    if (tok[0] === '-' && tok.length > 1) { bucket = neg; tok = tok.slice(1); }
    if (tok.length > 1 && tok[0] === '"' && tok[tok.length - 1] === '"') {
      const p = tok.slice(1, -1).trim(); if (p) bucket.text.push(p); return;
    }
    let m;
    if ((m = /^type:(.+)$/.exec(tok))) m[1].split(',').forEach(t => { const ct = SEARCH_TYPES[t]; if (ct && !bucket.type.includes(ct)) bucket.type.push(ct); });
    else if ((m = /^colou?r:(.+)$/.exec(tok))) m[1].split(',').forEach(c => { if (SEARCH_COLORS.includes(c)) bucket.color.push(c); });
    else if ((m = /^source:(.+)$/.exec(tok))) m[1].split(',').forEach(s => { if (['item', 'group', 'category'].includes(s)) bucket.source.push(s); });
    else if ((m = /^(?:in|group):(.+)$/.exec(tok))) m[1].split(',').forEach(v => { v = v.trim(); if (v) bucket.in.push(v); });
    else if ((m = /^(?:category|cat):(.+)$/.exec(tok))) m[1].split(',').forEach(v => { v = v.trim(); if (v) bucket.category.push(v); });
    else bucket.text.push(tok);
  });
  const inName = e => (e.groupName || '').toLowerCase();
  const catNm = e => (e.catName || '').toLowerCase();
  const title = e => (e.title || '').toLowerCase();
  const keep = e => (
    (!pos.type.length || pos.type.includes(e.itemType)) &&
    (!pos.color.length || pos.color.includes(e.color)) &&
    (!pos.source.length || pos.source.includes(e.source)) &&
    (!pos.in.length || pos.in.some(f => inName(e).includes(f))) &&
    (!pos.category.length || pos.category.some(f => catNm(e).includes(f))) &&
    (!pos.text.length || pos.text.every(n => title(e).includes(n)))
  );
  const drop = e => (
    (neg.type.length && neg.type.includes(e.itemType)) ||
    (neg.color.length && neg.color.includes(e.color)) ||
    (neg.source.length && neg.source.includes(e.source)) ||
    (neg.in.length && neg.in.some(f => inName(e).includes(f))) ||
    (neg.category.length && neg.category.some(f => catNm(e).includes(f))) ||
    (neg.text.length && neg.text.some(n => title(e).includes(n)))
  );
  return e => keep(e) && !drop(e);
}

// Bucket entries by local day-start (ms), each day's list sorted by time.
function calGroupByDay(entries) {
  const m = new Map();
  entries.forEach(e => { const k = _tlStartOfDay(e.at); if (!m.has(k)) m.set(k, []); m.get(k).push(e); });
  m.forEach(list => list.sort((a, b) => a.at - b.at));
  return m;
}

// ── Interactions ────────────────────────────────────────────────
// Click a dot → jump to a contextful destination (the item's group page with its
// detail pane open, the group page, or the category board). Browser Back returns
// to the calendar.
function openReminderTarget(entry) {
  if (entry.source === 'item') {
    if (!validDetailItemIdForSurface(entry.refId, { wsId: entry.wsId, groupId: entry.groupId })) {
      toast(tr('cal.itemUnavailable'), { danger: true });
      renderBoard();
      return;
    }
    prepareItemDetailOpen(entry.refId);
    Router.navigate({ type: 'group', wsId: entry.wsId, groupId: entry.groupId, itemId: entry.refId, query: {} });
  } else if (entry.source === 'group') {
    Router.navigate({ type: 'group', wsId: entry.wsId, groupId: entry.groupId, itemId: null, query: {} });
  } else {
    Router.navigate({ type: 'board', wsId: entry.wsId, catId: entry.catId, query: {} });
  }
}
// Pointer and keyboard context actions share one anchored menu. Entity removal
// always reopens the reviewed picker and carries the stable reminder id.
function calendarDotMenuItems(entry, opener) {
  const items = [{ text: tr('selection.open'), action: () => openReminderTarget(entry) }];
  if (entry.source === 'item') {
    items.push({
      text: `${tr('reminder.editTitle')}…`,
      action: () => openReminderPicker(entry.refId, undefined, { opener }),
    });
    items.push({ sep: true });
    items.push({ text: tr('detail.clearReminder'), danger: true, action: () => clearReminder(entry.refId) });
  } else {
    items.push({
      text: `${tr('reminder.editTitle')}…`,
      action: () => openEntityReminderPickerOrReport(entry.source, entry.refId, entry.reminderId, { opener }),
    });
    items.push({ sep: true });
    items.push({
      text: tr('reminder.removeNamed', { name: entry.title }),
      danger: true,
      action: () => openEntityReminderPickerOrReport(entry.source, entry.refId, entry.reminderId, {
        opener,
        initialFocus: 'remove',
      }),
    });
  }
  return items;
}
// Move a reminder to a different day, preserving its time-of-day. `receipt`
// words the success toast ("Moved to Mon 9 Nov, 09:00"); the write and its Undo
// are the normal reminder transaction.
function calRescheduleTo(entry, dayStart, receipt = undefined) {
  if (!entry) return false;
  const ts = calMoveTime(entry, dayStart);
  if (ts == null) {
    toast(tr('reminder.futureTime'), { danger: true });
    return false;
  }
  if (ts === entry.at) return true;
  if (entry.source === 'item') return setReminder(entry.refId, ts, { recur: entry.recur, receipt });
  if (!entry.mutationContext) return false;
  return commitEntityReminderMutation(entry.mutationContext, { at: ts }, { receipt });
}
// The time a reminder lands on when it moves to another day: the same time of
// day (DST-safe). On today, a time that has already passed becomes the next
// whole hour, as roll-over does; a past day has no valid time.
function calMoveTime(entry, dayStart, now = Date.now()) {
  if (!entry || !Number.isFinite(Number(entry.at))) return null;
  const ts = planSameTimeOn(entry.at, dayStart);
  if (ts > now) return ts;
  if (dayStart !== planDayStart(now)) return null;
  const next = planNextWholeHour(now);
  return next < planAddDays(dayStart, 1) ? next : null;
}
// Wire a container (day cell / week column) as a drop target for reschedule.
function calMakeDropTarget(el, dayStart) {
  el.addEventListener('dragover', e => {
    if (!calDrag) return;
    e.preventDefault();
    try { e.dataTransfer.dropEffect = 'move'; } catch {}
    el.classList.add('cal-drop');
  });
  el.addEventListener('dragleave', e => { if (!el.contains(e.relatedTarget)) el.classList.remove('cal-drop'); });
  el.addEventListener('drop', e => {
    if (!calDrag) return;
    e.preventDefault();
    el.classList.remove('cal-drop');
    const entry = calDrag; calDrag = null;
    void calMoveEntry(entry, dayStart, null);
  });
}

// A single reminder chip. `showTime` prefixes the time (week/agenda); month cells
// keep it in the tooltip to stay compact.
function calendarSourceLabel(source) {
  if (source === 'group') return tr('cal.sourceGroup');
  if (source === 'category') return tr('cal.sourceSpace');
  return '';
}

function calendarDotTitle(entry) {
  const date = new Date(entry.at).toLocaleString(appLocale(), {
    dateStyle: 'medium',
    timeStyle: 'short',
  });
  const source = calendarSourceLabel(entry.source);
  return tr(source ? 'cal.dotTitleWithSource' : 'cal.dotTitle', {
    title: entry.title,
    date,
    source,
  });
}

// The control that stands for one reminder in the day panel and the Past due
// strip: its title opens the target. Its data attributes are the focus target
// every reminder write, Add task and Plan with AI return to.
function buildCalDot(entry, className = '') {
  const dot = document.createElement('button');
  dot.type = 'button';
  dot.className = 'cal-dot' + (className ? ` ${className}` : '');
  dot.dataset.reminderSource = entry.source;
  dot.dataset.reminderOwnerId = entry.refId;
  if (entry.source !== 'item' && isStableEntityReminderId(entry.reminderId)) {
    dot.dataset.reminderId = entry.reminderId;
  }
  dot.textContent = entry.title;
  dot.title = calendarDotTitle(entry);
  dot.onclick = e => { e.stopPropagation(); openReminderTarget(entry); };
  bindAnchoredContextMenu(dot, () => calendarMoveMenuItems(entry, dot, { withOpen: true }));
  calBindDrag(dot, entry);
  return dot;
}

// Every reminder (item, Group or Space) can be dragged onto a day to move it.
function calBindDrag(el, entry) {
  el.draggable = true;
  el.addEventListener('dragstart', ev => {
    let mutationContext = null;
    if (entry.source !== 'item') {
      mutationContext = createEntityReminderMutationContext(entry.source, entry.refId, entry.reminderId);
      if (!mutationContext) {
        ev.preventDefault();
        renderBoard();
        toast(tr('reminder.entityUnavailable'), { danger: true });
        requestAnimationFrame(() => focusEntityReminderOwnerFallback(entry.source, entry.refId));
        return;
      }
    }
    calDrag = mutationContext ? { ...entry, mutationContext } : entry;
    el.classList.add('cal-dragging');
    try { ev.dataTransfer.setData('text/plain', entry.refId); ev.dataTransfer.effectAllowed = 'move'; } catch {}
  });
  el.addEventListener('dragend', () => { calDrag = null; el.classList.remove('cal-dragging'); });
}

// A day's menu: right-click, ContextMenu or Shift+F10 on a day. It offers the
// reviewed Add task dialog (date, 9:00, Space and Inbox shown before typing)
// beside the day panel's quick add, and opens any of the day's reminders.
const CAL_ADD_ICON = '<svg width="13" height="13" viewBox="0 0 13 13" fill="none"><path d="M6.5 2v9M2 6.5h9" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg>';
function openCalDay(dayStart, list, x, y, opener = null) {
  const dLabel = new Date(dayStart).toLocaleDateString(appLocale(), { weekday: 'long', month: 'long', day: 'numeric' });
  const items = [{ label: dLabel }];
  items.push({
    text: tr('cal.addTask'),
    icon: CAL_ADD_ICON,
    action: () => openCalendarTaskDialog(dayStart, opener),
  });
  if (list && list.length) {
    items.push({ sep: true });
    list.forEach(e => items.push({
      text: e.title,
      sub: new Date(e.at).toLocaleTimeString(appLocale(), { hour: 'numeric', minute: '2-digit' }),
      action: () => openReminderTarget(e),
    }));
  }
  showContextMenu(x, y, items, { focusFirst: true });
}

// Add a task on a given calendar day through one reviewed, receipt-gated
// transaction. The resulting to-do still lives in the exact Space Inbox with a
// 9:00 AM item reminder; Calendar never owns a second event model.
let calendarTaskCtx = null;
let calendarTaskBusy = false;
let calendarTaskMutationPending = null;

function calendarTaskDateParts(dayStart) {
  const value = Number(dayStart);
  if (!Number.isFinite(value)) return null;
  const reviewed = new Date(value);
  if (!Number.isFinite(reviewed.getTime())) return null;
  const normalized = new Date(reviewed);
  normalized.setHours(0, 0, 0, 0);
  if (normalized.getTime() !== value) return null;
  const when = new Date(normalized);
  when.setHours(9, 0, 0, 0);
  return {
    dayStart: value,
    at: when.getTime(),
    dateLabel: reviewed.toLocaleDateString(appLocale(), {
      weekday: 'long',
      year: 'numeric',
      month: 'long',
      day: 'numeric',
    }),
    timeLabel: when.toLocaleTimeString(appLocale(), {
      hour: 'numeric',
      minute: '2-digit',
    }),
  };
}

function createCalendarTaskMutationContext(dayStart) {
  const date = calendarTaskDateParts(dayStart);
  if (!date) return null;
  const state = State.get();
  const workspaceId = String(state.activeWsId || '');
  const workspace = organizationWorkspaceTarget(workspaceId);
  if (!workspace) return null;
  const spaceId = String(workspace.activeCatId || '');
  const location = identitySpaceTarget(workspaceId, spaceId);
  if (!location || location.workspace !== workspace || !Array.isArray(location.space.groups)) return null;
  const inboxes = location.space.groups.filter(group => group?.name === 'Inbox');
  if (inboxes.length > 1) return null;
  const inbox = inboxes[0] || null;
  if (inbox && (!inbox.id || !Array.isArray(inbox.items))) return null;
  if (inbox) {
    const exactInbox = organizationGroupTarget(String(inbox.id));
    if (!exactInbox
        || exactInbox.workspace !== workspace
        || exactInbox.space !== location.space
        || exactInbox.group !== inbox) return null;
  }
  return {
    workspaceId,
    workspaceRef: workspace,
    spaceId,
    spaceRef: location.space,
    spaceName: String(location.space.name || ''),
    inboxId: inbox ? String(inbox.id) : null,
    inboxRef: inbox,
    inboxName: inbox ? String(inbox.name) : 'Inbox',
    ...date,
  };
}

function resolveCalendarTaskMutationTarget(context) {
  if (!context || !context.workspaceId || !context.spaceId) return null;
  const state = State.get();
  if (String(state.activeWsId || '') !== context.workspaceId) return null;
  const workspace = organizationWorkspaceTarget(context.workspaceId);
  if (!workspace
      || workspace !== context.workspaceRef
      || String(workspace.activeCatId || '') !== context.spaceId) return null;
  const location = identitySpaceTarget(context.workspaceId, context.spaceId);
  if (!location
      || location.workspace !== workspace
      || location.space !== context.spaceRef
      || !Array.isArray(location.space.groups)) return null;
  const inboxes = location.space.groups.filter(group => group?.name === 'Inbox');
  if (context.inboxRef) {
    if (inboxes.length !== 1
        || inboxes[0] !== context.inboxRef
        || String(inboxes[0].id || '') !== context.inboxId
        || !Array.isArray(inboxes[0].items)) return null;
    const exactInbox = organizationGroupTarget(context.inboxId);
    if (!exactInbox
        || exactInbox.workspace !== workspace
        || exactInbox.space !== location.space
        || exactInbox.group !== context.inboxRef) return null;
    return { workspace, space: location.space, inbox: context.inboxRef };
  }
  if (context.inboxId != null || inboxes.length) return null;
  return { workspace, space: location.space, inbox: null };
}

function isCalendarTaskMutationPending() {
  return !!calendarTaskMutationPending;
}

function setCalendarTaskInterlock(enabled) {
  const overlay = document.getElementById('calendar-task-overlay');
  const recovery = document.getElementById('state-recovery-overlay');
  for (const child of document.body.children) {
    if (child === overlay || child === recovery) continue;
    setElementInertOwner(child, 'calendar-task', enabled);
  }
}

function paintCalendarTaskDialog() {
  if (calendarTaskCtx?.inline) {
    paintCalendarAddInline();
    return;
  }
  const overlay = document.getElementById('calendar-task-overlay');
  if (!overlay || !calendarTaskCtx) return;
  const input = document.getElementById('calendar-task-input');
  const status = document.getElementById('calendar-task-status');
  const close = document.getElementById('calendar-task-close');
  const cancel = document.getElementById('calendar-task-cancel');
  const confirm = document.getElementById('calendar-task-confirm');
  const unavailable = calendarTaskCtx.unavailable === true;
  const errorKey = calendarTaskCtx.errorKey || null;
  document.getElementById('calendar-task-description').textContent = tr('cal.addDescription', {
    space: calendarTaskCtx.spaceName,
    group: calendarTaskCtx.inboxName,
    date: calendarTaskCtx.dateLabel,
    time: calendarTaskCtx.timeLabel,
  });
  status.textContent = calendarTaskBusy
    ? tr('cal.adding')
    : (errorKey ? tr(errorKey) : '');
  if (calendarTaskBusy) status.dataset.tone = 'pending';
  else if (errorKey) status.dataset.tone = 'error';
  else delete status.dataset.tone;
  input.disabled = calendarTaskBusy || unavailable;
  input.setAttribute('aria-invalid', String(errorKey === 'cal.taskRequired'));
  close.disabled = calendarTaskBusy;
  cancel.disabled = calendarTaskBusy;
  confirm.disabled = calendarTaskBusy || unavailable;
  confirm.setAttribute('aria-disabled', String(confirm.disabled));
  confirm.textContent = tr(calendarTaskBusy ? 'cal.adding' : 'cal.confirmAdd');
  overlay.setAttribute('aria-busy', String(calendarTaskBusy));
}

function setCalendarTaskBusy(busy) {
  calendarTaskBusy = !!busy;
  paintCalendarTaskDialog();
  if (calendarTaskBusy && !calendarTaskCtx?.inline) {
    const confirm = document.getElementById('calendar-task-confirm');
    try { confirm?.focus({ preventScroll: true }); } catch { try { confirm?.focus(); } catch {} }
  }
}

function setCalendarTaskError(errorKey, { unavailable = false } = {}) {
  if (!calendarTaskCtx) return;
  calendarTaskCtx.errorKey = errorKey || null;
  calendarTaskCtx.unavailable = !!unavailable;
  paintCalendarTaskDialog();
  if (calendarTaskCtx.inline) {
    const input = document.getElementById('cal-add-input');
    try { input?.focus({ preventScroll: true }); } catch { try { input?.focus(); } catch {} }
    return;
  }
  const target = unavailable
    ? document.getElementById('calendar-task-close')
    : document.getElementById('calendar-task-input');
  try { target?.focus({ preventScroll: true }); } catch { try { target?.focus(); } catch {} }
}

function focusCalendarTaskFallback(context) {
  const spaceId = String(context?.spaceId || '');
  const escapedSpaceId = typeof CSS !== 'undefined' && typeof CSS.escape === 'function'
    ? CSS.escape(spaceId)
    : spaceId.replace(/["\\]/g, '\\$&');
  const candidates = [
    ...(escapedSpaceId ? [
      `.space-item[data-cat-id="${escapedSpaceId}"]`,
      `.cat-tab[data-cid="${escapedSpaceId}"]`,
    ] : []),
    '#cal-filter-input',
    '#nav-home',
  ];
  for (const selector of candidates) {
    const target = document.querySelector(selector);
    if (!target || typeof target.focus !== 'function') continue;
    try { target.focus({ preventScroll: true }); } catch { try { target.focus(); } catch {} }
    if (document.activeElement === target) return true;
  }
  return false;
}

function focusCalendarTaskMutationTarget(context, itemId, groupId) {
  const escapeValue = value => (
    typeof CSS !== 'undefined' && typeof CSS.escape === 'function'
      ? CSS.escape(String(value))
      : String(value).replace(/["\\]/g, '\\$&')
  );
  const focusTarget = target => {
    if (!target || typeof target.focus !== 'function') return false;
    try { target.focus({ preventScroll: true }); } catch { try { target.focus(); } catch {} }
    if (document.activeElement !== target) return false;
    try { target.scrollIntoView({ block: 'nearest' }); } catch {}
    return true;
  };
  // A task added from the day panel lands in its list; focus stays in the add
  // field for the next one.
  if (context?.inline && activeCalendar) {
    calMarkDropped(itemId);
    if (focusTarget(document.getElementById('cal-add-input'))) return true;
  }
  const escapedItemId = escapeValue(itemId || '');
  if (activeCalendar && escapedItemId && focusTarget(document.querySelector(
    `.cal-dot[data-reminder-source="item"][data-reminder-owner-id="${escapedItemId}"]`,
  ))) return true;
  if (groupId && focusIdentityTarget('group', groupId)) return true;
  return focusCalendarTaskFallback(context);
}

function closeCalendarTaskDialog({ restoreFocus = true } = {}) {
  if (calendarTaskCtx?.inline) {
    if (calendarTaskBusy) return false;
    calendarTaskCtx = null;
    paintCalendarAddInline();
    return true;
  }
  const overlay = document.getElementById('calendar-task-overlay');
  if (!overlay || overlay.classList.contains('hidden') || calendarTaskBusy) return false;
  const closingContext = calendarTaskCtx;
  overlay.classList.add('hidden');
  unlockBodyScroll();
  setCalendarTaskInterlock(false);
  calendarTaskCtx = null;
  calendarTaskBusy = false;
  if (restoreFocus) {
    if (!restoreOpener(overlay)) setTimeout(() => focusCalendarTaskFallback(closingContext), 0);
  } else {
    _overlayOpeners.delete(overlay);
  }
  return true;
}

function openCalendarTaskDialog(dayStart, opener = null) {
  const overlay = document.getElementById('calendar-task-overlay');
  if (!overlay || !overlay.classList.contains('hidden') || isCalendarTaskMutationPending()) return false;
  const conflictingIds = [
    'state-recovery-overlay',
    'paste-overlay',
    'reminder-overlay',
    'modal-overlay',
    'import-overlay',
    'trash-delete-overlay',
    'organization-name-overlay',
    'organization-delete-overlay',
  ];
  if (conflictingIds.some(id => {
    const element = document.getElementById(id);
    return element && !element.classList.contains('hidden');
  })) return false;
  const workspace = activeWs();
  if (!workspace || !Array.isArray(workspace.categories) || !workspace.categories.length) {
    toast(tr('cal.needSpace'), { danger: true });
    return false;
  }
  const context = createCalendarTaskMutationContext(dayStart);
  if (!context) {
    toast(tr('cal.destinationChanged'), { danger: true });
    return false;
  }
  focusDialogOpener(opener);
  rememberOpener(overlay, opener);
  calendarTaskCtx = {
    ...context,
    errorKey: null,
    unavailable: false,
  };
  calendarTaskBusy = false;
  const input = document.getElementById('calendar-task-input');
  input.value = '';
  setCalendarTaskInterlock(true);
  overlay.classList.remove('hidden');
  lockBodyScroll();
  paintCalendarTaskDialog();
  setTimeout(() => input.focus({ preventScroll: true }), 0);
  return true;
}

async function commitCalendarTaskMutation(context, rawText) {
  if (isCalendarTaskMutationPending()) return false;
  const text = String(rawText || '').trim();
  if (!text) {
    setCalendarTaskError('cal.taskRequired');
    return false;
  }
  if (State.isRecoveryRequired?.()) {
    setCalendarTaskError('cal.saveFailed', { unavailable: true });
    const error = new Error(tr('stateRecovery.detail'));
    error.code = 'LOCUS_STATE_RECOVERY_REQUIRED';
    if (typeof showStateRecoveryRequired === 'function') showStateRecoveryRequired(error);
    return false;
  }
  const target = resolveCalendarTaskMutationTarget(context);
  if (!target) {
    setCalendarTaskError('cal.destinationChanged', { unavailable: true });
    return false;
  }

  let inbox = target.inbox;
  let todo;
  try {
    const allocateId = createOrganizationIdAllocator();
    if (!inbox) {
      inbox = {
        id: allocateId(),
        name: 'Inbox',
        symbol: '📥',
        color: '#6366f1',
        collapsed: false,
        items: [],
      };
    }
    todo = stampNew({
      id: allocateId(),
      type: 'todo',
      text,
      done: false,
      reminder: { at: context.at, notified: false },
    });
  } catch {
    setCalendarTaskError('cal.idUnavailable', { unavailable: true });
    return false;
  }

  const transaction = {
    context,
    inbox,
    inboxWasCreated: !target.inbox,
    itemId: todo.id,
    groupId: inbox.id,
  };
  calendarTaskMutationPending = transaction;
  setCalendarTaskBusy(true);

  let actionId;
  try {
    actionId = State.snapshot(tr('cal.history.addTask'));
    if (transaction.inboxWasCreated) target.space.groups.unshift(inbox);
    inbox.items.push(todo);
  } catch (error) {
    if (calendarTaskMutationPending === transaction) calendarTaskMutationPending = null;
    setCalendarTaskBusy(false);
    setCalendarTaskError('cal.saveFailed', { unavailable: true });
    State.requireRecovery?.();
    if (typeof showStateRecoveryRequired === 'function') showStateRecoveryRequired(error);
    return false;
  }

  let writeReceipt;
  try {
    writeReceipt = await State.persistNow({ reconcileReminders: true });
  } catch (error) {
    if (calendarTaskMutationPending === transaction) calendarTaskMutationPending = null;
    setCalendarTaskBusy(false);
    setCalendarTaskError('cal.saveFailed', { unavailable: true });
    State.requireRecovery?.();
    if (State.isRecoveryRequired?.() && typeof showStateRecoveryRequired === 'function') {
      showStateRecoveryRequired(error);
    }
    return false;
  }

  if (calendarTaskMutationPending !== transaction) return false;
  calendarTaskMutationPending = null;
  setCalendarTaskBusy(false);
  closeCalendarTaskDialog({ restoreFocus: false });
  renderBoard();
  requestAnimationFrame(() => focusCalendarTaskMutationTarget(
    context,
    transaction.itemId,
    transaction.groupId,
  ));
  if (writeReceipt?.reminderReconciliation?.ok === true) {
    toast(tr('cal.added', { date: context.dateLabel }), {
      undo: actionId,
      sub: `${context.spaceName} › ${context.inboxName} · ${context.timeLabel}`,
    });
  } else {
    toast(tr('cal.addScheduleWarning'), {
      tone: 'warning',
      duration: 8000,
      undo: actionId,
    });
  }
  return true;
}

function confirmCalendarTaskAdd() {
  if (!calendarTaskCtx || calendarTaskBusy || calendarTaskCtx.unavailable) return false;
  const input = document.getElementById('calendar-task-input');
  return commitCalendarTaskMutation(calendarTaskCtx, input?.value || '');
}

function handleCalendarTaskGlobalKey(event) {
  const overlay = document.getElementById('calendar-task-overlay');
  const overlayOpen = !!overlay && !overlay.classList.contains('hidden');
  const inside = overlayOpen && overlay.contains(event.target);
  if (isCalendarTaskMutationPending()) {
    if (inside && event.key === 'Tab') return true;
    event.preventDefault();
    event.stopImmediatePropagation();
    if (overlayOpen && !inside) {
      document.getElementById('calendar-task-confirm')?.focus({ preventScroll: true });
    }
    return true;
  }
  if (!overlayOpen || inside) return false;
  event.preventDefault();
  event.stopImmediatePropagation();
  document.getElementById('calendar-task-input')?.focus({ preventScroll: true });
  return true;
}

function bindCalendarTaskDialog() {
  const overlay = document.getElementById('calendar-task-overlay');
  const form = document.getElementById('calendar-task-form');
  const input = document.getElementById('calendar-task-input');
  if (!overlay || !form || !input) return;
  document.getElementById('calendar-task-close').onclick = () => closeCalendarTaskDialog();
  document.getElementById('calendar-task-cancel').onclick = () => closeCalendarTaskDialog();
  form.addEventListener('submit', event => {
    event.preventDefault();
    void confirmCalendarTaskAdd();
  });
  overlay.addEventListener('click', event => {
    if (event.target === overlay) closeCalendarTaskDialog();
  });
  overlay.addEventListener('keydown', event => {
    if (event.key === 'Escape') {
      event.preventDefault();
      event.stopPropagation();
      closeCalendarTaskDialog();
      return;
    }
    if (event.key === 'Tab') {
      trapTabKey(event, overlay);
      return;
    }
    event.stopPropagation();
  });
  input.addEventListener('input', () => {
    if (calendarTaskCtx
        && !calendarTaskCtx.unavailable
        && calendarTaskCtx.errorKey === 'cal.taskRequired') {
      calendarTaskCtx.errorKey = null;
      paintCalendarTaskDialog();
    }
  });
}

// ── View builders ───────────────────────────────────────────────
// The view follows its canvas board (Calendar.dc.html): one toolbar row, the
// Past due strip, then the month, week or agenda view beside a day panel. The
// grid selects a day; the panel lists that day's reminders (open, Move, Edit,
// Clear) and adds a task. The selected day, like the anchor, is view state only.
let calendarPageSession = null;

const CAL_ICONS = {
  prev: 'M10 3.5 5.5 8l4.5 4.5',
  next: 'M6 3.5 10.5 8 6 12.5',
  search: 'M7 12a5 5 0 1 0 0-10 5 5 0 0 0 0 10zM10.6 10.6 13.5 13.5',
  close: 'M4 4l8 8M12 4l-8 8',
  plus: 'M8 3v10M3 8h10',
  arrow: 'M3 8h9M8.5 4.5 12 8l-3.5 3.5',
};
function calIcon(name, size = 15, stroke = 1.7) {
  return planSvg(CAL_ICONS[name] || PLAN_ICONS[name], size, stroke);
}

// One session per visit to the Calendar view: what the last paint showed, so
// the selection box, the view thumb, the panel and the counts can move from
// there instead of jumping.
function calendarSession() {
  if (!calendarPageSession || calendarPageSession.cal !== activeCalendar) {
    calendarPageSession = {
      cal: activeCalendar,
      view: null,
      viewIndex: null,
      sel: null,
      box: null,
      counts: new Map(),
      pulseAt: Date.now(),
      afterMove: null,
    };
  }
  return calendarPageSession;
}

function calSetAnchor(ts) {
  if (!activeCalendar) return;
  activeCalendar.anchor = ts;
  activeCalendar.anchorSeen = ts;
}

// The selected day. When something other than the view moved the anchor (the
// view was just entered, or Plan with AI shows its first block), the selection
// follows the anchor.
function calSelectedDay() {
  if (!activeCalendar) return _tlStartOfDay(Date.now());
  if (activeCalendar.anchorSeen !== activeCalendar.anchor || !Number.isFinite(activeCalendar.selected)) {
    activeCalendar.selected = _tlStartOfDay(activeCalendar.anchor);
    activeCalendar.anchorSeen = activeCalendar.anchor;
  }
  return activeCalendar.selected;
}

function calMonthGridStart() {
  return _tlStartOfWeek(_tlStartOfMonth(activeCalendar.anchor));
}
function calWeekStart() {
  return _tlStartOfWeek(calSelectedDay());
}
// Index of a day in a run of days from `start` (DST-safe), or -1 past `count`.
function calDayIndex(start, day, count) {
  let cursor = start;
  for (let index = 0; index < count; index += 1) {
    if (cursor === day) return index;
    cursor = planAddDays(cursor, 1);
  }
  return -1;
}
function calInMonthGrid(day) {
  return calDayIndex(calMonthGridStart(), day, 42) >= 0;
}

function calSelectDay(dayStart, { focus = false } = {}) {
  if (!activeCalendar || !Number.isFinite(dayStart)) return;
  const day = _tlStartOfDay(dayStart);
  activeCalendar.selected = day;
  // The shown period follows the selection: a week shows the selected day's
  // week, and a day outside the month grid turns the month.
  if (activeCalendar.view === 'week' || (activeCalendar.view === 'month' && !calInMonthGrid(day))) calSetAnchor(day);
  renderBoard();
  if (focus) calFocusDay(day);
}

function calFocusDay(day) {
  const target = document.querySelector(`.cld [data-cal-day="${day}"]`);
  if (!target) return false;
  try { target.focus({ preventScroll: false }); } catch { try { target.focus(); } catch {} }
  return document.activeElement === target;
}

function calEntryKey(entry) {
  return `${entry.source}:${entry.refId}:${entry.reminderId || ''}`;
}

// Restart a one-shot animation class, as Today does.
function calReplay(el, className) {
  if (!el?.classList) return;
  el.classList.remove(className);
  void el.offsetWidth;
  el.classList.add(className);
}

// One authoritative empty message per view: the workspace has no reminders, or
// the filter matches none. Month and Week still draw the grid, so a task can be
// added on any day; the message is the day panel's, or it replaces the Agenda.
function calEmptyKey(allCount, shownCount) {
  if (!allCount) return 'cal.noWorkspaceReminders';
  if (!shownCount) return 'cal.noFilterMatches';
  return null;
}

function calPeriodLabel() {
  if (!activeCalendar) return '';
  if (activeCalendar.view === 'agenda') return tr('cal.upcoming');
  const nowYear = new Date().getFullYear();
  if (activeCalendar.view === 'week') {
    const start = calWeekStart();
    const a = new Date(start), b = new Date(start); b.setDate(b.getDate() + 6);
    const sameMonth = a.getMonth() === b.getMonth();
    const left = a.toLocaleDateString(appLocale(), { month: 'short', day: 'numeric' });
    const right = b.toLocaleDateString(appLocale(), sameMonth ? { day: 'numeric' } : { month: 'short', day: 'numeric' });
    return `${left} – ${right}` + (a.getFullYear() !== nowYear ? `, ${a.getFullYear()}` : '');
  }
  return new Date(activeCalendar.anchor).toLocaleDateString(appLocale(), { month: 'long', year: 'numeric' });
}

// "Today 09:00", "Thu 17:00", or "Nov 2 17:00" for older ones.
function calWhenLabel(at, now = Date.now()) {
  const day = planDayStart(at);
  const today = planDayStart(now);
  if (day === today) return `${tr('cal.today')} ${planTimeLabel(at)}`;
  if (day > planAddDays(today, -7) && day < planAddDays(today, 7)) return `${planWeekdayLabel(at)} ${planTimeLabel(at)}`;
  return `${new Date(at).toLocaleDateString(appLocale(), { month: 'short', day: 'numeric' })} ${planTimeLabel(at)}`;
}

function buildCalToolbar(shownCount, totalCount, session = null, after = []) {
  const bar = document.createElement('div');
  bar.className = 'cld-bar';
  const isAgenda = activeCalendar.view === 'agenda';

  // View switch; its thumb slides from the view shown last.
  const seg = document.createElement('div');
  seg.className = 'cld-seg';
  seg.setAttribute('role', 'group');
  seg.setAttribute('aria-label', tr('cal.viewLabel'));
  const thumb = document.createElement('span');
  thumb.className = 'cld-seg-thumb';
  thumb.setAttribute('aria-hidden', 'true');
  seg.appendChild(thumb);
  [['month', 'cal.view.month'], ['week', 'cal.view.week'], ['agenda', 'cal.view.agenda']].forEach(([v, key]) => {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'cld-seg-btn';
    b.textContent = tr(key);
    b.setAttribute('aria-pressed', String(activeCalendar.view === v));
    b.onclick = () => setCalendarView(v);
    seg.appendChild(b);
  });
  const index = CAL_VIEWS.indexOf(activeCalendar.view);
  const from = session && session.viewIndex != null ? session.viewIndex : index;
  thumb.style.setProperty('--i', String(from));
  if (from !== index) after.push(() => { void thumb.offsetWidth; thumb.style.setProperty('--i', String(index)); });
  if (session) session.viewIndex = index;
  bar.appendChild(seg);

  // Today, previous and next. Agenda lists everything ahead, so it has no pages.
  const nav = document.createElement('div');
  nav.className = 'cld-nav';
  nav.setAttribute('role', 'group');
  nav.setAttribute('aria-label', tr('cal.periodNavigation'));
  const today = document.createElement('button');
  today.type = 'button';
  today.className = 'cld-btn';
  today.textContent = tr('cal.today');
  today.onclick = calendarToday;
  nav.appendChild(today);
  if (!isAgenda) {
    const mkNav = (icon, aria, fn) => {
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'cld-ibtn';
      b.setAttribute('aria-label', aria);
      b.title = aria;
      b.innerHTML = calIcon(icon, 15, 1.8);
      b.onclick = fn;
      return b;
    };
    nav.appendChild(mkNav('prev', tr('cal.previousPeriod'), () => shiftCalendar(-1)));
    nav.appendChild(mkNav('next', tr('cal.nextPeriod'), () => shiftCalendar(1)));
  }
  bar.appendChild(nav);

  const title = document.createElement('h2');
  title.className = 'cld-period';
  title.setAttribute('aria-live', 'polite');
  title.textContent = calPeriodLabel();
  bar.appendChild(title);

  // Filter: the board search vocabulary applied to reminders (§5.2).
  const filter = document.createElement('label');
  filter.className = 'cld-filter';
  filter.innerHTML = calIcon('search', 15, 1.6);
  const input = document.createElement('input');
  input.id = 'cal-filter-input';
  input.type = 'text';
  input.autocomplete = 'off';
  input.spellcheck = false;
  input.placeholder = tr('cal.filterPlaceholder');
  input.setAttribute('aria-label', tr('cal.filterLabel'));
  input.value = calendarFilter;
  input.addEventListener('input', () => {
    calendarFilter = input.value;
    _calFilterRestore = { caret: input.selectionStart };
    clearTimeout(_calFilterTimer);
    _calFilterTimer = setTimeout(() => renderBoard(), 130);
  });
  input.addEventListener('keydown', e => { if (e.key === 'Escape') { e.stopPropagation(); if (input.value) { input.value = ''; calendarFilter = ''; _calFilterRestore = { caret: 0 }; renderBoard(); } else input.blur(); } });
  filter.appendChild(input);
  if (calendarFilter) {
    const count = document.createElement('span');
    count.className = 'cld-filter-count';
    count.textContent = `${shownCount}/${totalCount}`;
    filter.appendChild(count);
    const clear = document.createElement('button');
    clear.type = 'button';
    clear.className = 'cld-filter-clear';
    clear.setAttribute('aria-label', tr('rail.clearFilter'));
    clear.innerHTML = calIcon('close', 12, 2);
    clear.onclick = event => {
      event.preventDefault();
      calendarFilter = '';
      _calFilterRestore = { caret: 0 };
      renderBoard();
    };
    filter.appendChild(clear);
  }
  bar.appendChild(filter);

  return bar;
}

function _calEmptyNote(text) {
  const n = document.createElement('p');
  n.className = 'cld-empty';
  n.textContent = text;
  return n;
}

function calendarDayAriaLabel(dayStart, count) {
  const date = new Date(dayStart).toLocaleDateString(appLocale(), {
    weekday: 'long',
    month: 'long',
    day: 'numeric',
  });
  if (count === 1) return tr('cal.dayOneReminder', { date });
  if (count > 1) return tr('cal.dayManyReminders', { date, count });
  return tr('cal.dayNoReminders', { date });
}

function buildCalMonth(entries, selected, now, session = null, after = []) {
  const wrap = document.createElement('div');
  wrap.className = 'cld-card cld-month';

  // Weekday header (Mon-first, matching the timeline's week start).
  const dows = document.createElement('div');
  dows.className = 'cld-dows';
  dows.setAttribute('aria-hidden', 'true');
  const hdCur = new Date(_tlStartOfWeek(now));
  for (let i = 0; i < 7; i++) {
    const h = document.createElement('span');
    h.textContent = hdCur.toLocaleDateString(appLocale(), { weekday: 'short' });
    dows.appendChild(h);
    hdCur.setDate(hdCur.getDate() + 1);
  }
  wrap.appendChild(dows);

  const grid = document.createElement('div');
  grid.className = 'cld-grid';
  grid.setAttribute('role', 'group');
  grid.setAttribute('aria-label', calPeriodLabel());
  const byDay = calGroupByDay(entries);
  const todayStart = _tlStartOfDay(now);
  const curMonth = new Date(_tlStartOfMonth(activeCalendar.anchor)).getMonth();
  const start = calMonthGridStart();
  const selIndex = calDayIndex(start, selected, 42);
  // Days from the Monday of the month's first week (DST-safe).
  let day = start;
  let firstOfMonth = -1;
  for (let i = 0; i < 42; i++) {
    const date = new Date(day);
    const inMonth = date.getMonth() === curMonth;
    if (inMonth && firstOfMonth < 0) firstOfMonth = i;
    const list = byDay.get(day) || [];
    const cell = document.createElement('button');
    cell.type = 'button';
    cell.className = 'cld-cell' + (inMonth ? '' : ' is-out');
    cell.dataset.calDay = String(day);
    cell.setAttribute('aria-pressed', String(day === selected));
    cell.setAttribute('aria-label', calendarDayAriaLabel(day, list.length));
    cell.appendChild(calDayNumber(date, day === todayStart, session, now));
    list.slice(0, 2).forEach(entry => cell.appendChild(calChip(entry, now, 'cld-chip')));
    if (list.length > 2) {
      const more = document.createElement('span');
      more.className = 'cld-more';
      more.textContent = tr('cal.more', { count: list.length - 2 });
      cell.appendChild(more);
    }
    // At phone width the chips give way to one dot per reminder (up to three).
    if (list.length) {
      const dots = document.createElement('span');
      dots.className = 'cld-dots';
      dots.setAttribute('aria-hidden', 'true');
      list.slice(0, 3).forEach(entry => {
        const dot = document.createElement('i');
        dot.style.setProperty('--dot', reminderDotColor(entry.color));
        dots.appendChild(dot);
      });
      cell.appendChild(dots);
    }
    calBindDay(cell, day, list);
    grid.appendChild(cell);
    day = planAddDays(day, 1);
  }
  const focusIndex = selIndex >= 0 ? selIndex : Math.max(0, firstOfMonth);
  grid.children[focusIndex].tabIndex = 0;
  [...grid.children].forEach((cell, i) => { if (i !== focusIndex) cell.tabIndex = -1; });
  grid.appendChild(calSelectionBox('month', start, selIndex, session, after));
  grid.addEventListener('keydown', calGridKey);
  wrap.appendChild(grid);
  return wrap;
}

// The day number; today's is orange and pulses once when the view opens.
function calDayNumber(date, isToday, session, now) {
  const num = document.createElement('span');
  num.className = 'cld-num' + (isToday ? ' is-today' : '');
  num.textContent = String(date.getDate());
  if (isToday && session) {
    // A repaint during the pulse carries it on instead of restarting it.
    const elapsed = now - session.pulseAt;
    if (elapsed < 1400) {
      num.classList.add('is-pulse');
      num.style.setProperty('--cld-pulse-t', `${-elapsed}ms`);
    }
  }
  return num;
}

// A reminder drawn inside a day: colour, mono time, title. Part of the day's
// target (the day panel holds its actions).
function calChip(entry, now, className) {
  const chip = document.createElement('span');
  chip.className = className + (entry.at < now ? ' is-past' : '');
  chip.dataset.calKey = calEntryKey(entry);
  chip.style.setProperty('--dot', reminderDotColor(entry.color));
  const time = document.createElement('span');
  time.className = 'cld-chip-t';
  time.textContent = planTimeLabel(entry.at);
  const title = document.createElement('span');
  title.className = 'cld-chip-n';
  title.textContent = entry.title;
  chip.append(time, title);
  return chip;
}

// The blue box around the selected day. It slides from where the last paint
// had it when the period is the same.
function calSelectionBox(view, start, index, session, after) {
  const box = document.createElement('span');
  box.className = 'cld-sel';
  box.setAttribute('aria-hidden', 'true');
  const cols = 7;
  const c = index % cols;
  const r = Math.floor(index / cols);
  if (index < 0) box.classList.add('is-off');
  const prev = session?.box;
  const same = prev && prev.view === view && prev.start === start && prev.index >= 0 && index >= 0;
  box.style.setProperty('--c', String(same ? prev.c : c));
  box.style.setProperty('--r', String(same ? prev.r : r));
  if (same && (prev.c !== c || prev.r !== r)) {
    after.push(() => {
      void box.offsetWidth;
      box.style.setProperty('--c', String(c));
      box.style.setProperty('--r', String(r));
    });
  }
  if (session) session.box = { view, start, index, c, r };
  return box;
}

// A day target: click selects it; right-click, ContextMenu or Shift+F10 opens
// the day menu; a dragged reminder can be dropped on it.
function calBindDay(el, day, list) {
  el.addEventListener('click', () => calSelectDay(day, { focus: true }));
  el.addEventListener('contextmenu', event => {
    event.preventDefault();
    event.stopPropagation();
    openCalDay(day, list, event.clientX, event.clientY, el.dataset.calDay ? el : el.querySelector('[data-cal-day]'));
  });
  el.addEventListener('keydown', event => {
    if (!(event.key === 'ContextMenu' || (event.shiftKey && event.key === 'F10'))) return;
    if (!event.target.dataset?.calDay) return;
    event.preventDefault();
    event.stopPropagation();
    const r = event.target.getBoundingClientRect();
    openCalDay(day, list, r.left + 16, r.bottom - 6, event.target);
  });
  calMakeDropTarget(el, day);
}

// Arrow keys move the selected day (the grid is one tab stop); Home and End go
// to the start and end of the week; Enter goes to the day panel's add field.
function calGridKey(event) {
  const target = event.target.closest?.('[data-cal-day]');
  if (!target || !activeCalendar || event.altKey || event.ctrlKey || event.metaKey) return;
  const day = Number(target.dataset.calDay);
  const month = activeCalendar.view === 'month';
  const steps = { ArrowLeft: -1, ArrowRight: 1, ArrowUp: month ? -7 : -1, ArrowDown: month ? 7 : 1 };
  let next = null;
  if (steps[event.key]) next = planAddDays(day, steps[event.key]);
  else if (event.key === 'Home') next = _tlStartOfWeek(day);
  else if (event.key === 'End') next = planAddDays(_tlStartOfWeek(day), 6);
  else if (event.key === 'Enter' && !event.shiftKey) {
    event.preventDefault();
    event.stopPropagation();
    if (day !== calSelectedDay()) calSelectDay(day);
    document.getElementById('cal-add-input')?.focus();
    return;
  }
  if (next == null) return;
  event.preventDefault();
  event.stopPropagation();
  calSelectDay(next, { focus: true });
}

function buildCalWeek(entries, selected, now, session = null, after = []) {
  const wrap = document.createElement('div');
  wrap.className = 'cld-card cld-week';
  const grid = document.createElement('div');
  grid.className = 'cld-wk';
  grid.setAttribute('role', 'group');
  grid.setAttribute('aria-label', calPeriodLabel());
  const byDay = calGroupByDay(entries);
  const todayStart = _tlStartOfDay(now);
  const start = calWeekStart();
  let day = start;
  for (let i = 0; i < 7; i++) {
    const date = new Date(day);
    const list = byDay.get(day) || [];
    const col = document.createElement('div');
    col.className = 'cld-wcol' + (day === selected ? ' is-sel' : '');
    const head = document.createElement('button');
    head.type = 'button';
    head.className = 'cld-wh';
    head.dataset.calDay = String(day);
    head.tabIndex = day === selected ? 0 : -1;
    head.setAttribute('aria-pressed', String(day === selected));
    head.setAttribute('aria-label', calendarDayAriaLabel(day, list.length));
    const dow = document.createElement('span');
    dow.className = 'cld-wh-dow';
    dow.textContent = date.toLocaleDateString(appLocale(), { weekday: 'short' });
    head.append(dow, calDayNumber(date, day === todayStart, session, now));
    col.appendChild(head);
    const body = document.createElement('div');
    body.className = 'cld-wbody';
    list.forEach(entry => body.appendChild(calChip(entry, now, 'cld-wchip')));
    col.appendChild(body);
    calBindDay(col, day, list);
    grid.appendChild(col);
    day = planAddDays(day, 1);
  }
  grid.appendChild(calSelectionBox('week', start, calDayIndex(start, selected, 7), session, after));
  grid.addEventListener('keydown', calGridKey);
  wrap.appendChild(grid);
  return wrap;
}

function _calAgendaDayLabel(dayStart, now = Date.now()) {
  const todayStart = _tlStartOfDay(now);
  const tmr = new Date(todayStart); tmr.setDate(tmr.getDate() + 1);
  if (dayStart === todayStart) return tr('cal.today');
  if (dayStart === _tlStartOfDay(tmr.getTime())) return tr('cal.tomorrow');
  return new Date(dayStart).toLocaleDateString(appLocale(), { weekday: 'long', month: 'short', day: 'numeric' });
}
function _calAgendaSection(day, list, selected, now) {
  const sec = document.createElement('section');
  sec.className = 'cld-ag-sec';
  const hd = document.createElement('h3');
  hd.className = 'cld-ag-hd' + (day === _tlStartOfDay(now) ? ' is-today' : '');
  hd.textContent = _calAgendaDayLabel(day, now);
  sec.appendChild(hd);
  list.forEach(entry => {
    const row = document.createElement('button');
    row.type = 'button';
    row.className = 'cld-arow';
    row.dataset.calKey = calEntryKey(entry);
    row.style.setProperty('--dot', reminderDotColor(entry.color));
    row.setAttribute('aria-pressed', String(day === selected));
    row.innerHTML = `<span class="cld-arow-t">${esc(planTimeLabel(entry.at))}</span><span class="cld-rdot" aria-hidden="true"></span><span class="cld-arow-n">${esc(entry.title)}</span><span class="cld-arow-s">${esc(calPlaceLabel(entry))}</span>`;
    row.onclick = () => {
      calSelectDay(day);
      document.querySelector(`.cld .cld-arow[data-cal-key="${CSS.escape(row.dataset.calKey)}"]`)?.focus({ preventScroll: true });
    };
    sec.appendChild(row);
  });
  return sec;
}
function buildCalAgenda(entries, selected, now) {
  const body = document.createElement('div');
  body.className = 'cld-card cld-agenda';
  // Past due sits in its own strip above every view.
  const upcoming = entries.filter(e => e.at >= now).sort((a, b) => a.at - b.at);
  if (!upcoming.length) {
    body.appendChild(_calEmptyNote(tr(entries.length ? 'cal.nothingUpcoming' : 'cal.noRemindersHere')));
    return body;
  }
  const byDay = calGroupByDay(upcoming);
  [...byDay.keys()].sort((a, b) => a - b).forEach(day => body.appendChild(_calAgendaSection(day, byDay.get(day), selected, now)));
  return body;
}

// Where a reminder lives: its Space, plus "Group" or "Space" for those.
function calPlaceLabel(entry) {
  const source = calendarSourceLabel(entry.source);
  return [entry.catName, source].filter(Boolean).join(' · ');
}

// The Past due strip: every overdue reminder (newest first), each with Move.
function buildCalPastDue(entries, now, entering = false) {
  const overdue = entries.filter(e => e.at < now).sort((a, b) => b.at - a.at);
  if (!overdue.length) return null;
  const strip = document.createElement('section');
  // The chips slide in when the view opens, not on every repaint.
  strip.className = 'cld-due' + (entering ? ' is-in' : '');
  strip.setAttribute('aria-labelledby', 'cld-due-hd');
  strip.innerHTML = `<h2 class="cld-due-hd" id="cld-due-hd">${planSvg(PLAN_ICONS.clock, 14, 1.7)}<span>${esc(tr('cal.pastDue'))}</span><span class="cld-due-n">${overdue.length}</span></h2>`;
  const list = document.createElement('div');
  list.className = 'cld-due-list';
  overdue.slice(0, 40).forEach(entry => {
    const chip = document.createElement('div');
    chip.className = 'cld-due-chip';
    chip.dataset.calKey = calEntryKey(entry);
    const when = document.createElement('span');
    when.className = 'cld-due-when';
    when.textContent = calWhenLabel(entry.at, now);
    chip.append(when, buildCalDot(entry, 'cld-due-title'), calMoveButton(entry, 'arrow'));
    list.appendChild(chip);
  });
  strip.appendChild(list);
  return strip;
}

function calMoveButton(entry, icon) {
  const b = document.createElement('button');
  b.type = 'button';
  b.className = 'cld-mv';
  b.setAttribute('aria-haspopup', 'menu');
  b.setAttribute('aria-expanded', 'false');
  b.setAttribute('aria-label', tr('plan.moveNamed', { name: entry.title || tr('plan.untitled') }));
  b.innerHTML = icon === 'arrow' ? calIcon('arrow', 15, 1.6) : calIcon('clock', 16, 1.6);
  b.onclick = event => {
    event.stopPropagation();
    showAnchoredContextMenu(b, calendarMoveMenuItems(entry, b), { ariaLabel: tr('plan.moveTo'), expandedOwner: b });
  };
  return b;
}

// Days offered by Move to: Today, Tomorrow, the day after (a weekday), This
// weekend and Next week, without the reminder's own day, at most four. Each
// keeps the reminder's time of day (see calMoveTime).
function calendarMoveOptions(entry, now = Date.now()) {
  const b = planBounds(now);
  const saturday = planAddDays(b.weekStart, 5);
  const from = planDayStart(entry.at);
  const candidates = [
    { key: 'today', day: b.today, label: tr('cal.today') },
    { key: 'tomorrow', day: b.tomorrow, label: tr('cal.tomorrow') },
    { key: 'day', day: b.afterTomorrow, label: new Date(b.afterTomorrow).toLocaleDateString(appLocale(), { weekday: 'long' }) },
    { key: 'weekend', day: saturday, label: tr('plan.move.weekend') },
    { key: 'nextWeek', day: b.nextWeek, label: tr('plan.move.nextWeek') },
  ];
  const seen = new Set();
  const options = [];
  candidates.forEach(option => {
    if (option.day < b.today || option.day === from || seen.has(option.day)) return;
    if (option.key === 'day' && option.day >= saturday) return;
    const at = calMoveTime(entry, option.day, now);
    if (at == null) return;
    seen.add(option.day);
    options.push({ ...option, at });
  });
  return options.slice(0, 4);
}

// Move to, then Edit reminder… and Clear / Remove (calendarDotMenuItems). A
// Group or Space reminder freezes its exact reminder now, as a drag does.
function calendarMoveMenuItems(entry, opener, { withOpen = false } = {}) {
  const base = calendarDotMenuItems(entry, opener);
  const rest = base.slice(1).filter(item => !item.sep).map(item => ({
    ...item,
    action: () => {
      calPrepareFocusAfter(opener);
      return item.action();
    },
  }));
  let moving = entry;
  if (entry.source !== 'item') {
    const mutationContext = createEntityReminderMutationContext(entry.source, entry.refId, entry.reminderId);
    moving = mutationContext ? { ...entry, mutationContext } : null;
  }
  const items = withOpen ? [base[0], { sep: true }] : [];
  const options = moving ? calendarMoveOptions(entry) : [];
  options.forEach(option => items.push({
    text: option.label,
    sub: planOptionHint(option),
    action: () => calMoveEntry(moving, option.day, opener),
  }));
  if (options.length) items.push({ sep: true });
  return items.concat(rest);
}

// After a reminder leaves the panel or the Past due strip, focus goes to the
// neighbour's Move button, else to the add field or the selected day.
function calPrepareFocusAfter(source) {
  const session = calendarPageSession;
  const item = source?.closest?.('[data-cal-key]');
  if (!session || !item?.parentElement) return;
  const siblings = [...item.parentElement.children].filter(el => el.dataset?.calKey);
  const index = siblings.indexOf(item);
  const mv = el => (el ? `.cld [data-cal-key="${CSS.escape(el.dataset.calKey)}"] .cld-mv` : null);
  session.afterMove = [
    mv(siblings[index + 1]),
    mv(siblings[index - 1]),
    item.closest('.cld-due') ? '.cld [data-cal-day][aria-pressed="true"]' : '#cal-add-input',
  ].filter(Boolean);
}
function calendarFocusAfterMove() {
  const session = calendarPageSession;
  const list = session?.afterMove;
  if (!list) return null;
  session.afterMove = null;
  for (const selector of list) {
    const target = document.querySelector(selector);
    if (target) return target;
  }
  return null;
}

function calMovedReceipt(entry, at) {
  const date = new Date(at).toLocaleDateString(appLocale(), { weekday: 'short', month: 'short', day: 'numeric' });
  return {
    message: tr('cal.movedTo', { date, time: planTimeLabel(at) }),
    options: { tone: 'warning', glyph: 'clock', sub: entry.title },
  };
}

// Move a reminder to a day through the normal reminder transaction (receipt
// with Undo), then fly its card from where it was to its new day.
async function calMoveEntry(entry, dayStart, source = null) {
  if (!entry || isReminderMutationPending()) return false;
  const at = calMoveTime(entry, dayStart);
  if (at == null) {
    toast(tr('reminder.futureTime'), { danger: true });
    return false;
  }
  if (at === entry.at) return true;
  const from = source?.isConnected
    ? (source.closest('[data-cal-key]') || source).getBoundingClientRect()
    : null;
  if (source) calPrepareFocusAfter(source);
  const ok = await calRescheduleTo(entry, dayStart, calMovedReceipt(entry, at));
  if (ok !== true) {
    if (calendarPageSession) calendarPageSession.afterMove = null;
    return false;
  }
  // Plan's "moved N times" mark counts Calendar moves too; Undo takes it back.
  if (entry.source === 'item' && typeof planBumpMoves === 'function') planBumpMoves(entry.refId, planLatestActionId());
  calLand(entry, at, from);
  return true;
}

// The moved card lands on its new day: a ghost travels from the old spot
// (with a small hop), then the card in the new day flashes. Without motion, or
// with no old spot (a drop), only the landing shows.
function calLand(entry, at, from) {
  const key = CSS.escape(calEntryKey(entry));
  const day = planDayStart(at);
  const target = document.querySelector(`.cld :is(.cld-chip, .cld-wchip, .cld-arow)[data-cal-key="${key}"]`)
    || document.querySelector(`.cld [data-cal-day="${day}"] .cld-more`)
    || document.querySelector(`.cld .cld-cell[data-cal-day="${day}"]`);
  if (!target || !target.getClientRects().length) return;
  if (!from || planReducedMotion()) {
    calReplay(target, 'is-landed');
    return;
  }
  const to = target.getBoundingClientRect();
  const ghost = document.createElement('div');
  ghost.className = 'cld-ghost';
  ghost.setAttribute('aria-hidden', 'true');
  ghost.style.setProperty('--dot', reminderDotColor(entry.color));
  ghost.style.left = `${Math.round(from.left)}px`;
  ghost.style.top = `${Math.round(from.top + Math.max(0, (from.height - to.height) / 2))}px`;
  ghost.style.width = `${Math.round(Math.max(to.width, 120))}px`;
  ghost.style.setProperty('--dx', `${Math.round(to.left - from.left)}px`);
  ghost.style.setProperty('--dy', `${Math.round(to.top - from.top - Math.max(0, (from.height - to.height) / 2))}px`);
  ghost.innerHTML = `<span class="cld-chip-t">${esc(planTimeLabel(at))}</span><span class="cld-chip-n">${esc(entry.title)}</span>`;
  target.classList.add('is-arriving');
  document.body.appendChild(ghost);
  let settled = false;
  const land = () => {
    if (settled) return;
    settled = true;
    ghost.remove();
    const live = document.querySelector(`.cld :is(.cld-chip, .cld-wchip, .cld-arow)[data-cal-key="${key}"]`) || target;
    live.classList.remove('is-arriving');
    calReplay(live, 'is-landed');
  };
  ghost.addEventListener('animationend', land, { once: true });
  // A hidden tab may never finish the animation; the card must not stay hidden.
  setTimeout(land, 900);
}

// A task added from the day panel drops into its list.
function calMarkDropped(itemId) {
  if (!itemId) return;
  const row = document.querySelector(`.cld .cld-row[data-cal-key^="item:${CSS.escape(String(itemId))}:"]`);
  if (row) calReplay(row, 'is-dropped');
}

// Add a task from the day panel: the same receipt-gated transaction as the Add
// task dialog (commitCalendarTaskMutation), reviewed when Enter is pressed.
async function calendarAddInline(dayStart, rawText) {
  const text = String(rawText || '').trim();
  if (!text || isCalendarTaskMutationPending()) return false;
  if (calendarTaskCtx && !calendarTaskCtx.inline) return false;
  const workspace = activeWs();
  if (!workspace || !Array.isArray(workspace.categories) || !workspace.categories.length) {
    toast(tr('cal.needSpace'), { danger: true });
    return false;
  }
  const context = createCalendarTaskMutationContext(dayStart);
  if (!context) {
    toast(tr('cal.addFailed'), { danger: true });
    return false;
  }
  calendarTaskCtx = { ...context, inline: true, errorKey: null, unavailable: false };
  calendarTaskBusy = false;
  return commitCalendarTaskMutation(calendarTaskCtx, text);
}

function paintCalendarAddInline() {
  const form = document.getElementById('cal-add-form');
  const input = document.getElementById('cal-add-input');
  const status = document.getElementById('cal-add-status');
  if (!form || !input || !status) return;
  const ctx = calendarTaskCtx?.inline ? calendarTaskCtx : null;
  const busy = !!ctx && calendarTaskBusy;
  const errorKey = ctx?.errorKey || null;
  const key = busy ? 'cal.adding'
    : errorKey === 'cal.saveFailed' ? errorKey
      : errorKey && errorKey !== 'cal.taskRequired' ? 'cal.addFailed' : '';
  input.disabled = busy;
  form.setAttribute('aria-busy', String(busy));
  status.textContent = key ? tr(key) : '';
  status.hidden = !key;
  if (busy) status.dataset.tone = 'pending';
  else if (key) status.dataset.tone = 'error';
  else delete status.dataset.tone;
}

function buildCalPanel(entries, selected, now, emptyText, session = null) {
  const list = (calGroupByDay(entries).get(selected) || []).slice();
  const todayStart = _tlStartOfDay(now);
  const date = new Date(selected);
  const aside = document.createElement('aside');
  aside.className = 'cld-panel';
  aside.setAttribute('aria-label', calendarDayAriaLabel(selected, list.length));
  const inner = document.createElement('div');
  inner.className = 'cld-pin';
  if (session && session.sel != null && session.sel !== selected) inner.classList.add(selected > session.sel ? 'is-next' : 'is-prev');

  const weekday = date.toLocaleDateString(appLocale(), { weekday: 'long' });
  const rel = selected === todayStart ? tr('cal.today') : selected === planAddDays(todayStart, 1) ? tr('cal.tomorrow') : '';
  const countKey = `d${selected}`;
  const roll = session ? spaceCountRoll(session, countKey, list.length) : { previous: null, delay: 0 };
  if (session) session.counts.set(countKey, list.length);
  const head = document.createElement('div');
  head.className = 'cld-ph';
  head.innerHTML = `<div class="cld-ph-text"><div class="cld-pwd${selected === todayStart ? ' is-today' : ''}">${rel ? `${esc(rel)} · ` : ''}${esc(weekday)}</div><div class="cld-pdate">${esc(date.toLocaleDateString(appLocale(), { month: 'long', day: 'numeric' }))}</div></div><span class="cld-pcount" aria-hidden="true">${spaceRollMarkup(list.length, roll.previous, roll.delay)}</span>`;
  inner.appendChild(head);

  // Add a task on this day (9:00, the active Space's Inbox).
  const review = createCalendarTaskMutationContext(selected);
  const form = document.createElement('form');
  form.className = 'cld-add';
  form.id = 'cal-add-form';
  form.setAttribute('aria-busy', 'false');
  const label = tr('cal.addOn', { date: date.toLocaleDateString(appLocale(), { weekday: 'long', month: 'long', day: 'numeric' }) });
  form.innerHTML = `<span class="cld-add-plus" aria-hidden="true">${calIcon('plus', 12, 2.2)}</span><label class="sr-only" for="cal-add-input">${esc(label)}</label><input id="cal-add-input" type="text" autocomplete="off" spellcheck="false" aria-describedby="cal-add-review cal-add-status"><span class="cld-add-time" aria-hidden="true"></span><kbd class="cld-kbd" aria-hidden="true">Enter</kbd><span class="sr-only" id="cal-add-review"></span>`;
  const input = form.querySelector('input');
  input.placeholder = tr('cal.addPlaceholder');
  if (review) {
    const reviewText = tr('cal.addDescription', { space: review.spaceName, group: review.inboxName, date: review.dateLabel, time: review.timeLabel });
    form.querySelector('#cal-add-review').textContent = reviewText;
    form.querySelector('.cld-add-time').textContent = planTimeLabel(review.at);
    form.title = reviewText;
  }
  input.addEventListener('input', () => form.classList.toggle('has-text', !!input.value.trim()));
  input.addEventListener('keydown', event => {
    if (event.key !== 'Escape') return;
    event.stopPropagation();
    if (input.value) {
      input.value = '';
      form.classList.remove('has-text');
    } else calFocusDay(selected);
  });
  form.addEventListener('submit', event => {
    event.preventDefault();
    void calendarAddInline(selected, input.value);
  });
  inner.appendChild(form);
  const status = document.createElement('p');
  status.className = 'cld-add-status';
  status.id = 'cal-add-status';
  status.setAttribute('role', 'status');
  status.setAttribute('aria-live', 'polite');
  status.hidden = true;
  inner.appendChild(status);

  const rows = document.createElement('div');
  rows.className = 'cld-rows';
  let nowShown = selected !== todayStart;
  list.forEach(entry => {
    if (!nowShown && entry.at >= now) {
      nowShown = true;
      const line = document.createElement('div');
      line.className = 'cld-now';
      line.innerHTML = `<span>${esc(tr('cal.now', { time: planTimeLabel(now) }))}</span><i aria-hidden="true"></i>`;
      rows.appendChild(line);
    }
    rows.appendChild(buildCalRow(entry, now));
  });
  if (!list.length && emptyText) rows.appendChild(_calEmptyNote(emptyText));
  inner.appendChild(rows);
  aside.appendChild(inner);
  return aside;
}

function buildCalRow(entry, now) {
  const row = document.createElement('div');
  row.className = 'cld-row' + (entry.at < now ? ' is-past' : '');
  row.dataset.calKey = calEntryKey(entry);
  row.style.setProperty('--dot', reminderDotColor(entry.color));
  const time = document.createElement('span');
  time.className = 'cld-rtime';
  time.textContent = planTimeLabel(entry.at);
  const main = document.createElement('div');
  main.className = 'cld-rmain';
  main.appendChild(buildCalDot(entry, 'cld-rtitle'));
  const meta = document.createElement('div');
  meta.className = 'cld-rmeta';
  meta.innerHTML = `<span class="cld-rdot" aria-hidden="true"></span><span>${esc(calPlaceLabel(entry))}</span>`
    + (entry.recur?.every ? `<span class="cld-rrep">${planSvg(PLAN_ICONS.rolled, 11, 2)}<span>${esc(recurLabel(entry.recur))}</span></span>` : '');
  main.appendChild(meta);
  row.append(time, main, calMoveButton(entry, 'clock'));
  return row;
}

// Render the calendar surface into #board. Returns false (letting the board
// render) if there's no active workspace, mirroring renderGroupPage's contract.
function renderCalendar() {
  const ws = activeWs();
  if (!ws || !activeCalendar) { activeCalendar = null; return false; }
  if (PLAN_VIEWS.includes(activeCalendar.view)) {
    if (typeof renderPlanSurface === 'function') return renderPlanSurface(ws);
    activeCalendar.view = 'month';
  }
  // A Plan view: no breadcrumb bar, as on Upcoming and Sort inbox.
  hideBreadcrumb();

  const $b = document.getElementById('board');
  const scrollTop = $b.classList.contains('calendar-mode') ? $b.scrollTop : 0;
  $b.classList.remove('list-mode', 'canvas-mode', 'explorer-mode', 'timeline-mode', 'group-page-mode');
  $b.classList.add('calendar-mode');
  $b.innerHTML = '';

  const session = calendarSession();
  const now = Date.now();
  const all = buildCalendarEntries();
  const pred = parseCalendarFilter(calendarFilter);
  const shown = pred ? all.filter(pred) : all;
  const view = activeCalendar.view;
  const selected = calSelectedDay();
  // Month opens on the selected day's month.
  if (view === 'month' && session.view !== 'month' && !calInMonthGrid(selected)) calSetAnchor(selected);
  const emptyKey = calEmptyKey(all.length, shown.length);
  const after = [];

  const wrap = document.createElement('div');
  wrap.className = 'cal-wrap cld';
  // The Calendar is a view inside Plan, so it carries Plan's header.
  if (typeof buildPlanHeader === 'function') wrap.appendChild(buildPlanHeader(ws, 'calendar'));
  wrap.appendChild(buildCalToolbar(shown.length, all.length, session, after));
  const due = buildCalPastDue(shown, now, !session.view);
  if (due) wrap.appendChild(due);
  const main = document.createElement('div');
  main.className = 'cld-main';
  main.setAttribute('role', 'region');
  main.setAttribute('aria-label', tr('cal.title'));
  const host = document.createElement('div');
  host.className = 'cld-view' + (session.view && session.view !== view ? ' is-in' : '');
  if (view === 'agenda') host.appendChild(emptyKey ? _calEmptyNote(tr(emptyKey)) : buildCalAgenda(shown, selected, now));
  else host.appendChild(view === 'week' ? buildCalWeek(shown, selected, now, session, after) : buildCalMonth(shown, selected, now, session, after));
  main.appendChild(host);
  main.appendChild(buildCalPanel(shown, selected, now, view === 'agenda' && emptyKey ? '' : tr(emptyKey || 'cal.noRemindersHere'), session));
  wrap.appendChild(main);
  $b.appendChild(wrap);
  after.forEach(step => step());
  if (scrollTop) $b.scrollTo({ top: scrollTop, behavior: 'instant' });
  session.view = view;
  session.sel = selected;
  paintCalendarAddInline();

  // Restore the filter input's focus/caret across the keystroke-triggered render.
  if (_calFilterRestore) {
    const fi = document.getElementById('cal-filter-input');
    if (fi) { fi.focus(); const p = _calFilterRestore.caret; if (p != null) { try { fi.setSelectionRange(p, p); } catch {} } }
    _calFilterRestore = null;
  }
  return true;
}

// ════════════════════════════════════════════════════════════════
// VIEW MODES (board / list) + selection / reorder mode toggles
// ════════════════════════════════════════════════════════════════
// The active layout is stored per category (`category.layout`, §7) so each space
// can default to the mode it's meant to be used in; it falls back to the legacy
// global `settings.viewMode` for categories that have never picked one (which
// keeps existing single-view users on their chosen mode with no migration).
function getViewMode() {
  const cat = activeCat();
  const m = (cat && cat.layout) || State.get().settings.viewMode;
  return LAYOUTS[m] ? m : 'board';
}
function setViewMode(mode) {
  if (!LAYOUTS[mode]) mode = 'board';
  const cat = activeCat();
  const settings = State.get().settings;
  // Boot re-applies the saved layout on every open. Persist only a real change
  // so opening a new tab never manufactures a revision.
  const changed = (cat && cat.layout !== mode) || settings.viewMode !== mode;
  if (cat) cat.layout = mode;
  // Keep the legacy global as the "last used" default for categories that
  // haven't picked a layout yet.
  settings.viewMode = mode;
  document.body.dataset.viewMode = mode;
  if (changed) State.persist();
  renderBoard();
  Router.sync();
}

// ── Command palette (§7) ──────────────────────────────────────────
// A Cmd/Ctrl-K surface that unifies navigation and quick actions: jump to a
// workspace / category / group, switch layout, open the calendar, save tabs,
// change theme, or drop into board search. It filters its list the same
// subsequence way search matches, is fully keyboard-driven (↑/↓/Enter/Esc), and
// reuses the app's overlay scrim, panel tokens and motion so it reads native
// across the 13 themes. Board text-search still opens directly on `/`.
let _palState = null;

// Open the dedicated local search route, optionally pre-filled from the palette.
function openSearchBar(prefill) {
  openSearchSurface(prefill == null ? '' : prefill);
}

// Open the Settings page from anywhere (mirrors the settings button handler).
// Optional `tab` activates a specific section; legacy drawer names
// ('behavior', 'archive') are mapped inside setSettingsSection so old
// deep-links keep working.
function openSettingsDrawer(tab, opener = null) {
  const d = document.getElementById('settings-drawer');
  if (!d) return;
  focusDialogOpener(opener);
  rememberOpener(d, opener);
  d.classList.remove('hidden');
  setSettingsSection(tab || document.querySelector('#drawer-tabs .dt.active')?.dataset.tab || 'general');
  try { renderAppearanceSettings(); } catch {}
  try { renderCaptureSettings(); } catch {}
  setTimeout(() => {
    const active = d.querySelector('#drawer-tabs .dt.active');
    if (active) active.focus();
    else focusFirstIn(d);
  }, 50);
}

