  sidebar: _palSvg('<rect x="2.5" y="3" width="15" height="14" rx="2" stroke="currentColor" stroke-width="1.5"/><path d="M7.5 3v14M4.5 6h.01M4.5 9h.01" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/>'),
